INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('talim_mutaallim', 'تَعْلِيمُ المُتَعَلِّمِ طَرِيقَ التَّعَلُّمِ', 'الإِمَامُ بُرْهَانُ الإِسْلَامِ الزَّرْنُوجِيُّ الحَنَفِيُّ (ت: 593ھ)', 'kharji_kitab', 'adab', 'آدابِ علم، مطالعہ و طریقہ تحصیل', 'کتبِ مطالعہ و تربیت (جملہ طلبۂ علومِ اسلامیہ)', NULL, NULL, 'from-amber-800 via-amber-900 to-stone-900', NULL, 'طلبہ کے لیے دنیا کی سب سے مؤثر اور رہنما خارجی کتاب۔ اس میں تحصیلِ علم کا طریقہ، اخلاصِ نیت، اساتذہ و کتب کا ادب، حفظ کے طریقے اور وقت کی حفاظت کے سنہری اصول قلمبند ہیں۔', 6, 6);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talim_ch1_fasl_ilm', 'talim_mutaallim', 0, 'فَصْلٌ فِي مَاهِيَّةِ العِلْمِ وَالفِقْهِ وَفَضْلِهِ', 'فصل اول: علم اور فقہ کی حقیقت، فضیلت اور فرضیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talim_seg_1_1', 'talim_ch1_fasl_ilm', 'talim_mutaallim', 0, 'قَالَ رَسُولُ اللَّهِ ﷺ: «طَلَبُ العِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ وَمُسْلِمَةٍ». اعْلَمْ بِأَنَّهُ لَا يُفْتَرَضُ عَلَى كُلِّ مُسْلِمٍ طَلَبُ كُلِّ عِلْمٍ، بَلْ يُفْتَرَضُ عَلَيْهِ طَلَبُ عِلْمِ الحَالِ، كَمَا قِيلَ: أَفْضَلُ العِلْمِ عِلْمُ الحَالِ، وَأَفْضَلُ العَمَلِ حِفْظُ الحَالِ. وَيُفْتَرَضُ عَلَى المُسْلِمِ طَلَبُ مَا يَقَعُ لَهُ فِي حَالِهِ فِي أَيِّ حَالٍ كَانَ، فَإِنَّهُ لَا بُدَّ لَهُ مِنَ الصَّلَاةِ فَيُفْتَرَضُ عَلَيْهِ عِلْمُ مَا يَقَعُ لَهُ فِي صَلَاتِهِ بِقَدْرِ مَا يُؤَدِّي بِهِ وَاجِبَ الصَّلَاةِ.', 'رسول اللہ ﷺ نے ارشاد فرمایا: ''علم حاصل کرنا ہر مسلمان مرد اور عورت پر فرض ہے۔'' جان لو کہ ہر مسلمان پر ہر علم کا سیکھنا فرضِ عین نہیں ہے، بلکہ اس پر ''علمِ حال'' (یعنی اپنی موجودہ حالت اور ضرورت کا علم) حاصل کرنا فرض ہے۔ جیسا کہ کہا گیا ہے: بہترین علم ''علمِ حال'' ہے اور بہترین عمل ''حال کی حفاظت'' ہے۔ اور مسلمان پر اس بات کا علم حاصل کرنا فرض ہے جو اس کی حالت میں پیش آتا ہے خواہ وہ کسی بھی حال میں ہو؛ پس چونکہ اس کے لیے نماز پڑھنا ضروری ہے، لہٰذا اس پر نماز کے ان تمام احکام کا جاننا فرض ہے جن سے نماز کا واجب ادا ہو سکے۔', 'امام زرنوجی رحمہ اللہ نے اس شاہکار کتاب کا آغاز طالب علم کے بنیادی ہدف اور فرضیتِ علم کی درست تفہیم سے کیا ہے۔', '[{"word":"طَلَبُ","role":"مبتدا مرفوع","sign":"ضمہ لفظاً","detail":"مضاف ہے العلم کی طرف، مرفوع بالابتداء"},{"word":"فَرِيضَةٌ","role":"خبر المبتدأ","sign":"ضمہ لفظاً","detail":"اسم مفرد مؤنث، تم به معنی الكلام"}]', '["الحديث رواه ابن ماجه وغيره من حديث أنس بن مالك رضي الله عنه."]', '{"en":"The Messenger of Allah ﷺ said: ''Seeking knowledge is an obligation upon every Muslim.'' Know that it is not obligatory upon every Muslim to seek all types of knowledge, but rather to seek ''the knowledge of one''s current state'' (''Ilm al-Hal).","ar":"بيان فرضية علم الحال على كل مكلف، وهو ما يحتاجه المسلم في عباداته ومعاملاته اليومية كالصلاة والصوم والبيوع."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talim_ch2_fasl_niyyah', 'talim_mutaallim', 1, 'فَصْلٌ فِي النِّيَّةِ فِي حَالِ التَّعَلُّمِ', 'فصل دوم: طلبِ علم میں نیت کا اخلاص اور رضائے الٰہی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talim_seg_2_1', 'talim_ch2_fasl_niyyah', 'talim_mutaallim', 0, 'ثُمَّ لَا بُدَّ لَهُ مِنَ النِّيَّةِ فِي زَمَانِ تَعَلُّمِ العِلْمِ، إِذِ النِّيَّةُ هِيَ الأَصْلُ فِي جَمِيعِ الأَحْوَالِ، لِقَوْلِهِ ﷺ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ». فَيَنْبَغِي أَنْ يَنْوِيَ المُتَعَلِّمُ بِطَلَبِ العِلْمِ: رِضَاءَ اللَّهِ تَعَالَى، وَالدَّارَ الآخِرَةَ، وَإِزَالَةَ الجَهْلِ عَنْ نَفْسِهِ وَعَنْ سَائِرِ الجُهَّالِ، وَإِحْيَاءَ الدِّينِ، وَإِبْقَاءَ الإِسْلَامِ، فَإِنَّ بَقَاءَ الإِسْلَامِ بِالعِلْمِ، وَلَا يَصِحُّ الزُّهْدُ وَالتَّقْوَى مَعَ الجَهْلِ.', 'پھر طالب علم کے لیے زمانۂ تحصیلِ علم میں نیت کا درست ہونا اشد ضروری ہے، کیونکہ تمام احوال میں نیت ہی اصل اور بنیاد ہے، جیسا کہ رسول اللہ ﷺ نے فرمایا: ''اعمال کا دارومدار نیتوں پر ہے۔'' پس طالب علم کو طلبِ علم سے یہ نیت کرنی چاہیے: اللہ تعالیٰ کی رضا، آخرت کا گھر، اپنے اور دوسرے تمام نادانوں سے جہالت کو دور کرنا، دین کو زندہ رکھنا، اور اسلام کو باقی رکھنا؛ کیونکہ اسلام کی بقا علم ہی سے وابستہ ہے، اور جہالت کے ساتھ زہد اور تقویٰ درست نہیں ہو سکتے۔', 'طالب علم کو کبھی دنیاوی شہرت، مناصب یا امراء سے دولت کمانے کی نیت نہیں کرنی چاہیے؛ کیونکہ علمِ دین کا سودا دنیا کے فانی سکوں سے کرنا بدترین خسارہ ہے۔', '[{"word":"إِزَالَةَ","role":"معطوف على رضاء","sign":"فتحة لفظاً","detail":"معطوف منصوب وعلامة نصبه الفتحة"}]', '["تعليم المتعلم، فصل في النية."]', '{"en":"Furthermore, it is necessary for the student to have proper intention while seeking knowledge, for intention is the foundation of all states... The student should intend the pleasure of Allah, the Hereafter, and removing ignorance from himself and others.","ar":"تأكيد إخلاص النية لله تعالى عند طلب العلم والحذر من طلب الدنيا والرياء."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talim_ch3_ikhtiyar', 'talim_mutaallim', 2, 'فَصْلٌ فِي اخْتِيَارِ العِلْمِ وَالأُسْتَاذِ وَالشَّرِيكِ وَالثَّبَاتِ', 'فصل سوم: علم، استاد اور ساتھی کا انتخاب اور استقامت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talim_seg_3_1', 'talim_ch3_ikhtiyar', 'talim_mutaallim', 0, 'يَنْبَغِي لِطَالِبِ العِلْمِ أَنْ يَخْتَارَ مِنْ كُلِّ عِلْمٍ أَحْسَنَهُ، وَمَا يَحْتَاجُ إِلَيْهِ فِي أَمْرِ دِينِهِ فِي الحَالِ، ثُمَّ مَا يَحْتَاجُ إِلَيْهِ فِي المَآلِ. وَيُقَدِّمَ عِلْمَ التَّوْحِيدِ وَالمَعْرِفَةِ، وَيَعْرِفَ اللَّهَ تَعَالَى بِالدَّلِيلِ. وَأَمَّا اخْتِيَارُ الأُسْتَاذِ: فَيَنْبَغِي أَنْ يَخْتَارَ الأَعْلَمَ، وَالأَوْرَعَ، وَالأَسَنَّ، كَمَا اخْتَارَ أَبُو حَنِيفَةَ رَحِمَهُ اللَّهُ حَمَّادَ بْنَ أَبِي سُلَيْمَانَ بَعْدَ التَّأَمُّلِ وَالتَّفَكُّرِ، فَقَالَ: وَجَدْتُهُ شَيْخاً وَقُوراً حَلِيماً صَبُوراً.', 'طالب علم کے لیے ضروری ہے کہ وہ ہر علم میں سے سب سے بہتر اور نفع بخش علم کا انتخاب کرے، اور پہلے وہ علم حاصل کرے جس کی اسے فی الحال اپنے دین کے معاملے میں ضرورت ہے، پھر اس کی طرف جائے جس کی آئندہ ضرورت ہوگی۔ اور سب سے پہلے علمِ توحید و معرفت کو مقدم رکھے تاکہ اللہ کو دلیل کے ساتھ پہچانے۔ اور استاد کے انتخاب میں چاہیے کہ سب سے زیادہ علم والے، سب سے زیادہ پرہیزگار (باورع) اور عمر میں بڑے شیخ کا انتخاب کرے، جیسا کہ امام اعظم ابو حنیفہ رحمہ اللہ نے خوب غور و فکر کے بعد حضرت حماد بن ابی سلیمان کا انتخاب کیا اور فرمایا: ''میں نے انہیں ایک باوقار، بردبار اور نہایت صابر استاد پایا''۔', 'استاد کے انتخاب میں تین شرائط بیان فرمائیں: ۱۔ اعلم (سب سے زیادہ راسخ فی العلم ہو)، ۲۔ اورع (سب سے زیادہ متقی ہو)، ۳۔ اسن (تجربہ کار اور پختہ عمر ہو)۔', '[{"word":"الأَعْلَمَ","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"اسم تفضيل منصوب مفعول به ليختار"}]', '["تعليم المتعلم، فصل في اختيار الأستاذ."]', '{"en":"The student should select the best knowledge, prioritizing what is immediately necessary for his religious duties... As for choosing a teacher, he should select the most knowledgeable, the most pious, and the most seasoned in age.","ar":"معايير اختيار المعلم والشيخ القدوة في السمت والورع والرسوخ العلمي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talim_ch4_tazim', 'talim_mutaallim', 3, 'فَصْلٌ فِي تَعْظِيمِ العِلْمِ وَأَهْلِهِ وَتَوْقِيرِ الأُسْتَاذِ', 'فصل چہارم: علم، اہلِ علم، اساتذہ اور کتابوں کی تعظیم و آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talim_seg_4_1', 'talim_ch4_tazim', 'talim_mutaallim', 0, 'اعْلَمْ أَنَّ طَالِبَ العِلْمِ لَا يَنَالُ العِلْمَ وَلَا يَنْتَفِعُ بِهِ إِلَّا بِتَعْظِيمِ العِلْمِ وَأَهْلِهِ، وَتَعْظِيمِ الأُسْتَاذِ وَتَوْقِيرِهِ. قِيلَ: مَا وَصَلَ مَنْ وَصَلَ إِلَّا بِالحُرْمَةِ، وَمَا سَقَطَ مَنْ سَقَطَ إِلَّا بِتَرْكِ الحُرْمَةِ وَالتَّعْظِيمِ. وَمِنْ تَوْقِيرِ الأُسْتَاذِ: أَنْ لَا يَمْشِيَ أَمَامَهُ، وَلَا يَجْلِسَ مَكَانَهُ، وَلَا يَبْتَدِئَ بِالكَلَامِ عِنْدَهُ إِلَّا بِإِذْنِهِ، وَلَا يُكْثِرَ الكَلَامَ عِنْدَهُ، وَلَا يَسْأَلَ شَيْئاً عِنْدَ مَلَالَتِهِ.', 'جان لو کہ طالب علم علم حاصل نہیں کر سکتا اور نہ اس سے نفع اٹھا سکتا ہے جب تک کہ وہ علم اور اہلِ علم کی دل سے تعظیم نہ کرے، اور اپنے استاد کی بے پناہ عزت و احترام نہ کرے۔ اکابرین نے فرمایا ہے: ''جس کو جو کمال بھی ملا وہ ادب اور احترام کی برکت سے ملا، اور جو محروم اور ناکام ہوا وہ ادب اور تعظیم کو چھوڑنے ہی کی وجہ سے ہوا۔'' اور استاد کے ادب میں سے یہ ہے: کہ طالب علم استاد کے آگے آگے نہ چلے، ان کی جگہ پر نہ بیٹھے، ان کی اجازت کے بغیر گفتگو شروع نہ کرے، ان کی مجلس میں فضول کلام نہ کرے، اور استاد کی تھکن کے وقت سوالات کی بوچھاڑ نہ کرے۔', 'باادب با نصیب، بے ادب بے نصیب! علم صرف کتاب پڑھنے سے نہیں آتا بلکہ استاد کے دل کی دعاؤں اور تعظیم سے قلب میں منتقل ہوتا ہے۔', '[{"word":"بِالحُرْمَةِ","role":"جار ومجرور","sign":"كسرة لفظاً","detail":"شبه جملة متعلق بفعل وصل"}]', '["تعليم المتعلم، فصل في تعظيم العلم وأهله."]', '{"en":"Know that a student does not attain knowledge nor benefit from it except through venerating knowledge and its people, and honoring the teacher... It was said: ''Whoever succeeded only succeeded through respect, and whoever failed only failed through abandoning respect.''","ar":"الأدب مع الشيخ والكتب أساس الفتح والبركة في العلم والتحصيل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talim_ch5_jidd', 'talim_mutaallim', 4, 'فَصْلٌ فِي الجِدِّ وَالمُوَاظَبَةِ وَالهِمَّةِ العَالِيَةِ', 'فصل پنجم: محنت، مداومت اور بلند ہمتی کے اصول');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talim_seg_5_1', 'talim_ch5_jidd', 'talim_mutaallim', 0, 'ثُمَّ لَا بُدَّ مِنَ الجِدِّ وَالمُوَاظَبَةِ وَالمُلَازَمَةِ لِطَالِبِ العِلْمِ، وَإِلَيْهِ الإِشَارَةُ فِي القُرْآنِ: ﴿يَا يَحْيَى خُذِ الكِتَابَ بِقُوَّةٍ﴾، وَقِيلَ: بِقَدْرِ مَا تَتَعَنَّى تَنَالُ مَا تَتَمَنَّى. وَأَنْشَدُوا شِعْراً:
بِقَدْرِ الكَدِّ تُكْتَسَبُ المَعَالِي ... وَمَنْ طَلَبَ العُلَا سَهِرَ اللَّيَالِي
تَرُومُ العِزَّ ثُمَّ تَنَامُ لَيْلاً ... يَغُوصُ البَحْرَ مَنْ طَلَبَ اللَّآلِي
فَمَنْ رَامَ العُلَى مِنْ غَيْرِ كَدٍّ ... أَضَاعَ العُمْرَ فِي طَلَبِ المُحَالِ', 'پھر طالب علم کے لیے محنت، باقاعدگی اور سبق کی مداومت ناگزیر ہے، اور اسی کی طرف قرآن مجید میں اشارہ ہے: ''اے یحییٰ! کتاب کو مضبوطی سے تھام لو!'' اور کہا گیا ہے: ''جتنی مشقت اٹھاؤ گے اتنی ہی اپنی تمنا اور مراد کو پاؤ گے''۔ اور شعراء نے کیا خوب فرمایا ہے:
''محنت ہی کے بقدر بلند مرتبے حاصل ہوتے ہیں، اور جس نے بلندی کی طلب کی وہ راتوں کو جاگا؛
تو عزت و شرف چاہتا ہے اور پھر رات بھر سوتا ہے؟ موتیوں کی تلاش والا ہی سمندر کی گہرائیوں میں غوطہ لگاتا ہے؛
پس جو شخص بغیر محنت کے بلندی حاصل کرنا چاہتا ہے، وہ ناممکن کی طلب میں اپنی قیمتی عمر ضائع کرتا ہے!''', 'سستی، تاخیر (تسویف) اور زیادہ سونا طالب علم کے راستے کے سب سے بڑے رہزن ہیں۔ راتوں کو جاگ کر مطالعہ کرنا اور تکرار کرنا ہی رسوخ فی العلم پیدا کرتا ہے۔', '[{"word":"المَعَالِي","role":"نائب فاعل مرفوع","sign":"ضمة مقدرة","detail":"لفعل تكتسب المبني للمجهول"}]', '["تعليم المتعلم، فصل في الجد والمواظبة."]', '{"en":"Then, diligence, perseverance, and dedication are indispensable for the seeker of knowledge... To the extent of toil are noble heights attained, and whoever seeks greatness spends the nights awake.","ar":"علو الهمة والسهر في تحصيل العلم والبعد عن الكسل والتسويف."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talim_ch6_hifdh', 'talim_mutaallim', 5, 'فَصْلٌ فِيمَا يُورِثُ الحِفْظَ وَمَا يُورِثُ النِّسْيَانَ', 'فصل ششم: قوتِ حافظہ کے اسباب اور نسیان (بھولنے) کی وجوہات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talim_seg_6_1', 'talim_ch6_hifdh', 'talim_mutaallim', 0, 'وَأَقْوَى أَسْبَابِ الحِفْظِ: الجِدُّ، وَالمُوَاظَبَةُ، وَتَقْلِيلُ الغِذَاءِ، وَصَلَاةُ اللَّيْلِ، وَقِرَاءَةُ القُرْآنِ نَظَراً. قِيلَ: لَيْسَ شَيْءٌ أَزْيَدَ لِلْحِفْظِ مِنْ قِرَاءَةِ القُرْآنِ نَظَراً. وَمِمَّا يُورِثُ الحِفْظَ: اسْتِعْمَالُ السِّوَاكِ، وَشُرْبُ العَسَلِ، وَأَكْلُ اللُّبَانِ مَعَ السُّكَّرِ، وَأَكْلُ إِحْدَى وَعِشْرِينَ زَبِيبَةً حَمْرَاءَ كُلَّ يَوْمٍ عَلَى الرِّيقِ. وَأَمَّا مَا يُورِثُ النِّسْيَانَ: فَالمَعَاصِي، وَكَثْرَةُ الذُّنُوبِ، وَالهُمُومُ وَالأَحْزَانُ فِي أُمُورِ الدُّنْيَا، وَكَثْرَةُ الشُّغْلِ وَالعَلَائِقِ، كَمَا قَالَ الشَّافِعِيُّ:
شَكَوْتُ إِلَى وَكِيعٍ سُوءَ حِفْظِي ... فَأَرْشَدَنِي إِلَى تَرْكِ المَعَاصِي
وَأَخْبَرَنِي بِأَنَّ العِلْمَ نُورٌ ... وَنُورُ اللَّهِ لَا يُهْدَى لِعَاصِي', 'اور حافظہ مضبوط کرنے کے سب سے قوی اسباب یہ ہیں: محنت، باقاعدگی، کم کھانا، تہجد کی نماز، اور قرآنِ مجید کو دیکھ کر تلاوت کرنا۔ کہا گیا ہے کہ دیکھ کر تلاوتِ قرآن سے بڑھ کر کوئی چیز حافظہ قوی کرنے والی نہیں۔ اور حافظہ بڑھانے والی چیزوں میں مسواک کرنا، شہد پینا، کندر کھانا، اور نہار منہ اکیس سرخ منقے کھانا شامل ہیں۔ اور جو چیزیں نسیان اور بھولنے کا سبب بنتی ہیں وہ یہ ہیں: گناہ کرنا، کثرتِ معاصی، دنیاوی پریشانیوں اور غموں میں الجھنا، اور بلا ضرورت تعلقات و مصروفیات کو بڑھانا؛ جیسا کہ امام شافعی نے فرمایا:
''میں نے اپنے استاد وکیع سے اپنے حافظے کی کمزوری کی شکایت کی، تو انہوں نے مجھے گناہوں کو چھوڑنے کی رہنمائی فرمائی؛
اور مجھے بتایا کہ بے شک علم اللہ کا نور ہے، اور اللہ کا نور کسی گناہ گار کو عطا نہیں کیا جاتا!''', 'علم اور گناہ کبھی ایک دل میں جمع نہیں ہو سکتے۔ گناہ حافظے کی تختی پر سیاہی پھیر دیتے ہیں جبکہ تقویٰ اور طہارت حافظے کو آئینے کی طرح چمکا دیتی ہے۔', '[{"word":"نُورٌ","role":"خبر أنّ مرفوع","sign":"ضمة لفظاً","detail":"اسمها العلم وخبرها نور"}]', '["تعليم المتعلم، فصل فيما يورث الحفظ."]', '{"en":"The strongest causes of memory retention are diligence, moderation in food, night prayers, and reciting Quran from the Mushaf... As for what causes forgetfulness, it is sins and excessive worldly entanglements, as Imam Al-Shafi''i said: ''I complained to Waki'' about my weak memory, so he advised me to abandon sins...''","ar":"الأسباب الروحية والعملية لتقوية الحفظ وخطورة المعاصي في طمس نور العلم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('riyad_salihin', 'رِيَاضُ الصَّالِحِينَ مِنْ كَلَامِ سَيِّدِ المُرْسَلِينَ', 'الإِمَامُ الحَافِظُ أَبُو زَكَرِيَّا يَحْيَى بْنُ شَرَفٍ النَّوَوِيُّ (ت: 676ھ)', 'kharji_kitab', 'hadith', 'احادیثِ اخلاق، معاشرت و تزکیۂ نفس', 'کتبِ مطالعہ و حفظ (عمومی نصاب و مطالعہ)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'امتِ مسلمہ کی مقبول ترین کتابِ حدیث و اخلاق۔ امام نووی رحمہ اللہ نے طالب علم کے شب و روز، اخلاق، معاملات اور باطنی تطہیر کے لیے قرآن و صحیح احادیث کا لاجواب گلدستہ سجایا ہے۔', 25, 50);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch1_ikhlas', 'riyad_salihin', 0, 'بَابُ الإِخْلَاصِ وَإِحْضَارِ النِّيَّةِ فِي جَمِيعِ الأَعْمَالِ', 'باب 1: تمام اعمال و اقوال میں اخلاص اور نیت کا استحضار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_1_1', 'riyad_ch1_ikhlas', 'riyad_salihin', 0, 'عَنْ أَمِيرِ المُؤْمِنِينَ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ».', 'امیر المؤمنین حضرت عمر بن الخطاب رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے ہوئے سنا: ''تمام اعمال کا دارومدار نیتوں پر ہے، اور ہر انسان کے لیے وہی ہے جس کی اس نے نیت کی۔ پس جس کی ہجرت اللہ اور اس کے رسول کی رضا کے لیے ہو، اس کی ہجرت اللہ اور اس کے رسول کے لیے ہی قبول ہوگی؛ اور جس کی ہجرت دنیا حاصل کرنے کے لیے یا کسی عورت سے نکاح کرنے کے لیے ہو، تو اس کی ہجرت اسی کے لیے شمار ہوگی جس کے لیے اس نے ہجرت کی۔''', 'نیت کی طہارت اور اخلاصِ قلب ہر دینی عمل کی روح ہے۔ امام شافعی اور امام احمد بن حنبل فرماتے ہیں کہ یہ حدیثِ پاک ایک تہائی دین پر محیط ہے، کیونکہ انسان کے اعمال کا تعلق دل، زبان اور اعضاء سے ہے اور دل کا عمل نیت ہے۔', '[{"word":"إِنَّمَا","role":"أداة حصر","sign":"مبنی","detail":"مركبة من إن المكفوفة وما الكافة"},{"word":"الأَعْمَالُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالابتداء وعلامة رفعه الضمة"},{"word":"بِالنِّيَّاتِ","role":"جار ومجرور","sign":"كسرة لفظاً","detail":"شبه جملة متعلق بمحذوف خبر المبتدأ"}]', '["متفق عليه: أخرجه البخاري (1)، ومسلم (1907)."]', '{"en":"Narrated ''Umar bin Al-Khattab: I heard Allah''s Messenger ﷺ saying: ''Actions are judged by intentions, and every person will get what they intended. So whoever emigrated for Allah and His Messenger, his emigration is for Allah and His Messenger...''","ar":"هذا الحديث قاعدة كبرى من قواعد الإسلام، وافتتح به الإمام البخاري صحيحه والإمام النووي رياض الصالحين تذكيراً بالإخلاص."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_1_2', 'riyad_ch1_ikhlas', 'riyad_salihin', 1, 'وَعَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى أَجْسَادِكُمْ، وَلَا إِلَى صُوَرِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''بے شک اللہ تعالیٰ تمہارے جسموں اور تمہاری ظاہری صورتوں کو نہیں دیکھتا، بلکہ وہ تمہارے دلوں (کے اخلاص) اور تمہارے اعمال کو دیکھتا ہے۔''', 'اللہ تعالیٰ کے ہاں انسانی صورت، حسب و نسب یا دنیاوی ٹھاٹھ باٹھ کی کوئی حیثیت نہیں؛ اصل کسوٹی دل کا تقویٰ اور عمل کا اخلاص ہے۔', '[{"word":"إِنَّ","role":"حرف توكيد ونصب","sign":"مبنی علی الفتح","detail":"تنصب الاسم وترفع الخبر"},{"word":"قُلُوبِكُمْ","role":"اسم مجرور بإلى","sign":"كسرة لفظاً","detail":"وهو مضاف والكاف ضمير متصل مضاف إليه"}]', '["أخرجه مسلم في صحيحه (2564)."]', '{"en":"Abu Hurairah narrated that the Messenger of Allah ﷺ said: ''Verily, Allah does not look at your bodies or your appearances, but He looks at your hearts and your deeds.''","ar":"المقصود طهارة السريرة وصدق الإخلاص، فالقلب محل نظر الرب سبحانه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch2_tawbah', 'riyad_salihin', 1, 'بَابُ التَّوْبَةِ وَشُرُوطِهَا وَفَضْلِ الاسْتِغْفَارِ', 'باب 2: توبہ، اس کی شرائط اور استغفار کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_2_1', 'riyad_ch2_tawbah', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «وَاللَّهِ إِنِّي لَأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي اليَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''اللہ کی قسم! میں دن بھر میں ستر مرتبہ سے بھی زیادہ اللہ تعالیٰ سے استغفار کرتا ہوں اور اس کی بارگاہ میں توبہ کرتا ہوں۔''', 'جب سید الانبیاء ﷺ تمام گناہوں سے پاک اور معصوم ہونے کے باوجود روزانہ کثرت سے استغفار فرماتے تھے، تو امت کے لیے ہر وقت توبہ و انابت کا دامن تھامے رکھنا کتنا ضروری ہے۔', '[{"word":"وَاللَّهِ","role":"واو القسم وجار ومجرور","sign":"كسرة لفظاً","detail":"متعلق بفعل أقسم المحذوف"},{"word":"لَأَسْتَغْفِرُ","role":"اللام واقعة في جواب القسم","sign":"ضمة لفظاً","detail":"فعل مضارع مرفوع والفاعل ضمير مستتر تقديره أنا"}]', '["أخرجه البخاري في صحيحه (6307)."]', '{"en":"Abu Hurairah reported: I heard Allah''s Messenger ﷺ saying: ''By Allah, I seek forgiveness of Allah and turn to Him in repentance more than seventy times a day.''","ar":"بيان عظم شأن التوبة والاستغفار واقتداء الأمة بالنبي المعصوم ﷺ."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_2_2', 'riyad_ch2_tawbah', 'riyad_salihin', 1, 'وَعَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَلَّهُ أَشَدُّ فَرَحاً بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا... فَبَيْنَمَا هُوَ كَذَلِكَ إِذَا هُوَ بِهَا قَائِمَةً عِنْدَهُ... ثُمَّ قَالَ مِنْ شِدَّةِ الفَرَحِ: اللَّهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ، أَخْطَأَ مِنْ شِدَّةِ الفَرَحِ».', 'حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے فرمایا: ''اللہ تعالیٰ اپنے بندے کی توبہ سے اس شخص سے بھی زیادہ خوش ہوتا ہے جس کی سواری کسی بیابان صحرا میں گم ہو جائے اور اسی پر اس کا سارا کھانا پینا ہو، اور وہ زندگی سے مایوس ہو کر کسی درخت کے سائے میں موت کا انتظار کرنے لگے، پھر اچانک وہ اپنی سواری کو بالکل اپنے پاس کھڑا پائے... تو وہ بے پناہ خوشی کی شدت میں زبان کی لغزش سے بول اٹھے: اے اللہ! تو میرا بندہ اور میں تیرا رب ہوں!''', 'اللہ تعالیٰ کی رحمت اپنے گناہ گار بندوں کے لیے بے پایاں ہے۔ یہ مثال سمجھاتی ہے کہ اللہ کے دربار میں مایوسی کفر ہے، جب بھی بندہ سچے دل سے رجوع کرتا ہے، اللہ تعالیٰ اسے گلے لگا لیتا ہے۔', '[{"word":"لَلَّهُ","role":"لام الابتداء ولفظ الجلالة مبتدأ","sign":"ضمة لفظاً","detail":"تفيد التوكيد ولفظ الجلالة مرفوع بالابتداء"},{"word":"أَشَدُّ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"اسم تفضيل ممنوع من الصرف"}]', '["متفق عليه: أخرجه البخاري (6309)، ومسلم (2747)."]', '{"en":"Anas reported that Allah''s Messenger ﷺ said: ''Allah is more pleased with the repentance of His servant than one of you who lost his camel loaded with food and water in a barren desert, surrendered to death, then suddenly found it standing before him...''","ar":"ضرب الأمثال لتقريب سعة رحمة الله وفرحه بعودة العبد المذنب إليه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch3_sabr', 'riyad_salihin', 2, 'بَابُ الصَّبْرِ وَالمُصَابَرَةِ عَلَى البَلَاءِ وَالمَصَائِبِ', 'باب 3: صبر، مصائب پر استقامت اور اس کا عظیم اجر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_3_1', 'riyad_ch3_sabr', 'riyad_salihin', 0, 'عَنْ أَبِي يَحْيَى صُهَيْبِ بْنِ سِنَانٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «عَجَباً لِأَمْرِ المُؤْمِنِ، إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ: إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْراً لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْراً لَهُ».', 'حضرت صہیب رومی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''مومن کا معاملہ بھی خوب عجیب ہے! اس کے ہر معاملے میں سراسر خیر ہی خیر ہے، اور یہ فضیلت مومن کے سوا کسی کو حاصل نہیں: اگر اسے خوشی اور نعمت ملے تو وہ شکر ادا کرتا ہے تو یہ اس کے لیے خیر بن جاتی ہے، اور اگر اسے کوئی تکلیف یا دکھ پہنچے تو وہ صبر کرتا ہے تو یہ بھی اس کے لیے خیر بن جاتی ہے۔''', 'مومن کی پوری زندگی شکر اور صبر کے دو پروں کے درمیان پرواز کرتی ہے۔ نعمت پر شکر اور مصیبت پر صبر انسان کو ہر حالت میں اللہ کا مقرب بنا دیتے ہیں۔', '[{"word":"عَجَباً","role":"مفعول مطلق لفعل محذوف","sign":"فتحة لفظاً","detail":"تقديره: أعجب عجباً"},{"word":"كُلَّهُ","role":"توكيد معنوي","sign":"ضمة لفظاً","detail":"توكيد لاسم إن (أمره) مرفوع"}]', '["أخرجه مسلم في صحيحه (2999)."]', '{"en":"Suhaib narrated that the Messenger of Allah ﷺ said: ''How wonderful is the affair of the believer! For all his affairs are good for him, and this is for none except the believer: if prosperity comes to him, he expresses gratitude and it is good for him; and if adversity befalls him, he is patient and it is good for him.''","ar":"المؤمن يتقلب بين مقامي الشكر والصبر، فكلتا الحالتين ربح له في ميزان الحسنات."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_3_2', 'riyad_ch3_sabr', 'riyad_salihin', 1, 'وَعَنْ أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ ﷺ قَالَ: «مَا يُصِيبُ المُسْلِمَ مِنْ نَصَبٍ، وَلَا وَصَبٍ، وَلَا هَمٍّ، وَلَا حُزْنٍ، وَلَا أَذًى، وَلَا غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ».', 'حضرت ابوسعید خدری اور حضرت ابوہریرہ رضی اللہ عنہما سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ''مسلمان کو جو بھی تھکن، بیماری، فکر، غم، تکلیف یا دکھ پہنچتا ہے، یہاں تک کہ وہ کانٹا بھی جو اس کے پاؤں میں چبھ جائے، تو اللہ تعالیٰ اس کے بدلے اس کے گناہوں کا کفارہ فرما دیتا ہے۔''', 'دنیا کی کوئی تکلیف بھی ضائع نہیں جاتی؛ بیماری اور پریشانی اگر بندہ صبر کے ساتھ برداشت کرے تو وہ گناہوں کو ایسے جھاڑ دیتی ہے جیسے خزاں میں درخت کے پتے گرتے ہیں۔', '[{"word":"مَا","role":"حرف نفي","sign":"مبني على السكون","detail":"نافية لا عمل لها"},{"word":"نَصَبٍ","role":"مجرور لفظاً بمن الزائدة","sign":"كسرة لفظاً","detail":"في محل رفع فاعل يُصِيب"}]', '["متفق عليه: البخاري (5641)، ومسلم (2573)."]', '{"en":"Abu Sa''id and Abu Hurairah reported that the Prophet ﷺ said: ''No fatigue, illness, sorrow, grief, hurt, or distress befalls a Muslim, even to the prick of a thorn, except that Allah expiates some of his sins by it.''","ar":"البلايا والمصائب كفارات للذنوب ورافعات للدرجات عند الصبر والاحتساب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch4_sidq', 'riyad_salihin', 3, 'بَابُ الصِّدْقِ وَفَضْلِهِ وَثَمَرَاتِهِ فِي الدُّنْيَا وَالآخِرَةِ', 'باب 4: سچائی، دیانت اور اس کے عظیم ثمرات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_4_1', 'riyad_ch4_sidq', 'riyad_salihin', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ الصِّدْقَ يَهْدِي إِلَى البِرِّ، وَإِنَّ البِرَّ يَهْدِي إِلَى الجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقاً، وَإِنَّ الكَذِبَ يَهْدِي إِلَى الفُجُورِ، وَإِنَّ الفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّاباً».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''بے شک سچائی نیکی کی راہ دکھاتی ہے، اور نیکی جنت کا راستہ بتاتی ہے؛ اور آدمی سچ بولتا رہتا ہے یہاں تک کہ اللہ کے ہاں اس کا نام صدیق (انتہائی سچا) لکھ دیا جاتا ہے۔ اور بے شک جھوٹ گناہ اور نافرمانی کی طرف لے جاتا ہے، اور نافرمانی جہنم کا راستہ دکھاتی ہے؛ اور آدمی جھوٹ بولتا رہتا ہے یہاں تک کہ اللہ کے ہاں اس کا نام کذاب (بڑا جھوٹا) لکھ دیا جاتا ہے۔''', 'سچائی تمام نیکیوں کی جڑ ہے اور جھوٹ تمام برائیوں اور نفاق کی ماں ہے۔ صدقِ لسان انسان کو مقامِ صدیقیت تک پہنچاتا ہے۔', '[{"word":"الصِّدْقَ","role":"اسم إن منصوب","sign":"فتحة لفظاً","detail":"منصوب وعلامة نصبه الفتحة"},{"word":"يَهْدِي","role":"فعل مضارع والفاعل مستتر","sign":"ضمة مقدرة","detail":"والجملة الفعلية في محل رفع خبر إن"}]', '["متفق عليه: البخاري (6094)، ومسلم (2607)."]', '{"en":"Abdullah bin Mas''ud narrated that the Prophet ﷺ said: ''Truthfulness leads to righteousness, and righteousness leads to Paradise. A man continues to speak the truth until he is recorded with Allah as a truthful person (Siddiq)...''","ar":"الحث على الصدق في الأقوال والأفعال والتحذير من الكذب وعواقبه الوخيمة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_4_2', 'riyad_ch4_sidq', 'riyad_salihin', 1, 'وَعَنْ أَبِي مُحَمَّدٍ الحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: حَفِظْتُ مِنْ رَسُولِ اللَّهِ ﷺ: «دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ، فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ، وَإِنَّ الكَذِبَ رِيبَةٌ».', 'حضرت حسن بن علی رضی اللہ عنہما نے فرمایا: میں نے رسول اللہ ﷺ سے یہ بات یاد رکھی ہے کہ آپ ﷺ نے فرمایا: ''جس چیز میں تمہیں شک اور شبہ ہو اسے چھوڑ کر اس چیز کو اختیار کرو جس میں کوئی شک نہ ہو، کیونکہ سچائی دل کا سکون و اطمینان ہے اور جھوٹ شک اور بے چینی ہے۔''', 'یہ حدیثِ مبارک شبہات سے بچنے اور تقویٰ و ورع اختیار کرنے کا عظیم ترین ضابطہ ہے۔ دل کا حقیقی سکون صرف سچائی اور حلال میں ہے۔', '[{"word":"دَعْ","role":"فعل أمر مبني على السكون","sign":"سكون","detail":"والفاعل ضمير مستتر وجوباً تقديره أنت"},{"word":"مَا","role":"اسم موصول مفعول به","sign":"مبني على السكون","detail":"في محل نصب مفعول به"}]', '["أخرجه الترمذي (2518) وقال: حديث حسن صحيح."]', '{"en":"Al-Hasan bin ''Ali reported: I memorized from Allah''s Messenger ﷺ: ''Leave that which makes you doubt for that which does not make you doubt. For indeed, truthfulness brings tranquility, while falsehood brings doubt and unease.''","ar":"قاعدة شرعية جليلة في الورع واجتناب الشبهات والتحلي بالصدق."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch5_muraqabah', 'riyad_salihin', 4, 'بَابُ المُرَاقَبَةِ وَخَشْيَةِ اللَّهِ فِي السِّرِّ وَالعَلَنِ', 'باب 5: مراقبہ، تنہائی و جلوت میں اللہ کا خوف اور استحضارِ ربوبیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_5_1', 'riyad_ch5_muraqabah', 'riyad_salihin', 0, 'عَنْ أَبِي ذَرٍّ جُنْدَبِ بْنِ جُنَادَةَ، وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ ﷺ قَالَ: «اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ».', 'حضرت ابوذر اور حضرت معاذ بن جبل رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تم جہاں کہیں بھی ہو اللہ سے ڈرتے رہو، اور کسی برائی کے بعد فوراً نیکی کر لیا کرو وہ نیکی اس برائی کو مٹا دے گی، اور لوگوں کے ساتھ حسنِ اخلاق سے پیش آؤ۔''', 'اس مختصر حدیث میں دین و دنیا کی تمام تر بھلائیاں سمو دی گئی ہیں: خالق کے ساتھ تقویٰ، اپنی خطاؤں کا نیکیوں سے علاج، اور مخلوق کے ساتھ بہترین اخلاق۔', '[{"word":"اتَّقِ","role":"فعل أمر","sign":"حذف حرف العلة","detail":"مبني على حذف الياء والفاعل مستتر تقديره أنت"},{"word":"حَيْثُمَا","role":"اسم شرط جازم للمكان","sign":"مبني على الضم","detail":"في محل نصب ظرف مكان"}]', '["أخرجه الترمذي (1987) وقال: حديث حسن."]', '{"en":"Abu Dharr and Mu''adh bin Jabal reported that the Messenger of Allah ﷺ said: ''Fear Allah wherever you may be; follow up an evil deed with a good one and it will wipe it out; and behave towards people with good manners.''","ar":"وصية نبوية جامعة جمعت حق الله تعالى في التقوى وحق النفس في التوبة وحق العباد في حسن الخلق."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_5_2', 'riyad_ch5_muraqabah', 'riyad_salihin', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي المَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِياً فَفَاضَتْ عَيْنَاهُ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ نبی کریم ﷺ نے ارشاد فرمایا: ''سات خوش نصیب ایسے ہیں جنہیں اللہ تعالیٰ اس دن اپنے عرش کے سائے میں جگہ دے گا جس دن اس کے سائے کے سوا کوئی سایہ نہ ہوگا: عادل حکمران، وہ نوجوان جس کی جوانی اللہ کی عبادت میں پروان چڑھی، وہ شخص جس کا دل مسجد سے اٹکا رہتا ہو، وہ دو شخص جو اللہ کے لیے محبت کریں اسی پر جمع ہوں اور اسی پر جدا ہوں، وہ شخص جسے کسی حسب و نسب اور حسن والی عورت نے گناہ کی دعوت دی تو اس نے کہا: میں اللہ سے ڈرتا ہوں، وہ شخص جس نے اتنا پوشیدہ صدقہ کیا کہ اس کے بائیں ہاتھ کو بھی خبر نہ ہوئی کہ دائیں ہاتھ نے کیا خرچ کیا، اور وہ شخص جس نے تنہائی میں اللہ کو یاد کیا اور اس کی آنکھوں سے آنسو جاری ہو گئے۔''', 'قیامت کی ہولناک گرمی میں عرش کا سایہ ان اہل اخلاص کو ملے گا جنہوں نے جوانی کی خواہشات کو دبایا، مساجد کو آباد کیا، تنہائیوں میں آنسو بہائے اور گناہ کی دعوت کو خوفِ خدا کی خاطر ٹھکرا دیا۔', '[{"word":"سَبْعَةٌ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"سوغ الابتداء بالنكرة كونها موصوفة بجملة يظلهم"},{"word":"إِمَامٌ","role":"بدل من سبعة","sign":"ضمة لفظاً","detail":"بدل تفصيل مرفوع"}]', '["متفق عليه: البخاري (660)، ومسلم (1031)."]', '{"en":"Abu Hurairah reported that the Prophet ﷺ said: ''Seven will be shaded by Allah under His Shade on the Day when there is no shade except His: a just ruler, a youth who grew up in the worship of Allah... and a person who remembers Allah in solitude and his eyes overflow with tears.''","ar":"أهل الإخلاص والمراقبة في أعلى درجات الكرامة يوم القيامة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch6_taqwa', 'riyad_salihin', 5, 'بَابُ التَّقْوَى وَفَضْلِهَا فِي الدُّنْيَا وَالآخِرَةِ', 'باب 6: تقویٰ، پرہیزگاری اور اس کی عظیم برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_6_1', 'riyad_ch6_taqwa', 'riyad_salihin', 0, 'عَنْ أَبِي أُمَامَةَ صُدَيِّ بْنِ عَجْلَانَ البَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَخْطُبُ فِي حَجَّةِ الوَدَاعِ فَقَالَ: «اتَّقُوا اللَّهَ رَبَّكُمْ، وَصَلُّوا خَمْسَكُمْ، وَصُومُوا شَهْرَكُمْ، وَأَدُّوا زَكَاةَ أَمْوَالِكُمْ، وَأَطِيعُوا ذَا أَمْرِكُمْ، تَدْخُلُوا جَنَّةَ رَبِّكُمْ».', 'حضرت ابو امامہ باہلی رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو حجتہ الوداع کے خطبے میں فرماتے سنا: ''اپنے رب اللہ سے ڈرو، اپنی پانچوں نمازیں ادا کرو، اپنے ماہِ رمضان کے روزے رکھو، اپنے مالوں کی زکوٰۃ ادا کرو، اور اپنے حکمرانوں اور امیروں کی جائز باتوں میں اطاعت کرو، تم اپنے رب کی جنت میں داخل ہو جاؤ گے۔''', 'رسول اکرم ﷺ نے آخری خطبے میں تمام بنیادی ارکان کو جمع فرما کر واضح کر دیا کہ تقویٰ اور شریعت پر عمل پیرا ہونا ہی دائمی فلاح اور دخولِ جنت کا واحد راستہ ہے۔', '[{"word":"اتَّقُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"},{"word":"تَدْخُلُوا","role":"جواب الطلب مجزوم","sign":"حذف النون","detail":"مجزوم في جواب الأمر وعلامة جزمه حذف النون"}]', '["أخرجه الترمذي في آخر كتاب الصلاة (616) وقال: حديث حسن صحيح."]', '{"en":"Abu Umamah reported: I heard Allah''s Messenger ﷺ deliver a sermon in the Farewell Pilgrimage saying: ''Fear your Lord, pray your five daily prayers, fast your month of Ramadan, pay the Zakah on your wealth, and obey your leaders, and you will enter the Paradise of your Lord.''","ar":"وصية جامعة من خطبة حجة الوداع جمعت أركان الإسلام وثمرتها دخول الجنة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_6_2', 'riyad_ch6_taqwa', 'riyad_salihin', 1, 'وَعَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «البِرُّ حُسْنُ الخُلُقِ، وَالإِثْمُ مَا حَاكَ فِي نَفْسِكَ، وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ».', 'حضرت نواس بن سمعان رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ''نیکی اچھے اخلاق کا نام ہے، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور بے چین کرے اور تم ناپسند کرو کہ لوگوں کو اس کی خبر ہو۔''', 'انسان کی فطرتِ سلیمہ گناہ پر بے چین ہو جاتی ہے۔ متقی انسان اپنے ضمیر کی اس پکار کو پہچانتا ہے اور ہر ایسے عمل سے دور رہتا ہے جسے وہ ظاہر کرنے سے شرمائے۔', '[{"word":"البِرُّ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالابتداء"},{"word":"حُسْنُ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والخلق مضاف إليه"}]', '["أخرجه مسلم في صحيحه (2553)."]', '{"en":"An-Nawwas bin Sam''an reported that the Prophet ﷺ said: ''Righteousness is good character, and sin is that which wavers in your heart and you dislike people finding out about it.''","ar":"الفطرة السليمة والضمير الحي ميزان لمعرفة الإثم واجتناب الشبهات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch7_tawakkul', 'riyad_salihin', 6, 'بَابُ اليَقِينِ وَالتَّوَكُّلِ عَلَى اللَّهِ تَعَالَى', 'باب 7: یقین، حسنِ ظن اور اللہ تعالیٰ پر توکل');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_7_1', 'riyad_ch7_tawakkul', 'riyad_salihin', 0, 'عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «لَوْ أَنَّكُمْ تَتَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ، تَغْدُو خِمَاصاً وَتَرُوحُ بِطَاناً».', 'حضرت عمر فاروق رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''اگر تم اللہ تعالیٰ پر ویسا توکل کرو جیسا کہ توکل کرنے کا حق ہے، تو وہ تمہیں اس طرح رزق عطا فرمائے گا جیسے وہ پرندوں کو رزق دیتا ہے؛ کہ وہ صبح خالی پیٹ نکلتے ہیں اور شام کو پیٹ بھر کر لوٹتے ہیں۔''', 'توکل کا مطلب ہاتھ پر ہاتھ رکھ کر بیٹھنا نہیں ہے، بلکہ پرندوں کی طرح محنت و جستجو کے لیے نکلنا اور دل کا بھروسہ صرف اور صرف رزاقِ حقیقی پر رکھنا ہے۔', '[{"word":"لَوْ","role":"حرف شرط غير جازم","sign":"مبني على السكون","detail":"حرف امتناع لامتناع"},{"word":"خِمَاصاً","role":"حال منصوب","sign":"فتحة لفظاً","detail":"حال من فاعل تغدو"}]', '["أخرجه الترمذي (2344) وقال: حديث حسن صحيح."]', '{"en":"''Umar bin Al-Khattab reported: I heard Allah''s Messenger ﷺ saying: ''If you were to rely upon Allah with true reliance, He would provide for you just as He provides for birds: they depart in the morning with empty stomachs and return in the evening full.''","ar":"التوكل الشرعي يجمع بين اعتماد القلب على الله والأخذ بالأسباب المشروعة كخروج الطير وسعيه."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_7_2', 'riyad_ch7_tawakkul', 'riyad_salihin', 1, 'وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: «حَسْبُنَا اللَّهُ وَنِعْمَ الوَكِيلُ» قَالَهَا إِبْرَاهِيمُ ﷺ حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ ﷺ حِينَ قَالُوا لَهُ: ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَاناً وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الوَكِيلُ﴾.', 'حضرت عبداللہ بن عباس رضی اللہ عنہما نے فرمایا: ''حسبنا اللہ ونعم الوکیل'' (ہمیں اللہ کافی ہے اور وہ کیا ہی بہترین کارساز ہے!) یہ وہ کلمہ مبارکہ ہے جو حضرت ابراہیم علیہ السلام نے اس وقت پکارا جب انہیں آگ میں ڈالا جا رہا تھا، اور یہی کلمہ سیدنا محمد ﷺ نے اس وقت فرمایا جب لوگوں نے کہا کہ کافروں نے تمہارے خلاف لشکر جمع کر لیا ہے تو ڈرو، مگر اس بات نے مسلمانوں کے ایمان کو اور بڑھا دیا اور انہوں نے کہا: ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے۔', 'جب تمام ظاہری اسباب ٹوٹ جائیں تو ''حسبنا اللہ ونعم الوکیل'' کا ورد بندۂ مومن کے لیے نصرتِ الٰہی کا دروازہ کھول دیتا ہے، جیسا کہ حضرت ابراہیم کے لیے آگ گلزار بن گئی تھی۔', '[{"word":"حَسْبُنَا","role":"مبتدأ مرفوع","sign":"ضمة مقدرة","detail":"وهو مضاف ونا ضمير متصل مضاف إليه"},{"word":"اللَّهُ","role":"خبر المبتدأ","sign":"ضمة لفظاً","detail":"لفظ الجلالة مرفوع بالخبرية"}]', '["أخرجه البخاري في صحيحه (4563)."]', '{"en":"Ibn ''Abbas reported: ''Allah alone is sufficient for us, and He is the best disposer of affairs'' was said by Ibrahim when he was thrown into the fire, and was said by Muhammad ﷺ when people said to them: ''Verily, people have gathered against you, so fear them.''","ar":"كلمة التوحيد واللجوء المطلق إلى الله عند الشدائد والأزمات العظام."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch8_istiqamah', 'riyad_salihin', 7, 'بَابُ الاسْتِقَامَةِ وَلُزُومِ الصِّرَاطِ المُسْتَقِيمِ', 'باب 8: استقامت اور صراطِ مستقیم پر ہمیشگی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_8_1', 'riyad_ch8_istiqamah', 'riyad_salihin', 0, 'عَنْ أَبِي عَمْرٍو، وَقِيلَ: أَبِي عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللَّهِ الثَّقَفِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، قُلْ لِي فِي الإِسْلَامِ قَوْلاً لَا أَسْأَلُ عَنْهُ أَحَداً غَيْرَكَ، قَالَ: «قُلْ: آمَنْتُ بِاللَّهِ، ثُمَّ اسْتَقِمْ».', 'حضرت سفیان بن عبداللہ ثقفی رضی اللہ عنہ نے عرض کیا: یا رسول اللہ! مجھے اسلام کے بارے میں ایسی جامع بات ارشاد فرما دیجیے کہ آپ کے بعد مجھے کسی اور سے پوچھنے کی ضرورت نہ رہے۔ آپ ﷺ نے فرمایا: ''کہو: میں اللہ پر ایمان لایا، پھر اس پر ڈٹ جاؤ (استقامت اختیار کرو)''۔', 'استقامت کرامت سے بڑھ کر ہے۔ ایمان لانے کے بعد شریعت کے احکام پر زندگی کی آخری سانس تک استقلال کے ساتھ قائم رہنا ہی انسان کی اصل کامیابی ہے۔', '[{"word":"آمَنْتُ","role":"فعل ماض وفاعل","sign":"مبني على السكون","detail":"والتاء ضمير متصل فاعل في محل نصب مقول القول"},{"word":"اسْتَقِمْ","role":"فعل أمر مبني على السكون","sign":"سكون","detail":"والفاعل ضمير مستتر تقديره أنت"}]', '["أخرجه مسلم في صحيحه (38)."]', '{"en":"Sufyan bin ''Abdullah reported: I said: ''O Messenger of Allah! Tell me something about Islam so comprehensive that I will not need to ask anyone after you.'' He replied: ''Say: I believe in Allah, and then be steadfast.''","ar":"هذا الحديث من جوامع كلمه ﷺ، جمع فيه الإيمان والعمل والاستمرار عليه."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_8_2', 'riyad_ch8_istiqamah', 'riyad_salihin', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «سَدِّدُوا وَقَارِبُوا، وَاعْلَمُوا أَنَّهُ لَنْ يَنْجُوَ أَحَدٌ مِنْكُمْ بِعَمَلِهِ»، قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: «وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِي اللَّهُ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''درستی اور میانہ روی اختیار کرو، اور جان لو کہ تم میں سے کوئی بھی محض اپنے عمل کے بل بوتے پر نجات نہیں پا سکے گا۔'' صحابہ کرام نے عرض کیا: یا رسول اللہ! کیا آپ بھی نہیں؟ فرمایا: ''نہ میں، بجز اس کے کہ اللہ تعالیٰ مجھے اپنی خاص رحمت اور فضل کی چادر میں ڈھانپ لے!''', 'بندے کو کبھی اپنے اعمال پر ناز اور گھمنڈ نہیں کرنا چاہیے؛ اعمال تو بندگی کی علامت ہیں، اصل نجات اور جنت اللہ کے بے پایاں فضل و کرم سے ہی نصیب ہوگی۔', '[{"word":"سَدِّدُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو فاعل"},{"word":"لَنْ","role":"حرف نفي ونصب واستقبال","sign":"مبني على السكون","detail":"ينجو فعل مضارع منصوب بالفتحة"}]', '["أخرجه مسلم في صحيحه (2816)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Aim for accuracy and moderation, and know that none of you will be saved merely by his actions.'' They said: ''Not even you, O Messenger of Allah?'' He said: ''Not even me, unless Allah envelops me in His mercy and grace.''","ar":"النجاة ودخول الجنة برحمة الله وفضله، والأعمال أسباب وأمارات للقبول."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch9_tafakkur', 'riyad_salihin', 8, 'بَابُ التَّفَكُّرِ فِي فَنَاءِ الدُّنْيَا وَعَظِيمِ خَلْقِ اللَّهِ', 'باب 9: دنیا کی ناپائیداری اور اللہ کی مخلوقات میں تفکر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_9_1', 'riyad_ch9_tafakkur', 'riyad_salihin', 0, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللَّهِ ﷺ بِمَنْكِبَيَّ فَقَالَ: «كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ، أَوْ عَابِرُ سَبِيلٍ». وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: «إِذَا أَمْسَيْتَ فَلَا تَنْتَظِرِ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلَا تَنْتَظِرِ المَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ، وَمِنْ حَيَاتِكَ لِمَوْتِكَ».', 'حضرت عبداللہ بن عمر رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ ﷺ نے میرے دونوں کندھوں کو پکڑ کر ارشاد فرمایا: ''دنیا میں اس طرح رہو گویا تم کوئی اجنبی پردیسی ہو، یا راستہ طے کرنے والے مسافر ہو۔'' اور حضرت ابن عمر فرمایا کرتے تھے: جب شام ہو جائے تو صبح کا انتظار نہ کرو، اور جب صبح ہو جائے تو شام کا انتظار نہ کرو؛ اور اپنی صحت کے زمانے میں بیماری کے وقت کے لیے، اور اپنی زندگی میں موت کے لیے تیاری کر لو۔', 'مسافر منزل پر پہنچنے کے لیے سامان ہلکا رکھتا ہے۔ اسی طرح مومن کو دنیا میں مستقل گھر نہیں بسانا چاہیے بلکہ آخرت کی ابدی منزل کے لیے توشہ تیار کرنا چاہیے۔', '[{"word":"كُنْ","role":"فعل أمر ناقص","sign":"سكون","detail":"واسمها ضمير مستتر تقديره أنت"},{"word":"كَأَنَّكَ","role":"كأن حرف تشبيه ونصب","sign":"مبني على الفتح","detail":"والكاف اسمها وغريب خبرها"}]', '["أخرجه البخاري في صحيحه (6416)."]', '{"en":"Ibn ''Umar narrated: Allah''s Messenger ﷺ took me by my shoulders and said: ''Be in this world as if you were a stranger or a wayfarer.'' And Ibn ''Umar used to say: ''When evening comes, do not anticipate the morning...''","ar":"الزهد في الدنيا وقصر الأمل والاستعداد للمصير الأخروي."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_9_2', 'riyad_ch9_tafakkur', 'riyad_salihin', 1, 'وَعَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَامَ رَسُولُ اللَّهِ ﷺ عَلَى حَصِيرٍ فَقَامَ وَقَدْ أَثَّرَ فِي جَنْبِهِ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، لَوِ اتَّخَذْنَا لَكَ وِطَاءً؟ فَقَالَ: «مَا لِي وَلِلدُّنْيَا؟ مَا أَنَا فِي الدُّنْيَا إِلَّا كَرَاكِبٍ اسْتَظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ ایک چٹائی پر سوئے، جب آپ بیدار ہوئے تو آپ کے مبارک جسم پر چٹائی کے نشانات پڑ گئے تھے۔ ہم نے عرض کیا: یا رسول اللہ! کاش ہم آپ کے لیے کوئی نرم بستر بچھا دیا کرتے؟ آپ ﷺ نے ارشاد فرمایا: ''مجھے دنیا سے کیا سروکار؟ میری اور دنیا کی مثال تو بس اس سوار کی سی ہے جس نے چلتے ہوئے کسی درخت کے سائے میں کچھ دیر آرام کیا، پھر روانہ ہوا اور درخت کو وہیں چھوڑ گیا۔''', 'یہ شان ہے شہنشاہِ کونین ﷺ کی کہ قیصر و کسریٰ کے محلات سونے چاندی سے آراستہ تھے اور رحمتِ عالم کے پہلوئے اقدس پر بوریا کے نشان پڑتے تھے۔ یہ زہد امت کو سادگی کا درس دیتا ہے۔', '[{"word":"مَا","role":"اسم استفهام مبني","sign":"سكون","detail":"في محل رفع مبتدأ وللدنيا جار ومجرور خبره"},{"word":"إِلَّا","role":"أداة استثناء ملغاة","sign":"مبني","detail":"أداة حصر والقصر"}]', '["أخرجه الترمذي (2377) وقال: حديث حسن صحيح."]', '{"en":"Abdullah bin Mas''ud reported: The Messenger of Allah ﷺ slept on a straw mat and stood up with marks on his side. We said: ''O Messenger of Allah, if only we prepared a soft bedding for you?'' He replied: ''What do I have to do with this world? My example in this world is like a rider who shades under a tree, then leaves it behind.''","ar":"ضرب المثل النبوي في زهد النبي الأكرم وعلو همته عن حطام الدنيا."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch10_mubadarah', 'riyad_salihin', 9, 'بَابُ المُبَادَرَةِ إِلَى الخَيْرَاتِ وَالمُسَارَعَةِ فِيهَا', 'باب 10: نیکیوں میں سبقت اور وقت کی قدر و قیمت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_10_1', 'riyad_ch10_mubadarah', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «بَادِرُوا بِالأَعْمَالِ فِتَناً كَقِطَعِ اللَّيْلِ المُظْلِمِ، يُصْبِحُ الرَّجُلُ مُؤْمِناً وَيُمْسِي كَافِراً، أَوْ يُمْسِي مُؤْمِناً وَيُصْبِحُ كَافِراً، يَبِيعُ دِينَهُ بِعَرَضٍ مِنَ الدُّنْيَا».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تاریک رات کے ٹکڑوں کی مانند فتنوں کے امڈ آنے سے پہلے پہلے نیک اعمال کرنے میں جلدی کر لو! فتنوں کا یہ حال ہوگا کہ آدمی صبح مومن ہوگا اور شام کو کافر ہو جائے گا، یا شام کو مومن ہوگا اور صبح کافر ہو جائے گا؛ لوگ دنیا کے حقیر ساز و سامان کے بدلے اپنا دین بیچ ڈالیں گے۔''', 'فتنوں کے دور میں ایمان کی حفاظت کا واحد ڈھال نیک اعمال اور سنت کی پیروی ہے۔ وقت ضائع کرنا اور توبہ میں تاخیر انسان کو گمراہی کی دلدل میں دھکیل سکتی ہے۔', '[{"word":"بَادِرُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"},{"word":"فِتَناً","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"وعلامة نصبه الفتحة الظاهرة"}]', '["أخرجه مسلم في صحيحه (118)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Hasten to do good deeds before trials emerge like patches of dark night, wherein a man wakes up as a believer and becomes an unbeliever by evening... selling his religion for a paltry worldly gain.''","ar":"التحذير من فتن آخر الزمان والحث على التمسك بالأعمال الصالحة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_10_2', 'riyad_ch10_mubadarah', 'riyad_salihin', 1, 'وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ: الصِّحَّةُ وَالفَرَاغُ».', 'حضرت عبداللہ بن عباس رضی اللہ عنہما نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''دو نعمتیں ایسی ہیں جن کے معاملے میں بہت سے لوگ بڑے خسارے اور دھوکے میں مبتلا ہیں: ایک صحت اور دوسری فراغت (فارغ وقت)۔''', 'انسان جب تندرست اور فارغ ہوتا ہے تو غفلت برتتا ہے، اور جب بیماری یا مصروفیات گھیر لیتی ہیں تو حسرت کرتا ہے۔ طالب علم کے لیے صحت اور فرصت سب سے بڑی دولت ہے۔', '[{"word":"نِعْمَتَانِ","role":"مبتدأ مرفوع","sign":"ألف المثنى","detail":"وعلامة رفعه الألف لأنه مثنى"},{"word":"مَغْبُونٌ","role":"نعت أو خبر ثان","sign":"ضمة لفظاً","detail":"اسم مفعول ونائب فاعله كثير"}]', '["أخرجه البخاري في صحيحه (6412)."]', '{"en":"Ibn ''Abbas reported that the Messenger of Allah ﷺ said: ''There are two blessings in which many people are in great loss: health and free time.''","ar":"بيان قيمة الوقت والصحة واغتنامهما في طاعة الله قبل فوات الأوان."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch11_mujahadah', 'riyad_salihin', 10, 'بَابُ المُجَاهَدَةِ وَمُحَاسَبَةِ النَّفْسِ', 'باب 11: نفس کے خلاف جہاد اور روزمرہ محاسبہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_11_1', 'riyad_ch11_mujahadah', 'riyad_salihin', 0, 'عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «الكَيِّسُ مَنْ دَانَ نَفْسَهُ وَعَمِلَ لِمَا بَعْدَ المَوْتِ، وَالعَاجِزُ مَنْ أَتْبَعَ نَفْسَهُ هَوَاهَا وَتَمَنَّى عَلَى اللَّهِ».', 'حضرت شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''عقلمند اور زیرک وہ شخص ہے جس نے اپنے نفس کا محاسبہ کیا اور موت کے بعد کی زندگی کے لیے تیاری کی؛ اور بے بس اور کمزور وہ شخص ہے جس نے اپنے نفس کو خواہشات کے پیچھے لگا دیا اور اللہ سے جھوٹی امیدیں باندھتا رہا۔''', 'محاسبہ نفس کا مطلب ہے کہ انسان ہر شام سونے سے پہلے اپنے اعمال کا جائزہ لے کہ آج کے دن اللہ کا کتنا حق ادا کیا اور کتنی نافرمانی کی۔ بغیر عمل کے صرف امیدیں باندھنا خود فریبی ہے۔', '[{"word":"الكَيِّسُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالابتداء"},{"word":"مَنْ","role":"اسم موصول خبر المبتدأ","sign":"مبني على السكون","detail":"في محل رفع خبر"}]', '["أخرجه الترمذي (2459) وقال: حديث حسن."]', '{"en":"Shaddad bin Aws reported that the Prophet ﷺ said: ''The wise person is one who holds himself accountable and works for what comes after death; and the helpless person is one who follows his desires and still hopes from Allah.''","ar":"المحاسبة الدائمة للنفس وحذر الركون إلى التمني الباطل دون عمل."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_11_2', 'riyad_ch11_mujahadah', 'riyad_salihin', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الجَنَّةُ بِالمَكَارِهِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جہنم کو دل لبھانے والی خواہشات سے ڈھانپ دیا گیا ہے، اور جنت کو مشقت اور ناپسندیدہ چیزوں سے گھیر دیا گیا ہے۔''', 'جنت کا راستہ آسان نہیں، اس میں فجر کی ٹھنڈک میں بیداری، حلال و حرام کی تمیز، اور نفس کی خواہشات کی قربانی درکار ہے۔ جبکہ جہنم کا راستہ وقتی لذتوں اور گناہوں سے مزین ہے۔', '[{"word":"حُجِبَتِ","role":"فعل ماض مبني للمجهول","sign":"مبني على الفتح","detail":"والتاء للتأنيث والنار نائب فاعل مرفوع"}]', '["متفق عليه: البخاري (6487)، ومسلم (2822)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''The Hellfire is veiled behind desires, and Paradise is veiled behind hardships.''","ar":"طريق الجنة محفوف بالصبر على الطاعات واجتناب المغريات المحرمة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch12_ilm', 'riyad_salihin', 11, 'بَابُ فَضْلِ العِلْمِ وَطَلَبِهِ وَبَثِّهِ فِي النَّاسِ', 'باب 12: طلبِ علم، فقاہت اور اشاعتِ علم کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_12_1', 'riyad_ch12_ilm', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ سَلَكَ طَرِيقاً يَلْتَمِسُ فِيهِ عِلْماً، سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقاً إِلَى الجَنَّةِ».', 'حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو شخص علم دین حاصل کرنے کے لیے کسی راستے پر نکلتا ہے، تو اللہ تعالیٰ اس کے بدلے اس کے لیے جنت کا راستہ آسان فرما دیتا ہے۔''', 'طالب علم کے اٹھنے والے تمام قدم جنت کی طرف اٹھتے ہیں۔ فرشتے طالب علم کے اکرام میں اپنے پر بچھاتے ہیں اور سمندر کی مچھلیاں تک اس کے لیے استغفار کرتی ہیں۔', '[{"word":"مَنْ","role":"اسم شرط جازم","sign":"مبني على السكون","detail":"في محل رفع مبتدأ"},{"word":"سَلَكَ","role":"فعل ماض في محل جزم","sign":"فعل الشرط","detail":"والفاعل مستتر تقديره هو"}]', '["أخرجه مسلم في صحيحه (2699)."]', '{"en":"Abu Hurairah reported that the Messenger of Allah ﷺ said: ''Whoever treads a path seeking knowledge, Allah will make easy for him thereby a path to Paradise.''","ar":"بيان عظمة فضل طلب العلم الشرعي وتيسيره لطريق الجنة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_12_2', 'riyad_ch12_ilm', 'riyad_salihin', 1, 'وَعَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «فَضْلُ العَالِمِ عَلَى العَابِدِ كَفَضْلِي عَلَى أَدْنَاكُمْ»، ثُمَّ قَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ وَمَلَائِكَتَهُ وَأَهْلَ السَّمَاوَاتِ وَالأَرْضِ حَتَّى النَّمْلَةَ فِي جُحْرِهَا وَحَتَّى الحُوتَ لَيُصَلُّونَ عَلَى مُعَلِّمِ النَّاسِ الخَيْرَ».', 'حضرت ابو امامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''عالم کی فضیلت عابد پر ایسی ہے جیسے میری فضیلت تم میں سے ادنیٰ ترین شخص پر!'' پھر آپ ﷺ نے فرمایا: ''بے شک اللہ تعالیٰ، اس کے فرشتے، تمام آسمان اور زمین کی مخلوقات، یہاں تک کہ چیونٹی اپنے سوراخ میں اور مچھلیاں سمندر میں اس شخص کے لیے خیر اور رحمت کی دعا کرتی ہیں جو لوگوں کو بھلائی کی تعلیم دیتا ہے۔''', 'عابد کی عبادت کا فائدہ صرف اس کی اپنی ذات تک محدود ہوتا ہے، جبکہ عالم کا نفع پوری انسانیت اور کائنات کے نظام کو مستحکم کرتا ہے، اس لیے ساری کائنات اس کے حق میں دعا گو رہتی ہے۔', '[{"word":"فَضْلُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والعالم مضاف إليه"},{"word":"كَفَضْلِي","role":"شبه جملة خبر المبتدأ","sign":"كسرة مقدرة","detail":"الكاف حرف جر وفضلي مجرور بالكسرة المقدرة"}]', '["أخرجه الترمذي (2685) وقال: حديث حسن صحيح."]', '{"en":"Abu Umamah reported that the Prophet ﷺ said: ''The superiority of the scholar over the devout worshipper is like my superiority over the lowest of you... Verily, Allah, His angels, the inhabitants of the heavens and earth, even the ant in its hole and the fish send blessings upon the teacher of good to mankind.''","ar":"عظم شأن المعلم والداعية إلى الله في ميزان الشريعة المطهرة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch13_quran', 'riyad_salihin', 12, 'بَابُ فَضْلِ قِرَاءَةِ القُرْآنِ الكَرِيمِ وَتَدَبُّرِهِ', 'باب 13: تلاوتِ قرآن، تدبر اور اس کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_13_1', 'riyad_ch13_quran', 'riyad_salihin', 0, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ».', 'حضرت عثمان بن عفان رضی اللہ عنہ نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تم میں سے سب سے بہترین اور افضل وہ شخص ہے جس نے خود قرآن سیکھا اور دوسروں کو سکھایا۔''', 'قرآن مجید کلامِ الٰہی ہے۔ کلام کا شرف متکلم کے شرف کے تابع ہوتا ہے۔ لہٰذا جو شخص قرآن کو پڑھنے اور پڑھانے میں اپنی زندگی صرف کرتا ہے وہ امت کا سب سے معزز فرد ہے۔', '[{"word":"خَيْرُكُمْ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"اسم تفضيل حذفت همزته لكثرة الاستعمال"},{"word":"مَنْ","role":"اسم موصول خبر المبتدأ","sign":"مبني على السكون","detail":"في محل رفع خبر"}]', '["أخرجه البخاري في صحيحه (5027)."]', '{"en":"''Uthman bin ''Affan narrated that the Messenger of Allah ﷺ said: ''The best amongst you are those who learn the Quran and teach it to others.''","ar":"أفضل الناس من جمع بين تعلم كتاب الله وتعليمه للناس ابتغاء وجه الله."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_13_2', 'riyad_ch13_quran', 'riyad_salihin', 1, 'وَعَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «اقْرَؤُوا القُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ القِيَامَةِ شَفِيعاً لِأَصْحَابِهِ».', 'حضرت ابو امامہ رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''قرآن مجید کی تلاوت کیا کرو، کیونکہ وہ قیامت کے دن اپنے پڑھنے والوں کے لیے شفاعت کرنے والا بن کر آئے گا۔''', 'قیامت کے اس دن جب ہر کوئی نفسی نفسی پکار رہا ہوگا، قرآنِ مجید اپنے پڑھنے اور اس پر عمل کرنے والے کے حق میں بارگاہِ الٰہی میں جھگڑا کرے گا اور اسے بخشوا کر جنت میں لے جائے گا۔', '[{"word":"اقْرَؤُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"},{"word":"شَفِيعاً","role":"حال منصوب","sign":"فتحة لفظاً","detail":"حال من الضمير في يأتي"}]', '["أخرجه مسلم في صحيحه (804)."]', '{"en":"Abu Umamah reported: I heard the Messenger of Allah ﷺ saying: ''Recite the Quran, for indeed it will come on the Day of Resurrection as an intercessor for its companions.''","ar":"شفاعة القرآن الكريم لأهله الذين كانوا يتلونه ويعملون بأحكامه في الدنيا."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch14_dhikr', 'riyad_salihin', 13, 'بَابُ فَضْلِ الذِّكْرِ وَالحَثِّ عَلَيْهِ وَمَجَالِسِ الذَّاكِرِينَ', 'باب 14: ذکرِ الٰہی، تسبیح و تہلیل اور ذاکرین کی مجالس');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_14_1', 'riyad_ch14_dhikr', 'riyad_salihin', 0, 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ، مَثَلُ الحَيِّ وَالمَيِّتِ».', 'حضرت ابوموسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''اپنے رب کو یاد کرنے والے اور یاد نہ کرنے والے کی مثال ایسی ہے جیسے زندہ اور مردہ کی مثال!''', 'جسم کی زندگی سانس اور خون کی روانی سے ہے اور روح کی زندگی اللہ کے ذکر سے ہے۔ جس دل میں ذکرِ الٰہی نہ ہو وہ بظاہر چلتا پھرتا جسم ہے مگر حقیقت میں ایک متحرک قبر ہے۔', '[{"word":"مَثَلُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والذي اسم موصول مضاف إليه"},{"word":"الحَيِّ","role":"مضاف إليه مجرور","sign":"كسرة لفظاً","detail":"مثل الثاني خبر المبتدأ"}]', '["متفق عليه: البخاري (6407)، ومسلم (777)."]', '{"en":"Abu Musa Al-Ash''ari reported that the Prophet ﷺ said: ''The example of the one who remembers his Lord and the one who does not remember his Lord is like that of the living and the dead.''","ar":"حياة القلوب الحقيقية بذكر الله، والغفلة موت روحي وإن كان الجسد حياً."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_14_2', 'riyad_ch14_dhikr', 'riyad_salihin', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي المِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ العَظِيمِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''دو کلمے ایسے ہیں جو زبان پر بالکل ہلکے پھلکے ہیں، مگر میزانِ عمل میں بے حد وزنی ہیں، اور رحمان کو نہایت محبوب ہیں: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ العَظِيمِ (اللہ پاک ہے اپنی تعریفوں کے ساتھ، اللہ پاک ہے جو بڑی عظمت والا ہے)''۔', 'امام بخاری نے اپنی صحیح کا اختتام اسی مبارک حدیث پر فرمایا ہے۔ یہ تسبیح اللہ تعالیٰ کی عظمت، تنزیہ اور حمد کا ایسا تحفہ ہے جو بندے کو رحمان کا محبوب بنا دیتا ہے۔', '[{"word":"كَلِمَتَانِ","role":"مبتدأ مرفوع","sign":"ألف المثنى","detail":"وعلامة رفعه الألف لأنه مثنى"},{"word":"خَفِيفَتَانِ","role":"نعت أول مرفوع","sign":"ألف المثنى","detail":"والخبر جملة: سبحان الله"}]', '["متفق عليه: البخاري (6682)، ومسلم (2694)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Two words are light on the tongue, heavy on the Balance, and beloved to the Most Merciful: Subhan Allahi wa bihamdihi, Subhan Allahil-''Azim.''","ar":"ختم به الإمام البخاري صحيحه الشريف، وهو من أجمع الأذكار فضلاً وأجراً."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch15_salawat', 'riyad_salihin', 14, 'بَابُ فَضْلِ الصَّلَاةِ عَلَى النَّبِيِّ ﷺ وَآدَابِهَا', 'باب 15: نبی کریم ﷺ پر درود و سلام کے فضائل و برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_15_1', 'riyad_ch15_salawat', 'riyad_salihin', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ صَلَّى عَلَيَّ صَلَاةً، صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً».', 'حضرت عبداللہ بن عمرو بن العاص رضی اللہ عنہما نے فرمایا کہ انہوں نے رسول اللہ ﷺ کو فرماتے سنا: ''جو شخص مجھ پر ایک مرتبہ درود شریف بھیجتا ہے، اللہ تعالیٰ اس کے بدلے اس پر دس رحمتیں نازل فرماتا ہے۔''', 'خالقِ کائنات کی ایک رحمت دونوں جہانوں کی تمام پریشانیوں کو ختم کرنے کے لیے کافی ہے، اور درود پڑھنے والے کو ہر ایک درود کے بدلے دس رحمتیں، دس درجات کی بلندی اور دس گناہوں کی معافی نصیب ہوتی ہے۔', '[{"word":"مَنْ","role":"اسم شرط جازم","sign":"مبني على السكون","detail":"في محل رفع مبتدأ"},{"word":"عَشْراً","role":"مفعول مطلق نائب عن المصدر","sign":"فتحة لفظاً","detail":"تقديره: صلوات عشراً"}]', '["أخرجه مسلم في صحيحه (384)."]', '{"en":"''Abdullah bin ''Amr bin Al-''As reported that he heard the Messenger of Allah ﷺ saying: ''Whoever sends blessings upon me once, Allah sends blessings upon him ten times thereby.''","ar":"عظيم فضل الصلاة على النبي المصطفى ﷺ وثمراتها العاجلة والآجلة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_15_2', 'riyad_ch15_salawat', 'riyad_salihin', 1, 'وَعَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أَوْلَى النَّاسِ بِي يَوْمَ القِيَامَةِ أَكْثَرُهُمْ عَلَيَّ صَلَاةً».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''قیامت کے دن لوگوں میں مجھ سے سب سے زیادہ قریب اور شفاعت کا حق دار وہ شخص ہوگا جو مجھ پر سب سے زیادہ کثرت سے درود شریف پڑھا کرتا تھا۔''', 'قیامت کے محشر میں آقائے نامدار ﷺ کی شفاعت اور حوضِ کوثر پر ان کا قرب سب سے بڑی کامیابی ہے۔ کثرتِ درود انسان کے دل کو عشقِ رسول کے نور سے منور کرتی ہے۔', '[{"word":"أَوْلَى","role":"مبتدأ مرفوع","sign":"ضمة مقدرة","detail":"اسم تفضيل والناس مضاف إليه"},{"word":"أَكْثَرُهُمْ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف وهم ضمير متصل مضاف إليه"}]', '["أخرجه الترمذي (484) وقال: حديث حسن."]', '{"en":"Ibn Mas''ud reported that the Messenger of Allah ﷺ said: ''The closest of people to me on the Day of Resurrection will be those who sent the most blessings upon me.''","ar":"القرب والوجاهة عند النبي الأعظم ﷺ رهن بكثرة الصلاة والسلام عليه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch16_zuhd', 'riyad_salihin', 15, 'بَابُ الزُّهْدِ فِي الدُّنْيَا وَفَضْلِ القَنَاعَةِ', 'باب 16: زہد فی الدنیا، قناعت اور فقرِ اختیاری کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_16_1', 'riyad_ch16_zuhd', 'riyad_salihin', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «قَدْ أَفْلَحَ مَنْ أَسْلَمَ، وَرُزِقَ كَفَافاً، وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ».', 'حضرت عبداللہ بن عمرو بن العاص رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''کامیاب ہو گیا وہ شخص جس نے اسلام قبول کیا، اور اسے بقدرِ ضرورت (کفاف) روزی نصیب ہوئی، اور اللہ نے اسے جو کچھ دیا اس پر اسے قناعت عطا فرما دی''۔', 'اصل غنا اور دولت دل کی قناعت کا نام ہے۔ جس انسان کے پاس اسلام، بنیادی ضروریات اور راضی بہ رضا رہنے والا دل ہو، وہ دنیا کا سب سے بڑا بادشاہ ہے۔', '[{"word":"قَدْ","role":"حرف تحقيق","sign":"مبني على السكون","detail":"تدخل على الماضي فتفيده التحقيق"},{"word":"كَفَافاً","role":"مفعول به ثان","sign":"فتحة لفظاً","detail":"لفعل رُزق المبني للمجهول"}]', '["أخرجه مسلم في صحيحه (1054)."]', '{"en":"''Abdullah bin ''Amr reported that the Messenger of Allah ﷺ said: ''Successful indeed is he who embraces Islam, is provided with sufficient sustenance, and Allah makes him content with what He gave him.''","ar":"الفلاح الحقيقي في الإسلام والكفاف والقناعة برزق الله."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_16_2', 'riyad_ch16_zuhd', 'riyad_salihin', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «لَيْسَ الغِنَى عَنْ كَثْرَةِ العَرَضِ، وَلَكِنَّ الغِنَى غِنَى النَّفْسِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''امیری اور تونگری دنیاوی ساز و سامان اور مال و دولت کی کثرت کا نام نہیں ہے، بلکہ حقیقی امیری دل کا غنی ہونا ہے۔''', 'بہت سے ارب پتی دل کے غریب اور لالچی ہوتے ہیں، جبکہ جھونپڑی میں بیٹھنے والا درویش اپنے دل کے استغنا کی وجہ سے دنیا سے بے پرواہ ہوتا ہے۔ اصل دولت باطنی قناعت ہے۔', '[{"word":"لَيْسَ","role":"فعل ماض ناقص","sign":"مبني على الفتح","detail":"يرفع الاسم وينصب الخبر"},{"word":"الغِنَى","role":"اسم ليس مرفوع","sign":"ضمة مقدرة","detail":"مرفوع بضمة مقدرة على الألف للتعذر"}]', '["متفق عليه: البخاري (6446)، ومسلم (1051)."]', '{"en":"Abu Hurairah reported that the Prophet ﷺ said: ''Richness is not in having many possessions, but true richness is the richness of the soul (contentment).''","ar":"الغنى الحقيقي غنى القلب والقناعة وعدم التطلع إلى ما في أيدي الناس."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch17_khuluq', 'riyad_salihin', 16, 'بَابُ حُسْنِ الخُلُقِ وَالحِلْمِ وَالرِّفْقِ', 'باب 17: حسنِ اخلاق، حلم اور نرم مزاجی کی برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_17_1', 'riyad_ch17_khuluq', 'riyad_salihin', 0, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ المُؤْمِنِ يَوْمَ القِيَامَةِ مِنْ حُسْنِ الخُلُقِ، وَإِنَّ اللَّهَ يُبْغِضُ الفَاحِشَ البَذِيءَ».', 'حضرت ابو درداء رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''قیامت کے دن مومن کے پلڑے میں حسنِ اخلاق سے زیادہ وزنی کوئی چیز نہیں ہوگی، اور بے شک اللہ تعالیٰ بے حیا اور بدزبان شخص سے سخت نفرت فرماتا ہے۔''', 'نرمی، خندہ پیشانی، درگزر اور دوسروں کے ساتھ ہمدردی کا سلوک انسان کو نفل نماز اور نفل روزے رکھنے والوں کے درجے تک پہنچا دیتا ہے۔', '[{"word":"مَا","role":"نافية تعمل عمل ليس أو مهملة","sign":"مبني","detail":"من شيء مجرور لفظاً مرفوع محلاً مبتدأ"},{"word":"أَثْقَلُ","role":"خبر مرفوع","sign":"ضمة لفظاً","detail":"اسم تفضيل ممنوع من الصرف"}]', '["أخرجه الترمذي (2002) وقال: حديث حسن صحيح."]', '{"en":"Abu Ad-Darda'' reported that the Prophet ﷺ said: ''Nothing is heavier upon the Scale of a believer on the Day of Resurrection than good character. Indeed, Allah hates the shameless and obscene person.''","ar":"حسن الخلق أثقل شيء في ميزان الأعمال الصالحة يوم القيامة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_17_2', 'riyad_ch17_khuluq', 'riyad_salihin', 1, 'وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ، وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ».', 'ام المؤمنین حضرت عائشہ صدیقہ رضی اللہ عنہا نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''نرمی جس چیز میں بھی شامل ہوتی ہے اسے خوبصورت اور پروقار بنا دیتی ہے، اور جس چیز سے نرمی نکال لی جائے وہ اسے عیب دار اور بدنما بنا دیتی ہے۔''', 'دعوتِ دین، تدریس اور گھریلو زندگی میں سختی دلوں کو توڑ دیتی ہے جبکہ حلم اور شفقت پتھر دلوں کو بھی موم کر دیتے ہیں۔ نرمی مومن کا خاصہ ہے۔', '[{"word":"إِنَّ","role":"حرف توكيد ونصب","sign":"مبني","detail":"الرفق اسمها منصوب بالفتحة"},{"word":"زَانَهُ","role":"فعل ماض ومفعول به","sign":"مبني على الفتح","detail":"والفاعل مستتر والجملة في محل نصب خبر كان"}]', '["أخرجه مسلم في صحيحه (2594)."]', '{"en":"''Aishah reported: I heard the Messenger of Allah ﷺ saying: ''Kindness is not found in anything except that it beautifies it, and it is not removed from anything except that it mars it.''","ar":"الرفق بالناس واللين في المعاملة زينة لكل قول وفعل وعمل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch18_birr', 'riyad_salihin', 17, 'بَابُ بِرِّ الوَالِدَيْنِ وَصِلَةِ الأَرْحَامِ', 'باب 18: والدین کے حقوق، حسنِ سلوک اور صلہ رحمی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_18_1', 'riyad_ch18_birr', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ ایک شخص نے رسول اللہ ﷺ کی خدمت میں حاضر ہو کر عرض کیا: یا رسول اللہ! لوگوں میں میرے اچھے سلوک کا سب سے زیادہ حق دار کون ہے؟ آپ ﷺ نے فرمایا: ''تمہاری ماں۔'' اس نے پوچھا: پھر کون؟ فرمایا: ''تمہاری ماں۔'' پوچھا: پھر کون؟ فرمایا: ''تمہاری ماں۔'' پوچھا: پھر کون؟ فرمایا: ''پھر تمہارا باپ۔''', 'ماں کی مشقت اور قربانی بے مثال ہے۔ اسی لیے شریعت نے حسنِ صحبت اور خدمت میں ماں کے حق کو باپ پر تین گنا ترجیح عطا فرمائی ہے۔', '[{"word":"مَنْ","role":"اسم استفهام مبني","sign":"سكون","detail":"في محل رفع مبتدأ أو خبر مقدم"},{"word":"أُمُّكَ","role":"خبر لمبتدأ محذوف","sign":"ضمة لفظاً","detail":"تقديره: أحق الناس أمك"}]', '["متفق عليه: البخاري (5971)، ومسلم (2548)."]', '{"en":"Abu Hurairah reported: A man came to Allah''s Messenger ﷺ and said: ''O Messenger of Allah! Who is most deserving of my fine companionship?'' He replied: ''Your mother.'' The man asked: ''Then who?'' He said: ''Your mother.'' The man asked: ''Then who?'' He said: ''Your mother.'' The man asked: ''Then who?'' He said: ''Then your father.''","ar":"تقديم حق الوالدة على الوالد لعظيم تضحيتها في الحمل والولادة والرضاع."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_18_2', 'riyad_ch18_birr', 'riyad_salihin', 1, 'وَعَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ».', 'حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو شخص یہ پسند کرتا ہو کہ اس کے رزق میں وسعت و برکت کی جائے اور اس کی عمر دراز کر دی جائے (اس کا نام باقی رہے)، تو اسے چاہیے کہ اپنے رشتہ داروں کے ساتھ صلہ رحمی اور حسن سلوک کرے۔''', 'صلہ رحمی سے انسان کے رزق میں خیر و برکت پیدا ہوتی ہے اور اس کی عمر میں نیک اعمال کی توفیق کے ذریعے درازی عطا فرمائی جاتی ہے۔ قطع رحمی نحوست کا سبب ہے۔', '[{"word":"فَلْيَصِلْ","role":"اللام لام الأمر والفعل مجزوم","sign":"سكون","detail":"مجزوم بلام الأمر والفاعل ضمير مستتر تقديره هو"},{"word":"رَحِمَهُ","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"وهو مضاف والهاء مضاف إليه"}]', '["متفق عليه: البخاري (5986)، ومسلم (2557)."]', '{"en":"Anas bin Malik reported that the Messenger of Allah ﷺ said: ''Whoever loves that his sustenance be expanded and his lifespan prolonged, let him maintain the ties of kinship.''","ar":"صلة الرحم سبب للبركة في العمر والرزق والتوفيق في الحياة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch19_lisan', 'riyad_salihin', 18, 'بَابُ حِفْظِ اللِّسَانِ عَنِ الغِيبَةِ وَالنَّمِيمَةِ', 'باب 19: حفظِ لسان، غیبت اور بدگوئی سے حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_19_1', 'riyad_ch19_lisan', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ فَلْيَقُلْ خَيْراً أَوْ لِيَصْمُتْ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہو، اسے چاہیے کہ یا تو بھلی اور اچھی بات کہے، ورنہ خاموش رہے!''', 'خاموشی میں سلامتی ہے۔ انسان کی اکثر خطائیں اور گناہ زبان کی بے احتیاطی سے سرزد ہوتے ہیں۔ اس لیے بلا ضرورت گفتگو سے بچنا اور صرف خیر کا کلمہ بولنا مومن کی علامت ہے۔', '[{"word":"فَلْيَقُلْ","role":"اللام لام الأمر والفعل مجزوم","sign":"سكون","detail":"جواب الشرط مقترن بالفاء"},{"word":"خَيْراً","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"وعلامة نصبه الفتحة الظاهرة"}]', '["متفق عليه: البخاري (6018)، ومسلم (47)."]', '{"en":"Abu Hurairah reported that the Prophet ﷺ said: ''Whoever believes in Allah and the Last Day, let him speak good or remain silent.''","ar":"قاعدة شرعية جامعة في ضبط المنطق وتطهير اللسان عن اللغو والآثام."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_19_2', 'riyad_ch19_lisan', 'riyad_salihin', 1, 'وَعَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنْ يَضْمَنْ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنْ لَهُ الجَنَّةَ».', 'حضرت سہل بن سعد رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو شخص مجھے اپنے دو جبڑوں کے درمیان کی چیز (زبان) اور اپنی دو ٹانگوں کے درمیان کی چیز (شرمگاہ) کی حفاظت کی ضمانت دے، میں اس کے لیے جنت کی ضمانت دیتا ہوں۔''', 'انسان کو ہلاکت میں ڈالنے والے دو بڑے دروازے زبان کی برائیاں (جھوٹ، غیبت، تہمت) اور شہوت کی بدکاریاں ہیں۔ جو ان دونوں کو شریعت کے تابع کر لے، نبی کریم ﷺ اس کے جنتی ہونے کے ضامن ہیں۔', '[{"word":"مَنْ","role":"اسم شرط جازم","sign":"مبني","detail":"يضمن فعل الشرط مجزوم بالسكون"},{"word":"أَضْمَنْ","role":"جواب الشرط مجزوم","sign":"سكون","detail":"والفاعل ضمير مستتر تقديره أنا"}]', '["أخرجه البخاري في صحيحه (6474)."]', '{"en":"Sahl bin Sa''d reported that Allah''s Messenger ﷺ said: ''Whoever guarantees for me what is between his jaws (his tongue) and what is between his legs (his private parts), I guarantee for him Paradise.''","ar":"حفظ اللسان والفرج هما أعظم أسباب النجاة ودخول الجنان."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch20_amr_bil_maruf', 'riyad_salihin', 19, 'بَابُ الأَمْرِ بِالمَعْرُوفِ وَالنَّهْيِ عَنِ المُنْكَرِ', 'باب 20: امر بالمعروف، نہی عن المنکر اور اصلاحِ معاشرہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_20_1', 'riyad_ch20_amr_bil_maruf', 'riyad_salihin', 0, 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ رَأَى مِنْكُمْ مُنْكَراً فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الإِيمَانِ».', 'حضرت ابوسعید خدری رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''تم میں سے جو شخص کوئی برائی دیکھے تو اسے چاہیے کہ اپنے ہاتھ کی طاقت سے بدل دے؛ اگر اس کی طاقت نہ ہو تو اپنی زبان سے روکے؛ اور اگر اس کی بھی طاقت نہ ہو تو کم از کم اپنے دل سے اسے برا جانے، اور یہ ایمان کا کمزور ترین درجہ ہے۔''', 'معاشرے کو بگاڑ سے بچانے کے لیے برائی کے خلاف کھڑا ہونا ضروری ہے۔ حکمران ہاتھ سے، علماء زبان و قلم سے اور عوام دل سے برائی کو ناپسند کر کے اپنا دینی فریضہ نبھائیں۔', '[{"word":"مُنْكَراً","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"لفعل رأى"},{"word":"فَلْيُغَيِّرْهُ","role":"اللام لام الأمر والفعل مجزوم","sign":"سكون","detail":"والهاء ضمير متصل مفعول به"}]', '["أخرجه مسلم في صحيحه (49)."]', '{"en":"Abu Sa''id Al-Khudri reported: I heard Allah''s Messenger ﷺ saying: ''Whoever among you sees an evil, let him change it with his hand; if he cannot, then with his tongue; if he cannot, then with his heart, and that is the weakest of faith.''","ar":"درجات إنكار المنكر بحسب القدرة والمصلحة الشرعية."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_20_2', 'riyad_ch20_amr_bil_maruf', 'riyad_salihin', 1, 'وَعَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ ﷺ قَالَ: «مَثَلُ القَائِمِ عَلَى حُدُودِ اللَّهِ وَالوَاقِعِ فِيهَا كَمَثَلِ قَوْمٍ اسْتَهَمُوا عَلَى سَفِينَةٍ، فَأَصَابَ بَعْضُهُمْ أَعْلَاهَا وَبَعْضُهُمْ أَسْفَلَهَا... فَقَالَ الَّذِينَ فِي أَسْفَلِهَا: لَوْ أَنَّا خَرَقْنَا فِي نَصِيبِنَا خَرْقاً وَلَمْ نُؤْذِ مَنْ فَوْقَنَا! فَإِنْ يَتْرُكُوهُمْ وَمَا أَرَادُوا هَلَكُوا جَمِيعاً، وَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ نَجَوْا وَنَجَوْا جَمِيعاً».', 'حضرت نعمان بن بشیر رضی اللہ عنہما سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ''اللہ کے حدود و احکام کی پابندی کرنے والے اور ان کو توڑنے والے کی مثال ان مسافروں جیسی ہے جنہوں نے کشتی میں سوار ہونے کے لیے قرعہ ڈالا، تو بعض کو اوپری منزل ملی اور بعض کو نچلی منزل... نچلی منزل والوں نے سوچا: ہم نیچے کے حصے میں سوراخ کر لیں تاکہ اوپر والوں کو پانی لینے کے لیے تکلیف نہ دیں! اب اگر اوپر والے انہیں اس ارادے پر چھوڑ دیں گے تو پوری کشتی والے ڈوب کر ہلاک ہو جائیں گے؛ اور اگر وہ ان کا ہاتھ پکڑ لیں گے تو وہ بھی بچ جائیں گے اور سارے کے سارے محفوظ رہیں گے!''', 'یہ نبی کریم ﷺ کی دی ہوئی شاندار تمثیل ہے جو بتاتی ہے کہ معاشرہ ایک کشتی ہے؛ اگر گناہ گاروں کو کھلی چھوٹ دے دی جائے تو عذابِ الٰہی پورے معاشرے کو اپنی لپیٹ میں لے لیتا ہے۔', '[{"word":"القَائِمِ","role":"مضاف إليه مجرور","sign":"كسرة لفظاً","detail":"مثل مبتدأ والقائم مضاف إليه"},{"word":"جَمِيعاً","role":"حال منصوب","sign":"فتحة لفظاً","detail":"حال من واو الجماعة في هلكوا"}]', '["أخرجه البخاري في صحيحه (2493)."]', '{"en":"An-Nu''man bin Bashir reported that the Prophet ﷺ said: ''The example of the person abiding by Allah''s bounds and the one falling into them is like people who drew lots for places on a ship... If they prevent them from boring a hole, all will be saved.''","ar":"مثل بليغ في التضامن الاجتماعي وأهمية الأمر بالمعروف لحماية المجتمع من الغرق."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch21_qiyam_layl', 'riyad_salihin', 20, 'بَابُ فَضْلِ قِيَامِ اللَّيْلِ وَالتَّهَجُّدِ', 'باب 21: قیام اللیل، تہجد اور مناجاتِ سحر کی برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_21_1', 'riyad_ch21_qiyam_layl', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ المُحَرَّمُ، وَأَفْضَلُ الصَّلَاةِ بَعْدَ الفَرِيضَةِ صَلَاةُ اللَّيْلِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''رمضان المبارک کے بعد سب سے افضل روزے اللہ کے مہینے محرم کے ہیں، اور فرض نمازوں کے بعد سب سے افضل نماز رات کی نماز (تہجد) ہے''۔', 'رات کی تاریکی اور تنہائی میں جب سب سو رہے ہوں، سجدہ ریز ہو کر مناجات کرنا بندۂ مومن کے قلب کو انوار سے بھر دیتا ہے۔ صلحاء و اولیاء کا سب سے بڑا ہتھیار نمازِ تہجد ہے۔', '[{"word":"أَفْضَلُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والصيام مضاف إليه"},{"word":"صَلَاةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"في الجملة الثانية"}]', '["أخرجه مسلم في صحيحه (1163)."]', '{"en":"Abu Hurairah reported that the Messenger of Allah ﷺ said: ''The best fasting after Ramadan is the month of Allah, Al-Muharram; and the best prayer after the obligatory prayer is the night prayer (Tahajjud).''","ar":"فضل قيام الليل وقربه من الله تعالى لما فيه من الإخلاص والبعد عن الرياء."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_21_2', 'riyad_ch21_qiyam_layl', 'riyad_salihin', 1, 'وَعَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «أَيُّهَا النَّاسُ، أَفْشُوا السَّلَامَ، وَأَطْعِمُوا الطَّعَامَ، وَصَلُّوا بِاللَّيْلِ وَالنَّاسُ نِيَامٌ، تَدْخُلُوا الجَنَّةَ بِسَلَامٍ».', 'حضرت عبداللہ بن سلام رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے مدینہ منورہ تشریف لاتے ہی پہلا خطبہ دیتے ہوئے ارشاد فرمایا: ''اے لوگو! سلام کو عام کرو، (محتاجوں کو) کھانا کھلاؤ، اور رات کو جب لوگ سو رہے ہوں نماز پڑھو، تم سلامتی کے ساتھ جنت میں داخل ہو جاؤ گے!''', 'مدینہ طیبہ کی نئی اسلامی ریاست کی بنیاد ان چار ستونوں پر رکھی گئی: محبت کی اشاعت (سلام)، غریب پروری (اطعام)، رات کا تعلق باللہ (تہجد)، جس کا حتمی نتیجہ دائمی امن و جنت ہے۔', '[{"word":"أَيُّهَا","role":"منادى مبني على الضم","sign":"ضم","detail":"والهاء للتنبيه والناس بدل أو نعت"},{"word":"تَدْخُلُوا","role":"جواب الطلب مجزوم","sign":"حذف النون","detail":"علامة جزمه حذف النون"}]', '["أخرجه الترمذي (2485) وقال: حديث حسن صحيح."]', '{"en":"''Abdullah bin Salam reported that the Prophet ﷺ said: ''O people! Spread peace, feed the hungry, and pray at night while people are sleeping, and you will enter Paradise in peace.''","ar":"أول وصية نبوية في المدينة المنورة جمعت بين الإحسان إلى الخلق والتقرب إلى الخالق."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch22_adab_taam', 'riyad_salihin', 21, 'بَابُ آدَابِ الطَّعَامِ وَالشَّرَابِ وَالضِّيَافَةِ', 'باب 22: کھانے پینے اور مہمان نوازی کے مسنون آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_22_1', 'riyad_ch22_adab_taam', 'riyad_salihin', 0, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْتُ غُلَاماً فِي حِجْرِ رَسُولِ اللَّهِ ﷺ، وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي رَسُولُ اللَّهِ ﷺ: «يَا غُلَامُ، سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ».', 'حضرت عمر بن ابی سلمہ رضی اللہ عنہما نے فرمایا: میں رسول اللہ ﷺ کی زیرِ پرورش بچہ تھا اور کھانا کھاتے وقت میرا ہاتھ برتن میں چاروں طرف گھوما کرتا تھا، تو رسول اللہ ﷺ نے شفقت سے مجھ سے فرمایا: ''اے بچے! اللہ کا نام لو (بسم اللہ پڑھو)، اپنے دائیں ہاتھ سے کھاؤ، اور اپنے سامنے سے کھاؤ!''', 'کھانے پینے کے اس نبوی دستور میں برکت، طہارت اور شائستگی ہے۔ بسم اللہ سے برکت آتی ہے، دائیں ہاتھ سے سنت ادا ہوتی ہے اور سامنے سے کھانا ادبِ طعام ہے۔', '[{"word":"سَمِّ","role":"فعل أمر مبني على حذف حرف العلة","sign":"حذف الياء","detail":"والفاعل مستتر تقديره أنت"},{"word":"بِيَمِينِكَ","role":"جار ومجرور","sign":"كسرة لفظاً","detail":"متعلق بفعل كُل"}]', '["متفق عليه: البخاري (5376)، ومسلم (2022)."]', '{"en":"''Umar bin Abi Salamah reported: I was a boy under the care of Allah''s Messenger ﷺ and my hand used to wander around the dish. He said to me: ''O boy! Mention Allah''s Name, eat with your right hand, and eat from what is directly in front of you.''","ar":"تعليم النبي ﷺ للأطفال آداب الأكل بكل رفق ومحبة وتوجيه سديد."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_22_2', 'riyad_ch22_adab_taam', 'riyad_salihin', 1, 'وَعَنْ مِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَا مَلَأَ آدَمِيٌّ وِعَاءً شَرّاً مِنْ بَطْنٍ، بِحَسْبِ ابْنِ آدَمَ أُكُلَاتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا مَحَالَةَ، فَثُلُثٌ لِطَعَامِهِ، وَثُلُثٌ لِشَرَابِهِ، وَثُلُثٌ لِنَفَسِهِ».', 'حضرت مقدام بن معدیکرب رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''انسان نے پیٹ سے برا کوئی برتن نہیں بھرا! ابنِ آدم کے لیے تو چند لقمے ہی کافی ہیں جو اس کی پیٹھ سیدھی رکھ سکیں؛ اگر زیادہ ہی کھانا ضروری ہو تو ایک تہائی پیٹ کھانے کے لیے، ایک تہائی پانی کے لیے، اور ایک تہائی سانس لینے کے لیے خالی رکھے!''', 'تمام بیماریوں کی جڑ پیٹ کا ضرورت سے زیادہ بھرنا ہے۔ نبی کریم ﷺ نے طبِ نبوی کا یہ سنہرا قانون عطا فرمایا کہ اعتدال اور بھوک رکھ کر کھانا انسان کو صحت مند اور عبادات کے لیے چست رکھتا ہے۔', '[{"word":"شَرّاً","role":"نعت منصوب لوعاء","sign":"فتحة لفظاً","detail":"أو تمييز منصوب"},{"word":"ثُلُثٌ","role":"مبتدأ مؤخر أو خبر لمبتدأ محذوف","sign":"ضمة لفظاً","detail":"تقديره: فالواجب ثلث لطعامه"}]', '["أخرجه الترمذي (2380) وقال: حديث حسن صحيح."]', '{"en":"Al-Miqdam bin Ma''dikarib reported: I heard the Messenger of Allah ﷺ saying: ''A human being fills no vessel worse than his stomach. A few morsels to keep his back straight are sufficient for him. But if he must, then one third for his food, one third for his drink, and one third for his breath.''","ar":"قاعدة نبوية عظيمة في حفظ الصحة والاعتدال في المأكل والمشرب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch23_salam', 'riyad_salihin', 22, 'بَابُ آدَابِ السَّلَامِ وَالاسْتِئْذَانِ وَالمُصَافَحَةِ', 'باب 23: سلام کی اشاعت، مصافحہ اور اجازت طلب کرنے کے آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_23_1', 'riyad_ch23_salam', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا تَدْخُلُونَ الجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تم جنت میں داخل نہیں ہو سکتے جب تک کہ کامل مومن نہ بن جاؤ، اور تم کامل مومن نہیں بن سکتے جب تک کہ آپس میں ایک دوسرے سے محبت نہ کرنے لگو؛ کیا میں تمہیں ایسا عمل نہ بتاؤں جس کو کرنے سے تمہارے درمیان باہمی محبت پیدا ہو جائے؟ آپس میں کثرت سے سلام کو عام کرو!''', 'سلام صرف ایک رسمی کلمہ نہیں بلکہ سلامتی اور رحمت کی دعا ہے۔ ہر مسلمان کو خواہ جان پہچان ہو یا نہ ہو سلام کرنے سے دلوں سے کینہ، بغض اور تکبر کا خاتمہ ہوتا ہے اور ایمانی اخوت پروان چڑھتی ہے۔', '[{"word":"تَدْخُلُونَ","role":"فعل مضارع مرفوع بثبوت النون","sign":"ثبوت النون","detail":"والواو فاعل ولا نافية"},{"word":"أَفْشُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"}]', '["أخرجه مسلم في صحيحه (54)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I not guide you to something which, if you do it, will make you love one another? Spread peace among yourselves.''","ar":"إفشاء السلام مفتاح المحبة والمودة وكمال الإيمان المفضي إلى الجنة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_23_2', 'riyad_ch23_salam', 'riyad_salihin', 1, 'وَعَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَا مِنْ مُسْلِمَيْنِ يَلْتَقِيَانِ فَيَتَصَافَحَانِ إِلَّا غُفِرَ لَهُمَا قَبْلَ أَنْ يَفْتَرِقَا».', 'حضرت براء بن عازب رضی اللہ عنہما نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جب بھی دو مسلمان آپس میں ملتے ہیں اور گرم جوشی سے مصافحہ کرتے ہیں، تو ان کے جدا ہونے سے پہلے پہلے اللہ تعالیٰ ان دونوں کے گناہوں کی مغفرت فرما دیتا ہے!''', 'مصافحہ کرنے سے باہمی دوری اور کھچاؤ ختم ہو جاتا ہے۔ جب دونوں ہاتھ ملتے ہیں تو گناہ ایسے جھڑتے ہیں جیسے درخت سے خشک پتے جھڑتے ہیں، یہ اسلام کے خوبصورت معاشرتی آداب کا عکس ہے۔', '[{"word":"مَا","role":"حرف نفي","sign":"مبني","detail":"من حرف جر زائد ومسلمين مجرور لفظاً مرفوع محلاً مبتدأ"},{"word":"إِلَّا","role":"أداة حصر","sign":"مبني","detail":"وغفر لهما جملة فعلية خبر المبتدأ"}]', '["أخرجه أبو داود (5212)، والترمذي (2727) وقال: حديث حسن."]', '{"en":"Al-Bara'' bin ''Azib reported that Allah''s Messenger ﷺ said: ''No two Muslims meet and shake hands except that their sins are forgiven before they part.''","ar":"فضل المصافحة باليد وتطهيرها للذنوب وإزالة الأحقاد بين المسلمين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch24_iyadah', 'riyad_salihin', 23, 'بَابُ عِيَادَةِ المَرِيضِ وَحُقُوقِ المُسْلِمِ', 'باب 24: عیادتِ مریض، حقوقِ مسلم اور جنازے کے احکام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_24_1', 'riyad_ch24_iyadah', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «حَقُّ المُسْلِمِ عَلَى المُسْلِمِ سِتٌّ»، قِيلَ: مَا هُنَّ يَا رَسُولَ اللَّهِ؟ قَالَ: «إِذَا لَقِيتَهُ فَسَلِّمْ عَلَيْهِ، وَإِذَا دَعَاكَ فَأَجِبْهُ، وَإِذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ، وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ فَشَمِّتْهُ، وَإِذَا مَرِضَ فَعُدْهُ، وَإِذَا مَاتَ فَاتَّبِعْهُ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''ایک مسلمان کے دوسرے مسلمان پر چھ حقوق ہیں''۔ پوچھا گیا: یا رسول اللہ! وہ کون سے ہیں؟ آپ ﷺ نے فرمایا: ''جب تم اس سے ملو تو اسے سلام کرو؛ جب وہ تمہاری دعوت کرے تو اسے قبول کرو؛ جب وہ تم سے مخلصانہ مشورہ مانگے تو اسے نیک مشورہ دو؛ جب وہ چھینکے اور الحمد للہ کہے تو اس کے جواب میں یرحمک اللہ کہو؛ جب وہ بیمار ہو جائے تو اس کی عیادت کرو؛ اور جب وہ وفات پا جائے تو اس کے جنازے کے ساتھ جاؤ''۔', 'یہ چھ حقوق اسلامی معاشرے کے تانے بانے کو مضبوط کرتے ہیں۔ خوشی میں شرکت، دکھ میں ہمدردی، بیماری میں تسلی اور موت کے بعد دعائے مغفرت باہمی وحدت کو جنم دیتی ہے۔', '[{"word":"حَقُّ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والمسلم مضاف إليه"},{"word":"سِتٌّ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"والجمل بعده تفصيل للمجمل"}]', '["أخرجه مسلم في صحيحه (2162)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''The rights of a Muslim upon a Muslim are six: When you meet him, greet him; when he invites you, accept; when he seeks your advice, counsel him; when he sneezes and praises Allah, invoke mercy on him; when he is sick, visit him; and when he dies, follow his funeral.''","ar":"الحقوق الستة المشتركة التي تبني المجتمع الإسلامي المترابط."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_24_2', 'riyad_ch24_iyadah', 'riyad_salihin', 1, 'وَعَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ المُسْلِمَ إِذَا عَادَ أَخَاهُ المُسْلِمَ لَمْ يَزَلْ فِي خُرْفَةِ الجَنَّةِ حَتَّى يَرْجِعَ»، قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا خُرْفَةُ الجَنَّةِ؟ قَالَ: «جَنَاهَا».', 'حضرت ثوبان رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''بے شک مسلمان جب اپنے کسی مسلمان بھائی کی عیادت کے لیے جاتا ہے، تو وہ واپس لوٹنے تک مسلسل جنت کے پھلوں کے باغ میں رہتا ہے!'' عرض کیا گیا: یا رسول اللہ! خرفۃ الجنۃ سے کیا مراد ہے؟ آپ ﷺ نے فرمایا: ''جنت کے چنے ہوئے تازہ اور لذیذ پھل!''', 'بیمار پرسی کے لمحات رحمت کے سائے میں گزرتے ہیں۔ جب تک بندہ بیمار کی دلجوئی کرتا ہے، اللہ کی رحمتیں اور جنت کی برکات اس کا احاطہ کیے رکھتی ہیں۔', '[{"word":"لَمْ يَزَلْ","role":"فعل مضارع ناقص مجزوم","sign":"سكون","detail":"واسمها ضمير مستتر تقديره هو"},{"word":"فِي خُرْفَةِ","role":"شبه جملة خبر لم يزل","sign":"كسرة لفظاً","detail":"في محل نصب خبر لم يزل"}]', '["أخرجه مسلم في صحيحه (2568)."]', '{"en":"Thawban reported that the Prophet ﷺ said: ''Verily, when a Muslim visits his sick Muslim brother, he remains in the fruit gardens of Paradise until he returns.'' It was asked: ''What is Khurfat al-Jannah?'' He said: ''Its harvested fruits.''","ar":"ثواب عيادة المريض وتفقد أحوال الضعفاء وإدخال السرور على قلوبهم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch25_raja_khatm', 'riyad_salihin', 24, 'بَابُ الرَّجَاءِ وَحُسْنِ الظَّنِّ بِاللَّهِ وَسَعَةِ الرَّحْمَةِ (خَتْمُ الكِتَابِ)', 'باب 25: رجاء، اللہ سے امید، حسنِ ظن اور ختمِ کتاب کی دعائیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_25_1', 'riyad_ch25_raja_khatm', 'riyad_salihin', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «قَالَ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ، وَإِنْ تَقَرَّبَ إِلَيَّ بِشِبْرٍ تَقَرَّبْتُ إِلَيْهِ ذِرَاعاً، وَإِنْ تَقَرَّبَ إِلَيَّ ذِرَاعاً تَقَرَّبْتُ إِلَيْهِ بَاعاً، وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''اللہ تعالیٰ کا ارشاد ہے: میں اپنے بندے کے ساتھ اس کے گمان کے مطابق معاملہ فرماتا ہوں، اور جب وہ مجھے یاد کرتا ہے تو میں اس کے ساتھ ہوتا ہوں۔ پس اگر وہ مجھے اپنے دل میں یاد کرے تو میں اسے اپنی بارگاہ میں یاد فرماتا ہوں، اور اگر وہ کسی مجلس اور مجمع میں میرا ذکر کرے تو میں اس سے کہیں زیادہ معزز اور برگزیدہ مجمع (فرشتوں کی جماعت) میں اس کا تذکرہ کرتا ہوں۔ اور اگر وہ میری طرف ایک بالشت قریب آتا ہے تو میں اس کی طرف ایک ہاتھ قریب ہوتا ہوں، اور اگر وہ میری طرف ایک ہاتھ قریب آئے تو میں اس کی طرف دو کھلے ہاتھوں کے فاصلے کے برابر قریب ہوتا ہوں، اور اگر وہ میری طرف چل کر آئے تو میں اس کی طرف دوڑ کر آتا ہوں!''', 'امام نووی رحمہ اللہ نے اپنی مبارک کتاب کا اختتام اللہ تعالیٰ کی بے پایاں رحمت، وسعتِ مغفرت اور حسنِ ظن کے ابواب پر کیا ہے۔ اللہ اپنے بندے کے ذرا سے رجوع کو بھی شرفِ قبولیت بخشتا ہے۔', '[{"word":"أَنَا","role":"ضمير منفصل مبتدأ","sign":"مبني","detail":"في محل رفع مبتدأ"},{"word":"عِنْدَ","role":"ظرف مكان خبر المبتدأ","sign":"فتحة لفظاً","detail":"متعلق بمحذوف خبر وهو مضاف وظن مضاف إليه"}]', '["متفق عليه: البخاري (7405)، ومسلم (2675)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Allah Almighty says: I am as My servant thinks of Me, and I am with him when he mentions Me. If he remembers Me in his heart, I remember him in Myself... and if he comes to Me walking, I come to him running.''","ar":"حديث قدسي جليل يفيض بالرجاء والمحبة الإلهية لمن أقبل على ربه مخلصاً."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_25_2', 'riyad_ch25_raja_khatm', 'riyad_salihin', 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَمَّا قَضَى اللَّهُ الخَلْقَ كَتَبَ فِي كِتَابِهِ فَهُوَ عِنْدَهُ فَوْقَ العَرْشِ: إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي»؛ وَفِي رِوَايَةٍ: «سَبَقَتْ غَضَبِي». وَالحَمْدُ لِلَّهِ رَبِّ العَالَمِينَ عَلَى التَّمَامِ، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَصَحْبِهِ أَجْمَعِينَ.', 'حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جب اللہ تعالیٰ نے کائنات کو پیدا فرمایا تو اپنے پاس عرشِ معلیٰ پر رکھی ہوئی کتاب میں تحریر فرما دیا: بے شک میری رحمت میرے غضب پر غالب آ گئی ہے؛ (اور دوسری روایت میں ہے: میری رحمت میرے غضب سے سبقت لے گئی ہے)''۔ اور تمام تعریفیں اللہ رب العالمین ہی کے لیے ہیں جس نے اس کتاب کے مطالعے کی تکمیل کی توفیق بخشی، اور درود و سلام ہو ہمارے آقا و مولیٰ محمد ﷺ اور ان کی تمام آل اور اصحاب پر۔', 'یہ مبارک کتاب کا آخری صفحہ ہے! امام محیی الدین نووی رحمہ اللہ نے پوری کتاب میں پہلے انسان کے باطن کی اصلاح (اخلاص، توبہ، تقویٰ)، پھر ظاہری معاملات (آداب، حقوق، حسنِ خلق) اور آخر میں وسعتِ رحمتِ الٰہی پر خاتمہ فرمایا، تاکہ قاری خوف اور امید کے حسین توازن کے ساتھ دنیا سے رخصت ہو۔', '[{"word":"إِنَّ","role":"حرف توكيد ونصب","sign":"مبني","detail":"رحمتي اسمها منصوب بفتحة مقدرة"},{"word":"غَلَبَتْ","role":"فعل ماض والتاء للتأنيث","sign":"مبني على الفتح","detail":"والجملة الفعلية في محل رفع خبر إن"}]', '["متفق عليه: البخاري (3194)، ومسلم (2751)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''When Allah decreed the creation, He wrote in His Book which is with Him above the Throne: Verily, My mercy prevails over My wrath.'' All praise is due to Allah for the completion of this blessed book.","ar":"ختام كتاب رياض الصالحين بتقرير غلبة رحمة أرحم الراحمين ليكون العبد في خاتمته مقبلاً على الله راجياً لفضله."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_shamail_tirmidhi', 'الشَّمَائِلُ المُحَمَّدِيَّةُ وَالخَصَائِصُ المُصْطَفَوِيَّةُ', 'الإِمَامُ الحَافِظُ أَبُو عِيسَى مُحَمَّدُ بْنُ عِيسَى التِّرْمِذِيُّ (ت: 279ھ)', 'kharji_kitab', 'seerah', 'سیرت، سراپا اقدس و عاداتِ طیبہ ﷺ', 'کتبِ مطالعہ و محبتِ رسول ﷺ (جملہ درجات)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'حضور سید کونین ﷺ کے جمال، سراپا، لباس، گفتگو، حلم، عبادت اور عاداتِ طیبہ پر محدثین کی سب سے بے نظیر اور مستند تصنیف۔', 5, 5);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shamail_ch1_khalq', 'kharji_shamail_tirmidhi', 0, 'بَابُ مَا جَاءَ فِي خَلْقِ رَسُولِ اللَّهِ ﷺ', 'باب 1: رسول اللہ ﷺ کے حسن و جمال اور مبارک جسمانی صفات کا بیان');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shamail_seg_1_1', 'shamail_ch1_khalq', 'kharji_shamail_tirmidhi', 0, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَهُ يَقُولُ: «كَانَ رَسُولُ اللَّهِ ﷺ لَيْسَ بِالطَّوِيلِ البَائِنِ، وَلَا بِالقَصِيرِ، وَلَا بِالأَبْيَضِ الأَمْهَقِ، وَلَا بِالآدَمِ، وَلَا بِالجَعْدِ القَطَطِ، وَلَا بِالسَّبْطِ، بَعَثَهُ اللَّهُ عَلَى رَأْسِ أَرْبَعِينَ سَنَةً، فَأَقَامَ بِمَكَّةَ عَشْرَ سِنِينَ، وَبِالمَدِينَةِ عَشْرَ سِنِينَ، وَتَوَفَّاهُ اللَّهُ عَلَى رَأْسِ سِتِّينَ سَنَةً، وَلَيْسَ فِي رَأْسِهِ وَلِحْيَتِهِ عِشْرُونَ شَعْرَةً بَيْضَاءَ».', 'حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: ''رسول اللہ ﷺ قد میں نہ بہت زیادہ لمبے تھے اور نہ پستہ قد، بلکہ درمیانہ قد و قامت کے تھے۔ آپ کا رنگ نہ تو بالکل چونے کی طرح سفید تھا اور نہ گندمی، بلکہ سرخی مائل سفید چمکدار تھا۔ آپ کے بال نہ بالکل گھنگھریالے تھے اور نہ بالکل سیدھے لٹکے ہوئے، بلکہ ہلکے سے خم دار تھے۔ اللہ تعالیٰ نے آپ کو چالیس سال کی عمر میں مبعوث فرمایا، آپ دس سال مکہ مکرمہ میں اور دس سال مدینہ منورہ میں مقیم رہے، اور ساٹھ سال کی عمر مبارک میں وفات پائی؛ اس وقت آپ کے سر اور ریش مبارک میں بیس بال بھی سفید نہیں تھے۔''', 'نبی کریم ﷺ حسن و جمال کا ایسا شاہکار تھے کہ چودھویں کے چاند کی مانند آپ کا چہرۂ اقدس چمکتا تھا۔ اعتدال اور توازن آپ کی تمام جسمانی اور باطنی صفات کا خاصہ تھا۔', '[{"word":"كَانَ","role":"فعل ماض ناقص","sign":"مبني","detail":"يرفع الاسم وينصب الخبر"},{"word":"رَسُولُ","role":"اسم كان مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف ولفظ الجلالة مضاف إليه"},{"word":"بِالطَّوِيلِ","role":"الباء زائدة وخبر كان","sign":"كسرة لفظاً منصوب محلاً","detail":"مجرور لفظاً منصوب محلاً خبر ليس"}]', '["متفق عليه: البخاري (3547)، ومسلم (2347)، والترمذي في الشمائل (1)."]', '{"en":"Anas bin Malik reported that Allah''s Messenger ﷺ was neither excessively tall nor short, nor purely chalky white nor dark-skinned, and his hair was neither very curly nor completely straight...","ar":"وصف دقيق لخلقة النبي المصطفى ﷺ وأكرم خلق الله صورة وسيرة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shamail_ch2_khatam', 'kharji_shamail_tirmidhi', 1, 'بَابُ مَا جَاءَ فِي خَاتَمِ النُّبُوَّةِ', 'باب 2: پشتِ مبارک پر مہرِ نبوت کا بیان اور اس کے اوصاف');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shamail_seg_2_1', 'shamail_ch2_khatam', 'kharji_shamail_tirmidhi', 0, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذَهَبَتْ بِي خَالَتِي إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَ أُخْتِي وَجِعٌ، فَمَسَحَ رَأْسِي وَدَعَا لِي بِالبَرَكَةِ، ثُمَّ تَوَضَّأَ فَشَرِبْتُ مِنْ وَضُوئِهِ، ثُمَّ قُمْتُ خَلْفَ ظَهْرِهِ فَنَظَرْتُ إِلَى خَاتَمِ النُّبُوَّةِ بَيْنَ كَتِفَيْهِ مِثْلَ زِرِّ الحَجَلَةِ.', 'حضرت سائب بن یزید رضی اللہ عنہ فرماتے ہیں کہ میری خالہ مجھے رسول اللہ ﷺ کی خدمت میں لے گئیں اور عرض کیا: یا رسول اللہ! میرے بھانجے کو پاؤں میں تکلیف ہے۔ آپ ﷺ نے ازراہِ شفقت میرے سر پر اپنا مبارک ہاتھ پھیرا اور میرے لیے برکت کی دعا فرمائی، پھر آپ نے وضو فرمایا تو میں نے آپ کے وضو کا بچا ہوا پانی پیا، پھر میں آپ کے پیچھے کھڑا ہوا تو میں نے آپ کے دونوں مبارک کندھوں کے درمیان مہرِ نبوت کو کبوتر کے انڈے کی مانند دیکھا۔', 'مہرِ نبوت رسول اللہ ﷺ کے دونوں کندھوں کے درمیان ابھرا ہوا ایک گوشت کا نشان تھا جس پر بال تھے، جو تورات اور انجیل کی پیشین گوئیوں کے مطابق آخری نبی ہونے کی ظاہری علامت تھی۔', '[{"word":"ذَهَبَتْ","role":"فعل ماض والتاء للتأنيث","sign":"مبني","detail":"وخالتي فاعل مرفوع بضمة مقدرة"}]', '["أخرجه البخاري (190)، ومسلم (2345)، والترمذي في الشمائل (16)."]', '{"en":"As-Sa''ib bin Yazid said: My maternal aunt took me to the Messenger of Allah ﷺ... He wiped my head and prayed for blessings upon me. Then I stood behind his back and looked at the Seal of Prophethood between his shoulders...","ar":"إثبات خاتم النبوة الحسية بين كتفي الحبيب المصطفى ﷺ كما ورد في البشارات السابقة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shamail_ch3_libas', 'kharji_shamail_tirmidhi', 2, 'بَابُ مَا جَاءَ فِي لِبَاسِ رَسُولِ اللَّهِ ﷺ', 'باب 3: رسول اللہ ﷺ کے مبارک لباس، کرتہ اور چادر کے آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shamail_seg_3_1', 'shamail_ch3_libas', 'kharji_shamail_tirmidhi', 0, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: «كَانَ أَحَبَّ الثِّيَابِ إِلَى رَسُولِ اللَّهِ ﷺ القَمِيصُ». وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «عَلَيْكُمْ بِالبَيَاضِ مِنَ الثِّيَابِ، لِيَلْبَسْهَا أَحْيَاؤُكُمْ، وَكَفِّنُوا فِيهَا مَوْتَاكُمْ، فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ».', 'ام المؤمنین حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں: ''رسول اللہ ﷺ کو لباس میں سب سے زیادہ پسندیدہ لباس قمیص (کرتہ) تھا۔'' اور حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''سفید لباس کو اپنے اوپر لازم کرو، تمہارے زندہ لوگ سفید کپڑے پہنیں اور اپنے مردوں کو بھی سفید کپڑوں میں کفن دیا کرو، کیونکہ سفید کپڑے تمہارے بہترین لباس ہیں۔''', 'سفید لباس طہارت، پاکیزگی اور سادگی کی علامت ہے۔ نبی کریم ﷺ تکبر اور اسراف والے لباس کو سخت ناپسند فرماتے تھے اور ہمیشہ ساتر اور سادہ لباس پسند فرماتے تھے۔', '[{"word":"أَحَبَّ","role":"خبر كان مقدم منصوب","sign":"فتحة لفظاً","detail":"والقميص اسم كان مؤخر مرفوع"}]', '["أخرجه الترمذي في الشمائل (54، 58)، وأبو داود (4061)."]', '{"en":"Umm Salamah reported: The garment most beloved to Allah''s Messenger ﷺ was the Qamis (shirt). And Ibn Abbas reported that the Prophet recommended wearing white clothes for purity.","ar":"استحباب لبس القميص والبياض لما فيهما من الستر والنظافة والوقار."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shamail_ch4_eish', 'kharji_shamail_tirmidhi', 3, 'بَابُ مَا جَاءَ فِي صِفَةِ خُبْزِ رَسُولِ اللَّهِ ﷺ وَعَيْشِهِ', 'باب 4: نبی کریم ﷺ کے طعام، سادگی اور زاہدانہ طرزِ زندگی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shamail_seg_4_1', 'shamail_ch4_eish', 'kharji_shamail_tirmidhi', 0, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: «مَا شَبِعَ آلُ مُحَمَّدٍ ﷺ مِنْ خُبْزِ الشَّعِيرِ يَوْمَيْنِ مُتَتَابِعَيْنِ حَتَّى قُبِضَ رَسُولُ اللَّهِ ﷺ». وَفِي رِوَايَةٍ: «كَانَ يَمُرُّ بِنَا الهِلَالُ ثُمَّ الهِلَالُ ثُمَّ الهِلَالُ، ثَلَاثَةُ أَهِلَّةٍ فِي شَهْرَيْنِ، وَمَا أُوقِدَ فِي أَبْيَاتِ رَسُولِ اللَّهِ ﷺ نَارٌ، قِيلَ: مَا كَانَ يُعِيشُكُمْ؟ قَالَتْ: الأَسْوَدَانِ: التَّمْرُ وَالمَاءُ».', 'ام المؤمنین حضرت عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں: ''آلِ محمد ﷺ نے رسول اللہ ﷺ کے وصال تک کبھی دو دن مسلسل جو کی روٹی سے پیٹ نہیں بھرا۔'' اور دوسری روایت میں فرماتی ہیں: ''ہمارے ہاں ایک چاند نظر آتا، پھر دوسرا، پھر تیسرا؛ یعنی دو مہینوں میں تین چاند گزر جاتے اور رسول اللہ ﷺ کے گھروں میں چولہا نہیں جلتا تھا! پوچھا گیا: آپ لوگوں کی زندگی کا گزارا کس چیز پر تھا؟ فرمایا: دو سیاہ چیزوں پر: یعنی کھجور اور پانی پر!''', 'سید الکونین ﷺ جن کے اشارے پر پہاڑ سونے کے بن سکتے تھے، انہوں نے فقرِ اختیاری کو پسند فرمایا تاکہ امت کا غریب ترین انسان بھی آپ کی زندگی کو دیکھ کر تسلی پا سکے۔', '[{"word":"مَا","role":"نافية","sign":"مبني","detail":"شبع فعل ماض وآل فاعل مرفوع"},{"word":"يَوْمَيْنِ","role":"ظرف زمان منصوب","sign":"ياء المثنى","detail":"وعلامة نصبه الياء لأنه مثنى"}]', '["متفق عليه: البخاري (5416)، ومسلم (2970)، والترمذي في الشمائل (138)."]', '{"en":"''Aishah reported: The family of Muhammad ﷺ never ate their fill of barley bread for two consecutive days until he passed away... Two months would pass with three crescent moons without a fire being lit in the Prophet''s homes, subsisting on dates and water.","ar":"بيان زهد النبي الأكرم وصبر أزواجه الطاهرات على شظف العيش ابتغاء الدار الآخرة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shamail_ch5_ibadah', 'kharji_shamail_tirmidhi', 4, 'بَابُ مَا جَاءَ فِي عِبَادَةِ رَسُولِ اللَّهِ ﷺ وَتَهَجُّدِهِ', 'باب 5: رسول اللہ ﷺ کی شب بیداری، طویل رکوع و سجود اور خشوع');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shamail_seg_5_1', 'shamail_ch5_ibadah', 'kharji_shamail_tirmidhi', 0, 'عَنِ المُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللَّهِ ﷺ حَتَّى انْتَفَخَتْ قَدَمَاهُ، فَقِيلَ لَهُ: أَتَتَكَلَّفُ هَذَا وَقَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ؟ قَالَ: «أَفَلَا أَكُونُ عَبْداً شَكُوراً».', 'حضرت مغیرہ بن شعبہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے رات کو اتنی لمبی نماز پڑھی کہ آپ کے دونوں پاؤں مبارک متورم ہو گئے (سوج گئے)۔ آپ ﷺ سے عرض کیا گیا: آپ اتنی مشقت کیوں اٹھاتے ہیں جبکہ اللہ تعالیٰ نے آپ کے اگلے پچھلے تمام گناہوں کی مغفرت فرما دی ہے؟ آپ ﷺ نے ارشاد فرمایا: ''تو کیا میں اللہ کا شکر گزار بندہ نہ بنوں؟''', 'عبادت صرف خوف یا لالچ سے نہیں کی جاتی، بلکہ محبتِ الٰہی اور شکر گزاری کی بنیاد پر کی جانے والی عبادت سب سے اعلیٰ مقام ہے جس کا عملی نمونہ رسول اللہ ﷺ نے پیش فرمایا۔', '[{"word":"أَفَلَا","role":"الهمزة للاستفهام والفاء عاطفة","sign":"مبني","detail":"ولا نافية وأكون فعل مضارع ناقص واسمه ضمير مستتر تقديره أنا"},{"word":"عَبْداً","role":"خبر أكون منصوب","sign":"فتحة لفظاً","detail":"وشكوراً نعت منصوب"}]', '["متفق عليه: البخاري (1130)، ومسلم (2819)، والترمذي في الشمائل (264)."]', '{"en":"Al-Mughirah bin Shu''bah reported: The Prophet ﷺ prayed at night until his feet swelled. It was said to him: ''Why do you undertake such hardship when Allah has forgiven your past and future sins?'' He said: ''Shall I not be a grateful servant?''","ar":"كمال العبودية في شكر المنعم سبحانه وليس فقط لدفع العذاب أو طلب الثواب."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('qimat_zaman', 'قِيمَةُ الزَّمَنِ عِنْدَ العُلَمَاءِ', 'العَلَّامَةُ المُحَقِّقُ الشَّيْخُ عَبْدُ الفَتَّاحِ أَبُو غُدَّةَ الحَلَبِيُّ (ت: 1417ھ)', 'kharji_kitab', 'adab', 'وقت کی قدر و قیمت اور اکابرین کی کتب بینی', 'کتبِ مطالعہ و فکری رہنمائی (مفید برائے تمام طلبہ و اساتذہ)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'عصرِ حاضر کی بے مثال ترین تحریکی و تربیتی تصنیف۔ علامہ ابو غدہ نے سلفِ صالحین کے کتب بینی کے شوق اور وقت کی حفاظت کے حیرت انگیز واقعات جمع کیے ہیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qimat_zaman_ch1_hiras', 'qimat_zaman', 0, 'حِرْصُ السَّلَفِ الصَّالِحِ عَلَى الوَقْتِ وَاغْتِنَامِ دَقَائِقِ العُمُرِ', 'باب 1: سلف صالحین کی وقت سے والہانہ محبت اور منٹوں سیکنڈوں کی حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qimat_zaman_seg_1_1', 'qimat_zaman_ch1_hiras', 'qimat_zaman', 0, 'قَالَ العَلَّامَةُ الشَّيْخُ عَبْدُ الفَتَّاحِ أَبُو غُدَّةَ: «كَانَ السَّلَفُ الصَّالِحُ أَشَدَّ حِرْصاً عَلَى أَوْقَاتِهِمْ مِنْ حِرْصِ أَهْلِ الدُّنْيَا عَلَى أَمْوَالِهِمْ وَدَنَانِيرِهِمْ. قَالَ الحَسَنُ البَصْرِيُّ: «أَدْرَكْتُ أَقْوَاماً كَانَ أَحَدُهُمْ أَشَحَّ عَلَى عُمُرِهِ مِنْهُ عَلَى دَرَاهِمِهِ وَدَنَانِيرِهِ». وَكَانَ الخَلِيلُ بْنُ أَحْمَدَ الفَرَاهِيدِيُّ يَقُولُ: «أَثْقَلُ السَّاعَاتِ عَلَيَّ سَاعَةٌ آكُلُ فِيهَا!»؛ لِأَنَّهُ يَرَى تَنَاوُلَ الطَّعَامِ قَاطِعاً لَهُ عَنِ النَّظَرِ وَالبَحْثِ وَالعِلْمِ».', 'علامہ شیخ عبد الفتاح ابو غدہ رحمہ اللہ فرماتے ہیں: ''سلف صالحین اپنی زندگی کے قیمتی لمحات پر دنیا داروں کے مال و دولت اور اشرفیوں سے بھی زیادہ حریص تھے۔ امام حسن بصری فرماتے ہیں: ''میں نے ایسے بزرگوں کو پایا ہے جو اپنی عمر کے ایک ایک لمحے پر اپنے درہم و دینار سے بھی زیادہ بخیل اور حفاظت کرنے والے تھے''۔ اور علمِ عروض کے بانی خلیل بن احمد فراہیدی فرمایا کرتے تھے: ''میری زندگی کی سب سے بھاری اور ناگوار ترین گھڑی وہ ہوتی ہے جب میں کھانا کھا رہا ہوتا ہوں!'' کیونکہ وہ کھانا کھانے کو بھی مطالعے، غور و فکر اور علمی تحقیق کے راستے میں رکاوٹ سمجھتے تھے''۔', 'کتاب ''قيمة الزمن عند العلماء'' وقت کی قدروقیمت پر لکھی جانے والی سب سے لاجواب کتاب ہے۔ شیخ ابو غدہ نے علماء کے وہ سچے واقعات جمع کیے ہیں جنہیں پڑھ کر انسان کا اپنے وقت کو ضائع کرنے پر کلیجہ منہ کو آتا ہے۔', '[{"word":"أَشَدَّ","role":"خبر كان منصوب","sign":"فتحة","detail":"السلف اسمها وأشد خبرها"},{"word":"قَاطِعاً","role":"مفعول به ثان ليرى منصوب","sign":"فتحة","detail":"تناول مفعول أول وقاطعاً ثانٍ"}]', '["قيمة الزمن عند العلماء لعبد الفتاح أبو غدة، ص 21-28، دار البشائر."]', '{"en":"Shaykh Abd al-Fattah Abu Ghuddah''s ''Value of Time'': The righteous forebears guarded their hours more jealously than misers hoard gold coins. Al-Khalil ibn Ahmad lamented eating hours as a burdensome interruption to scholarly thought.","ar":"شواهد فريدة على ضنانة العلماء الربانيين بأوقاتهم في تحصيل العلوم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qimat_zaman_ch2_tasneef', 'qimat_zaman', 1, 'عَجَائِبُ مُؤَلَّفَاتِ العُلَمَاءِ وَاسْتِغْلَالُ أَشَدِّ اللَّحَظَاتِ فِي التَّصْنِيفِ', 'باب 2: تصنیف و تالیف کے محیر العقول عجائبات — سفر اور بیماری میں بھی قلم جاری رکھنا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qimat_zaman_seg_2_1', 'qimat_zaman_ch2_tasneef', 'qimat_zaman', 0, '«مِنْ أَعْجَبِ مَا يُرْوَى عَنْ عُلَمَائِنَا: أَنَّ الإِمَامَ ابْنَ جَرِيرٍ الطَّبَرِيَّ مَكَثَ أَرْبَعِينَ سَنَةً يَكْتُبُ فِي كُلِّ يَوْمٍ أَرْبَعِينَ وَرَقَةً! وَأَنَّ الإِمَامَ ابْنَ عَقِيلٍ الحَنْبَلِيَّ أَلَّفَ كِتَابَ «الفُنُونَ» فِي ثَمَانِمِائَةِ مُجَلَّدٍ، وَكَانَ يَقُولُ: «إِنِّي لَا يَحِلُّ لِي أَنْ أُضَيِّعَ سَاعَةً مِنْ عُمُرِي، حَتَّى إِذَا تَعَطَّلَ لِسَانِي عَنْ مُذَاكَرَةٍ، وَبَصَرِي عَنْ مُطَالَعَةٍ، أَعْمَلْتُ فِكْرِي فِي حَالِ رَاحَتِي وَأَنَا مُسْتَلْقٍ!». وَكَانَ يَبُلُّ الكَعْكَ بِالمَاءِ لِيَأْكُلَهُ سَرِيعاً تَوَفِيراً لِوَقْتِ القِرَاءَةِ».', 'شیخ ابو غدہ فرماتے ہیں: ''ہمارے اسلاف کے وقت کی حفاظت کے سب سے حیرت انگیز واقعات میں سے امام ابن جریر طبری کا واقعہ ہے جو چالیس سال تک روزانہ چالیس صفحات لکھتے رہے! اور امام ابن عقیل حنبلی نے ''کتاب الفنون'' آٹھ سو جلدوں میں تصنیف فرمائی، وہ فرمایا کرتے تھے: ''میرے لیے حلال نہیں کہ میں اپنی زندگی کا ایک لمحہ بھی ضائع کروں، یہاں تک کہ جب میری زبان بولنے سے تھک جاتی ہے اور میری آنکھیں مطالعے سے اکتا جاتی ہیں تو میں لیٹ کر آرام کرتے ہوئے بھی علمی مسائل پر غور و فکر کرتا رہتا ہوں!'' اور وہ کھانے کا وقت بچانے کے لیے سوکھی روٹی کو پانی میں بھگو کر نگل لیتے تھے تاکہ چبانے کا وقت بھی بچ جائے اور مطالعہ جاری رہے''۔', 'یہ محیر العقول واقعات بتاتے ہیں کہ اسلامی کتب خانوں کے ہزاروں عظیم الشان ذخیرے کوئی حادثاتی شے نہیں بلکہ خونِ جگر اور ایک ایک سیکنڈ کو علم پر قربان کرنے کا ثمرہ ہیں۔', '[{"word":"أَرْبَعِينَ","role":"ظرف زمان منصوب","sign":"ياء","detail":"ملحق بجمع المذكر السالم"},{"word":"تَوْفِيراً","role":"مفعول لأجله منصوب","sign":"فتحة","detail":"يبين سبب صنيعه"}]', '["قيمة الزمن عند العلماء، ص 48-62."]', '{"en":"Astonishing scholarly productivity: Ibn Jarir at-Tabari wrote 40 pages daily for 40 years. Ibn ''Aqil authored an 800-volume encyclopedia, soaking dry biscuits in water to save the chewing time for book study.","ar":"همم العلماء العالية في التصنيف والتدوين وصناعة التراث الخالد."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('bidayat_hidayah', 'بِدَايَةُ الهِدَايَةِ فِي الآدَابِ وَالأَخْلَاقِ', 'حُجَّةُ الإِسْلَامِ الإِمَامُ أَبُو حَامِدٍ مُحَمَّدُ بْنُ مُحَمَّدٍ الغَزَالِيُّ (ت: 505ھ)', 'kharji_kitab', 'tazkiyah', 'آدابِ بندگی، شب و روز کا جدول و اصلاحِ باطن', 'کتبِ مطالعہ و تزکیہ (مفید برائے طلبہ)', NULL, NULL, 'from-teal-900 via-emerald-950 to-stone-900', NULL, 'امام غزالی کا رسالہ جو طالب علم کو صبح بیدار ہونے سے لے کر رات سونے تک کے لمحات کو عبادت بنانے کا عملی دستور فراہم کرتا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bidayah_hidayah_ch1_taah', 'bidayat_hidayah', 0, 'القِسْمُ الأَوَّلُ: فِي بِدَايَةِ الهِدَايَةِ وَآدَابِ الطَّاعَاتِ وَاليَقَظَةِ', 'باب 1: بیداری سے لے کر سونے تک بندگی اور طاعت کا یومیہ نظام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bidayah_hidayah_seg_1_1', 'bidayah_hidayah_ch1_taah', 'bidayat_hidayah', 0, 'قَالَ حُجَّةُ الإِسْلَامِ الإِمَامُ أَبُو حَامِدٍ الغَزَالِيُّ: «اعْلَمْ أَيُّهَا الحَرِيصُ عَلَى اقْتِبَاسِ العِلْمِ، المُظْهِرُ مِنْ نَفْسِهِ صِدْقَ الرَّغْبَةِ، أَنَّكَ إِنْ كُنْتَ تَقْصِدُ بِالعِلْمِ المُنَافَسَةَ وَالمُبَاهَاةَ وَالتَّقَدُّمَ عَلَى الأَقْرَانِ وَاسْتِمَالَةَ وُجُوهِ النَّاسِ، فَأَنْتَ سَاعٍ فِي هَدْمِ دِينِكَ وَإِهْلَاكِ نَفْسِكَ وَبَيْعِ آخِرَتِكَ بِدُنْيَاكَ. وَإِنْ كَانَتْ نِيَّتُكَ بَيْنَكَ وَبَيْنَ اللَّهِ الهِدَايَةَ دُونَ مُجَرَّدِ الرِّوَايَةِ فَأَبْشِرْ، فَإِنَّ المَلَائِكَةَ تَبْسُطُ لَكَ أَجْنِحَتَهَا إِذَا مَشَيْتَ».', 'حجۃ الاسلام امام ابو حامد غزالی رحمہ اللہ فرماتے ہیں: ''اے علم حاصل کرنے کے شائق اور سچی طلب کا اظہار کرنے والے! خوب جان لے کہ اگر علم سے تیرا مقصد لوگوں سے مسابقت، اپنی برتری جتانا، ہم عصروں پر فوقیت حاصل کرنا اور لوگوں کی توجہ اپنی طرف کھینچنا ہے، تو تو اپنے دین کو منہدم کرنے، اپنی جان کو ہلاکت میں ڈالنے اور اپنی آخرت کو کوڑیوں کے مول دنیا کے ہاتھوں بیچنے کی دوڑ میں لگا ہوا ہے۔ اور اگر تیرے اور اللہ کے درمیان تیری نیت محض معلومات جمع کرنے کے بجائے ہدایت پانے کی ہے تو تجھے خوشخبری ہو، کیونکہ جب تو چلے گا تو فرشتے تیرے قدموں تلے اپنے پر بچھائیں گے''۔', 'بداية الهداية امام غزالی کی وہ روحانی وصیت ہے جس میں انہوں نے ایک مسلمان کے چوبیس گھنٹوں کی باطنی اور ظاہری ترتیب سکھائی ہے۔ علم اگر اخلاص سے خالی ہو تو سب سے بڑا فتنہ بن جاتا ہے۔', '[{"word":"الحَرِيصُ","role":"نعت لأيُّ مرفوع","sign":"ضمة ظاهرة","detail":"في أسلوب النداء (أيها الحريص)"},{"word":"سَاعٍ","role":"خبر المبتدأ أنت مرفوع","sign":"ضمة مقدرة","detail":"على الياء المحذوفة لالتقاء الساكنين"}]', '["بداية الهداية للغزالي، ص 7-12، دار المنهاج."]', '{"en":"Imam Al-Ghazali admonishes the seeker: If you seek knowledge for vanity, rivaling peers, and winning human applause, you are orchestrating the demolition of your faith and selling your hereafter. But if your intent is true divine guidance, rejoice, for angels spread their wings beneath your feet.","ar":"تجريد النية في طلب العلم والتحذير من الرياء وحب الشهرة والمباهاة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bidayah_hidayah_ch2_ijtinaab', 'bidayat_hidayah', 1, 'القِسْمُ الثَّانِي: فِي اجْتِنَابِ المَعَاصِي وَحِفْظِ الجَوَارِحِ السَّبْعَةِ', 'باب 2: گناہوں سے بچاؤ اور ساتوں جسمانی اعضاء (آنکھ، کان، زبان، پیٹ، شرمگاہ، ہاتھ، پاؤں) کی حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bidayah_hidayah_seg_2_1', 'bidayah_hidayah_ch2_ijtinaab', 'bidayat_hidayah', 0, '«اعْلَمْ أَنَّ الدِّينَ شَطْرَانِ: أَحَدُهُمَا تَرْكُ المَنَاهِي، وَالآخَرُ فِعْلُ الطَّاعَاتِ، وَتَرْكُ المَنَاهِي هُوَ الأَشَدُّ؛ فَإِنَّ الطَّاعَاتِ يَقْدِرُ عَلَيْهَا كُلُّ أَحَدٍ، وَتَرْكَ الشَّهَوَاتِ لَا يَقْدِرُ عَلَيْهِ إِلَّا الصِّدِّيقُونَ. وَمَعَاصِيكَ كُلُّهَا إِنَّمَا تَجْرِي عَلَى جَوَارِحِكَ السَّبْعَةِ: عَيْنِكَ، وَأُذُنِكَ، وَلِسَانِكَ، وَبَطْنِكَ، وَفَرْجِكَ، وَيَدَيْكَ، وَرِجْلَيْكَ؛ فَهِيَ رَعَايَاكَ فَلَا تَسْتَعْمِلْهَا إِلَّا فِيمَا خُلِقَتْ لَهُ».', 'امام غزالی فرماتے ہیں: ''جان لو کہ دین کے دو حصے ہیں: ایک گناہوں اور برائیوں کو چھوڑنا، اور دوسرا نیک اعمال کرنا؛ اور گناہوں کو چھوڑنا زیادہ کٹھن اور سخت ہے، کیونکہ ظاہری نیک کام تو ہر عام و خاص کر لیتا ہے لیکن نفس کی گناہ گار خواہشات کو لگام دینا صرف سچے صدیقین کا کام ہے۔ اور تیرے تمام گناہ دراصل تیرے سات اعضاء سے سرزد ہوتے ہیں: تیری آنکھ، تیرے کان، تیری زبان، تیرا پیٹ، تیری شرمگاہ، تیرے ہاتھ اور تیرے پاؤں؛ یہ سب تیری رعیت اور امانت ہیں، لہٰذا انہیں صرف اسی مقصد میں استعمال کر جس کے لیے اللہ نے انہیں پیدا فرمایا ہے''۔', 'انسان کا دل ایک شفاف تالاب کی طرح ہے جس میں یہ سات اعضاء نالیوں کی طرح اثرات انڈیلتے ہیں۔ اگر آنکھ اور کان حرام سے محفوظ ہوں تو دل خود بخود اللہ کی یاد سے سرشار رہتا ہے۔', '[{"word":"شَطْرَانِ","role":"خبر المبتدأ مرفوع","sign":"ألف","detail":"الدين مبتدأ وشطران خبره مثنى"},{"word":"الصِّدِّيقُونَ","role":"فاعل يقدر مرفوع","sign":"واو","detail":"جمع مذكر سالم (استثناء مفرغ)"}]', '["بداية الهداية، ص 42-48."]', '{"en":"Faith comprises two halves: Forsaking prohibitions and fulfilling devotions. Forsaking sins is far more arduous, for mere rites can be performed by anyone, but abstaining from primal temptations is achieved only by the steadfast Siddiqin through guarding the seven organs.","ar":"حفظ الجوارح السبعة عن الآثام لكونها منافذ القلب إلى المعاصي."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('qasas_nabiyyin', 'قِصَصُ النَّبِيِّينَ لِلأَطْفَالِ وَالنَّاشِئِينَ', 'مُفَكِّرُ الإِسْلَامِ العَلَّامَةُ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ (ت: 1420ھ)', 'kharji_kitab', 'adab', 'عربی ادب، سلیس انشاء و سیرتِ انبیاء', 'کتبِ مطالعہ و تسہیلِ عربی (مبتدی و متوسط طلبہ)', NULL, NULL, 'from-amber-900 via-stone-900 to-emerald-950', NULL, 'عربی زبان کے حسن، فصاحت اور انبیاء کے واقعات پر مشتمل وہ کتاب جو عربی فہم اور سلیس تحریر سکھانے کے لیے طلبہ کی پہلی پسند ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qasas_nabiyyin_ch1_ibrahim', 'qasas_nabiyyin', 0, 'قِصَّةُ سَيِّدِنَا إِبْرَاهِيمَ عَلَيْهِ السَّلَامُ: كَسْرُ الأَصْنَامِ وَالبَحْثُ عَنِ الحَقِيقَةِ', 'باب 1: سیدنا ابراہیم علیہ السلام کا قصہ — بتوں کو توڑنا اور توحیدِ خالص کی للکار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qasas_nabiyyin_seg_1_1', 'qasas_nabiyyin_ch1_ibrahim', 'qasas_nabiyyin', 0, 'قَالَ مُفَكِّرُ الإِسْلَامِ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ: «كَانَ فِي قَرْيَةٍ رَجُلٌ اسْمُهُ آزَرُ، وَكَانَ يَنْحِتُ الأَصْنَامَ بِيَدِهِ ثُمَّ يَسْجُدُ لَهَا! وَكَانَ لَهُ ابْنٌ صَالِحٌ ذَكِيٌّ اسْمُهُ إِبْرَاهِيمُ؛ رَأَى قَوْمَهُ يَعْبُدُونَ الحِجَارَةَ فَقَالَ فِي نَفْسِهِ: كَيْفَ يَعْبُدُ الإِنْسَانُ حَجَراً لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يَنْفَعُ؟! فَلَمَّا خَرَجَ القَوْمُ إِلَى عِيدِهِمْ حَمَلَ إِبْرَاهِيمُ فَأْسَهُ وَحَطَّمَ الأَصْنَامَ كُلَّهَا، وَتَرَكَ كَبِيراً لَهُمْ وَعَلَّقَ الفَأْسَ فِي عُنُقِهِ، فَلَمَّا رَجَعُوا قَالُوا: مَنْ فَعَلَ هَذَا بِآلِهَتِنَا؟ قَالَ: «بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا فَاسْأَلُوهُمْ إِنْ كَانُوا يَنْطِقُونَ!».', 'مفکر اسلام علامہ سید ابو الحسن علی ندوی رحمہ اللہ فرماتے ہیں: ''ایک بستی میں آزر نامی ایک شخص رہتا تھا جو اپنے ہاتھوں سے پتھر تراش کر بت بناتا اور پھر خود ہی ان کے آگے سجدہ ریز ہو جاتا! اس کا ایک بڑا نیک اور ذہین بیٹا تھا جس کا نام ابراہیم تھا۔ حضرت ابراہیم نے اپنی قوم کو پتھروں کی پوجا کرتے دیکھا تو اپنے دل میں سوچا: ایک جیتا جاگتا عقل مند انسان ایسے بے جان پتھر کو کیسے پوج سکتا ہے جو نہ سنتا ہے، نہ دیکھتا ہے، اور نہ کوئی نفع پہنچا سکتا ہے؟! چنانچہ جب قوم اپنے تہوار پر بستی سے باہر گئی تو حضرت ابراہیم نے کلہاڑی اٹھائی اور ان کے سارے بتوں کو توڑ کر ریزہ ریزہ کر دیا، اور صرف ان کے بڑے بت کو چھوڑ دیا اور کلہاڑی اس کی گردن میں لٹکا دی؛ پس جب وہ لوگ واپس آئے تو چیخ اٹھے: ہمارے معبودوں کے ساتھ یہ حشر کس نے کیا؟ ابراہیم علیہ السلام نے فرمایا: ''بلکہ یہ کام ان کے اس بڑے بت نے کیا ہے، ذرا انہی سے پوچھ لو اگر یہ بول سکتے ہوں!''', 'قصص النبيين علامہ ابو الحسن ندوی کی وہ کتاب ہے جو عربی ادب کی سادگی، شگفتگی اور تفسیری بلاغت کا حسین نمونہ ہے جسے دنیا بھر کے مدارس میں عربی زبان کے پہلے نصاب کے طور پر پڑھایا جاتا ہے۔', '[{"word":"حَجَراً","role":"مفعول به ليعبد منصوب","sign":"فتحة","detail":"وجملة لا يسمع نعت له"},{"word":"كَبِيرُهُمْ","role":"فاعل لفعله مرفوع","sign":"ضمة","detail":"وهو مضاف والهاء مضاف إليه"}]', '["قصص النبيين للأطفال، الجزء الأول: قصة إبراهيم عليه السلام، ص 10-25."]', '{"en":"Allama Nadwi''s elegant prose in ''Qasas an-Nabiyyin'': The young Abraham contemplated the absurdity of idolatry. When the townsfolk left for their festival, he shattered the idols with an axe, placing it upon the chief idol''s shoulder to awaken their intellects: ''Ask them, if they can speak!''","ar":"حوار إبراهيم الخليل مع قومه وإقامة الحجة العقلية على بطلان الوثنية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qasas_nabiyyin_ch2_yusuf', 'qasas_nabiyyin', 1, 'قِصَّةُ سَيِّدِنَا يُوسُفَ عَلَيْهِ السَّلَامُ: مِنَ الجُبِّ إِلَى عَرْشِ مِصْرَ', 'باب 2: سیدنا یوسف علیہ السلام — کنویں کی تنہائی اور قید خانے کی آزمائش سے مصر کی حکمرانی تک');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qasas_nabiyyin_seg_2_1', 'qasas_nabiyyin_ch2_yusuf', 'qasas_nabiyyin', 0, '«كَانَ يُوسُفُ عَلَيْهِ السَّلَامُ أَحْسَنَ إِخْوَتِهِ خُلُقاً وَصُورَةً، فَحَسَدَهُ إِخْوَتُهُ وَأَلْقَوْهُ فِي غَيَابَتِ الجُبِّ، وَقَالُوا لِأَبِيهِمْ: أَكَلَهُ الذِّئْبُ! فَقَالَ يَعْقُوبُ: {فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ}. وَبِيعَ يُوسُفُ فِي مِصْرَ بِثَمَنٍ بَخْسٍ، ثُمَّ ابْتُلِيَ بِفِتْنَةِ امْرَأَةِ العَزِيزِ فَآثَرَ السِّجْنَ عَلَى المَعْصِيَةِ، فَمَكُثَ فِي السِّجْنِ بِضْعَ سِنِينَ دَاعِياً إِلَى التَّوْحِيدِ، حَتَّى أَظْهَرَ اللَّهُ بَرَاءَتَهُ وَمَكَّنَ لَهُ فِي الأَرْضِ، فَلَمَّا جَاءَهُ إِخْوَتُهُ قَالَ لَهُمْ بِعَفْوِ الأَنْبِيَاءِ: {لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ}».', 'علامہ ندوی فرماتے ہیں: ''حضرت یوسف علیہ السلام اپنے تمام بھائیوں میں سب سے زیادہ خوبصورت اور با اخلاق تھے، ان کے بھائیوں نے حسد کیا اور انہیں ایک اندھے کنویں میں پھینک دیا، اور اپنے والد سے جا کر جھوٹ بول دیا کہ یوسف کو بھیڑیا کھا گیا ہے! تو حضرت یعقوب علیہ السلام نے فرمایا: {پس صبرِ جمیل ہی بہتر ہے اور اللہ ہی سے مدد مانگی جاتی ہے}۔ اور یوسف علیہ السلام کو مصر کے بازار میں چند کھوٹے سکوں کے بدلے بیچ دیا گیا، پھر عزیزِ مصر کی بیوی کی فتنے انگیز آزمائش آئی تو آپ نے گناہ پر قید خانے کی مشقت کو ترجیح دی، اور کئی سال جیل کی تنہائی میں توحید کی دعوت دیتے رہے، یہاں تک کہ اللہ نے آپ کی پاک دامنی کو روزِ روشن کی طرح عیاں کر دیا اور آپ کو مصر کی حکومت اور اقتدار بخشا؛ اور جب وہی حسد کرنے والے بھائی آپ کے دربار میں جھولی پھیلائے آئے تو آپ نے انبیاء کی شانِ عفو کا مظاہرہ کرتے ہوئے فرمایا: {آج کے دن تم پر کوئی ملامت نہیں، اللہ تمہیں معاف فرمائے اور وہ سب سے بڑھ کر رحم کرنے والا ہے}''۔', 'قصۂ یوسف صبر، عفت، آزمائش اور معاف کرنے کا سب سے حسین مرقع ہے۔ علامہ ندوی نے قرآنی قصص کو ایسی شیریں اور فصیح عربی میں پیش کیا ہے جو طالب علم کے دل میں ایمان کا بیج بو دیتی ہے۔', '[{"word":"صَبْرٌ","role":"خبر لمبتدأ محذوف","sign":"ضمة","detail":"تقديره: أمري أو فصبري صبرٌ جميل"},{"word":"لَا تَثْرِيبَ","role":"لا نافية للجنس","sign":"مبني على الفتح","detail":"تثريب اسمها وعليكم خبرها"}]', '["قصص النبيين، الجزء الرابع: قصة يوسف عليه السلام، ص 80-120."]', '{"en":"The epic journey of Joseph (Yusuf): From the jealousy of brothers and depths of the well to resisting seduction and enduring prison, emerging as ruler of Egypt, culminating in the prophetic pardon: {No blame will there be upon you today; may Allah forgive you}.","ar":"محاسن سورة يوسف وتجلي الصبر الجميل والعفة والعفو عند المقدرة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('tarikh_dawah', 'تَارِيخُ الدَّعْوَةِ وَالعَزِيمَةِ (رِجَالُ الفِكْرِ وَالدَّعْوَةِ)', 'مُفَكِّرُ الإِسْلَامِ العَلَّامَةُ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ (ت: 1420ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ تجدید، دعوت و سوانحِ ائمۂ اسلام', 'کتبِ مطالعہ و فکری پختگی (متوسط و منتہی طلبہ)', NULL, NULL, 'from-slate-900 via-emerald-950 to-stone-900', NULL, 'اسلامی تاریخ کے عظیم مجددین، ائمۂ دین اور مصلحین کی حیات و خدمات کا ولولہ انگیز جائزہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tarikh_dawah_ch1_hasan_basri', 'tarikh_dawah', 0, 'عَصْرُ الحَسَنِ البَصْرِيِّ وَعُمَرَ بْنِ عَبْدِ العَزِيزِ: يَقَظَةُ الضَّمِيرِ الإِسْلَامِيِّ', 'باب 1: امام حسن بصری اور حضرت عمر بن عبد العزیز — اسلامی ضمیر کی نشاۃ ثانیہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tarikh_dawah_seg_1_1', 'tarikh_dawah_ch1_hasan_basri', 'tarikh_dawah', 0, 'قَالَ مُفَكِّرُ الإِسْلَامِ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ: «لَمْ يَمْضِ عَلَى العَهْدِ الرَّاشِدِ قَرْنٌ حَتَّى كَادَتِ المَادِّيَّةُ وَالمُلْكُ العَضُوضُ أَنْ يَجْرُفَا الرُّوحَ الإِسْلَامِيَّةَ، فَانْتَدَبَ اللَّهُ لِهَذَا الدِّينِ رِجَالاً مَلَكُوا شَجَاعَةَ الرَّأْيِ وَرَوْعَةَ الإِيمَانِ. كَانَ الحَسَنُ البَصْرِيُّ ضَمِيرَ الأُمَّةِ الحَيَّ؛ إِذَا تَكَلَّمَ كَأَنَّهُ عَائِدٌ مِنَ الآخِرَةِ يُخْبِرُ عَنْهَا. وَجَاءَ عُمَرُ بْنُ عَبْدِ العَزِيزِ فَأَحْيَا سِيرَةَ الخُلَفَاءِ الرَّاشِدِينَ فِي عَدْلِهِ وَزُهْدِهِ، فَأَثْبَتَ أَنَّ المَنْهَجَ النَّبَوِيَّ صَالِحٌ لِلتَّطْبِيقِ فِي كُلِّ زَمَانٍ».', 'مفکرِ اسلام علامہ سید ابو الحسن علی حسنی ندوی رحمہ اللہ فرماتے ہیں: ''خلافت راشدہ کو ابھی ایک صدی بھی نہ گزری تھی کہ مادہ پرستی اور ملوکیت کے طوفان نے اسلامی روح کو بہا لے جانے کی کوشش کی، تو اللہ تعالیٰ نے اس دین کی حفاظت کے لیے ایسے مردانِ کار پیدا فرمائے جو حق گوئی کی شجاعت اور ایمان کی بے پناہ رفعت کے مالک تھے۔ امام حسن بصری امت کا زندہ ضمیر تھے؛ جب کلام فرماتے تو یوں معلوم ہوتا گویا آخرت سے لوٹ کر اس کے احوال سنا رہے ہیں۔ اور پھر حضرت عمر بن عبد العزیز کی خلافت آئی تو انہوں نے اپنے عدل اور بے مثال زہد سے خلافت راشدہ کی پاکیزہ تاریخ کو دوبارہ زندہ کر دکھایا اور ثابت کر دیا کہ نبوی منہاج ہر دور میں نافذ ہونے کی مکمل صلاحیت رکھتا ہے''۔', 'تاریخ دعوت و عزیمت (رجال الفکر والدعوۃ) علامہ ندوی کی وہ تاریخ ساز تصنیف ہے جس نے امت کے مجددین کی قربانیوں اور دعوت کو تاریخ کی روشنی میں زندہ کیا۔', '[{"word":"ضَمِيرَ","role":"خبر كان منصوب","sign":"فتحة","detail":"الحسن اسمها وضمير خبرها وهو مضاف"},{"word":"صَالِحٌ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"اسم أنّ المنهج وصالح خبرها"}]', '["رجال الفكر والدعوة في الإسلام (تاريخ الدعوة والعزيمة)، 1/ 45-56، دار القلم."]', '{"en":"Allama Abul Hasan Ali Nadwi depicts the heroic resurgence: When monarchical materialism threatened to extinguish the Prophetic spirit, Hasan al-Basri emerged as the living conscience of the Ummah, and ''Umar bin ''Abd al-''Aziz revived the pristine justice of the Rightly Guided Caliphs.","ar":"بيان دور أئمة التجديد في مواجهة الانحراف السياسي والمادي وحفظ أصالة الإسلام."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tarikh_dawah_ch2_salahuddin', 'tarikh_dawah', 1, 'عَصْرُ نُورِ الدِّينِ زَنْكِي وَصَلَاحِ الدِّينِ الأَيُّوبِيِّ: تَحْرِيرُ القُدْسِ وَبَعْثُ الأُمَّةِ', 'باب 2: سلطان نور الدین زنگی اور صلاح الدین ایوبی — قدس کی آزادی اور ملت کا فکری و عسکری احیاء');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tarikh_dawah_seg_2_1', 'tarikh_dawah_ch2_salahuddin', 'tarikh_dawah', 0, '«إِنَّ فَتْحَ بَيْتِ المَقْدِسِ عَلَى يَدِ البَطَلِ صَلَاحِ الدِّينِ لَمْ يَكُنْ مُجَرَّدَ نَصْرٍ عَسْكَرِيٍّ طَارِئٍ، بَلْ كَانَ ثَمَرَةَ جِهَادٍ تَرْبَوِيٍّ وَعِلْمِيٍّ طَوِيلٍ بَدَأَهُ الإِمَامُ الغَزَالِيُّ وَعَبْدُ القَادِرِ الجِيلَانِيُّ فِي إِصْلَاحِ النُّفُوسِ، وَبَنَاهُ نُورُ الدِّينِ زَنْكِي فِي تَوْحِيدِ الجَبْهَةِ الإِسْلَامِيَّةِ. فَلَمَّا كَمُلَتِ التَّرْبِيَةُ الإِيمَانِيَّةُ جَاءَ النَّصْرُ الإِلَهِيُّ فِي حِطِّينَ، وَدَخَلَ صَلَاحُ الدِّينِ القُدْسَ فَاتِحاً رَحِيماً، فَضَرَبَ لِلْعَالَمِ أَرْوَعَ أَمْثِلَةِ النُّبْلِ وَالسَّمَاحَةِ الإِسْلَامِيَّةِ».', 'علامہ ندوی فرماتے ہیں: ''سلطان صلاح الدین ایوبی کے ہاتھوں بیت المقدس کی فتح کوئی اچانک ہونے والی عسکری کامیابی نہ تھی، بلکہ یہ اس طویل تربیتی اور علمی جہاد کا ثمرہ تھی جس کا آغاز امام غزالی اور شیخ عبد القادر جیلانی نے نفوس کی باطنی اصلاح اور مدارس کے قیام سے کیا تھا، اور جسے سلطان نور الدین زنگی نے امت کی بکھری طاقتوں کو یکجا کر کے پروان چڑھایا۔ پس جب ایمانی تربیت پایۂ تکمیل کو پہنچی تو میدانِ حطین میں نصرتِ خداوندی نازل ہوئی، اور صلاح الدین ایوبی ایک رحم دل فاتح بن کر قدس میں داخل ہوئے اور انہوں نے خونخوار صلیبیوں کے برعکس دنیا کے سامنے اسلامی عفو، شرافت اور اعلیٰ اخلاق کی بے نظیر مثال قائم کی''۔', 'یہ بصیرت افروز تجزیہ بتاتا ہے کہ سیاسی و عسکری فتوحات ہمیشہ باطنی تزکیے اور اخلاقی تیاری کا نتیجہ ہوتی ہیں، بغیر تیاری کے نعرے کامیابی نہیں لا سکتے۔', '[{"word":"ثَمَرَةَ","role":"خبر كان منصوب","sign":"فتحة","detail":"اسم كان ضمير مستتر وثمرة خبرها"},{"word":"فَاتِحاً","role":"حال أولى منصوبة","sign":"فتحة","detail":"ورحيماً حال ثانية"}]', '["رجال الفكر والدعوة، المجلد الثاني: صلاح الدين الأيوبي، ص 180-195."]', '{"en":"The liberation of Jerusalem by Saladin was not an overnight martial accident, but the culmination of profound moral regeneration initiated by Ghazali and Jilani, strategically unified by Nur ad-Din Zengi, culminating in Hittin and unmatched magnanimity.","ar":"السنن الربانية في استحقاق النصر والتمكين بعد تزكية النفوس ووحدة الصف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_itqan_suyuti', 'الإِتْقَانُ فِي عُلُومِ القُرْآنِ', 'الحَافِظُ جَلَالُ الدِّينِ عَبْدُ الرَّحْمَنِ السُّيُوطِيُّ (ت: 911ھ)', 'kharji_kitab', 'quran', 'علوم القرآن و اصولِ تفسیر', 'کتبِ مطالعہ و تخصص (علوم القرآن)', NULL, NULL, 'from-teal-900 via-emerald-950 to-stone-900', NULL, 'علوم القرآن کا سب سے مفصل اور معتمد انسائیکلوپیڈیا۔ اس میں ناسخ و منسوخ، اعجاز، اسبابِ نزول اور قراءات کے 80 انواع کا علمی احاطہ کیا گیا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('itqan_ch1_jam', 'kharji_itqan_suyuti', 0, 'النَّوْعُ الثَّامِنَ عَشَرَ: فِي مَعْرِفَةِ جَمْعِ القُرْآنِ وَتَرْتِيبِهِ', 'باب 1: جمعِ قرآن اور ترتیبِ سور و آیات کی تاریخ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('itqan_seg_1_1', 'itqan_ch1_jam', 'kharji_itqan_suyuti', 0, 'قَالَ الإِمَامُ جَلَالُ الدِّينِ السُّيُوطِيُّ: «الإِجْمَاعُ مُنْعَقِدٌ عَلَى أَنَّ تَرْتِيبَ الآيَاتِ تَوْقِيفِيٌّ لَا شُبْهَةَ فِيهِ، كَانَ جِبْرِيلُ عَلَيْهِ السَّلَامُ يَنْزِلُ بِالآيَةِ فَيَقُولُ: ضَعُوا هَذِهِ الآيَةَ فِي مَوْضِعِ كَذَا مِنْ سُورَةِ كَذَا. وَأَمَّا جَمْعُ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ فَكَانَ لِخَشْيَةِ ذَهَابِ شَيْءٍ مِنْهُ بِمَوْتِ حَفَظَتِهِ فِي اليَمَامَةِ، وَجَمْعُ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ كَانَ لِجَمْعِ النَّاسِ عَلَى مُصْحَفٍ وَاحِدٍ لَمَّا اخْتَلَفُوا فِي القِرَاءَاتِ».', 'امام جلال الدین سیوطی رحمہ اللہ فرماتے ہیں: ''اس بات پر امت کا قطعی اجماع ہے کہ قرآن کریم کی آیات کی ترتیب توقیفی (منجانب اللہ) ہے جس میں کوئی شبہ نہیں۔ حضرت جبریل علیہ السلام وحی لے کر نازل ہوتے اور فرماتے: اس آیت کو فلاں سورت میں فلاں مقام پر رکھو۔ صدیقِ اکبر رضی اللہ عنہ کا جمع کرنا جنگِ یمامہ میں حفاظ کی شہادت کے بعد ضیاع کے اندیشے کی وجہ سے تھا، جبکہ سیدنا عثمان غنی رضی اللہ عنہ کا جمع کرنا مسلمانوں کو ایک ہی رسم الخط اور مصحفِ امام پر جمع کرنے کے لیے تھا جب مختلف علاقوں میں قرات کا اختلاف رونما ہوا''۔', 'الاتقان فی علوم القرآن علومِ قرآن کی امہات الکتب میں شمار ہوتی ہے۔ امام سیوطی نے اس کتاب میں 80 اہم ترین علوم کو یکجا کیا ہے۔ اس باب میں جمعِ قرآن کے دونوں مراحل (صدیقی و عثمانی) کی حکمت اور آیات کے توقیفی ہونے کا تاریخی و روائی ثبوت پیش کیا گیا ہے۔', '[{"word":"الإِجْمَاعُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"اسم معرفة في أول الجملة"},{"word":"مُنْعَقِدٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"يتمم معنى المبتدأ"},{"word":"تَوْقِيفِيٌّ","role":"خبر أنّ مرفوع","sign":"ضمة ظاهرة","detail":"اسم أنّ ترتيب والخبر توقيفي"}]', '["الإتقان في علوم القرآن، النوع الثامن عشر، 1/ 210-218، دار الفكر."]', '{"en":"Imam As-Suyuti affirms: The arrangement of Ayahs is completely Tawqifi (divinely dictated) by consensus; Gabriel directed the Prophet ﷺ where to place each verse. Abu Bakr compiled it to preserve it from loss, while ''Uthman unified the Muslims upon a single standardized mushaf.","ar":"بيان قطعية الترتيب التوقيفي لآيات التنزيل الحكيم ومراتب الجمع في العهد الراشدي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('itqan_ch2_shurut_mufassir', 'kharji_itqan_suyuti', 1, 'النَّوْعُ الثَّامِنُ وَالسَّبْعُونَ: فِي مَعْرِفَةِ شُرُوطِ المُفَسِّرِ وَآدَابِهِ', 'باب 2: مفسرِ قرآن کی علمی شرائط اور ضروری آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('itqan_seg_2_1', 'itqan_ch2_shurut_mufassir', 'kharji_itqan_suyuti', 0, '«لَا يَجُوزُ لِأَحَدٍ أَنْ يُفَسِّرَ كِتَابَ اللَّهِ تَعَالَى بِمُجَرَّدِ رَأْيِهِ مِنْ غَيْرِ أَنْ يَكُونَ عَارِفاً بِعُلُومٍ جَمَّةٍ: عِلْمِ اللُّغَةِ وَالنَّحْوِ وَالتَّصْرِيفِ وَالاشْتِقَاقِ، وَعُلُومِ البَلَاغَةِ الثَّلَاثَةِ: المَعَانِي وَالبَيَانِ وَالبَدِيعِ، وَأُصُولِ الدِّينِ، وَأُصُولِ الفِقْهِ، وَأَسْبَابِ النُّزُولِ، وَالنَّاسِخِ وَالمَنْسُوخِ، وَالمُجْمَلِ وَالمُبَيَّنِ، وَعِلْمِ الحَدِيثِ دِرَايَةً وَرِوَايَةً، مَعَ صِدْقِ النِّيَّةِ وَالتَّقْوَى».', 'سیوطی رحمہ اللہ فرماتے ہیں: ''کسی کے لیے جائز نہیں کہ وہ کتاب اللہ کی تفسیر محض اپنی ذاتی رائے سے کرے بغیر اس کے کہ وہ بنیادی علوم کا ماہر ہو: لغت، نحو، صرف، اشتقاق، بلاغت کے تینوں علوم (معانی، بیان، بدیع)، علمِ عقائد و اصولِ دین، اصولِ فقہ، اسبابِ نزول، ناسخ و منسوخ، مجمل و مبین، اور علمِ حدیث بسند و درایت؛ اور ان تمام علوم کے ساتھ ساتھ سچی نیت اور تقویٰ و للہیت لازم ہے''۔', 'قرآن کریم رب کائنات کا کلام ہے۔ اس کی مراد متعین کرنے کے لیے صرف لغت شناسی کافی نہیں بلکہ اصولِ فقہ، بلاغت، ناسخ و منسوخ اور حدیث نبوی کا رسوخ درکار ہے، ورنہ انسان تحریف و الحاد کا شکار ہو جاتا ہے۔', '[{"word":"لَا يَجُوزُ","role":"لا نافية، يجوز فعل مضارع مرفوع","sign":"ضمة ظاهرة","detail":"المصدر المؤول (أن يفسر) فاعل يجوز"},{"word":"عَارِفاً","role":"خبر كان منصوب","sign":"فتحة","detail":"واسمها ضمير مستتر يعود على أحد"}]', '["الإتقان في علوم القرآن، النوع 78، 2/ 480، طبعة مجمع الملك فهد."]', '{"en":"Imam As-Suyuti outlines the 15 prerequisite sciences for any qualified Mufassir: Lexicology, Grammar, Morphology, Etymology, Rhetoric (Bayan, Ma''ani, Badi''), Theology, Usul al-Fiqh, Asbab an-Nuzul, Abrogation, Hadith sciences, combined with sincere devotion and Taqwa.","ar":"اشتراط العلوم الخمسة عشر فيمن يتصدى لتفسير كلام رب العالمين صيانة لكتاب الله عن التحريف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_muqaddimah_tafseer_taymiyyah', 'مُقَدِّمَةٌ فِي أُصُولِ التَّفْسِيرِ', 'شَيْخُ الإِسْلَامِ أَحْمَدُ بْنُ عَبْدِ الحَلِيمِ ابْنُ تَيْمِيَّةَ (ت: 728ھ)', 'kharji_kitab', 'tafseer', 'اصولِ تفسیر و مناہجِ مفسرین', 'کتبِ مطالعہ و اصولِ فہمِ قرآن (جملہ طلبہ)', NULL, NULL, 'from-amber-900 via-stone-900 to-emerald-950', NULL, 'اصولِ تفسیر کا بے نظیر رسالہ جس میں قرآن کی قرآن سے، سنت سے، اور اقوالِ صحابہ سے تفسیر کرنے کے درجات و قواعد بیان کیے گئے ہیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('taymiyyah_tafseer_ch1_turuq', 'kharji_muqaddimah_tafseer_taymiyyah', 0, 'فَصْلٌ فِي أَحْسَنِ طُرُقِ التَّفْسِيرِ النَّقْلِيِّ وَالعَقْلِيِّ', 'باب 1: تفسیر کا سب سے مستند اور معتبر منہاج');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('taymiyyah_tafseer_seg_1_1', 'taymiyyah_tafseer_ch1_turuq', 'kharji_muqaddimah_tafseer_taymiyyah', 0, 'قَالَ شَيْخُ الإِسْلَامِ ابْنُ تَيْمِيَّةَ: «فَإِنْ قَالَ قَائِلٌ: فَمَا أَحْسَنُ طُرُقِ التَّفْسِيرِ؟ فَالجَوَابُ: إِنَّ أَصَحَّ الطُّرُقِ فِي ذَلِكَ أَنْ يُفَسَّرَ القُرْآنُ بِالقُرْآنِ؛ فَمَا أُجْمِلَ فِي مَكَانٍ فَإِنَّهُ قَدْ فُسِّرَ فِي مَوْضِعٍ آخَرَ، وَمَا اخْتُصِرَ فِي مَكَانٍ فَقَدْ بُسِطَ فِي مَوْضِعٍ آخَرَ. فَإِنْ أَعْيَاكَ ذَلِكَ فَعَلَيْكَ بِالسُّنَّةِ؛ فَإِنَّهَا شَارِحَةٌ لِلْقُرْآنِ وَمُوَضِّحَةٌ لَهُ. فَإِذَا لَمْ نَجِدِ التَّفْسِيرَ فِي القُرْآنِ وَلَا فِي السُّنَّةِ رَجَعْنَا فِي ذَلِكَ إِلَى أَقْوَالِ الصَّحَابَةِ، فَإِنَّهُمْ أَدْرَى بِذَلِكَ لِمَا شَاهَدُوهُ مِنَ القَرَائِنِ وَالأَحْوَالِ».', 'شیخ الاسلام ابن تیمیہ رحمہ اللہ فرماتے ہیں: ''اگر کوئی سوال کرے کہ تفسیر کا سب سے بہترین طریقہ کیا ہے؟ تو جواب یہ ہے کہ سب سے مستند اور صحیح ترین طریقہ یہ ہے کہ قرآن کی تفسیر قرآن ہی سے کی جائے؛ کیونکہ جو بات ایک جگہ مجمل ہے دوسری جگہ اس کی تفصیل موجود ہے، اور جو ایک جگہ اختصار سے آئی دوسری جگہ اسے کھول کر بیان کیا گیا۔ پھر اگر وہاں نہ ملے تو سنتِ نبویہ کی طرف رجوع کیا جائے کیونکہ سنت قرآن کی شارح اور توضیح ہے۔ اور اگر قرآن اور سنت میں نہ ملے تو صحابہ کرام رضی اللہ عنہم کے اقوال کی طرف رجوع کیا جائے کیونکہ انہوں نے وحی کا نزول، اس کے احوال اور قرائن اپنی آنکھوں سے دیکھے تھے''۔', 'یہ مختصر کتاب دراصل تفسیر کے علمی مناہج کا خلاصہ ہے۔ امام ابن تیمیہ نے ثابت کیا کہ تفسیر بالمأثور ہی شریعت کی بنیاد ہے اور صحابہ کی فہم عربی زبان و وحی کے سیاق کو سمجھنے میں حجت ہے۔', '[{"word":"أَحْسَنُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"وهو مضاف وطرق مضاف إليه"},{"word":"شَارِحَةٌ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"والهاء ضمير متصل اسمها"}]', '["مقدمة في أصول التفسير، ص 93-95، تحقيق د. عدنان زرزور."]', '{"en":"Ibn Taymiyyah''s golden hierarchy of Tafsir: 1. Tafsir of the Quran by the Quran itself, 2. Tafsir by the authentic Sunnah, 3. Tafsir by the companions (Sahabah) who witnessed the revelation, 4. Tafsir by the prominent Tabi''in.","ar":"تقرير منهج أهل السنة والجماعة في التفسير بالمأثور ودرجاته الأربع."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('taymiyyah_tafseer_ch2_ikhtilaf', 'kharji_muqaddimah_tafseer_taymiyyah', 1, 'فَصْلٌ فِي سَبَبِ اخْتِلَافِ السَّلَفِ فِي التَّفْسِيرِ: تَنَوُّعٌ لَا تَضَادٌّ', 'باب 2: تفسیر میں سلف کا اختلاف — تنوع اور تعبیر کا فرق، تضاد نہیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('taymiyyah_tafseer_seg_2_1', 'taymiyyah_tafseer_ch2_ikhtilaf', 'kharji_muqaddimah_tafseer_taymiyyah', 0, '«وَالخِلَافُ بَيْنَ السَّلَفِ فِي التَّفْسِيرِ قَلِيلٌ، وَغَالِبُ مَا يَصِحُّ عَنْهُمْ مِنَ الخِلَافِ مَرْجِعُهُ إِلَى اخْتِلَافِ تَنَوُّعٍ لَا اخْتِلَافِ تَضَادٍّ. وَذَلِكَ عَلَى وَجْهَيْنِ: أَحَدُهُمَا: أَنْ يُعَبِّرَ كُلُّ وَاحِدٍ مِنْهُمْ عَنِ المُرَادِ بِعِبَارَةٍ غَيْرِ عِبَارَةِ صَاحِبِهِ تَدُلُّ عَلَى مَعْنًى فِي المُسَمَّى غَيْرِ الآخَرِ، كَمَا قِيلَ فِي الصِّرَاطِ المُسْتَقِيمِ: هُوَ القُرْآنُ، وَقِيلَ: هُوَ الإِسْلَامُ، وَقِيلَ: السُّنَّةُ، وَهِيَ كُلُّهَا حَقٌّ مُتَلَازِمَةٌ».', 'ابن تیمیہ رحمہ اللہ فرماتے ہیں: ''تفسیر میں سلف صالحین کے درمیان اختلاف بہت کم ہے، اور ان سے جو اختلاف صحیح سند سے ثابت ہے اس کی غالب مقدار اختلافِ تنوع (تعبیر کا تنوع) ہے، اختلافِ تضاد (ایک دوسرے کی نفی) نہیں۔ اس کی دو صورتیں ہیں: ایک یہ کہ ہر مفسر مطلوبہ معنی کو اپنے ایسے الفاظ میں بیان کرے جو دوسرے سے بظاہر الگ ہوں مگر دونوں ایک ہی حقیقت کے مختلف اوصاف بتاتے ہوں؛ جیسے ''صراط مستقیم'' کے بارے میں ایک بزرگ نے فرمایا کہ اس سے مراد قرآن ہے، دوسرے نے فرمایا اسلام ہے، اور تیسرے نے فرمایا سنت ہے؛ اور حقیقت میں یہ سب حق اور ایک دوسرے کے لازم و ملزوم ہیں''۔', 'یہ قاعدہ قرآنی تفاسیر کے طلبہ کے لیے سنگِ میل ہے۔ کثیر تفسیری اقوال کو تضاد سمجھنے کی بجائے حقیقتِ واحدہ کے مختلف پہلو قرار دینا ہی سلف کی حقیقی منشا کو سمجھنے کی کلید ہے۔', '[{"word":"قَلِيلٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"الخلاف مبتدأ وقليل خبره"},{"word":"تَنَوُّعٍ","role":"مضاف إليه مجرور","sign":"كسرة","detail":"اختلاف مضاف وتنوع مضاف إليه"}]', '["مقدمة في أصول التفسير، ص 41-45."]', '{"en":"Ibn Taymiyyah elucidates that variation among early exegetes is mostly an ''Ikhtilaf Tanawwu'''' (diversity of facet/expression) rather than an ''Ikhtilaf Tadadd'' (mutual contradiction)—such as defining Sirat al-Mustaqim as Quran, Islam, or Sunnah.","ar":"تأصيل قاعدة التوفيق بين عبارات السلف في التفسير وردهم إلى أصل واحد."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_burhan_zarkashi', 'البُرْهَانُ فِي عُلُومِ القُرْآنِ', 'الإِمَامُ بَدْرُ الدِّينِ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزَّرْكَشِيُّ (ت: 794ھ)', 'kharji_kitab', 'quran', 'علوم القرآن و اسرارِ بلاغت', 'کتبِ مطالعہ و تخصص (علوم القرآن)', NULL, NULL, 'from-emerald-950 via-stone-900 to-teal-900', NULL, 'علوم القرآن کی پہلی جامع ترین کتاب جس پر علامہ سیوطی کی اتقان کی بنیاد رکھی گئی۔ نظمِ قرآن، فصاحت اور اعجاز پر وقیع بحث۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('burhan_ch1_asbab', 'kharji_burhan_zarkashi', 0, 'النَّوْعُ الأَوَّلُ: فِي مَعْرِفَةِ سَبَبِ النُّزُولِ وَفَوَائِدِهِ', 'باب 1: اسبابِ نزول کی معرفت اور تفسیری فوائد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('burhan_seg_1_1', 'burhan_ch1_asbab', 'kharji_burhan_zarkashi', 0, 'قَالَ الإِمَامُ بَدْرُ الدِّينِ الزَّرْكَشِيُّ: «مَعْرِفَةُ سَبَبِ النُّزُولِ أَمْرٌ مُهِمٌّ جِدّاً فِي فَهْمِ الآيَةِ؛ فَإِنَّ العِلْمَ بِالسَّبَبِ يُورِثُ العِلْمَ بِالمُسَبَّبِ، وَقَدْ يُشْكِلُ مَعْنَى الآيَةِ حَتَّى يُعْلَمَ سَبَبُ نُزُولِهَا، فَيَزُولُ الإِشْكَالُ، كَمَا فِي قَوْلِهِ تَعَالَى: {وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ}، فَإِنَّ ظَاهِرَهَا يُوهِمُ جَوَازَ اسْتِقْبَالِ أَيِّ جِهَةٍ فِي الصَّلَاةِ، فَلَمَّا عُرِفَ سَبَبُ النُّزُولِ فِي السَّفَرِ وَالاشْتِبَاهِ عَلَى القِبْلَةِ انْجَلَى المُرَادُ».', 'امام بدر الدین زرکشی رحمہ اللہ فرماتے ہیں: ''آیت کے صحیح فہم کے لیے سببِ نزول کی معرفت ازحد ضروری ہے؛ کیونکہ سبب کا علم مسبب (آیت کے حکم) کا علم پیدا کرتا ہے، اور بسا اوقات آیت کا معنی اشکال پیدا کرتا ہے یہاں تک کہ اس کا سببِ نزول معلوم ہو جائے تو اشکال زائل ہو جاتا ہے۔ جیسا کہ اللہ کا فرمان: {اور مشرق و مغرب اللہ ہی کے ہیں، تم جدھر بھی رخ کرو ادھر ہی اللہ کا رخ ہے}، اس کا ظاہری مفہوم یہ وہم ڈالتا ہے کہ نماز میں جس طرف چاہے منہ کر لو، لیکن جب معلوم ہوا کہ یہ سفر میں نفل نماز یا قبلہ مشتبہ ہونے کے واقعے میں نازل ہوئی تو اصل مراد روزِ روشن کی طرح واضح ہو گئی''۔', 'علامہ زرکشی کی کتاب ''البرهان فی علوم القرآن'' امام سیوطی کے اتقان سے قبل سب سے عظیم شاہکار سمجھی جاتی ہے۔ اس باب میں ثابت کیا گیا کہ تاریخی سیاق سمجھے بغیر آیات کی تطبیق کرنا شدید گمراہی کا پیش خیمہ بن سکتا ہے۔', '[{"word":"أَمْرٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"معرفة مبتدأ وهو مضاف وأمر خبره"},{"word":"يُورِثُ","role":"فعل مضارع مرفوع","sign":"ضمة","detail":"والجملة الفعلية في محل رفع نعت لأمر"}]', '["البرهان في علوم القرآن، النوع 1، 1/ 22-25، دار إحياء الكتب العربية."]', '{"en":"Imam Az-Zarkashi explains the immense importance of Asbab an-Nuzul: Knowledge of the context generates understanding of the ruling. Verses whose wording seems ambiguous become unmistakably clear once their occasion of descent is identified.","ar":"تحرير أثر أسباب النزول في دفع الإشكالات الفقهية واللغوية عن كتاب الله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('burhan_ch2_ijaz', 'kharji_burhan_zarkashi', 1, 'النَّوْعُ الثَّالِثُ وَالأَرْبَعُونَ: فِي بَيَانِ إِعْجَازِ القُرْآنِ وَوُجُوهِهِ', 'باب 2: اعجازِ قرآن کے وجوہ اور بلاغت کا کمال');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('burhan_seg_2_1', 'burhan_ch2_ijaz', 'kharji_burhan_zarkashi', 0, '«اعْلَمْ أَنَّ إِعْجَازَ القُرْآنِ لَيْسَ فِي وَجْهٍ وَاحِدٍ، بَلْ فِي وُجُوهٍ كَثِيرَةٍ مُتَظَاهِرَةٍ: مِنْهَا فَصَاحَةُ أَلْفَاظِهِ وَبَلَاغَةُ نَظْمِهِ الَّتِي عَجَزَ عَنْهَا فُصَحَاءُ العَرَبِ، وَمِنْهَا مَا انْطَوَى عَلَيْهِ مِنَ الإِخْبَارِ بِالغُيُوبِ المُسْتَقْبَلَةِ، وَمِنْهَا مَا حَوَاهُ مِنَ التَّشْرِيعِ المُحْكَمِ الَّذِي لَا يَأْتِيهِ البَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ، فَبَهَرَ العُقُولَ وَأَفْحَمَ البُلَغَاءَ».', 'زرکشی رحمہ اللہ فرماتے ہیں: ''جان لو کہ قرآن کریم کا معجزہ ہونا کسی ایک پہلو میں منحصر نہیں ہے بلکہ یہ متعدد باہم پیوست وجوہات کا مجموعہ ہے: جن میں اس کے الفاظ کی بے مثال فصاحت اور نظم کی بلاغت ہے جس کے مقابلے سے عرب کے بڑے بڑے خطباء عاجز آ گئے، اس میں مستقبل کی غیب کی سچی خبریں ہیں، اور وہ محکم اور عادلانہ شریعت و احکام ہیں جن میں باطل کا شائبہ تک نہیں، پس اس نے عقلوں کو دنگ کر دیا اور تمام فصحاء کو خاموش کر دیا''۔', 'قرآن کریم صرف عربی فصاحت ہی کا معجزہ نہیں ہے بلکہ اس کے اندر غیبی پیشین گوئیاں، انسانی فطرت کی تسکین اور جامع قوانین ایسی خصوصیات ہیں جو انسانی استطاعت سے ماورا ہیں۔', '[{"word":"إِعْجَازَ","role":"اسم أنّ منصوب","sign":"فتحة ظاهرة","detail":"وهو مضاف والقرآن مضاف إليه"},{"word":"فَصَاحَةُ","role":"مبتدأ مؤخر مرفوع","sign":"ضمة","detail":"منها خبر مقدم وفصاحة مبتدأ"}]', '["البرهان في علوم القرآن، النوع 43، 2/ 90-104."]', '{"en":"The multidimensional facets of Quranic I''jaz (miraculous inimitability): 1. Peerless rhetorical perfection, 2. Foretelling of unseen future events, 3. Incomparable comprehensive legal and ethical legislation.","ar":"استقصاء وجوه إعجاز التنزيل النظمية والتشريعية والغيبية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tibyan_nawawi', 'التِّبْيَانُ فِي آدَابِ حَمَلَةِ القُرْآنِ', 'الإِمَامُ أَبُو زَكَرِيَّا يَحْيَى بْنُ شَرَفٍ النَّوَوِيُّ (ت: 676ھ)', 'kharji_kitab', 'quran', 'آدابِ تلاوت، حفظ و حاملینِ قرآن', 'کتبِ مطالعہ و تربیتِ حفاظ و طلبہ', NULL, NULL, 'from-teal-850 via-emerald-950 to-stone-900', NULL, 'قرآن مجید کے حفظ، تلاوت، اکرام اور تلاوت کرنے والوں کے شب و روز کے اخلاق و احکام پر امام نووی کا بے نظیر رسالہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tibyan_ch1_fadl', 'kharji_tibyan_nawawi', 0, 'البَابُ الأَوَّلُ: فِي فَضِيلَةِ تِلَاوَةِ القُرْآنِ وَحَمَلَتِهِ', 'باب 1: تلاوتِ قرآن اور اہلِ قرآن کی عظیم الشان فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tibyan_seg_1_1', 'tibyan_ch1_fadl', 'kharji_tibyan_nawawi', 0, 'قَالَ الإِمَامُ النَّوَوِيُّ: «عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ». وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ ﷺ: «المَاهِرُ بِالقُرْآنِ مَعَ السَّفَرَةِ الكِرَامِ البَرَرَةِ، وَالَّذِي يَقْرَأُ القُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ».', 'امام محیی الدین یحییٰ بن شرف النووی رحمہ اللہ فرماتے ہیں: حضرت عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''تم میں سے سب سے بہترین شخص وہ ہے جو قرآن سیکھے اور اسے دوسروں کو سکھائے''۔ اور ام المؤمنین حضرت عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''قرآن کا ماہر قاری قیامت کے دن معزز اور اطاعت گزار فرشتوں کے ساتھ ہوگا، اور جو شخص اٹک اٹک کر مشقت کے ساتھ قرآن پڑھتا ہے اس کے لیے دہرا اجر ہے''۔', 'امام نووی کی التبیان تلاوتِ کلام پاک کے آداب اور حاملینِ قرآن کی روحانی تربیت کے لیے عالم اسلام کی سب سے مقبول کتاب ہے۔ اس حدیث میں تلاوت میں کمزور اور محنت کرنے والے کے لیے دہرا اجر بیان کر کے ہمت افزائی فرمائی گئی ہے۔', '[{"word":"خَيْرُكُمْ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"وهو مضاف وكم مضاف إليه"},{"word":"مَنْ","role":"اسم موصول خبر المبتدأ","sign":"مبني على السكون في محل رفع","detail":"تعلم صلة الموصول لا محل لها"}]', '["أخرجه البخاري (5027)، ومسلم (798)، والتبیان في آداب حملة القرآن ص 25."]', '{"en":"The Prophet ﷺ said: ''The best amongst you are those who learn the Quran and teach it.'' And: ''The one who is proficient with the Quran will be with the noble, righteous angel ambassadors; and the one who stumbles through it while it is difficult for him will have a double reward.''","ar":"بيان عظم منزلة قارئ القرآن ومعلمه عند الله ورسوله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tibyan_ch2_adab', 'kharji_tibyan_nawawi', 1, 'البَابُ السَّادِسُ: فِي آدَابِ القِرَاءَةِ وَالتَّرْتِيلِ وَالبُكَاءِ عِنْدَهَا', 'باب 2: آدابِ تلاوت — ترتیل، تدبر اور خشوع و خضوع');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tibyan_seg_2_1', 'tibyan_ch2_adab', 'kharji_tibyan_nawawi', 0, '«يَنْبَغِي لِلتَّالِي أَنْ يَكُونَ شَأْنُهُ الإِخْلَاصَ، وَأَنْ يَسْتَحْضِرَ فِي نَفْسِهِ أَنَّهُ يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ، وَلْيَقْرَأْ عَلَى حَالِ مَنْ يَرَى اللَّهَ، فَإِنْ لَمْ يَكُنْ يَرَاهُ فَإِنَّ اللَّهَ يَرَاهُ. وَيُسْتَحَبُّ لَهُ التَّرْتِيلُ وَالتَّدَبُّرُ، وَالبُكَاءُ مَعَ القِرَاءَةِ، وَذَلِكَ بِأَنْ يَشْغَلَ قَلْبَهُ بِالحُزْنِ وَالخَوْفِ مِمَّا فِيهِ مِنَ الوَعِيدِ الشَّدِيدِ، ثُمَّ يَنْظُرَ إِلَى تَقْصِيرِهِ فِي جَنْبِ اللَّهِ تَعَالَى».', 'امام نووی فرماتے ہیں: ''تلاوت کرنے والے کی پہلی شان اخلاص ہونی چاہیے، اور وہ اپنے دل میں یہ حاضر رکھے کہ وہ اپنے پروردگار عزوجل سے سرگوشی کر رہا ہے، اور وہ اس کیفیت پر تلاوت کرے گویا وہ اللہ کو دیکھ رہا ہے، کیونکہ اگر وہ اللہ کو نہیں دیکھ رہا تو اللہ اسے دیکھ رہا ہے۔ اور قاری کے لیے ترتیل کے ساتھ ٹھہر ٹھہر کر پڑھنا، تدبر کرنا، اور تلاوت کے وقت رونا مستحب ہے؛ اس کا طریقہ یہ ہے کہ وہ قرآن کی سخت وعیدوں سے اپنے دل میں خوف پیدا کرے، پھر اللہ کی جناب میں اپنی کوتاہیوں اور گناہوں کو پیشِ نظر رکھے''۔', 'تلاوت صرف الفاظ ادا کرنے کا نام نہیں بلکہ یہ کلامِ الٰہی سے دلوں کو زندہ کرنے کا عمل ہے۔ امام نووی نے ترتیل اور تدبر کو باطنی بیداری کا بنیادی ذریعہ قرار دیا ہے۔', '[{"word":"الإِخْلَاصَ","role":"خبر كان منصوب","sign":"فتحة","detail":"شأنه اسم كان والإخلاص خبرها"},{"word":"التَّرْتِيلُ","role":"فاعل يستحب مرفوع","sign":"ضمة ظاهرة","detail":"يستحب فعل مبني لما لم يُسمَّ فاعله أو لازم"}]', '["التبیان في آداب حملة القرآن، ص 73-82."]', '{"en":"Imam An-Nawawi outlines the spiritual etiquette of recitation: Sincerity (Ikhlas), consciousness of whispering directly with Allah (Munajah), slow reflective cadence (Tartil), and weeping out of deep awe and acknowledgment of one''s shortcomings.","ar":"حضور القلب وتحقيق مقام الإحسان في تلاوة القرآن الكريم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_mufradat_raghib', 'مُفْرَدَاتُ أَلْفَاظِ القُرْآنِ', 'العَلَّامَةُ أَبُو القَاسِمِ الحُسَيْنُ بْنُ مُحَمَّدٍ الرَّاغِبُ الأَصْفَهَانِيُّ (ت: 502ھ)', 'kharji_kitab', 'quran', 'لغتِ قرآنی و قاموسِ الفاظِ وحی', 'کتبِ مطالعہ و مراجعِ لغت و تفسیر', NULL, NULL, 'from-slate-900 via-stone-900 to-emerald-950', NULL, 'قرآنی الفاظ کی فصاحت، اشتقاق اور دقیق معانی کا مستند ترین لغت۔ ہر طالب علم کے لیے قرآن مجید کے الفاظ کی تفہیم کا ناگزیر کلید۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('raghib_ch1_iman_kufr', 'kharji_mufradat_raghib', 0, 'مَادَّةُ «أَمَنَ»: حَقِيقَةُ الإِيمَانِ وَالأَمَانِ فِي الِاسْتِعْمَالِ القُرْآنِيِّ', 'باب 1: مادۂ ''أمن'' — قرآنی اصطلاح میں ایمان اور امن کی فکری گہرائی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('raghib_seg_1_1', 'raghib_ch1_iman_kufr', 'kharji_mufradat_raghib', 0, 'قَالَ الرَّاغِبُ الأَصْفَهَانِيُّ: «أَصْلُ الأَمْنِ: طُمَأْنِينَةُ النَّفْسِ وَزَوَالُ الخَوْفِ. وَالإِيمَانُ فِي الشَّرْعِ: تَارَةً يُقَالُ لِلِاعْتِقَادِ الحَقِّ المُصَدَّقِ بِالقَلْبِ، وَتَارَةً يُقَالُ لِلشَّرِيعَةِ كُلِّهَا قَوْلاً وَعَمَلاً. وَسُمِّيَ المُؤْمِنُ مُؤْمِناً لِأَنَّهُ أَمِنَ بِإِيمَانِهِ مِنْ عَذَابِ اللَّهِ، أَوْ لِأَنَّهُ أَمَّنَ النَّاسَ مِنْ شَرِّهِ كَمَا قَالَ ﷺ: «المُؤْمِنُ مَنْ أَمِنَهُ النَّاسُ عَلَى دِمَائِهِمْ وَأَمْوَالِهِمْ».', 'امام راغب اصفہانی رحمہ اللہ فرماتے ہیں: ''امن کی اصل بنیاد نفس کا اطمینان اور خوف کا زائل ہونا ہے۔ اور شریعت میں ''ایمان'' کبھی تو دل کے سچے یقین و تصدیق کو کہا جاتا ہے، اور کبھی پوری شریعت (قول و عمل) کے مجموعے پر بولا جاتا ہے۔ اور مؤمن کو مؤمن اس لیے کہا گیا کیونکہ وہ اپنے ایمان کی برکت سے اللہ کے عذاب سے امن میں آ گیا، یا اس لیے کہ لوگ اس کے شر سے مامون ہو گئے جیسا کہ نبی ﷺ نے فرمایا: حقیقی مؤمن وہ ہے جس سے لوگ اپنی جانوں اور اپنے مالوں کے معاملے میں بے خوف اور محفوظ ہوں''۔', 'مفردات القرآن علامہ راغب اصفہانی کی وہ شہرۂ آفاق تصنیف ہے جس نے قرآنی لغت شناسی میں ایک نئی روح پھونکی۔ الفاظ کے اشتقاقی معانی اور قرآنی سیاق کا ایسا باکمال امتزاج پیش کیا گیا ہے جس کی نظیر نہیں۔', '[{"word":"طُمَأْنِينَةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"أصل مبتدأ وطمأنينة خبره"},{"word":"مُؤْمِناً","role":"مفعول به ثان لسمي","sign":"فتحة","detail":"المؤمن الأول نائب فاعل ومؤمناً ثانٍ"}]', '["مفردات ألفاظ القرآن، ص 89-91، تحقيق صفوان داوودي."]', '{"en":"Ar-Raghib Al-Isfahani analyzes the root ''A-M-N'': The origin is soul''s serenity and absence of fear. Religiously, Iman denotes firm heart conviction and the comprehensive embodiment of faith. A believer is termed ''Mu''min'' because he gains security from divine wrath or guarantees safety to humanity.","ar":"التحقيق اللغوي الدقيق لمفردة الإيمان ومشتقاتها في المعجم القرآني."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('raghib_ch2_hikmah', 'kharji_mufradat_raghib', 1, 'مَادَّةُ «حَكَمَ»: مَعْنَى الحِكْمَةِ وَتَمْيِيزُهَا عَنِ العِلْمِ المُجَرَّدِ', 'باب 2: مادۂ ''حکم'' — قرآنی مفہوم میں ''حکمت'' اور علمِ نافع کا فرق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('raghib_seg_2_1', 'raghib_ch2_hikmah', 'kharji_mufradat_raghib', 0, '«الحِكْمَةُ: إِصَابَةُ الحَقِّ بِالعِلْمِ وَالعَمَلِ؛ فَهِيَ مِنَ اللَّهِ تَعَالَى: مَعْرِفَةُ الأَشْيَاءِ وَإِيجَادُهَا عَلَى غَايَةِ الإِحْكَامِ، وَمِنَ الإِنْسَانِ: مَعْرِفَةُ المَوْجُودَاتِ وَفِعْلُ الخَيْرَاتِ، وَهَذَا هُوَ الَّذِي وَصَفَ اللَّهُ بِهِ لُقْمَانَ فَقَالَ: {وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ}. وَكُلُّ مَا يَمْنَعُ الفَسَادَ فَهُوَ حُكْمٌ؛ وَمِنْهُ حَكَمَةُ اللِّجَامِ لِأَنَّهَا تَمْنَعُ الدَّابَّةَ مِنَ الِاضْطِرَابِ».', 'راغب اصفہانی فرماتے ہیں: ''حکمت سے مراد علم اور عمل دونوں کے ذریعے حق تک پہنچنا ہے؛ پس اللہ تعالیٰ کی طرف سے حکمت تمام کائنات کی معرفت اور ان کو انتہائی پختگی اور اتقان کے ساتھ پیدا کرنا ہے، اور انسان کی جانب سے حکمت موجوداتِ کائنات کی حقیقت کو پہچاننا اور نیک کاموں کو انجام دینا ہے؛ اور یہی وہ کمال ہے جس سے اللہ نے حضرت لقمان کو متصف فرما کر فرمایا: {اور بلاشبہ ہم نے لقمان کو حکمت عطا کی}۔ اور ہر وہ چیز جو بگاڑ اور فساد کو روکے اسے ''حکم'' کہا جاتا ہے، اسی سے گھوڑے کی لگام کا وہ حصہ ہے جو اسے سرکشی سے روکتا ہے''۔', 'قرآن کریم میں حکمت صرف تھیوری کا نام نہیں بلکہ علمِ حق کے ساتھ عملِ صالح کی مطابقت کا نام حکمت ہے۔', '[{"word":"إِصَابَةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"الحكمة مبتدأ وإصابة خبره"},{"word":"الحَقِّ","role":"مضاف إليه مجرور","sign":"كسرة","detail":"إصابة مضاف والحق مضاف إليه"}]', '["مفردات ألفاظ القرآن، مادة (حكم)، ص 248."]', '{"en":"Hikmah (Wisdom) in the Quran: Attaining the truth through both knowledge and righteous action. It prevents corruption just as the bridle reins in a steed.","ar":"معنى الحكمة والفرقان في التعبير القرآني وعلاقتها بالعمل."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ahkam_quran_jassas', 'أَحْكَامُ القُرْآنِ لِلْجَصَّاصِ', 'الإِمَامُ أَبُو بَكْرٍ أَحْمَدُ بْنُ عَلِيٍّ الرَّازِيُّ الجَصَّاصُ الحَنَفِيُّ (ت: 370ھ)', 'kharji_kitab', 'fiqh', 'فقہ القرآن و آیاتِ احکام', 'کتبِ مطالعہ و تخصص فی الفقہ والافتاء', NULL, NULL, 'from-amber-950 via-emerald-950 to-stone-900', NULL, 'فقہِ حنفی کی امہات الکتب میں سے۔ قرآن مجید کی آیاتِ احکام سے استنباط، فقہی دلائل اور ائمہ کے مباحث کا بحرِ زخار۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jassas_ch1_wudu', 'kharji_ahkam_quran_jassas', 0, 'بَابُ مَفْرُوضِ الوُضُوءِ وَحَدِّ غَسْلِ الوَجْهِ وَاليَدَيْنِ', 'باب 1: فرائضِ وضو — اعضاء کے دھونے کی حدود اور استنباطی قواعد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jassas_seg_1_1', 'jassas_ch1_wudu', 'kharji_ahkam_quran_jassas', 0, 'قَالَ الإِمَامُ أَبُو بَكْرٍ الجَصَّاصُ الحَنَفِيُّ: «قَالَ اللَّهُ تَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ}. فِيهِ دَلَالَةٌ عَلَى أَنَّ الأَمْرَ بِالغَسْلِ يَقْتَضِي الاسْتِيعَابَ لِأَنَّ اسْمَ الوَجْهِ يَقَعُ عَلَى مَا يُوَاجِهُ بِهِ الإِنْسَانُ، وَأَنَّ الغَايَةَ فِي قَوْلِهِ {إِلَى المَرَافِقِ} دَاخِلَةٌ فِي المَغْسُولِ؛ لِأَنَّ مَا بَعْدَ (إِلَى) إِذَا كَانَ مِنْ جِنْسِ مَا قَبْلَهَا دَخَلَ فِيهِ عِنْدَ جُمْهُورِ أَهْلِ اللُّغَةِ وَالفِقْهِ».', 'امام ابو بکر جصاص حنفی رحمہ اللہ فرماتے ہیں: ''اللہ تعالیٰ کا ارشاد ہے: {اے ایمان والو! جب تم نماز کے لیے کھڑے ہو تو اپنے چہرے دھو لو اور اپنے ہاتھ کہنیوں تک دھو لو}۔ اس آیت میں اس بات کی دلیل ہے کہ دھونے کا حکم پورے عضو کو گھیرنے کا تقاضا کرتا ہے کیونکہ ''وجہ'' (چہرہ) کا اطلاق ہر اس حصے پر ہوتا ہے جس سے انسان کا سامنا ہو۔ اور {کہنیوں تک} میں لفظ ''إلى'' غایت اور انتہا کو ظاہر کرتا ہے جو کہ دھونے میں داخل ہے؛ کیونکہ عربی لغت اور فقہاء کے نزدیک ''إلى'' کے بعد والی چیز جب اسی جنس سے ہو جو پہلے ہے تو وہ حکم میں داخل ہوتی ہے''۔', 'احکام القرآن للجصاص فقہ حنفی کے تفسیری استنباط کا معتبر ترین مرجع ہے۔ جصاص نے ثابت کیا کہ قرآنی نصوص کے ایک ایک حرف اور غایت سے فقہی احکام کس طرح اخذ کیے جاتے ہیں۔', '[{"word":"فَاغْسِلُوا","role":"فعل أمر مبني على حذف النون","sign":"مبني","detail":"والواو فاعل والجملة جواب الشرط"},{"word":"المَرَافِقِ","role":"مجرور بإلى","sign":"كسرة","detail":"داخلة في حكم الغسل"}]', '["أحكام القرآن للجصاص، سورة المائدة، 2/ 420-425."]', '{"en":"Imam Al-Jassas deduces Fiqh from the verse of Wudu: Washing demands complete coverage, and ''unto the elbows'' includes the elbows themselves based on linguistic and legal principles.","ar":"استنباط أحكام الوضوء ودخول الغاية في المغيا عند فقهاء الحنفية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jassas_ch2_riba', 'kharji_ahkam_quran_jassas', 1, 'بَابُ آيَةِ الرِّبَا وَعِلَّةِ التَّحْرِيمِ فِي الأَمْوَالِ الرِّبَوِيَّةِ', 'باب 2: حرمتِ ربا کا قرآنی حکم اور حنفی فقہ میں علتِ سود');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jassas_seg_2_1', 'jassas_ch2_riba', 'kharji_ahkam_quran_jassas', 0, '«قَوْلُهُ تَعَالَى: {وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا}. الرِّبَا فِي اللُّغَةِ هُوَ الزِّيَادَةُ، وَفِي الشَّرْعِ: هُوَ الفَضْلُ الخَالِي عَنِ العِوَضِ المَشْرُوطُ فِي البَيْعِ. وَعِلَّةُ الرِّبَا عِنْدَ أَبِي حَنِيفَةَ وَأَصْحَابِهِ: القَدْرُ مَعَ الجِنْسِ (الكَيْلُ أَوْ الوَزْنُ)، فَإِذَا وُجِدَ الوَصْفَانِ حَرُمَ الفَضْلُ وَالنَّسَاءُ مَعاً، صِيَانَةً لأَمْوَالِ النَّاسِ عَنِ الاسْتِغْلَالِ».', 'جصاص رحمہ اللہ فرماتے ہیں: ''اللہ تعالیٰ کا ارشاد: {اور اللہ نے بیع کو حلال کیا اور سود کو حرام قرار دیا}۔ ربا لغت میں اضافے اور زیادتی کو کہتے ہیں، اور شرعی اصطلاح میں بیع کے اندر کسی عوض کے بغیر طے شدہ مشروط زیادتی کو ربا کہا جاتا ہے۔ اور امام ابو حنیفہ اور ان کے اصحاب کے نزدیک اموالِ ربویہ میں حرمت کی علت دو چیزیں ہیں: ''قدر'' (پیمانہ یا وزن ہونا) اور ''جنس'' (ایک ہی جنس ہونا)؛ پس جب یہ دونوں وصف پائے جائیں تو سود اور ادھار دونوں بیک وقت حرام ہو جاتے ہیں تاکہ لوگوں کے اموال کا استحصال نہ ہو سکے''۔', 'اسلامی بینکاری اور تجارت کے لیے حرمتِ ربا کا یہ اصول بنیاد ہے۔ جصاص نے واضح کیا کہ شریعت نے مال کے بدلے بلا عوض اضافہ لینے کو ظلم قرار دے کر ممانعت فرمائی ہے۔', '[{"word":"البَيْعَ","role":"مفعول به منصوب","sign":"فتحة","detail":"أحل فعل ماض ولفظ الجلالة فاعل"},{"word":"الزِّيَادَةُ","role":"خبر المبتدأ","sign":"ضمة","detail":"الربا مبتدأ أول والزيادة خبر"}]', '["أحكام القرآن للجصاص، 1/ 550-562."]', '{"en":"Imam Al-Jassas explains Riba: It is surplus stipulated in a contract without equivalent countervalue. In Hanafi jurisprudence, the legal effective cause (''Illah) of Riba is measurement by weight/volume coupled with homogeneity of genus.","ar":"تحرير علة الربا الفقهية وصيانة المعاملات المالية من الغبن والاستغلال."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tawil_mushkil_quran', 'تَأْوِيلُ مُشْكِلِ القُرْآنِ', 'الإِمَامُ عَبْدُ اللَّهِ بْنُ مُسْلِمِ بْنِ قُتَيْبَةَ الدِّينَوَرِيُّ (ت: 276ھ)', 'kharji_kitab', 'quran', 'دفاعِ قرآن و حلِ اشکالاتِ لغویہ', 'کتبِ مطالعہ و دفعِ شبہات (متوسط و منتہی طلبہ)', NULL, NULL, 'from-stone-900 via-teal-950 to-emerald-950', NULL, 'قرآن مجید کے الفاظ، اسلوب، استعارات اور نحوی تضاد کے خود ساختہ شبہات کا دندان شکن دفاع اور عربی لغت و بلاغت سے مسکت جوابات۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qutaybah_ch1_bayan', 'kharji_tawil_mushkil_quran', 0, 'بَابُ الرَّدِّ عَلَى مَنِ ادَّعَى التَّنَاقُضَ فِي القُرْآنِ الكَرِيمِ', 'باب 1: قرآنی آیات میں تعارض کے باطل شکوک کا علمی رد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qutaybah_seg_1_1', 'qutaybah_ch1_bayan', 'kharji_tawil_mushkil_quran', 0, 'قَالَ الإِمَامُ ابْنُ قُتَيْبَةَ الدِّينَوَرِيُّ: «زَعَمَ المُلْحِدُونَ وَالطَّاعِنُونَ أَنَّ فِي القُرْآنِ اخْتِلَافاً وَتَنَاقُضاً؛ فَاحْتَجُّوا بِقَوْلِهِ: {فَيَوْمَئِذٍ لَا يُسْأَلُ عَنْ ذَنْبِهِ إِنْسٌ وَلَا جَانٌّ}، مَعَ قَوْلِهِ: {فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ}. وَالجَوَابُ عِنْدَ أَهْلِ العِلْمِ وَاللِّسَانِ: أَنَّ يَوْمَ القِيَامَةِ يَوْمٌ مِقْدَارُهُ خَمْسُونَ أَلْفَ سَنَةٍ، وَفِيهِ مَوَاقِفُ وَأَحْوَالٌ مُتَبَايِنَةٌ؛ فَمَوْقِفٌ لَا يُسْأَلُونَ فِيهِ سُؤَالَ اسْتِفْهَامٍ لِعِلْمِ اللَّهِ بِهِمْ، وَمَوْقِفٌ يُسْأَلُونَ فِيهِ سُؤَالَ تَوْبِيخٍ وَتَقْرِيعٍ».', 'امام ابن قتیبہ دینوری رحمہ اللہ فرماتے ہیں: ''ملحدین اور قرآن پر اعتراض کرنے والوں نے یہ گمان کیا کہ قرآن میں باہمی تضاد ہے؛ انہوں نے بطور دلیل ایک طرف یہ آیت پیش کی: {پس اس دن کسی انسان اور جن سے اس کے گناہ کا سوال نہ ہوگا}، اور دوسری طرف یہ آیت رکھی: {پس تیرے رب کی قسم! ہم ان سب سے ضرور بازپرس کریں گے}۔ اہل علم اور زبان دانوں کے نزدیک اس کا شافی جواب یہ ہے کہ قیامت کا دن پچاس ہزار سال کے برابر طویل دن ہے جس میں مختلف مراحل اور احوال ہوں گے؛ پس ایک موقف وہ ہوگا جس میں معلومات حاصل کرنے کا سوال نہیں ہوگا کیونکہ اللہ ان کے سب کرتوت جانتا ہے، جبکہ دوسرا موقف وہ ہوگا جس میں ملامت، رسوائی اور ڈانٹ ڈپٹ کے طور پر سوال کیا جائے گا''۔', 'ابن قتیبہ نے تیسری صدی ہجری میں ان معترضین کے منہ بند کیے جو عربی اسالیب سے ناواقفیت کی بنیاد پر آیات میں تعارض کا دعویٰ کرتے تھے۔ مختلف مقامات اور احوال کا فرق سمجھنا آیات کا اصل حل ہے۔', '[{"word":"المُلْحِدُونَ","role":"فاعل زعم مرفوع","sign":"واو","detail":"جمع مذكر سالم"},{"word":"سُؤَالَ","role":"مفعول مطلق منصوب","sign":"فتحة","detail":"مبين للنوع"}]', '["تأويل مشكل القرآن، ص 53-56، دار الكتب العلمية."]', '{"en":"Ibn Qutaybah dismantles the alleged contradictions raised by skeptics: The Day of Judgment spans varied epochs—in one phase they are not questioned for information (since Allah is All-Knowing), whereas in another phase they are questioned for reproach and rebuke.","ar":"دفع التعارض الموهوم في مواقف يوم القيامة ومسائل الحساب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qutaybah_ch2_majaz', 'kharji_tawil_mushkil_quran', 1, 'بَابُ مَجَازَاتِ القُرْآنِ وَسُنَنِ العَرَبِ فِي خِطَابِهَا', 'باب 2: قرآنی مجازات اور عربی کلام کے بلیغ اسالیب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qutaybah_seg_2_1', 'qutaybah_ch2_majaz', 'kharji_tawil_mushkil_quran', 0, '«إِنَّمَا نَزَلَ القُرْآنُ بِلِسَانِ العَرَبِ وَعَلَى مَذَاهِبِهِمْ فِي اتِّسَاعِ الكَلَامِ: مِنَ الحَذْفِ وَالإِضْمَارِ، وَالتَّقْدِيمِ وَالتَّأْخِيرِ، وَالِاسْتِعَارَةِ وَالتَّمْثِيلِ؛ فَمَنْ جَهِلَ سُنَنَ العَرَبِ فِي مَنْطِقِهَا أَنْكَرَ مَا لَا يُنْكَرُ، كَقَوْلِهِ تَعَالَى: {جِدَاراً يُرِيدُ أَنْ يَنْقَضَّ}؛ فَإِنَّ الجِدَارَ لَا إِرَادَةَ لَهُ، وَإِنَّمَا اسْتُعِيرَتِ الإِرَادَةُ لِمُقَارَبَةِ السُّقُوطِ كَمَا يَقُولُ العَرَبِيُّ: دَارِي تُطَالِعُ دَارَكَ».', 'ابن قتیبہ فرماتے ہیں: ''قرآن کریم عربی زبان میں اور عرب کے فصیح کلامی اسالیب پر نازل ہوا ہے: جس میں جملوں کا حذف، ضمیروں کا لانا، تقدیم و تاخیر، اور استعارہ و تمثیل شامل ہیں؛ پس جو شخص عرب کے کلامی راستوں اور محاورات سے ناواقف ہو وہ ان باتوں پر بھی اعتراض کر بیٹھتا ہے جو قابل اعتراض نہیں ہوتیں؛ جیسے اللہ تعالیٰ کا فرمان: {ایک دیوار جو گرنے کا ارادہ کر رہی تھی}؛ ظاہر ہے دیوار کا کوئی ارادہ نہیں ہوتا، بلکہ یہاں ارادہ گرنے کے قریب ہونے سے بطورِ استعارہ لایا گیا ہے جیسے عرب کہتے ہیں کہ میرا گھر تیرے گھر کو جھانک رہا ہے''۔', 'اگر استعارات اور مجازات کو لفظی معنی پر محمول کیا جائے تو ادب کا حسن ختم ہو جاتا ہے۔ قرآن کریم نے زبان کے اعلیٰ ترین بلاغتی پیرائے استعمال فرمائے ہیں۔', '[{"word":"بِلِسَانِ","role":"جار ومجرور متعلق بنزل","sign":"كسرة","detail":"وهو مضاف والعرب مضاف إليه"},{"word":"جِدَاراً","role":"مفعول به لفعل محذوف أو موصوف","sign":"فتحة","detail":"في قصة موسى والخضر"}]', '["تأويل مشكل القرآن، باب المجاز، ص 102-105."]', '{"en":"The Quran utilizes Arabic rhetorical expansions: ellipsis, hyperbaton, metaphor, and personification—such as the wall that ''wished to collapse'' in Surah Al-Kahf, which is sublime poetic personification.","ar":"بيان أوجه المجاز والاستعارة وسنن العرب في التعبير القرآني."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_qawaid_hisan_saadi', 'القَوَاعِدُ الحِسَانُ فِي تَفْسِيرِ القُرْآنِ', 'العَلَّامَةُ عَبْدُ الرَّحْمَنِ بْنُ نَاصِرٍ السَّعْدِيُّ (ت: 1376ھ)', 'kharji_kitab', 'tafseer', 'قواعدِ تفسیر و ضوابطِ تدبرِ قرآن', 'کتبِ مطالعہ و تسہیلِ فہمِ قرآن', NULL, NULL, 'from-emerald-900 via-stone-900 to-amber-950', NULL, 'فہمِ قرآن کے ستر جامع اور سنہری قواعد۔ تدبر اور تفسیر کے اصولوں کو عام فہم اور دلنشین انداز میں طلبہ کے ذہن نشین کراتی ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('saadi_ch1_qaida1', 'kharji_qawaid_hisan_saadi', 0, 'القَاعِدَةُ الأُولَى: كَلَامُ اللَّهِ يُفَسِّرُ بَعْضُهُ بَعْضاً وَيُصَدِّقُ بَعْضُهُ بَعْضاً', 'قاعدہ 1: قرآن کریم کا باہمی ربط — ایک آیت دوسری آیت کی تشریح کرتی ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('saadi_seg_1_1', 'saadi_ch1_qaida1', 'kharji_qawaid_hisan_saadi', 0, 'قَالَ الشَّيْخُ عَبْدُ الرَّحْمَنِ بْنُ نَاصِرٍ السَّعْدِيُّ: «مِنْ أَعْظَمِ القَوَاعِدِ فِي التَّفْسِيرِ: أَنَّ القُرْآنَ يُفَسِّرُ بَعْضُهُ بَعْضاً؛ فَمَا أُطْلِقَ فِي مَوْضِعٍ قُيِّدَ فِي مَوْضِعٍ آخَرَ، وَمَا أُجْمِلَ فِي سُورَةٍ فُصِّلَ فِي أُخْرَى. وَالسِّرُّ فِي ذَلِكَ أَنَّ الكَلَامَ صَادِرٌ عَنْ عَلِيمٍ حَكِيمٍ لَا يَخْتَلِفُ قَوْلُهُ وَلَا يَتَنَاقَضُ، فَيَجِبُ عَلَى المُفَسِّرِ أَنْ يَجْمَعَ بَيْنَ الآيَاتِ فِي المَوْضُوعِ الوَاحِدِ قَبْلَ أَنْ يَحْكُمَ».', 'علامہ عبد الرحمن بن ناصر السعدی رحمہ اللہ فرماتے ہیں: ''تفسیر کا سب سے عظیم اصول یہ ہے کہ قرآن کریم کا ایک حصہ دوسرے حصے کی خود تشریح کرتا ہے؛ پس جو حکم ایک جگہ مطلق چھوڑا گیا دوسری جگہ اس کی قید بیان کر دی گئی، اور جو بات ایک سورت میں مجمل تھی دوسری سورت میں اسے کھول کر واضح کر دیا گیا۔ اس کا بنیادی راز یہ ہے کہ یہ سارا کلام اس علیم و حکیم ذات کا نازل کردہ ہے جس کے قول میں نہ کبھی اختلاف ہوتا ہے نہ تضاد، لہٰذا مفسر پر فرض ہے کہ وہ کسی نتیجے پر پہنچنے سے پہلے ایک موضوع کی تمام آیات کو یکجا کرے''۔', 'القواعد الحسان علامہ سعدی کی تصنیف ہے جس میں انہوں نے قرآن فہمی کے ستر سے زائد اصول بیان کیے ہیں۔ یہ قاعدہ مفسر کو تنہا ایک آیت پر جمود کرنے سے بچاتا ہے اور پورے قرآنی نظام کو سامنے رکھنے کی ترغیب دیتا ہے۔', '[{"word":"أَعْظَمِ","role":"مجرور بمن","sign":"كسرة","detail":"شبه الجملة خبر مقدم"},{"word":"أَنَّ القُرْآنَ","role":"مصدر مؤول مبتدأ مؤخر","sign":"في محل رفع","detail":"تقديره: كون القرآن مفسراً"}]', '["القواعد الحسان في تفسير القرآن، ص 15-18، مكتبة الرشد."]', '{"en":"Shaykh As-Sa''di''s Rule 1: The Quran explains itself—what is absolute in one verse is restricted in another, and what is concise is elaborated elsewhere. A commentator must collate all thematic verses before deducing a verdict.","ar":"قاعدة تفسير القرآن بالقرآن وجمع النظائر الموضوعية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('saadi_ch2_qaida10', 'kharji_qawaid_hisan_saadi', 1, 'القَاعِدَةُ العَاشِرَةُ: العِبْرَةُ بِعُمُومِ اللَّفْظِ لَا بِخُصُوصِ السَّبَبِ', 'قاعدہ 2: احکام کی ہمہ گیری — اعتبار لفظ کے عموم کا ہے، سبب کے خاص ہونے کا نہیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('saadi_seg_2_1', 'saadi_ch2_qaida10', 'kharji_qawaid_hisan_saadi', 0, '«إِذَا نَزَلَتِ الآيَةُ عَلَى سَبَبٍ خَاصٍّ، وَكَانَ لَفْظُهَا عَامّاً يَتَنَاوَلُ ذَلِكَ السَّبَبَ وَغَيْرَهُ، فَالوَاجِبُ حَمْلُهَا عَلَى عُمُومِهَا؛ فَإِنَّ القُرْآنَ هِدَايَةٌ لِلأُمَّةِ كُلِّهَا فِي كُلِّ زَمَانٍ، وَتَخْصِيصُهُ بِالشَّخْصِ الَّذِي نَزَلَ فِيهِ يُعَطِّلُ أَكْثَرَ أَحْكَامِ الشَّرِيعَةِ، وَلِذَا كَانَ الصَّحَابَةُ يَقُولُونَ: نَزَلَتْ فِي كَذَا لِلدَّلَالَةِ عَلَى أَنَّهَا تَدْخُلُ فِيهِ لَا لِحَصْرِهَا عَلَيْهِ».', 'علامہ سعدی فرماتے ہیں: ''جب کوئی آیت کسی خاص واقعے کے سبب نازل ہو، لیکن اس کے الفاظ عام ہوں جو اس سبب اور دیگر تمام صورتوں کو شامل کرتے ہوں، تو واجب یہ ہے کہ اس آیت کو اس کے عام مفہوم پر محمول کیا جائے؛ کیونکہ قرآن ہر زمانے کے تمام انسانوں کے لیے ہدایت ہے، اور اگر کسی آیت کو صرف اسی شخص تک محدود کر دیا جائے جس کے بارے میں وہ نازل ہوئی تھی تو شریعت کے اکثر احکام معطل ہو کر رہ جائیں گے، یہی وجہ ہے کہ صحابہ کرام فرماتے تھے کہ یہ آیت فلاں واقعے میں نازل ہوئی تو اس کا مقصد یہ بتانا ہوتا تھا کہ وہ واقعہ اس میں داخل ہے، نہ کہ حکم صرف اسی تک محدود ہے''۔', 'یہ اصول فقہ اسلامی کا ستون ہے۔ اگر لعان، قذف، یا ظہار کی آیات کو صرف مخصوص صحابہ کے واقعات تک محدود مانا جائے تو قیامت تک کے مسلمانوں کے لیے فقہی حل ختم ہو جائیں۔', '[{"word":"الوَاجِبُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"حملها خبر المبتدأ مرفوع"},{"word":"عُمُومِهَا","role":"مجرور بعلى","sign":"كسرة","detail":"والهاء ضمير مضاف إليه"}]', '["القواعد الحسان في تفسير القرآن، ص 34-37."]', '{"en":"Rule 10: Legal weight lies in the generality of the expression, not the specificity of the incident (Al-''Ibratu bi-''Umum al-Lafz la bi-Khusus as-Sabab). This ensures the Quran''s universal applicability across all generations.","ar":"قاعدة الأصوليين الكبرى في عموم الأحكام التشريعية المستنبطة من التنزيل."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_amthal_quran_jawziyyah', 'الأَمْثَالُ فِي القُرْآنِ الكَرِيمِ', 'شَمْسُ الدِّينِ الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'quran', 'قرآنی تمثیلات، امثال و اسرارِ بلاغت', 'کتبِ مطالعہ و تدبر (مفید برائے خطباء و طلبہ)', NULL, NULL, 'from-teal-950 via-emerald-900 to-stone-900', NULL, 'قرآن مجید میں اللہ تعالیٰ نے جو ایمان افروز اور عقل کو جھنجھوڑنے والی مثالیں بیان فرمائی ہیں ان کے معانی، بصائر اور حکمتوں کی دلنشین تشریح۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('amthal_ch1_nar_maa', 'kharji_amthal_quran_jawziyyah', 0, 'المَثَلُ المَائِيُّ وَالنَّارِيُّ فِي صِفَةِ القُلُوبِ وَالمُنَافِقِينَ', 'باب 1: سورت بقرہ میں ناری اور مائی مثالیں — دلوں اور نفاق کی بصیرت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('amthal_seg_1_1', 'amthal_ch1_nar_maa', 'kharji_amthal_quran_jawziyyah', 0, 'قَالَ الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ: «ضَرَبَ اللَّهُ تَعَالَى لِلْمُنَافِقِينَ مَثَلَيْنِ: مَثَلاً نَارِيّاً وَمَثَلاً مَائِيّاً؛ لِمَا فِي النَّارِ وَالمَاءِ مِنَ الحَيَاةِ وَالإِشْرَاقِ. فَأَمَّا المَثَلُ النَّارِيُّ فَفِي قَوْلِهِ: {مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ نَاراً فَلَمَّا أَضَاءَتْ مَا حَوْلَهُ ذَهَبَ اللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِي ظُلُمَاتٍ لَا يُبْصِرُونَ}. فَالنَّارُ تَحْتَاجُ إِلَى حَطَبٍ يُبْقِيهَا، فَلَمَّا انْقَطَعَتِ المَادَّةُ طَفِئَتْ، وَكَذَلِكَ المُنَافِقُ أَضَاءَ لَهُ الإِسْلَامُ فِي الظَّاهِرِ، فَلَمَّا جَاءَ المَوْتُ ذَهَبَ نُورُهُ وَبَقِيَتْ عَلَيْهِ حَسْرَتُهُ».', 'امام ابن قیم الجوزیہ رحمہ اللہ فرماتے ہیں: ''اللہ تعالیٰ نے منافقین کے لیے دو مثالیں بیان فرمائی ہیں: ایک ناری (آگ کی) مثال اور دوسری مائی (پانی کی) مثال؛ کیونکہ آگ اور پانی ہی میں روشنی اور زندگی کا دارومدار ہے۔ آگ کی مثال اس آیت میں ہے: {ان کی مثال اس شخص جیسی ہے جس نے آگ جلائی، پھر جب اس نے اردگرد کی چیزوں کو روشن کر دیا تو اللہ نے ان کا نور چھین لیا اور انہیں تاریکیوں میں چھوڑ دیا جہاں انہیں کچھ سجھائی نہیں دیتا}۔ پس آگ کو برقرار رہنے کے لیے ایندھن درکار ہوتا ہے، جب ایندھن ختم ہو گیا تو آگ بجھ گئی؛ بالکل اسی طرح منافق کے لیے دنیا میں اسلام کے ظاہری کلمے نے روشنی پیدا کی، لیکن جب موت آئی تو وہ عارضی روشنی ختم ہو گئی اور دائمی حسرت و تاریکی باقی رہ گئی''۔', 'ابن قیم نے اپنی کتاب ''امثال القرآن'' میں کلام اللہ کی تمثیلات کی اتنی عمیق روحانی و نفسیاتی تحلیل کی ہے جو دلوں کی گہرائیوں تک اتر جاتی ہے۔ نفاق کی ظاہری چمک اور باطنی اندھیرے کا موازنہ آگ کے شعلے سے بے نظیر ہے۔', '[{"word":"مَثَلَيْنِ","role":"مفعول به منصوب","sign":"ياء","detail":"مثنى مذكر سالم"},{"word":"ذَهَبَ اللَّهُ","role":"فعل ماض وفاعل","sign":"ضمة لفظ الجلالة","detail":"الباء للتعدية في بنورهم"}]', '["الأمثال في القرآن الكريم، ص 21-26، دار المعرفة."]', '{"en":"Ibn al-Qayyim analyzes the fiery and aquatic parables: Fire and water symbolize illumination and life. The hypocrite ignited a temporary kindle by uttering the verbal testimony, but at death the divine light vanished, leaving him in perpetual darkness.","ar":"إعجاز ضرب الأمثال القرآنية في تشخيص أمراض النفاق والقلوب المريضة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('amthal_ch2_nur', 'kharji_amthal_quran_jawziyyah', 1, 'مَثَلُ نُورِ الإِيمَانِ فِي قَلْبِ المُؤْمِنِ (آيَةُ النُّورِ)', 'باب 2: آیہ نور — دلِ مومن میں معرفتِ الٰہی کی قندیل');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('amthal_seg_2_1', 'amthal_ch2_nur', 'kharji_amthal_quran_jawziyyah', 0, '«قَالَ تَعَالَى: {اللَّهُ نُورُ السَّمَاوَاتِ وَالأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ}. شَبَّهَ سُبْحَانَهُ نُورَهُ فِي قَلْبِ عَبْدِهِ المُؤْمِنِ بِالقِنْدِيلِ الصَّافِي: فَالقَلْبُ كَالزُّجَاجَةِ لِصَفَائِهَا وَرِقَّتِهَا وَصَلَابَتِهَا؛ يَصْفُو فَيَرَى الحَقَّ، وَيَرِقُّ فَيَرْحَمُ الخَلْقَ، وَيَصْلُبُ فَيَثْبُتُ فِي دِينِ اللَّهِ. وَالمَادَّةُ الَّتِي يَتَّقِدُ مِنْهَا هِيَ شَجَرَةُ الوَحْيِ المُبَارَكَةِ: زَيْتُونَةٌ لَا شَرْقِيَّةٌ وَلَا غَرْبِيَّةٌ، يَكَادُ زَيْتُهَا يُضِيءُ لِصَفَائِهِ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ؛ نُورٌ عَلَى نُورٍ!».', 'ابن قیم رحمہ اللہ فرماتے ہیں: ''اللہ تعالیٰ کا فرمان ہے: {اللہ آسمانوں اور زمین کا نور ہے، اس کے نور کی مثال ایسی ہے جیسے ایک طاق ہو جس میں چراغ رکھا ہو}۔ اللہ تعالیٰ نے مومن بندے کے دل میں اپنے ایمان و معرفت کے نور کو ایک شفاف قندیل سے تشبیہ دی ہے: پس مؤمن کا دل شیشے کی مانند ہے اپنی صفائی، نزاکت اور مضبوطی میں؛ وہ شفاف ہوتا ہے تو حق کو بے داغ دیکھتا ہے، نرم ہوتا ہے تو مخلوق پر شفقت کرتا ہے، اور سخت و مضبوط ہوتا ہے تو اللہ کے دین پر چٹان کی طرح قائم رہتا ہے۔ اور جس تیل سے وہ چراغ روشن ہوتا ہے وہ وحیِ الٰہی کا مبارک درخت ہے جس کا تیل اپنی شفافیت کی وجہ سے آگ چھوئے بغیر بھی چمکنے کے قریب ہے؛ یعنی فطرت کا نور اور وحی کا نور باہم مل کر نور علیٰ نور بن جاتا ہے!''', 'یہ تفسیری نکتہ ابن قیم کے شاہکار افکار میں سے ہے جہاں انہوں نے دل کی تین صفات (صفا، رقت، صلابت) کا موازنہ چراغ کی شیشے کی قندیل سے کیا ہے۔', '[{"word":"نُورُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"لفظ الجلالة مبتدأ ونور خبره"},{"word":"نُورٌ","role":"خبر لمبتدأ محذوف","sign":"ضمة","detail":"تقديره: ذلك نورٌ على نور"}]', '["الأمثال في القرآن الكريم، ص 45-52، ومدارج السالكين 1/ 340."]', '{"en":"Ibn al-Qayyim''s contemplation of the Verse of Light (Ayat an-Nur): The believer''s heart is compared to a pure glass lamp possessing clarity to witness truth, tenderness to show compassion, and firmness to defend righteousness.","ar":"تحقيق معنى نور الله في قلوب الموحدين واجتماع نور الفطرة مع نور الوحي."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_fazail_quran_faryabi', 'فَضَائِلُ القُرْآنِ وَتِلَاوَتِهِ', 'الإِمَامُ الحَافِظُ جَعْفَرُ بْنُ مُحَمَّدٍ الفِرْيَابِيُّ (ت: 301ھ)', 'kharji_kitab', 'quran', 'فضائلِ تلاوت و برکاتِ حفظِ قرآن', 'کتبِ مطالعہ و ترغیبِ تلاوت (حفاظ و طلبہ)', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-900', NULL, 'قرآن مجید کی سورتوں کے فضائل، تلاوت کے اجر، اور قیامت کے دن قرآن کی شفاعت پر قدیم ترین مسند احادیث کا مستند مجموعہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('faryabi_ch1_thawab', 'kharji_fazail_quran_faryabi', 0, 'بَابُ ثَوَابِ تِلَاوَةِ حُرُوفِ القُرْآنِ وَمُضَاعَفَةِ الحَسَنَاتِ', 'باب 1: حروفِ قرآن کی تلاوت پر دس گنا اجر کا نبوی اعلان');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('faryabi_seg_1_1', 'faryabi_ch1_thawab', 'kharji_fazail_quran_faryabi', 0, 'حَدَّثَنَا الإِمَامُ جَعْفَرُ بْنُ مُحَمَّدٍ الفِرْيَابِيُّ قَالَ: حَدَّثَنَا إِسْحَاقُ بْنُ رَاهَوَيْهِ، عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنْ قَرَأَ حَرْفاً مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ، وَالحَسَنَةُ بِعَشْرِ أَمْثَالِهَا؛ لَا أَقُولُ {الم} حَرْفٌ، وَلَكِنْ: أَلِفٌ حَرْفٌ، وَلَامٌ حَرْفٌ، وَمِيمٌ حَرْفٌ».', 'امام حافظ ابو بکر جعفر بن محمد الفریابی رحمہ اللہ بسندِ متصل حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ ﷺ نے فرمایا: ''جس شخص نے اللہ کی کتاب کا ایک حرف بھی تلاوت کیا تو اس کے بدلے اسے ایک نیکی ملے گی، اور ایک نیکی کا بدلہ دس گنا بڑھا کر دیا جاتا ہے؛ میں یہ نہیں کہتا کہ {الم} ایک حرف ہے، بلکہ ''الف'' الگ حرف ہے، ''لام'' الگ حرف ہے، اور ''میم'' الگ حرف ہے''۔', 'امام فریابی تیسری صدی ہجری کے نامور ائمہ حدیث میں سے ہیں۔ انہوں نے اس کتاب میں فضائلِ قرآن کی مستند روایات جمع کی ہیں۔ اس حدیث سے ظاہر ہوتا ہے کہ صرف تلاوت کرنا بھی اجرِ عظیم کا حامل ہے حتیٰ کہ وہ حروف مقطعات جن کے تفصیلی معانی صرف اللہ جانتا ہے ان پر بھی ہر حرف پر دس نیکیاں ملتی ہیں۔', '[{"word":"مَنْ","role":"اسم شرط جازم مبتدأ","sign":"مبني","detail":"قرأ فعل الشرط فله جوابه"},{"word":"حَرْفاً","role":"مفعول به لقرأ منصوب","sign":"فتحة","detail":"اسم نكرة يدل على العموم"}]', '["فضائل القرآن للفريابي، حديث رقم (1)، وأخرجه الترمذي (2910) وصححه."]', '{"en":"The Messenger of Allah ﷺ said: ''Whoever recites a single letter from the Book of Allah will receive one reward, and each reward is multiplied tenfold. I do not say that Alif-Lam-Mim is one letter, but Alif is a letter, Lam is a letter, and Mim is a letter.''","ar":"الأجر الجزيل المترتب على تلاوة الحروف المفردة من كلام رب العالمين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('faryabi_ch2_shafaah', 'kharji_fazail_quran_faryabi', 1, 'بَابُ شَفَاعَةِ القُرْآنِ لِصَاحِبِهِ يَوْمَ القِيَامَةِ', 'باب 2: قیامت کے ہولناک دن قرآنِ حکیم کی خصوصی شفاعت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('faryabi_seg_2_1', 'faryabi_ch2_shafaah', 'kharji_fazail_quran_faryabi', 0, '«عَنْ أَبِي أُمَامَةَ البَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «اقْرَءُوا القُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ القِيَامَةِ شَفِيعاً لِأَصْحَابِهِ؛ اقْرَءُوا الزَّهْرَاوَيْنِ: البَقَرَةَ وَسُورَةَ آلِ عِمْرَانَ، فَإِنَّهُمَا تَأْتِيَانِ يَوْمَ القِيَامَةِ كَأَنَّهُمَا غَمَامَتَانِ أَوْ غَيَايَتَانِ أَوْ كَأَنَّهُمَا فِرْقَانِ مِنْ طَيْرٍ صَوَافَّ تُحَاجَّانِ عَنْ أَصْحَابِهِمَا».', 'حضرت ابو امامہ باہلی رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ ﷺ کو فرماتے ہوئے سنا: ''قرآن کثرت سے پڑھا کرو کیونکہ وہ قیامت کے دن اپنے پڑھنے والوں کے لیے سفارشی اور شفیع بن کر آئے گا؛ اور دو چمکتی ہوئی سورتیں پڑھا کرو: سورۃ البقرہ اور سورۃ آل عمران، کیونکہ یہ دونوں قیامت کے دن اس حال میں آئیں گی گویا وہ بادلوں کے دو ٹکڑے ہیں یا اڑتے ہوئے پرندوں کی دو قطاریں ہیں جو اپنے پڑھنے والوں کی مغفرت کے لیے اللہ کی بارگاہ میں جھگڑا اور پرزور سفارش کریں گی''۔', 'قرآن کریم اپنے قاری کا وہ مخلص ساتھی ہے جو قبر کی تنہائی سے لے کر میدانِ محشر کی تپش تک اس کا محافظ بنتا ہے اور جب تک اسے جنت میں داخل نہ کروا دے اس کا ساتھ نہیں چھوڑتا۔', '[{"word":"شَفِيعاً","role":"حال منصوب","sign":"فتحة ظاهرة","detail":"يأتي فاعله مستتر وشفيعاً حال"},{"word":"الزَّهْرَاوَيْنِ","role":"مفعول به منصوب","sign":"ياء","detail":"مثنى مؤنث"}]', '["أخرجه مسلم (804)، وفضائل القرآن للفريابي رقم (62)."]', '{"en":"Abu Umamah heard the Messenger of Allah ﷺ say: ''Read the Quran, for it will arrive on the Day of Resurrection as an intercessor for its companions. Read the two shining ones: Al-Baqarah and Al ''Imran... pleading on behalf of their companions.''","ar":"ثبوت شفاعة القرآن والزهراوين لأهلهما عند الموقف العظيم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_iijaz_quran_baqillani', 'إِعْجَازُ القُرْآنِ', 'القَاضِي الإِمَامُ أَبُو بَكْرٍ مُحَمَّدُ بْنُ الطَّيِّبِ البَاقِلَّانِيُّ (ت: 403ھ)', 'kharji_kitab', 'balaghah', 'اعجازِ قرآن و کمالِ بلاغت و فصاحت', 'کتبِ مطالعہ و بلاغتِ عالیہ', NULL, NULL, 'from-blue-950 via-stone-900 to-emerald-950', NULL, 'قرآن مجید کے معجزہ ہونے کے دلائل، فصحائے عرب کی عاجزی اور نظمِ کلام اللہ کی بے مثل بلاغت پر تاریخِ اسلام کی سب سے عمیق تصنیف۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('iijaz_baqillani_ch1_bayan', 'kharji_iijaz_quran_baqillani', 0, 'وُجُوهُ إِعْجَازِ القُرْآنِ وَعَجْزُ فُصَحَاءِ العَرَبِ عَنِ التَّحَدِّي', 'باب 1: اعجازِ قرآن کے دلائل اور عرب کے فصحاء کا قرآنی چیلنج کے سامنے مکمل عاجز ہونا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('iijaz_baqillani_seg_1_1', 'iijaz_baqillani_ch1_bayan', 'kharji_iijaz_quran_baqillani', 0, 'قَالَ القَاضِي الإِمَامُ أَبُو بَكْرٍ البَاقِلَّانِيُّ: «إِنَّ إِعْجَازَ القُرْآنِ يَقُومُ عَلَى ثَلَاثَةِ أَوْجُهٍ قَاطِعَةٍ: الأَوَّلُ: الإِخْبَارُ عَنِ الغُيُوبِ الَّتِي لَا تَقَعُ فِي طَوْقِ البَشَرِ، كَقَوْلِهِ: {الم * غُلِبَتِ الرُّومُ * فِي أَدْنَى الْأَرْضِ وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ}. الثَّانِي: مَا حَوَاهُ مِنْ نَظْمٍ بَدِيعٍ خَارِجٍ عَنْ جَمِيعِ كَلَامِ العَرَبِ؛ فَلَيْسَ بِشِعْرٍ، وَلَا رَجَزٍ، وَلَا سَجْعٍ، مَعَ أَنَّهُمْ أَرْبَابُ الفَصَاحَةِ، وَتَحَدَّاهُمْ بِأَنْ يَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ فَعَجَزُوا. الثَّالِثُ: سَلَامَتُهُ مِنَ التَّنَاقُضِ وَالتَّفَاوُتِ عَلَى طُولِهِ وَتَفَرُّقِ نُزُولِهِ فِي ثَلَاثٍ وَعِشْرِينَ سَنَةً».', 'قاضی امام ابو بکر محمد بن طیب باقلانی رحمہ اللہ فرماتے ہیں: ''قرآن کریم کا معجزہ ہونا تین قطعی اور ٹھوس بنیادوں پر قائم ہے: پہلا پہلو: مستقبل کی غیبی خبریں بیان کرنا جن کا جاننا انسانی طاقت سے بالاتر تھا، جیسے اللہ کا فرمان: {رومی مغلوب ہو گئے، قریبی زمین میں، اور وہ اپنے مغلوب ہونے کے بعد چند سالوں میں ضرور غالب آ جائیں گے}۔ دوسرا پہلو: اس کا وہ بے مثل اور انوکھا اسلوب اور نظم جو عربوں کے تمام کلامی اصناف سے بالکل الگ ہے؛ وہ نہ شعر ہے، نہ رجز ہے اور نہ کاہنوں کا مسجع کلام، حالانکہ اہلِ عرب فصاحت کے بے تاج بادشاہ تھے اور قرآن نے انہیں چیلنج کیا کہ ایک چھوٹی سی سورت ہی بنا لاؤ مگر وہ مکمل طور پر عاجز رہ گئے۔ تیسرا پہلو: تئیس سال کے طویل عرصے میں بکھرے ہوئے نزول اور ضخامت کے باوجود اس کا ہر قسم کے تضاد، کمزوری اور تفاوت سے بالکل پاک اور یکساں بلند پایہ رہنا ہے''۔', 'إعجاز القرآن للقاضي أبي بكر الباقلاني کلامی اور بلاغتی انداز میں اعجازِ قرآن پر لکھی جانے والی تاریخِ اسلام کی سب سے مضبوط اور مدلل کتاب ہے۔', '[{"word":"إِعْجَازَ","role":"اسم إنّ منصوب","sign":"فتحة","detail":"يقوم جملة فعلية خبر إنّ"},{"word":"سَيَغْلِبُونَ","role":"فعل مضارع مرفوع بثبوت النون","sign":"ثبوت النون","detail":"والواو فاعل"}]', '["إعجاز القرآن للباقلاني، ص 33-45، دار المعارف."]', '{"en":"Qadi Abu Bakr al-Baqillani details the tripartite foundations of Quranic Miraculousness (I''jaz): 1. Accurate prophecies of future unseen events, 2. A peerless literary genre transcending all classical Arabic prose, poetry, and rhyme, 3. Flawless linguistic and thematic consistency sustained across 23 years of piecemeal revelation.","ar":"البرهان العقلي والبياني على عجز الفصحاء والبلغاء عن معارضة التنزيل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('iijaz_baqillani_ch2_nazm', 'kharji_iijaz_quran_baqillani', 1, 'المُوَازَنَةُ بَيْنَ فَصَاحَةِ القُرْآنِ وَأَشْعَارِ فُحُولِ الجَاهِلِيَّةِ', 'باب 2: قرآنی بلاغت اور جاہلی شعراء (امراء القیس و زہیر) کے کلام کا تقابلی جائزہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('iijaz_baqillani_seg_2_1', 'iijaz_baqillani_ch2_nazm', 'kharji_iijaz_quran_baqillani', 0, '«عَقَدَ القَاضِي البَاقِلَّانِيُّ مُوَازَنَةً بَدِيعَةً بَيْنَ مُعَلَّقَةِ امْرِئِ القَيْسِ وَبَيْنَ آيَاتِ القُرْآنِ، فَبَيَّنَ أَنَّ أَعْظَمَ شُعَرَاءِ العَرَبِ لَا يَخْلُو كَلَامُهُ مِنْ حَشْوٍ، وَتَكَلُّفٍ، وَقِصَرِ بَاعٍ فِي حَقَائِقِ المَعَانِي؛ بَيْنَمَا تَجِدُ الآيَةَ الوَاحِدَةَ مِنَ القُرْآنِ كَقَوْلِهِ: {وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ وَيَا سَمَاءُ أَقْلِعِي وَغِيضَ الْمَاءُ وَقُضِيَ الْأَمْرُ وَاسْتَوَتْ عَلَى الْجُودِيِّ وَقِيلَ بُعْداً لِلْقَوْمِ الظَّالِمِينَ} قَدِ اشْتَمَلَتْ عَلَى سِتَّةَ عَشَرَ فَنّاً بَلَاغِيّاً فِي سَطْرٍ وَاحِدٍ، يَشْهَدُ لَهَا كُلُّ ذِي ذَوْقٍ بِأَنَّهَا فَوْقَ كَلَامِ البَشَرِ».', 'باقلانی رحمہ اللہ فرماتے ہیں: ''انہوں نے امرؤ القیس کے مشہور معلقے اور قرآنی آیات کا ایسا باکمال تقابل کیا جس سے ثابت ہوا کہ عرب کا سب سے بڑا شاعر بھی اپنے کلام میں فضول الفاظ (حشو)، بناوٹ اور حقائق سے تہی دامن خیالی باتوں سے نہیں بچ سکا؛ جبکہ قرآن کی صرف ایک مختصر آیت مثلاً طوفانِ نوح کا یہ فرمان: {اور حکم دیا گیا کہ اے زمین! اپنا پانی نگل لے، اور اے آسمان! تھم جا، اور پانی خشک کر دیا گیا اور معاملہ تمام ہو گیا اور کشتی کوہِ جودی پر ٹھہر گئی اور کہہ دیا گیا کہ ظالم قوم کے لیے ہلاکت اور دوری ہو!}، اس اکیلی آیت نے صرف ایک سطر کے اندر بلاغت و فصاحت کے سولہ مختلف محاسن (استعارہ، مجاز، ایجاز، مطابقت وغیرہ) کو اس کمال سے جمع کر دیا ہے جس پر ہر ذی شعور پکار اٹھتا ہے کہ یہ انسان کا کلام ہو ہی نہیں سکتا!''', 'آیتِ طوفان پر باقلانی اور سکاکی کی بلاغتی تحقیق ادبِ عربی کا شاہکار مانی جاتی ہے جس نے ثابت کیا کہ زبان کے جملہ کمالات قرآن کے آگے ہیچ ہیں۔', '[{"word":"يَا أَرْضُ","role":"منادى مبني على الضم","sign":"مبني","detail":"نكرة مقصودة"},{"word":"بُعْداً","role":"مفعول مطلق لفعل محذوف منصوب","sign":"فتحة","detail":"يفيد الدعاء والهلاك"}]', '["إعجاز القرآن للباقلاني، ص 140-155."]', '{"en":"Baqillani''s comparative critique: Deconstructing the celebrated Mu''allaqah of Imru'' al-Qays versus the Quranic verse of Noah''s Ark ({O Earth, swallow your water...}). The single Ayah contains 16 rhetorical figures simultaneously, proving divine transcendence.","ar":"التحليل البلاغي لآية الطوفان وبيان تفوق النظم القرآني على معلقات الجاهلية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_asbab_nuzul_wahidi', 'أَسْبَابُ نُزُولِ القُرْآنِ', 'الإِمَامُ أَبُو الحَسَنِ عَلِيُّ بْنُ أَحْمَدَ الوَاحِدِيُّ النَّيْسَابُورِيُّ (ت: 468ھ)', 'kharji_kitab', 'quran', 'شانِ نزول و تاریخِ نزولِ آیات', 'کتبِ مطالعہ و مراجعِ تفسیر', NULL, NULL, 'from-teal-950 via-amber-950 to-stone-900', NULL, 'اسبابِ نزول کا قدیم ترین اور سب سے مستند اصل ماخذ۔ ہر آیت کے نازل ہونے کے پس منظر، سائل کے سوال اور واقعے کی اسانید کے ساتھ تحقیق۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wahidi_ch1_fatihah_baqarah', 'kharji_asbab_nuzul_wahidi', 0, 'سَبَبُ نُزُولِ فَاتِحَةِ الكِتَابِ وَصُدُورِ سُورَةِ البَقَرَةِ', 'باب 1: سورۃ الفاتحہ اور ابتدائی آیاتِ بقرہ کے اسبابِ نزول');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wahidi_seg_1_1', 'wahidi_ch1_fatihah_baqarah', 'kharji_asbab_nuzul_wahidi', 0, 'قَالَ الإِمَامُ أَبُو الحَسَنِ عَلِيُّ بْنُ أَحْمَدَ الوَاحِدِيُّ: «لَا يُمْكِنُ مَعْرِفَةُ تَفْسِيرِ الآيَةِ دُونَ الوُقُوفِ عَلَى قِصَّتِهَا وَبَيَانِ نُزُولِهَا. فَقَوْلُهُ تَعَالَى فِي البَقَرَةِ: {إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُونَ}، نَزَلَتْ فِي مُشْرِكِي قُرَيْشٍ وَيَهُودِ المَدِينَةِ الَّذِينَ أَبَوْا حَسَداً؛ مِثْلِ حُيَيِّ بْنِ أَخْطَبَ وَكَعْبِ بْنِ الأَشْرَفِ، خَتَمَ اللَّهُ عَلَى قُلُوبِهِمْ لَمَّا عَرَفُوا الحَقَّ ثُمَّ اسْتَكْبَرُوا عَنْهُ عِنَاداً».', 'امام ابو الحسن علی بن احمد الواحدی نیشاپوری رحمہ اللہ فرماتے ہیں: ''کسی آیت کی حقیقی تفسیر کو جاننا اس کے تاریخی پس منظر اور سببِ نزول پر مطلع ہوئے بغیر ممکن نہیں۔ پس اللہ تعالیٰ کا فرمان: {یقیناً جن لوگوں نے کفر اختیار کر لیا ان کے حق میں برابر ہے آپ انہیں ڈرائیں یا نہ ڈرائیں وہ ایمان نہیں لائیں گے}، یہ آیت قریش کے ہٹ دھرم مشرکین اور مدینہ کے ان یہودی سرداروں (جیسے حیی بن اخطب اور کعب بن اشرف) کے بارے میں اتری جنہوں نے حسد اور بغض کی وجہ سے حق کو پہچان لینے کے باوجود ضد کا راستہ اپنایا، پس اللہ نے ان کے دلوں پر مہر ثبت فرما دی''۔', 'کتاب ''اسباب النزول'' علامہ واحدی کی وہ اولین اور مستند ترین کتاب ہے جس نے علومِ قرآن میں اس فن کی باقاعدہ بنیاد رکھی۔ واحدی نے واضح کیا کہ جن کافروں پر مہر لگنے کا تذکرہ ہے وہ وہ بدبخت تھے جن کے علم میں حق واضح ہو چکا تھا مگر وہ تکبر و حسد کی وجہ سے انکار پر جمے رہے۔', '[{"word":"سَوَاءٌ","role":"خبر مقدم مرفوع","sign":"ضمة","detail":"وهمزة التسوية وما بعدها مبتدأ مؤخر"},{"word":"عِنَاداً","role":"مفعول لأجله منصوب","sign":"فتحة","detail":"يبين سبب الاستكبار"}]', '["أسباب نزول القرآن للواحدي، ص 12-16، دار الكتب العلمية."]', '{"en":"Imam Al-Wahidi states: It is impossible to fathom the true commentary of an Ayah without apprehending the historical event of its revelation. The verse ''Indeed those who disbelieve...'' specifically addressed obstinate leaders like Huyayy and Ka''b who rejected the truth out of stubborn malice despite recognizing it.","ar":"بيان وجوب معرفة الواقعة التاريخية التي واكبت الخطاب القرآني لفهم المراد."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wahidi_ch2_ayatul_kursi', 'kharji_asbab_nuzul_wahidi', 1, 'سَبَبُ نُزُولِ قَوْلِهِ تَعَالَى: {لَا إِكْرَاهَ فِي الدِّينِ}', 'باب 2: آیۂ ''لَا إِكْرَاهَ فِي الدِّينِ'' کا سببِ نزول اور اسلامی رواداری');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wahidi_seg_2_1', 'wahidi_ch2_ayatul_kursi', 'kharji_asbab_nuzul_wahidi', 0, '«عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَتِ المَرْأَةُ مِنَ الأَنْصَارِ تَكُونُ مِقْلَاتاً (لَا يَعِيشُ لَهَا وَلَدٌ)، فَتَنْذِرُ عَلَى نَفْسِهَا: لَئِنْ عَاشَ لَهَا وَلَدٌ لَتُهَوِّدَنَّهُ! فَلَمَّا أُجْلِيَتْ بَنُو النَّضِيرِ كَانَ فِيهِمْ أَبْنَاءُ الأَنْصَارِ، فَقَالَ آبَاؤُهُمْ مِنَ المُسْلِمِينَ: يَا رَسُولَ اللَّهِ، لَا نَدَعُ أَبْنَاءَنَا يَتَهَوَّدُونَ مَعَهُمْ! فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {لَا إِكْرَاهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ}، فَتَرَكُوهُمْ وَلَمْ يُكْرِهُوهُمْ».', 'حضرت عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے: انصارِ مدینہ کی جس عورت کے بچے زندہ نہ رہتے تو وہ اپنے اوپر یہ نذر مان لیتی تھی کہ اگر میرا بچہ زندہ رہا تو میں اسے یہودی بنا دوں گی (کیونکہ وہ یہود کو اہل کتاب سمجھتی تھیں)! پس جب قبیلہ بنو نضیر کو مدینہ سے جلاوطن کیا گیا تو ان کے ساتھ انصار کے وہ بیٹے بھی جا رہے تھے، انصاری مسلمان والدین نے عرض کیا: یا رسول اللہ! ہم اپنے لختِ جگر بیٹوں کو یہود کے ساتھ دینِ یہودیت پر کیسے جانے دیں، ہم انہیں مجبور کریں گے کہ وہ اسلام قبول کریں! تو اللہ تبارک و تعالیٰ نے یہ آیت نازل فرمائی: {دین کے معاملے میں کوئی زبردستی نہیں ہے، یقیناً ہدایت گمراہی سے بالکل واضح ہو چکی ہے}؛ چنانچہ مسلمانوں نے انہیں آزاد چھوڑ دیا اور اسلام قبول کرنے پر مجبور نہ کیا''۔', 'یہ سببِ نزول اسلامی شریعت کی بلند پایہ اخلاقی عظمت اور عدل کا شاہکار ہے۔ اسلام دل کی سچی تصدیق کا نام ہے، اس لیے کسی پر بھی عقیدے کے معاملے میں جبر کرنا قطعی حرام قرار دیا گیا، حتیٰ کہ اپنے سگے بچوں پر بھی۔', '[{"word":"لَا","role":"نافية للجنس تعمل عمل إنّ","sign":"مبني","detail":"إكراه اسمها مبني على الفتح في محل نصب"},{"word":"قَدْ","role":"حرف تحقيق","sign":"مبني على السكون","detail":"تبين فعل ماض والرشد فاعل مرفوع"}]', '["أسباب النزول للواحدي، ص 68-70، وأخرجه أبو داود (2682) والنسائي (3057) بإسناد صحيح."]', '{"en":"Ibn Abbas reports the noble context of ''There is no compulsion in religion'': Ansar parents had vowed during Jahiliyyah to raise sickly children as Jews. When Banu Nadir were expelled, parents wanted to compel their adult sons to accept Islam, but Allah revealed that faith cannot be forced, embodying profound religious tolerance.","ar":"تجلي العدل والحرية الاعتقادية في الإسلام حتى مع فلذات الأكباد."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_muqaddimah_ibn_salah', 'مَعْرِفَةُ أَنْوَاعِ عِلْمِ الحَدِيثِ (مُقَدِّمَةُ ابْنِ الصَّلَاحِ)', 'الإِمَامُ الحَافِظُ أَبُو عَمْرٍو عُثْمَانُ بْنُ الصَّلَاحِ الشَّهْرَزُورِيُّ (ت: 643ھ)', 'kharji_kitab', 'hadith', 'اصولِ حدیث و علومِ روایت کا دستور', 'کتبِ مطالعہ و اساسِ دورۂ حدیث (جملہ طلبہ)', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'اصولِ حدیث کی وہ عظیم الشان کتاب جس کے بعد آنے والے تمام محدثین (ابن حجر، نووی، سیوطی، عراقی) اسی کے گرد گھومتے ہیں اور اس پر شرحیں لکھتے ہیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('salah_ch1_sahih', 'kharji_muqaddimah_ibn_salah', 0, 'النَّوْعُ الأَوَّلُ: مَعْرِفَةُ الحَدِيثِ الصَّحِيحِ وَشُرُوطِهِ الخَمْسَةِ', 'باب 1: حدیثِ صحیح کی تعریف اور اس کی پانچ بنیادی و لازمی شرائط');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('salah_seg_1_1', 'salah_ch1_sahih', 'kharji_muqaddimah_ibn_salah', 0, 'قَالَ الإِمَامُ ابْنُ الصَّلَاحِ: «الحَدِيثُ الصَّحِيحُ: هُوَ الحَدِيثُ المُسْنَدُ الَّذِي يَتَّصِلُ إِسْنَادُهُ بِنَقْلِ العَدْلِ الضَّابِطِ عَنِ العَدْلِ الضَّابِطِ إِلَى مُنْتَهَاهُ، وَلَا يَكُونُ شَاذّاً، وَلَا مُعَلَّلاً». فَهَذِهِ خَمْسَةُ شُرُوطٍ: اتِّصَالُ السَّنَدِ، وَعَدَالَةُ الرُّوَاةِ، وَضَبْطُ الرُّوَاةِ، وَانْتِفَاءُ الشُّذُوذِ، وَانْتِفَاءُ العِلَّةِ القَادِحَةِ.', 'امام ابو عمرو عثمان بن الصلاح رحمہ اللہ فرماتے ہیں: ''حدیثِ صحیح وہ حدیث ہے جس کی سند اول سے آخر تک عادل اور کامل ضبط والے راوی کی اپنے جیسے عادل اور ضابط راوی سے مسلسل روایت کے ذریعے ملی ہوئی ہو، اور وہ حدیث شاذ اور معلل (پوشیدہ عیب والی) نہ ہو''۔ پس صحتِ حدیث کے پانچ ارکان ہیں: ۱۔ اتصالِ سند، ۲۔ راویوں کی عدالت، ۳۔ راویوں کا پختہ ضبط، ۴۔ شذوذ کی نفی، ۵۔ کسی پوشیدہ نقص و علتِ قادحہ کی نفی۔', 'امام ابن الصلاح کی یہ کتاب علوم الحدیث کا سب سے بڑا دستور ہے جس پر بعد کے تمام ائمہ جیسے نووی، ابن حجر اور سیوطی نے انحصار کیا۔ صحتِ حدیث کا یہ پانچ نکاتی ضابطہ علمی تحقیق کا شاہکار ہے۔', '[{"word":"الصَّحِيحُ","role":"نعت للحديث مرفوع","sign":"ضمة","detail":"هو ضمير فصل أو مبتدأ ثان"}]', '["مقدمة ابن الصلاح، النوع الأول."]', '{"en":"Imam Ibn Al-Salah defines the Sahih Hadith: It is a narration with a continuous chain of trustworthy and precise transmitters without irregularity (Shudhudh) or hidden defect (''Illah).","ar":"التعريف العمدة للحديث الصحيح وشروطه الخمسة التي اتفق عليها جهابذة المحدثين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('salah_ch2_hasan', 'kharji_muqaddimah_ibn_salah', 1, 'النَّوْعُ الثَّانِي: مَعْرِفَةُ الحَدِيثِ الحَسَنِ وَمَرَاتِبِهِ', 'باب 2: حدیثِ حسن کی تعریف، اقسام اور حجیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('salah_seg_2_1', 'salah_ch2_hasan', 'kharji_muqaddimah_ibn_salah', 0, 'قَالَ ابْنُ الصَّلَاحِ: «الحَسَنُ قِسْمَانِ: أَحَدُهُمَا: الحَدِيثُ الَّذِي لَا يَخْلُو رِجَالُ إِسْنَادِهِ مِنْ مَسْتُورٍ لَمْ تَتَحَقَّقْ أَهْلِيَّتُهُ، غَيْرَ أَنَّهُ لَيْسَ مُغَفَّلاً كَثِيرَ الخَطَأِ، وَلَا مُتَّهَماً بِالكَذِبِ، وَقَدْ رُوِيَ نَحْوُهُ مِنْ وَجْهٍ آخَرَ فَيَعْتَضِدُ بِهِ... وَالقِسْمُ الثَّانِي: أَنْ يَكُونَ رَاوِيهِ مَشْهُوراً بِالصِّدْقِ وَالأَمَانَةِ، غَيْرَ أَنَّهُ لَمْ يَبْلُغْ دَرَجَةَ رِجَالِ الصَّحِيحِ فِي الحِفْظِ وَالضَّبْطِ».', 'امام ابن الصلاح فرماتے ہیں: ''حدیثِ حسن کی دو قسمیں ہیں: پہلی قسم وہ ہے جس کی سند میں کوئی مستور الحال راوی ہو لیکن وہ بہت زیادہ غلطیاں کرنے والا یا جھوٹ کے ساتھ متہم نہ ہو، اور وہ حدیث دوسری سندوں سے بھی مروی ہو تو وہ تقویت پا کر حسن لغیرہ بن جاتی ہے؛ اور دوسری قسم (حسن لذاتہ) وہ ہے جس کا راوی سچائی اور امانت میں تو مشہور ہو لیکن حفظ و ضبط کی پختگی میں صحیح کے راویوں کے بلند ترین درجے تک نہ پہنچا ہو''۔', 'حدیثِ حسن صحیح کی بہن ہے اور احکامِ شریعت میں بالاتفاق حجت ہے۔ صحیح اور حسن میں اصل فرق صرف راوی کے حفظ و یادداشت (ضبط) کی باریک کمی بیشی کا ہے۔', '[{"word":"قِسْمَانِ","role":"خبر المبتدأ مرفوع","sign":"ألف المثنى","detail":"الحسن مبتدأ وقسمان خبره"}]', '["مقدمة ابن الصلاح، النوع الثاني."]', '{"en":"Ibn Al-Salah divides Hasan Hadith into two categories: Hasan li-dhatihi (due to a narrator with slightly lighter precision) and Hasan li-ghayrihi (supported by multiple corroborating chains).","ar":"تحرير دقيق لحد الحديث الحسن بين رتبتي الصحيح والضعيف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_nuzhat_nazar_hajar', 'نُزْهَةُ النَّظَرِ فِي تَوْضِيحِ نُخْبَةِ الفِكَرِ', 'أَمِيرُ المُؤْمِنِينَ فِي الحَدِيثِ الحَافِظُ ابْنُ حَجَرٍ العَسْقَلَانِيُّ (ت: 852ھ)', 'kharji_kitab', 'hadith', 'اصولِ حدیث و اصطلاحاتِ محدثین', 'کتبِ مطالعہ و نصابِ مصطلح الحدیث', NULL, NULL, 'from-emerald-900 via-teal-950 to-stone-900', NULL, 'حافظ ابن حجر کا شاہکار۔ مصطلح الحدیث کے قواعد کو ریاضی کی طرح قطعی، مرتب اور استدلالی انداز میں سمیٹنے والی کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nuzhah_ch1_taqsim', 'kharji_nuzhat_nazar_hajar', 0, 'المَبْحَثُ الأَوَّلُ: تَقْسِيمُ الخَبَرِ إِلَى مُتَوَاتِرٍ وَآحَادٍ', 'باب 1: تقسیمِ خبر — متواتر اور آحاد کے اساسی قواعد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nuzhah_seg_1_1', 'nuzhah_ch1_taqsim', 'kharji_nuzhat_nazar_hajar', 0, 'قَالَ الحَافِظُ ابْنُ حَجَرٍ العَسْقَلَانِيُّ: «الخَبَرُ إِمَّا أَنْ يَكُونَ لَهُ طُرُقٌ بِلَا حَصْرٍ، أَوْ بِمَا فَوْقَ الِاثْنَيْنِ، أَوْ بِهِمَا، أَوْ بِوَاحِدٍ. فَالأَوَّلُ: المُتَوَاتِرُ، وَالثَّانِي: المَشْهُورُ، وَالثَّالِثُ: العَزِيزُ، وَالرَّابِعُ: الغَرِيبُ».', 'حافظ ابن حجر عسقلانی رحمہ اللہ فرماتے ہیں: روایت کی راہیں یا تو بے شمار ہوں گی یا دو سے زائد، یا دو، یا ایک۔ پہلی قسم متواتر ہے، دوسری مشہور، تیسری عزیز اور چوتھی غریب ہے۔', 'نخبة الفكر اور اس کی شرح نزهة النظر علومِ حدیث کا وہ مستند ترین متن ہے جس پر پچھلی چھ صدیوں سے تمام مدارس کا مدار رہا ہے۔', '[{"word":"المُتَوَاتِرُ","role":"خبر لمبتدأ محذوف","sign":"ضمة","detail":"تقديره: فالأول المتواتر"}]', '["نزهة النظر، ص 42."]', '{"en":"Classification of reports: Mutawatir, Mashhur, ''Aziz, and Gharib.","ar":"التقسيم المنطقي الحاصر لطرق الحديث."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nuzhah_ch2_sahih', 'kharji_nuzhat_nazar_hajar', 1, 'المَبْحَثُ الثَّانِي: الخَبَرُ المَقْبُولُ وَأَقْسَامُ الصَّحِيحِ وَالحَسَنِ', 'باب 2: خبرِ مقبول — صحیح لذاتہ، صحیح لغیرہ، حسن لذاتہ اور حسن لغیرہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nuzhah_seg_2_1', 'nuzhah_ch2_sahih', 'kharji_nuzhat_nazar_hajar', 0, '«وَخَبَرُ الآحَادِ بِنَقْلِ عَدْلٍ تَامِّ الضَّبْطِ، مُتَّصِلَ السَّنَدِ، غَيْرَ مُعَلَّلٍ وَلَا شَاذٍّ: هُوَ الصَّحِيحُ لِذَاتِهِ، فَإِنْ خَفَّ الضَّبْطُ فَالحَسَنُ لِذَاتِهِ، وَبِكَثْرَةِ الطُّرُقِ يُصْبِحُ صَحِيحاً لِغَيْرِهِ».', 'اور خبرِ واحد جب عادل، کامل ضبط والے راوی کی متصل سند کے ساتھ ہو اور وہ شاذ و معلل نہ ہو تو وہ ''صحیح لذاتہ'' ہے؛ پس اگر ضبط میں معمولی کمی ہو تو ''حسن لذاتہ'' بن جاتی ہے، اور طرق کی کثرت سے یہی حسن ''صحیح لغیرہ'' کے درجے پر فائز ہو جاتی ہے۔', 'حافظ ابن حجر نے نہایت اختصار کے ساتھ حدیثِ مقبول کی چاروں بنیادیں ایک جملے میں سمیٹ دی ہیں۔', '[{"word":"الصَّحِيحُ","role":"خبر المبتدأ","sign":"ضمة","detail":"هو ضمير فصل والصحيح خبر"}]', '["نزهة النظر، ص 58."]', '{"en":"Definitions of Sahih li-dhatihi, Hasan li-dhatihi, and elevation to Sahih li-ghayrihi through multiple corroborating chains.","ar":"تحرير مراتب المقبول في مصطلح الحديث."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tadrib_rawi_suyuti', 'تَدْرِيبُ الرَّاوِي فِي شَرْحِ تَقْرِيبِ النَّوَاوِي', 'الحَافِظُ جَلَالُ الدِّينِ السُّيُوطِيُّ (ت: 911ھ)', 'kharji_kitab', 'hadith', 'اصولِ حدیث، شروح و قواعدِ روایت', 'کتبِ مطالعہ و مراجعِ عالیہ (دورۂ حدیث)', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'امام نووی کے تقریب کی مفصل ترین شرح۔ اصولِ حدیث کی جزئیات، روات کے احوال اور نایاب فوائد پر مشتمل انسائیکلوپیڈیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tadrib_ch1_sahih', 'kharji_tadrib_rawi_suyuti', 0, 'النَّوْعُ الأَوَّلُ: الصَّحِيحُ وَشُرُوطُ العَدَالَةِ وَالضَّبْطِ', 'باب 1: حدیثِ صحیح — راوی کی عدالت اور ضبط کے تحقیقی پیمانے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tadrib_seg_1_1', 'tadrib_ch1_sahih', 'kharji_tadrib_rawi_suyuti', 0, 'قَالَ الإِمَامُ جَلَالُ الدِّينِ السُّيُوطِيُّ: «العَدَالَةُ: مَلَكَةٌ تَحْمِلُ الإِنْسَانَ عَلَى مُلَازَمَةِ التَّقْوَى وَالمُرُوءَةِ، بِحَيْثُ يَجْتَنِبُ الكَبَائِرَ، وَلَا يُصِرُّ عَلَى الصَّغَائِرِ، وَيَبْتَعِدُ عَنْ خَوَارِمِ المُرُوءَةِ».', 'امام جلال الدین سیوطی رحمہ اللہ فرماتے ہیں: ''عدالت انسان کے اندر وہ ملکہ اور اخلاقی پختگی ہے جو اسے ہر وقت تقویٰ اور مروءت پر قائم رکھتی ہے، اس طرح کہ وہ کبیرہ گناہوں سے بالکلیہ بچتا ہو، صغیرہ گناہوں پر اصرار نہ کرتا ہو، اور خلافِ مروءت و وقار کاموں سے دور رہتا ہو''۔', 'محدثین کے ہاں صرف سچائی کافی نہیں تھی بلکہ راوی کا باوقار، متقی اور گناہوں سے پاک ہونا شرط تھا۔', '[{"word":"مَلَكَةٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"العدالة مبتدأ وملكة خبره"}]', '["تدريب الراوي في شرح تقريب النواوي، 1/ 45."]', '{"en":"Imam As-Suyuti defines ''Adalah (probity): A firm inner trait driving the person towards perpetual piety and dignified decorum.","ar":"تحقيق معنى العدالة الشرطية في قبول رواية الحديث."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tadrib_ch2_adab_tahammul', 'kharji_tadrib_rawi_suyuti', 1, 'النَّوْعُ الثَّالِثُ وَالعِشْرُونَ: صِيَغُ الأَدَاءِ وَالتَّحَمُّلِ', 'باب 2: صیغِ ادا اور روایتِ حدیث کے آٹھ مسنون طریقے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tadrib_seg_2_1', 'tadrib_ch2_adab_tahammul', 'kharji_tadrib_rawi_suyuti', 0, '«طُرُقُ تَحَمُّلِ الحَدِيثِ ثَمَانِيَةٌ: السَّمَاعُ مِنْ لَفْظِ الشَّيْخِ، وَالقِرَاءَةُ عَلَيْهِ (العَرْضُ)، وَالإِجَازَةُ، وَالمُنَاوَلَةُ، وَالمُكَاتَبَةُ، وَإِعْلَامُ الشَّيْخِ، وَالوَصِيَّةُ، وَالوِجَادَةُ. وَأَرْفَعُهَا: السَّمَاعُ مِنْ لَفْظِ الشَّيْخِ».', 'حدیث کے حاصل کرنے اور روایت کے آٹھ طریقے ہیں: ۱۔ شیخ کے منہ سے سننا (السماع)، ۲۔ شیخ کے سامنے پڑھ کر سنانا (العرض)، ۳۔ اجازت دینا (الاجازۃ)، ۴۔ کتاب دینا (المناولۃ)، ۵۔ خط کے ذریعے روایت بھیجنا (المکاتبۃ)، ۶۔ شیخ کا آگاہ کرنا (الاعلام)، ۷۔ کتاب کی وصیت کرنا (الوصیۃ)، ۸۔ اور بغیر اجازت کے لکھی ہوئی کتاب پانا (الوجادۃ)؛ اور ان میں سب سے اعلیٰ درجہ شیخ کے مبارک الفاظ کو براہِ راست سننا ہے۔', 'روایت کے اس مکمل اور مفصل نظام نے حدیث کو تحریف، جعل سازی اور ملاوٹ سے ہمیشہ کے لیے محفوظ رکھا۔', '[{"word":"ثَمَانِيَةٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"طرق مبتدأ وثمانية خبره"}]', '["تدريب الراوي، 2/ 5."]', '{"en":"The eight methods of Hadith transmission and reception, with the highest being direct audition from the teacher''s mouth.","ar":"مراتب تحمل الحديث وأداء الرواية في المدارس الإسلامية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_arbaeen_nawawi', 'الأَرْبَعُونَ النَّوَوِيَّةُ فِي الأَحَادِيثِ الصَّحِيحَةِ النَّبَوِيَّةِ', 'الإِمَامُ مُحْيِي الدِّينِ يَحْيَى بْنُ شَرَفٍ النَّوَوِيُّ (ت: 676ھ)', 'kharji_kitab', 'hadith', 'جوامع الکلم اور دین کے بنیادی اصول', 'کتبِ حفظ و مطالعہ (تمام مراحلِ تعلیم)', NULL, NULL, 'from-teal-900 via-emerald-900 to-amber-950', NULL, 'وہ شہرۂ آفاق مجموعۂ احادیث جسے ہر دور میں طلبہ کو حفظ کرایا گیا۔ 42 ایسی احادیث جن پر اسلام کے تمام تر احکام اور اخلاق کی عمارت قائم ہے۔', 8, 8);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch1_niyyah', 'kharji_arbaeen_nawawi', 0, 'الحَدِيثُ الأَوَّلُ: إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ', 'حدیث اول: اعمال کا دارومدار نیتوں پر ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_1', 'arbaeen_ch1_niyyah', 'kharji_arbaeen_nawawi', 0, 'عَنْ أَمِيرِ المُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ».', 'امیر المؤمنین حضرت عمر بن الخطاب رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ ﷺ کو فرماتے سنا: اعمال کا دارومدار نیتوں پر ہے، اور ہر شخص کے لیے وہی ہے جس کی اس نے نیت کی...', 'نیت دین کا ایک تہائی ہے، تمام عبادات و معاملات کی بنیاد اخلاص پر ہے۔', '[{"word":"الأَعْمَالُ","role":"مبتدأ","sign":"ضمة","detail":"مرفوع بالابتداء"}]', '["رواه البخاري ومسلم."]', '{"en":"Actions are judged by intentions...","ar":"قاعدة الإسلام وأصل الأعمال."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch2_jibril', 'kharji_arbaeen_nawawi', 1, 'الحَدِيثُ الثَّانِي: حَدِيثُ جِبْرِيلَ عَلَيْهِ السَّلَامُ فِي مَرَاتِبِ الدِّينِ', 'حدیث دوم: حدیثِ جبرائیل علیہ السلام — اسلام، ایمان اور احسان کے مراتب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_2', 'arbaeen_ch2_jibril', 'kharji_arbaeen_nawawi', 0, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ أَيْضاً قَالَ: «بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ﷺ ذَاتَ يَوْمٍ إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ شَدِيدُ سَوَادِ الشَّعْرِ... فَقَالَ: يَا مُحَمَّدُ أَخْبِرْنِي عَنِ الإِسْلَامِ... قَالَ: فَأَخْبِرْنِي عَنِ الإِيمَانِ... قَالَ: فَأَخْبِرْنِي عَنِ الإِحْسَانِ: قَالَ: أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ... ثُمَّ قَالَ: يَا عُمَرُ، هَذَا جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ».', 'حضرت عمر رضی اللہ عنہ سے روایت ہے: ایک دن ہم رسول اللہ ﷺ کی خدمت میں تھے کہ ایک اجنبی شخص آیا جس کے کپڑے نہایت سفید اور بال نہایت سیاہ تھے... اس نے اسلام، ایمان اور احسان کے بارے میں پوچھا۔ آپ ﷺ نے احسان کے جواب میں فرمایا: ''اللہ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو، ورنہ وہ تو تمہیں دیکھ ہی رہا ہے!'' پھر فرمایا: ''یہ جبرائیل تھے جو تمہیں تمہارا دین سکھانے آئے تھے''۔', 'اسے ام السنہ کہا جاتا ہے کیونکہ اس میں عقائد، اعمال اور تصوف سب کا خلاصہ ہے۔', '[{"word":"جِبْرِيلُ","role":"خبر المبتدأ","sign":"ضمة","detail":"هذا مبتدأ وجبريل خبره"}]', '["رواه مسلم."]', '{"en":"The Hadith of Jibril explaining Islam, Iman, and Ihsan...","ar":"أم السنة وجماع أصول العقيدة والشريعة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch3_arkan', 'kharji_arbaeen_nawawi', 2, 'الحَدِيثُ الثَّالِثُ: بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ', 'حدیث سوم: ارکانِ خمسہ — اسلام کی پانچ مضبوط بنیادیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_3', 'arbaeen_ch3_arkan', 'kharji_arbaeen_nawawi', 0, 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّداً رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ البَيْتِ، وَصَوْمِ رَمَضَانَ».', 'حضرت عبداللہ بن عمر رضی اللہ عنہما نے فرمایا کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''اسلام کی عمارت پانچ ستونوں پر اٹھائی گئی ہے: اس بات کی گواہی دینا کہ اللہ کے سوا کوئی معبود نہیں اور محمد ﷺ اللہ کے رسول ہیں، نماز قائم کرنا، زکوٰۃ ادا کرنا، بیت اللہ کا حج کرنا، اور رمضان کے روزے رکھنا''۔', 'اسلام ایک پرشکوہ محل ہے اور یہ پانچ ارکان اس کے مضبوط ستون ہیں جن کے بغیر عمارت قائم نہیں رہ سکتی۔', '[{"word":"شَهَادَةِ","role":"بدل من خمس","sign":"كسرة","detail":"بدل مجرور"}]', '["رواه البخاري ومسلم."]', '{"en":"Islam is built upon five pillars: Shahadah, Salah, Zakah, Hajj, and fasting Ramadan.","ar":"أركان الإسلام ودعائمه العظام."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch4_khalq', 'kharji_arbaeen_nawawi', 3, 'الحَدِيثُ الرَّابِعُ: أَطْوَارُ خَلْقِ الإِنْسَانِ وَكِتَابَةُ المَقَادِيرِ', 'حدیث چہارم: انسان کی تخلیقی مراحل، تقدیر اور خاتمہ بالخیر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_4', 'arbaeen_ch4_khalq', 'kharji_arbaeen_nawawi', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللَّهِ ﷺ وَهُوَ الصَّادِقُ المَصْدُوقُ: «إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْماً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يُرْسَلُ إِلَيْهِ المَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهِ، وَأَجَلِهِ، وَعَمَلِهِ، وَشَقِيٌّ أَوْ سَعِيدٌ...».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ ہمیں رسول اللہ ﷺ نے بیان فرمایا اور آپ سچے اور سچے مانے ہوئے ہیں: ''تم میں سے ہر ایک کی پیدائش کا مادہ اس کی ماں کے پیٹ میں چالیس دن جمع رہتا ہے، پھر اتنی ہی مدت وہ خون کا لوتھڑا رہتا ہے، پھر اتنی ہی مدت وہ بوٹی رہتا ہے، پھر اللہ فرشتہ بھیجتا ہے جو اس میں روح پھونکتا ہے اور چار باتوں کے لکھنے کا حکم دیا جاتا ہے: اس کا رزق، اس کی عمر، اس کا عمل، اور یہ کہ وہ بدبخت ہوگا یا نیک بخت...''۔', 'یہ حدیث علم الجنین (Embryology) اور عقیدہ تقدیر کا بے مثل اعجاز ہے۔ خاتمہ بالخیر کی دعا ہر مسلمان کو ہر وقت مانگتے رہنا چاہیے۔', '[{"word":"أَرْبَعِينَ","role":"ظرف زمان منصوب","sign":"ياء الجمع","detail":"ملحق بجمع المذكر السالم"}]', '["رواه البخاري ومسلم."]', '{"en":"Stages of human creation in the womb and decree of destiny...","ar":"تقرير عقيدة القدر وأطوار الخلق الإلهي الإعجازي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch5_bidah', 'kharji_arbaeen_nawawi', 4, 'الحَدِيثُ الخَامِسُ: النَّهْيُ عَنِ الِابْتِدَاعِ فِي الدِّينِ', 'حدیث پنجم: دین میں بدعات و اختراعات کی مذمت اور سنت کی اتباع');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_5', 'arbaeen_ch5_bidah', 'kharji_arbaeen_nawawi', 0, 'عَنْ أُمِّ المُؤْمِنِينَ أُمِّ عَبْدِ اللَّهِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ»، وَفِي رِوَايَةٍ لِمُسْلِمٍ: «مَنْ عَمِلَ عَمَلاً لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ».', 'ام المؤمنین حضرت عائشہ صدیقہ رضی اللہ عنہا نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جس نے ہمارے اس دین کے معاملے میں کوئی ایسی نئی بات نکالی جو اس میں سے نہیں ہے تو وہ مردود اور نا مقبول ہے!'' اور مسلم کی روایت میں ہے: ''جس نے کوئی ایسا عمل کیا جس پر ہمارا حکم نہیں ہے تو وہ عمل مردود ہے!''', 'حدیثِ نیت باطنی اعمال کا میزان ہے اور یہ حدیث ظاہری اعمال کا میزان ہے۔ کوئی بھی عمل سنت کے مطابق نہ ہو تو بارگاہِ الٰہی میں ناقابلِ قبول ہے۔', '[{"word":"رَدٌّ","role":"خبر المبتدأ","sign":"ضمة","detail":"هو مبتدأ ورد خبره بمعنى مردود"}]', '["رواه البخاري ومسلم."]', '{"en":"Whoever innovates in this religion of ours what is not part of it, it will be rejected.","ar":"ميزان الأعمال الظاهرة ووجوب الاتباع وحرمة الابتداع."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch6_shubuhat', 'kharji_arbaeen_nawawi', 5, 'الحَدِيثُ السَّادِسُ: الحَلَالُ بَيِّنٌ وَالحَرَامُ بَيِّنٌ وَالوَرَعُ', 'حدیث ششم: حلال و حرام کی وضاحت، مشتبہات سے بچنا اور اصلاحِ قلب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_6', 'arbaeen_ch6_shubuhat', 'kharji_arbaeen_nawawi', 0, 'عَنْ أَبِي عَبْدِ اللَّهِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّ الحَلَالَ بَيِّنٌ، وَإِنَّ الحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الحَرَامِ كَالرَّاعِي يَرْعَى حَوْلَ الحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ... أَلَا وَإِنَّ فِي الجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الجَسَدُ كُلُّهُ، أَلَا وَهِيَ القَلْبُ».', 'حضرت نعمان بن بشیر رضی اللہ عنہما نے فرمایا: میں نے رسول اللہ ﷺ کو فرماتے سنا: ''بے شک حلال بھی واضح ہے اور حرام بھی واضح ہے، اور ان دونوں کے درمیان کچھ مشتبہ چیزیں ہیں جنہیں بہت سے لوگ نہیں جانتے۔ پس جو شخص شبہات سے بچ گیا اس نے اپنے دین اور اپنی عزت کو محفوظ کر لیا، اور جو شبہات میں پڑ گیا وہ حرام میں جا پڑا، اس چرواہے کی مانند جو ممنوعہ چراگاہ کی منڈیر پر جانور چراتا ہے، قریب ہے کہ اس کے جانور چراگاہ کے اندر چرنے لگیں... خبردار! جسم کے اندر گوشت کا ایک ٹکڑا ہے، اگر وہ درست ہو جائے تو پورا جسم درست ہو جاتا ہے، اور اگر وہ بگڑ جائے تو پورا جسم بگڑ جاتا ہے؛ سن لو! وہ دل ہے''۔', 'یہ حدیث فقہ اور تقویٰ کی بنیاد ہے۔ حلال و حرام کی حد بندی اور دل کی پاکیزگی ہی پر پورے انسانی وجود کی سلامتی منحصر ہے۔', '[{"word":"القَلْبُ","role":"خبر المبتدأ","sign":"ضمة","detail":"هي مبتدأ والقلب خبره"}]', '["رواه البخاري ومسلم."]', '{"en":"The Halal is clear and the Haram is clear, and between them are ambiguous matters...","ar":"أصل الورع ومكانة القلب في صلاح الجوارح."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch7_nasihah', 'kharji_arbaeen_nawawi', 6, 'الحَدِيثُ السَّابِعُ: الدِّينُ النَّصِيحَةُ', 'حدیث ہفتم: دین خیر خواہی کا نام ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_7', 'arbaeen_ch7_nasihah', 'kharji_arbaeen_nawawi', 0, 'عَنْ أَبِي رُقَيَّةَ تَمِيمِ بْنِ أَوْسٍ الدَّارِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «الدِّينُ النَّصِيحَةُ»، قُلْنَا: لِمَنْ يَا رَسُولَ اللَّهِ؟ قَالَ: «لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ المُسْلِمِينَ، وَعَامَّتِهِمْ».', 'حضرت تمیم داری رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''دین سراسر خیر خواہی کا نام ہے!'' ہم نے عرض کیا: کس کے لیے یا رسول اللہ؟ آپ ﷺ نے فرمایا: ''اللہ کے لیے، اس کی کتاب کے لیے، اس کے رسول کے لیے، اور مسلمانوں کے حکمرانوں و ائمہ کے لیے، اور عام مسلمانوں کے لیے''۔', 'نصیحت کا مطلب ہے کھوٹ سے پاک خلوص۔ اللہ پر خالص ایمان، قرآن پر عمل، رسول کی اطاعت، حکمرانوں کی رہنمائی اور عامۃ المسلمین کی ہمدردی ہی دینِ اسلام کا خلاصہ ہے۔', '[{"word":"النَّصِيحَةُ","role":"خبر المبتدأ","sign":"ضمة","detail":"الدين مبتدأ والنصيحة خبره"}]', '["رواه مسلم."]', '{"en":"Religion is sincerity and good counsel: to Allah, His Book, His Messenger, leaders of Muslims, and their common folk.","ar":"شعار الإسلام وقوامه في إرادة الخير للأمة جمعاء."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('arbaeen_ch8_hurmat', 'kharji_arbaeen_nawawi', 7, 'الحَدِيثُ الثَّامِنُ: حُرْمَةُ دَمِ المُسْلِمِ وَمَالِهِ', 'حدیث ہشتم: جان و مال کی حرمت اور کلمۂ توحید کی حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('arbaeen_seg_8', 'arbaeen_ch8_hurmat', 'kharji_arbaeen_nawawi', 0, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّداً رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللَّهِ».', 'حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''مجھے حکم دیا گیا ہے کہ میں لوگوں سے قتال کروں یہاں تک کہ وہ اس بات کی گواہی دیں کہ اللہ کے سوا کوئی معبود نہیں اور محمد ﷺ اللہ کے رسول ہیں، اور نماز قائم کریں اور زکوٰۃ ادا کریں؛ پس جب وہ ایسا کر لیں تو انہوں نے مجھ سے اپنی جانوں اور اپنے مالوں کو محفوظ کر لیا، سوائے اسلام کے حق کے، اور ان کا باطنی حساب اللہ کے سپرد ہے''۔', 'اسلام ظاہری اقرار اور نماز و زکوٰۃ کی پابندی پر جان و مال کی مکمل حفاظت کی ضمانت دیتا ہے، دل کا راز اور نیت اللہ کے سپرد ہے۔', '[{"word":"عَصَمُوا","role":"فعل ماض وفاعل","sign":"ضم","detail":"جواب الشرط في إذا فعلوا"}]', '["رواه البخاري ومسلم."]', '{"en":"Sanctity of Muslim life and property upon uttering the Shahadah and fulfilling obligations.","ar":"تقرير حرمة دم المسلم وماله واعتبار الظاهر في الأحكام الدنيوية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_adkhar_nawawi', 'الأَذْكَارُ المُنْتَخَبَةُ مِنْ كَلَامِ سَيِّدِ الأَبْرَارِ', 'الإِمَامُ الحَافِظُ أَبُو زَكَرِيَّا يَحْيَى بْنُ شَرَفٍ النَّوَوِيُّ (ت: 676ھ)', 'kharji_kitab', 'hadith', 'مسنون اذکار، دعائیں اور عاداتِ نبوی ﷺ', 'کتبِ مطالعہ و عملی زندگی کا دستور', NULL, NULL, 'from-emerald-950 via-teal-900 to-stone-900', NULL, 'مسلمان کے شب و روز، بیماری و صحت، سفر و حضر کے تمام مسنون اذکار اور دعاؤں کا مستند ترین ذخیرہ۔ جس کے بارے میں علماء نے کہا: ''بِعِ الدَّارَ وَاشْتَرِ الأَذْكَارَ'' (گھر بیچ کر بھی اذکار خریدو)۔', 4, 4);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adkhar_ch1_fadl', 'kharji_adkhar_nawawi', 0, 'بَابُ الأَمْرِ بِذِكْرِ اللَّهِ تَعَالَى وَفَضْلِهِ', 'باب 1: ذکرِ الٰہی کا حکم اور اس کی بے پایاں فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adkhar_seg_1_1', 'adkhar_ch1_fadl', 'kharji_adkhar_nawawi', 0, 'قَالَ اللَّهُ تَعَالَى: ﴿فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ﴾. وَعَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ، وَأَزْكَاهَا عِنْدَ مَلِيكِكُمْ، وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ، وَخَيْرٍ لَكُمْ مِنْ إِنْفَاقِ الذَّهَبِ وَالوَرِقِ، وَخَيْرٍ لَكُمْ مِنْ أَنْ تَلْقَوْا عَدُوَّكُمْ فَتَضْرِبُوا أَعْنَاقَهُمْ وَيَضْرِبُوا أَعْنَاقَكُمْ؟» قَالُوا: بَلَى، قَالَ: «ذِكْرُ اللَّهِ تَعَالَى».', 'اللہ تعالیٰ کا ارشاد ہے: ''پس تم مجھے یاد کرو، میں تمہیں یاد رکھوں گا، اور میرا شکر ادا کرو اور ناشکری نہ کرو۔'' اور حضرت ابو درداء رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''کیا میں تمہیں تمہارا سب سے بہترین عمل نہ بتاؤں، جو تمہارے بادشاہ (اللہ) کے ہاں سب سے زیادہ پاکیزہ ہے، اور تمہارے درجات کو سب سے زیادہ بلند کرنے والا ہے، اور سونے چاندی کے صدقہ کرنے سے بھی بہتر ہے، اور اس بات سے بھی افضل ہے کہ تم میدانِ جنگ میں دشمن سے ٹکراؤ تم ان کی گردنیں مارو اور وہ تمہاری گردنیں ماریں؟'' صحابہ نے عرض کیا: کیوں نہیں یا رسول اللہ! فرمایا: ''اللہ تعالیٰ کا ذکر!''', 'ذکرِ الٰہی تمام عبادات کی جان ہے۔ زبان کو ذکر سے تر رکھنا انسان کو ہر لمحہ اللہ کے حضور میں رکھتا ہے اور بلا مشقت عظیم ترین درجات عطا کرتا ہے۔', '[{"word":"أَلَا","role":"أداة استفتاح وتحضيض","sign":"مبني","detail":"تفيد التنبيه والتشويق"},{"word":"ذِكْرُ","role":"خبر لمبتدأ محذوف","sign":"ضمة لفظاً","detail":"تقديره: هو ذكر الله"}]', '["أخرجه الترمذي (3377)، وابن ماجه (3790)، وصححه الحاكم."]', '{"en":"Abu Ad-Darda'' reported that the Messenger of Allah ﷺ said: ''Shall I not inform you of the best of your deeds, the purest before your Sovereign, the highest in rank, and better for you than spending gold and silver...?'' They said: ''Yes.'' He said: ''The remembrance of Allah.''","ar":"عظم شأن الذكر وأنه روح الأعمال الصالحة وأيسرها وأعلاها قدراً."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adkhar_ch2_istayqaza', 'kharji_adkhar_nawawi', 1, 'بَابُ مَا يَقُولُ إِذَا اسْتَيْقَظَ مِنْ نَوْمِهِ', 'باب 2: نیند سے بیداری کے مسنون اذکار اور دعائیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adkhar_seg_2_1', 'adkhar_ch2_istayqaza', 'kharji_adkhar_nawawi', 0, 'عَنْ حُذَيْفَةَ بْنِ اليَمَانِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ ﷺ إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ: «بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا»، وَإِذَا اسْتَيْقَظَ مِنْ مَنَامِهِ قَالَ: «الحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ».', 'حضرت حذیفہ بن یمان رضی اللہ عنہما فرماتے ہیں کہ نبی کریم ﷺ جب رات کو اپنے بستر پر تشریف لے جاتے تو یہ دعا پڑھتے: ''اے اللہ! میں تیرے نام کے ساتھ ہی مرتا (سوتا) ہوں اور جیتا (جاگتا) ہوں''؛ اور جب صبح نیند سے بیدار ہوتے تو یہ دعا فرماتے: ''تمام تعریفیں اللہ ہی کے لیے ہیں جس نے ہمیں مارنے (سلانے) کے بعد دوبارہ زندگی بخشی، اور اسی کی طرف سب کو دوبارہ جی اٹھنا ہے''۔', 'نیند موت کی چھوٹی بہن ہے۔ بیدار ہوتے ہی شکرِ خداوندی اور قیامت کے جی اٹھنے کا استحضار انسان کے دن کا آغاز توحید اور آخرت کی یاد سے کرتا ہے۔', '[{"word":"الحَمْدُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"ولله شبه جملة خبر المبتدأ"},{"word":"أَحْيَانَا","role":"فعل ماض وفاعل ومفعول به","sign":"مبني","detail":"والجملة صلة الموصول"}]', '["أخرجه البخاري في صحيحه (6312)."]', '{"en":"Hudhaifah reported that when the Prophet ﷺ went to bed, he said: ''In Your Name, O Allah, I die and live.'' And when he woke up, he said: ''All praise is for Allah Who gave us life after causing us to die, and to Him is the resurrection.''","ar":"النوم أخو الموت، والاستيقاظ تذكير ببعث الأجساد يوم القيامة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adkhar_ch3_sabah_masa', 'kharji_adkhar_nawawi', 2, 'بَابُ أَذْكَارِ الصَّبَاحِ وَالمَسَاءِ الحَافِظَةِ', 'باب 3: صبح و شام کے حفاظتی اذکار اور مسنون حصار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adkhar_seg_3_1', 'adkhar_ch3_sabah_masa', 'kharji_adkhar_nawawi', 0, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَا مِنْ عَبْدٍ يَقُولُ فِي صَبَاحِ كُلِّ يَوْمٍ وَمَسَاءِ كُلِّ لَيْلَةٍ: بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ العَلِيمُ، ثَلَاثَ مَرَّاتٍ، إِلَّا لَمْ يَضُرَّهُ شَيْءٌ».', 'حضرت عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو بھی بندہ ہر صبح اور ہر شام تین مرتبہ یہ کلمات کہہ لے: ''بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ العَلِيمُ'' (اللہ کے نام کے ساتھ جس کے نام کی برکت سے زمین اور آسمان کی کوئی چیز نقصان نہیں پہنچا سکتی، اور وہ خوب سننے والا اور جاننے والا ہے) تو اسے کوئی چیز نقصان نہیں پہنچا سکے گی!''', 'یہ دعا اسمِ اعظم کی برکت سے بندے کے گرد ایک مضبوط روحانی قلعہ بنا دیتی ہے جس میں نہ زہر اثر کر سکتا ہے، نہ جادو، اور نہ کوئی ناگہانی آفت۔', '[{"word":"بِسْمِ","role":"جار ومجرور متعلق بمحذوف","sign":"كسرة","detail":"تقديره: أتحصن باسم الله"},{"word":"شَيْءٌ","role":"فاعل يضر مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالفاعلية"}]', '["أخرجه أبو داود (5088)، والترمذي (3388) وقال: حسن صحيح."]', '{"en":"''Uthman bin ''Affan reported that the Messenger of Allah ﷺ said: ''No servant recites three times every morning and evening: In the Name of Allah with Whose Name nothing can cause harm in earth or heaven, and He is the All-Hearing, All-Knowing, except that nothing will harm him.''","ar":"أعظم أدعية الحفظ والتحصين من الآفات والشرور والسموم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adkhar_ch4_karb', 'kharji_adkhar_nawawi', 3, 'بَابُ دُعَاءِ الكَرْبِ وَالشَّدَائِدِ وَالهُمُومِ', 'باب 4: پریشانی، غم، قرض اور مصیبت کے وقت کی دعائیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adkhar_seg_4_1', 'adkhar_ch4_karb', 'kharji_adkhar_nawawi', 0, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ كَانَ يَقُولُ عِنْدَ الكَرْبِ: «لَا إِلَهَ إِلَّا اللَّهُ العَظِيمُ الحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ العَرْشِ العَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الأَرْضِ وَرَبُّ العَرْشِ الكَرِيمِ».', 'حضرت عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ ﷺ کسی بھی مصیبت، دکھ یا پریشانی کے وقت یہ کلمات فرمایا کرتے تھے: ''اللہ کے سوا کوئی معبود نہیں جو عظمت والا اور بردبار ہے، اللہ کے سوا کوئی معبود نہیں جو عرشِ عظیم کا رب ہے، اللہ کے سوا کوئی معبود نہیں جو آسمانوں کا رب اور زمین کا رب اور عرشِ کریم کا رب ہے''۔', 'پریشانی کے وقت صرف توحید اور اللہ کی صفاتِ کمال کا اقرار ہی دل کو سکون بخشتا ہے، کیونکہ جب انسان عرش اور زمین کے مالک کی طرف متوجہ ہو جاتا ہے تو ہر غم ہیچ نظر آنے لگتا ہے۔', '[{"word":"العَظِيمُ","role":"نعت للفظ الجلالة","sign":"ضمة لفظاً","detail":"والحليم نعت ثان مرفوع"}]', '["متفق عليه: البخاري (6346)، ومسلم (2730)."]', '{"en":"Ibn ''Abbas reported that the Messenger of Allah ﷺ used to supplicate at times of distress: ''None has the right to be worshipped but Allah, the Majestic, the Forbearing; none has the right to be worshipped but Allah, Lord of the Magnificent Throne...''","ar":"دعاء الكرب وتوحيد الربوبية والألوهية عند نزول الهموم والغموم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_bulugh_maram_hajar', 'بُلُوغُ المَرَامِ مِنْ أَدِلَّةِ الأَحْكَامِ', 'الحَافِظُ أَبُو الفَضْلِ أَحْمَدُ بْنُ عَلِيِّ بْنِ حَجَرٍ العَسْقَلَانِيُّ (ت: 852ھ)', 'kharji_kitab', 'hadith', 'احادیثِ احکام، فقہی دلائل و تخریج', 'کتبِ مطالعہ و تخصص فی الفقہ والحدیث', NULL, NULL, 'from-stone-900 via-emerald-950 to-amber-950', NULL, 'فقہائے اسلام کے دلائل پر مشتمل احادیثِ احکام کا سب سے جامع اور معروف مجموعہ، جس میں ہر حدیث کی صحت و ضعف اور راویوں کا حکم بھی ساتھ لکھا ہے۔', 3, 3);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bulugh_ch1_taharah', 'kharji_bulugh_maram_hajar', 0, 'كِتَابُ الطَّهَارَةِ — بَابُ المِيَاهِ وَأَحْكَامِهَا', 'باب 1: کتاب الطہارۃ — پانیوں کی اقسام اور پاکی کے احکام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bulugh_seg_1_1', 'bulugh_ch1_taharah', 'kharji_bulugh_maram_hajar', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ فِي البَحْرِ: «هُوَ الطَّهُورُ مَاؤُهُ، الحِلُّ مَيْتَتُهُ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ رسول اللہ ﷺ نے سمندر کے پانی کے بارے میں ارشاد فرمایا: ''سمندر کا پانی پاک کرنے والا ہے، اور اس کا مردار حلال ہے۔''', 'صحابہ نے سمندر کے سفر کے دوران میٹھے پانی کی کمی کی شکایت کی تو رسول اللہ ﷺ نے اصولی ضابطہ عطا فرمایا کہ سمندر کا کھارا پانی وضو اور غسل کے لیے طہور (پاک کرنے والا) ہے اور اس کی مچھلی حلال ہے۔', '[{"word":"هُوَ","role":"ضمير منفصل مبتدأ","sign":"مبني","detail":"الطهور خبر مقدم وماؤه مبتدأ مؤخر"},{"word":"مَاؤُهُ","role":"فاعل للمصدر أو مبتدأ مؤخر","sign":"ضمة لفظاً","detail":"وهو مضاف والهاء مضاف إليه"}]', '["أخرجه الأربعة وابن أبي شيبة وصححه ابن خزيمة والترمذي."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said regarding the sea: ''Its water is purifying and its dead animals are lawful to eat.''","ar":"أصل عظيم في طهارة ماء البحر وحل صيد البحر وميتته."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bulugh_ch2_salah', 'kharji_bulugh_maram_hajar', 1, 'كِتَابُ الصَّلَاةِ — بَابُ المَوَاقِيتِ وَفَضِيلَتِهَا', 'باب 2: کتاب الصلاۃ — نماز کے اوقات اور اولین وقت کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bulugh_seg_2_1', 'bulugh_ch2_salah', 'kharji_bulugh_maram_hajar', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ ﷺ: أَيُّ العَمَلِ أَحَبُّ إِلَى اللَّهِ تَعَالَى؟ قَالَ: «الصَّلَاةُ عَلَى وَقْتِهَا»، قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: «بِرُّ الوَالِدَيْنِ»، قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: «الجِهَادُ فِي سَبِيلِ اللَّهِ».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ سے دریافت کیا: کون سا عمل اللہ کے ہاں سب سے زیادہ محبوب ہے؟ آپ ﷺ نے فرمایا: ''نماز کو اس کے مقررہ وقت پر ادا کرنا!'' میں نے عرض کیا: پھر کون سا؟ فرمایا: ''والدین کے ساتھ حسن سلوک کرنا!'' میں نے پوچھا: پھر کون سا؟ فرمایا: ''اللہ کی راہ میں جہاد کرنا!''', 'نماز تمام عبادات کا تاج ہے۔ وقت کی پابندی عبودیت کا کمال امتحان ہے، اس لیے شریعت نے فرض نماز کو وقت پر ادا کرنے کو سب سے محبوب عمل قرار دیا۔', '[{"word":"الصَّلَاةُ","role":"مبتدأ أو خبر لمبتدأ محذوف","sign":"ضمة لفظاً","detail":"تقديره: أحب العمل الصلاة"}]', '["متفق عليه: البخاري (527)، ومسلم (85)."]', '{"en":"Ibn Mas''ud reported: I asked the Messenger of Allah ﷺ: Which deed is most beloved to Allah? He replied: ''Prayer at its appointed time.'' I asked: Then what? He said: ''Kindness to parents.'' I asked: Then what? He said: ''Jihad in the cause of Allah.''","ar":"تقديم الصلاة على بر الوالدين والجهاد لكونها عماد الدين ورابطة الصلة بالله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bulugh_ch3_buyu', 'kharji_bulugh_maram_hajar', 2, 'كِتَابُ البُيُوعِ — بَابُ شُرُوطِ البَيْعِ وَالمَنْهِيِّ عَنْهُ', 'باب 3: کتاب البیوع — خرید و فروخت کی شرائط اور ممنوعہ سودے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bulugh_seg_3_1', 'bulugh_ch3_buyu', 'kharji_bulugh_maram_hajar', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: «نَهَى رَسُولُ اللَّهِ ﷺ عَنْ بَيْعِ الحَصَاةِ، وَعَنْ بَيْعِ الغَرَرِ». وَعَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، يَأْتِينِي الرَّجُلُ يُرِيدُ مِنِّي البَيْعَ لَيْسَ عِنْدِي أَفَأَبْتَاعُ لَهُ مِنَ السُّوقِ؟ قَالَ: «لَا تَبِعْ مَا لَيْسَ عِنْدَكَ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے کنکری پھینک کر سودا طے کرنے سے اور دھوکے و مجہول (بیعِ غرر) کے سودے سے منع فرمایا۔ اور حضرت حکیم بن حزام رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کیا: یا رسول اللہ! ایک شخص میرے پاس سودا خریدنے آتا ہے جو میرے پاس موجود نہیں ہوتا، تو کیا میں اس کے لیے بازار سے خرید کر بیچ دوں؟ آپ ﷺ نے فرمایا: ''جو چیز تمہارے پاس (ملکیت و قبضے میں) نہ ہو اسے مت بیچو!''', 'اسلامی معاشیات کا بنیادی اصول شفافیت، انصاف اور دھوکے کا خاتمہ ہے۔ جس چیز کا وجود یا قبضہ یقینی نہ ہو اس کی خرید و فروخت باطل ہے تاکہ تنازعات کا سد باب ہو۔', '[{"word":"لَا","role":"ناهية جازمة","sign":"مبني","detail":"تبع فعل مضارع مجزوم بالسكون وحذفت الياء لالتقاء الساكنين"}]', '["أخرجه مسلم (1513)، وأبو داود (3503)، والترمذي (1232)."]', '{"en":"Abu Hurairah reported: The Messenger of Allah ﷺ prohibited sale by throwing stones and sale of uncertainty (Gharar). And Hakim bin Hizam reported the Prophet said: ''Do not sell what you do not possess.''","ar":"أصل جامع في تحريم الغرر والجهالة والربا وبيع ما لا يملك الإنسان."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_umdat_ahkam_maqdisi', 'عُمْدَةُ الأَحْكَامِ مِنْ كَلَامِ خَيْرِ الأَنَامِ', 'الحَافِظُ تَقِيُّ الدِّينِ عَبْدُ الغَنِيِّ بْنُ عَبْدِ الوَاحِدِ المَقْدِسِيُّ (ت: 600ھ)', 'kharji_kitab', 'hadith', 'متفق علیہ احادیثِ احکام (بخاری و مسلم)', 'کتبِ حفظ و مطالعہ برائے طلبۂ شریعت', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-900', NULL, 'صحیح بخاری اور صحیح مسلم کی ان احادیث کا منتخب گلدستہ جن پر فقہائے اسلام نے طہارت، نماز، زکوۃ، روزہ اور حج کے احکام مرتب فرمائے۔', 3, 3);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('umdah_ch1_taharah', 'kharji_umdat_ahkam_maqdisi', 0, 'كِتَابُ الطَّهَارَةِ — الحَدِيثُ الأَوَّلُ فِي النِّيَّةِ', 'باب 1: کتاب الطہارۃ — نیت کا وجوب اور طہارت کی بنیاد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('umdah_seg_1_1', 'umdah_ch1_taharah', 'kharji_umdat_ahkam_maqdisi', 0, 'عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّةِ، وَإِنَّمَا لِامْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ».', 'حضرت عمر بن الخطاب رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''اعمال کا دارومدار صرف نیت پر ہے، اور ہر شخص کے لیے وہی ہے جس کی اس نے نیت کی...''۔', 'حافظ عبدالغنی مقدسی نے صرف ان احادیث کو جمع کیا ہے جن پر امام بخاری اور امام مسلم دونوں متفق ہیں۔ وضو اور غسل میں نیت کی فرضیت پر فقہاء کا استدلال اسی حدیث سے ہے۔', '[{"word":"بِالنِّيَّةِ","role":"جار ومجرور","sign":"كسرة","detail":"متعلق بمحذوف خبر"}]', '["عمدة الأحكام، الحديث الأول، متفق عليه."]', '{"en":"Umar bin Al-Khattab narrated: I heard Allah''s Messenger ﷺ saying: ''Actions are judged by intentions...''","ar":"افتتح به الحافظ عبد الغني المقدسي كتابه للدلالة على وجوب النية في الطهارة والصلاة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('umdah_ch2_wudu', 'kharji_umdat_ahkam_maqdisi', 1, 'بَابُ صِفَةِ وُضُوءِ النَّبِيِّ ﷺ', 'باب 2: رسول اللہ ﷺ کے مسنون وضو کا تفصیلی طریقہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('umdah_seg_2_1', 'umdah_ch2_wudu', 'kharji_umdat_ahkam_maqdisi', 0, 'عَنْ حُمْرَانَ مَوْلَى عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ: «أَنَّهُ رَأَى عُثْمَانَ دَعَا بِوَضُوءٍ، فَأَفْرَغَ عَلَى يَدَيْهِ مِنْ إِنَائِهِ فَغَسَلَهُمَا ثَلَاثَ مَرَّاتٍ، ثُمَّ أَدْخَلَ يَمِينَهُ فِي الوَضُوءِ، ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ وَاسْتَنْثَرَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثاً، وَيَدَيْهِ إِلَى المِرْفَقَيْنِ ثَلَاثاً، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ رِجْلَيْهِ إِلَى الكَعْبَيْنِ ثَلَاثاً، ثُمَّ قَالَ: رَأَيْتُ النَّبِيَّ ﷺ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا، وَقَالَ: مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا، ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».', 'حضرت عثمان بن عفان رضی اللہ عنہ کے آزاد کردہ غلام حمران سے روایت ہے کہ انہوں نے حضرت عثمان کو دیکھا کہ انہوں نے وضو کا پانی منگوایا، پہلے برتن سے اپنے دونوں ہاتھوں پر پانی ڈال کر تین بار دھویا، پھر دایاں ہاتھ برتن میں ڈال کر کلی کی اور ناک میں پانی چڑھا کر جھاڑا، پھر چہرہ تین بار دھویا، پھر دونوں ہاتھ کہنیوں سمیت تین بار دھوئے، پھر سر کا مسح فرمایا، پھر دونوں پاؤں ٹخنوں سمیت تین بار دھوئے، پھر فرمایا: میں نے نبی کریم ﷺ کو بالکل اسی طرح وضو فرماتے دیکھا، اور آپ ﷺ نے فرمایا: جو شخص میرے اس وضو کی طرح وضو کرے اور پھر دو رکعت نماز اس طرح پڑھے کہ دل میں دنیا کے خیالات نہ لائے تو اس کے پچھلے تمام گناہ معاف کر دیے جاتے ہیں!', 'یہ حدیث فقہِ اسلامی میں مسنون وضو کا سب سے بڑا دستور ہے جس میں ترتیب، اعضاء کا تین تین بار دھونا، اور بعد میں دو رکعت تحیۃ الوضوء کے بے پایاں اجر کا ثبوت ہے۔', '[{"word":"نَحْوَ","role":"مفعول مطلق نائب عن المصدر","sign":"فتحة","detail":"مضاف ووضوئي مضاف إليه"}]', '["متفق عليه: البخاري (159)، ومسلم (226)."]', '{"en":"''Uthman demonstrated the exact ablution of the Prophet ﷺ and conveyed the glad tiding of forgiveness for whoever prays two Rak''ahs without wandering thoughts.","ar":"أجمع وأصح حديث في صفة وضوء رسول الله ﷺ وفضل ركعتي الوضوء."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('umdah_ch3_salah_musi', 'kharji_umdat_ahkam_maqdisi', 2, 'كِتَابُ الصَّلَاةِ — حَدِيثُ المُسِيءِ صَلَاتَهُ', 'باب 3: کتاب الصلاۃ — تعدیلِ ارکان اور نماز میں اطمینان کا وجوب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('umdah_seg_3_1', 'umdah_ch3_salah_musi', 'kharji_umdat_ahkam_maqdisi', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: «أَنَّ رَسُولَ اللَّهِ ﷺ دَخَلَ المَسْجِدَ، فَدَخَلَ رَجُلٌ فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ عَلَى رَسُولِ اللَّهِ ﷺ، فَرَدَّ عَلَيْهِ رَسُولُ اللَّهِ ﷺ السَّلَامَ، فَقَالَ: ارْجِعْ فَصَلِّ، فَإِنَّكَ لَمْ تُصَلِّ، فَرَجَعَ فَصَلَّى كَمَا صَلَّى، ثُمَّ جَاءَ فَسَلَّمَ... فَقَالَ فِي الثَّالِثَةِ: وَالَّذِي بَعَثَكَ بِالحَقِّ مَا أُحْسِنُ غَيْرَهُ فَعَلِّمْنِي! فَقَالَ ﷺ: إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ، ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ القُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعاً، ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِماً، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِداً... ثُمَّ افْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص مسجد میں آیا اور جلدی جلدی نماز پڑھ کر نبی کریم ﷺ کو سلام کیا۔ آپ ﷺ نے فرمایا: ''واپس جاؤ اور دوبارہ نماز پڑھو، کیونکہ تم نے نماز نہیں پڑھی!'' اس نے تین بار ایسا کیا، پھر عرض کیا: اس ذات کی قسم جس نے آپ کو حق کے ساتھ بھیجا، میں اس سے بہتر نہیں جانتا، آپ مجھے سکھا دیجیے! آپ ﷺ نے فرمایا: ''جب تم نماز کے لیے کھڑے ہو تو تکبیر کہو، پھر قرآن سے جو آسان ہو تلاوت کرو، پھر رکوع کرو یہاں تک کہ رکوع میں اطمینان پا لو، پھر سر اٹھاؤ یہاں تک کہ سیدھے کھڑے ہو جاؤ، پھر سجدہ کرو یہاں تک کہ سجدے میں اطمینان حاصل ہو جائے... پھر اپنی پوری نماز میں اسی طرح کرو''۔', 'نماز میں رکوع، سجدے اور قومے میں تعدیلِ ارکان (اطمینان) فرض اور واجب ہے۔ کوے کی طرح ٹھونگیں مارنے سے نماز باطل ہو جاتی ہے۔', '[{"word":"تَطْمَئِنَّ","role":"فعل مضارع منصوب بأن مضمرة بعد حتى","sign":"فتحة","detail":"فاعله مستتر تقديره أنت"}]', '["متفق عليه: البخاري (757)، ومسلم (397)."]', '{"en":"The Hadith of the man who prayed improperly: The Prophet ﷺ taught him the necessity of tranquility (Ta''dil al-Arkan) in bowing and prostration.","ar":"وجوب الطمأنينة وتعديل الأركان في الصلاة وبطلان صلاة من ينقرها نقر الغراب."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_jami_saghir_suyuti', 'الجَامِعُ الصَّغِيرُ مِنْ حَدِيثِ البَشِيرِ النَّذِيرِ', 'الحَافِظُ جَلَالُ الدِّينِ السُّيُوطِيُّ (ت: 911ھ)', 'kharji_kitab', 'hadith', 'معجمِ احادیثِ نبویہ بروایتِ حروفِ تہجی', 'کتبِ مطالعہ و مراجعِ تخریجِ حدیث', NULL, NULL, 'from-stone-900 via-teal-950 to-emerald-950', NULL, 'دس ہزار سے زائد مختصر اور جامع ارشاداتِ نبویہ کا وہ گلدستہ جو حروفِ تہجی کے مطابق مرتب ہے، جس سے ہر حدیث کو سیکنڈوں میں تلاش کیا جا سکتا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('saghir_ch1_alif', 'kharji_jami_saghir_suyuti', 0, 'حَرْفُ الأَلِفِ — جَوَامِعُ الكَلِمِ فِي الإِيمَانِ وَالإِخْلَاصِ', 'باب 1: حرف الف — ایمان، اخلاص اور عمل کے نبوی اصول');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('saghir_seg_1_1', 'saghir_ch1_alif', 'kharji_jami_saghir_suyuti', 0, 'قَالَ رَسُولُ اللَّهِ ﷺ: «أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ تَعَالَى أَدْوَمُهَا وَإِنْ قَلَّ». وَقَالَ ﷺ: «أَفْضَلُ الجِهَادِ كَلِمَةُ عَدْلٍ عِنْدَ سُلْطَانٍ جَائِرٍ». وَقَالَ ﷺ: «أَكْمَلُ المُؤْمِنِينَ إِيمَاناً أَحْسَنُهُمْ خُلُقاً».', 'رسول اللہ ﷺ نے ارشاد فرمایا: ''اللہ تعالیٰ کے نزدیک سب سے پسندیدہ عمل وہ ہے جس پر ہمیشگی کی جائے اگرچہ وہ مقدار میں تھوڑا ہی ہو!'' اور فرمایا: ''سب سے افضل جہاد ظالم اور جابر بادشاہ کے سامنے انصاف اور حق کی بات کہنا ہے!'' اور فرمایا: ''مومنوں میں سب سے کامل ایمان والا وہ شخص ہے جس کے اخلاق سب سے اچھے ہوں!''', 'امام سیوطی نے حروفِ تہجی کی ترتیب پر دس ہزار سے زائد احادیث جمع فرمائیں۔ اس باب میں مداومتِ عمل، جراتِ حق گوئی اور حسنِ اخلاق کو ایمان کا کمال قرار دیا گیا ہے۔', '[{"word":"أَحَبُّ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"اسم تفضيل وأدومها خبره"}]', '["أخرجه البخاري ومسلم والترمذي وأبو داود."]', '{"en":"The Messenger of Allah ﷺ said: ''The most beloved deeds to Allah are those that are most consistent, even if small.'' And: ''The best Jihad is a word of truth before a tyrannical ruler.'' And: ''The most complete in faith are the best in character.''","ar":"من جوامع الكلم المبدوءة بحرف الألف في الجامع الصغير للإمام السيوطي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('saghir_ch2_ta', 'kharji_jami_saghir_suyuti', 1, 'حَرْفُ التَّاءِ — التَّقْوَى وَالتَّوْبَةُ وَالتَّوَاضُعُ', 'باب 2: حرف ت — تقویٰ، توبہ اور تواضع کی جامع احادیث');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('saghir_seg_2_1', 'saghir_ch2_ta', 'kharji_jami_saghir_suyuti', 0, 'قَالَ رَسُولُ اللَّهِ ﷺ: «التَّائِبُ مِنَ الذَّنْبِ كَمَنْ لَا ذَنْبَ لَهُ». وَقَالَ ﷺ: «التَّوَاضُعُ لَا يَزِيدُ العَبْدَ إِلَّا رِفْعَةً، فَتَوَاضَعُوا يَرْفَعْكُمُ اللَّهُ». وَقَالَ ﷺ: «تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ».', 'رسول اللہ ﷺ نے فرمایا: ''گناہ سے سچی توبہ کرنے والا ایسا ہے گویا اس نے گناہ کیا ہی نہیں!'' اور فرمایا: ''عاجزی و انکساری بندے کی عزت و رفعت میں ہی اضافہ کرتی ہے، پس تواضع اختیار کرو اللہ تمہیں بلند فرما دے گا!'' اور فرمایا: ''اپنے مسلمان بھائی کے سامنے تمہارا مسکرا دینا بھی تمہارے لیے صدقہ ہے!''', 'توبہ سے گناہ یکسر دھل جاتے ہیں، عاجزی سے انسان کا وقار بلند ہوتا ہے اور مسکراہٹ دلوں سے کینہ دور کرتی ہے۔', '[{"word":"التَّائِبُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"كمن شبه جملة خبر"}]', '["أخرجه ابن ماجه والترمذي."]', '{"en":"The Prophet ﷺ said: ''The one who repents from sin is like one without sin.'' And: ''Humility only increases a servant in elevation, so be humble and Allah will elevate you.'' And: ''Your smile in the face of your brother is charity.''","ar":"درر نبوية جامعة في تزكية النفس وإشاعة المودة بين المسلمين."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_qawaid_tahdith_qasimi', 'قَوَاعِدُ التَّحْدِيثِ مِنْ فُنُونِ مُصْطَلَحِ الحَدِيثِ', 'العَلَّامَةُ مُحَمَّدُ جَمَالُ الدِّينِ القَاسِمِيُّ الدِّمَشْقِيُّ (ت: 1332ھ)', 'kharji_kitab', 'hadith', 'اصولِ حدیث و تجدیدِ فہمِ سنت', 'کتبِ مطالعہ و فکرِ حدیث (طلبۂ عالیہ و عالمیہ)', NULL, NULL, 'from-amber-900 via-stone-900 to-teal-950', NULL, 'اصولِ حدیث کی کلاسیکی روح اور عصرِ حاضر کے علمی مطالبات کا امتزاج۔ محدثین کی اصطلاحات کی گہری تفہیم پر لکھی گئی وقیع کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qasimi_ch1_hajah', 'kharji_qawaid_tahdith_qasimi', 0, 'حَاجَةُ الأُمَّةِ إِلَى السُّنَّةِ وَعُلُومِ الإِسْنَادِ', 'باب 1: امت کی سنت سے وابستگی اور علمِ اسناد کی اختصاصی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qasimi_seg_1_1', 'qasimi_ch1_hajah', 'kharji_qawaid_tahdith_qasimi', 0, 'قَالَ العَلَّامَةُ جَمَالُ الدِّينِ القَاسِمِيُّ: «الإِسْنَادُ خَصِيصَةٌ فَاضِلَةٌ مِنْ خَصَائِصِ هَذِهِ الأُمَّةِ، قَالَ ابْنُ المُبَارَكِ: الإِسْنَادُ مِنَ الدِّينِ، وَلَوْلَا الإِسْنَادُ لَقَالَ مَنْ شَاءَ مَا شَاءَ».', 'علامہ جمال الدین قاسمی رحمہ اللہ فرماتے ہیں: ''اسناد (روایت کا سلسلہ بیان کرنا) اس امتِ محمدیہ کی ایسی بے نظیر خصوصیت ہے جو دنیا کی کسی دوسری قوم کو نصیب نہیں ہوئی۔ امام عبداللہ بن مبارک نے فرمایا: اسناد دین کا حصہ ہے، اور اگر اسناد کا نظام نہ ہوتا تو جس کا جو جی چاہتا دین کے نام پر کہہ دیتا!''', 'دنیا کی کسی تاریخ کے پاس اسناد اور جرح و تعدیل جیسا بے لاگ تحقیقی نظام موجود نہیں ہے۔ مسلمانوں نے رسول اللہ ﷺ کے ایک ایک لفظ کو اسناد کے ذریعے محفوظ کیا۔', '[{"word":"الإِسْنَادُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"خصيصة خبر المبتدأ"}]', '["قواعد التحديث من فنون مصطلح الحديث، ص 25."]', '{"en":"Al-Qasimi notes: The Isnad (chain of transmission) is a unique, unrivaled glory of this Ummah, safeguarding religion from fabricated claims.","ar":"أهمية الإسناد في صيانة الدين الإسلامي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qasimi_ch2_naqd', 'kharji_qawaid_tahdith_qasimi', 1, 'قَوَاعِدُ نَقْدِ الحَدِيثِ سَنَداً وَمَتْناً', 'باب 2: سند اور متن دونوں کی تنقید اور جانچ پڑتال کے اصول');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qasimi_seg_2_1', 'qasimi_ch2_naqd', 'kharji_qawaid_tahdith_qasimi', 0, '«لَمْ يَكْتَفِ المُحَدِّثُونَ بِنَقْدِ الرِّجَالِ وَالسَّنَدِ فَقَطْ، بَلْ وَضَعُوا مَعَايِيرَ صَارِمَةً لِنَقْدِ المَتْنِ: أَنْ لَا يُخَالِفَ صَرِيحَ القُرْآنِ، وَلَا السُّنَّةَ المُتَوَاتِرَةَ، وَلَا العَقْلَ الصَّرِيحَ، وَلَا التَّارِيخَ القَطْعِيَّ المَعْلُومَ».', 'محدثینِ کرام نے صرف سند اور راویوں کی جانچ پڑتال پر ہی اکتفا نہیں کیا، بلکہ متن کی جانچ کے لیے بھی نہایت کڑے اصول قائم کیے: کہ حدیث کا متن قرآن کے صریح حکم، متواتر سنت، عقلِ سلیم، اور قطعی و ثابت شدہ تاریخی حقائق کے خلاف نہ ہو۔', 'مستشرقین اور منکرینِ حدیث کے اس اعتراض کا دندان شکن جواب ہے کہ محدثین صرف سند دیکھتے تھے؛ درحقیقت محدثین نے متن کے معانی پر بھی کڑا نقد قائم کیا۔', '[{"word":"لَمْ يَكْتَفِ","role":"فعل مضارع مجزوم بلم","sign":"حذف حرف العلة","detail":"المحدثون فاعل مرفوع بالواو"}]', '["قواعد التحديث، ص 115."]', '{"en":"Hadith scholars formulated rigorous criteria for Matn (textual) critique alongside Isnad critique.","ar":"بيان شمول النقد الحديثي للسند والمتن معاً."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tawjih_nazar_jazairi', 'تَوْجِيهُ النَّظَرِ إِلَى أُصُولِ الأَثَرِ', 'العَلَّامَةُ الشَّيْخُ طَاهِرُ بْنُ صَالِحٍ الجَزَائِرِيُّ الدِّمَشْقِيُّ (ت: 1338ھ)', 'kharji_kitab', 'hadith', 'اصولِ حدیث و اصطلاحاتِ ائمۂ نقد', 'کتبِ مطالعہ و تحقیق (طلبۂ حدیث)', NULL, NULL, 'from-emerald-950 via-teal-950 to-stone-900', NULL, 'اصولِ حدیث کے باریک ترین مباحث، ائمۂ جرح و تعدیل کے الفاظ، اور عللِ حدیث کے اصولوں کو کھولنے والی معتمد کتاب۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tawjih_ch1_tadwin', 'kharji_tawjih_nazar_jazairi', 0, 'تَارِيخُ تَدْوِينِ السُّنَّةِ وَأَطْوَارُهَا', 'باب 1: تدوینِ حدیث کا تاریخی سفر اور عمر بن عبدالعزیز کا فرمان');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tawjih_seg_1_1', 'tawjih_ch1_tadwin', 'kharji_tawjih_nazar_jazairi', 0, 'قَالَ الشَّيْخُ طَاهِرٌ الجَزَائِرِيُّ: كَتَبَ عُمَرُ بْنُ عَبْدِ العَزِيزِ رَضِيَ اللَّهُ عَنْهُ إِلَى أَهْلِ المَدِينَةِ: «انْظُرُوا حَدِيثَ رَسُولِ اللَّهِ ﷺ فَاكْتُبُوهُ، فَإِنِّي خِفْتُ دُرُوسَ العِلْمِ وَذَهَابَ أَهْلِهِ، وَلَا تُقْبَلُ إِلَّا حَدِيثُ النَّبِيِّ ﷺ».', 'علامہ طاہر الجزائری رحمہ اللہ فرماتے ہیں: خلیفہ راشد حضرت عمر بن عبدالعزیز رضی اللہ عنہ نے مدینہ منورہ کے گورنر ابو بکر بن حزم اور ائمہ کو سرکاری فرمان جاری کیا: ''رسول اللہ ﷺ کی احادیث کو تلاش کرو اور انہیں لکھ کر مدون کر لو، کیونکہ مجھے علم کے مٹنے اور علماء کے رخصت ہو جانے کا اندیشہ ہے، اور صرف نبی کریم ﷺ کی حدیث ہی قبول کی جائے''۔', 'عمر بن عبدالعزیز کے اس تاریخی اقدام سے امام ابن شہاب زہری اور دیگر اکابر نے باضابطہ دفاتر اور ابواب کی ترتیب پر احادیث کو کتابی شکل دی۔', '[{"word":"انْظُرُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو فاعل"}]', '["توجيه النظر إلى أصول الأثر، وأخرجه البخاري تعليقاً."]', '{"en":"Caliph ''Umar bin ''Abd al-''Aziz issued the first official imperial decree for the systematic compilation and recording of Hadith.","ar":"البدء الرسمي لتدوين السنة النبوية الشريفة بأمر أمير المؤمنين."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_hadyu_sari_hajar', 'هَدْيُ السَّارِي مُقَدِّمَةُ فَتْحِ البَارِي', 'الحَافِظُ أَمِيرُ المُؤْمِنِينَ ابْنُ حَجَرٍ العَسْقَلَانِيُّ (ت: 852ھ)', 'kharji_kitab', 'hadith', 'مقدمۂ صحیح بخاری و دفاعِ اسانید', 'کتبِ مطالعہ و دورۂ حدیث شریف', NULL, NULL, 'from-amber-950 via-emerald-950 to-stone-900', NULL, 'صحیح بخاری کے ابواب، معلقات، تراجم الابواب اور رواۃ پر ہونے والے تمام شکوک و شبہات کا مفصل ترین جواب۔ دورۂ حدیث کے ہر طالب علم کے لیے ناگزیر زادِ راہ۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hadyu_ch1_shart_bukhari', 'kharji_hadyu_sari_hajar', 0, 'الفَصْلُ الأَوَّلُ: شَرْطُ الإِمَامِ البُخَارِيِّ فِي صَحِيحِهِ', 'باب 1: صحیح بخاری میں امام بخاری کی کڑی شرائط اور تالیف کا سبب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hadyu_seg_1_1', 'hadyu_ch1_shart_bukhari', 'kharji_hadyu_sari_hajar', 0, 'قَالَ الحَافِظُ ابْنُ حَجَرٍ: «شَرْطُ البُخَارِيِّ أَنْ يُخْرِجَ الحَدِيثَ المُتَّصِلَ الإِسْنَادِ بِنَقْلِ العَدْلِ الضَّابِطِ عَنْ مِثْلِهِ، وَاشْتَرَطَ اللِّقَاءَ وَالسَّمَاعَ وَلَوْ مَرَّةً وَاحِدَةً، وَلَمْ يَكْتَفِ بِمُجَرَّدِ المُعَاصَرَةِ».', 'حافظ ابن حجر عسقلانی رحمہ اللہ فرماتے ہیں: ''امام بخاری کی شرط یہ ہے کہ وہ صرف وہی حدیث لاتے ہیں جس کی سند عادل اور ضابط راوی کی روایت سے متصل ہو، اور انہوں نے راوی اور مروی عنہ کے مابین کم از کم ایک بار باہمی ملاقات اور براہِ راست سننے کا ثبوت شرط قرار دیا ہے، اور محض ہم عصر ہونے پر اکتفا نہیں فرمایا''۔', 'یہی وہ شرط ہے جس کی وجہ سے امت نے صحیح بخاری کو ''أصح الكتب بعد كتاب الله'' (قرآن کے بعد روئے زمین کی سب سے سچی کتاب) کا متفقہ درجہ عطا کیا۔', '[{"word":"شَرْطُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"البخاري مضاف إليه مجرور"}]', '["هدي الساري مقدمة فتح الباري، الفصل الأول."]', '{"en":"Ibn Hajar elucidates Imam Bukhari''s rigorous criterion: Requiring positive proof of direct meeting and audition between narrators, not merely contemporary existence.","ar":"شرط الإمام البخاري الدقيق الذي فاق به سائر المحدثين."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ilm_rijal_laknawi', 'الرَّفْعُ وَالتَّكْمِيلُ فِي الجَرْحِ وَالتَّعْدِيلِ', 'الإِمَامُ المُحَقِّقُ أَبُو الحَسَنَاتِ عَبْدُ الحَيِّ اللَّكْنَوِيُّ الهِنْدِيُّ (ت: 1304ھ)', 'kharji_kitab', 'hadith', 'قواعدِ جرح و تعدیل و علمِ رجال', 'کتبِ مطالعہ و مراجعِ نقدِ اسانید', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'برصغیر کے عظیم عبقری محدث علامہ عبد الحی لکھنوی کی وہ شاہکار کتاب جس نے جرح و تعدیل کے ائمہ کے کلمات، تعارضِ اقوال اور قواعدِ نقد کو پانی کی طرح شفاف کر دیا۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('laknawi_ch1_dawabit', 'kharji_ilm_rijal_laknawi', 0, 'البَابُ الأَوَّلُ: ضَوَابِطُ الجَرْحِ وَالتَّعْدِيلِ عِنْدَ الأَئِمَّةِ', 'باب 1: راویوں کی جرح و تعدیل کے اصولی ضوابط اور تعصب سے اجتناب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('laknawi_seg_1_1', 'laknawi_ch1_dawabit', 'kharji_ilm_rijal_laknawi', 0, 'قَالَ الإِمَامُ عَبْدُ الحَيِّ اللَّكْنَوِيُّ الحَنَفِيُّ: «الجَرْحُ لَا يُقْبَلُ إِلَّا مُفَسَّراً مُبَيَّنَ السَّبَبِ، لِأَنَّ النَّاسَ يَخْتَلِفُونَ فِي أَسْبَابِ الجَرْحِ، فَقَدْ يَجْرَحُ أَحَدُهُمْ بِمَا لَا يَرَاهُ الآخَرُ جَرْحاً».', 'امام المتکلمین علامہ عبدالحی لکھنوی حنفی رحمہ اللہ فرماتے ہیں: ''کسی بھی راوی پر جرح اس وقت تک قبول نہیں کی جائے گی جب تک کہ وہ سبب کی مکمل وضاحت کے ساتھ مفسر نہ ہو؛ کیونکہ اسبابِ جرح میں علماء کا اختلاف ہوتا ہے، بسا اوقات ایک محدث کسی ایسی بات پر جرح کر دیتا ہے جسے دوسرا محدث جرح شمار ہی نہیں کرتا''۔', 'امام لکھنوی کی یہ کتاب علم رجال کا شاہکار ہے۔ انہوں نے ثابت کیا کہ ائمہ کے باہمی اختلافات یا فقہی تعصب کی بنا پر کی گئی جرح ناقابلِ التفات ہے۔', '[{"word":"مُفَسَّراً","role":"حال منصوب","sign":"فتحة","detail":"حال من الجرح"}]', '["الرفع والتكميل في الجرح والتعديل، ص 64."]', '{"en":"Imam Al-Laknawi establishes the critical rule: Disparagement (Jarh) is not accepted unless explicitly explained with its objective reason.","ar":"قاعدة الجرح المفسر والمبهم عند أئمة نقد الرجال."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ajwibah_fadilah_laknawi', 'الأَجْوِبَةُ الفَاضِلَةُ لِلأَسْئِلَةِ العَشَرَةِ الكَامِلَةِ', 'الإِمَامُ المُحَقِّقُ عَبْدُ الحَيِّ اللَّكْنَوِيُّ (ت: 1304ھ)', 'kharji_kitab', 'hadith', 'تحقیقِ احادیث، شروح و فقہِ حنفی کے دلائل', 'کتبِ مطالعہ و مناظرہ و تحقیق (طلبۂ تخصص)', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'اصولِ حدیث کے دس اہم ترین اور مشکل ترین سوالات کے وہ محققانہ جوابات جنہیں پڑھ کر علامہ عبد الفتاح ابو غدہ نے فرمایا کہ لکھنوی علامہ ابن حجر ثانی ہیں۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ajwibah_ch1_daeef', 'kharji_ajwibah_fadilah_laknawi', 0, 'حُكْمُ العَمَلِ بِالحَدِيثِ الضَّعِيفِ فِي فَضَائِلِ الأَعْمَالِ', 'باب 1: فضائلِ اعمال میں حدیثِ ضعیف پر عمل کے شرعی ضوابط');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ajwibah_seg_1_1', 'ajwibah_ch1_daeef', 'kharji_ajwibah_fadilah_laknawi', 0, 'قَالَ اللَّكْنَوِيُّ: «اتَّفَقَ جُمْهُورُ العُلَمَاءِ عَلَى جَوَازِ العَمَلِ بِالحَدِيثِ الضَّعِيفِ فِي فَضَائِلِ الأَعْمَالِ وَالمَوَاعِظِ بِثَلَاثَةِ شُرُوطٍ: أَنْ لَا يَكُونَ الضَّعْفُ شَدِيداً، وَأَنْ يَنْدَرِجَ تَحْتَ أَصْلٍ عَامٍّ، وَأَنْ لَا يُعْتَقَدَ عِنْدَ العَمَلِ ثُبُوتُهُ عَنِ النَّبِيِّ ﷺ قَطْعاً».', 'امام لکھنوی فرماتے ہیں: ''جمہور فقہاء و محدثین کا اس پر اتفاق ہے کہ فضائلِ اعمال اور ترغیب و ترہیب میں حدیثِ ضعیف پر عمل کرنا تین شرائط کے ساتھ جائز ہے: ۱۔ اس کا ضعف شدید (مثلاً کذاب یا متہم راوی) نہ ہو، ۲۔ وہ شریعت کے کسی عمومی اصل اور قاعدے کے ماتحت ہو، ۳۔ اور عمل کرتے وقت اس کے قطعی سنت ہونے کا پختہ عقیدہ نہ رکھا جائے بلکہ احتیاطاً عمل کیا جائے''۔', 'عقائد اور حلال و حرام میں صرف صحیح اور حسن احادیث حجت ہیں، لیکن نیکیوں کی ترغیب میں ضعیف حدیث پر عمل کرنے کی سلف و خلف نے اجازت دی ہے۔', '[{"word":"اتَّفَقَ","role":"فعل ماض","sign":"مبني","detail":"جمهور فاعل مرفوع بالضمة"}]', '["الأجوبة الفاضلة للأسئلة العشرة الكاملة، ص 38."]', '{"en":"Conditions for acting upon weak (Da''if) Hadith in virtuous deeds as formulated by scholars.","ar":"الشروط الثلاثة للعمل بالحديث الضعيف في فضائل الأعمال."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_athar_sunan_nimawi', 'آثَارُ السُّنَنِ مَعَ حَاشِيَتِهِ التَّعْلِيقِ الحَسَنِ', 'العَلَّامَةُ ظَهِيرُ أَحْسَنَ النِّيمَوِيُّ الهِنْدِيُّ (ت: 1322ھ)', 'kharji_kitab', 'hadith', 'احادیثِ فقہِ حنفی کی تحقیق و اسانید', 'کتبِ مطالعہ و دورۂ حدیث شریف', NULL, NULL, 'from-teal-950 via-emerald-900 to-stone-900', NULL, 'فقہِ حنفی کے تمام معمولات و فتاویٰ پر صحیح اور حسن احادیث کا مدلل ذخیرہ مع اسانید کی باریک بینانہ جرح و تعدیل۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('athar_ch1_taharah', 'kharji_athar_sunan_nimawi', 0, 'كِتَابُ الطَّهَارَةِ — أَدِلَّةُ السُّنَّةِ فِي فِقْهِ الإِمَامِ أَبِي حَنِيفَةَ', 'باب 1: کتاب الطہارۃ — فقہ حنفی کے مضبوط اور مستند دلائلِ حدیث');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('athar_seg_1_1', 'athar_ch1_taharah', 'kharji_athar_sunan_nimawi', 0, 'قَالَ العَلَّامَةُ شَوْقٌ نِيمَوِي: «خَرَّجْنَا فِي هَذَا الكِتَابِ صِحَاحَ الآثَارِ وَحِسَانَهَا الَّتِي اعْتَمَدَ عَلَيْهَا فُقَهَاءُ العِرَاقِ وَالإِمَامُ الأَعْظَمُ أَبُو حَنِيفَةَ، لِيَعْلَمَ المُنْصِفُ أَنَّ مَذْهَبَهُ مَبْنِيٌّ عَلَى صَحِيحِ الأَخْبَارِ».', 'علامہ ظہیر احسن شوق نیموی عظیم آبادی رحمہ اللہ فرماتے ہیں: ''ہم نے اس کتاب میں ان صحیح اور حسن احادیث و آثار کو جمع کیا ہے جن پر فقہائے کوفہ اور امام اعظم ابو حنیفہ نے اپنے مسائل کی بنیاد رکھی، تاکہ ہر انصاف پسند پر یہ حقیقت واضح ہو جائے کہ فقہ حنفی محض قیاس نہیں بلکہ صحیح احادیثِ رسول پر قائم ہے''۔', 'آثار السنن برصغیر کی عظیم ترین تصانیف میں سے ہے جس نے ثابت کیا کہ حنفی مسائل احادیثِ صحابہ و تابعین کے عین موافق ہیں۔', '[{"word":"خَرَّجْنَا","role":"فعل ماض وفاعل","sign":"مبني","detail":"ونا ضمير متصل فاعل"}]', '["آثار السنن مع حاشيته التعليق الحسن، ص 12."]', '{"en":"Allamah Al-Nimawi compiles the authentic Hadith foundations supporting the Hanafi school of jurisprudence.","ar":"تخريج وتحقيق أدلة المذهب الحنفي بالروايات الصحيحة والحسنة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ashbah_nazair_ibn_nujaym', 'الأَشْبَاهُ وَالنَّظَائِرُ عَلَى مَذْهَبِ أَبِي حَنِيفَةَ', 'العَلَّامَةُ زَيْنُ الدِّينِ بْنُ إِبْرَاهِيمَ ابْنُ نُجَيْمٍ المِصْرِيُّ الحَنَفِيُّ (ت: 970ھ)', 'kharji_kitab', 'usul', 'قواعدِ فقہیہ و کلیاتِ فقہِ حنفی', 'کتبِ مطالعہ و تخصص فی الفقہ والافتاء', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'فقہی قواعد کا مایہ ناز شاہکار۔ پانچ بنیادی کلیات (الأمور بمقاصدها، اليقين لا يزول بالشك وغیرہ) سے ہزاروں فروعی مسائل حل کرنے کا طریقہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ashbah_ch1_maqasid', 'kharji_ashbah_nazair_ibn_nujaym', 0, 'القَاعِدَةُ الكُلِّيَّةُ الأُولَى: الأُمُورُ بِمَقَاصِدِهَا', 'قاعدہ 1: الامور بمقاصدھا — کاموں کا دارومدار ان کے ارادوں اور مقاصد پر ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ashbah_seg_1_1', 'ashbah_ch1_maqasid', 'kharji_ashbah_nazair_ibn_nujaym', 0, 'قَالَ العَلَّامَةُ زَيْنُ الدِّينِ ابْنُ نُجَيْمٍ المِصْرِيُّ الحَنَفِيُّ: «الأَصْلُ فِيهَا حَدِيثُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ». وَمَعْنَاهَا أَنَّ تَصَرُّفَاتِ المُكَلَّفِ قَوْلِيَّةً أَوْ فِعْلِيَّةً تَخْتَلِفُ أَحْكَامُهَا الشَّرْعِيَّةُ بِاخْتِلَافِ قَصْدِهِ؛ فَالقَتْلُ قَدْ يَكُونَ عَمْداً يُوجِبُ القِصَاصَ، وَقَدْ يَكُونَ خَطَأً يُوجِبُ الدِّيَةَ، وَالفَرْقُ بَيْنَهُمَا القَصْدُ. وَكَذَلِكَ إِمْسَاكُ المَالِ إِنْ كَانَ لِلتِّجَارَةِ وَجَبَتْ فِيهِ الزَّكَاةُ، وَإِنْ كَانَ لِلْقِنْيَةِ لَمْ تَجِبْ».', 'علامہ زین الدین ابن نجیم مصری حنفی فرماتے ہیں: ''اس قاعدے کی اصل بنیاد نبی کریم ﷺ کی حدیث: «تمام اعمال کا دارومدار نیتوں پر ہے» ہے۔ اس کا مفہوم یہ ہے کہ مکلف انسان کے قولی و فعلی تصرفات کے شرعی احکام اس کی نیت اور قصد کے بدلنے سے بدل جاتے ہیں؛ مثلاً کسی کو جان سے مارنا کبھی ارادتاً (قتل عمد) ہوتا ہے جس میں قصاص واجب ہے، اور کبھی غلطی سے (قتل خطا) ہوتا ہے جس میں دیت واجب ہے، اور دونوں کے درمیان فرق صرف قصد و نیت کا ہے۔ اسی طرح مال رکھنا اگر تجارت کی نیت سے ہو تو اس میں زکوٰۃ فرض ہے، اور اگر ذاتی استعمال (قنیہ) کی نیت سے ہو تو زکوٰۃ فرض نہیں''۔', 'الأشباه والنظائر ابن نجیم حنفی فقہ کی سب سے معتبر اور جامع کتاب ہے جس پر فتاویٰ کا دارومدار ہے۔ یہ قاعدہ عبادات، معاملات اور حدود سب پر حاوی ہے۔', '[{"word":"الأُمُورُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"بمقاصدها جار ومجرور شبه جملة خبر"},{"word":"عَمْداً","role":"خبر كان منصوب","sign":"فتحة","detail":"واسم كان ضمير مستتر يعود على القتل"}]', '["الأشباه والنظائر لابن نجيم، الفن الأول: القواعد الكلية، ص 23-35."]', '{"en":"Ibn Nujaym''s Rule 1: ''Matters are judged by their intentions'' (Al-Umuru bi-Maqasidiha). A person''s verbal and physical acts take on vastly different legal rulings depending on intent—such as deliberate murder versus accidental manslaughter, or holding assets for trade versus personal use.","ar":"بيان أثر النية والقصد في التمييز بين العبادات والمعاملات والعقوبات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ashbah_ch2_yaqeen', 'kharji_ashbah_nazair_ibn_nujaym', 1, 'القَاعِدَةُ الثَّانِيَةُ: اليَقِينُ لَا يَزُولُ بِالشَّكِّ', 'قاعدہ 2: الیقین لا یزول بالشک — پختہ یقین محض وہم اور شک سے زائل نہیں ہوتا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ashbah_seg_2_1', 'ashbah_ch2_yaqeen', 'kharji_ashbah_nazair_ibn_nujaym', 0, '«أَصْلُهَا قَوْلُهُ ﷺ فِي الَّذِي يَجِدُ الشَّيْءَ فِي بَطْنِهِ: «لَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتاً أَوْ يَجِدَ رِيحاً». وَمِنْ فُرُوعِهَا: مَنْ تَيَقَّنَ الطَّهَارَةَ وَشَكَّ فِي الحَدَثِ فَهُوَ طَاهِرٌ، وَمَنْ تَيَقَّنَ الحَدَثَ وَشَكَّ فِي الطَّهَارَةِ فَهُوَ مُحْدِثٌ. وَالأَصْلُ بَرَاءَةُ الذِّمَّةِ مِنْ حُقُوقِ العِبَادِ حَتَّى يَثْبُتَ الحَقُّ بِبَيِّنَةٍ قَاطِعَةٍ، وَالأَصْلُ بَقَاءُ مَا كَانَ عَلَى مَا كَانَ».', 'ابن نجیم رحمہ اللہ فرماتے ہیں: ''اس قاعدے کی بنیاد نبی کریم ﷺ کا وہ ارشاد ہے جس میں نماز کے دوران پیٹ میں گڑبڑ محسوس کرنے والے کے بارے میں فرمایا: ''جب تک آواز نہ سن لے یا بو نہ پائے ہرگز نماز نہ توڑے''۔ اس قاعدے کی جزئیات میں سے ہے: جس شخص کو باوضو ہونے کا یقین ہو اور بعد میں وضو ٹوٹنے میں شک ہو تو وہ باوضو مانا جائے گا، اور جس کو وضو ٹوٹنے کا یقین ہو اور دوبارہ وضو کرنے میں شک ہو تو وہ بے وضو شمار ہوگا۔ اور اصول یہ ہے کہ انسان کا ذمہ تمام حقوق اور مالی دعووں سے بری ہے جب تک مدعی قطعی گواہی سے حق ثابت نہ کرے، اور اصول یہ ہے کہ جو چیز جس حال پر تھی اسی پر برقرار مانی جائے گی''۔', 'یہ قاعدہ انسانی زندگی سے وہم، وسوسے اور شکوک کا خاتمہ کرتا ہے۔ عدالت میں مدعا علیہ کی بے گناہی اور عبادات میں یقین کی بنیاد اسی اصول پر قائم ہے۔', '[{"word":"اليَقِينُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"لا يزول جملة فعلية خبر"},{"word":"طَاهِرٌ","role":"خبر المبتدأ هو","sign":"ضمة","detail":"والجملة الاسمية جواب الشرط"}]', '["الأشباه والنظائر لابن نجيم، ص 56-68، وأخرجه مسلم (361)."]', '{"en":"Rule 2: ''Certainty is not overruled by doubt'' (Al-Yaqinu la yazulu bish-Shakk). Derived from the Prophet''s instruction not to break prayer due to phantom doubts. It anchors legal presumption of innocence and continuity of prior status.","ar":"قاعدة استصحاب الأصل وبراءة الذمة ودرء الوساوس في الطهارات والمعاملات."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_qawaid_fiqhiyyah_nadwi', 'القَوَاعِدُ الفِقْهِيَّةُ: مَفْهُومُهَا وَنَشْأَتُهَا وَتَطَوُّرُهَا', 'الدُّكْتُورُ عَلِيُّ أَحْمَدَ النَّدْوِيُّ', 'kharji_kitab', 'usul', 'تاریخ و تدوینِ قواعدِ فقہیہ', 'کتبِ مطالعہ و افتاء (طلبۂ تخصص)', NULL, NULL, 'from-blue-950 via-stone-900 to-emerald-950', NULL, 'فقہی قواعد کی تاریخ، ائمہ اربعہ کے قواعد، اور جدید مسائل کے حل میں قواعد کے استعمال پر عصرِ حاضر کی سب سے مستند اور معتمد کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nadwi_qawaid_ch1_taareef', 'kharji_qawaid_fiqhiyyah_nadwi', 0, 'البَابُ الأَوَّلُ: تَعْرِيفُ القَاعِدَةِ الفِقْهِيَّةِ وَالفَرْقُ بَيْنَهَا وَبَيْنَ الضَّابِطِ', 'باب 1: قواعدِ فقہیہ کا تعارف اور ''قاعدہ'' و ''ضابطہ'' کے مابین فرق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nadwi_qawaid_seg_1_1', 'nadwi_qawaid_ch1_taareef', 'kharji_qawaid_fiqhiyyah_nadwi', 0, 'قَالَ الدُّكْتُورُ عَلِيُّ أَحْمَدَ النَّدْوِيُّ: «القَاعِدَةُ الفِقْهِيَّةُ: حُكْمٌ كُلِّيٌّ أَوْ أَكْثَرِيٌّ يَنْطَبِقُ عَلَى جُزْئِيَّاتٍ كَثِيرَةٍ تُفْهَمُ أَحْكَامُهَا مِنْهَا فِي أَبْوَابٍ مُتَعَدِّدَةٍ مِنَ الفِقْهِ. وَالفَرْقُ بَيْنَهَا وَبَيْنَ الضَّابِطِ الفِقْهِيِّ: أَنَّ القَاعِدَةَ تَجْمَعُ فُرُوعاً مِنْ أَبْوَابٍ شَتَّى (كَالصَّلَاةِ وَالبَيْعِ وَالجِنَايَاتِ)، أَمَّا الضَّابِطُ فَيَخْتَصُّ بِبَابٍ وَاحِدٍ فَقَطْ؛ كَقَوْلِهِمْ: «كُلُّ صَلَاةٍ بَطَلَتْ عَلَى الإِمَامِ بَطَلَتْ عَلَى المَأْمُومِ» فَهَذَا ضَابِطٌ خَاصٌّ بِالصَّلَاةِ».', 'ڈاکٹر علی احمد الندوی فرماتے ہیں: ''قاعدۂ فقہیہ سے مراد وہ کلی یا اکثری شرعی ضابطہ ہے جو فقہ کے متعدد مختلف ابواب میں پھیلی ہوئی کثیر جزئیات پر منطبق ہوتا ہے اور ان کے احکام اسی سے سمجھے جاتے ہیں۔ اور ''قاعدہ'' اور ''ضابطہ'' میں باریک فرق یہ ہے کہ قاعدہ مختلف ابواب (مثلاً نماز، خرید و فروخت، نکاح، حدود) کی تمام شاخوں کو اپنے اندر سمو لیتا ہے، جبکہ ضابطہ صرف کسی ایک مخصوص باب تک محدود رہتا ہے؛ جیسے فقہاء کا کہنا: ''ہر وہ نماز جو امام کی فاسد ہو جائے وہ مقتدی کی بھی فاسد ہو جاتی ہے''، یہ صرف نماز کے باب کا ایک ضابطہ ہے، عام قاعدہ نہیں''۔', 'ڈاکٹر علی احمد ندوی کی یہ کتاب معاصر دور میں قواعدِ فقہیہ کی تاریخ اور تدوین پر سب سے مستند علمی تحقیق مانی جاتی ہے۔', '[{"word":"حُكْمٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"القاعدة مبتدأ وحكم خبره"},{"word":"شَتَّى","role":"نعت لأبواب مجرور","sign":"فتحة مقدرة","detail":"ممنوع من الصرف"}]', '["القواعد الفقهية، د. علي أحمد الندوي، دار القلم، ص 41-47."]', '{"en":"Dr. Ali Ahmad An-Nadwi differentiates between a universal Legal Maxim (Qaidah) spanning diverse Fiqh chapters and a specific Sub-Maxim (Dabit) restricted to a single specific chapter.","ar":"التحرير الأكاديمي الدقيق للفروق بين القواعد الفقهية والضوابط والأصول."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nadwi_qawaid_ch2_khams_kubra', 'kharji_qawaid_fiqhiyyah_nadwi', 1, 'البَابُ الثَّانِي: القَوَاعِدُ الفِقْهِيَّةُ الخَمْسُ الكُبْرَى الَّتِي يَدُورُ عَلَيْهَا الفِقْهُ', 'باب 2: پانچ بنیادی فقہی قواعدِ کلیہ جن پر پورے اسلام کا مدار ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nadwi_qawaid_seg_2_1', 'nadwi_qawaid_ch2_khams_kubra', 'kharji_qawaid_fiqhiyyah_nadwi', 0, '«اتَّفَقَ فُقَهَاءُ المَذَاهِبِ الأَرْبَعَةِ عَلَى أَنَّ أُصُولَ القَوَاعِدِ الفِقْهِيَّةِ تَرْجِعُ إِلَى خَمْسِ قَوَاعِدَ كُبْرَى: 1. الأُمُورُ بِمَقَاصِدِهَا. 2. اليَقِينُ لَا يَزُولُ بِالشَّكِّ. 3. المَشَقَّةُ تَجْلِبُ التَّيْسِيرَ. 4. الضَّرَرُ يُزَالُ. 5. العَادَةُ مُحَكَّمَةٌ. وَقَدْ نَظَمَهَا بَعْضُ الفُقَهَاءِ فَقَالَ: خَمْسٌ مُحَرَّرَةٌ قَوَاعِدُ مَذْهَبٍ ... لِلشَّافِعِيِّ وَغَيْرِهِ مِنَ الفُقَهَا / ضَرَرٌ يُزَالُ وَعَادَةٌ قَدْ حُكِّمَتْ ... وَكَذَا المَشَقَّةُ تَجْلِبُ التَّيْسِيرَا / وَالشَّكُّ لَا تَرْفَعْ بِهِ يَقِيناً مَعْ ... أُمُورٍ بِمَقَاصِدِهَا تُنَالُ خَبِيرَا».', 'ڈاکٹر علی احمد ندوی فرماتے ہیں: ''چاروں فقہی مذاہب (حنفی، شافعی، مالکی، حنبلی) کا اس پر مکمل اتفاق ہے کہ فقہ اسلامی کے ہزاروں مسائل پانچ بنیادی قواعدِ کلیہ کے گرد گھومتے ہیں: 1. الامور بمقاصدھا (کاموں کا مدار نیتوں پر ہے)۔ 2. الیقین لا یزول بالشک (یقین شک سے زائل نہیں ہوتا)۔ 3. المشقۃ تجلب التیسیر (تکلیف و مشقت آسانی کو کھینچ لاتی ہے)۔ 4. الضرر یزال (نقصان کا خاتمہ کیا جائے گا)۔ 5. العادۃ محکمۃ (معروف رواج اور عرف کو ثالث اور حجت مانا جائے گا)''۔', 'یہ پانچ قواعد دراصل انسانی زندگی کی ہر قانونی ضرورت اور فقہی اجتہاد کا احاطہ کرتے ہیں، چاہے پرانے زمانے کے مسائل ہوں یا جدید طب، تجارت اور ٹیکنالوجی کے معاملات۔', '[{"word":"خَمْسِ","role":"مجرور بإلى","sign":"كسرة","detail":"وهو مضاف وقواعد مضاف إليه"},{"word":"مُحَكَّمَةٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"العادة مبتدأ ومحكمة خبره"}]', '["القواعد الفقهية للندوي، ص 98-105، ومجلة الأحكام العدلية المادة (2-10)."]', '{"en":"The Five Universal Maxims (Al-Qawa''id al-Khams al-Kubra) accepted across all four schools of jurisprudence: 1. Intent determines acts, 2. Certainty dispels doubt, 3. Hardship begets facility, 4. Harm must be eliminated, 5. Custom holds legal authority.","ar":"الدعائم الخمس التشريعية التي تنتظم سائر الأحكام الفقهية وتطبيقاتها المعاصرة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_risalah_shafii', 'الرِّسَالَةُ فِي أُصُولِ الفِقْهِ', 'الإِمَامُ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ (ت: 204ھ)', 'kharji_kitab', 'usul', 'اصولِ فقہ کی اولین تاریخی تصنیف', 'کتبِ مطالعہ و امہاتِ اصولِ شریعت', NULL, NULL, 'from-emerald-950 via-teal-950 to-stone-900', NULL, 'دنیا کی تاریخ میں اصولِ فقہ کی سب سے پہلی تصنیف۔ ناسخ و منسوخ، خبرِ واحد، قیاس اور اجماع کے قوانین کی ایسی بنیاد جس پر پوری امت متفق ہوئی۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shafii_ch1_bayan', 'kharji_risalah_shafii', 0, 'بَابُ البَيَانِ وَمَرَاتِبِهِ الخَمْسِ فِي الكِتَابِ وَالسُّنَّةِ', 'باب 1: کتاب و سنت میں ''بیان'' کے مراتب اور اصولِ فقہ کی پہلی بنیاد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shafii_seg_1_1', 'shafii_ch1_bayan', 'kharji_risalah_shafii', 0, 'قَالَ الإِمَامُ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ: «جِمَاعُ البَيَانِ فِي كِتَابِ اللَّهِ عَلَى وُجُوهٍ: مِنْهَا مَا أَبَانَهُ اللَّهُ لِخَلْقِهِ نَصّاً، كَمُجْمَلِ فَرَائِضِهِ فِي الصَّلَاةِ وَالزَّكَاةِ، وَمِنْهَا مَا أَحْكَمَ فَرْضَهُ بِكِتَابِهِ وَبَيَّنَ كَيْفِيَّتَهُ عَلَى لِسَانِ نَبِيِّهِ ﷺ (كَأَعْدَادِ الرَّكَعَاتِ وَأَنْصِبَةِ الزَّكَاةِ)، وَمِنْهَا مَا سَنَّهُ رَسُولُ اللَّهِ ﷺ مِمَّا لَيْسَ فِيهِ نَصُّ كِتَابٍ، فَأَلْزَمَنَا اللَّهُ طَاعَتَهُ فِيهِ فَقَالَ: {وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا}».', 'امام محمد بن ادریس الشافعی رحمہ اللہ فرماتے ہیں: ''اللہ کی کتاب میں بیان کا خلاصہ چند درجوں پر مشتمل ہے: ان میں سے ایک وہ ہے جسے اللہ نے اپنی مخلوق کے لیے بالکل صریح نص کے طور پر بیان فرمایا، جیسے نماز اور زکوٰۃ کی بنیادی فرضیت؛ دوسرا درجہ وہ ہے جس کی فرضیت کو کتاب اللہ میں محکم کیا اور اس کی عملی کیفیت اپنے نبی ﷺ کی زبانِ مبارک سے واضح فرمائی (جیسے نماز کی رکعتوں کی تعداد اور زکوٰۃ کے نصاب)؛ اور تیسرا درجہ وہ ہے جس کا حکم رسول اللہ ﷺ نے اپنی سنت سے جاری فرمایا جس پر قرآن میں کوئی صریح نص نہ تھی، تو اللہ نے ہمیں آپ ﷺ کی سنت کی اطاعت کا پابند بناتے ہوئے فرمایا: {اور جو کچھ رسول تمہیں دیں اسے لے لو اور جس سے منع فرمائیں اس سے رک جاؤ}''۔', 'کتاب ''الرسالة'' تاریخِ اسلام میں اصولِ فقہ کی سب سے پہلی تصنیف ہے۔ امام شافعی نے اس شاہکار کے ذریعے قرآن و سنت کے ربط اور حجیتِ حدیث کا ایسا دفاع فرمایا جس نے امت کو فکری انحراف سے بچا لیا۔', '[{"word":"جِمَاعُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"على وجوه شبه جملة خبر"},{"word":"نَصّاً","role":"حال أو تمييز منصوب","sign":"فتحة","detail":"يبين هيئة البيان"}]', '["الرسالة للإمام الشافعي، تحقيق أحمد محمد شاكر، ص 21-25."]', '{"en":"Imam Ash-Shafi''i establishes the foundational tiers of ''Al-Bayan'' (divine clarification): Explicit Quranic texts, Quranic obligations expounded by prophetic Sunnah, and independent Sunnah legislations divinely sanctioned by the Quran.","ar":"التأسيس التاريخي الأول لمنهج أصول الفقه وعلاقة السنة التشريعية بالقرآن."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shafii_ch2_qiyas_khabar', 'kharji_risalah_shafii', 1, 'بَابُ الإِجْمَاعِ وَالقِيَاسِ وَحُجِّيَّةِ خَبَرِ الوَاحِدِ', 'باب 2: اجماع، قیاس اور خبرِ واحد کی شرعی حجیت کا ثبوت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shafii_seg_2_1', 'shafii_ch2_qiyas_khabar', 'kharji_risalah_shafii', 0, '«وَلَا يَسَعُ أَحَداً إِذَا ثَبَتَتْ عِنْدَهُ سُنَّةُ رَسُولِ اللَّهِ ﷺ أَنْ يَدَعَهَا لِقَوْلِ أَحَدٍ كَائِناً مَنْ كَانَ. وَالقِيَاسُ لَا يُصَارُ إِلَيْهِ إِلَّا عِنْدَ الضَّرُورَةِ وَعَدَمِ النَّصِّ؛ فَالقِيَاسُ مِثْلُ التَّيَمُّمِ: يُتَيَمَّمُ بِالتُّرَابِ عِنْدَ فَقْدِ المَاءِ، فَإِذَا وُجِدَ المَاءُ بَطَلَ التَّيَمُّمُ، وَكَذَلِكَ إِذَا وُجِدَ النَّصُّ فَلَا قِيَاسَ. وَالِاسْتِحْسَانُ تَلَذُّذٌ وَاتِّبَاعٌ لِلْهَوَى إِذَا خَلَا عَنِ الدَّلِيلِ».', 'امام شافعی رحمہ اللہ فرماتے ہیں: ''کسی شخص کے لیے یہ گنجائش نہیں کہ جب اس کے سامنے رسول اللہ ﷺ کی صحیح سنت ثابت ہو جائے تو وہ کسی بھی انسان کے قول کی وجہ سے سنت کو چھوڑ دے، وہ انسان کتنا ہی بڑا کیوں نہ ہو۔ اور قیاس کی طرف صرف اس وقت رخ کیا جائے گا جب صریح نص موجود نہ ہو اور مجبوری لاحق ہو؛ قیاس کی مثال تیمم کی طرح ہے: پانی نہ ملنے پر مٹی سے تیمم کیا جاتا ہے، لیکن جب پانی موجود ہو جائے تو تیمم باطل ہو جاتا ہے، بالکل اسی طرح جب صریح نص موجود ہو تو قیاس کی کوئی گنجائش نہیں رہتی۔ اور دلیل کے بغیر محض اپنی پسند سے استحسان کرنا نفس کی لذت اور خواہش کی پیروی ہے''۔', 'امام شافعی کا یہ جملہ کہ ''قیاس تیمم کی طرح ہے'' علمِ اصول کا زریں مقولہ بن چکا ہے۔ انہوں نے شریعت میں ذاتی پسند کی بنیاد پر اجتہاد کرنے کو سختی سے مسترد کیا۔', '[{"word":"أَحَداً","role":"فاعل يسع مؤخر مرفوع أو مفعول به","sign":"فتحة","detail":"والفاعل هو المصدر المؤول (أن يدعها)"},{"word":"بَطَلَ","role":"فعل ماض مبني على الفتح","sign":"مبني","detail":"جواب الشرط فإذا وجد الماء"}]', '["الرسالة للشافعي، ص 508-512، وجماع العلم ص 11."]', '{"en":"Imam Ash-Shafi''i establishes the primacy of Hadith: No one may abandon a verified Sunnah for any human opinion. Qiyas is akin to Tayammum—only permissible when direct textual water is absent; when explicit Nass appears, Qiyas dissolves.","ar":"قاعدة تقديم النصوص على الآراء والقياس، والرد على من أفتى بمجرد الاستحسان."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_mustasfa_ghazali', 'المُسْتَصْفَى مِنْ عِلْمِ الأُصُولِ', 'حُجَّةُ الإِسْلَامِ الإِمَامُ أَبُو حَامِدٍ مُحَمَّدُ بْنُ مُحَمَّدٍ الغَزَالِيُّ (ت: 505ھ)', 'kharji_kitab', 'usul', 'فلسفۂ اصولِ فقہ و مقاصدِ شریعت', 'کتبِ مطالعہ و فکری ارتقاء (طلبۂ تخصص)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-950', NULL, 'اصولِ فقہ کی چار ارکانِ اربعہ والی وہ مشہور کتاب جس میں امام غزالی نے احکام، دلائل، استنباط اور اجتہاد کے قوانین کو فلسفیانہ گہرائی اور منطقی ترتیب سے مرتب کیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ghazali_mustasfa_ch1_ahkam', 'kharji_mustasfa_ghazali', 0, 'القُطْبُ الأَوَّلُ: فِي الأَحْكَامِ التَّكْلِيفِيَّةِ الخَمْسَةِ وَالأَحْكَامِ الوَضْعِيَّةِ', 'باب 1: احکامِ تکلیفیہ خمسہ اور احکامِ وضعیہ کی منطقی ترتیب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ghazali_mustasfa_seg_1_1', 'ghazali_mustasfa_ch1_ahkam', 'kharji_mustasfa_ghazali', 0, 'قَالَ حُجَّةُ الإِسْلَامِ الإِمَامُ الغَزَالِيُّ: «الحُكْمُ الشَّرْعِيُّ عِنْدَنَا هُوَ: خِطَابُ الشَّارِعِ المُتَعَلِّقُ بِأَفْعَالِ المُكَلَّفِينَ بِالطَّلَبِ أَوْ التَّخْيِيرِ أَوْ الوَضْعِ. وَأَقْسَامُ الحُكْمِ التَّكْلِيفِيِّ خَمْسَةٌ: الإِيجَابُ، وَالنَّدْبُ، وَالتَّحْرِيمُ، وَالكَرَاهَةُ، وَالإِبَاحَةُ. فَإِنْ طَلَبَ الفِعْلَ طَلَباً جَازِماً فَهُوَ الوَاجِبُ، أَوْ غَيْرَ جَازِمٍ فَالمَنْدُوبُ، وَإِنْ طَلَبَ التَّرْكَ طَلَباً جَازِماً فَالحَرَامُ، أَوْ غَيْرَ جَازِمٍ فَالمَكْرُوهُ، وَإِنْ خَيَّرَ بَيْنَهُمَا فَهِيَ الإِبَاحَةُ».', 'حجۃ الاسلام امام ابو حامد غزالی رحمہ اللہ فرماتے ہیں: ''ہمارے نزدیک شرعی حکم کی تعریف یہ ہے: شریعت کے نازل کرنے والے کا وہ خطاب جو مکلف انسانوں کے افعال کے ساتھ کسی کام کے طلب کرنے، یا اختیار دینے، یا کسی چیز کو علامت و سبب بنانے (وضع) کے ساتھ متعلق ہو۔ اور تکلیفی حکم کی پانچ قسمیں ہیں: ایجاب (فرضیت)، ندب (استحباب)، تحریم (حرام ہونا)، کراہت، اور اباحت (جائز ہونا)۔ پس اگر شارع نے کسی کام کا حتمی و لازمی مطالبہ کیا تو وہ واجب ہے، اور اگر غیر حتمی ترغیب دی تو مندوب ہے؛ اور اگر کسی کام کے چھوڑنے کا حتمی مطالبہ کیا تو وہ حرام ہے، اور اگر بغیر سختی کے روکا تو مکروہ ہے؛ اور اگر کرنے اور نہ کرنے کا برابر اختیار دیا تو وہ مباح ہے''۔', 'کتاب ''المستصفى'' اصولِ فقہ کی چار امہات الکتب میں سے ہے۔ امام غزالی نے اس کتاب میں منطق اور کلامی مباحث کو اصولِ فقہ کی گہری باریکیوں کے ساتھ نہایت شستہ انداز میں مربوط کیا ہے۔', '[{"word":"خِطَابُ","role":"خبر المبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"الحكم مبتدأ وهو ضمير فصل وخطاب خبر"},{"word":"جَازِماً","role":"نعت لطَلباً منصوب","sign":"فتحة","detail":"يحدد نوع الطلب"}]', '["المستصفى من علم الأصول للغزالي، 1/ 65-72، المطبعة الأميرية."]', '{"en":"Imam Al-Ghazali defines the Shariah ruling: The Lawgiver''s communication concerning human actions via demand, option, or condition. The five normative rulings are Obligatory (Wajib), Recommended (Mandub), Prohibited (Haram), Disliked (Makruh), and Permissible (Mubah).","ar":"التحرير المنطقي الأصولي لماهية الحكم الشرعي وأقسامه التكليفية الخمسة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ghazali_mustasfa_ch2_ijtihad', 'kharji_mustasfa_ghazali', 1, 'القُطْبُ الرَّابِعُ: فِي شُرُوطِ المُجْتَهِدِ وَأَدَوَاتِ اسْتِنْبَاطِ الأَحْكَامِ', 'باب 2: مجتہد کی علمی شرائط اور شریعت سے احکام نکالنے کا طریقہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ghazali_mustasfa_seg_2_1', 'ghazali_mustasfa_ch2_ijtihad', 'kharji_mustasfa_ghazali', 0, '«الِاجْتِهَادُ: بَذْلُ المُجْتَهِدِ وُسْعَهُ فِي طَلَبِ العِلْمِ بِأَحْكَامِ الشَّرِيعَةِ. وَلَا يَصِيرُ العَالِمُ مُجْتَهِداً حَتَّى يَجْمَعَ ثَمَانِيَةَ عُلُومٍ: الإِحَاطَةَ بِآيَاتِ الأَحْكَامِ (وَهِيَ خَمْسُمِائَةِ آيَةٍ)، وَمَعْرِفَةَ أَحَادِيثِ الأَحْكَامِ وَأَبْوَابِهَا، وَمَعْرِفَةَ الإِجْمَاعِ وَمَوَاقِعِهِ حَتَّى لَا يُفْتِيَ بِخِلَافِهِ، وَمَعْرِفَةَ القِيَاسِ وَشُرُوطِ العِلَّةِ، وَمَعْرِفَةَ لِسَانِ العَرَبِ نَحْواً وَلُغَةً، وَمَعْرِفَةَ النَّاسِخِ وَالمَنْسُوخِ، وَمَعْرِفَةَ رُوَاةِ الأَخْبَارِ وَشُرُوطِ العَدَالَةِ، مَعَ مَلَكَةِ التَّقْوَى».', 'امام غزالی فرماتے ہیں: ''اجتہاد سے مراد یہ ہے کہ مجتہد شریعت کے احکام کا علم حاصل کرنے کے لیے اپنی پوری علمی طاقت اور وسعت خرچ کر دے۔ اور کوئی عالم اس وقت تک مجتہد نہیں بن سکتا جب تک وہ آٹھ علوم کا جامع نہ ہو: احکام کی قرآنی آیات کا احاطہ (جو تقریباً پانچ سو آیات ہیں)، احادیثِ احکام اور ان کے ابواب کی معرفت، اجماع کے متفقہ مقامات کا علم تاکہ اس کے خلاف فتویٰ نہ دے، قیاس اور علت کی شرائط کی مہارت، عربی زبان و نحو کا مکمل ادراک، ناسخ و منسوخ کی شناخت، راویانِ حدیث کی عدالت و ضبط کا علم، اور ان سب کے ساتھ باطنی تقویٰ اور ملکہ و بصیرت''۔', 'امام غزالی نے اجتہاد کے لیے جو معیار مقرر کیا اس نے شریعت کو اناڑیوں کی دخل اندازی سے محفوظ رکھا اور یہ واضح کیا کہ اجتہاد صرف گہری مہارت کے بعد ہی ممکن ہے۔', '[{"word":"بَذْلُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"الاجتهاد مبتدأ وبذل خبره"},{"word":"مُجْتَهِداً","role":"خبر يصير منصوب","sign":"فتحة","detail":"العالم اسم يصير"}]', '["المستصفى للغزالي، 2/ 350-358."]', '{"en":"Al-Ghazali defines Ijtihad: Expending maximum intellectual exertion to deduce legal rulings. An aspiring Mujtahid must master eight essential competencies spanning Quranic legal verses, Hadith corpora, consensus (Ijma''), analogical reasoning (Qiyas), and Arabic mastery.","ar":"شروط الاجتهاد المطلق وحفظ الشريعة من تصدر غير المؤهلين للفتيا."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_muwafaqat_shatibi', 'المُوَافَقَاتُ فِي أُصُولِ الشَّرِيعَةِ وَمَقَاصِدِهَا', 'الإِمَامُ أَبُو إِسْحَاقَ إِبْرَاهِيمُ بْنُ مُوسَى الشَّاطِبِيُّ (ت: 790ھ)', 'kharji_kitab', 'usul', 'علمِ مقاصدِ شریعت و فلسفۂ احکام', 'کتبِ مطالعہ و تجدیدِ اجتہاد (علماء و طلبۂ تخصص)', NULL, NULL, 'from-amber-950 via-emerald-950 to-stone-900', NULL, 'مقاصدِ شریعت کی تاریخ کا سب سے بڑا شاہکار۔ شریعت کے احکام کے پیچھے حکمتوں، مصلحتوں، اور حیلوں کی ممانعت پر بے مثال تجزیہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shatibi_ch1_daruriyyat', 'kharji_muwafaqat_shatibi', 0, 'كِتَابُ المَقَاصِدِ: المَصَالِحُ الضَّرُورِيَّةُ الخَمْسُ وَحِفْظُهَا', 'باب 1: پانچ بنیادی مقاصدِ شریعت (ضروریاتِ خمسہ) اور ان کی حفاظت کا نظام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shatibi_seg_1_1', 'shatibi_ch1_daruriyyat', 'kharji_muwafaqat_shatibi', 0, 'قَالَ الإِمَامُ أَبُو إِسْحَاقَ الشَّاطِبِيُّ: «تَكَافَلَتْ أَدِلَّةُ الشَّرِيعَةِ كُلُّهَا عَلَى أَنَّهَا وُضِعَتْ لِرِعَايَةِ مَصَالِحِ العِبَادِ فِي المَعَاشِ وَالمَعَادِ. وَالمَصَالِحُ ثَلَاثَةُ أَقْسَامٍ: ضَرُورِيَّةٌ، وَحَاجِيَّةٌ، وَتَحْسِينِيَّةٌ. فَأَمَّا الضَّرُورِيَّةُ فَمَعْنَاهَا أَنَّهَا لَا بُدَّ مِنْهَا فِي قِيَامِ مَصَالِحِ الدِّينِ وَالدُّنْيَا، بِحَيْثُ إِذَا فُقِدَتْ لَمْ تَجْرِ مَصَالِحُ الدُّنْيَا عَلَى اسْتِقَامَةٍ، بَلْ عَلَى فَسَادٍ وَتَهَارُجٍ، وَهِيَ مَجْمُوعَةٌ فِي حِفْظِ خَمْسَةِ أُمُورٍ: حِفْظِ الدِّينِ، وَالنَّفْسِ، وَالنَّسْلِ، وَالمَالِ، وَالعَقْلِ».', 'امام ابو اسحاق شاطبی اندلسی رحمہ اللہ فرماتے ہیں: ''شریعت کے تمام تر دلائل اس بات پر متفق ہیں کہ شریعت دنیا اور آخرت میں بندوں کی مصلحتوں اور بھلائیوں کی حفاظت کے لیے نازل کی گئی ہے۔ اور مصلحتیں تین درجوں میں تقسیم ہیں: ضروریات، حاجیات، اور تحسینیات۔ پس ضروریات وہ بنیادی ستون ہیں جن کے بغیر دین اور دنیا کا نظام قائم رہ ہی نہیں سکتا، اس طرح کہ اگر یہ مفقود ہو جائیں تو دنیا کا امن و سکون تباہ ہو جائے اور ہر طرف فتنہ و فساد برپا ہو جائے؛ اور یہ پانچ بنیادی چیزوں کے تحفظ میں سموئی ہوئی ہیں: دین کا تحفظ، جان کا تحفظ، نسل کا تحفظ، مال کا تحفظ، اور عقل کا تحفظ''۔', 'کتاب ''الموافقات'' علمِ مقاصد الشریعہ کی تاریخ کی سب سے عظیم ترین کتاب سمجھی جاتی ہے۔ امام شاطبی نے ثابت کیا کہ اسلام کا ہر حکم انہی پانچ مقاصد کی تکمیل کے لیے وضع کیا گیا ہے۔', '[{"word":"ضَرُورِيَّةٌ","role":"بدل أو خبر لمبتدأ محذوف","sign":"ضمة","detail":"تفصيل بعد إجمال"},{"word":"حِفْظِ","role":"مجرور بفي","sign":"كسرة","detail":"وهو مضاف والدين مضاف إليه"}]', '["الموافقات في أصول الشريعة للشاطبي، كتاب المقاصد، 2/ 8-15."]', '{"en":"Imam Ash-Shatibi formulates the philosophy of Maqasid al-Shariah: All divine laws exist to preserve human welfare across three tiers (Necessities, Needs, Embellishments). The Five Absolute Necessities (Al-Daruriyyat al-Khams) are the preservation of: Faith, Life, Lineage, Wealth, and Intellect.","ar":"التقعيد المقاصدي الكلي للشريعة وحصر الضرورات الخمس الكبرى."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shatibi_ch2_hajiyyat_tahsiniyyat', 'kharji_muwafaqat_shatibi', 1, 'مَرَاتِبُ الحَاجِيَّاتِ وَالتَّحْسِينِيَّاتِ وَخِدْمَتُهَا لِلأَصْلِ الضَّرُورِيِّ', 'باب 2: حاجیات اور تحسینیات کے مراتب اور ان کا ضروریاتِ خمسہ کا خادم ہونا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shatibi_seg_2_1', 'shatibi_ch2_hajiyyat_tahsiniyyat', 'kharji_muwafaqat_shatibi', 0, '«وَأَمَّا الحَاجِيَّاتُ: فَمَعْنَاهَا أَنَّهَا مُفْتَقَرٌ إِلَيْهَا مِنْ حَيْثُ التَّوْسِعَةُ وَرَفْعُ الضِّيقِ المُؤَدِّي إِلَى الحَرَجِ، كَالرُّخَصِ فِي السَّفَرِ وَعَقْدِ الإِجَارَةِ وَالسَّلَمِ. وَأَمَّا التَّحْسِينِيَّاتُ: فَالأَخْذُ بِمَا يَلِيقُ بِمَحَاسِنِ العَادَاتِ وَمَكَارِمِ الأَخْلَاقِ، كَطَهَارَةِ الخَبَثِ وَسَتْرِ العَوْرَةِ وَآدَابِ الأَكْلِ. وَكُلُّ حَاجِيٍّ وَتَحْسِينِيٍّ إِنَّمَا هُوَ خَادِمٌ لِلأَصْلِ الضَّرُورِيِّ وَمُكَمِّلٌ لَهُ؛ فَكُلُّ خَلَلٍ يَقَعُ فِي الحَاجِيِّ قَدْ يَتَطَرَّقُ بِالفَسَادِ إِلَى الضَّرُورِيِّ».', 'شاطبی رحمہ اللہ فرماتے ہیں: ''حاجیات سے مراد وہ احکام ہیں جن کی ضرورت تنگی دور کرنے، آسانی پیدا کرنے اور مشقت کو ہٹانے کے لیے ہوتی ہے، جیسے سفر میں نماز کا قصر کرنا، اور اجارہ (کرایہ داری) اور بیعِ سلم کے سودے جائز کرنا۔ اور تحسینیات سے مراد وہ محاسنِ اخلاق اور عمدہ عادات ہیں جو انسانی شرافت کے لائق ہیں، جیسے نجاستوں سے پاکی، ستر عورت اور کھانے پینے کے آداب۔ اور جان لو کہ ہر حاجی اور تحسینی حکم دراصل اصل ضروری مقصد کا خادم اور معاون ہے؛ پس جو خلل حاجی یا تحسینی احکام میں واقع ہوگا وہ بالآخر اصل ضروری مقصد کو کمزور کر دے گا''۔', 'یہ مقاصدی درجہ بندی فقہاء کو یہ فہم عطا کرتی ہے کہ کس مسئلے کو کس درجے میں رکھنا ہے اور جب دو مصلحتیں ٹکرائیں تو کس کو کس پر قربان کرنا ہے۔', '[{"word":"خَادِمٌ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"إنما كافة ومكفوفة وخادم خبر المبتدأ هو"},{"word":"المُؤَدِّي","role":"نعت للضيق مجرور","sign":"كسرة مقدرة","detail":"اسم فاعل يعمل عمل فعله"}]', '["الموافقات للشاطبي، 2/ 16-24."]', '{"en":"Needs (Hajiyyat) alleviate hardship (e.g. travel dispensations, leasing), while Embellishments (Tahsiniyyat) foster noble etiquette and aesthetic virtue (e.g. cleanliness, modest dress). Both serve as protective orbital shields around the core Necessities.","ar":"التكامل البنائي بين مراتب المصالح الثلاث وخضوع الفروع للأصول."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_bidayat_mujtahid', 'بِدَايَةُ المُجْتَهِدِ وَنِهَايَةُ المُقْتَصِدِ', 'القَاضِي أَبُو الوَلِيدِ مُحَمَّدُ بْنُ أَحْمَدَ ابْنُ رُشْدٍ الحَفِيدُ (ت: 595ھ)', 'kharji_kitab', 'fiqh', 'فقہِ مقارن و اسبابِ اختلافِ فقہاء', 'کتبِ مطالعہ و مقارنة المذاہب (طلبۂ عالیہ و عالمیہ)', NULL, NULL, 'from-stone-900 via-teal-950 to-emerald-950', NULL, 'فقہِ مقارن کی سب سے بے تعصب اور علمی کتاب۔ ائمہ اربعہ (ابو حنیفہ، مالک، شافعی، احمد) کے اختلافی مسائل میں ان کے دلائل اور اختلاف کی اصولی وجوہات کا عمیق بیان۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ibn_rushd_ch1_mash_ras', 'kharji_bidayat_mujtahid', 0, 'كِتَابُ الطَّهَارَةِ: مَسْأَلَةُ مَسْحِ الرَّأْسِ وَأَسْبَابُ اخْتِلَافِ الفُقَهَاءِ', 'باب 1: مسحِ سر کا مسئلہ اور فقہاء کے درمیان لغوی و روائی اختلاف کے اسباب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ibn_rushd_seg_1_1', 'ibn_rushd_ch1_mash_ras', 'kharji_bidayat_mujtahid', 0, 'قَالَ القَاضِي أَبُو الوَلِيدِ ابْنُ رُشْدٍ الحَفِيدُ: «اخْتَلَفَ العُلَمَاءُ فِي القَدْرِ الوَاجِبِ مِنْ مَسْحِ الرَّأْسِ: فَذَهَبَ مَالِكٌ وَأَحْمَدُ إِلَى وُجُوبِ اسْتِيعَابِ جَمِيعِ الرَّأْسِ، وَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّهُ يُجْزِئُ مَا يَقَعُ عَلَيْهِ اسْمُ المَسْحِ وَلَوْ شَعَرَاتٍ، وَذَهَبَ أَبُو حَنِيفَةَ إِلَى أَنَّ الوَاجِبَ مِقْدَارُ الرُّبُعِ (نَاصِيَةٍ). وَسَبَبُ اخْتِلَافِهِمْ: اشْتِرَاكُ حَرْفِ البَاءِ فِي قَوْلِهِ تَعَالَى: {وَامْسَحُوا بِرُءُوسِكُمْ}؛ هَلْ هِيَ لِلإِلْصَاقِ فَيَكُونُ المَسْحُ لِلْكُلِّ، أَمْ هِيَ لِلتَّبْعِيضِ، أَمْ لِلتَّأْكِيدِ؟ وَتَعَارُضُ الآثَارِ فِي صِفَةِ مَسْحِ النَّبِيِّ ﷺ».', 'قاضی ابو الولید ابن رشد الحفید قرطبی رحمہ اللہ فرماتے ہیں: ''مسحِ سر کے واجب حصے کی مقدار میں ائمہ کا اختلاف ہے: امام مالک اور امام احمد کے نزدیک پورے سر کا استیعاب اور مسح کرنا فرض ہے، امام شافعی کے نزدیک جس پر مسح کا نام بولا جا سکے کافی ہے اگرچہ چند بال ہی کیوں نہ ہوں، اور امام ابو حنیفہ کے نزدیک چوتھائی سر (پیشانی کے بال) کا مسح فرض ہے۔ اور ان کے اختلاف کا بنیادی سبب یہ ہے کہ قرآنی آیت {اور اپنے سروں کا مسح کرو} میں حرفِ ''باء'' لغت میں مشترک المعنی ہے؛ آیا یہ باء الساق (ملانے) کے لیے ہے جس سے پورے سر کا مسح مراد ہوگا، یا باء تبعیض (بعض حصے) کے لیے ہے، یا تاکید کے لیے ہے؟ اور اس کے ساتھ رسول اللہ ﷺ کے مسح کی احادیث میں ظاہری تعارض بھی اختلاف کا سبب بنا''۔', 'بداية المجتهد فقہ مقارن (تقابلی فقہ) کی دنیا کی بے نظیر کتاب ہے۔ ابن رشد نے فقہی فتووں کے پیچھے کارفرما لغوی، اصولی اور حدیثی اسباب کو آشکار کیا ہے تاکہ طالب علم تعصب سے نکل کر علم کی اصل تک پہنچے۔', '[{"word":"القَدْرِ","role":"مجرور بفي","sign":"كسرة","detail":"بدل أو مضاف إليه من الواجب"},{"word":"اشْتِرَاكُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"سبب مبتدأ واشتراك خبره"}]', '["بداية المجتهد ونهاية المقتصد لابن رشد، كتاب الطهارة، 1/ 12-16."]', '{"en":"Ibn Rushd''s celebrated comparative method: He analyzes why the four Imams differed on the portion of head-wiping in Wudu—tracing it precisely to the grammatical ambiguity of the preposition ''Ba'' (whether indicative of accompaniment, partitive, or emphatic) and differing authentic hadiths.","ar":"تحليل أسباب اختلاف الفقهاء استناداً إلى دلالات الحروف وتعارض الآثار."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ibn_rushd_ch2_khiyar_majlis', 'kharji_bidayat_mujtahid', 1, 'كِتَابُ البُيُوعِ: مَسْأَلَةُ خِيَارِ المَجْلِسِ بَيْنَ النَّصِّ وَالقِيَاسِ', 'باب 2: کتاب البیوع — خیارِ مجلس کے مسئلے میں ائمہ کے دلائل اور ترجیحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ibn_rushd_seg_2_1', 'ibn_rushd_ch2_khiyar_majlis', 'kharji_bidayat_mujtahid', 0, '«مَسْأَلَةٌ: إِذَا تَبَايَعَ الرَّجُلَانِ فَكُلُّ وَاحِدٍ مِنْهُمَا بِالخِيَارِ مَا لَمْ يَتَفَرَّقَا عِنْدَ الشَّافِعِيِّ وَأَحْمَدَ، عَمَلاً بِحَدِيثِ ابْنِ عُمَرَ: «البَيِّعَانِ بِالخِيَارِ مَا لَمْ يَتَفَرَّقَا». وَقَالَ مَالِكٌ وَأَبُو حَنِيفَةَ: لَا خِيَارَ بَعْدَ الإِيجَابِ وَالقَبُولِ، وَالبَيْعُ يَلْزَمُ بِالكَلَامِ. وَسَبَبُ الخِلَافِ: تَرْجِيحُ قِيَاسِ اللُّزُومِ فِي العُقُودِ وَقَوْلِهِ: {أَوْفُوا بِالْعُقُودِ} عِنْدَ الحَنَفِيَّةِ، وَعَمَلِ أَهْلِ المَدِينَةِ عِنْدَ مَالِكٍ، فِي مُقَابَلَةِ حَمْلِ التَّفَرُّقِ عَلَى تَبَايُنِ الأَبْدَانِ عِنْدَ الجُمْهُورِ».', 'ابن رشد فرماتے ہیں: ''مسئلہ: جب دو آدمی سودا کر لیں تو امام شافعی اور امام احمد کے نزدیک دونوں کو مجلس میں سودا ختم کرنے کا اختیار (خیارِ مجلس) حاصل رہتا ہے جب تک کہ وہ جدا نہ ہوں، کیونکہ حضرت ابن عمر کی حدیث ہے: ''بیچنے اور خریدنے والے کو اختیار ہے جب تک وہ الگ نہ ہوں''۔ جبکہ امام مالک اور امام ابو حنیفہ فرماتے ہیں: ایجاب و قبول کے فوراً بعد بیع لازم ہو جاتی ہے اور محض کلام مکمل ہونے سے خیار ختم ہو جاتا ہے۔ اور اختلاف کا سبب یہ ہے کہ حنفیہ نے عمومی نصوص جیسے {عہدوں کو پورا کرو} اور عقود کے لزوم کے قیاس کو ترجیح دی، اور امام مالک نے اہل مدینہ کے تعامل کو خبرِ واحد پر مقدم جانا، جبکہ جمہور نے ''تفرق'' کو جسمانی طور پر جدا ہونے پر محمول کیا''۔', 'یہ مسئلہ اصولِ فقہ کے اس عظیم اصول کو واضح کرتا ہے کہ کس طرح ایک مکتبِ فکر خبرِ واحد پر عمل کرتا ہے جبکہ دوسرا مکتب اسے قرآن کے عمومی قواعد کے ساتھ تطبیق دیتا ہے۔', '[{"word":"البَيِّعَانِ","role":"مبتدأ مرفوع","sign":"ألف","detail":"مثنى مذكر"},{"word":"بِالخِيَارِ","role":"جار ومجرور شبه جملة خبر","sign":"كسرة","detail":"في محل رفع"}]', '["بداية المجتهد، كتاب البيوع، 2/ 120-125، وأخرجه البخاري (2110)."]', '{"en":"The classic debate on Khiyar al-Majlis (the option to cancel a sale before parting): Ash-Shafi''i and Ahmad validate it via Ibn Umar''s hadith, whereas Malik relies on the Medinan practice (''Amal Ahl al-Madinah) and Abu Hanifah relies on the strict sanctity of completed contracts ({Fulfil your contracts}).","ar":"الموازنة بين حجية الآحاد وعمل أهل المدينة والقواعد العامة للعقود."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_qawaid_ahkam_izz', 'قَوَاعِدُ الأَحْكَامِ فِي مَصَالِحِ الأَنَامِ', 'سُلْطَانُ العُلَمَاءِ الإِمَامُ عِزُّ الدِّينِ عَبْدُ العَزِيزِ بْنُ عَبْدِ السَّلَامِ (ت: 660ھ)', 'kharji_kitab', 'usul', 'جلبِ مصالح، درءِ مفاسد و حریتِ فکر', 'کتبِ مطالعہ و تربیتِ فقہاء و قضاۃ', NULL, NULL, 'from-teal-950 via-emerald-900 to-amber-950', NULL, 'سلطان العلماء کی وہ انقلابی تصنیف جس نے ثابت کیا کہ پوری شریعتِ اسلامیہ کا خلاصہ ایک ہی جملہ ہے: ''مصالح کو حاصل کرنا اور برائیوں کو مٹانا''۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('izz_ch1_masalih', 'kharji_qawaid_ahkam_izz', 0, 'فَصْلٌ فِي أَنَّ الشَّرِيعَةَ كُلَّهَا مَصَالِحُ: دَرْءُ مَفَاسِدَ أَوْ جَلْبُ مَصَالِحَ', 'باب 1: شریعتِ اسلامیہ کا اصل جوہر — مفاسد کو روکنا اور مصالح کو حاصل کرنا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('izz_seg_1_1', 'izz_ch1_masalih', 'kharji_qawaid_ahkam_izz', 0, 'قَالَ سُلْطَانُ العُلَمَاءِ الإِمَامُ العِزُّ بْنُ عَبْدِ السَّلَامِ: «الشَّرِيعَةُ كُلُّهَا مَصَالِحُ: إِمَّا تَدْرَأُ مَفَاسِدَ أَوْ تَجْلِبُ مَصَالِحَ؛ فَإِذَا سَمِعْتَ اللَّهَ يَقُولُ: {يَا أَيُّهَا الَّذِينَ آمَنُوا} فَتَأَمَّلْ وَصِيَّتَهُ بَعْدَ نِدَائِهِ، فَلَا تَجِدُ إِلَّا خَيْراً يَحُثُّكَ عَلَيْهِ، أَوْ شَرّاً يَزْجُرُكَ عَنْهُ، أَوْ جَمْعاً بَيْنَ التَّرْغِيبِ وَالتَّرْهِيبِ. فَالتَّكَالِيفُ كُلُّهَا رَاجِعَةٌ إِلَى مَصَالِحِ العِبَادِ فِي دُنْيَاهُمْ وَأُخْرَاهُمْ، وَاللَّهُ غَنِيٌّ عَنْ عِبَادِهِ لَا تَنْفَعُهُ طَاعَةُ الطَّائِعِينَ وَلَا تَضُرُّهُ مَعْصِيَةُ العَاصِينَ».', 'سلطان العلماء امام العز بن عبد السلام رحمہ اللہ فرماتے ہیں: ''پوری شریعتِ اسلامی سراپا مصالح اور بھلائیوں کا مجموعہ ہے: یا تو وہ نقصانات اور برائیوں کا سد باب کرتی ہے یا فائدوں اور نیکیوں کو کھینچ لاتی ہے؛ پس جب تم اللہ کا فرمان سنو: {اے ایمان والو!} تو اس پکار کے بعد آنے والی ہدایت پر غور کرو، تم اس میں لازماً یا تو ایسی بھلائی پاؤ گے جس کی تمہیں ترغیب دی جا رہی ہوگی، یا ایسی برائی جس سے سختی سے روکا جا رہا ہوگا، یا دونوں کا امتزاج۔ پس تمام شرعی احکام بندوں ہی کی دنیا و آخرت کی بہتری کے لیے ہیں، اور اللہ اپنے بندوں سے بالکل بے پرواہ اور غنی ہے، نہ اطاعت گزاروں کی بندگی سے اسے کوئی نفع ہوتا ہے اور نہ نافرمانوں کی سرکشی سے اس کا کوئی نقصان ہوتا ہے''۔', 'قواعد الأحكام سلطان العلماء امام عز بن عبد السلام کا وہ بے مثل کارنامہ ہے جس نے فقہ کو خشک قانونی احکام سے نکال کر حکمت اور انسان دوستی کے بلند ترین روحانی مقام پر پہنچا دیا۔', '[{"word":"الشَّرِيعَةُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"كلها توكيد معنوي ومصالح خبر المبتدأ"},{"word":"خَيْراً","role":"مفعول به لتجد منصوب","sign":"فتحة","detail":"استثناء مفرغ"}]', '["قواعد الأحكام في مصالح الأنام، 1/ 9-14، دار الكتب العلمية."]', '{"en":"Sultan al-Ulama Al-''Izz ibn ''Abd al-Salam writes: The entirety of the Shariah revolves around benefits—either warding off harms or securing utilities. Divine commandments serve human temporal and eternal welfare; Allah is completely self-sufficient and independent of human deeds.","ar":"الأصل المقاصدي الشامل بأن التكاليف معللة برعاية مصالح الخلق تنزهاً للحق سبحانه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('izz_ch2_taqdeem', 'kharji_qawaid_ahkam_izz', 1, 'فَصْلٌ فِي قَوَاعِدِ التَّرْجِيحِ: تَقْدِيمُ أَعْلَى المَصْلَحَتَيْنِ وَارْتِكَابُ أَدْنَى المَفْسَدَتَيْنِ', 'باب 2: ترجیحات کا میزان — دو مصالح میں بڑی مصلحت کو ترجیح اور دو نقصانوں میں ہلکے نقصان کا انتخاب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('izz_seg_2_1', 'izz_ch2_taqdeem', 'kharji_qawaid_ahkam_izz', 0, '«إِذَا تَزَاحَمَتِ المَصَالِحُ قُدِّمَ أَعْلَاهَا، وَإِذَا تَزَاحَمَتِ المَفَاسِدُ ارْتُكِبَ أَدْنَاهَا؛ فَمَنْ وَجَدَ غَرِيقاً مَعْصُوماً فِي وَقْتِ الصَّلَاةِ وَضَاقَ الوَقْتُ، قَدَّمَ إِنْقَاذَ الغَرِيقِ عَلَى أَدَاءِ الصَّلَاةِ فِي وَقْتِهَا؛ لِأَنَّ مَصْلَحَةَ إِحْيَاءِ النَّفْسِ أَعْظَمُ، وَالصَّلَاةُ يُمْكِنُ قَضَاؤُهَا وَالنَّفْسُ لَا يُمْكِنُ تَدَارُكُهَا. وَمَنْ أُكْرِهَ عَلَى القَتْلِ لَمْ يَجُزْ لَهُ أَنْ يَقْتُلَ لِيَفْدِيَ نَفْسَهُ؛ لِأَنَّ نَفْسَهُ لَيْسَتْ بِأَوْلَى مِنْ نَفْسِ غَيْرِهِ».', 'سلطان العلماء فرماتے ہیں: ''جب دو مصلحتیں باہم ٹکرا جائیں تو ان میں سے جو سب سے اعلیٰ اور بڑی مصلحت ہو اسے آگے رکھا جائے گا، اور جب دو مفاسد اور برائیاں سامنے آ جائیں تو ان میں سے ہلکی اور کمتر برائی کو اختیار کر کے بڑی برائی کو دفع کیا جائے گا؛ پس جس شخص نے نماز کے وقت کسی معصوم انسان کو ڈوبتے دیکھا اور نماز کا وقت تنگ ہو رہا ہو، تو اس پر واجب ہے کہ وہ نماز پر ڈوبتے ہوئے انسان کی جان بچانے کو ترجیح دے؛ کیونکہ انسانی جان بچانے کی مصلحت زیادہ بڑی ہے، اور نماز کی قضا بعد میں ممکن ہے جبکہ ضائع ہونے والی جان کی تلافی ممکن نہیں۔ لیکن جس پر کسی دوسرے کو قتل کرنے کے لیے جبر کیا جائے اس کے لیے اپنی جان بچانے کی خاطر دوسرے کو قتل کرنا ہرگز جائز نہیں، کیونکہ اس کی اپنی جان دوسرے کی جان سے زیادہ قیمتی نہیں ہے''۔', 'یہ اصول ایمرجنسی، طب، جنگ اور ریاست کے نازک ترین فیصلوں میں فکری راہنمائی فراہم کرتا ہے جہاں نیکیوں اور برائیوں کے تصادم میں فیصلے کرنے ہوتے ہیں۔', '[{"word":"أَعْلَاهَا","role":"نائب فاعل لقُدِّم مرفوع","sign":"ضمة مقدرة","detail":"قدم فعل مبني للمجهول"},{"word":"إِنْقَاذَ","role":"مفعول به منصوب","sign":"فتحة","detail":"قدم فاعله مستتر وإنقاذ مفعول"}]', '["قواعد الأحكام في مصالح الأنام، 1/ 62-70."]', '{"en":"The Golden Principle of Prioritization: When utilities conflict, uphold the superior; when evils collide, endure the lesser. Saving a drowning soul overrides punctual prayer because life cannot be compensated whereas missed prayer can be made up.","ar":"قواعد الترجيح والموازنة بين المصالح والمفاسد المتعارضة في فقه النوازل."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_furuq_qarafi', 'أَنْوَارُ البُرُوقِ فِي أَنْوَاءِ الفُرُوقِ', 'الإِمَامُ شِهَابُ الدِّينِ أَبُو العَبَّاسِ أَحْمَدُ بْنُ إِدْرِيسَ القَرَافِيُّ (ت: 684ھ)', 'kharji_kitab', 'usul', 'فقہی اور اصولی فرق کے باریک ضوابط', 'کتبِ مطالعہ و تخصص (علومِ شریعت)', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'فقہ و اصول کی وہ نادر کتاب جو بظاہر ایک جیسے نظر آنے والے دو مسائل، دو اصولوں اور احکام کے درمیان پائے جانے والے دقیق اور لطیف فرق کو واضح کرتی ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qarafi_ch1_shahadah_riwayah', 'kharji_furuq_qarafi', 0, 'الفَرْقُ الأَوَّلُ: بَيْنَ قَاعِدَةِ الشَّهَادَةِ وَقَاعِدَةِ الرِّوَايَةِ', 'فرق 1: شہادت (عدالتی گواہی) اور روایت (حدیث کی نقل) کے مابین بنیادی اصولی فرق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qarafi_seg_1_1', 'qarafi_ch1_shahadah_riwayah', 'kharji_furuq_qarafi', 0, 'قَالَ الإِمَامُ شِهَابُ الدِّينِ القَرَافِيُّ: «الفَرْقُ بَيْنَ الشَّهَادَةِ وَالرِّوَايَةِ: أَنَّ الرِّوَايَةَ خَبَرٌ عَامٌّ كُلِّيٌّ لَا يَخْتَصُّ بِمُعَيَّنٍ، فَلَا يَجُرُّ بِهَا الرَّاوِي نَفْعاً لِنَفْسِهِ، وَلِذَلِكَ تُقْبَلُ رِوَايَةُ العَبْدِ، وَالمَرْأَةِ، وَالقَرِيبِ لِقَرِيبِهِ كَالابْنِ عَنْ أَبِيهِ. أَمَّا الشَّهَادَةُ فَهِيَ إِخْبَارٌ عَنْ حَقٍّ خَاصٍّ مُعَيَّنٍ لِشَخْصٍ عَلَى آخَرَ، فَدَخَلَتْهَا التُّهْمَةُ؛ وَلِذَلِكَ رُدَّتْ شَهَادَةُ العَدُوِّ عَلَى عَدُوِّهِ، وَشَهَادَةُ الوَالِدِ لِوَلَدِهِ، وَاشْتُرِطَ فِيهَا العَدَدُ وَالحُرِّيَّةُ وَالذُّكُورَةُ فِي الحُدُودِ».', 'امام شہاب الدین احمد بن ادریس القرافی مالکی رحمہ اللہ فرماتے ہیں: ''شہادت اور روایت کے درمیان فرق یہ ہے: روایت ایک ایسا عام اور کلی شرعی حکم ہوتا ہے جو کسی خاص فرد کے لیے مختص نہیں ہوتا، لہٰذا راوی اس سے اپنی ذات کے لیے کوئی ذاتی فائدہ حاصل نہیں کر سکتا، اسی وجہ سے حدیث کی روایت میں غلام، عورت، اور بیٹے کی اپنے باپ سے روایت بلا شبہ قبول کی جاتی ہے۔ لیکن شہادت (گواہی) عدالت میں کسی ایک خاص شخص کے خلاف دوسرے کے حق کا دعویٰ ہوتی ہے، لہٰذا اس میں ذاتی عناد یا فائدے کی تہمت لگ سکتی ہے؛ اسی وجہ سے دشمن کی اپنے دشمن کے خلاف گواہی رد کر دی جاتی ہے، اور باپ کی اپنے بیٹے کے حق میں گواہی قبول نہیں ہوتی، اور شہادت میں گواہوں کی تعداد، آزادی اور حدود میں مرد ہونا شرط کیا گیا ہے''۔', 'کتاب ''الفروق'' امام قرافی کا وہ شاہکار ہے جس نے فقہی باریکیوں اور ان کے درمیانی دقیق فرقوں کو واضح کیا۔ اس فرق نے ثابت کیا کہ کیوں کتبِ حدیث میں ہر سچے راوی کی روایت قبول ہوئی جبکہ عدالت کے قوانین زیادہ سخت رکھے گئے۔', '[{"word":"خَبَرٌ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"الرواية اسمها وخبر خبرها"},{"word":"التُّهْمَةُ","role":"فاعل دخلتها مرفوع","sign":"ضمة","detail":"والهاء ضمير مفعول به مقدم"}]', '["أنوار البروق في أنواء الفروق للقرافي، الفرق الأول، 1/ 12-20."]', '{"en":"Imam Al-Qarafi''s Distinction 1: Between Hadith transmission (Riwayah) and courtroom testimony (Shahadah). Transmission carries universal relevance devoid of personal bias (thus women, kin, and slaves are unconditionally accepted); courtroom testimony entails specific disputed claims subject to suspicion and strict admissibility filters.","ar":"الفروق الأصولية الدقيقة في باب الإثبات القضائي وقبول الرواية النبوية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qarafi_ch2_tasarrufat_nabiy', 'kharji_furuq_qarafi', 1, 'الفَرْقُ الثَّالِثُ وَالسِّتُّونَ: بَيْنَ تَصَرُّفِهِ ﷺ بِالإِمَامَةِ وَتَصَرُّفِهِ بِالفُتْيَا', 'فرق 2: رسول اللہ ﷺ کے بحیثیتِ حاکم و امام فیصلے اور بحیثیتِ مفتی ارشادات کا فرق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qarafi_seg_2_1', 'qarafi_ch2_tasarrufat_nabiy', 'kharji_furuq_qarafi', 0, '«اعْلَمْ أَنَّ رَسُولَ اللَّهِ ﷺ هُوَ الإِمَامُ الأَعْظَمُ، وَالقَاضِي الأَعْدَلُ، وَالمُفْتِي الأَكْمَلُ؛ فَمَا قَالَهُ أَوْ فَعَلَهُ بِطَرِيقِ الفُتْيَا وَالتَّبْلِيغِ فَهُوَ شَرِيعَةٌ عَامَّةٌ لِكُلِّ مُسْلِمٍ إِلَى يَوْمِ القِيَامَةِ، كَقَوْلِهِ: «بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ». وَمَا تَصَرَّفَ فِيهِ بِحُكْمِ الإِمَامَةِ (كَقِسْمَةِ الغَنَائِمِ وَإِقَامَةِ الجُيُوشِ وَإِقْطَاعِ الأَرَاضِي وَصَرْفِ بَيْتِ المَالِ) فَلَا يَجُوزُ لِأَحَدٍ أَنْ يُقْدِمَ عَلَيْهِ إِلَّا بِإِذْنِ إِمَامِ المُسْلِمِينَ؛ لِأَنَّهُ تَصَرُّفٌ سِيَاسِيٌّ مَنُوطٌ بِالمَصْلَحَةِ العَامَّةِ».', 'امام قرافی فرماتے ہیں: ''جان لو کہ رسول اللہ ﷺ مسلمانوں کے سب سے عظیم سربراہِ مملکت (امام اعظم)، سب سے عادل قاضی، اور سب سے کامل مفتی تھے؛ پس آپ ﷺ نے تبلیغِ دین اور فتویٰ کے طور پر جو فرمایا وہ قیامت تک کے تمام مسلمانوں کے لیے عمومی اور ابدی شریعت ہے، جیسے آپ کا فرمان: ''اسلام کی بنیاد پانچ چیزوں پر ہے''۔ لیکن وہ امور جن میں آپ ﷺ نے بحیثیتِ سربراہِ ریاست اور امام فیصلہ فرمایا (جیسے غنیمت کے مال کی تقسیم، فوجیں روانہ کرنا، جاگیریں عطا کرنا، اور بیت المال کا خرچ کرنا) تو بعد میں کسی عام فرد کے لیے جائز نہیں کہ وہ حکمرانِ وقت کی اجازت کے بغیر ان پر اقدام کرے؛ کیونکہ یہ سیاسی و انتظامی تصرفات ہیں جو عمومی ملکی مصلحت کے تابع ہوتے ہیں''۔', 'یہ فرق دورِ حاضر کی اسلامی ریاست اور فقہِ سیاسی کے لیے سنگِ میل ہے۔ قرافی نے واضح کیا کہ نبوی ارشادات کے مختلف قانونی مقامات کو سمجھے بغیر انتہا پسندی اور لاقانونیت جنم لیتی ہے۔', '[{"word":"شَرِيعَةٌ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"فهو مبتدأ وشريعة خبره"},{"word":"سِيَاسِيٌّ","role":"نعت لتصرف مرفوع","sign":"ضمة","detail":"يصف طبيعة التصرف الإمامي"}]', '["الفروق للقرافي، الفرق 63، 3/ 205-212، والإحكام في تمييز الفتاوى عن الأحكام."]', '{"en":"Al-Qarafi''s monumental distinction regarding Prophetic actions: Distinguishing between the Prophet''s universal religious promulgations (Fatwa/Risalah) binding on all individuals, and his administrative actions as Head of State (Imamah) which can only be enacted by the governing authority.","ar":"تحرير مقامات التصرفات النبوية الشريفة وأثرها البالغ في الفقه السياسي المعاصر."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_madkhal_zarqa', 'المَدْخَلُ الفِقْهِيُّ العَامُّ', 'العَلَّامَةُ الفَقِيهُ الأُصُولِيُّ مُصْطَفَى أَحْمَدَ الزَّرْقَا (ت: 1420ھ)', 'kharji_kitab', 'fiqh', 'نظریاتِ فقہِ اسلامی و قوانینِ جدیدہ', 'کتبِ مطالعہ و فقہِ معاصر (طلبۂ عالیہ و تخصص)', NULL, NULL, 'from-teal-900 via-stone-900 to-emerald-950', NULL, 'عصرِ حاضر میں فقہِ اسلامی کی نظریہ سازی (نظریہ عقد، نظریہ ملکیت، نظریہ ذمہ داری) پر عالمِ اسلام کا سب سے معتبر اور جدید شاہکار۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('zarqa_ch1_khasais', 'kharji_madkhal_zarqa', 0, 'النَّظَرِيَّةُ العَامَّةُ لِلْفِقْهِ الإِسْلَامِيِّ وَمُمَيِّزَاتُهُ التَّشْرِيعِيَّةُ', 'باب 1: فقہِ اسلامی کا عمومی نظریہ اور اس کی قانون سازی کی خصوصیات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('zarqa_seg_1_1', 'zarqa_ch1_khasais', 'kharji_madkhal_zarqa', 0, 'قَالَ العَلَّامَةُ الشَّيْخُ مُصْطَفَى أَحْمَدَ الزَّرْقَا: «يَتَمَيَّزُ الفِقْهُ الإِسْلَامِيُّ عَنِ القَوَانِينِ الوَضْعِيَّةِ بِخَصَائِصَ فَرِيدَةٍ: أُولَاهَا: أَنَّهُ رَبَّانِيُّ المَصْدَرِ يَسْتَمِدُّ قُوَّتَهُ الإِلْزَامِيَّةَ مِنْ عَقِيدَةِ الإِيمَانِ، مِمَّا يَجْعَلُ لَهُ سُلْطَاناً عَلَى الضَّمَائِرِ فِي السِّرِّ وَالعَلَنِ. ثَانِيهَا: الجَمْعُ بَيْنَ الثَّبَاتِ فِي الأُصُولِ وَالمَقَاصِدِ، وَالمُرُونَةِ فِي الفُرُوعِ وَالتَّطْبِيقَاتِ بِحَسَبِ تَغَيُّرِ الزَّمَانِ. ثَالِثُهَا: أَنَّهُ نِظَامٌ شَامِلٌ يُنَظِّمُ عِلَاقَةَ الإِنْسَانِ بِرَبِّهِ فِي العِبَادَاتِ، وَعِلَاقَتَهُ بِأَخِيهِ فِي المُعَامَلَاتِ، وَعِلَاقَةَ الدَّوْلَةِ بِالمُجْتَمَعِ».', 'علامہ مصطفیٰ احمد الزرقا رحمہ اللہ فرماتے ہیں: ''فقہ اسلامی دنیا کے خود ساختہ انسانی قوانین سے ایسی ممتاز خصوصیات کی بنا پر جدا ہے جن کی کوئی نظیر نہیں: پہلی صفت: یہ ربانی اور الٰہی ماخذ کا حامل ہے جس کی پابندی کی طاقت بندے کے ایمانی عقیدے سے پھوٹتی ہے، جس کی وجہ سے خلوت و جلوت میں انسان کے ضمیر پر اس کی حکمرانی قائم رہتی ہے۔ دوسری صفت: یہ اصولوں اور مقاصد میں دائمی ثبات و پختگی، اور زمانے کے تقاضوں کے مطابق فروعی مسائل میں ہمہ جہت لچک و وسعت کا حسین امتزاج ہے۔ تیسری صفت: یہ ایک ہمہ گیر نظام ہے جو عبادات میں بندے کا رب سے تعلق، معاملات میں انسان کا معاشرے سے تعلق اور حکومت کا شہریوں سے تعلق کامل انصاف کے ساتھ قائم کرتا ہے''۔', 'کتاب ''المدخل الفقهي العام'' دورِ جدید میں فقہِ اسلامی کو قانونی دفعات اور جدید تعبیرات کے سانچے میں ڈھالنے والی سب سے معتبر کتاب مانی جاتی ہے۔', '[{"word":"رَبَّانِيُّ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"والهاء اسمها"},{"word":"شَامِلٌ","role":"نعت لنظام مرفوع","sign":"ضمة","detail":"يصف شمولية الفقه"}]', '["المدخل الفقهي العام لمصطفى الزرقا، 1/ 45-58، دار القلم."]', '{"en":"Shaykh Mustafa Al-Zarqa highlights the supremacy of Islamic jurisprudence: Its divine origin commanding voluntary internal conscience, its equilibrium between immutable foundational values and adaptable pragmatic branches, and its holistic coverage encompassing spiritual, civil, and constitutional spheres.","ar":"معالم الإعجاز التشريعي في الفقه الإسلامي ومقارنته بالمدارس القانونية الغربية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('zarqa_ch2_nadariyyat_aqd', 'kharji_madkhal_zarqa', 1, 'نَظَرِيَّةُ العَقْدِ وَالإِرَادَةِ المُنْفَرِدَةِ فِي التَّشْرِيعِ الإِسْلَامِيِّ', 'باب 2: فقہِ اسلامی میں نظریۂ عقد (معاہدات) اور یکطرفہ ارادے کی قانونی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('zarqa_seg_2_1', 'zarqa_ch2_nadariyyat_aqd', 'kharji_madkhal_zarqa', 0, '«العَقْدُ فِي الفِقْهِ الإِسْلَامِيِّ هُوَ: ارْتِبَاطُ إِيجَابٍ بِقَبُولٍ عَلَى وَجْهٍ مَشْرُوعٍ يَثْبُتُ أَثَرُهُ فِي المَعْقُودِ عَلَيْهِ. وَالأَصْلُ فِي العُقُودِ وَالشُّرُوطِ عِنْدَ مُحَقِّقِي الفُقَهَاءِ الصِّحَّةُ وَالإِبَاحَةُ، إِلَّا مَا حَرَّمَهُ الشَّارِعُ بِنَصٍّ صَرِيحٍ أَوْ قَاعِدَةٍ قَاطِعَةٍ، عَمَلاً بِقَوْلِهِ ﷺ: «المُسْلِمُونَ عَلَى شُرُوطِهِمْ إِلَّا شَرْطاً حَرَّمَ حَلَالاً أَوْ أَحَلَّ حَرَاماً». وَقَدْ سَبَقَ الفِقْهُ الإِسْلَامِيُّ القَوَانِينَ الحَدِيثَةَ فِي الِاعْتِرَافِ بِأَثَرِ الإِرَادَةِ المُنْفَرِدَةِ فِي مِثْلِ الوَقْفِ وَالجِعَالَةِ وَالإِبْرَاءِ».', 'شیخ مصطفیٰ زرقا فرماتے ہیں: ''فقہ اسلامی میں عقد (معاہدے) کی تعریف یہ ہے: جائز شرعی طریقے پر ایجاب کا قبول کے ساتھ ایسا ربط قائم ہونا جس کا قانونی اثر مطلوبہ چیز پر ثابت ہو جائے۔ اور محقق فقہاء کے نزدیک معاہدات اور باہمی شرائط میں اصل بنیاد صحت اور اباحت و آزادی ہے، سوائے اس شرط کے جسے شریعت نے واضح نص یا قطعی اصول سے حرام قرار دیا ہو، نبی ﷺ کے اس فرمان پر عمل کرتے ہوئے: ''مسلمان اپنی طے کردہ شرائط کے پابند ہیں سوائے اس شرط کے جو کسی حلال کو حرام یا حرام کو حلال بنا دے''۔ اور فقہ اسلامی نے وقف، جعالہ (انعامی اعلان) اور بری الذمہ کرنے جیسے معاملات میں یکطرفہ ارادے کے اثر کو تسلیم کر کے جدید مغربی قوانین پر صدیوں پہلے سبقت حاصل کی تھی''۔', 'مصطفیٰ زرقا نے اس تحقیق کے ذریعے ثابت کیا کہ اسلامی فقہ تجارتی معاہدات اور شرائط میں انتہا درجے کی آزادی اور لچک فراہم کرتا ہے۔', '[{"word":"ارْتِبَاطُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"العقد مبتدأ وارتباط خبره"},{"word":"حَرَاماً","role":"مفعول به لأحل منصوب","sign":"فتحة","detail":"يبين ما لا يجوز اشتراطه"}]', '["المدخل الفقهي العام، 1/ 320-335، وأخرجه أبو داود (3594) والترمذي (1352)."]', '{"en":"The Theory of Contract in Islamic Law: A legally binding nexus of offer and acceptance. Default status of contracts is validity and freedom of stipulation unless violating an explicit prohibition, pioneering unilateral declarations (Iradah Munfaridah) like endowments centuries ahead of Western law.","ar":"تأصيل حرية التعاقد وسلطان الإرادة في الفقه الإسلامي المقارن."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ilam_muwaqqiin_jawziyyah', 'إِعْلَامُ المُوَقِّعِينَ عَنْ رَبِّ العَالَمِينَ', 'الإِمَامُ الحَافِظُ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'usul', 'اصولِ افتاء، قیاس و مقاصدِ شریعت', 'کتبِ مطالعہ و مفتیانِ کرام کے لیے لازمی مرجع', NULL, NULL, 'from-amber-950 via-emerald-950 to-stone-900', NULL, 'مفتی کو ''اللہ کے دستخط کرنے والے'' کا مقام دے کر فتوے کے خطرات، حیلوں کی مذمت اور سلف کے طریقہ اجتہاد پر وقیع ترین کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jawziyyah_ilam_ch1_fatwa', 'kharji_ilam_muwaqqiin_jawziyyah', 0, 'فَصْلٌ فِي خُطُورَةِ الفُتْيَا وَأَنَّ المَفْتِيَ مُوَقِّعٌ عَنْ رَبِّ العَالَمِينَ', 'باب 1: منصبِ افتاء کی نزاکت — مفتی رب العالمین کی جانب سے دستخط کرنے والا ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jawziyyah_ilam_seg_1_1', 'jawziyyah_ilam_ch1_fatwa', 'kharji_ilam_muwaqqiin_jawziyyah', 0, 'قَالَ الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ: «إِذَا كَانَ مَنْصِبُ التَّوْقِيعِ عَنِ المُلُوكِ فِي الدُّنْيَا لَا يَنَالُهُ إِلَّا خِيَارُ النَّاسِ أَهْلُ الصِّدْقِ وَالأَمَانَةِ وَالعِلْمِ، فَكَيْفَ بِمَنْصِبِ التَّوْقِيعِ عَنْ رَبِّ السَّمَاوَاتِ وَالأَرْضِ؟! فَالمُفْتِي مُوَقِّعٌ عَنِ اللَّهِ تَعَالَى شَرِيعَتَهُ، فَلْيَنْظُرْ كَيْفَ يُوَقِّعُ، وَلْيَحْذَرْ أَنْ يَقُولَ لِمَا لَمْ يُحَرِّمْهُ اللَّهُ: هَذَا حَرَامٌ، أَوْ لِمَا لَمْ يُوجِبْهُ: هَذَا وَاجِبٌ؛ فَيَقَعَ فِي قَوْلِهِ سُبْحَانَهُ: {وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَذَا حَلَالٌ وَهَذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ}».', 'امام ابن قیم الجوزیہ رحمہ اللہ فرماتے ہیں: ''اگر دنیا میں بادشاہوں کی جانب سے فرامین پر دستخط کرنے کا منصب صرف سب سے معزز، سچے، امانت دار اور لائق ترین انسانوں کو ملتا ہے، تو ذرا سوچو زمین و آسمان کے پروردگار کی جانب سے دستخط کرنے کے منصب کی کیا عظمت ہوگی؟! پس مفتی اللہ تبارک و تعالیٰ کی جانب سے اس کی شریعت پر دستخط کرنے والا ہے، لہٰذا وہ سوچے کہ وہ کیسا دستخط کر رہا ہے، اور اس بات سے سخت ڈرے کہ جس چیز کو اللہ نے حرام نہ کیا ہو اس پر کہہ دے کہ یہ حرام ہے، یا جسے اللہ نے واجب نہ کیا ہو اس پر کہہ دے کہ یہ واجب ہے؛ اور یوں وہ اللہ تعالیٰ کے اس غضب کے نیچے آ جائے: {اور تمہاری زبانیں جو جھوٹ تراشتی ہیں اس پر یہ نہ کہو کہ یہ حلال ہے اور یہ حرام ہے تاکہ اللہ پر جھوٹ باندھو}''۔', 'کتاب ''إعلام الموقعين عن رب العالمين'' اصولِ فقہ، مقاصدِ شریعت اور آدابِ افتاء کی تاریخ کی سب سے اثر انگیز کتاب ہے۔ ابن قیم نے واضح کیا کہ حلال و حرام کا فتویٰ دینا کتنا نازک کام ہے۔', '[{"word":"مُوَقِّعٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"المفتي مبتدأ وموقع خبره"},{"word":"الكَذِبَ","role":"مفعول به لتصف منصوب","sign":"فتحة","detail":"أو نعت لمصدر محذوف"}]', '["إعلام الموقعين عن رب العالمين، 1/ 10-14، دار ابن الجوزي."]', '{"en":"Ibn al-Qayyim writes: If signing state decrees on behalf of earthly kings requires supreme trustworthiness, what of signing decrees on behalf of the Lord of the Universe?! A Mufti is a signatory on behalf of Allah—he must tread with trembling caution before pronouncing something Halal or Haram.","ar":"التحذير من الجرأة على الفتيا بغير علم والتوقيع عن رب العالمين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jawziyyah_ilam_ch2_taghayyur_fatwa', 'kharji_ilam_muwaqqiin_jawziyyah', 1, 'فَصْلٌ فِي تَغَيُّرِ الفَتْوَى بِحَسَبِ تَغَيُّرِ الأَزْمِنَةِ وَالأَمْكِنَةِ وَالأَحْوَالِ وَالنِّيَّاتِ', 'باب 2: فتویٰ کی تبدیلی — زمان، مکان، حالات اور عادات کے بدلنے سے احکام کی تطبیق میں تغیر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jawziyyah_ilam_seg_2_1', 'jawziyyah_ilam_ch2_taghayyur_fatwa', 'kharji_ilam_muwaqqiin_jawziyyah', 0, '«فَصْلٌ عَظِيمُ النَّفْعِ جِدّاً: وَقَعَ فِيهِ الغَلَطُ مِنْ كَثِيرٍ مِنَ المُفْتِينَ لِجَهْلِهِمْ بِهِ؛ فَإِنَّ الشَّرِيعَةَ مَبْنَاهَا وَأَسَاسُهَا عَلَى الحِكَمِ وَمَصَالِحِ العِبَادِ فِي المَعَاشِ وَالمَعَادِ، وَهِيَ عَدْلٌ كُلُّهَا، وَرَحْمَةٌ كُلُّهَا، وَمَصَالِحُ كُلُّهَا، وَحِكْمَةٌ كُلُّهَا؛ فَكُلُّ مَسْأَلَةٍ خَرَجَتْ عَنِ العَدْلِ إِلَى الجَوْرِ، وَعَنِ الرَّحْمَةِ إِلَى ضِدِّهَا، وَعَنِ المَصْلَحَةِ إِلَى المَفْسَدَةِ، وَعَنِ الحِكْمَةِ إِلَى العَبَثِ؛ فَلَيْسَتْ مِنَ الشَّرِيعَةِ وَإِنْ أُدْخِلَتْ فِيهَا بِالتَّأْوِيلِ. وَالفَتْوَى تَتَغَيَّرُ بِتَغَيُّرِ العُرْفِ وَالحَالِ صِيَانَةً لِمَقَاصِدِ الشَّرْعِ».', 'ابن قیم رحمہ اللہ فرماتے ہیں: ''یہ ایک انتہائی عظیم اور مفید باب ہے جس سے ناواقفیت کی وجہ سے بہت سے مفتیانِ کرام سنگین غلطیوں کا شکار ہوئے؛ جان لو کہ شریعت کی بنیاد اور عمارت دنیا اور آخرت میں حکمتوں اور بندوں کے مصالح پر رکھی گئی ہے، وہ پوری کی پوری سراپا عدل ہے، سراپا رحمت ہے، سراپا مصلحت ہے، اور سراپا حکمت ہے؛ پس ہر وہ مسئلہ جو عدل سے نکل کر ظلم میں داخل ہو جائے، اور رحمت سے نکل کر سختی و قساوت بن جائے، اور فائدے سے نکل کر فساد و نقصان بن جائے، اور حکمت سے نکل کر بے ہودگی بن جائے؛ تو وہ ہرگز شریعت کا حصہ نہیں ہے اگرچہ اسے کسی بھی تاویل کے زور پر شریعت میں داخل کرنے کی کوشش کی گئی ہو! اور شریعت کے مقاصد کو بچانے کے لیے عرف اور حالات کے بدلنے سے فتوے کی تطبیق بدل جاتی ہے''۔', 'یہ عبارت اسلامی قانون سازی کا سب سے درخشندہ باب ہے جس نے یہ واضح کر دیا کہ شریعت جامد لکیر کی فقیر نہیں بلکہ اس کا مقصد ہر زمانے میں عدل اور رحمت کو نافذ کرنا ہے۔', '[{"word":"عَدْلٌ","role":"خبر المبتدأ هي مرفوع","sign":"ضمة","detail":"كلها توكيد معنوي"},{"word":"فَلَيْسَتْ","role":"فعل ماض ناقص والتاء للتأنيث","sign":"مبني","detail":"واسمها مستتر ومن الشريعة خبرها"}]', '["إعلام الموقعين عن رب العالمين، 3/ 11-18."]', '{"en":"Ibn al-Qayyim''s immortal manifesto: The Shariah is founded upon wisdom and human welfare—it is entirely justice, mercy, benefit, and wisdom. Any ruling that departs from justice to oppression, from mercy to harshness, or from benefit to harm is not part of the Shariah, no matter what legal stratagem is invoked.","ar":"دستور الشريعة الخالد في ارتباط الفتوى بالعدل والرحمة ومراعاة تغير الأعراف والأزمان."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_badaa_sanaii_kasani', 'بَدَائِعُ الصَّنَائِعِ فِي تَرْتِيبِ الشَّرَائِعِ', 'الإِمَامُ عَلَاءُ الدِّينِ أَبُو بَكْرِ بْنُ مَسْعُودٍ الكَاسَانِيُّ الحَنَفِيُّ (ت: 587ھ)', 'kharji_kitab', 'fiqh', 'فقہِ حنفی کی منطقی ترتیب و استدلال', 'کتبِ مطالعہ و مراجعِ فقہ و فتاویٰ', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'الملقب بـ ''ملك العلماء''۔ فقہِ حنفی کی تاریخ کی سب سے مربوط، منطقی اور حسنِ ترتیب والی کتاب۔ ہر مسئلے کی شرط، رکن، سبب، اور حکم الگ الگ درج ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kasani_ch1_salah', 'kharji_badaa_sanaii_kasani', 0, 'كِتَابُ الصَّلَاةِ: شَرَائِطُ فَرْضِيَّةِ الصَّلَاةِ وَشَرَائِطُ صِحَّتِهَا وَالتَّرْتِيبُ الهَنْدَسِيُّ لِلْمَذْهَبِ', 'باب 1: کتاب الصلاۃ — شرائطِ فرضیت اور شرائطِ صحت کی ریاضیاتی اور ہندسی ترتیب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kasani_seg_1_1', 'kasani_ch1_salah', 'kharji_badaa_sanaii_kasani', 0, 'قَالَ الإِمَامُ عَلَاءُ الدِّينِ الكَاسَانِيُّ الحَنَفِيُّ: «الكَلَامُ فِي الصَّلَاةِ يَنْتَظِمُ فِي فُصُولٍ مُحْكَمَةٍ: فِي شَرَائِطِ الفَرْضِيَّةِ، وَشَرَائِطِ الجَوَازِ، وَأَرْكَانِهَا، وَوَاجِبَاتِهَا، وَسُنَنِهَا، وَمُفْسِدَاتِهَا. فَأَمَّا شَرَائِطُ الفَرْضِيَّةِ فَثَلَاثَةٌ: الإِسْلَامُ، وَالبُلُوغُ، وَالعَقْلُ؛ فَلَا تَجِبُ عَلَى كَافِرٍ وُجُوبَ مُطَالَبَةٍ فِي الدُّنْيَا، وَلَا عَلَى صَبِيٍّ وَلَا مَجْنُونٍ لِعَدَمِ التَّكْلِيفِ. وَأَمَّا شَرَائِطُ الصِّحَّةِ فَسِتَّةٌ: طَهَارَةُ البَدَنِ، وَطَهَارَةُ الثَّوْبِ، وَطَهَارَةُ المَكَانِ، وَسَتْرُ العَوْرَةِ، وَاسْتِقْبَالُ القِبْلَةِ، وَمَعْرِفَةُ دُخُولِ الوَقْتِ مَعَ النِّيَّةِ».', 'امام علاء الدین ابو بکر بن مسعود الکاسانی حنفی (الملقب بملک العلماء) فرماتے ہیں: ''نماز پر ہماری گفتگو محکم اور مربوط فصول پر مشتمل ہے: شرائطِ فرضیت، شرائطِ جواز و صحت، ارکان، واجبات، سنن، اور مفسدات۔ پس شرائطِ فرضیت تین ہیں: اسلام، بلوغت، اور عقل؛ لہٰذا دنیا میں کافر سے نماز کا مطالبہ نہیں کیا جائے گا، اور بچے اور مجنون پر تکلیف نہ ہونے کے سبب فرض نہیں۔ اور شرائطِ صحت چھ ہیں: بدن کی پاکی، کپڑوں کی پاکی، جگہ کی پاکی، ستر عورت، استقبالِ قبلہ، اور وقت کے داخل ہونے کا علم مع نیت''۔', 'کتاب ''بدائع الصنائع فی ترتیب الشرائع'' کو فقہ حنفی کی سب سے منظم اور خوبصورت کتاب مانا جاتا ہے۔ اس کی ترتیب اتنی علمی اور ریاضیاتی ہے کہ فقہی فروع خودبخود منطقی زنجیر میں پروئے نظر آتے ہیں۔', '[{"word":"الكَلَامُ","role":"مبتدأ مرفوع","sign":"ضمة ظاهرة","detail":"ينتظم جملة فعلية خبر"},{"word":"طَهَارَةُ","role":"بدل أو خبر لمبتدأ محذوف","sign":"ضمة","detail":"تفصيل لستة"}]', '["بدائع الصنائع في ترتيب الشرائع للكاساني، 1/ 85-92، دار الكتب العلمية."]', '{"en":"Imam Al-Kasani structures prayer rulings with unmatched mathematical clarity: Distinguishing conditions of obligation (Islam, puberty, sanity) from conditions of validity (threefold purity, covering Awrah, facing Qiblah, time awareness, and intention).","ar":"الترتيب المنطقي الهندسي البديع لفقه العبادات في المذهب الحنفي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kasani_ch2_nikah', 'kharji_badaa_sanaii_kasani', 1, 'كِتَابُ النِّكَاحِ: أَرْكَانُهُ وَشَرَائِطُ انْعِقَادِهِ وَحَقُّ الكَفَاءَةِ', 'باب 2: کتاب النکاح — ارکان، شرائطِ انعقاد اور کفاءت (برابری) کا شرعی معیار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kasani_seg_2_1', 'kasani_ch2_nikah', 'kharji_badaa_sanaii_kasani', 0, '«النِّكَاحُ عَقْدٌ وُضِعَ لِتَمْلِيكِ مُتْعَةِ التَّقْبِيلِ وَالمُبَاشَرَةِ عَلَى وَجْهِ الحِلِّ، وَشُرِعَ لِمَصَالِحَ عَظِيمَةٍ: مِنْهَا صِيَانَةُ النَّفْسِ عَنِ الزِّنَا، وَتَحْصِيلُ الوَلَدِ وَبَقَاءُ النَّوْعِ الإِنْسَانِيِّ. وَرُكْنُهُ عِنْدَ أَبِي حَنِيفَةَ وَأَصْحَابِهِ: الإِيجَابُ وَالقَبُولُ الدَّالَّانِ عَلَى التَّرَاضِي. وَشَرْطُ انْعِقَادِهِ: حُضُورُ شَاهِدَيْنِ حُرَّيْنِ عَاقِلَيْنِ بَالِغَيْنِ مُسْلِمَيْنِ؛ لِقَوْلِهِ ﷺ: «لَا نِكَاحَ إِلَّا بِوَلِيٍّ وَشَاهِدَيْ عَدْلٍ». وَالكَفَاءَةُ مُعْتَبَرَةٌ فِي النِّكَاحِ لِدَفْعِ العَارِ فِي النَّسَبِ وَالدِّينِ وَالمَالِ».', 'کاسانی رحمہ اللہ فرماتے ہیں: ''نکاح وہ شرعی عقد ہے جو پاکیزہ ازدواجی تعلق کو حلال کرنے کے لیے وضع کیا گیا ہے، اور اس کی مشروعیت عظیم مصالح پر مبنی ہے: جن میں نفس کو زنا سے بچانا، نیک اولاد کا حصول، اور انسانی نوع کی بقا شامل ہیں۔ اور امام ابو حنیفہ اور ان کے اصحاب کے نزدیک نکاح کا اصل رکن ایجاب اور قبول ہیں جو دونوں فریقوں کی باہمی رضامندی پر دلالت کرتے ہوں۔ اور نکاح کے انعقاد کی شرط دو آزاد، عاقل، بالغ مسلمان گواہوں کی موجودگی ہے؛ کیونکہ نبی ﷺ کا فرمان ہے: ''نکاح نہیں ہوتا مگر ولی اور دو عادل گواہوں کے ساتھ''۔ اور خاندان پر عار اور ذلت کو دور کرنے کے لیے نسب، دین اور مال میں کفاءت (برابری) کا لحاظ رکھا گیا ہے''۔', 'نکاح صرف ایک قانونی معاہدہ نہیں بلکہ نسلِ انسانی اور اخلاقیات کے تحفظ کا مقدس قلعہ ہے۔ کاسانی نے اس کے تمام ارکان اور گواہوں کی اہمیت کو واضح کیا۔', '[{"word":"عَقْدٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"النكاح مبتدأ وعقد خبره"},{"word":"شَاهِدَيْنِ","role":"مضاف إليه مجرور","sign":"ياء","detail":"مثنى مذكر سالم"}]', '["بدائع الصنائع للكاساني، 2/ 228-235."]', '{"en":"The Pillars and Validity of Marriage: Mutual consent manifested through offer and acceptance, presence of two adult sane Muslim witnesses, and the preservation of lineage and social equilibrium via Kafa''ah (suitability).","ar":"أحكام عقد النكاح وشروط صحته ومقاصده الأسرية والاجتماعية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_usul_karkhi', 'أُصُولُ الكَرْخِيِّ مَعَ أُصُولِ البَزْدَوِيِّ', 'الإِمَامُ أَبُو الحَسَنِ عُبَيْدُ اللَّهِ بْنُ الحُسَيْنِ الكَرْخِيُّ الحَنَفِيُّ (ت: 340ھ)', 'kharji_kitab', 'usul', 'اصولِ فقہِ حنفی کے قدیم ترین کلیات', 'کتبِ مطالعہ و تخصص فی الاصول', NULL, NULL, 'from-emerald-950 via-teal-950 to-stone-900', NULL, 'احناف کے قدیم ترین اصولی قواعد۔ امام ابو حنیفہ، ابو یوسف اور محمد رحمہم اللہ کے ہزاروں مسائل کس اصل کلی پر مبنی ہیں اس کا خلاصہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('karkhi_ch1_usul', 'kharji_usul_karkhi', 0, 'الأَصْلُ الأَوَّلُ عِنْدَ الكَرْخِيِّ: قَوَاعِدُ تَخْرِيجِ الفُرُوعِ عَلَى الأُصُولِ فِي المَذْهَبِ', 'قاعدہ 1: امام کرخی کا اساسی اصول — تخریجِ فروع اور حنفی قواعد کی پختگی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('karkhi_seg_1_1', 'karkhi_ch1_usul', 'kharji_usul_karkhi', 0, 'قَالَ الإِمَامُ أَبُو الحَسَنِ عُبَيْدُ اللَّهِ بْنُ الحُسَيْنِ الكَرْخِيُّ الحَنَفِيُّ: «الأَصْلُ عِنْدَنَا: أَنَّ كُلَّ آيَةٍ أَوْ خَبَرٍ يُخَالِفُ قَوْلَ أَصْحَابِنَا، فَإِنَّهُ يُحْمَلُ عَلَى النَّسْخِ، أَوْ عَلَى التَّرْجِيحِ، أَوْ يُؤَوَّلُ بِمَا يُوَافِقُ قَوَاعِدَ المَذْهَبِ. وَمَعْنَى هَذَا الأَصْلِ: أَنَّ أَئِمَّتَنَا أَبَا حَنِيفَةَ وَأَبَا يُوسُفَ وَمُحَمَّداً لَمْ يُخَالِفُوا النُّصُوصَ عَنْ جَهْلٍ أَوْ عَمْدٍ، بَلْ لِوُجُودِ مُعَارِضٍ أَقْوَى عِنْدَهُمْ مِنَ القُرْآنِ أَوْ السُّنَّةِ المُتَوَاتِرَةِ، فَالوَاجِبُ عَلَى الفَقِيهِ البَحْثُ عَنْ وَجْهِ اسْتِدْلَالِهِمْ».', 'امام ابو الحسن عبید اللہ بن حسین الکرخی حنفی رحمہ اللہ فرماتے ہیں: ''ہمارے نزدیک اصول یہ ہے: ہر وہ آیت یا حدیث جو بظاہر ہمارے ائمہ (ابو حنیفہ، ابو یوسف، محمد) کے فتوے کے خلاف نظر آئے، تو وہ منسوخ ہونے پر محمول ہوگی، یا ترجیح کے اصول پر، یا اس کی ایسی تاویل کی جائے گی جو شریعت کے دیگر نصوص سے موافق ہو۔ اور اس اصول کی حقیقت یہ ہے: ہمارے ائمہ نے نصوص کی مخالفت نہ تو ناواقفیت کی وجہ سے کی اور نہ جان بوجھ کر، بلکہ ان کے سامنے اس سے زیادہ مضبوط قرآنی اصول یا متواتر سنت موجود تھی، لہٰذا فقیہ پر فرض ہے کہ وہ ان کی دلیل اور استنباط کی گہرائی کو تلاش کرے''۔', 'اصول الکرخی حنفی مذہب کے اولین تقعیدی اصولوں میں سے ہے۔ اس قول کا مقصد ائمہ کے فقہی استنباط پر اعتماد پیدا کرنا ہے کہ وہ کسی حدیث کو رد نہیں کرتے بلکہ عمومی قرآنی قواعد کو فوقیت دیتے ہیں۔', '[{"word":"الأَصْلُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"أن كل آية مصدر مؤول خبر"},{"word":"يُحْمَلُ","role":"فعل مضارع مبني للمجهول","sign":"ضمة","detail":"ونائب الفاعل مستتر يعود على ما خالف"}]', '["أصول الكرخي، القاعدة رقم (1)، ص 11-15، مطبوع مع تأسيس النظر."]', '{"en":"Imam Al-Karkhi''s famous maxim on legal methodology: Clarifying that when a solitary narration seemingly contradicts established Hanafi rulings, it is reconciled through abrogation, textual harmonization, or preference for broader Quranic universal principles.","ar":"تأصيل منهجية أئمة الحنفية في التوفيق بين الآحاد والقواعد الكلية للتشريع."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('karkhi_ch2_bazdawi', 'kharji_usul_karkhi', 1, 'أَصْلُ دَلَالَاتِ الأَلْفَاظِ عِنْدَ الإِمَامِ البَزْدَوِيِّ: الخَاصُّ وَالعَامُّ', 'قاعدہ 2: امام بزدوی کا اصول — خاص اور عام کے احکام اور قطعی دلالت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('karkhi_seg_2_1', 'karkhi_ch2_bazdawi', 'kharji_usul_karkhi', 0, '«قَالَ فَخْرُ الإِسْلَامِ البَزْدَوِيُّ: الخَاصُّ كُلُّ لَفْظٍ وُضِعَ لِمَعْنًى مَعْلُومٍ عَلَى الِانْفِرَادِ؛ وَحُكْمُهُ أَنَّهُ يُوجِبُ العِلْمَ وَالعَمَلَ قَطْعاً بِلَا شُبْهَةٍ، وَلَا يَحْتَمِلُ البَيَانَ. أَمَّا العَامُّ فَهُوَ اللَّفْظُ المُسْتَغْرِقُ لِجَمِيعِ مَا يَصْلُحُ لَهُ بِحَسَبِ وَضْعٍ وَاحِدٍ؛ وَحُكْمُهُ عِنْدَنَا: أَنَّهُ قَطْعِيُّ الدَّلَالَةِ عَلَى أَفْرَادِهِ كَالخَاصِّ سَوَاءً، فَلَا يَجُوزُ تَخْصِيصُهُ بِخَبَرِ الوَاحِدِ الظَّنِّيِّ؛ لِأَنَّ الظَّنِّيَّ لَا يَقْوَى عَلَى زِيَادَةِ قَيْدٍ عَلَى النَّصِّ القَطْعِيِّ».', 'فخر الاسلام امام علی بن محمد البزدوی حنفی فرماتے ہیں: ''لفظِ خاص وہ لفظ ہے جو اکیلے معلوم معنی کے لیے وضع کیا گیا ہو؛ اور اس کا شرعی حکم یہ ہے کہ وہ بغیر کسی شک و شبہ کے قطعی علم اور عمل کو واجب کرتا ہے، اور اس میں کسی اور وضاحت کی گنجائش نہیں ہوتی۔ جبکہ لفظِ عام وہ لفظ ہے جو اپنے تمام افراد کو ایک ہی وضع کے تحت گھیر لے؛ اور ہمارے نزدیک اس کا حکم یہ ہے: وہ اپنے تمام افراد پر اسی طرح قطعی الدلالۃ ہوتا ہے جس طرح لفظِ خاص قطعی ہوتا ہے، لہٰذا خبرِ واحد (جو ظنی ہے) کے ذریعے قرآنی عام کی تخصیص کرنا جائز نہیں؛ کیونکہ ظنی دلیل قطعی قرآنی نص پر قید بڑھانے کی طاقت نہیں رکھتی''۔', 'اصول البزدوی حنفی اصولِ فقہ کا سب سے بڑا اور بنیادی متن ہے۔ یہ قاعدہ حنفی اور شافعی اصول میں تخصیصِ عام کے معاملے میں سب سے بڑا اختلافی نقطہ ہے۔', '[{"word":"الخَاصُّ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"كل لفظ خبر المبتدأ"},{"word":"قَطْعِيُّ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"وهو مضاف والدلالة مضاف إليه"}]', '["أصول البزدوي (كنز الوصول إلى معرفة الأصول)، ص 18-26."]', '{"en":"Imam Al-Bazdawi''s classical distinction between Khas (specific) and ''Amm (general): In Hanafi Usul, general expressions in the Quran carry definitive (Qat''i) legal certainty, which cannot be restricted by solitary Hadiths (Ahad) without a mediating corroboration.","ar":"تحرير أصول دلالات الألفاظ عند الحنفية وقطعية دلالة العام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_mabsut_sarakhsi', 'المَبْسُوطُ لِشَمْسِ الأَئِمَّةِ السَّرَخْسِيِّ', 'الإِمَامُ شَمْسُ الأَئِمَّةِ مُحَمَّدُ بْنُ أَحْمَدَ السَّرَخْسِيُّ الحَنَفِيُّ (ت: 483ھ)', 'kharji_kitab', 'fiqh', 'انسائیکلوپیڈیا فقہِ حنفی و دلائلِ مذاہب', 'کتبِ مطالعہ و مراجعِ عالیہ (30 جلدیں)', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'فقہِ حنفی کی سب سے عظیم اور ضخیم ترین کتاب (30 جلدیں)۔ شمس الائمہ نے اسے کنوئیں کے قید خانے میں حافظے کے زور پر اپنے شاگردوں کو املا کرایا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sarakhsi_ch1_siyar', 'kharji_mabsut_sarakhsi', 0, 'كِتَابُ السِّيَرِ: أَحْكَامُ الجِهَادِ وَالمُعَاهَدَاتِ وَالأَمَانِ وَالقَانُونِ الدَّوْلِيِّ', 'باب 1: کتاب السیر — جہاد، بین الاقوامی معاہدات اور امان کے قوانین');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sarakhsi_seg_1_1', 'sarakhsi_ch1_siyar', 'kharji_mabsut_sarakhsi', 0, 'قَالَ شَمْسُ الأَئِمَّةِ السَّرَخْسِيُّ: «أَمْلَيْتُ هَذَا الكِتَابَ وَأَنَا فِي حَبْسِ أُوزْجَنْدَ صَابِراً مُحْتَسِباً. اعْلَمْ أَنَّ السِّيَرَ جَمْعُ سِيرَةٍ، وَهِيَ فِي اصْطِلَاحِ الفُقَهَاءِ: بَيَانُ مُعَامَلَةِ المُسْلِمِينَ مَعَ غَيْرِهِمْ فِي الحَرْبِ وَالسِّلْمِ وَالمُعَاهَدَاتِ. وَالأَصْلُ فِيهِ أَنَّ الإِسْلَامَ لَا يُجِيزُ الغَدْرَ وَلَا المَثْلَةَ، وَلَا قَتْلَ النِّسَاءِ وَالصِّبْيَانِ وَالرُّهْبَانِ الَّذِينَ لَا يُقَاتِلُونَ؛ لِأَنَّ القِتَالَ فِي الإِسْلَامِ إِنَّمَا شُرِعَ لِدَفْعِ العُدْوَانِ، لَا لِإِفْنَاءِ البَشَرِ، وَالأَمَانُ إِذَا أَعْطَاهُ أَدْنَى مُسْلِمٍ جَازَ عَلَى جَمِيعِهِمْ؛ لِقَوْلِهِ ﷺ: «ذِمَّةُ المُسْلِمِينَ وَاحِدَةٌ يَسْعَى بِهَا أَدْنَاهُمْ».', 'شمس الائمہ امام محمد بن احمد السرخسی رحمہ اللہ فرماتے ہیں: ''میں نے یہ عظیم کتاب اوزجند کے کنویں کی قیدِ تنہائی میں بغیر کسی کتاب کو دیکھے محض اپنے حافظے سے املا کرائی۔ جان لو کہ ''سیر'' سیرت کی جمع ہے، اور فقہاء کی اصطلاح میں اس سے مراد مسلمانوں کے غیر مسلموں کے ساتھ جنگ، امن اور بین الاقوامی معاہدات کے احکام ہیں۔ اور اس میں بنیادی اصول یہ ہے کہ اسلام دھوکہ دہی، مقتولین کے اعضاء کاٹنے (مثلۂ)، اور ان عورتوں، بچوں اور راہبوں کو قتل کرنے کی قطعی اجازت نہیں دیتا جو جنگ میں عملاً شریک نہ ہوں؛ کیونکہ اسلام میں جنگ محض سرکشی اور ظلم کو مٹانے کے لیے مشروع کی گئی ہے، انسانوں کی نسل کشی کے لیے نہیں؛ اور جب ادنیٰ سا مسلمان بھی کسی دشمن کو امان دے دے تو وہ تمام مسلمانوں پر لازم ہو جاتی ہے؛ کیونکہ نبی ﷺ کا فرمان ہے: ''مسلمانوں کا عہد اور پناہ ایک ہی ہے جس کی ذمہ داری ان کا ادنیٰ فرد بھی اٹھا سکتا ہے''۔', 'المبسوط للسرخسی فقہ حنفی کی سب سے ضخیم اور عظیم الشان کتاب (30 جلدیں) ہے جسے شمس الائمہ نے قید خانے کے اندھیرے کنویں میں بیٹھ کر اپنے شاگردوں کو زبانی لکھوایا۔ یہ بین الاقوامی قانون کا اولین چارٹر ہے۔', '[{"word":"السِّيَرَ","role":"اسم أنّ منصوب","sign":"فتحة","detail":"جمع سيرة خبر أنّ مرفوع"},{"word":"وَاحِدَةٌ","role":"خبر المبتدأ ذمة مرفوع","sign":"ضمة","detail":"يبين وحدة الأمان"}]', '["المبسوط لشمس الأئمة السرخسي، كتاب السير، 10/ 2-8."]', '{"en":"Imam Al-Sarakhsi dictated this monumental encyclopedia from the depths of a prison well in Uzgend from memory alone: He articulates Islamic International Humanitarian Law—categorically forbidding treachery, mutilation of corpses, and the targeting of non-combatant women, children, and monks, affirming that a treaty of protection granted by even the humblest Muslim binds the entire state.","ar":"تأسيس القانون الدولي الإنساني وقواعد الاشتباك العادل في الفقه الحنفي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sarakhsi_ch2_dawa', 'kharji_mabsut_sarakhsi', 1, 'كِتَابُ الدَّعْوَى وَالقَضَاءِ: مَنْ كَانَ القَوْلُ قَوْلَهُ مَعَ يَمِينِهِ', 'باب 2: کتاب الدعویٰ و القضاء — عدالتی نظام میں مدعی اور مدعا علیہ کے تعین کا معیار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sarakhsi_seg_2_1', 'sarakhsi_ch2_dawa', 'kharji_mabsut_sarakhsi', 0, '«أَصْلُ القَضَاءِ فِي الشَّرِيعَةِ قَوْلُهُ ﷺ: «البَيِّنَةُ عَلَى المُدَّعِي، وَاليَمِينُ عَلَى مَنْ أَنْكَرَ». وَالفَرْقُ بَيْنَ المُدَّعِي وَالمُدَّعَى عَلَيْهِ: أَنَّ المُدَّعِيَ مَنْ إِذَا سَكَتَ تُرِكَ وَسُكُوتُهُ، لِأَنَّهُ يَدَّعِي أَمْراً خَفِيّاً خِلَافَ الظَّاهِرِ؛ فَلِذَلِكَ كُلِّفَ الحُجَّةَ وَالبَيِّنَةَ لِيُظْهِرَ مَا خَفِيَ. أَمَّا المُدَّعَى عَلَيْهِ فَهُوَ مَنْ إِذَا سَكَتَ لَمْ يُتْرَكْ بَلْ يُطَالَبُ بِالجَوَابِ، لِأَنَّهُ يَتَمَسَّكُ بِالأَصْلِ وَالظَّاهِرِ، وَالأَصْلُ بَرَاءَةُ الذِّمَّةِ؛ فَكَفَاهُ اليَمِينُ لِدَفْعِ الدَّعْوَى عَنْ نَفْسِهِ».', 'شمس الائمہ فرماتے ہیں: ''شریعت میں عدالتی نظام اور فیصلے کی اصل بنیاد نبی کریم ﷺ کا یہ فرمان ہے: ''گواہی پیش کرنا مدعی کے ذمے ہے، اور قسم اس پر ہے جو انکار کرے''۔ اور مدعی اور مدعا علیہ کے درمیان دقیق فرق یہ ہے: مدعی وہ شخص ہے کہ اگر وہ اپنا دعویٰ چھوڑ کر خاموش ہو جائے تو عدالت اسے چھوڑ دیتی ہے اور اس پر کوئی زبردستی نہیں ہوتی، کیونکہ وہ ظاہر کے خلاف ایک پوشیدہ حق کا دعویٰ کر رہا ہوتا ہے؛ اسی لیے اس پر گواہ اور ثبوت لانے کا بوجھ ڈالا گیا تاکہ وہ اپنے پوشیدہ دعوے کو ثابت کرے۔ جبکہ مدعا علیہ وہ ہے کہ اگر وہ خاموش رہے تو عدالت اسے نہیں چھوڑتی بلکہ اس سے جواب کا مطالبہ کرتی ہے، کیونکہ وہ اصل حالت اور ظاہر کا سہارا لے رہا ہوتا ہے، اور اصل یہ ہے کہ انسان کا ذمہ ہر قسم کے دعوے سے بری ہے؛ لہٰذا اپنے دفاع کے لیے اس کی حلفیہ قسم ہی کافی ہوتی ہے''۔', 'سرخسی کی یہ قانونی تعریف کہ ''مدعی وہ ہے جو خاموش ہو جائے تو چھوڑ دیا جائے'' پوری مسلم عدالتی تاریخ میں ججوں اور قاضیوں کا سب سے سنہری فارمولا رہی ہے۔', '[{"word":"البَيِّنَةُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"على المدعي شبه جملة خبر"},{"word":"بَرَاءَةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"الأصل مبتدأ وبراءة خبره"}]', '["المبسوط للسرخسي، كتاب الدعوى، 17/ 28-35."]', '{"en":"Imam Al-Sarakhsi formulates the evidentiary procedural law in Islamic courts: ''Evidence is upon the claimant, and the oath is upon the denier.'' A claimant asserts a hidden departure from the status quo and therefore bears the burden of proof, whereas the defendant is fortified by the presumption of original innocence.","ar":"قواعد المرافعات والإثبات القضائي وتحرير الفروق الدقيقة بين الخصوم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_wajiiz_zaydan', 'الوَجِيزُ فِي أُصُولِ الفِقْهِ', 'الدُّكْتُورُ الفَقِيهُ عَبْدُ الكَرِيمِ زَيْدَانَ العِرَاقِيُّ (ت: 1435ھ)', 'kharji_kitab', 'usul', 'اصولِ فقہ کی جدید تسہیل و تفہیم', 'کتبِ مطالعہ و تسہیلِ نصاب (جامعات و مدارس)', NULL, NULL, 'from-teal-950 via-emerald-950 to-stone-900', NULL, 'اصولِ فقہ کو عصرِ حاضر کے طلبہ کے لیے انتہائی آسان، مربوط اور جدید عناوین میں پیش کرنے والی مقبول ترین کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('zaydan_ch1_adillah', 'kharji_wajiiz_zaydan', 0, 'البَابُ الأَوَّلُ: الأَدِلَّةُ الشَّرْعِيَّةُ المُتَّفَقُ عَلَيْهَا وَالمُخْتَلَفُ فِيهَا', 'باب 1: ادلۂ شرعیہ متفقہ (قرآن، سنت، اجماع، قیاس) اور مختلف فیہ (استحسان، مصالحِ مرسلہ)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('zaydan_seg_1_1', 'zaydan_ch1_adillah', 'kharji_wajiiz_zaydan', 0, 'قَالَ الدُّكْتُورُ الفَقِيهُ عَبْدُ الكَرِيمِ زَيْدَانَ: «أَدِلَّةُ الأَحْكَامِ الشَّرْعِيَّةِ تَنْقَسِمُ إِلَى نَوْعَيْنِ: أَدِلَّةٍ مُتَّفَقٍ عَلَيْهَا بَيْنَ جُمْهُورِ الأُمَّةِ، وَهِيَ أَرْبَعَةٌ: القُرْآنُ الكَرِيمُ، وَالسُّنَّةُ النَّبَوِيَّةُ، وَالإِجْمَاعُ، وَالقِيَاسُ. وَأَدِلَّةٍ مُخْتَلَفٍ فِيهَا، وَأَهَمُّهَا: الِاسْتِحْسَانُ، وَالمَصَالِحُ المُرْسَلَةُ، وَالعُرْفُ، وَسَدُّ الذَّرَائِعِ، وَاسْتِصْحَابُ الحَالِ، وَشَرْعُ مَنْ قَبْلَنَا، وَمَذْهَبُ الصَّحَابِيِّ. وَهَذِهِ الأَدِلَّةُ التَّبَعِيَّةُ هِيَ مَعِينُ الفِقْهِ فِي مُعَالَجَةِ القَضَايَا المُعَاصِرَةِ الَّتِي لَا نَصَّ فِيهَا بِعَيْنِهَا».', 'ڈاکٹر عبد الکریم زیدان عراقی رحمہ اللہ فرماتے ہیں: ''شرعی احکام کے مآخذ اور دلائل دو قسموں میں تقسیم ہیں: ایک وہ متفقہ دلائل جن پر جمہورِ امت کا اتفاق ہے، اور وہ چار ہیں: قرآن کریم، سنتِ نبویہ، اجماعِ امت، اور قیاسِ شرعی۔ اور دوسرے وہ مختلف فیہ دلائل جن کی حجیت و وسعت میں فقہی مذاہب کا اختلاف رہا ہے، جن میں سب سے اہم ہیں: استحسان، مصالحِ مرسلہ، عرف و رواج، سدِ ذرائع (برائی کے راستوں کو روکنا)، استصحاب، شرعِ من قبلنا، اور قولِ صحابی۔ اور یہ ضمنی مآخذ ہی دراصل وہ چشمہ ہیں جس کے ذریعے فقہ اسلامی جدید دور کے ان مسائل کو حل کرتی ہے جن پر کوئی مخصوص صریح نص موجود نہیں ہے''۔', 'کتاب ''الوجيز في أصول الفقه'' عالم اسلام کی جامعات اور مدارس میں اصولِ فقہ کی سب سے زیادہ پڑھی جانے والی نصابی کتاب ہے کیونکہ اس کی زبان نہایت شگفتہ، سلیس اور جدید قانونی انداز کی حامل ہے۔', '[{"word":"أَدِلَّةُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"تنقسم جملة فعلية خبر"},{"word":"أَرْبَعَةٌ","role":"خبر لمبتدأ محذوف","sign":"ضمة","detail":"تقديره: هي أربعة"}]', '["الوجيز في أصول الفقه، د. عبد الكريم زيدان، ص 150-165، مؤسسة الرسالة."]', '{"en":"Dr. Abd al-Karim Zaydan outlines the sources of Islamic legislation: The four agreed-upon primary sources (Quran, Sunnah, Ijma'', Qiyas) and the supplementary secondary sources (Istihsan, Maslahah Mursalah, ''Urf, Sadd al-Dhara''i, Istishab) which empower contemporary Ijtihad.","ar":"التأصيل المنهجي المعاصر لمصادر التشريع الأصيلة والتبعية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('zaydan_ch2_ahliyyah', 'kharji_wajiiz_zaydan', 1, 'البَابُ الثَّانِي: أَهْلِيَّةُ الوُجُوبِ وَأَهْلِيَّةُ الأَدَاءِ وَعَوَارِضُ الأَهْلِيَّةِ', 'باب 2: اہلیتِ وجوب اور اہلیتِ ادا — قانونی ذمہ داری اور اس کے عوارض (جنون، صغر، نسیان)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('zaydan_seg_2_1', 'zaydan_ch2_ahliyyah', 'kharji_wajiiz_zaydan', 0, '«الأَهْلِيَّةُ هِيَ: صَلَاحِيَّةُ الإِنْسَانِ لِوُجُوبِ الحُقُوقِ المَشْرُوعَةِ لَهُ وَعَلَيْهِ، وَلِصُدُورِ التَّصَرُّفَاتِ مِنْهُ. وَهِيَ قِسْمَانِ: أَهْلِيَّةُ وُجُوبٍ: وَمَنَاطُهَا ثُبُوتُ الحَيَاةِ، فَتَثْبُتُ لِلْجَنِينِ فِي بَطْنِ أُمِّهِ ثُبُوتاً نَاقِصاً (فَيَرِثُ وَيُوصَى لَهُ)، وَتَثْبُتُ كَامِلَةً بِمُجَرَّدِ الوِلَادَةِ. وَأَهْلِيَّةُ أَدَاءٍ: وَمَنَاطُهَا العَقْلُ وَالتَّمْيِيزُ، فَلَا تَكْمُلُ إِلَّا بِالبُلُوغِ وَالرُّشْدِ. ثُمَّ تَعْتَرِيهَا عَوَارِضُ سَمَاوِيَّةٌ كَالجُنُونِ وَالعَتَهِ وَالنِّسْيَانِ، أَوْ كَسْبِيَّةٌ كَالسَّكَرِ وَالسَّفَهِ وَالإِكْرَاهِ».', 'ڈاکٹر عبد الکریم زیدان فرماتے ہیں: ''اہلیت سے مراد انسان کی وہ قانونی صلاحیت ہے جس سے وہ حقوق پانے اور فرائض ادا کرنے کا حقدار بنتا ہے، اور جس سے اس کے تصرفات قانونی حیثیت پاتے ہیں۔ اس کی دو قسمیں ہیں: اہلیتِ وجوب: اس کی بنیاد انسانی زندگی کا وجود ہے، لہٰذا ماں کے پیٹ میں موجود جنین (بچے) کے لیے بھی ناقص طور پر ثابت ہوتی ہے (چنانچہ وہ وارث بنتا ہے اور اس کے لیے وصیت کی جا سکتی ہے)، اور پیدا ہوتے ہی یہ مکمل ہو جاتی ہے۔ اور دوسری قسم اہلیتِ ادا ہے: اس کی بنیاد عقل، فہم اور تمیز ہے، پس یہ بلوغت اور فکری پختگی (رشد) ہی سے مکمل ہوتی ہے۔ پھر اس اہلیت پر بعض ایسے عوارض لاحق ہو جاتے ہیں جو اس کی قانونی ذمہ داری کو ختم یا کم کر دیتے ہیں: جن میں سے کچھ آسمانی و قدرتی ہیں جیسے پاگل پن، کم عقلی اور بھول جانا؛ اور کچھ اختیاری ہیں جیسے نشہ، فضول خرچی (سفہ) اور زبردستی کا دباؤ (اکراہ)''۔', 'یہ قانونی باب جدید سول اور کرمنل لاء کا سرچشمہ ہے۔ زیدان نے واضح کیا کہ اسلام نے پیدائش سے قبل جنین کے حقوق سے لے کر فکری بیماریوں تک ہر مرحلے کی قانونی حیثیت کا تحفظ کیا ہے۔', '[{"word":"صَلَاحِيَّةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"الأهلية مبتدأ وصلاحية خبره"},{"word":"نَاقِصاً","role":"نعت لمصدر محذوف (ثبوتاً) منصوب","sign":"فتحة","detail":"يبين نوع الثبوت"}]', '["الوجيز في أصول الفقه، ص 85-98."]', '{"en":"Legal Capacity (Ahliyyah): Ahliyyah al-Wujub (receptive capacity based on biological life, granting rights even to a fetus) and Ahliyyah al-Ada'' (active capacity based on intellectual discernment, required for contractual transactions and criminal culpability), along with impeding factors (''Awarid).","ar":"التأصيل الحقوقي الدقيق للمسؤولية المدنية والجنائية في الفقه الإسلامي."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_seerah_ibn_hisham', 'السِّيرَةُ النَّبَوِيَّةُ لِابْنِ هِشَامٍ', 'الإِمَامُ أَبُو مُحَمَّدٍ عَبْدُ المَلِكِ بْنُ هِشَامٍ المَعَافِرِيُّ (ت: 218ھ)', 'kharji_kitab', 'seerah', 'سیرتِ نبوی ﷺ کا سب سے اولین و معتمد ماخذ', 'کتبِ مطالعہ و اساسِ سیرت و مغازی', NULL, NULL, 'from-rose-950 via-stone-900 to-emerald-950', NULL, 'ابن اسحاق کی مغازی کی وہ مستند تدوین جس پر تمام مؤرخین اور سیرت نگاروں کا انحصار ہے۔ بعثت سے وفات تک کے تمام احوال کا تاریخی ریکارڈ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hisham_ch1_hirah', 'kharji_seerah_ibn_hisham', 0, 'بَدْءُ الوَحْيِ وَنُزُولُ جِبْرِيلَ فِي غَارِ حِرَاءٍ', 'باب 1: غارِ حرا میں پہلی وحی اور بعثتِ نبوی کا مبارک آغاز');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hisham_seg_1_1', 'hisham_ch1_hirah', 'kharji_seerah_ibn_hisham', 0, 'قَالَ ابْنُ إِسْحَاقَ: فَلَمَّا بَلَغَ رَسُولُ اللَّهِ ﷺ أَرْبَعِينَ سَنَةً، بَعَثَهُ اللَّهُ رَحْمَةً لِلْعَالَمِينَ... فَجَاءَهُ المَلَكُ وَهُوَ فِي غَارِ حِرَاءٍ فِي شَهْرِ رَمَضَانَ، فَقَالَ لَهُ: اقْرَأْ، قَالَ: مَا أَنَا بِقَارِئٍ، فَغَطَّهُ المَلَكُ ثَلَاثاً حَتَّى بَلَغَ مِنْهُ الجَهْدُ، ثُمَّ قَالَ: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الإِنْسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الأَكْرَمُ * الَّذِي عَلَّمَ بِالقَلَمِ * عَلَّمَ الإِنْسَانَ مَا لَمْ يَعْلَمْ﴾.', 'امام ابن اسحاق اور ابن ہشام فرماتے ہیں: جب رسول اللہ ﷺ کی عمر مبارک چالیس سال کو پہنچی تو اللہ تعالیٰ نے آپ کو تمام جہانوں کے لیے رحمت بنا کر مبعوث فرمایا... پس ماہِ رمضان میں جب آپ غارِ حرا میں گوشہ نشین تھے تو حضرت جبرائیل علیہ السلام تشریف لائے اور کہا: پڑھو! آپ ﷺ نے فرمایا: میں پڑھا ہوا نہیں ہوں۔ جبرائیل نے آپ کو تین بار سینے سے بھیینچا یہاں تک کہ مشقت پہنچی، پھر وحی کی یہ آیات سنائیں: ''پڑھیے اپنے رب کے نام کے ساتھ جس نے پیدا کیا! جس نے انسان کو خون کے لوتھڑے سے بنایا! پڑھیے اور آپ کا رب سب سے بڑا کریم ہے! جس نے قلم کے ذریعے سکھایا، انسان کو وہ سکھایا جو وہ نہ جانتا تھا!''', 'سیرتِ ابن ہشام سیرت نگاری کا اصل ام اور سرچشمہ ہے۔ غارِ حرا کا یہ واقعہ نبوت کی سچائی، قلم کی اہمیت اور علم کی عظمت کا جاوداں پیغام ہے۔', '[{"word":"رَحْمَةً","role":"مفعول لأجله منصوب","sign":"فتحة","detail":"أو حال منصوبة"}]', '["سيرة ابن هشام، باب بدء الوحي، وأصله في الصحيحين."]', '{"en":"The historical beginning of Divine Revelation in the Cave of Hira: Gabriel commanded the Prophet ﷺ to recite the opening verses of Surah Al-''Alaq, ushering in the light of Islam to mankind.","ar":"المشهد التاريخي الأعظم الذي غير مجرى التاريخ البشري بنزول الوحي الإلهي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hisham_ch2_hijrah', 'kharji_seerah_ibn_hisham', 1, 'الهِجْرَةُ النَّبَوِيَّةُ المُبَارَكَةُ وَصُحْبَةُ الصِّدِّيقِ فِي الغَارِ', 'باب 2: ہجرتِ مدینہ اور غارِ ثور میں یارِ غار سیدنا ابوبکر صدیق کی معیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hisham_seg_2_1', 'hisham_ch2_hijrah', 'kharji_seerah_ibn_hisham', 0, 'وَخَرَجَ رَسُولُ اللَّهِ ﷺ وَمَعَهُ أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ، فَدَخَلَا غَارَ ثَوْرٍ، وَوَقَفَ المُشْرِكُونَ عَلَى فَمِ الغَارِ، فَقَالَ أَبُو بَكْرٍ مَشْفِقاً: يَا رَسُولَ اللَّهِ، لَوْ أَنَّ أَحَدَهُمْ نَظَرَ إِلَى قَدَمَيْهِ لَأَبْصَرَنَا تَحْتَ قَدَمَيْهِ! فَقَالَ لَهُ النَّبِيُّ ﷺ بِثَبَاتِ اليَقِينِ: «يَا أَبَا بَكْرٍ، مَا ظَنُّكَ بِاثْنَيْنِ اللَّهُ ثَالِثُهُمَا؟ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا».', 'اور رسول اللہ ﷺ مکہ سے نکلے اور آپ کے ساتھ حضرت ابوبکر صدیق رضی اللہ عنہ تھے، دونوں حضرات غارِ ثور میں پناہ گزیں ہوئے، اور کفار کے تلاش کرنے والے عین غار کے منہ پر آ کھڑے ہوئے۔ حضرت ابوبکر نے ازراہِ محبت و فکر عرض کیا: یا رسول اللہ! اگر ان میں سے کسی نے اپنے قدموں کی طرف بھی دیکھ لیا تو وہ ہمیں اپنے قدموں کے نیچے دیکھ لے گا! تو نبی کریم ﷺ نے پہاڑ جیسے یقین کے ساتھ فرمایا: ''اے ابوبکر! ان دو کے بارے میں تمہارا کیا گمان ہے جن کا تیسرا خود اللہ تعالیٰ ہو؟ غمگین نہ ہو، بے شک اللہ ہمارے ساتھ ہے!''', 'ہجرت اسلامی تاریخ کا فیصلہ کن موڑ ہے۔ غارِ ثور میں نبی کریم ﷺ کا غیر متزلزل یقین اور سیدنا ابوبکر کا لازوال ایثار قرآنِ مجید کی سورۃ التوبہ میں ابد تک کے لیے محفوظ کر دیا گیا۔', '[{"word":"مَا","role":"اسم استفهام مبتدأ","sign":"مبني","detail":"ظنك خبره وهو مضاف والكاف مضاف إليه"}]', '["سيرة ابن هشام، متفق عليه في الصحيحين."]', '{"en":"The Prophet ﷺ and Abu Bakr in the Cave of Thawr: ''O Abu Bakr, what do you think of two when Allah is their third? Do not grieve, indeed Allah is with us.''","ar":"أعلى مقامات التوكل واليقين بالله وظهور معية الله الخاصة لنبيه وصاحبه."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_raheeq_makhtum', 'الرَّحِيقُ المَخْتُومُ فِي سِيرَةِ النَّبِيِّ المَعْصُومِ ﷺ', 'العَلَّامَةُ صَفِيُّ الرَّحْمَنِ المُبَارَكْفُورِيُّ الهِنْدِيُّ (ت: 1427ھ)', 'kharji_kitab', 'seerah', 'سیرتِ نبوی ﷺ پر عالمی ایوارڈ یافتہ شاہکار', 'کتبِ مطالعہ و حفظِ سیرت (تمام طبقات)', NULL, NULL, 'from-rose-900 via-amber-950 to-stone-900', NULL, 'رابطہ عالمِ اسلامی کے زیرِ اہتمام دنیا بھر کی سیرت نگاری کے مقابلے میں اول انعام حاصل کرنے والی شاندار، دلنشین اور مستند ترین کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('raheeq_ch1_badr', 'kharji_raheeq_makhtum', 0, 'غَزْوَةُ بَدْرٍ الكُبْرَى — يَوْمُ الفُرْقَانِ وَمَصَارِعُ الطُّغَاةِ', 'باب 1: غزوۂ بدرِ کبریٰ — حق و باطل کا پہلا معرکہ اور نصرتِ الٰہی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('raheeq_seg_1_1', 'raheeq_ch1_badr', 'kharji_raheeq_makhtum', 0, 'قَالَ الشَّيْخُ صَفِيُّ الرَّحْمَنِ المُبَارَكْفُورِيُّ: كَانَتْ غَزْوَةُ بَدْرٍ فِي السَّابِعَ عَشَرَ مِنْ رَمَضَانَ فِي السَّنَةِ الثَّانِيَةِ لِلْهِجْرَةِ. وَقَفَ رَسُولُ اللَّهِ ﷺ لَيْلَتَهَا يَدْعُو رَبَّهُ وَيَسْتَغِيثُهُ: «اللَّهُمَّ إِنْ تَهْلِكْ هَذِهِ العِصَابَةُ مِنْ أَهْلِ الإِسْلَامِ لَا تُعْبَدْ فِي الأَرْضِ»، حَتَّى سَقَطَ رِدَاؤُهُ عَنْ مَنْكِبَيْهِ، فَالْتَزَمَهُ أَبُو بَكْرٍ وَقَالَ: حَسْبُكَ يَا رَسُولَ اللَّهِ، فَإِنَّ اللَّهَ سَيُنْجِزُ لَكَ مَا وَعَدَكَ، فَأَنْزَلَ اللَّهُ جُنْدَهُ مِنَ المَلَائِكَةِ مُرْدِفِينَ.', 'مولانا صفی الرحمن مبارکپوری رحمہ اللہ فرماتے ہیں: غزوۂ بدر ۱۷ رمضان المبارک ۲ ہجری کو پیش آیا۔ رسول اللہ ﷺ اس رات بارگاہِ الٰہی میں گریہ و زاری کے ساتھ مناجات فرماتے رہے اور ہاتھ اٹھا کر دعا کی: ''اے اللہ! اگر اہل اسلام کی یہ مٹھی بھر جماعت آج ہلاک ہو گئی تو روئے زمین پر تیری عبادت کرنے والا کوئی نہ رہے گا!'' یہاں تک کہ چادر مبارک کندھوں سے ڈھلک گئی، حضرت ابوبکر صدیق نے چادر سنبھالی اور لپٹ کر عرض کیا: یا رسول اللہ! آپ کی مناجات کافی ہے، اللہ اپنا وعدہ ضرور پورا فرمائے گا؛ چنانچہ اللہ نے ہزاروں فرشتوں کی فوجیں اتار کر مسلمانوں کو فتحِ مبین عطا فرمائی۔', 'الرحیق المختوم کو رابطہ عالم اسلامی کے بین الاقوامی مقابلے میں دنیا بھر کی ۱۷۱ کتب میں اول انعام ملا۔ بدر کا یہ واقعہ دعاؤں کی طاقت اور نصرتِ الٰہی کا روشن باب ہے۔', '[{"word":"مُرْدِفِينَ","role":"حال منصوب","sign":"ياء الجمع","detail":"حال من الملائكة"}]', '["الرحيق المختوم، غزوة بدر الكبرى، رواه مسلم."]', '{"en":"From ''The Sealed Nectar'': The Battle of Badr, 17th of Ramadan 2 AH. The intense supplication of the Prophet ﷺ and the miraculous descent of angelic reinforcements.","ar":"يوم الفرقان الذي أعز الله فيه الإسلام وأذل فيه صناديد الشرك والباطل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('raheeq_ch2_fath', 'kharji_raheeq_makhtum', 1, 'فَتْحُ مَكَّةَ المُعَظَّمَةِ — دُخُولُ الفَاتِحِ الأَعْظَمِ خَاضِعاً', 'باب 2: فتحِ مکہ — عفو و درگزر، رحمۃ للعالمینی اور بتوں کی پاش پاشی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('raheeq_seg_2_1', 'raheeq_ch2_fath', 'kharji_raheeq_makhtum', 0, 'دَخَلَ رَسُولُ اللَّهِ ﷺ مَكَّةَ فَاتِحاً فِي رَمَضَانَ سَنَةَ ثَمَانٍ مِنَ الهِجْرَةِ، وَهُوَ وَاضِعٌ رَأْسَهُ تَوَاضُعاً لِلَّهِ حَتَّى إِنَّ عُثْنُونَهُ لَيَمَسُّ وَاسِطَةَ الرَّحْلِ، ثُمَّ وَقَفَ عَلَى بَابِ الكَعْبَةِ وَقَالَ لِقُرَيْشٍ: «يَا مَعْشَرَ قُرَيْشٍ، مَا تَرَوْنَ أَنِّي فَاعِلٌ بِكُمْ؟» قَالُوا: خَيْراً، أَخٌ كَرِيمٌ وَابْنُ أَخٍ كَرِيمٍ! فَقَالَ ﷺ: «لَا تَثْرِيبَ عَلَيْكُمُ اليَوْمَ، اذْهَبُوا فَأَنْتُمُ الطُّلَقَاءُ».', 'رسول اللہ ﷺ ۸ ہجری میں مکہ مکرمہ میں فاتحانہ داخل ہوئے، اور آپ اللہ کی بارگاہ میں عاجزی سے اپنا سر اس قدر جھکائے ہوئے تھے کہ داڑھی مبارک کجاوے کی لکڑی کو چھو رہی تھی۔ پھر آپ کعبہ کے دروازے پر کھڑے ہوئے اور قریش سے پوچھا: ''اے قریش کے لوگو! تمہارا کیا خیال ہے کہ میں تمہارے ساتھ کیا سلوک کرنے والا ہوں؟'' انہوں نے کہا: ہم خیر کی امید رکھتے ہیں، آپ شریف بھائی ہیں اور شریف بھائی کے فرزند ہیں! آپ ﷺ نے تاریخِ انسانی کا سب سے بڑا عفو کا اعلان کرتے ہوئے فرمایا: ''آج تم پر کوئی گرفت نہیں، جاؤ تم سب آزاد ہو!''', 'جس مکہ نے آپ پر پتھر برسائے، صحابہ کو شہید کیا اور وطن چھوڑنے پر مجبور کیا، فتح کے دن بدلہ لینے کے بجائے سب کو معاف فرما دینا صرف اور صرف رحمۃ للعالمین ﷺ کا ہی شیوہ ہو سکتا ہے۔', '[{"word":"تَوَاضُعاً","role":"مفعول لأجله منصوب","sign":"فتحة","detail":"أو حال منصوبة"}]', '["الرحيق المختوم، فتح مكة، وأصله في سيرة ابن هشام وسنن البيهقي."]', '{"en":"Conquest of Makkah: The Prophet ﷺ entered with profound humility before Allah, then granted unprecedented general amnesty: ''No blame will there be upon you today. Go, for you are free.''","ar":"أعظم نموذج في العفو عند المقدرة في تاريخ البشرية جمعاء."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_zad_maad_jawziyyah', 'زَادُ المَعَادِ فِي هَدْيِ خَيْرِ العِبَادِ', 'شَمْسُ الدِّينِ الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'seerah', 'نبوی ہدایات، فقہ، عبادات و طبِ نبوی', 'کتبِ مطالعہ و موسوعة الہدایت النبویہ', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'سیرت اور فقہ کا لاجواب امتزاج۔ حضور ﷺ کی نماز، روزہ، حج، جہاد، قضا، لباس، خوراک اور علاج کے تمام مسنون طریقوں کا انسائیکلوپیڈیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('zad_ch1_salah', 'kharji_zad_maad_jawziyyah', 0, 'هَدْيُهُ ﷺ فِي صَلَاتِهِ وَخُشُوعِهِ', 'باب 1: رسول اللہ ﷺ کی نماز اور خشوع و خضوع کے اسرار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('zad_seg_1_1', 'zad_ch1_salah', 'kharji_zad_maad_jawziyyah', 0, 'قَالَ ابْنُ قَيِّمِ الجَوْزِيَّةِ: كَانَ ﷺ إِذَا قَامَ إِلَى الصَّلَاةِ اسْتَقْبَلَ القِبْلَةَ وَرَفَعَ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ، وَكَانَتْ صَلَاتُهُ قُرَّةَ عَيْنِهِ وَرَاحَةَ قَلْبِهِ، يَقُولُ: «يَا بِلَالُ، أَرِحْنَا بِالصَّلَاةِ».', 'امام ابن قیم فرماتے ہیں: رسول اللہ ﷺ جب نماز کے لیے کھڑے ہوتے تو قبلہ رخ ہو کر دونوں ہاتھ اٹھاتے، اور نماز آپ کی آنکھوں کی ٹھنڈک تھی، آپ فرماتے: ''اے بلال! اذان دو اور نماز سے ہمیں راحت پہنچاؤ!''', 'زاد المعاد سیرت اور فقہ کا انسائیکلوپیڈیا ہے۔', '[{"word":"قُرَّةَ","role":"خبر كان منصوب","sign":"فتحة","detail":"صلاته اسمها وقرة خبرها"}]', '["زاد المعاد، 1/ 120."]', '{"en":"The Prophet''s profound tranquility and devotion in prayer.","ar":"بيان هدي النبي في الصلاة والخشوع."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('zad_ch2_tibb', 'kharji_zad_maad_jawziyyah', 1, 'هَدْيُهُ ﷺ فِي الطِّبِّ النَّبَوِيِّ وَالحِمْيَةِ', 'باب 2: طبِ نبوی — جسمانی صحت، پرہیز اور علاج کے مسنون طریقے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('zad_seg_2_1', 'zad_ch2_tibb', 'kharji_zad_maad_jawziyyah', 0, '«كَانَ مِنْ هَدْيِهِ ﷺ التَّدَاوِي، وَأَمَرَ بِهِ أُمَّتَهُ، فَقَالَ: تَدَاوَوْا عِبَادَ اللَّهِ، فَإِنَّ اللَّهَ لَمْ يَضَعْ دَاءً إِلَّا وَضَعَ لَهُ شِفَاءً. وَكَانَ يَمْزُجُ بَيْنَ الطِّبِّ الإِلَهِيِّ الرُّوحَانِيِّ وَالطِّبِّ الطَّبِيعِيِّ البَدَنِيِّ».', 'رسول اللہ ﷺ کی سنت علاج کروانا تھی، اور آپ نے امت کو حکم دیا: ''اے اللہ کے بندو! علاج کروایا کرو، کیونکہ اللہ نے کوئی بیماری ایسی نہیں اتاری جس کی شفا نہ اتاری ہو!'' اور آپ روحانی علاج (دعاؤں) اور قدرتی ادویات و پرہیز دونوں کو جمع فرماتے تھے۔', 'اسلام بیماریوں پر ہاتھ پر ہاتھ رکھ کر بیٹھنے کی مذمت کرتا ہے اور علاج کو توکل کے منافی نہیں بلکہ عین توکل قرار دیتا ہے۔', '[{"word":"تَدَاوَوْا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو فاعل"}]', '["زاد المعاد، فصل في الطب النبوي."]', '{"en":"Prophetic Medicine: Combining spiritual healing with natural remedies and dietetic hygiene.","ar":"أصول الطب النبوي والحث على التداوي والأخذ بالأسباب."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_siyar_alam_nubala', 'سِيَرُ أَعْلَامِ النُّبَلَاءِ', 'الإِمَامُ الحَافِظُ شَمْسُ الدِّينِ أَبُو عَبْدِ اللَّهِ الذَّهَبِيُّ (ت: 748ھ)', 'kharji_kitab', 'tarikh', 'سوانحِ ائمۂ دین، محدثین و عباقرہ', 'کتبِ مطالعہ و بصیرتِ علمیہ (جامع انسائیکلوپیڈیا)', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'صحابہ، تابعین، ائمہ مجتہدین اور مشاہیر اسلام کی زندگی کے چونکا دینے والے واقعات۔ اس کتاب کے مطالعے سے طلبہ کے دلوں میں سلف کا عشق اور علم کا ولولہ انگڑائیاں لیتا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('siyar_ch1_ahmad_mihnah', 'kharji_siyar_alam_nubala', 0, 'مِحْنَةُ خَلْقِ القُرْآنِ وَثَبَاتُ الإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ رَحِمَهُ اللَّهُ', 'باب 1: فتنۂ خلقِ قرآن اور امام احمد بن حنبل کا پہاڑ جیسا تاریخی ثبات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('siyar_seg_1_1', 'siyar_ch1_ahmad_mihnah', 'kharji_siyar_alam_nubala', 0, 'قَالَ الإِمَامُ الحَافِظُ شَمْسُ الدِّينِ الذَّهَبِيُّ: «وَقَفَ الإِمَامُ أَحْمَدُ بْنُ حَنْبَلٍ فِي المِحْنَةِ مَوْقِفَ الأَنْبِيَاءِ، حِينَ جُلِبَ إِلَى سِيَاطِ المُعْتَصِمِ وَقِيلَ لَهُ: قُلْ: القُرْآنُ مَخْلُوقٌ حَتَّى أُطْلِقَ عَنْكَ! فَقَالَ: أَعْطُونِي شَيْئاً مِنْ كِتَابِ اللَّهِ أَوْ سُنَّةِ رَسُولِهِ حَتَّى أَقُولَ بِهِ، كَيْفَ أَقُولُ مَا لَمْ يُقَلْ؟! وَضُرِبَ بِالسِّيَاطِ حَتَّى غُشِيَ عَلَيْهِ وَتَقَطَّعَ لَحْمُهُ، وَهُوَ ثَابِتٌ كَالجَبَلِ الأَشَمِّ يَقُولُ: كَلَامُ اللَّهِ غَيْرُ مَخْلُوقٍ. قَالَ عَلِيُّ بْنُ المَدِينِيِّ: أَعَزَّ اللَّهُ الدِّينَ بِأَبِي بَكْرٍ يَوْمَ الرِّدَّةِ، وَبِأَحْمَدَ يَوْمَ المِحْنَةِ».', 'امام حافظ شمس الدین ذہبی رحمہ اللہ فرماتے ہیں: ''امام احمد بن حنبل فتنۂ خلقِ قرآن کی ہولناک آزمائش میں انبیاء کے مقام پر کھڑے ہو گئے، جب انہیں عباسی خلیفہ معتصم کے کوڑوں کے سامنے لایا گیا اور کہا گیا: صرف اتنا کہہ دیجیے کہ قرآن مخلوق ہے تاکہ آپ کو رہا کر دیا جائے! تو انہوں نے فرمایا: مجھے کتاب اللہ یا سنتِ رسول میں سے کوئی دلیل لا کر دو تاکہ میں وہ مان لوں، میں وہ بات کیسے کہہ دوں جو اللہ اور اس کے رسول نے نہیں فرمائی؟! پھر آپ کو بے دریغ کوڑے مارے گئے یہاں تک کہ آپ بے ہوش ہو گئے اور مبارک گوشت کٹ گیا، مگر آپ بلند پہاڑ کی طرح ثابت قدم رہے اور یہی فرماتے رہے: قرآن اللہ کا کلام ہے، مخلوق نہیں! علی بن مدینی فرماتے ہیں: اللہ نے اس دین کو ارتداد کے دن حضرت ابوبکر کے ذریعے عزت دی، اور آزمائش کے دن احمد بن حنبل کے ذریعے سر بلند فرمایا''۔', 'سير أعلام النبلاء تراجم اور اسلامی تاریخ کا عظیم ترین انسائیکلوپیڈیا ہے۔ امام ذہبی نے ائمہ کے حالات اس شان سے لکھے ہیں کہ قاری کے اندر ایمانی غیرت اور صبر کا ولولہ انگڑائیاں لینے لگتا ہے۔', '[{"word":"مَوْقِفَ","role":"مفعول مطلق منصوب","sign":"فتحة","detail":"مبين للنوع وهو مضاف"},{"word":"كَالجَبَلِ","role":"جار ومجرور شبه جملة نعت","sign":"كسرة","detail":"يصف ثبات الإمام"}]', '["سير أعلام النبلاء للذهبي، ترجمة الإمام أحمد، 11/ 230-260."]', '{"en":"Imam Adh-Dhahabi chronicles the trial of the Quran''s creation: Imam Ahmad stood like a mountain under the lashes of the Caliph Al-Mu''tasim, refusing to compromise orthodoxy. ''Ali ibn al-Madini said: ''Allah aided Islam through Abu Bakr on the Day of Apostasy, and through Ahmad on the Day of the Mihnah.''","ar":"بطولة الإمام أحمد بن حنبل في الذود عن عقيدة أهل السنة والجماعة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('siyar_ch2_bukhari_wara', 'kharji_siyar_alam_nubala', 1, 'سِيرَةُ الإِمَامِ البُخَارِيِّ: العِبَادَةُ وَالوَرَعُ وَعِزَّةُ أَهْلِ الحَدِيثِ', 'باب 2: امیر المؤمنین فی الحدیث امام محمد بن اسماعیل البخاری کا زہد، عبادت اور دینی غیرت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('siyar_seg_2_1', 'siyar_ch2_bukhari_wara', 'kharji_siyar_alam_nubala', 0, '«قَالَ الذَّهَبِيُّ: كَانَ أَبُو عَبْدِ اللَّهِ البُخَارِيُّ رَأْساً فِي العِلْمِ، وَرَأْساً فِي العِبَادَةِ وَالوَرَعِ. كَانَ يَخْتِمُ فِي رَمَضَانَ كُلَّ يَوْمٍ خَتْمَةً فِي النَّهَارِ، وَيَقُومُ بِثُلُثِ القُرْآنِ بِاللَّيْلِ. وَلَمَّا طَلَبَ مِنْهُ أَمِيرُ بُخَارَى خَالِدُ بْنُ أَحْمَدَ أَنْ يَحْمِلَ إِلَيْهِ الصَّحِيحَ لِيَسْمَعَهُ أَوْلَادُهُ فِي قَصْرِهِ، امْتَنَعَ البُخَارِيُّ وَقَالَ لِرَسُولِهِ: قُلْ لَهُ: أَنَا لَا أُذِلُّ العِلْمَ وَلَا أَحْمِلُهُ إِلَى أَبْوَابِ السَّلَاطِينِ، فَمَنْ كَانَتْ لَهُ حَاجَةٌ فَلْيَحْضُرْ إِلَى مَسْجِدِي! فَكَانَ ذَلِكَ سَبَبَ إِخْرَاجِهِ مِنْ وَطَنِهِ مَظْلُوماً».', 'امام ذہبی فرماتے ہیں: ''امام بخاری رحمہ اللہ جہاں علمِ حدیث میں امامت کے اعلیٰ ترین مقام پر تھے وہیں زہد، شب بیداری اور عبادت میں بھی یکتا تھے۔ رمضان المبارک میں ہر روز دن کے وقت ایک مکمل قرآن ختم کرتے اور رات کو تہائی قرآن کے ساتھ تہجد ادا کرتے۔ اور جب بخارا کے گورنر خالد بن احمد نے پیغام بھیجا کہ آپ میرے محل میں آ کر میرے بیٹوں کو صحیح بخاری پڑھائیں، تو امام بخاری نے اس کے قاصد سے فرمایا: ''جا کر اپنے امیر سے کہہ دو کہ میں علمِ نبوت کو سلاطین کی دہلیز پر لے جا کر ذلیل نہیں کروں گا، جس کو علم کی طلب ہو وہ عام طلبہ کی طرح میری مسجد میں حاضر ہو!'' اور یہی حق پرستی ان کے اپنے وطن سے مظلومانہ جلاوطنی کا سبب بنی''۔', 'اہلِ علم کی عزت اسی میں ہے کہ وہ علم کو دنیاوی مفادات کے لیے حکمرانوں کا خادم نہ بنائیں بلکہ علم کی حرمت پر جان اور وطن قربان کر دیں۔', '[{"word":"رَأْساً","role":"خبر كان منصوب","sign":"فتحة","detail":"أبو عبد الله اسمها ورأساً خبرها"},{"word":"مَظْلُوماً","role":"حال منصوب","sign":"فتحة","detail":"يبين هيئة خروج الإمام"}]', '["سير أعلام النبلاء للذهبي، 12/ 390-420."]', '{"en":"Imam Al-Bukhari''s supreme scholarly dignity: He completed a recitation of the Quran daily in Ramadan. When the governor of Bukhara ordered him to tutor his royal children privately, Bukhari boldly refused: ''I shall never demean sacred knowledge by carrying it to the doorsteps of rulers.''","ar":"عزة العالم الرباني ورفضه إهانة علم الحديث أمام الملوك والحكام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_bidayah_nihayah_kathir', 'البِدَايَةُ وَالنِّهَايَةُ', 'الحَافِظُ عِمَادُ الدِّينِ إِسْمَاعِيلُ بْنُ عُمَرَ ابْنُ كَثِيرٍ الدِّمَشْقِيُّ (ت: 774ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام: تخلیقِ کائنات تا روزِ جزا', 'کتبِ مطالعہ و مراجعِ تاریخ (کبار طلبہ)', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'تخلیقِ آدم، قصص الانبیاء، سیرتِ نبوی، خلفائے راشدین، اموی و عباسی تاریخ، اور علاماتِ قیامت و حشر و نشر کا مفصل ترین تاریخی ریکارڈ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bidayah_ch1_khalq', 'kharji_bidayah_nihayah_kathir', 0, 'بَدْءُ الخَلْقِ: خَلْقُ العَرْشِ وَالقَلَمِ وَالسَّمَاوَاتِ وَالأَرْضِ', 'باب 1: کائنات کا آغاز — عرشِ الٰہی، لوح و قلم اور زمین و آسمان کی تخلیق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bidayah_seg_1_1', 'bidayah_ch1_khalq', 'kharji_bidayah_nihayah_kathir', 0, 'قَالَ الحَافِظُ عِمَادُ الدِّينِ ابْنُ كَثِيرٍ: «قَالَ اللَّهُ تَعَالَى: {وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى المَاءِ}. رَوَى البُخَارِيُّ عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «كَانَ اللَّهُ وَلَمْ يَكُنْ شَيْءٌ قَبْلَهُ، وَكَانَ عَرْشُهُ عَلَى المَاءِ، ثُمَّ كَتَبَ فِي الذِّكْرِ كُلَّ شَيْءٍ، ثُمَّ خَلَقَ السَّمَاوَاتِ وَالأَرْضَ». فَأَوَّلُ مَخْلُوقَاتِ هَذَا العَالَمِ المَشْهُودِ هُوَ العَرْشُ، ثُمَّ القَلَمُ الَّذِي جَرَى بِمَقَادِيرِ الخَلَائِقِ قَبْلَ خَلْقِ السَّمَاوَاتِ بِخَمْسِينَ أَلْفَ سَنَةٍ».', 'حافظ ابن کثیر رحمہ اللہ فرماتے ہیں: ''اللہ تبارک و تعالیٰ کا ارشاد ہے: {اور وہی ہے جس نے آسمانوں اور زمین کو چھ دنوں میں پیدا کیا اور اس کا عرش پانی پر تھا}۔ امام بخاری نے حضرت عمران بن حصین رضی اللہ عنہ سے روایت کیا کہ رسول اللہ ﷺ نے فرمایا: ''سب سے پہلے ازل میں صرف اللہ تھا اور اس سے پہلے کوئی چیز نہ تھی، اور اس کا عرش پانی پر تھا، پھر اس نے لوحِ محفوظ میں ہر چیز کی تقدیر لکھی، پھر آسمانوں اور زمین کو پیدا فرمایا''۔ پس اس کائناتِ مشہود میں سب سے پہلی مخلوق عرشِ عظیم ہے، اس کے بعد قلم کو پیدا کیا گیا جس نے زمین و آسمان کی پیدائش سے پچاس ہزار سال پہلے تمام مخلوقات کے مقدر لکھ دیے''۔', 'البداية والنهاية اسلامی تاریخ کا سب سے جامع اور مستند شاہکار ہے جو آغازِ کائنات سے لے کر قیامت کے احوال تک کا مستند بیان فراہم کرتا ہے۔', '[{"word":"سِتَّةِ","role":"مجرور بفي","sign":"كسرة","detail":"وهو مضاف وأيام مضاف إليه"},{"word":"العَرْشُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"أول مبتدأ والعرش خبره"}]', '["البداية والنهاية لابن كثير، 1/ 8-15، وأخرجه البخاري (3191)."]', '{"en":"Hafiz Ibn Kathir''s grand narrative on the beginning of creation: ''Allah existed and there was nothing before Him, and His Throne was over water...'' The pristine cosmological sequence of Throne, Pen, and cosmic architecture according to authentic prophetic narrations.","ar":"تحقيق أول ما خلق الله وبيان عظمة بدء الخلق في المنظور العقدي التاريخي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bidayah_ch2_nihayah_fitan', 'kharji_bidayah_nihayah_kathir', 1, 'أَشْرَاطُ السَّاعَةِ الكُبْرَى وَالمَلَاحِمُ فِي آخِرِ الزَّمَانِ', 'باب 2: قیامت کی بڑی نشانیاں، ظہورِ مہدی اور نزولِ عیسیٰ علیہ السلام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bidayah_seg_2_1', 'bidayah_ch2_nihayah_fitan', 'kharji_bidayah_nihayah_kathir', 0, '«عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ الغِفَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: اطَّلَعَ النَّبِيُّ ﷺ عَلَيْنَا وَنَحْنُ نَتَذَاكَرُ فَقَالَ: «مَا تَذَاكَرُونَ؟» قَالُوا: نَذْكُرُ السَّاعَةَ. قَالَ: «إِنَّهَا لَنْ تَقُومَ حَتَّى تَرَوْنَ قَبْلَهَا عَشْرَ آيَاتٍ: الدُّخَانَ، وَالدَّجَّالَ، وَالدَّابَّةَ، وَطُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا، وَنُزُولَ عِيسَى ابْنِ مَرْيَمَ، وَيَأْجُوجَ وَمَأْجُوجَ، وَثَلَاثَةَ خُسُوفٍ: خَسْفاً بِالمَشْرِقِ، وَخَسْفاً بِالمَغْرِبِ، وَخَسْفاً بِجَزِيرَةِ العَرَبِ، وَآخِرُ ذَلِكَ نَارٌ تَخْرُجُ مِنَ اليَمَنِ تَطْرُدُ النَّاسَ إِلَى مَحْشَرِهِمْ».', 'حضرت حذیفہ بن اسید غفاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ ہمارے پاس تشریف لائے جبکہ ہم آپس میں علمی گفتگو کر رہے تھے، آپ نے دریافت فرمایا: ''تم کس چیز کا تذکرہ کر رہے ہو؟'' صحابہ نے عرض کیا: ہم قیامت کا ذکر کر رہے ہیں۔ آپ ﷺ نے فرمایا: ''قیامت اس وقت تک ہرگز قائم نہیں ہوگی جب تک کہ تم اس سے پہلے دس بڑی نشانیاں نہ دیکھ لو: دھوئیں کا آنا، دجال اکبر کا فتنہ، دابۃ الارض کا نکلنا، سورج کا مغرب سے طلوع ہونا، حضرت عیسیٰ بن مریم کا آسمان سے نزول، یاجوج و ماجوج کا خروج، تین بڑے زلزلے و دھنسن (ایک مشرق میں، ایک مغرب میں اور ایک جزیرۂ عرب میں)، اور سب سے آخر میں ایک زبردست آگ جو یمن سے نکلے گی اور لوگوں کو ہانک کر ان کے میدانِ محشر کی طرف لے جائے گی''۔', 'ابن کثیر نے کتاب النہایہ میں فتنوں اور علاماتِ قیامت کی تمام صحیح روایات کو تاریخی تسلسل کے ساتھ مرتب کر کے امت کے ایمان کو مضبوط کیا ہے۔', '[{"word":"عَشْرَ","role":"مفعول به لترون منصوب","sign":"فتحة","detail":"وهو مضاف وآيات مضاف إليه"},{"word":"نَارٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"آخر مبتدأ ونار خبره"}]', '["البداية والنهاية، كتاب الفتن والملاحم، وأخرجه مسلم (2901)."]', '{"en":"The Ten Major Signs of the Final Hour: The Smoke, the Dajjal, the Beast, sunrise from the west, descent of Jesus, Gog and Magog, three major landslides, and the apocalyptic fire driving mankind to the gathering place.","ar":"استقصاء أشراط الساعة الكبرى كما رواها مسلم في صحيحه وحققها ابن كثير."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_fiqh_seerah_ghazali', 'فِقْهُ السِّيرَةِ النَّبَوِيَّةِ', 'الشَّيْخُ الدَّاعِيَةُ مُحَمَّدُ الغَزَالِيُّ المِصْرِيُّ (ت: 1416ھ)', 'kharji_kitab', 'seerah', 'سیرت سے جدید فکری و انقلابی اسباق', 'کتبِ مطالعہ و بیداریٔ فکر (جملہ طلبہ)', NULL, NULL, 'from-teal-950 via-emerald-900 to-stone-900', NULL, 'سیرتِ رسول ﷺ کو محض ماضی کے واقعات کے بجائے زندہ تحریک، دعوت اور امت کے مسائل کا حل بنا کر پیش کرنے والی عصرِ حاضر کی شاہکار کتاب۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('f_ghazali_ch1_dawah', 'kharji_fiqh_seerah_ghazali', 0, 'فِقْهُ الدَّعْوَةِ فِي العَهْدِ المَكِّيِّ وَالصَّبْرُ عَلَى الأَذَى', 'باب 1: مکی دور کی دعوتی حکمتیں اور ظلم پر صبر و استقامت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('f_ghazali_seg_1_1', 'f_ghazali_ch1_dawah', 'kharji_fiqh_seerah_ghazali', 0, 'قَالَ الشَّيْخُ مُحَمَّدٌ الغَزَالِيُّ: «لَمْ تَكُنِ الدَّعْوَةُ المَكِّيَّةُ مُجَرَّدَ كَلِمَاتٍ تُقَالُ، بَلْ كَانَتْ مَدْرَسَةً لِصِنَاعَةِ الرِّجَالِ، وَتَرْبِيَةِ الجِيلِ الأَوَّلِ عَلَى التَّضْحِيَةِ بِالمَالِ وَالنَّفْسِ فِي سَبِيلِ المَبْدَأِ».', 'علامہ محمد الغزالی مصری رحمہ اللہ فرماتے ہیں: ''مکی دور کی دعوت محض زبانی کلامی باتیں نہیں تھیں، بلکہ وہ کردار ساز انسانوں کو تراشنے اور پہلی نسل کو حق کے لیے جان و مال کی قربانی کا خوگر بنانے والی عظیم درسگاہ تھی''۔', 'تکالیف انسان کو کندن بناتی ہیں۔ صحابہ کرام نے مکہ کے تپتے انگاروں پر جو استقامت دکھائی اسی نے انہیں دنیا کی قیادت کے قابل بنایا۔', '[{"word":"مَدْرَسَةً","role":"خبر كان منصوب","sign":"فتحة","detail":"الدعوة اسمها ومدرسة خبرها"}]', '["فقه السيرة لمحمد الغزالي، ص 85."]', '{"en":"Sheikh Muhammad Al-Ghazali demonstrates how the Makkan period forged resilient characters capable of carrying Islam''s global mission.","ar":"فقه التربية القيادية في العهد المكي الشريف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_fiqh_seerah_bouti', 'فِقْهُ السِّيرَةِ النَّبَوِيَّةِ مَعَ مُوجَزٍ لِتَارِيخِ الخِلَافَةِ الرَّاشِدَةِ', 'الدُّكْتُورُ الشَّهِيدُ مُحَمَّدُ سَعِيدٍ رَمَضَانُ البُوطِيُّ (ت: 1434ھ)', 'kharji_kitab', 'seerah', 'سیرتِ نبوی کے فقہی، عقدی و اخلاقی احکام', 'کتبِ مطالعہ و تدریسِ سیرت (جامعات و مدارس)', NULL, NULL, 'from-rose-950 via-stone-900 to-emerald-950', NULL, 'سیرتِ نبوی کے ہر واقعے (ہجرت، صلح حدیبیہ، بیعت عقبہ، غزوات) سے عقیدے، فقہ اور تزکیہ کے استنباطات کا علمی تجزیہ۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('bouti_ch1_dawlah', 'kharji_fiqh_seerah_bouti', 0, 'تَأْسِيسُ دَوْلَةِ المَدِينَةِ وَوَثِيقَةُ التَّعَايُشِ السِّلْمِيِّ', 'باب 1: میثاقِ مدینہ — تاریخ کا پہلا تحریری دستور اور اسلامی ریاست کی بنیاد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('bouti_seg_1_1', 'bouti_ch1_dawlah', 'kharji_fiqh_seerah_bouti', 0, 'قَالَ الشَّهِيدُ الدُّكْتُورُ مُحَمَّدٌ سَعِيدٌ رَمَضَانُ البُوطِيُّ: «وَثِيقَةُ المَدِينَةِ هِيَ أَوَّلُ دُسْتُورٍ مَدَنِيٍّ مَكْتُوبٍ فِي تَارِيخِ البَشَرِيَّةِ، أَرْسَى فِيهِ النَّبِيُّ ﷺ قَوَاعِدَ المُواطَنَةِ، وَالعَدَالَةِ، وَحُرِّيَّةِ الِاعْتِقَادِ، وَالتَّكَافُلِ الاجْتِمَاعِيِّ بَيْنَ المُسْلِمِينَ وَغَيْرِهِمْ».', 'شہیدِ محراب ڈاکٹر محمد سعید رمضان البوطی رحمہ اللہ فرماتے ہیں: ''میثاقِ مدینہ تاریخِ انسانیت کا پہلا تحریری آئین و دستور ہے، جس میں رسول اللہ ﷺ نے مسلمانوں اور غیر مسلموں کے مابین شہری حقوق، عدل و انصاف، مذہبی آزادی اور باہمی دفاع کے انقلابی اصول قائم فرمائے''۔', 'سیرتِ نبوی نے دنیا کو بتایا کہ امن، قانون کی بالادستی اور تمام شہریوں کے حقوق کا احترام ریاستِ مدینہ کا اصل جوہر تھا۔', '[{"word":"وَثِيقَةُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"هي ضمير فصل وأول خبر المبتدأ"}]', '["فقه السيرة النبوية للبوطي، ص 162."]', '{"en":"Dr. Al-Bouti explores the Constitution of Madinah: The first written civil charter guaranteeing citizenship and justice in history.","ar":"دستور المدينة المنورة وأسس الدولة الإسلامية المدنية العادلة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_suwar_sahabah_basha', 'صُوَرٌ مِنْ حَيَاةِ الصَّحَابَةِ', 'الدُّكْتُورُ عَبْدُ الرَّحْمَنِ رَأْفَتِ البَاشَا (ت: 1406ھ)', 'kharji_kitab', 'seerah', 'صحابہ کرام کے ایمان افروز و سبق آموز سوانح', 'کتبِ مطالعہ و ترغیب (نوجوان نسل و طلبہ)', NULL, NULL, 'from-emerald-900 via-amber-950 to-stone-900', NULL, 'صحابہ کرام کے ایثار، شجاعت، عبادت اور انکساری کے ایسے روح پرور مرقعے جنہیں پڑھ کر طالب علم کی آنکھیں اشکبار اور دل جذبہ ایمانی سے سرشار ہو جاتا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('basha_ch1_siddiq', 'kharji_suwar_sahabah_basha', 0, 'أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ: ثَانِي اثْنَيْنِ وَخَلِيفَةُ رَسُولِ اللَّهِ', 'باب 1: سیدنا ابوبکر صدیق رضی اللہ عنہ — ثانی اثنین، پیکرِ صدق و وفا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('basha_seg_1_1', 'basha_ch1_siddiq', 'kharji_suwar_sahabah_basha', 0, 'قَالَ الدُّكْتُورُ عَبْدُ الرَّحْمَنِ رَأْفَت البَاشَا: «مَا تَرَدَّدَ حِينَ دَعَاهُ النَّبِيُّ ﷺ لَحْظَةً، وَأَنْفَقَ مَالَهُ كُلَّهُ فِي غَزْوَةِ تَبُوكَ، فَقَالَ لَهُ النَّبِيُّ ﷺ: مَا أَبْقَيْتَ لِأَهْلِكَ؟ فَقَالَ بِكُلِّ يَقِينٍ: أَبْقَيْتُ لَهُمُ اللَّهَ وَرَسُولَهُ».', 'ڈاکٹر عبدالرحمن رأفت الباشا فرماتے ہیں: جب نبی کریم ﷺ نے انہیں اسلام کی دعوت دی تو انہوں نے پلک جھپکنے کی دیر بھی تامل نہ کیا، اور غزوۂ تبوک میں اپنا سارا مال لا کر بارگاہِ رسالت میں ڈال دیا۔ نبی کریم ﷺ نے دریافت فرمایا: اپنے گھر والوں کے لیے کیا چھوڑا؟ تو انہوں نے کمالِ یقین کے ساتھ عرض کیا: ''ان کے لیے اللہ اور اس کے رسول کو چھوڑ آیا ہوں!''', 'صور من حياة الصحابة طلبہ کے دلوں میں صحابہ کرام کا والہانہ عشق اور کردار پیدا کرنے والی بے نظیر کتاب ہے۔', '[{"word":"أَبْقَيْتُ","role":"فعل ماض وفاعل","sign":"مبني","detail":"لفظ الجلالة مفعول به منصوب"}]', '["صور من حياة الصحابة، ص 15، وأخرجه أبو داود والترمذي."]', '{"en":"Abu Bakr As-Siddiq: Sacrificing everything for Allah and His Messenger without hesitation.","ar":"سيد الصديقين وأول الخلفاء الراشدين وأحب الرجال إلى رسول الله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('basha_ch2_farooq', 'kharji_suwar_sahabah_basha', 1, 'عُمَرُ بْنُ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: الفَارُوقُ الَّذِي أَعَزَّ اللَّهُ بِهِ الإِسْلَامَ', 'باب 2: سیدنا عمر فاروق رضی اللہ عنہ — عدل و انصاف کا ہمالہ اور مرادِ رسول ﷺ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('basha_seg_2_1', 'basha_ch2_farooq', 'kharji_suwar_sahabah_basha', 0, '«كَانَ إِسْلَامُ عُمَرَ فَتْحاً، وَهِجْرَتُهُ نَصْراً، وَإِمَارَتُهُ رَحْمَةً. وَقَفَ عَلَى المِنْبَرِ يَقُولُ: لَوْ عَثَرَتْ بَغْلَةٌ فِي العِرَاقِ لَسَأَلَنِي اللَّهُ عَنْهَا: لِمَ لَمْ تُسَوِّ لَهَا الطَّرِيقَ يَا عُمَرُ!».', 'سیدنا عبداللہ بن مسعود فرماتے ہیں: حضرت عمر کا اسلام لانا فتح تھا، ان کی ہجرت نصرت تھی، اور ان کی خلافت سراپا رحمت تھی۔ وہ منبر پر کھڑے ہو کر فرماتے تھے: ''اگر فرات کے کنارے عراق میں کوئی خچر بھی ٹھوکر کھا کر گر جائے تو مجھے خوف ہے کہ قیامت کے دن اللہ عمر سے پوچھے گا کہ تو نے اس کے لیے راستہ کیوں ہموار نہ کیا تھا!''', 'یہ احساسِ ذمہ داری اور خوفِ خدا ہی تھا جس نے فاروقِ اعظم کی حکومت کو مشرق سے مغرب تک عدل و انصاف کی لازوال مثال بنا دیا۔', '[{"word":"فَتْحاً","role":"خبر كان منصوب","sign":"فتحة","detail":"إسلام اسمها وفتحاً خبرها"}]', '["صور من حياة الصحابة، وأخرجه البخاري."]', '{"en":"''Umar bin Al-Khattab: The paragon of justice who said: ''If a mule stumbles on the bank of the Euphrates, I fear Allah will question me why I did not pave the road for it.''","ar":"قمة الشعور بالمسؤولية والعدل الراشدي في تاريخ الأمم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_suwar_tabiin_basha', 'صُوَرٌ مِنْ حَيَاةِ التَّابِعِينَ', 'الدُّكْتُورُ عَبْدُ الرَّحْمَنِ رَأْفَتِ البَاشَا (ت: 1406ھ)', 'kharji_kitab', 'tarikh', 'تابعینِ عظام کے ایمان افروز کارنامے', 'کتبِ مطالعہ و تزکیہ (طلبۂ علومِ دینیہ)', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'تابعین کرام کے علم، زہد، خوفِ خدا، اور حکمرانوں کے سامنے کلمۂ حق کہنے کی لرزہ خیز اور شاندار تاریخی داستانیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tabiin_ch1_uwais', 'kharji_suwar_tabiin_basha', 0, 'أُوَيْسٌ القَرَنِيُّ: خَيْرُ التَّابِعِينَ بِإِخْبَارِ الصَّادِقِ المَصْدُوقِ ﷺ', 'باب 1: حضرت اویس قرنی — تابعین کے سب سے بہترین بزرگ اور والہانہ خدمتِ والدہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tabiin_seg_1_1', 'tabiin_ch1_uwais', 'kharji_suwar_tabiin_basha', 0, 'قَالَ الدُّكْتُورُ عَبْدُ الرَّحْمَنِ رَأْفَتِ البَاشَا: «قَالَ رَسُولُ اللَّهِ ﷺ لِعُمَرَ بْنِ الخَطَّابِ: «إِنَّ خَيْرَ التَّابِعِينَ رَجُلٌ يُقَالُ لَهُ أُوَيْسٌ، وَكَانَ بِهِ بَرَصٌ فَبَرَأَ مِنْهُ إِلَّا مَوْضِعَ دِرْهَمٍ، وَلَهُ وَالِدَةٌ هُوَ بِهَا بَرٌّ، لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ؛ فَإِنِ اسْتَطَعْتَ أَنْ يَسْتَغْفِرَ لَكَ فَافْعَلْ!». وَظَلَّ الفَارُوقُ يَتَحَرَّاهُ فِي وُفُودِ أَهْلِ اليَمَنِ حَتَّى لَقِيَهُ فِي مَوْسِمِ الحَجِّ مُرْتَدِياً طِمْرَيْنِ خَلِقَيْنِ لَا يَأْبَهُ لَهُ النَّاسُ، فَسَأَلَهُ أَنْ يَسْتَغْفِرَ لَهُ، ثُمَّ رَغِبَ أُوَيْسٌ فِي الخَفَاءِ فَانْطَلَقَ إِلَى الكُوفَةِ يَكْتَسِبُ قُوتَهُ بِعَرَقِ جَبِينِهِ».', 'ڈاکٹر عبد الرحمن رأفت الباشا فرماتے ہیں: ''رسول اللہ ﷺ نے حضرت عمر بن خطاب سے فرمایا تھا: ''تابعین میں سب سے بہترین شخص ایک مرد ہوگا جسے اویس کہا جاتا ہے، اسے برص کی بیماری تھی جو ایک درہم کے بقدر داغ کے سوا سب ٹھیک ہو گئی، اور اس کی ایک بوڑھی ماں ہے جس کے ساتھ وہ انتہا درجے کا حسن سلوک کرتا ہے؛ وہ اللہ کے ہاں اس قدر مقبول ہے کہ اگر اللہ کے بھروسے پر قسم کھا لے تو اللہ اس کی قسم پوری فرمائے؛ پس اے عمر! اگر تم اس سے اپنے لیے دعائے مغفرت کرا سکو تو ضرور کرانا!'' چنانچہ فاروقِ اعظم یمن کے قافلوں میں برسوں اس کا انتظار کرتے رہے یہاں تک کہ حج کے موقع پر انہیں پا لیا، اس حال میں کہ وہ دو پرانی چادریں اوڑھے ہوئے تھے جنہیں دنیا دار کوئی اہمیت نہ دیتے تھے، حضرت عمر نے ان سے اپنے لیے استغفار کی درخواست کی، پھر حضرت اویس نے شہرت سے بچ کر گمنامی کو ترجیح دی اور کوفہ جا کر اپنی محنت سے روزی کمانے لگے''۔', 'حضرت اویس قرنی کا یہ واقعہ ثابت کرتا ہے کہ اللہ کے ہاں قبولیت کا معیار شاہی محلات یا دنیاوی شہرت نہیں بلکہ خدمتِ والدین، اخلاص اور خاموش للہیت ہے۔', '[{"word":"خَيْرَ","role":"اسم إنّ منصوب","sign":"فتحة","detail":"رجل خبر إنّ مرفوع"},{"word":"بَرٌّ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"والجملة نعت لرجل"}]', '["صور من حياة التابعين، ص 15-26، وأخرجه مسلم (2542)."]', '{"en":"Dr. Raf''at Al-Basha portrays Uwais al-Qarani: The best of the Tabi''in as certified by the Prophet ﷺ. Despite Umar being the mighty Caliph, he sought Uwais''s prayers because of Uwais''s peerless devotion to his mother and total detachment from worldly fame.","ar":"فضل بر الوالدين وإخفاء الصالحات وتجلي الولاية في البساطة والتواضع."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tabiin_ch2_said_musayyib', 'kharji_suwar_tabiin_basha', 1, 'سَعِيدُ بْنُ المُسَيِّبِ: سَيِّدُ التَّابِعِينَ وَعَالِمُ المَدِينَةِ وَالصَّدْعُ بِالحَقِّ', 'باب 2: حضرت سعید بن المسیب — سید التابعین، مدینہ کے سب سے بڑے مفتی اور کلمۂ حق کی بے باکی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tabiin_seg_2_1', 'tabiin_ch2_said_musayyib', 'kharji_suwar_tabiin_basha', 0, '«كَانَ سَعِيدُ بْنُ المُسَيِّبِ سَيِّدَ التَّابِعِينَ عِلْماً وَعَمَلاً؛ مَكَثَ خَمْسِينَ سَنَةً مَا فَاتَتْهُ التَّكْبِيرَةُ الأُولَى فِي مَسْجِدِ رَسُولِ اللَّهِ ﷺ، وَلَا نَظَرَ فِي قَفَا رَجُلٍ فِي الصَّلَاةِ لِمُلَازَمَتِهِ الصَّفَّ الأَوَّلَ. وَخَطَبَ ابْنَتَهُ أَمِيرُ المُؤْمِنِينَ عَبْدُ المَلِكِ بْنُ مَرْوَانَ لِوَلِيِّ عَهْدِهِ الوَلِيدِ، فَأَبَى سَعِيدٌ أَنْ يُزَوِّجَهَا لَهُ، وَزَوَّجَهَا لِطَالِبِ عِلْمٍ فَقِيرٍ مِنْ أَصْحَابِهِ بِدِرْهَمَيْنِ، فَلَمَّا ضُرِبَ بِالسِّيَاطِ لِامْتِنَاعِهِ عَنِ البَيْعَةِ الجَبْرِيَّةِ لَمْ يَلِنْ وَلَمْ يُهَادِنْ».', 'ڈاکٹر باشا فرماتے ہیں: ''حضرت سعید بن المسیب علم و عمل کے اعتبار سے سید التابعین تھے؛ پچاس سال تک مسجدِ نبوی میں ان کی تکبیرِ اولیٰ فوت نہیں ہوئی، اور پہلی صف کی دائمی پابندی کی وجہ سے انہوں نے نماز میں کبھی کسی دوسرے نمازی کی پشت نہیں دیکھی۔ اور جب خلیفہ عبد الملک بن مروان نے اپنے ولی عہد بیٹے ولید بن عبد الملک کے لیے سعید کی بیٹی کا رشتہ مانگا تو حضرت سعید نے بادشاہ کے بیٹے کو رشتہ دینے سے صاف انکار کر دیا، اور اس نیک بیٹی کا نکاح اپنی مجلس کے ایک مفلس طالب علم (ابو وداعہ) سے صرف دو درہم مہر پر کر دیا، اور جب جبری بیعت نہ کرنے پر انہیں سخت کوڑے مارے گئے اور گلیوں میں گھمایا گیا تو تب بھی وہ باطل کے سامنے ذرہ برابر نہ جھکے''۔', 'سعید بن المسیب کی یہ سیرت اہل علم کے لیے مینارۂ نور ہے کہ دنیا کی بڑی سے بڑی پیشکش اور دھمکی بھی ایک باعمل عالم کے ضمیر کا سودا نہیں کر سکتی۔', '[{"word":"سَيِّدَ","role":"خبر كان منصوب","sign":"فتحة","detail":"سعيد اسمها وسيد خبرها وهو مضاف"},{"word":"خَمْسِينَ","role":"ظرف زمان منصوب","sign":"ياء","detail":"ملحق بجمع المذكر السالم"}]', '["صور من حياة التابعين، ص 70-85، وحلية الأولياء 2/ 161."]', '{"en":"Said ibn al-Musayyib: Master of the Tabi''in. For fifty years he never missed the opening Takbir in the Prophet''s Mosque. He rejected the Caliph''s proposal for his daughter to wed the crown prince, choosing instead a destitute pious student for a dowry of two dirhams.","ar":"عزة الإيمان وترجيح التقوى على زهرة الدنيا ومصاهرة الملوك."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tarikh_khulafa_suyuti', 'تَارِيخُ الخُلَفَاءِ', 'الحَافِظُ جَلَالُ الدِّينِ السُّيُوطِيُّ (ت: 911ھ)', 'kharji_kitab', 'tarikh', 'خلفائے راشدین، اموی و عباسی حکمرانوں کی تاریخ', 'کتبِ مطالعہ و تاریخِ خلافتِ اسلامیہ', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'خلافتِ راشدہ سے لے کر عباسی دور کے زوال تک کے تمام خلفاء کی سیاسی تاریخ، عدل و انصاف، فتوحات اور علمی ترقی کا بے لاگ تذکرہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('suyuti_khulafa_ch1_siddiq', 'kharji_tarikh_khulafa_suyuti', 0, 'خِلَافَةُ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ وَحُرُوبُ الرِّدَّةِ', 'باب 1: خلیفۂ اول سیدنا ابوبکر صدیق رضی اللہ عنہ — فتنۂ ارتداد کا خاتمہ اور اسلام کی حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('suyuti_khulafa_seg_1_1', 'suyuti_khulafa_ch1_siddiq', 'kharji_tarikh_khulafa_suyuti', 0, 'قَالَ الحَافِظُ جَلَالُ الدِّينِ السُّيُوطِيُّ: «تَوَلَّى أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ الخِلَافَةَ يَوْمَ السَّقِيفَةِ بِإِجْمَاعِ الصَّحَابَةِ، وَقَامَ خَطِيباً فَقَالَ: «أَمَّا بَعْدُ، أَيُّهَا النَّاسُ، فَإِنِّي قَدْ وُلِّيتُ عَلَيْكُمْ وَلَسْتُ بِخَيْرِكُمْ، فَإِنْ أَحْسَنْتُ فَأَعِينُونِي، وَإِنْ أَسَأْتُ فَقَوِّمُونِي، الصِّدْقُ أَمَانَةٌ وَالكِذْبُ خِيَانَةٌ، وَالقَوِيُّ فِيكُمْ ضَعِيفٌ عِنْدِي حَتَّى آخُذَ الحَقَّ مِنْهُ، وَالضَّعِيفُ فِيكُمْ قَوِيٌّ عِنْدِي حَتَّى آخُذَ الحَقَّ لَهُ». وَلَمَّا ارْتَدَّتِ العَرَبُ قَالَ كَلِمَتَهُ الخَالِدَةَ: «أَيُنْقَصُ الدِّينُ وَأَنَا حَيٌّ؟! وَاللَّهِ لَوْ مَنَعُونِي عِقَالاً كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللَّهِ لَقَاتَلْتُهُمْ عَلَيْهِ».', 'حافظ جلال الدین سیوطی رحمہ اللہ فرماتے ہیں: ''سیدنا ابوبکر صدیق رضی اللہ عنہ سقیفہ بنو ساعدہ میں صحابہ کے اجماع سے خلیفہ بنے، اور منبر پر پہلا خطبہ دیتے ہوئے فرمایا: ''اے لوگو! مجھے تم پر حاکم بنایا گیا ہے حالانکہ میں تم سے بہتر نہیں ہوں، پس اگر میں نیک کام کروں تو میری مدد کرو، اور اگر مجھ سے کوئی کوتاہی ہو تو مجھے سیدھا کر دو؛ سچائی امانت ہے اور جھوٹ خیانت ہے؛ اور تم میں سے جو طاقتور ہے وہ میرے نزدیک اس وقت تک کمزور ہے جب تک میں اس سے حقدار کا حق وصول نہ کر لوں، اور تم میں سے جو کمزور ہے وہ میرے نزدیک طاقتور ہے یہاں تک کہ میں اس کا چھینا ہوا حق اسے واپس نہ دلا دوں''۔ اور جب عرب کے قبائل زکوٰۃ کے منکر ہوئے تو آپ نے وہ لازوال جملہ فرمایا: ''کیا میری زندگی میں دین میں کمی کی جائے گی؟! بخدا! اگر وہ اونٹ باندھنے کی ایک رسی بھی روکیں گے جو وہ رسول اللہ ﷺ کو دیتے تھے تو میں اس پر ان سے جنگ کروں گا!''', 'تاریخ الخلفاء امام سیوطی کی وہ مشہور تاریخی کتاب ہے جس میں انہوں نے خلافت راشدہ، بنو امیہ اور بنو عباس کے خلفاء کے حالات اور سیاسی نشیب و فراز کو جمع کیا ہے۔', '[{"word":"خَطِيباً","role":"حال منصوب","sign":"فتحة","detail":"يبين هيئة أبي بكر عند قيامه"},{"word":"أَمَانَةٌ","role":"خبر المبتدأ الصدق مرفوع","sign":"ضمة","detail":"والكذب خيانة معطوف عليه"}]', '["تاريخ الخلفاء للسيوطي، ص 60-75."]', '{"en":"Imam As-Suyuti records Abu Bakr''s immortal inaugural address: ''The strong amongst you is weak in my sight until I extract justice from him, and the weak amongst you is strong until I secure justice for him.'' His resolute stand against the apostasy wars preserved the integrity of Islam.","ar":"تأسيس معالم الحكم الراشدي الحازم والدفاع عن أركان الإسلام."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('suyuti_khulafa_ch2_farooq', 'kharji_tarikh_khulafa_suyuti', 1, 'خِلَافَةُ عُمَرَ بْنِ الخَطَّابِ: الفُتُوحَاتُ الكُبْرَى وَتَأْسِيسُ الدَّوْلَةِ', 'باب 2: خلیفۂ دوم سیدنا عمر فاروق رضی اللہ عنہ — فتوحاتِ شام و عراق اور اسلامی ریاست کے محکم ادارے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('suyuti_khulafa_seg_2_1', 'suyuti_khulafa_ch2_farooq', 'kharji_tarikh_khulafa_suyuti', 0, '«كَانَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ أَوَّلَ مَنْ سُمِّيَ أَمِيرَ المُؤْمِنِينَ، وَأَوَّلَ مَنْ وَضَعَ التَّارِيخَ الهِجْرِيَّ، وَأَوَّلَ مَنْ دَوَّنَ الدَّوَاوِينَ، وَأَوَّلَ مَنْ عَسَّ بِاللَّيْلِ يَتَفَقَّدُ الرَّعِيَّةَ. فُتِحَتْ فِي عَهْدِهِ مَمَالِكُ كِسْرَى وَقَيْصَرَ، وَمُصِّرَتِ الأَمْصَارُ كَالبَصْرَةِ وَالكُوفَةِ وَالفُسْطَاطِ، وَهُوَ مَعَ ذَلِكَ يَأْكُلُ الخُبْزَ وَالزَّيْتَ وَيَلْبَسُ ثَوْباً فِيهِ اثْنَتَا عَشْرَةَ رُقْعَةً، وَيَقُولُ: «لَوْ مَاتَتْ شَاةٌ عَلَى شَطِّ الفُرَاتِ ضَائِعَةً لَظَنَنْتُ أَنَّ اللَّهَ تَعَالَى سَائِلِي عَنْهَا يَوْمَ القِيَامَةِ»».', 'حافظ سیوطی فرماتے ہیں: ''سیدنا عمر بن خطاب رضی اللہ عنہ پہلے حکمران تھے جنہیں ''امیر المؤمنین'' کا لقب دیا گیا، پہلے شخص تھے جنہوں نے ہجری تقویم کی بنیاد رکھی، پہلے شخص تھے جنہوں نے سرکاری محکمے (دیوان) قائم کیے، اور پہلے حکمران تھے جو راتوں کو گلیوں میں گشت کر کے اپنی رعایا کے دکھ درد کی خبر لیتے تھے۔ ان کے مبارک دور میں قیصر و کسریٰ کی عظیم سلطنتیں فتح ہوئیں، بصرہ، کوفہ اور فسطاط جیسے نئے شہر آباد ہوئے، لیکن اس تمام کروفر کے باوجود آپ کی ذاتی خوراک روٹی اور زیتون کا تیل تھا، اور لباس میں بارہ پیوند لگے ہوتے تھے، اور فرماتے تھے: ''اگر فرات کے کنارے ایک بکری کا بچہ بھی بے یارومددگار مر جائے تو مجھے ڈر ہے کہ قیامت کے دن اللہ عمر سے اس کی بازپرس فرمائے گا''۔', 'عمر بن خطاب کی خلافت دنیا کی تاریخ میں گڈ گورننس، شفافیت اور سادگی کی سب سے شاندار مثال ہے جس پر غیر مسلم مؤرخین بھی انگشت بدنداں ہیں۔', '[{"word":"أَوَّلَ","role":"خبر كان منصوب","sign":"فتحة","detail":"عمر اسمها وأول خبرها"},{"word":"اثْنَتَا","role":"مبتدأ مؤخر مرفوع","sign":"ألف","detail":"ملحق بالمثنى"}]', '["تاريخ الخلفاء للسيوطي، ص 105-125."]', '{"en":"Umar bin Al-Khattab: The first to be called Amir al-Mu''minin, founder of the Hijri calendar, creator of the public treasury registries (Diwan), and pioneer of nightly welfare patrols—conquering Persia and Rome while subsisting on dry bread and patched garments.","ar":"معالم البناء المؤسسي والعدالة الاجتماعية في الدولة العمرية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_mada_khasira_nadwi', 'مَا ذَا خَسِرَ العَالَمُ بِانْحِطَاطِ المُسْلِمِينَ', 'المُفَكِّرُ الإِسْلَامِيُّ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ (ت: 1420ھ)', 'kharji_kitab', 'tarikh', 'فلسفۂ تاریخ و بیداریِ امتِ مسلمہ', 'کتبِ مطالعہ و فکری تربیت (کلاسیکی شاہکار)', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'عصرِ حاضر کی سب سے اثر انگیز فکری و تاریخی کتاب جس نے دنیا کو دکھایا کہ مسلمانوں کے زوال سے انسانیت کا کیا نقصان ہوا اور اسلامی قیادت کا احیاء کیوں ناگزیر ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('mada_khasira_ch1_jahiliyyah', 'kharji_mada_khasira_nadwi', 0, 'العَالَمُ فِي الجَاهِلِيَّةِ قَبْلَ البِعْثَةِ النَّبَوِيَّةِ: رُكُودٌ وَظَلَامٌ', 'باب 1: بعثتِ نبوی سے قبل دنیا کی ابتر حالت — فکری جمود، اخلاقی انحطاط اور روحانی تاریکی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('mada_khasira_seg_1_1', 'mada_khasira_ch1_jahiliyyah', 'kharji_mada_khasira_nadwi', 0, 'قَالَ الإِمَامُ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ: «إِنَّ القَرْنَ السَّادِسَ المِيلَادِيَّ كَانَ يُمَثِّلُ أَحْلَكَ عُصُورِ التَّارِيخِ الإِنْسَانِيِّ؛ كَانَتِ الإِنْسَانِيَّةُ تَتَرَدَّى فِي هُوَّةٍ سَحِيقَةٍ مِنَ الوَثَنِيَّةِ، وَالتَّفَكُّكِ، وَالاسْتِبْدَادِ. فَفِي الرُّومَانِ شَهَوَاتٌ جَامِحَةٌ وَطُغْيَانٌ، وَفِي فَارِسَ مَجُوسِيَّةٌ وَتَأْلِيهٌ لِلْمُلُوكِ، وَفِي الهِنْدِ طَبَقِيَّةٌ قَاتِلَةٌ، وَفِي العَرَبِ عَصَبِيَّةٌ عَمْيَاءُ. نَظَرَ اللَّهُ إِلَى أَهْلِ الأَرْضِ فَمَقَتَهُمْ عَرَبَهُمْ وَعَجَمَهُمْ إِلَّا بَقَايَا مِنْ أَهْلِ الكِتَابِ، حَتَّى انْبَلَجَ صُبْحُ النُّبُوَّةِ بِمُحَمَّدٍ ﷺ فَأَنْقَذَ البَشَرِيَّةَ مِنَ الهَلَاكِ».', 'علامہ ابو الحسن علی ندوی رحمہ اللہ فرماتے ہیں: ''چھٹی صدی عیسوی انسانی تاریخ کے سیاہ ترین ادوار کی عکاس تھی؛ پوری انسانیت بت پرستی، اخلاقی انارکی اور بدترین ظلم و استبداد کی گہری کھائی میں گر چکی تھی۔ رومی سلطنت میں سرکش خواہشات اور جبر تھا، فارس میں آتش پرستی اور بادشاہوں کی خدائی کا ڈھونگ تھا، ہندوستان میں انسان دشمن طبقاتی اونچ نیچ تھی، اور عرب میں اندھی قبائلی عصبیت کا راج تھا۔ اللہ تعالیٰ نے زمین والوں کی طرف دیکھا تو ان سب سے بیزار ہو گیا سوائے چند بچے کھچے اہلِ کتاب کے، یہاں تک کہ محمد مصطفیٰ ﷺ کے ظہور سے نبوت کی صبحِ صادق طلوع ہوئی جس نے انسانیت کو ابدی ہلاکت سے بچا لیا''۔', 'کتاب ''ما ذا خسر العالم بانحطاط المسلمين'' بیسویں صدی کی سب سے زیادہ اثر انگیز اسلامی کتاب سمجھی جاتی ہے جس کا درجنوں زبانوں میں ترجمہ ہوا اور اس نے اسلامی بیداری کی نئی بنیاد رکھی۔', '[{"word":"أَحْلَكَ","role":"مفعول به ليمثل منصوب","sign":"فتحة","detail":"وهو مضاف وعصور مضاف إليه"},{"word":"بَقَايَا","role":"مستثنى منصوب","sign":"فتحة مقدرة","detail":"استثناء تام موجب"}]', '["ماذا خسر العالم بانحطاط المسلمين، ص 25-38، دار القلم."]', '{"en":"Allama Nadwi''s masterwork: The 6th century represented humanity''s darkest epoch—Rome was paralyzed by decadence, Persia by royal deification, India by oppressive casteism, and Arabia by blind tribal bloodlust, until the dawn of Prophethood rescued mankind.","ar":"تشخيص الواقع العالمي الكئيب قبيل البعثة المحمدية وبيان ضرورة الرسالة الإلهية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('mada_khasira_ch2_inhetat', 'kharji_mada_khasira_nadwi', 1, 'انْحِطَاطُ المُسْلِمِينَ وَانْتِقَالُ القِيَادَةِ إِلَى الغَرْبِ المَادِّيِّ: الخَسَارَةُ الفَادِحَةُ', 'باب 2: مسلمانوں کا زوال اور عالمی قیادت کا مادہ پرست مغرب کے ہاتھ جانا — انسانیت کا سب سے بڑا المیہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('mada_khasira_seg_2_1', 'mada_khasira_ch2_inhetat', 'kharji_mada_khasira_nadwi', 0, '«لَمْ تَكُنْ خَسَارَةُ انْحِطَاطِ المُسْلِمِينَ خَسَارَةً لَهُمْ وَحْدَهُمْ، بَلْ كَانَتْ كَارِثَةً عَامَّةً أَصَابَتِ الإِنْسَانِيَّةَ جَمْعَاءَ؛ فَقَدْ نُزِعَتْ قِيَادَةُ العَالَمِ مِنْ يَدِ أُمَّةٍ تَقُودُهُ بِالقُرْآنِ وَالعَدْلِ وَالرَّحْمَةِ، وَوُضِعَتْ فِي يَدِ أُمَّةٍ مَادِّيَّةٍ أَعْمَاهَا الغُرُورُ العِلْمِيُّ وَتَجَرَّدَتْ مِنَ الإِيمَانِ وَالأَخْلَاقِ. فَأَصْبَحَ العَالَمُ كَمَجْنُونٍ فِي يَدِهِ سِلَاحٌ فَارِهٌ، يَقْدِرُ عَلَى تَدْمِيرِ الحَضَارَةِ وَلَا يَقْدِرُ عَلَى إِسْعَادِ قَلْبِ الإِنْسَانِ».', 'علامہ ندوی فرماتے ہیں: ''مسلمانوں کے زوال اور پسماندگی کا نقصان صرف مسلمانوں کی اپنی ذات تک محدود نہ تھا، بلکہ یہ ایک ایسا عالمگیر المیہ تھا جس نے پوری نوعِ انسانی کو اپنی لپیٹ میں لے لیا؛ کیونکہ دنیا کی قیادت و امامت اس امت کے ہاتھ سے چھن گئی جو قرآن، عدل اور رحمت کے ساتھ دنیا کی رہنمائی کرتی تھی، اور وہ قیادت ایسی مادہ پرست مغربی تہذیب کے ہاتھ میں چلی گئی جس کو سائنسی غرور نے اندھا کر دیا تھا اور وہ ایمان اور اخلاقیات سے بالکلیہ محروم تھی۔ چنانچہ آج دنیا کی حالت اس پاگل اور دیوانے شخص کی طرح ہو گئی ہے جس کے ہاتھ میں مہلک ترین ایٹمی ہتھیار تو موجود ہیں جس سے وہ دنیا کو پلک جھپکتے میں راکھ کا ڈھیر تو بنا سکتا ہے مگر انسان کے تڑپتے دل کو سکون اور خوشی عطا کرنے کی اس میں کوئی صلاحیت نہیں ہے''۔', 'یہ درد مندانہ تجزیہ بتاتا ہے کہ امتِ مسلمہ کا وجود صرف اپنے لیے نہیں بلکہ پوری دنیا کو تباہی سے بچانے اور عدل و رحمت کا سایہ فراہم کرنے کے لیے ناگزیر ہے۔', '[{"word":"خَسَارَةً","role":"خبر كان منصوب","sign":"فتحة","detail":"خسارة الأولى اسمها وخسارة الثانية خبرها"},{"word":"سِلَاحٌ","role":"مبتدأ مؤخر مرفوع","sign":"ضمة","detail":"في يده خبر مقدم"}]', '["ماذا خسر العالم بانحطاط المسلمين، ص 190-205."]', '{"en":"Nadwi''s thesis: The decline of Muslims was a catastrophic tragedy for all humanity. Global leadership transitioned from a civilization anchored in divine justice and moral restraint to a materialistic civilization armed with immense technological power but spiritually bankrupt.","ar":"تحليل أبعاد المأساة الإنسانية الناتجة عن سيادة المادية وفقدان التوجيه الرباني."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_hilyat_awliya_asbahani', 'حِلْيَةُ الأَوْلِيَاءِ وَطَبَقَاتُ الأَصْفِيَاءِ', 'الحَافِظُ أَبُو نُعَيْمٍ أَحْمَدُ بْنُ عَبْدِ اللَّهِ الأَصْبَهَانِيُّ (ت: 430ھ)', 'kharji_kitab', 'tarikh', 'سوانحِ صلحاء، اتقیاء و زہادِ امت', 'کتبِ مطالعہ و تزکیۂ باطن', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'اصحابِ صفہ، تابعین، اور ائمۂ سلف کے زہد، عبادت، اخلاص اور کرامات کا مستند انسائیکلوپیڈیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hilyah_ch1_suffah', 'kharji_hilyat_awliya_asbahani', 0, 'أَهْلُ الصُّفَّةِ فِي مَسْجِدِ رَسُولِ اللَّهِ ﷺ: عُبَّادُ اللَّيْلِ وَفُرْسَانُ العِلْمِ', 'باب 1: اصحابِ صفہ رضی اللہ عنہم — مسجدِ نبوی کے درویش، شب بیدار اور علم و معرفت کے ستارے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hilyah_seg_1_1', 'hilyah_ch1_suffah', 'kharji_hilyat_awliya_asbahani', 0, 'قَالَ الحَافِظُ أَبُو نُعَيْمٍ الأَصْبَهَانِيُّ: «أَهْلُ الصُّفَّةِ هُمْ أَوْلِيَاءُ اللَّهِ الَّذِينَ انْقَطَعُوا إِلَى رَسُولِهِ ﷺ فِي مَسْجِدِهِ، لَا يَشْغَلُهُمْ بَيْعٌ وَلَا تِجَارَةٌ، صَبَرُوا عَلَى لَأْوَاءِ العَيْشِ وَشِدَّةِ الجُوعِ؛ حَتَّى كَانَ أَحَدُهُمْ يَخِرُّ مِنَ الجُوعِ فِي الصَّلَاةِ فَيَحْسَبُهُ الأَعْرَابِيُّ مَجْنُوناً، وَمَا هُوَ بِمَجْنُونٍ وَلَكِنَّهُ الجُوعُ! وَكَانَ رَسُولُ اللَّهِ ﷺ يَجْلِسُ مَعَهُمْ وَيُؤَانِسُهُمْ وَيَقُولُ: «لَوْ تَعْلَمُونَ مَا لَكُمْ عِنْدَ اللَّهِ لَأَحْبَبْتُمْ أَنْ تَزْدَادُوا فَاقَةً وَحَاجَةً».', 'حافظ ابو نعیم اصبہانی رحمہ اللہ فرماتے ہیں: ''اصحابِ صفہ اللہ کے وہ برگزیدہ اولیاء تھے جنہوں نے مسجدِ نبوی میں رسول اللہ ﷺ کی صحبت کے لیے اپنے آپ کو دنیا سے فارغ کر لیا تھا، انہیں نہ تجارت غافل کرتی تھی نہ دنیاوی دھندے؛ انہوں نے تنگیِ معیشت اور بھوک کی شدت پر ایسا بے مثال صبر کیا کہ ان میں سے کوئی بھوک کی کمزوری سے نماز میں گر پڑتا تو نادان بدو اسے پاگل سمجھ بیٹھتا، حالانکہ وہ پاگل نہیں تھا بلکہ بھوک کی شدت تھی! اور رسول اللہ ﷺ خود ان کی مجلس میں تشریف فرما ہوتے، ان کی دلجوئی فرماتے اور ارشاد فرماتے تھے: ''اگر تمہیں معلوم ہو جائے کہ اللہ کے ہاں تمہارے لیے کیا درجات تیار ہیں تو تم چاہو گے کہ تمہاری محتاجی اور فاقہ کشی میں اور اضافہ ہو جائے!''', 'حلية الأولياء وطبقات الأصفياء زہد، تصوف اور سیرتِ صلحاء کی تاریخ کا سب سے ضخیم انسائیکلوپیڈیا ہے جس میں ابو نعیم نے صحابہ سے لے کر ائمہ تک کے روحانی احوال بسند جمع کیے ہیں۔', '[{"word":"أَوْلِيَاءُ","role":"خبر المبتدأ هم مرفوع","sign":"ضمة","detail":"أهل مبتدأ وهم ضمير فصل وأولياء خبر"},{"word":"فَاقَةً","role":"تمييز منصوب","sign":"فتحة","detail":"محول عن الفاعل"}]', '["حلية الأولياء لأبي نعيم، 1/ 338-345، وأخرجه الترمذي (2368)."]', '{"en":"Abu Nu''aym details Ahl as-Suffah: The destitute spiritual ascetics of the Prophet''s Mosque who endured searing poverty to dedicate their lives entirely to Quranic learning and devotions, receiving intimate prophetic companionship.","ar":"مناقب أهل الصفة والصبر على الفاقة في سبيل تحصيل العلم والعبادة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hilyah_ch2_fudayl', 'kharji_hilyat_awliya_asbahani', 1, 'الفُضَيْلُ بْنُ عِيَاضٍ: عَابِدُ الحَرَمَيْنِ وَمَقَامُ الخَوْفِ وَالبُكَاءِ', 'باب 2: حضرت فضیل بن عیاض — عابدِ حرمین، خشیتِ الٰہی اور خلوص کا بے مثال نمونہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hilyah_seg_2_1', 'hilyah_ch2_fudayl', 'kharji_hilyat_awliya_asbahani', 0, '«كَانَ الفُضَيْلُ بْنُ عِيَاضٍ يَقُولُ: «تَرْكُ العَمَلِ مِنْ أَجْلِ النَّاسِ رِيَاءٌ، وَالعَمَلُ مِنْ أَجْلِ النَّاسِ شِرْكٌ، وَالإِخْلَاصُ أَنْ يُعَافِيَكَ اللَّهُ مِنْهُمَا». وَدَخَلَ عَلَيْهِ هَارُونُ الرَّشِيدُ فَقَالَ لَهُ الفُضَيْلُ: يَا حَسَنَ الوَجْهِ، أَنْتَ الَّذِي اسْتَرْعَاكَ اللَّهُ عَلَى هَذِهِ الأُمَّةِ، فَلَوْ سُئِلْتَ يَوْمَ القِيَامَةِ عَنْ عَنَاقٍ تَعْثُرُ فِي أَقْصَى بِلَادِكَ لَخَشِيتُ أَنْ يُؤْخَذَ بِهَا عُنُقُكَ، فَبَكَى الرَّشِيدُ حَتَّى اخْضَلَّتْ لِحْيَتُهُ».', 'حافظ ابو نعیم فرماتے ہیں: ''حضرت فضیل بن عیاض رحمہ اللہ فرمایا کرتے تھے: ''لوگوں کے ڈر یا ملامت سے نیک کام کو چھوڑ دینا ریاکاری ہے، اور لوگوں کو دکھانے کے لیے عمل کرنا شرک ہے، اور سچا اخلاص یہ ہے کہ اللہ تجھے ان دونوں بیماریوں سے سلامت اور محفوظ رکھے''۔ اور ایک مرتبہ عباسی خلیفہ ہارون الرشید ان کی خدمت میں حاضر ہوا تو حضرت فضیل نے اسے نصیحت کرتے ہوئے فرمایا: ''اے خوبصورت چہرے والے! تو وہ شخص ہے جسے اللہ نے اس پوری امت کی حفاظت سونپی ہے، پس اگر قیامت کے دن تجھ سے تیری قلمرو کے آخری کنارے پر ٹھوکر کھانے والی ایک بکری کے بچے کے بارے میں بھی سوال ہو گیا تو مجھے اندیشہ ہے کہ تیری گردن پکڑ لی جائے گی!'' یہ سن کر ہارون الرشید اس قدر رویا کہ اس کی داڑھی آنسوؤں سے تر ہو گئی''۔', 'حضرت فضیل بن عیاض زہد اور اخلاص کے امام تھے۔ ان کا یہ قول ریاکاری کے دونوں پہلوؤں (کرنا یا چھوڑنا) کو مٹا کر خالص للہیت قائم کرنے کی بنیاد ہے۔', '[{"word":"رِيَاءٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"ترك مبتدأ وهو مضاف ورياء خبره"},{"word":"عُنُقُكَ","role":"نائب فاعل ليؤخذ مرفوع","sign":"ضمة","detail":"وهو مضاف والكاف مضاف إليه"}]', '["حلية الأولياء، ترجمة الفضيل بن عياض، 8/ 84-95."]', '{"en":"Al-Fudayl ibn ''Iyad''s famous aphorism: ''Abandoning a deed for the sake of people is ostentation (Riya''), doing a deed for people is polytheism (Shirk), and sincerity is that Allah preserves you from both.'' His fearless counsel moved Caliph Harun al-Rashid to tears.","ar":"حقيقة الإخلاص الصادق وموعظة الحكام بلسان التقوى والتذكير بالآخرة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_wafa_wafa_samhudi', 'وَفَاءُ الوَفَا بِأَخْبَارِ دَارِ المُصْطَفَى ﷺ', 'الإِمَامُ عَلِيُّ بْنُ عَبْدِ اللَّهِ السَّمْهُودِيُّ (ت: 911ھ)', 'kharji_kitab', 'seerah', 'تاریخِ مدینہ منورہ و معالمِ نبویہ', 'کتبِ مطالعہ و جغرافیۂ سیرت', NULL, NULL, 'from-emerald-950 via-teal-900 to-stone-900', NULL, 'مدینہ منورہ، مسجدِ نبوی، حجرۂ مبارکہ، اور سیرتِ نبوی کے تمام تاریخی مقامات کی جامع ترین دستاویزی تاریخ۔', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wafa_ch1_fadl_madinah', 'kharji_wafa_wafa_samhudi', 0, 'فَضْلُ المَدِينَةِ المُنَوَّرَةِ وَحُرْمَتُهَا وَمَسْجِدِهَا الشَّرِيفِ', 'باب 1: مدینہ منورہ کا تقدس، حرمت اور روضۂ اقدس کی زیارت کے آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wafa_seg_1_1', 'wafa_ch1_fadl_madinah', 'kharji_wafa_wafa_samhudi', 0, 'قَالَ الإِمَامُ عَلِيُّ بْنُ عَبْدِ اللَّهِ السَّمْهُودِيُّ: «المَدِينَةُ طَيْبَةُ وَطَابَةُ، حَرَّمَهَا رَسُولُ اللَّهِ ﷺ كَمَا حَرَّمَ إِبْرَاهِيمُ مَكَّةَ، وَقَالَ ﷺ: صَلَاةٌ فِي مَسْجِدِي هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا المَسْجِدَ الحَرَامَ، وَمَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الجَنَّةِ».', 'امام نور الدین علی السمہودی رحمہ اللہ فرماتے ہیں: ''مدینہ منورہ طیبہ اور طابہ ہے، اسے رسول اللہ ﷺ نے اسی طرح حرم قرار دیا جس طرح حضرت ابراہیم نے مکہ کو حرم بنایا تھا۔ اور آپ ﷺ نے فرمایا: میری اس مسجد میں ایک نماز دوسری مسجدوں کی ہزار نمازوں سے افضل ہے سوائے مسجدِ حرام کے؛ اور جو جگہ میرے حجرے اور میرے منبر کے درمیان ہے وہ جنت کے باغوں میں سے ایک باغ ہے!''', 'وفاء الوفا مدینہ منورہ اور مسجدِ نبوی کی تاریخ کا سب سے جامع اور مستند ترین انسائیکلوپیڈیا ہے جو ہر عاشقِ رسول کے لیے مشعلِ راہ ہے۔', '[{"word":"رَوْضَةٌ","role":"خبر المبتدأ","sign":"ضمة","detail":"ما موصولة مبتدأ وروضة خبرها"}]', '["وفاء الوفا بأخبار دار المصطفى، متفق عليه."]', '{"en":"Imam Al-Samhudi documents the sacred sanctuary of Madinah: A prayer in the Prophet''s Mosque equals 1,000 prayers elsewhere, and the Rawdah is a garden from Paradise.","ar":"تاريخ وفضل مدينة رسول الله ﷺ ومسجده المبارك."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_madarij_salikin', 'مَدَارِجُ السَّالِكِينَ بَيْنَ مَنَازِلِ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'tazkiyah', 'سلوک و احسان، معرفتِ الٰہی و مقاماتِ باطنیہ', 'کتبِ مطالعہ و تصوفِ سنی', NULL, NULL, 'from-teal-950 via-emerald-950 to-stone-900', NULL, 'تزکیۂ نفس، اخلاص، توبہ، انابت، صبر اور شکر کی روحانی منزلوں کا قرآن و سنت کی روشنی میں بے مثال بیان۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('madarij_ch1_iyyaka_nabudu', 'kharji_madarij_salikin', 0, 'مَنْزِلَةُ «إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ»: قُطْبُ رَحَى العُبُودِيَّةِ', 'باب 1: ''ایاک نعبد و ایاک نستعین'' کی منزل — اخلاص، توحید اور عاجزی کا کمال');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('madarij_seg_1_1', 'madarij_ch1_iyyaka_nabudu', 'kharji_madarij_salikin', 0, 'قَالَ الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ: «فَاتِحَةُ الكِتَابِ هِيَ أُمُّ القُرْآنِ، وَسِرُّ الفَاتِحَةِ فِي قَوْلِهِ: {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ}. فَـ {إِيَّاكَ نَعْبُدُ}: بَرَاءَةٌ مِنَ الشِّرْكِ وَالرِّيَاءِ، وَ{إِيَّاكَ نَسْتَعِينُ}: بَرَاءَةٌ مِنَ الحَوْلِ وَالقُوَّةِ وَالتَّفْوِيضِ إِلَى اللَّهِ. فَالقَلْبُ يَعْرِضُ لَهُ مَرَضَانِ عَظِيمَانِ: الرِّيَاءُ وَالكِبْرُ؛ فَدَوَاءُ الرِّيَاءِ بـِ {إِيَّاكَ نَعْبُدُ}، وَدَوَاءُ الكِبْرِ وَالعُجْبِ بـِ {إِيَّاكَ نَسْتَعِينُ}. فَمَنْ تَحَقَّقَ بِهِمَا كَمُلَتْ عُبُودِيَّتُهُ وَنَالَ خَيْرَيِ الدُّنْيَا وَالآخِرَةِ».', 'امام شمس الدین ابن قیم الجوزیہ رحمہ اللہ فرماتے ہیں: ''سورۃ الفاتحہ پورے قرآن کی اصل بنیاد ہے، اور سورۃ الفاتحہ کا سب سے بڑا راز اللہ کے اس فرمان میں پوشیدہ ہے: {ہم صرف تیری ہی عبادت کرتے ہیں اور صرف تجھ ہی سے مدد مانگتے ہیں}۔ پس {ہم تیری ہی عبادت کرتے ہیں}: ہر قسم کے شرک اور دکھاوے سے مکمل برأت و بیزاری کا اعلان ہے؛ اور {تجھ ہی سے مدد مانگتے ہیں}: اپنی ذاتی طاقت و قوت سے دستبردار ہو کر تمام معاملات کو اللہ کے سپرد کرنے کا نام ہے۔ اور انسانی دل کو دو مہلک بیماریاں لاحق ہوتی ہیں: ریاکاری اور تکبر؛ پس ریاکاری کا شافی علاج {إِيَّاكَ نَعْبُدُ} میں ہے، اور تکبر و خود پسندی کا علاج {إِيَّاكَ نَسْتَعِينُ} میں ہے۔ پس جو بندہ ان دونوں حقیقتوں کو پا لے اس کی بندگی مکمل ہو گئی اور وہ دونوں جہانوں کی بھلائی حاصل کر لے گا''۔', 'مدارج السالكين امام ابن قیم کی تزکیۂ نفس اور روحانی منازل کی سب سے گہری تصنیف ہے۔ شیخ عبد اللہ انصاری ہروی کی منازل السائرین کی یہ ایسی شرح ہے جس نے سلوک و تصوف کو سنتِ نبوی کے تابع کر دیا۔', '[{"word":"إِيَّاكَ","role":"ضمير منفصل في محل نصب مفعول به مقدم","sign":"مبني","detail":"يفيد الحصر والاختصاص"},{"word":"بَرَاءَةٌ","role":"خبر المبتدأ إياك نعبد","sign":"ضمة","detail":"يبين المعنى العقدي"}]', '["مدارج السالكين بين منازل إياك نعبد وإياك نستعين، 1/ 78-86."]', '{"en":"Ibn al-Qayyim''s magnum opus: The core of the Quran resides in Surah Al-Fatihah, whose pinnacle is ''You alone we worship, and You alone we ask for help.'' The first half cures ostentation (Riya''), while the second cures pride and arrogance (Kibr).","ar":"تحقيق سر الفاتحة وشفاء القلوب من مرضي الرياء والكبر."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('madarij_ch2_tawbah', 'kharji_madarij_salikin', 1, 'مَنْزِلَةُ التَّوْبَةِ: أَوَّلُ مَنَازِلِ السَّالِكِينَ وَأَوْسَطُهَا وَآخِرُهَا', 'باب 2: منزلِ توبہ — سالک کی راہ کی پہلی، درمیانی اور آخری پناہ گاہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('madarij_seg_2_1', 'madarij_ch2_tawbah', 'kharji_madarij_salikin', 0, '«التَّوْبَةُ هِيَ: الرُّجُوعُ مِمَّا يَكْرَهُهُ اللَّهُ ظَاهِراً وَبَاطِناً إِلَى مَا يُحِبُّهُ ظَاهِراً وَبَاطِناً. وَلَيْسَتِ التَّوْبَةُ مَنْزِلَةً يَبْتَدِئُ بِهَا السَّالِكُ ثُمَّ يُفَارِقُهَا إِلَى غَيْرِهَا، بَلْ هِيَ مَنْزِلَةٌ تَبْدَأُ مَعَهُ وَتَصْحَبُهُ إِلَى المَمَاتِ؛ وَلِذَلِكَ كَانَ رَسُولُ اللَّهِ ﷺ وَهُوَ المَغْفُورُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ يَقُولُ: «يَا أَيُّهَا النَّاسُ، تُوبُوا إِلَى اللَّهِ؛ فَإِنِّي أَتُوبُ فِي اليَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ». وَأَرْكَانُهَا ثَلَاثَةٌ: النَّدَمُ عَلَى مَا مَضَى، وَالإِقْلَاعُ عَنِ الذَّنْبِ فِي الحَالِ، وَالعَزْمُ الجَازِمُ عَلَى أَلَّا يَعُودَ أَبَداً».', 'ابن قیم رحمہ اللہ فرماتے ہیں: ''توبہ سے مراد یہ ہے کہ انسان ان تمام باتوں سے جنہیں اللہ ناپسند فرماتا ہے (ظاہری ہوں یا باطنی) لوٹ کر ان باتوں کی طرف آ جائے جن سے اللہ محبت فرماتا ہے۔ اور توبہ کوئی ایسی منزل نہیں کہ سالک صرف آغاز میں اس سے گزرے اور پھر اسے چھوڑ کر آگے بڑھ جائے، بلکہ یہ وہ منزل ہے جو انسان کے ساتھ شروع ہوتی ہے اور موت تک اس کے ساتھ سفر کرتی ہے؛ اسی لیے رسول اللہ ﷺ جن کے اگلے اور پچھلے تمام گناہ معاف تھے وہ بھی فرمایا کرتے تھے: ''اے لوگو! اللہ کے حضور توبہ کرو، کیونکہ میں دن میں سو مرتبہ اللہ کے حضور توبہ کرتا ہوں''۔ اور توبہ کے تین بنیادی ارکان ہیں: پچھلے گناہ پر سچے دل سے نادم ہونا، اس گناہ کو فوراً چھوڑ دینا، اور آئندہ کبھی اس کے قریب نہ جانے کا پختہ عزم کرنا''۔', 'توبہ بندگی کا کمال ہے۔ انسان جتنا اللہ کے قریب ہوتا ہے اتنا ہی اپنی کوتاہیوں کا احساس بڑھتا ہے، اس لیے رسول اللہ ﷺ سب سے زیادہ توبہ و استغفار فرماتے تھے۔', '[{"word":"الرُّجُوعُ","role":"خبر المبتدأ التوبة مرفوع","sign":"ضمة","detail":"هي ضمير فصل والرجوع خبر"},{"word":"مِائَةَ","role":"نائب عن المفعول المطلق منصوب","sign":"فتحة","detail":"يبين عدد مرات التوبة"}]', '["مدارج السالكين، فصل: منزلة التوبة، 1/ 175-190، وأخرجه مسلم (2702)."]', '{"en":"The Station of Tawbah (Repentance): Turning from all that Allah detests internally and externally to all that He loves. It is not an elementary phase discarded later, but a lifelong companion—the Prophet ﷺ repented 100 times daily.","ar":"حقيقة التوبة النصوح وشروطها ودوام لزومها للعبد حتى يلقى ربه."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ihya_ulum_din', 'إِحْيَاءُ عُلُومِ الدِّينِ', 'حُجَّةُ الإِسْلَامِ أَبُو حَامِدٍ الغَزَالِيُّ (ت: 505ھ)', 'kharji_kitab', 'tazkiyah', 'تزکیۂ باطن، اسرارِ عبادات و اخلاق', 'کتبِ مطالعہ و تہذیبِ اخلاق', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'عبادات، عادات، مہلکات اور منجیات کا روحانی و اخلاقی تجزیہ۔ امتِ اسلامیہ کی سب سے مشہور اخلاقی کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ihya_ch1_ilm', 'kharji_ihya_ulum_din', 0, 'كِتَابُ العِلْمِ: آفَاتُ عُلَمَاءِ السُّوءِ وَعَلَامَاتُ عُلَمَاءِ الآخِرَةِ', 'باب 1: کتاب العلم — علمائے سوء کے فتنے اور علمائے آخرت کی حقیقی نشانیاں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ihya_seg_1_1', 'ihya_ch1_ilm', 'kharji_ihya_ulum_din', 0, 'قَالَ حُجَّةُ الإِسْلَامِ الإِمَامُ أَبُو حَامِدٍ الغَزَالِيُّ: «فَرَّقَ اللَّهُ تَعَالَى بَيْنَ عُلَمَاءِ الدُّنْيَا وَعُلَمَاءِ الآخِرَةِ: فَعُلَمَاءُ السُّوءِ قَصْدُهُمْ مِنَ العِلْمِ التَّنَعُّمُ بِالدُّنْيَا وَالتَّوَصُّلُ إِلَى الجَاهِ عِنْدَ المُلُوكِ، يَبِيعُونَ الدِّينَ بِالعَرَضِ الزَّائِلِ. أَمَّا عُلَمَاءُ الآخِرَةِ فَلَهُمْ عَلَامَاتٌ: أَنْ لَا يَطْلُبُوا بِعِلْمِهِمْ مَالاً وَلَا جَاهاً، وَأَنْ يَكُونَ فِعْلُهُمْ غَيْرَ مُنَاقِضٍ لِقَوْلِهِمْ، وَأَنْ يَكُونَ هَمُّهُمْ عِلْمَ البَاطِنِ وَمُرَاقَبَةَ القَلْبِ، وَأَنْ يَكُونُوا شَدِيدِي التَّوَقِّي لِلشُّبُهَاتِ وَمُجَانَبَةِ السَّلَاطِينِ، كَمَا قَالَ سُفْيَانُ الثَّوْرِيُّ: «إِذَا رَأَيْتَ العَالِمَ يُكْثِرُ الدُّخُولَ عَلَى المُلُوكِ فَاعْلَمْ أَنَّهُ لِصٌّ!».', 'حجۃ الاسلام امام غزالی رحمہ اللہ فرماتے ہیں: ''اللہ تعالیٰ نے دنیا پرست علماء اور علمائے آخرت کے درمیان واضح فرق بیان فرمایا ہے: پس علمائے سوء کا مقصد علم سے دنیاوی عیش و عشرت، بادشاہوں کی دہلیز پر رسوخ اور عزت حاصل کرنا ہوتا ہے، وہ ناپائیدار دنیا کے بدلے دین کو بیچ ڈالتے ہیں۔ جبکہ علمائے آخرت کی روشن نشانیاں یہ ہیں: وہ اپنے علم کے بدلے نہ مال مانگتے ہیں نہ عہدہ و جاہ، ان کا عمل ان کے قول کے کبھی متضاد نہیں ہوتا، ان کی اصل فکر باطن کی اصلاح اور دل کی نگرانی ہوتی ہے، اور وہ شبہات سے انتہا درجے کا پرہیز کرنے والے اور حکمرانوں کے درباروں سے دور بھاگنے والے ہوتے ہیں؛ جیسا کہ سفیان ثوری رحمہ اللہ نے فرمایا: ''جب تم کسی عالم کو بادشاہوں کی دہلیز پر بار بار حاضری دیتے دیکھو تو جان لو کہ وہ چور اور راہزن ہے!''', 'إحياء علوم الدين امام غزالی کا وہ شاہکار ہے جس نے اسلامی تاریخ کے دھارے کو بدل کر رکھ دیا۔ امام غزالی نے علمائے سوء کو امت کا سب سے بڑا ناسور قرار دیا کیونکہ وہ باطل کو فتووں کا غلاف پہناتے ہیں۔', '[{"word":"قَصْدُهُمْ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"وهو مضاف والتنعم خبر المبتدأ"},{"word":"لِصٌّ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"والهاء اسمها"}]', '["إحياء علوم الدين للغزالي، كتاب العلم، 1/ 58-75، دار المعرفة."]', '{"en":"Imam Al-Ghazali''s foundational treatise on Knowledge: Contrasting corrupt worldly scholars (''Ulama as-Su'') who trade faith for royal favors with scholars of the Hereafter who embody congruence between speech and action, heart vigilance, and detachment from power.","ar":"التمييز الجوهري بين علماء الآخرة الربانيين وعلماء السوء المتكسبين بالدين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ihya_ch2_muhasabah', 'kharji_ihya_ulum_din', 1, 'كِتَابُ المُرَاقَبَةِ وَالمُحَاسَبَةِ: مَرَاتِبُ المُرَابَطَةِ السِّتَّةِ', 'باب 2: کتاب المراقبہ و المحاسبہ — اپنے نفس سے نمٹنے کے چھ مراحل (مشارطہ، مراقبہ، محاسبہ، معاقبہ، مجاہدہ، معاتبہ)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ihya_seg_2_1', 'ihya_ch2_muhasabah', 'kharji_ihya_ulum_din', 0, '«اعْلَمْ أَنَّ التَّاجِرَ فِي الدُّنْيَا لَا يَتِمُّ لَهُ رِبْحٌ إِلَّا بِمُحَاسَبَةِ شَرِيكِهِ، وَكَذَلِكَ العَبْدُ الكَيِّسُ يَجِبُ أَنْ يُحَاسِبَ نَفْسَهُ فِي سَفَرِ الآخِرَةِ عَلَى سِتِّ مَقَامَاتٍ: المَقَامُ الأَوَّلُ: المُشَارَطَةُ، وَهِيَ أَنْ يَشْتَرِطَ عَلَى نَفْسِهِ عِنْدَ الصَّبَاحِ حِفْظَ الجَوَارِحِ وَالطَّاعَاتِ. المَقَامُ الثَّانِي: المُرَاقَبَةُ، وَهِيَ اسْتِحْضَارُ نَظَرِ اللَّهِ إِلَيْهِ فِي كُلِّ حَرَكَةٍ. المَقَامُ الثَّالِثُ: المُحَاسَبَةُ بَعْدَ العَمَلِ عِنْدَ النَّوْمِ. المَقَامُ الرَّابِعُ: المُعَاقَبَةُ لِلنَّفْسِ عَلَى تَقْصِيرِهَا بِالصِّيَامِ وَالصَّدَقَةِ. المَقَامُ الخَامِسُ: المُجَاهَدَةُ بِإِلْزَامِهَا مَا يَثْقُلُ عَلَيْهَا. المَقَامُ السَّادِسُ: المُعَاتَبَةُ وَتَوْبِيخُ النَّفْسِ عَلَى غَفْلَتِهَا».', 'امام غزالی فرماتے ہیں: ''جان لو کہ دنیا کا کوئی تاجر اپنے کاروباری شریک سے پائی پائی کا حساب لیے بغیر نفع نہیں کما سکتا، بالکل اسی طرح آخرت کے مسافر عقلمند انسان پر لازم ہے کہ وہ اپنے نفس کے ساتھ چھ مرحلوں میں حساب کتاب رکھے: پہلا مرحلہ ''مشارطہ'' (شرط لگانا) ہے کہ وہ ہر صبح اٹھ کر اپنے نفس کو گناہوں سے بچنے اور فرائض کی پابندی کی سخت تاکید کرے۔ دوسرا مرحلہ ''مراقبہ'' ہے کہ ہر حرکت و عمل میں یہ سوچے کہ اللہ مجھے دیکھ رہا ہے۔ تیسرا مرحلہ ''محاسبہ'' ہے کہ رات کو سونے سے پہلے دن بھر کی ایک ایک حرکت کا جائزہ لے۔ چوتھا مرحلہ ''معاقبہ'' ہے کہ جب نفس سے خطا ہو تو اسے نفل روزوں اور صدقے سے سزا دے۔ پانچواں مرحلہ ''مجاہدہ'' ہے کہ نفس پر وزنی عبادات لازم کرے۔ اور چھٹا مرحلہ ''معاتبہ'' ہے کہ نفس کو اس کی غفلت پر ڈانٹے اور ملامت کرے''۔', 'یہ چھ مراحل اسلامی سائیکالوجی اور تزکیۂ نفس کا کامل خاکہ ہیں جس کے ذریعے انسان اپنی بد اخلاقیوں پر قابو پا کر ولایت کے اعلیٰ مقام تک پہنچ سکتا ہے۔', '[{"word":"المُشَارَطَةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"المقام مبتدأ وألغيت النعتية والمشارطة خبر"},{"word":"شَرِيكِهِ","role":"مضاف إليه مجرور","sign":"كسرة","detail":"محاسبة مضاف وشريك مضاف إليه"}]', '["إحياء علوم الدين، ربع المنجيات: كتاب المراقبة والمحاسبة، 4/ 394-406."]', '{"en":"The Six Stations of Spiritual Accounting (Murabatah): 1. Musharatah (morning covenant setting conditions), 2. Muraqabah (vigilant presence of Allah''s gaze), 3. Muhasabah (nightly audit of deeds), 4. Mu''aqabah (penalizing the ego via extra devotions), 5. Mujahadah (struggling against impulses), 6. Mu''atabah (reproaching oneself).","ar":"المنهج المتكامل لترويض النفس وتزكيتها وضبط سلوكها الإيماني."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_daa_dawaa_jawziyyah', 'الدَّاءُ وَالدَّوَاءُ (الجَوَابُ الكَافِي لِمَنْ سَأَلَ عَنِ الدَّوَاءِ الشَّافِي)', 'الإِمَامُ شَمْسُ الدِّينِ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'tazkiyah', 'گناہوں کے نقصانات اور قلبی امراض کا نبوی علاج', 'کتبِ مطالعہ و علاجِ امراضِ قلب', NULL, NULL, 'from-rose-950 via-stone-900 to-emerald-950', NULL, 'عشقِ مجازی، گناہوں کی عادت اور قلبی غفلت کے شکار افراد کے لیے قرآن و سنت پر مبنی روحانی و نفسیاتی علاج۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('daa_dawaa_ch1_dua', 'kharji_daa_dawaa_jawziyyah', 0, 'بَابُ الدُّعَاءِ وَأَنَّهُ أَقْوَى الأَسْبَابِ فِي دَفْعِ البَلَاءِ', 'باب 1: دعا — مصیبتوں اور بلاؤں کو ٹالنے کا سب سے طاقتور ترین روحانی ہتھیار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('daa_dawaa_seg_1_1', 'daa_dawaa_ch1_dua', 'kharji_daa_dawaa_jawziyyah', 0, 'قَالَ الإِمَامُ شَمْسُ الدِّينِ ابْنُ قَيِّمِ الجَوْزِيَّةِ: «الدُّعَاءُ مِنْ أَنْفَعِ الأَدْوِيَةِ، وَهُوَ عَدُوُّ البَلَاءِ؛ يُدَافِعُهُ، وَيُعَالِجُهُ، وَيَمْنَعُ نُزُولَهُ، وَيَرْفَعُهُ أَوْ يُخَفِّفُهُ إِذَا نَزَلَ. وَلَهُ مَعَ البَلَاءِ ثَلَاثُ مَقَامَاتٍ: أَحَدُهَا: أَنْ يَكُونَ أَقْوَى مِنَ البَلَاءِ فَيَدْفَعُهُ. الثَّانِي: أَنْ يَكُونَ أَضْعَفَ مِنَ البَلَاءِ فَيَقْوَى عَلَيْهِ البَلَاءُ، فَيُصَابُ بِهِ العَبْدُ وَلَكِنْ قَدْ يُخَفِّفُهُ. الثَّالِثُ: أَنْ يَتَقَاوَمَا وَيَمْنَعَ كُلُّ وَاحِدٍ مِنْهُمَا صَاحِبَهُ، كَمَا قَالَ ﷺ: «لَا يَرُدُّ القَدَرَ إِلَّا الدُّعَاءُ».', 'امام ابن قیم الجوزیہ رحمہ اللہ فرماتے ہیں: ''دعا تمام روحانی اور جسمانی دواؤں میں سب سے زیادہ نافع دوا ہے، اور وہ ہر مصیبت و آزمائش کی سب سے بڑی دشمن ہے؛ وہ مصیبت کا مقابلہ کرتی ہے، اس کا علاج کرتی ہے، مصیبت کے اترنے سے پہلے اسے روک دیتی ہے، اور اگر وہ اتر چکی ہو تو اسے اٹھا لیتی ہے یا اس کی شدت کو گھٹا دیتی ہے۔ اور بلا و مصیبت کے ساتھ دعا کی تین صورتیں ہوتی ہیں: پہلی صورت یہ کہ دعا مصیبت کے مقابلے میں زیادہ قوی اور مضبوط ہو تو وہ مصیبت کو بالکل ختم کر دیتی ہے۔ دوسری صورت یہ کہ دعا میں کمزوری ہو (غفلت یا حرام لقمے کے سبب) اور مصیبت طاقتور ہو، تو مصیبت غالب آ جاتی ہے لیکن دعا اس کے زہر کو کم کر دیتی ہے۔ تیسری صورت یہ کہ دعا اور مصیبت دونوں ہم پلہ ہوں اور دونوں ایک دوسرے سے گتھم گتھا ہو کر رک جائیں، جیسا کہ نبی ﷺ نے فرمایا: ''تقدیر کو صرف دعا ہی ٹال سکتی ہے''۔', 'کتاب ''الداء والدواء'' (الجواب الكافي لمن سأل عن الدواء الشافي) ایک پریشان حال شخص کے اس خط کا جواب ہے جس نے عشقِ مجازی اور گناہوں کی دلدل سے نکلنے کا نسخہ مانگا تھا۔ ابن قیم نے گناہوں کے اثرات اور دعا کی طاقت کو عیاں کیا۔', '[{"word":"أَنْفَعِ","role":"مجرور بمن","sign":"كسرة","detail":"وهو مضاف والأدوية مضاف إليه"},{"word":"عَدُوُّ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"والبلاء مضاف إليه"}]', '["الداء والدواء لابن القيم، ص 10-18، وأخرجه الترمذي (2139)."]', '{"en":"Ibn al-Qayyim analyzes the dynamics of Supplication (Du''a): It is the foremost medicine and adversary of calamity—countering, curing, preventing, or softening adversity. When Du''a is stronger than affliction, it vanquishes it outright; when balanced, they wrestle until the Day of Judgment.","ar":"بيان قدرة الدعاء الصادق على مصارعة البلاء وتغيير المقادير المعلقة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('daa_dawaa_ch2_atharr_dhunub', 'kharji_daa_dawaa_jawziyyah', 1, 'فَصْلٌ فِي عُقُوبَاتِ الذُّنُوبِ وَآثَارِهَا المَدْمُوغَةِ فِي القَلْبِ وَالبَدَنِ', 'باب 2: گناہوں کی سزائیں — دل کی ویرانی، رزق کی تنگی اور چہرے کی بے نوری');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('daa_dawaa_seg_2_1', 'daa_dawaa_ch2_atharr_dhunub', 'kharji_daa_dawaa_jawziyyah', 0, '«وَمِنْ عُقُوبَاتِ المَعَاصِي: حِرْمَانُ العِلْمِ؛ فَإِنَّ العِلْمَ نُورٌ يَقْذِفُهُ اللَّهُ فِي القَلْبِ، وَالمَعْصِيَةُ تُطْفِئُ ذَلِكَ النُّورَ. وَمِنْهَا: حِرْمَانُ الرِّزْقِ؛ فَإِنَّ العَبْدَ لَيُحْرَمُ الرِّزْقَ بِالذَّنْبِ يُصِيبُهُ. وَمِنْهَا: الوَحْشَةُ الَّتِي تَحْصُلُ لِلْعَاصِي بَيْنَهُ وَبَيْنَ اللَّهِ، وَلَوْ وُضِعَتْ لَهُ الدُّنْيَا بِحَذَافِيرِهَا لَمْ تَدْفَعْ تِلْكَ الوَحْشَةَ. وَمِنْهَا: تَعْسِيرُ أُمُورِهِ عَلَيْهِ؛ فَلَا يَتَوَجَّهُ لِأَمْرٍ إِلَّا وَيَجِدُهُ مُغْلَقاً أَوْ عَسِيراً».', 'ابن قیم رحمہ اللہ فرماتے ہیں: ''گناہوں کی ہولناک سزاؤں میں سے ایک سزا یہ ہے کہ انسان حقیقی علم سے محروم ہو جاتا ہے؛ کیونکہ علم وہ نور ہے جسے اللہ دل میں ڈالتا ہے، اور گناہ اس نور کو بجھا کر راکھ کر دیتا ہے۔ اور سزاؤں میں سے یہ ہے کہ انسان پاکیزہ رزق سے محروم ہو جاتا ہے؛ کیونکہ بندہ اپنے گناہ کی نحوست سے حلال رزق سے محروم کر دیا جاتا ہے۔ اور سزاؤں میں سے وہ دل کی ہولناک ویرانی اور گھٹن ہے جو گناہ گار کے اور اس کے رب کے درمیان حائل ہو جاتی ہے، اگر اس کے سامنے پوری دنیا کی دولت بھی لا کر رکھ دی جائے تو وہ اس ویرانی اور بے چینی کو دور نہیں کر سکتی۔ اور سزاؤں میں سے اس کے کاموں کا اٹک جانا اور بگڑ جانا ہے؛ وہ جس کام کی طرف بھی رخ کرتا ہے اسے بند اور بند گلی پاتا ہے''۔', 'گناہ صرف آخرت کا نقصان نہیں کرتے بلکہ انسان کی موجودہ زندگی کو گھٹن، ناکامی اور اضطراب کا جہنم بنا دیتے ہیں۔ امام ابن قیم کی یہ وارننگ انسانی ضمیر کو جھنجھوڑ دیتی ہے۔', '[{"word":"حِرْمَانُ","role":"مبتدأ مؤخر مرفوع","sign":"ضمة","detail":"من عقوبات شبه جملة خبر مقدم"},{"word":"مُغْلَقاً","role":"مفعول به ثان ليجده منصوب","sign":"فتحة","detail":"والهاء مفعول أول"}]', '["الداء والدواء، ص 55-68."]', '{"en":"The toxic repercussions of sin: Deprivation of sacred knowledge (since knowledge is divine illumination quenched by transgression), constriction of sustenance, an agonizing estrangement in the soul against Allah, and the systematic obstruction of all life affairs.","ar":"الآثار التدميرية للسيئات على السكينة النفسية والبركة المعيشية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_sayd_khatir_jawzi', 'صَيْدُ الخَاطِرِ', 'الإِمَامُ أَبُو الفَرَجِ عَبْدُ الرَّحْمَنِ ابْنُ الجَوْزِيِّ (ت: 597ھ)', 'kharji_kitab', 'tazkiyah', 'فکری و نفسیاتی واردات، عبرتیں و حکمتیں', 'کتبِ مطالعہ و بصیرتِ حیات', NULL, NULL, 'from-amber-950 via-stone-900 to-teal-950', NULL, 'ابن الجوزی کے دل و دماغ پر آنے والے روزمرہ کے انوکھے خیالات، معاشرتی کمزوریوں کا ادراک اور فکری شاہکار۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sayd_khatir_ch1_hifz_zaman', 'kharji_sayd_khatir_jawzi', 0, 'فَصْلٌ فِي حِفْظِ الزَّمَانِ وَاغْتِنَامِ أَنْفَاسِ العُمُرِ', 'باب 1: وقت کی حفاظت — عمر کی قیمتی گھڑیوں اور سانسوں کو ضیاع سے بچانا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sayd_khatir_seg_1_1', 'sayd_khatir_ch1_hifz_zaman', 'kharji_sayd_khatir_jawzi', 0, 'قَالَ الإِمَامُ أَبُو الفَرَجِ ابْنُ الجَوْزِيِّ: «يَنْبَغِي لِلإِنْسَانِ أَنْ يَعْرِفَ شَرَفَ زَمَانِهِ وَقَدْرَ وَقْتِهِ، فَلَا يُضَيِّعَ مِنْهُ لَحْظَةً فِي غَيْرِ قُرْبَةٍ، وَيُقَدِّمَ الأَفْضَلَ فَالأَفْضَلَ مِنَ القَوْلِ وَالعَمَلِ. رَأَيْتُ عَامَّةَ النَّاسِ يُضَيِّعُونَ أَوْقَاتَهُمْ عَجَباً: يَتَجَالَسُونَ فِي الحَدِيثِ الفَارِغِ، وَيَقْطَعُونَ النَّهَارَ بِالبَاطِلِ؛ فَعَلِمْتُ أَنَّ اللَّهَ تَعَالَى لَمْ يُطْلِعْ عَلَى شَرَفِ العُمُرِ وَمَعْرِفَةِ قَدْرِ العَافِيَةِ إِلَّا مَنْ وَفَّقَهُ وَأَلْهَمَهُ؛ فَالعُمُرُ مَزْرَعَةُ الآخِرَةِ، وَكُلُّ نَفَسٍ جَوْهَرَةٌ لَا قِيمَةَ لَهَا».', 'امام ابو الفرج عبد الرحمن بن الجوزی رحمہ اللہ فرماتے ہیں: ''ہر ہوش مند انسان پر لازم ہے کہ وہ اپنے زمانے کی عظمت اور اپنے وقت کی قیمت کو پہچانے، اور اس کی ایک گھڑی بھی اللہ کے قرب کے سوا کسی کام میں ضائع نہ کرے، اور ہر لمحہ بہترین سے بہترین قول و عمل کو آگے رکھے۔ میں نے عام لوگوں کو دیکھا کہ وہ حیرت انگیز طور پر اپنی قیمتی عمر ضائع کر رہے ہیں: گھنٹوں فضول گپ شپ میں بیٹھے رہتے ہیں اور دن کو لایعنی باتوں میں گزار دیتے ہیں؛ پس مجھے یقین ہو گیا کہ اللہ تعالیٰ نے زندگی کی قدر و قیمت اور عمر کی شرافت کی سمجھ صرف اسی کو بخشی ہے جسے اس نے توفیق دی ہو؛ پس یہ عمر آخرت کی کھیتی ہے، اور تیرا ہر ایک سانس ایسا انمول ہیرا ہے جس کا کوئی بدل نہیں ہو سکتا''۔', 'صيد الخاطر امام ابن جوزی کی ذاتی ڈائری اور نایاب مشاہدات کا مجموعہ ہے جہاں انہوں نے دل میں ابھرنے والے نکتوں کو شکار کیا ہے۔ وقت کی حفاظت پر ان کا یہ کلام اسلامی تاریخ کا شاہکار ادب ہے۔', '[{"word":"شَرَفَ","role":"مفعول به ليعرف منصوب","sign":"فتحة","detail":"وهو مضاف وزمانه مضاف إليه"},{"word":"جَوْهَرَةٌ","role":"خبر المبتدأ نفس مرفوع","sign":"ضمة","detail":"كل مبتدأ وهو مضاف ونفس مضاف إليه"}]', '["صيد الخاطر لابن الجوزي، فصل: حفظ الوقت، ص 15-18."]', '{"en":"Imam Ibn al-Jawzi reflects in ''Sayd al-Khatir'': A person must realize the immense sacredness of time and not squander a second outside divine proximity. Most people squander hours in frivolous idle gossip; every breath is an irreplaceable jewel meant to plant eternity.","ar":"المحافظة على رأس مال الإنسان وهو العمر وتحذير الغافلين من تضييع الأوقات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sayd_khatir_ch2_uzlah', 'kharji_sayd_khatir_jawzi', 1, 'فَصْلٌ فِي فَضِيلَةِ العُزْلَةِ عَنِ الخَلْقِ وَمُنَاجَاةِ الخَالِقِ', 'باب 2: خلوت پسندی اور کتابوں سے دوستی — دنیاوی میل جول سے بچ کر علم و فکر کی تنہائی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sayd_khatir_seg_2_1', 'sayd_khatir_ch2_uzlah', 'kharji_sayd_khatir_jawzi', 0, '«مَا رَأَيْتُ أَعَزَّ وَلَا أَنْفَعَ مِنَ العُزْلَةِ عَنْ فُضُولِ الخَلْطَةِ؛ فَإِنَّهَا تَكُفُّ اللِّسَانَ عَنِ الغِيبَةِ، وَتَحْفَظُ البَصَرَ عَنِ النَّظَرِ إِلَى المَحَارِمِ، وَتَصُونُ القَلْبَ عَنْ كَدَرِ الدُّنْيَا. وَأَحْسَنُ أَنِيسٍ فِي العُزْلَةِ الكِتَابُ؛ فَإِنِّي إِذَا خَلَوْتُ بِكُتُبِي كَأَنِّي جَالَسْتُ الحَسَنَ، وَابْنَ سِيرِينَ، وَالشَّافِعِيَّ، وَأَحْمَدَ؛ أَسْتَفِيدُ مِنْ عُقُولِهِمْ وَأَنْهَلُ مِنْ حِكْمَتِهِمْ بِلَا مَنٍّ وَلَا أَذًى».', 'ابن جوزی فرماتے ہیں: ''میں نے بے مقصد میل جول اور لوگوں کی بھیڑ سے تنہائی اختیار کرنے سے زیادہ باعزت اور مفید کوئی چیز نہیں دیکھی؛ کیونکہ یہ تنہائی انسان کی زبان کو غیبت سے روکتی ہے، آنکھوں کو حرام مناظر سے محفوظ رکھتی ہے، اور دل کو دنیا کی کدورتوں اور حسد سے بچاتی ہے۔ اور تنہائی کا سب سے بہترین ساتھی کتاب کا مطالعہ ہے؛ کیونکہ جب میں اپنی کتابوں کے ساتھ تنہا ہوتا ہوں تو یوں لگتا ہے جیسے میں امام حسن بصری، ابن سیرین، امام شافعی اور امام احمد بن حنبل کی محفل میں بیٹھا ہوں؛ میں بغیر کسی احسان اور تکلیف کے ان کی عقلوں سے فائدہ اٹھاتا ہوں اور ان کی حکمتوں سے سیراب ہوتا ہوں''۔', 'عظیم لوگ تنہائی اور کتابوں کے مطالعے سے جنم لیتے ہیں۔ ابن جوزی نے بیس ہزار سے زائد جلدیں خود پڑھی تھیں اور اسی خلوت نے انہیں بیس ہزار خطبے دینے اور پانچ سو کتابیں لکھنے کا ملکہ دیا۔', '[{"word":"أَعَزَّ","role":"مفعول به لرأيت منصوب","sign":"فتحة","detail":"اسم تفضيل ممنوع من الصرف"},{"word":"الكِتَابُ","role":"خبر المبتدأ أحسن مرفوع","sign":"ضمة","detail":"أحسن مبتدأ وأنيس مضاف إليه"}]', '["صيد الخاطر، فصل: منافع العزلة، ص 88-92."]', '{"en":"The bliss of intellectual solitude: Isolation from frivolous mingling preserves the tongue from backbiting and the heart from rancor. The finest companion in seclusion is the book—communing directly with the brilliant minds of Hasan, Shafi''i, and Ahmad.","ar":"أنس الخلوة بالقراءة ومجالسة عقول السلف في بطون الكتب."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lataif_maarif_rajab', 'لَطَائِفُ المَعَارِفِ فِيمَا لِمَوَاسِمِ العَامِ مِنَ الوَظَائِفِ', 'الحَافِظُ زَيْنُ الدِّينِ ابْنُ رَجَبٍ الحَنْبَلِيُّ (ت: 795ھ)', 'kharji_kitab', 'tazkiyah', 'اسلامی مہینوں اور مبارک ایام کے فضائل و معمولات', 'کتبِ مطالعہ و اعمالِ سالانہ', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'محرم، رجب، شعبان، رمضان، ذو الحجہ اور سال بھر کے مبارک ایام میں کی جانے والی عبادات، رقت انگیز دعائیں اور نصیحتیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('lataif_rajab_ch1_ramadan', 'kharji_lataif_maarif_rajab', 0, 'وَظَائِفُ شَهْرِ رَمَضَانَ المُبَارَكِ: فَضْلُ الجُودِ وَتِلَاوَةِ القُرْآنِ', 'باب 1: رمضان المبارک کے فضائل اور اعمال — سخاوت، شب بیداری اور قرآن کا دور');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('lataif_rajab_seg_1_1', 'lataif_rajab_ch1_ramadan', 'kharji_lataif_maarif_rajab', 0, 'قَالَ الحَافِظُ زَيْنُ الدِّينِ ابْنُ رَجَبٍ الحَنْبَلِيُّ: «كَانَ رَسُولُ اللَّهِ ﷺ أَجْوَدَ النَّاسِ، وَكَانَ أَجْوَدَ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ جِبْرِيلُ فَيُدَارِسُهُ القُرْآنَ، فَلَرَسُولُ اللَّهِ ﷺ أَجْوَدُ بِالخَيْرِ مِنَ الرِّيحِ المُرْسَلَةِ. وَفِي هَذَا الحَدِيثِ دَلَالَةٌ عَلَى اسْتِحْبَابِ مُدَارَسَةِ القُرْآنِ فِي رَمَضَانَ وَالِاجْتِمَاعِ عَلَى ذَلِكَ، وَعَلَى اسْتِحْبَابِ كَثْرَةِ الصَّدَقَةِ وَإِطْعَامِ الطَّعَامِ؛ فَإِنَّ اجْتِمَاعَ الصِّيَامِ وَالصَّدَقَةِ أَوْجَبُ لِلْمَغْفِرَةِ وَأَبْعَدُ عَنِ النَّارِ».', 'حافظ زین الدین ابن رجب حنبلی رحمہ اللہ فرماتے ہیں: ''رسول اللہ ﷺ تمام انسانوں میں سب سے زیادہ سخی تھے، اور رمضان کے مبارک مہینے میں آپ کی سخاوت کا دریا اس وقت اور زیادہ جوش مارتا جب حضرت جبریل علیہ السلام آپ سے ملاقات کرتے اور آپ کے ساتھ قرآن کا دور فرماتے، پس رسول اللہ ﷺ بھلائی اور فیض رسانی میں تیز جھونکوں والی ہوا سے بھی زیادہ سخی ہو جایا کرتے تھے۔ اور اس حدیث میں رمضان میں قرآن کا باہمی دور کرنے، تلاوت کے لیے جمع ہونے، اور کثرت سے صدقہ دینے اور غریبوں کو کھانا کھلانے کے مستحب ہونے کی واضح دلیل ہے؛ کیونکہ روزے اور صدقے کا اکٹھا ہونا مغفرت کو واجب کرنے والا اور جہنم کی آگ سے سب سے زیادہ دور کرنے والا ہے''۔', 'لطائف المعارف اسلامی سال کے بارہ مہینوں کے فضائل اور ان کے موسمی وظائف و عبادات پر لکھی جانے والی سب سے خوبصورت اور مؤثر کتاب ہے۔ ابن رجب نے رمضان کی برکات کو دل میں اتار دیا ہے۔', '[{"word":"أَجْوَدَ","role":"خبر كان منصوب","sign":"فتحة","detail":"رسول اسمها وأجود خبرها"},{"word":"الرِّيحِ","role":"مجرور بمن","sign":"كسرة","detail":"المرسلة نعت لها"}]', '["لطائف المعارف فيما لمواسم العام من الوظائف، ص 168-180، وأخرجه البخاري (6)."]', '{"en":"Hafiz Ibn Rajab expounds the virtues of Ramadan: The Prophet ﷺ was the most generous of all men, but his generosity peaked in Ramadan when Gabriel reviewed the Quran with him—faster in charity than the blowing wind. Pairing fasting with charity guarantees divine forgiveness.","ar":"فضائل مدارسة القرآن في رمضان واقتران الصوم بالجود والصدقة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('lataif_rajab_ch2_ashr_dhulhijjah', 'kharji_lataif_maarif_rajab', 1, 'فَضْلُ عَشْرِ ذِي الحِجَّةِ: أَيَّامُ النَّفَحَاتِ الإِلَهِيَّةِ وَأَعْظَمُ أَيَّامِ الدُّنْيَا', 'باب 2: عشرۂ ذی الحجہ کے دس مبارک دن — دنیا کے سب سے افضل ترین ایام اور اعمالِ صالحہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('lataif_rajab_seg_2_1', 'lataif_rajab_ch2_ashr_dhulhijjah', 'kharji_lataif_maarif_rajab', 0, '«عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَا مِنْ أَيَّامٍ العَمَلُ الصَّالِحُ فِيهَا أَحَبُّ إِلَى اللَّهِ مِنْ هَذِهِ الأَيَّامِ (يَعْنِي أَيَّامَ العَشْرِ)»، قَالُوا: يَا رَسُولَ اللَّهِ، وَلَا الجِهَادُ فِي سَبِيلِ اللَّهِ؟ قَالَ: «وَلَا الجِهَادُ فِي سَبِيلِ اللَّهِ، إِلَّا رَجُلٌ خَرَجَ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ مِنْ ذَلِكَ بِشَيْءٍ». وَالسِّرُّ فِي تَفْضِيلِهَا: اجْتِمَاعُ أُمَّهَاتِ العِبَادَةِ فِيهَا؛ وَهِيَ الصَّلَاةُ، وَالصِّيَامُ، وَالصَّدَقَةُ، وَالحَجُّ، وَذَلِكَ لَا يَتَأَتَّى فِي غَيْرِهَا».', 'ابن رجب رحمہ اللہ فرماتے ہیں: حضرت عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ ﷺ نے فرمایا: ''کوئی دن ایسے نہیں جن میں نیک عمل اللہ تعالیٰ کو ان دنوں (یعنی ذی الحجہ کے ابتدائی دس دنوں) کے نیک عمل سے زیادہ محبوب ہو!'' صحابہ نے عرض کیا: یا رسول اللہ! کیا اللہ کی راہ میں جہاد کرنا بھی نہیں؟ آپ ﷺ نے فرمایا: ''اللہ کی راہ میں جہاد بھی نہیں! سوائے اس شخص کے جہاد کے جو اپنی جان اور اپنا سارا مال لے کر نکلا اور پھر اس میں سے کچھ بھی واپس نہ لایا (سب کچھ راہِ خدا میں قربان کر کے شہید ہو گیا)''۔ اور ان دس دنوں کی فضیلت کا راز یہ ہے کہ ان میں اسلام کی تمام امہات العبادات بیک وقت اکٹھی ہو جاتی ہیں: یعنی نماز، روزہ، صدقہ و قربانی، اور حجِ بیت اللہ؛ اور یہ جامعیت سال کے کسی اور دن میں میسر نہیں آتی''۔', 'مسلمانوں کے لیے ذی الحجہ کے دس دن نیکیوں کا عظیم ترین سیزن ہیں۔ ابن رجب نے واضح کیا کہ ان دنوں میں ایک سبحان اللہ اور ایک نفل عمل باقی دنوں کے اعمال سے بدرجہا بھاری ہے۔', '[{"word":"أَحَبُّ","role":"خبر المبتدأ العمل مرفوع","sign":"ضمة","detail":"ما نافية تعمل عمل ليس أو تميمية"},{"word":"اجْتِمَاعُ","role":"خبر المبتدأ السر مرفوع","sign":"ضمة","detail":"وهو مضاف وأمهات مضاف إليه"}]', '["لطائف المعارف لابن رجب، ص 260-272، وأخرجه البخاري (969)."]', '{"en":"The Ten Days of Dhul Hijjah: The Prophet ﷺ certified that righteous deeds are more beloved to Allah in these days than any other, surpassing even standard Jihad. Their sublime supremacy stems from hosting the grand synergy of prayer, fasting, charity, sacrifice, and Hajj.","ar":"سر تفضيل عشر ذي الحجة باجتماع أمهات العبادات فيها."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_jami_ulum_hikam_rajab', 'جَامِعُ العُلُومِ وَالحِكَمِ فِي شَرْحِ خَمْسِينَ حَدِيثاً مِنْ جَوَامِعِ الكَلِمِ', 'الحَافِظُ ابْنُ رَجَبٍ الحَنْبَلِيُّ (ت: 795ھ)', 'kharji_kitab', 'hadith', 'شرحِ اربعینِ نووی مع تکملہ ابن رجب', 'کتبِ مطالعہ و حدیثِ نبوی', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'امام نووی کی چالیس حدیثوں پر مزید دس جامع احادیث کا اضافہ اور ان کی فقہی، لغوی اور تربیتی شرح کا لازوال خزانہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hikam_ch1_hifz_allah', 'kharji_jami_ulum_hikam_rajab', 0, 'شَرْحُ حَدِيثِ ابْنِ عَبَّاسٍ: «احْفَظِ اللَّهَ يَحْفَظْكَ»', 'باب 1: شرح حدیثِ ابن عباس — اللہ کے احکام کی حفاظت اور نصرتِ الٰہی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hikam_seg_1_1', 'hikam_ch1_hifz_allah', 'kharji_jami_ulum_hikam_rajab', 0, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْتُ خَلْفَ النَّبِيِّ ﷺ يَوْماً فَقَالَ: «يَا غُلَامُ، إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ، وَاعْلَمْ أَنَّ الأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ، وَلَوِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ، رُفِعَتِ الأَقْلَامُ وَجَفَّتِ الصُّحُفُ».', 'حضرت عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں کہ ایک دن میں رسول اللہ ﷺ کی سواری پر آپ کے پیچھے بیٹھا تھا تو آپ نے فرمایا: ''اے لڑکے! میں تمہیں چند سنہری باتیں سکھاتا ہوں: تم اللہ کے احکام کی حفاظت کرو اللہ تمہاری حفاظت فرمائے گا؛ تم اللہ کے حقوق کی حفاظت کرو تم اسے اپنے بالکل سامنے پاؤ گے؛ جب بھی مانگنا ہو صرف اللہ سے مانگو؛ جب بھی مدد طلب کرنی ہو صرف اللہ سے مدد چاہو؛ اور اچھی طرح جان لو کہ اگر پوری دنیا کے لوگ مل کر تمہیں کوئی نفع پہنچانا چاہیں تو ہرگز کوئی نفع نہیں پہنچا سکتے مگر وہی جو اللہ نے تمہارے مقدر میں لکھ دیا ہے، اور اگر وہ سب مل کر تمہیں کوئی نقصان پہنچانا چاہیں تو ہرگز کوئی نقصان نہیں پہنچا سکتے بجز اس کے جو اللہ نے تمہارے مقدر میں لکھ دیا ہے، قلمیں اٹھا لی گئیں اور صحیفے خشک ہو چکے!''', 'حافظ ابن رجب فرماتے ہیں: یہ حدیث عقیدہ توحید، توکل اور تقدیر کا بحرِ ذخار ہے۔ جو بندہ جوانی میں اپنے اعضاء اور حلال و حرام کی حفاظت کرتا ہے، اللہ بڑھاپے میں اس کے ہوش و حواس اور عزت کی حفاظت فرماتا ہے۔', '[{"word":"يَا","role":"أداة نداء","sign":"مبني","detail":"غلام منادى نكرة مقصودة مبني على الضم"}]', '["أخرجه الترمذي (2516) وقال: حسن صحيح، وشرحه ابن رجب في جامع العلوم والحكم."]', '{"en":"Ibn Abbas reported the comprehensive advice: ''Preserve Allah''s limits and He will preserve you... If the whole nation gathers to benefit or harm you, they cannot except what Allah has decreed.''","ar":"قاعدة التوحيد المطلق وتفويض الأمور لله واليقين بالقدر المحتوم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hikam_ch2_nasihah', 'kharji_jami_ulum_hikam_rajab', 1, 'شَرْحُ حَدِيثِ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ»', 'باب 2: شرح حدیثِ اخوت — باہمی ہمدردی، ایثار اور سلامتیِ قلب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hikam_seg_2_1', 'hikam_ch2_nasihah', 'kharji_jami_ulum_hikam_rajab', 0, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ». قَالَ ابْنُ رَجَبٍ: هَذَا يَدُلُّ عَلَى أَنَّ المُؤْمِنَ يَسُرُّهُ مَا يَسُرُّ أَخَاهُ المُؤْمِنَ، وَيُرِيدُ لَهُ مِنَ الخَيْرِ مَا يُرِيدُهُ لِنَفْسِهِ، وَذَلِكَ كُلُّهُ إِنَّمَا يَنْشَأُ عَنْ سَلَامَةِ الصَّدْرِ مِنَ الغِلِّ وَالغِشِّ وَالحَسَدِ.', 'حضرت انس رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''تم میں سے کوئی شخص اس وقت تک کامل مومن نہیں ہو سکتا جب تک کہ وہ اپنے بھائی کے لیے وہی چیز پسند نہ کرے جو وہ اپنی ذات کے لیے پسند کرتا ہے!'' حافظ ابن رجب فرماتے ہیں: یہ حدیث واضح دلیل ہے کہ مومن کو وہی بات خوش کرتی ہے جو اس کے مسلمان بھائی کو خوش کرے، اور وہ اپنے بھائی کے لیے وہی خیر چاہتا ہے جو اپنے لیے چاہتا ہے، اور یہ بلند مرتبہ صرف اسی وقت حاصل ہوتا ہے جب دل کینے، فریب اور حسد کی گندگی سے بالکل پاک ہو جائے۔', 'حسد اور کینہ ایمان کی چاشنی کو ختم کر دیتے ہیں۔ سچا مومن دوسروں کی ترقی اور نعمتوں پر خوش ہوتا ہے اور یہی ایمانی اخوت کی معراج ہے۔', '[{"word":"حَتَّى","role":"حرف غاية ونصب","sign":"مبني","detail":"يحب فعل مضارع منصوب بأن مضمرة"}]', '["متفق عليه: البخاري (13)، ومسلم (45)."]', '{"en":"Anas reported: ''None of you truly believes until he loves for his brother what he loves for himself.'' Ibn Rajab explains this springs from a heart completely purified of malice and envy.","ar":"تطهير القلوب من الحسد شرط لكمال الإيمان والأخوة الإسلامية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_sifat_safwah_jawzi', 'صِفَةُ الصَّفْوَةِ', 'الإِمَامُ أَبُو الفَرَجِ عَبْدُ الرَّحْمَنِ ابْنُ الجَوْزِيِّ (ت: 597ھ)', 'kharji_kitab', 'tazkiyah', 'برگزیدہ صحابہ، تابعین و صالحین کے احوال', 'کتبِ مطالعہ و رقتِ قلوب', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'حافظ ابو نعیم کی ''حلیۃ الاولیاء'' کا نفیس اختصار جس میں ضعیف روایات کو چھانٹ کر خالص مستند سوانح اور نصیحتیں جمع کی گئی ہیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('safwah_ch1_khulafa', 'kharji_sifat_safwah_jawzi', 0, 'أَخْبَارُ الخُلَفَاءِ وَالصَّحَابَةِ فِي الزُّهْدِ وَالبُكَاءِ وَالخَوْفِ مِنَ الجَلِيلِ', 'باب 1: خلفائے راشدین اور اکابر صحابہ کا زہد، خوفِ خدا اور گریہ و زاری');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('safwah_seg_1_1', 'safwah_ch1_khulafa', 'kharji_sifat_safwah_jawzi', 0, 'قَالَ الإِمَامُ ابْنُ الجَوْزِيِّ: «اخْتَصَرْتُ فِي هَذَا الكِتَابِ «حِلْيَةَ الأَوْلِيَاءِ» وَهَذَّبْتُهُ، وَجَعَلْتُهُ فِي أَخْبَارِ صَفْوَةِ الخَلْقِ. كَانَ عُثْمَانُ بْنُ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ إِذَا وَقَفَ عَلَى قَبْرٍ بَكَى حَتَّى يَبُلَّ لِحْيَتَهُ، فَقِيلَ لَهُ: تُذْكَرُ الجَنَّةُ وَالنَّارُ فَلَا تَبْكِي، وَتَبْكِي مِنْ هَذَا؟! فَقَالَ: إِنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «إِنَّ القَبْرَ أَوَّلُ مَنْزِلٍ مِنْ مَنَازِلِ الآخِرَةِ، فَإِنْ نَجَا مِنْهُ فَمَا بَعْدَهُ أَيْسَرُ مِنْهُ، وَإِنْ لَمْ يَنْجُ مِنْهُ فَمَا بَعْدَهُ أَشَدُّ مِنْهُ!».', 'امام ابو الفرج ابن الجوزی رحمہ اللہ فرماتے ہیں: ''میں نے اس کتاب میں ابو نعیم کی ''حلیۃ الاولیاء'' کو چھانٹ کر اور اس کی ضعیف روایات کو نکال کر امت کی برگزیدہ شخصیات کے مستند احوال کے لیے مرتب کیا ہے۔ امیر المؤمنین حضرت عثمان غنی رضی اللہ عنہ جب کسی قبر کے پاس کھڑے ہوتے تو اس قدر زار و قطار روتے کہ آپ کی ریش مبارک آنسوؤں سے تر ہو جاتی، آپ سے عرض کیا گیا: آپ کے سامنے جنت اور دوزخ کا تذکرہ ہوتا ہے تو آپ اس طرح نہیں روتے، اور اس قبر کو دیکھ کر اتنا روتے ہیں؟! تو آپ نے فرمایا: رسول اللہ ﷺ نے ارشاد فرمایا ہے: ''قبر آخرت کی منزلوں میں سے سب سے پہلی منزل ہے، پس اگر انسان اس سے نجات پا گیا تو اس کے بعد کی منزلیں اس سے زیادہ آسان ہوں گی، اور اگر وہ اس قبر کے عذاب سے نہ بچ سکا تو بعد کے مراحل اس سے کہیں زیادہ سخت اور ہولناک ہوں گے!''', 'صفة الصفوة ابن جوزی کی وہ اصلاحی کتاب ہے جس میں انہوں نے صوفیاء کے تذکروں سے بے بنیاد قصے کہانیاں نکال کر صحابہ اور تابعین کے صحیح زہد اور خوفِ خدا کو نمایاں کیا۔', '[{"word":"أَوَّلُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"القبر اسمها وأول خبرها وهو مضاف"},{"word":"أَيْسَرُ","role":"خبر المبتدأ ما مرفوع","sign":"ضمة","detail":"اسم تفضيل"}]', '["صفة الصفوة لابن الجوزي، 1/ 285-290، وأخرجه الترمذي (2308) وحسنه."]', '{"en":"Ibn al-Jawzi''s refined anthology ''Sifat as-Safwah'': When Caliph ''Uthman stood over a grave, he wept until his beard was drenched. When asked why the grave evoked more tears than descriptions of Paradise and Hell, he cited the Prophet ﷺ: ''The grave is the first stage of the Hereafter; if one is saved from it, what follows is easier.''","ar":"التحذير من فتنة القبر والاتعاظ بمنازل الآخرة على طريقة الصحابة الأخيار."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('safwah_ch2_rabiah', 'kharji_sifat_safwah_jawzi', 1, 'رَابِعَةُ العَدَوِيَّةُ: إِخْلَاصُ المَحَبَّةِ الإِلَهِيَّةِ وَالشَّوْقُ إِلَى اللَّهِ', 'باب 2: رابعہ بصریہ — محبتِ الٰہی کا سوز اور خالص بندگی کا جذبہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('safwah_seg_2_1', 'safwah_ch2_rabiah', 'kharji_sifat_safwah_jawzi', 0, '«كَانَتْ رَابِعَةُ العَدَوِيَّةُ البَصْرِيَّةُ مِنْ أَعْظَمِ العَابِدَاتِ زُهْداً؛ كَانَتْ تُصَلِّي اللَّيْلَ كُلَّهُ، فَإِذَا طَلَعَ الفَجْرُ هَجَعَتْ هَجْعَةً خَفِيفَةً، ثُمَّ تَقُومُ فَزِعَةً تَقُولُ: «يَا نَفْسُ، كَمْ تَنَامِينَ؟! يُوشِكُ أَنْ تَنَامِي نَوْمَةً لَا تَقُومِينَ مِنْهَا إِلَّا لِصَيْحَةِ يَوْمِ النُّشُورِ!». وَكَانَتْ تَقُولُ فِي دُعَائِهَا: «اللَّهُمَّ إِنِّي مَا عَبَدْتُكَ خَوْفاً مِنْ نَارِكَ، وَلَا طَمَعاً فِي جَنَّتِكَ، وَلَكِنِّي عَبَدْتُكَ لِأَنَّكَ أَهْلٌ لِلْعِبَادَةِ وَحَبّاً فِي جَلَالِكَ».', 'ابن جوزی رحمہ اللہ فرماتے ہیں: ''حضرت رابعہ عدویہ بصریہ عبادت گزار زاہدات میں بلند ترین مقام رکھتی تھیں؛ وہ پوری رات نماز میں گزار دیتیں، اور جب صبحِ صادق طلوع ہوتی تو چند لمحوں کے لیے ہلکی سی اونگھ لیتیں، پھر گھبرا کر اٹھ کھڑی ہوتیں اور اپنے نفس کو مخاطب کر کے فرماتیں: ''اے میرے نفس! تو کب تک سوئے گا؟! عنقریب تو قبر میں ایسی گہری نیند سو جائے گا جس سے قیامت کے صور کی ہولناک چیخ کے سوا تجھے کوئی نہیں جگا سکے گا!'' اور اپنی پرخلوص مناجات میں عرض کیا کرتی تھیں: ''اے میرے اللہ! میں نے تیری عبادت صرف تیرے جہنم کے ڈر یا تیری جنت کے لالچ میں نہیں کی، بلکہ میں نے تیری بندگی اس لیے کی کیونکہ تو بذاتِ خود عبادت کے لائق ہے اور مجھے تیرے جلال و حسن سے والہانہ محبت ہے''۔', 'رابعہ بصریہ نے بندگی کو صرف خوف اور لالچ سے بلند کر کے ذاتِ الٰہی کی سچی محبت اور جلال کا آئینہ دار بنایا۔', '[{"word":"نَوْمَةً","role":"مفعول مطلق منصوب","sign":"فتحة","detail":"مبين للنوع"},{"word":"أَهْلٌ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"والكاف اسمها"}]', '["صفة الصفوة لابن الجوزي، 4/ 24-28."]', '{"en":"Rabi''ah al-''Adawiyyah: The pinnacle of devotional love. She vigiled through nights, chastising her soul upon brief dawn dozes: ''O soul, soon you shall sleep a sleep from which you will not awaken until the Resurrection Trumpet!''","ar":"تجريد العبودية لله حباً وإجلالاً لذاته العلية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tanbih_ghafilin_samarqandi', 'تَنْبِيهُ الغَافِلِينَ بِأَحَادِيثِ سَيِّدِ الأَنْبِيَاءِ وَالمُرْسَلِينَ', 'الفَقِيهُ أَبُو اللَّيْثِ نَصْرُ بْنُ مُحَمَّدٍ السَّمَرْقَنْدِيُّ الحَنَفِيُّ (ت: 373ھ)', 'kharji_kitab', 'tazkiyah', 'مواعظِ حسنہ و تنبیہاتِ ایمانیہ', 'کتبِ مطالعہ و خطابت و مواعظ', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'فقہِ حنفی کے نامور امام ابو اللیث سمرقندی کی وعظ و نصیحت پر مشتمل لازوال کتاب جو صدیوں سے مسلمانوں کی خوابیدہ روح کو بیدار کر رہی ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tanbih_samarqandi_ch1_ikhlas', 'kharji_tanbih_ghafilin_samarqandi', 0, 'بَابُ الإِخْلَاصِ وَالنِّيَّةِ فِي سَائِرِ الأَعْمَالِ الصَّالِحَةِ', 'باب 1: تمام اعمال میں اخلاص اور سچی نیت کا ہونا — نجات کی اولین شرط');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tanbih_samarqandi_seg_1_1', 'tanbih_samarqandi_ch1_ikhlas', 'kharji_tanbih_ghafilin_samarqandi', 0, 'قَالَ الفَقِيهُ أَبُو اللَّيْثِ السَّمَرْقَنْدِيُّ الحَنَفِيُّ: «اعْلَمْ أَنَّ العَمَلَ لَا يُقْبَلُ إِلَّا بِثَلَاثَةِ أَشْيَاءَ: العِلْمِ قَبْلَهُ، وَالنِّيَّةِ مَعَهُ، وَالصَّبْرِ فِيهِ. فَإِنَّ العَمَلَ بِلَا عِلْمٍ ضَلَالٌ، وَبِلَا نِيَّةٍ عَبَثٌ، وَبِلَا صَبْرٍ هَبَاءٌ مَنْثُورٌ. وَرُوِيَ عَنْ عُمَرَ بْنِ الخَطَّابِ أَنَّهُ قَالَ: «أَفْضَلُ الأَعْمَالِ أَدَاءُ مَا افْتَرَضَ اللَّهُ، وَالوَرَعُ عَمَّا حَرَّمَ اللَّهُ، وَصِدْقُ النِّيَّةِ فِيمَا عِنْدَ اللَّهِ تَعَالَى». فَمَنْ عَمِلَ عَمَلاً يُرِيدُ بِهِ ثَنَاءَ النَّاسِ أَوْ مَحْمَدَتَهُمْ فَلَيْسَ لَهُ فِي الآخِرَةِ مِنْ نَصِيبٍ».', 'فقیہ ابو اللیث نصر بن محمد سمرقندی حنفی رحمہ اللہ فرماتے ہیں: ''جان لو کہ کوئی عمل اللہ کے ہاں اس وقت تک مقبول نہیں ہوتا جب تک کہ اس میں تین چیزیں نہ ہوں: عمل سے پہلے اس کا صحیح شرعی علم، عمل کے ساتھ سچی نیت، اور عمل کے دوران استقامت و صبر۔ کیونکہ بغیر علم کے عمل گمراہی ہے، بغیر نیت کے عمل بے کار ہے، اور بغیر صبر کے عمل ہوا میں اڑ جانے والی راکھ ہے۔ اور حضرت عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: ''سب سے افضل ترین اعمال اللہ کے فرائض کو پورا کرنا، اللہ کی حرام کردہ چیزوں سے بچنا، اور اللہ کے اجر و ثواب میں سچی نیت رکھنا ہے''۔ پس جس شخص نے کوئی عمل لوگوں کی تعریف یا واہ واہ سمیٹنے کے لیے کیا تو آخرت میں اس کا کوئی حصہ نہیں ہوگا''۔', 'تنبيه الغافلين فقیہ ابو اللیث سمرقندی کی وہ دردمندانہ وعظ اور نصیحت کی کتاب ہے جو صدیوں سے مسلمانوں کے دلوں کو غفلت سے جگانے کے لیے پڑھی جاتی رہی ہے۔', '[{"word":"ضَلَالٌ","role":"خبر المبتدأ العمل مرفوع","sign":"ضمة","detail":"جملة اسمية تبين خطورة الجهل"},{"word":"نَصِيبٍ","role":"مجرور لفظاً بمن منصوب محلاً","sign":"كسرة","detail":"اسم ليس مؤخر"}]', '["تنبيه الغافلين بأحاديث سيد الأنبياء والمرسلين للسمرقندي، ص 12-16."]', '{"en":"Faqih Abu al-Layth as-Samarqandi sets the tripartite condition for accepted deeds: Prior knowledge, accompanying sincere intention, and steadfast patience during execution. Without intention, action is vanity; without patience, it dissipates like dust.","ar":"اشتراط العلم والنية والصبر لصحة الأعمال وقبولها عند الله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tanbih_samarqandi_ch2_birr', 'kharji_tanbih_ghafilin_samarqandi', 1, 'بَابُ بِرِّ الوَالِدَيْنِ وَعُقُوقِهِمَا وَعَظِيمِ حَقِّهِمَا فِي الإِسْلَامِ', 'باب 2: والدین کے ساتھ حسن سلوک اور نافرمانی کی تباہ کاری');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tanbih_samarqandi_seg_1_2', 'tanbih_samarqandi_ch2_birr', 'kharji_tanbih_ghafilin_samarqandi', 0, '«قَالَ أَبُو اللَّيْثِ: قَرَنَ اللَّهُ تَعَالَى شُكْرَ الوَالِدَيْنِ بِشُكْرِهِ فَقَالَ: {أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ}؛ فَمَنْ شَكَرَ اللَّهَ وَلَمْ يَشْكُرْ وَالِدَيْهِ لَمْ يُقْبَلْ مِنْهُ. وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ». وَعُقُوقُ الوَالِدَيْنِ مِنَ الكَبَائِرِ الَّتِي يُعَجَّلُ لِصَاحِبِهَا العُقُوبَةُ فِي الدُّنْيَا قَبْلَ الآخِرَةِ».', 'ابو اللیث سمرقندی فرماتے ہیں: ''اللہ تبارک و تعالیٰ نے والدین کے شکر کو اپنے شکر کے ساتھ ملا کر ذکر فرمایا: {میرا شکر ادا کرو اور اپنے والدین کا شکر ادا کرو، میری ہی طرف لوٹ کر آنا ہے}؛ پس جس نے اللہ کا شکر تو ادا کیا لیکن اپنے والدین کا شکر اور خدمت نہ کی تو اس کا کوئی شکر قبول نہیں ہوگا۔ اور حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے رسول اللہ ﷺ کی خدمت میں حاضر ہو کر پوچھا: میرے حسنِ سلوک اور خدمت کا سب سے زیادہ مستحق کون ہے؟ آپ ﷺ نے فرمایا: ''تیری ماں!'' اس نے پوچھا: پھر کون؟ فرمایا: ''تیری ماں!'' اس نے پوچھا: پھر کون؟ فرمایا: ''تیری ماں!'' اس نے چوتھی بار پوچھا: پھر کون؟ فرمایا: ''پھر تیرا باپ!'' اور والدین کی نافرمانی اور دل دکھانا ان کبیرہ گناہوں میں سے ہے جس کی سزا انسان کو آخرت سے پہلے دنیا ہی میں بھگتنی پڑتی ہے''۔', 'والدین کی خدمت جنت کی کنجی ہے۔ سمرقندی نے ثابت کیا کہ والدین کے حقوق ادا کیے بغیر کوئی شخص اللہ کا قرب حاصل نہیں کر سکتا۔', '[{"word":"أَحَقُّ","role":"خبر المبتدأ من مرفوع","sign":"ضمة","detail":"من اسم استفهام مبتدأ"},{"word":"العُقُوبَةُ","role":"نائب فاعل ليعجل مرفوع","sign":"ضمة","detail":"فعل مبني للمجهول"}]', '["تنبيه الغافلين، باب بر الوالدين، ص 65-72، وأخرجه البخاري (5971)."]', '{"en":"The towering obligation of honoring parents: Allah tethered gratitude to Himself with gratitude to parents ({Be grateful to Me and to your parents}). The Prophet ﷺ prioritized the mother three times before the father, warning that filial ingratitude receives expedited retribution in this earthly life.","ar":"عظم بر الوالدين والتحذير من شؤم العقوق المعجل في الدنيا."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_talbis_iblis_jawzi', 'تَلْبِيسُ إِبْلِيسَ', 'الإِمَامُ أَبُو الفَرَجِ ابْنُ الجَوْزِيِّ (ت: 597ھ)', 'kharji_kitab', 'tazkiyah', 'شیطانی فریب اور اہلِ علم و صلحاء کے مکر کے راستے', 'کتبِ مطالعہ و نقادیِ باطل', NULL, NULL, 'from-red-950 via-stone-900 to-amber-950', NULL, 'شیطان کس طرح علماء، صوفیاء، فقہاء اور عبادت گزاروں کو ان کی اپنی ہی عبادت اور علم کے راستے سے دھوکہ دیتا ہے، اس پر گہرا تنقیدی جائزہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talbis_iblis_ch1_taqlid', 'kharji_talbis_iblis_jawzi', 0, 'تَلْبِيسُ إِبْلِيسَ فِي الِابْتِدَاعِ وَالتَّقْلِيدِ الأَعْمَى بِغَيْرِ بُرْهَانٍ', 'باب 1: بدعات اور اندھی تقلید میں ابلیس کا فریب — عقل اور دلیل کو معطل کرنے کا شیطانی جال');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talbis_iblis_seg_1_1', 'talbis_iblis_ch1_taqlid', 'kharji_talbis_iblis_jawzi', 0, 'قَالَ الإِمَامُ الحَافِظُ ابْنُ الجَوْزِيِّ: «أَعْظَمُ مَكَايِدِ إِبْلِيسَ وَفِخَاخِهِ: تَزْيِينُ البِدْعَةِ وَالتَّقْلِيدِ المَحْضِ؛ فَإِنَّهُ يَصْرِفُ الإِنْسَانَ عَنِ اسْتِعْمَالِ عَقْلِهِ وَالبَحْثِ عَنِ الدَّلِيلِ إِلَى إِحْسَانِ الظَّنِّ بِالرِّجَالِ دُونَ حُجَّةٍ. وَالتَّقْلِيدُ يُعَطِّلُ مَنْفَعَةَ العَقْلِ الَّذِي خُلِقَ لِلتَّأَمُّلِ وَالتَّمْيِيزِ، وَإِنَّمَا مَثَلُ المُقَلِّدِ بِلَا دَلِيلٍ كَمَثَلِ رَجُلٍ لَهُ عَيْنَانِ صَحِيحَتَانِ يَقُودُهُ أَعْمَى فِي طَرِيقٍ مَهْلَكَةٍ! وَالبِدْعَةُ أَحَبُّ إِلَى إِبْلِيسَ مِنَ المَعْصِيَةِ؛ لِأَنَّ العَاصِيَ يَعْلَمُ أَنَّهُ عَاصٍ فَيَتُوبُ، أَمَّا المُبْتَدِعُ فَيَحْسَبُ أَنَّهُ يُحْسِنُ صُنْعاً فَلَا يَتُوبُ».', 'امام حافظ ابن الجوزی رحمہ اللہ فرماتے ہیں: ''شیطان کے سب سے بڑے ہتھکنڈوں اور جالوں میں سے دین میں بدعت اور بلا دلیل اندھی تقلید کو خوبصورت بنا کر پیش کرنا ہے؛ کیونکہ شیطان انسان کو اس کی عقل استعمال کرنے اور دلیل تلاش کرنے سے روک کر شخصیات کی بے بنیاد عقیدت میں مبتلا کر دیتا ہے۔ اور اندھی تقلید اس عقل کو معطل کر دیتی ہے جسے اللہ نے غور و فکر اور سچ جھوٹ میں تمیز کرنے کے لیے پیدا فرمایا تھا، اور بغیر دلیل کے اندھی تقلید کرنے والے کی مثال اس شخص جیسی ہے جس کی دونوں آنکھیں سلامت ہوں مگر وہ کسی اندھے کے پیچھے چل کر ہلاکت کے گڑھے میں گر رہا ہو! اور دین میں بدعت شیطان کو گناہ سے بھی زیادہ محبوب ہے؛ کیونکہ گناہ گار جانتا ہے کہ وہ گناہ کر رہا ہے لہٰذا وہ توبہ کر لیتا ہے، جبکہ بدعتی سمجھتا ہے کہ وہ بڑا نیک کام کر رہا ہے اس لیے وہ کبھی توبہ نہیں کرتا''۔', 'تلبيس إبليس امام ابن جوزی کی وہ انقلابی کتاب ہے جس میں انہوں نے صوفیاء، فقہاء، محدثین اور عوام پر شیطان کے مختلف دھوکے بے نقاب کیے تاکہ دین کو خالص کتاب و سنت پر برقرار رکھا جائے۔', '[{"word":"أَعْظَمُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"تزيين خبر المبتدأ"},{"word":"صُنْعاً","role":"تمييز منصوب","sign":"فتحة","detail":"محول عن المفعول"}]', '["تلبيس إبليس لابن الجوزي، ص 15-22، دار الفكر."]', '{"en":"Ibn al-Jawzi unmasks Satan''s deceptions (Talbis Iblis): Ensnaring humanity via religious innovation (Bid''ah) and blind uncritical following (Taqlid). Innovation is more beloved to Iblis than common sins, because a sinner acknowledges guilt and repents, whereas an innovator believes he is serving God.","ar":"كشف مكايد الشيطان في صرف الناس عن الدليل إلى البدع والتعصب المقيت."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('talbis_iblis_ch2_zuhd', 'kharji_talbis_iblis_jawzi', 1, 'تَلْبِيسُ إِبْلِيسَ عَلَى بَعْضِ الزُّهَّادِ فِي تَحْرِيمِ الحَلَالِ وَتَعْذِيبِ النَّفْسِ', 'باب 2: نام نہاد زاہدوں پر ابلیس کا فریب — حلال نعمتوں کو حرام ٹھہرانا اور جسم کو غیر شرعی عذاب دینا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('talbis_iblis_seg_2_1', 'talbis_iblis_ch2_zuhd', 'kharji_talbis_iblis_jawzi', 0, '«وَمِنْ تَلْبِيسِ إِبْلِيسَ عَلَى فِرَقٍ مِنَ المُنْتَسِبِينَ إِلَى الزُّهْدِ: أَنَّهُ حَسَّنَ لَهُمْ تَرْكَ الطَّيِّبَاتِ، وَلُبْسَ المُرَقَّعَاتِ الخَلِقَةِ، وَالِامْتِنَاعَ عَنْ أَكْلِ اللَّحْمِ وَشُرْبِ المَاءِ البَارِدِ، زَعْماً مِنْهُمْ أَنَّ هَذَا هُوَ التَّقَشُّفُ المَطْلُوبُ! وَهَذَا خِلَافُ هَدْيِ رَسُولِ اللَّهِ ﷺ؛ فَقَدْ كَانَ ﷺ يَأْكُلُ اللَّحْمَ، وَيُحِبُّ الحَلْوَاءَ وَالعَسَلَ، وَيَسْتَعْذِبُ لَهُ المَاءَ، وَيَلْبَسُ الحُلَّةَ الحَمْرَاءَ لِلْوُفُودِ. وَقَالَ اللَّهُ تَعَالَى رَادّاً عَلَى هَؤُلَاءِ: {قُلْ مَنْ حَرَّمَ زِينَةَ اللَّهِ الَّتِي أَخْرَجَ لِعِبَادِهِ وَالطَّيِّبَاتِ مِنَ الرِّزْقِ}».', 'ابن جوزی رحمہ اللہ فرماتے ہیں: ''اور زہد کی طرف منسوب بعض نادان لوگوں پر شیطان کا دھوکہ یہ ہے کہ اس نے ان کے ذہن میں پاکیزہ حلال نعمتوں کو چھوڑ دینے، پھٹے پرانے پیوند لگے کپڑے پہننے، اور گوشت کھانے اور ٹھنڈا پانی پینے سے رک جانے کو نیکی بنا کر دکھایا، ان کا یہ گمان تھا کہ جسم کو عذاب میں ڈالنا ہی مطلوبہ زہد ہے! حالانکہ یہ سوچ رسول اللہ ﷺ کی سنتِ مطہرہ کے صریح خلاف ہے؛ کیونکہ آپ ﷺ گوشت تناول فرماتے تھے، میٹھا اور شہد پسند فرماتے تھے، آپ کے لیے مدینہ کے میٹھے کنوؤں سے ٹھنڈا پانی لایا جاتا تھا، اور آپ وفود کے سامنے خوبصورت سرخ حلہ زیب تن فرماتے تھے۔ اور اللہ تعالیٰ نے ایسے جاہل زاہدوں کا رد کرتے ہوئے فرمایا: {آپ فرما دیجیے کہ اللہ کی اس زینت اور پاکیزہ رزق کو کس نے حرام کیا ہے جو اس نے اپنے بندوں کے لیے پیدا فرمایا ہے}''۔', 'اسلام رہبانیت اور خود ساختہ اذیت کا دین نہیں بلکہ اعتدال کا نام ہے۔ ابن جوزی نے ثابت کیا کہ سنت کے مطابق حلال نعمتوں سے لطف اندوز ہونا اور شکر ادا کرنا نام نہاد بھوک ہڑتالوں سے کہیں افضل ہے۔', '[{"word":"زَعْماً","role":"مفعول لأجله أو مفعول مطلق منصوب","sign":"فتحة","detail":"يبين علة صنيعهم الباطل"},{"word":"مَنْ","role":"اسم استفهام إنكاري مبتدأ","sign":"مبني","detail":"حرّم صلة وخبر"}]', '["تلبيس إبليس، باب تلبيس إبليس على الصوفية والزهاد، ص 180-195."]', '{"en":"Exposing faux-asceticism: Ibn al-Jawzi censures those who torture themselves by abstaining from meat, cold sweet water, and decent attire under the delusion of piety. The Prophet ﷺ enjoyed honey, meat, cool water, and dignified garments, quoting {Who has forbidden the adornment of Allah...}.","ar":"الرد على الغلو في الزهد ومخالفة الهدي النبوي المعتدل في التمتع بالطيبات."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_fawaid_jawziyyah', 'الفَوَائِدُ', 'الإِمَامُ شَمْسُ الدِّينِ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'tazkiyah', 'نکاتِ معرفت، حقائقِ توحید و وارداتِ قلبیہ', 'کتبِ مطالعہ و نکاتِ ربانیہ', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'قرآنی آیات کے گہرے پوشیدہ معانی، توحید، معرفتِ باری تعالیٰ، اور قلبی بیداری کے نایاب اور بیش قیمت نکات۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('fawaid_jawziyyah_ch1_qalb', 'kharji_fawaid_jawziyyah', 0, 'قَاعِدَةٌ جَلِيلَةٌ: فِي أَنَّ مَبْدَأَ كُلِّ خَيْرٍ وَشَرٍّ هُوَ الخَاطِرَةُ فِي القَلْبِ', 'باب 1: سنہری اصول — ہر نیکی اور برائی کا آغاز دل میں ابھرنے والے ''خیال'' سے ہوتا ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('fawaid_jawziyyah_seg_1_1', 'fawaid_jawziyyah_ch1_qalb', 'kharji_fawaid_jawziyyah', 0, 'قَالَ الإِمَامُ شَمْسُ الدِّينِ ابْنُ قَيِّمِ الجَوْزِيَّةِ: «دَافِعِ الخَطْرَةَ؛ فَإِنْ لَمْ تَفْعَلْ صَارَتْ فِكْرَةً، فَإِنْ لَمْ تُدَافِعْهَا صَارَتْ شَهْوَةً، فَإِنْ لَمْ تُعَالِجْهَا صَارَتْ إِرَادَةً وَعَزِيمَةً، فَإِنْ لَمْ تَقْطَعْهَا صَارَتْ فِعْلاً، فَإِنْ لَمْ تَتَدَارَكْهُ بِضِدِّهِ صَارَ عَادَةً، فَيَعْسُرُ عَلَيْكَ الخُرُوجُ مِنْهَا! فَمَلَكُ الإِنْسَانِ وَمِفْتَاحُ صَلَاحِهِ حِرَاسَةُ خَوَاطِرِهِ عِنْدَ بَابِ القَلْبِ؛ فَلَا يَأْذَنُ لِخَاطِرِ سُوءٍ أَنْ يَدْخُلَ، فَإِنَّ طَرْدَ الدَّاخِلِ بَعْدَ اسْتِقْرَارِهِ أَصْعَبُ مِنْ مَنْعِهِ قَبْلَ وُلُوجِهِ».', 'امام شمس الدین ابن قیم الجوزیہ رحمہ اللہ فرماتے ہیں: ''دل میں ابھرنے والے برے خیال کو فوراً جھٹک دو؛ کیونکہ اگر تم نے اسے نہ روکا تو وہ ''سوچ'' بن جائے گا، اگر تم نے سوچ کا علاج نہ کیا تو وہ ''خواہش'' بن جائے گی، اگر خواہش کو نہ روکا تو وہ ''پختہ ارادہ'' بن جائے گی، اگر ارادے کو نہ توڑا تو وہ ''عمل'' کا روپ دھار لے گا، اور اگر عمل کی تلافی نہ کی تو وہ پختہ ''عادت'' بن جائے گا، اور پھر اس عادت کی غلامی سے نکلنا تیرے لیے ناممکن کی حد تک مشکل ہو جائے گا! پس انسان کا اصل بادشاہ اور اس کی اصلاح کی کلید یہ ہے کہ وہ اپنے دل کے دروازے پر چوکیدار بن کر بیٹھے؛ کسی برے خیال کو دل کے اندر داخل ہی نہ ہونے دے، کیونکہ کسی چور کو گھر میں گھس جانے کے بعد نکالنا اس کو دروازے ہی پر روکنے کے مقابلے میں ہزار گنا زیادہ کٹھن ہوتا ہے''۔', 'کتاب ''الفوائد'' امام ابن قیم کے نادر افکار، علمی حکمتوں اور روحانی اشارات کا مجموعہ ہے۔ خیالات سے عادات تک کا یہ نفسیاتی سفر دنیا کی کسی بھی جدید سائیکالوجی سے زیادہ گہرا اور حقیقت پسندانہ ہے۔', '[{"word":"الخَطْرَةَ","role":"مفعول به لدافع منصوب","sign":"فتحة","detail":"دافع فعل أمر والفاعل مستتر"},{"word":"عَادَةً","role":"خبر صار منصوب","sign":"فتحة","detail":"واسمها مستتر يعود على الفعل"}]', '["الفوائد لابن القيم، ص 31-34، دار الكتب العلمية."]', '{"en":"Ibn al-Qayyim''s psychological chain of causation: Repel the fleeting thought (Khatrah), for if ignored, it turns into contemplation, then desire, then firm resolve, then physical action, then entrenched habit. Guard the gateway of the heart before the intruder establishes residency.","ar":"التحليل النفسي الدقيق لتدرج المعصية في النفس ووجوب حراسة الخواطر."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('fawaid_jawziyyah_ch2_lazzah', 'kharji_fawaid_jawziyyah', 1, 'فَصْلٌ فِي أَنَّ أَعْظَمَ لَذَّاتِ الدُّنْيَا لَذَّةُ مَعْرِفَةِ اللَّهِ وَالأُنْسِ بِهِ', 'باب 2: دنیا کی سب سے بڑی لذت — اللہ کی معرفت، اس سے محبت اور خلوت کا سرور');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('fawaid_jawziyyah_seg_2_1', 'fawaid_jawziyyah_ch2_lazzah', 'kharji_fawaid_jawziyyah', 0, '«مَنْ عَرَفَ اللَّهَ صَفَا لَهُ العَيْشُ، وَطَابَتْ لَهُ الحَيَاةُ، وَهَابَهُ كُلُّ شَيْءٍ، وَذَهَبَ عَنْهُ خَوْفُ المَخْلُوقِينَ. إِنَّ فِي القَلْبِ شَعَثاً لَا يَلُمُّهُ إِلَّا الإِقْبَالُ عَلَى اللَّهِ، وَفِيهِ وَحْشَةً لَا يُزِيلُهَا إِلَّا الأُنْسُ بِهِ فِي خَلْوَتِهِ، وَفِيهِ حُزْناً لَا يُذْهِبُهُ إِلَّا السُّرُورُ بِمَعْرِفَتِهِ وَصِدْقُ مُعَامَلَتِهِ. فَلَوْ أُعْطِيَ العَبْدُ الدُّنْيَا وَمَا فِيهَا لَمْ يَلُمَّ ذَلِكَ الشَّعَثَ أَبَداً؛ فَاللَّهُ وَحْدَهُ هُوَ غَايَةُ المُطَالَبِ وَمُنْتَهَى الرَّغَائِبِ».', 'ابن قیم رحمہ اللہ فرماتے ہیں: ''جس نے اللہ کو پہچان لیا اس کی زندگی صاف شفاف ہو گئی، اس کے شب و روز پرلطف ہو گئے، ہر چیز اس کی ہیبت ماننے لگی، اور مخلوق کا خوف اس کے دل سے رخصت ہو گیا۔ بلاشبہ انسانی دل کے اندر ایک ایسی پریشانی اور انتشار ہے جسے سوائے اللہ کی طرف متوجہ ہونے کے کوئی چیز سمیٹ نہیں سکتی، اور دل میں ایسی ویرانی ہے جسے خلوت میں اللہ سے مانوس ہوئے بغیر کوئی چیز دور نہیں کر سکتی، اور دل میں ایسا غم ہے جسے اللہ کی معرفت کی خوشی اور اس کے ساتھ سچے تعلق کے سوا کوئی دوا مٹا نہیں سکتی۔ پس اگر بندے کو پوری دنیا اور اس کے خزانے بھی دے دیے جائیں تب بھی اس کے دل کا یہ اضطراب کبھی ختم نہیں ہو سکتا؛ کیونکہ اکیلا اللہ ہی تمام ارادوں کی آخری منزل اور تمام تمناؤں کا مرکز و محور ہے''۔', 'یہ پیراگراف اسلامی تصوف اور معرفت کا سب سے شاندار موتی ہے جسے ہر دور کے علماء اور صلحاء نے اپنے دلوں پر نقش کیا۔ دنیا کے سارے سامان مل کر بھی دل کی پیاس نہیں بجھا سکتے سوائے ذکرِ الٰہی کے۔', '[{"word":"شَعَثاً","role":"اسم إنّ مؤخر منصوب","sign":"فتحة","detail":"في القلب شبه جملة خبر مقدم"},{"word":"غَايَةُ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"وهو مضاف والمطالب مضاف إليه"}]', '["الفوائد لابن القيم، ص 118-122."]', '{"en":"Ibn al-Qayyim''s famous meditation on the heart: ''In the heart there is a disarray that nothing can gather except turning to Allah; in it is a loneliness that nothing can dispel except intimacy with Him; in it is a sorrow that nothing can remove except the joy of knowing Him.''","ar":"تحقيق حاجة الروح الفطرية إلى بارئها وأن لا طمأنينة للقلب إلا به سبحانه."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_wara_ahmad', 'كِتَابُ الوَرَعِ', 'الإِمَامُ أَحْمَدُ بْنُ حَنْبَلٍ الشَّيْبَانِيُّ (ت: 241ھ)', 'kharji_kitab', 'tazkiyah', 'تقویٰ، پرہیزگاری اور مشتبہ لقمے سے اجتناب', 'کتبِ مطالعہ و زہدِ سلف', NULL, NULL, 'from-emerald-950 via-stone-900 to-teal-950', NULL, 'امام اہل سنت احمد بن حنبل کے تقویٰ، لقمۂ حلال کی احتیاط، اور دنیاوی مال و منصب سے بے نیازی کے حیرت انگیز واقعات اور فتاویٰ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wara_ahmad_ch1_shubuhat', 'kharji_wara_ahmad', 0, 'بَابُ تَوَقِّي الشُّبُهَاتِ فِي المَطْعَمِ وَالمَشْرَبِ وَالمَكَاسِبِ', 'باب 1: شبہات سے پرہیز — مشکوک روزی اور مال و دولت سے بچنے کا امام احمد کا تقویٰ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wara_ahmad_seg_1_1', 'wara_ahmad_ch1_shubuhat', 'kharji_wara_ahmad', 0, 'قَالَ الإِمَامُ أَحْمَدُ بْنُ حَنْبَلٍ رَحِمَهُ اللَّهُ: «الحَلَالُ بَيِّنٌ وَالحَرَامُ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ. وَالوَرَعُ: تَرْكُ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ. وَسُئِلَ الإِمَامُ أَحْمَدُ: بِمَ تَلِينُ القُلُوبُ؟ قَالَ: بِأَكْلِ الحَلَالِ! وَكَانَ لَا يَأْكُلُ مِنْ مَالِ وَلَدِهِ صَالِحٍ لِأَنَّهُ كَانَ يَأْخُذُ جِرَايَةً مِنْ بَيْتِ المَالِ، وَيَقُولُ: دَعْ مَا يَحِيكُ فِي صَدْرِكَ!».', 'امام اہلسنت امام احمد بن حنبل شیبانی رحمہ اللہ فرماتے ہیں: ''حلال بھی واضح ہے اور حرام بھی واضح ہے، اور ان دونوں کے درمیان مشتبہ چیزیں ہیں جنہیں بہت سے لوگ نہیں جانتے، پس جو شخص شبہات سے بچ گیا اس نے اپنے دین اور اپنی عزت کو داغدار ہونے سے بچا لیا۔ اور ورع (تقویٰ) یہ ہے کہ جس چیز میں ذرہ برابر بھی شک ہو اسے چھوڑ کر اس چیز کی طرف آ جاؤ جس میں کوئی شک نہ ہو۔ اور امام احمد سے پوچھا گیا: سخت دل کن چیزوں سے نرم ہوتے ہیں؟ فرمایا: ''صرف لقمۂ حلال کھانے سے!'' اور امام احمد اپنے لخت جگر صالح بن احمد کے گھر کا کھانا بھی نہیں کھاتے تھے کیونکہ وہ حکومت کے بیت المال سے تنخواہ لیتے تھے، اور فرماتے تھے: ''جو چیز تیرے سینے میں کھٹکے اسے چھوڑ دے!''', 'کتاب الورع للإمام أحمد تقویٰ اور زہد کی تاریخ کی سب سے مستند کتاب ہے جس میں امام احمد نے باریک ترین شبہات سے بچنے کی عملی مثالیں اپنے شاگردوں کو بتائیں۔', '[{"word":"الحَلَالُ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"بيّن خبر المبتدأ"},{"word":"بِأَكْلِ","role":"جار ومجرور متعلق بمحذوف خبر","sign":"كسرة","detail":"جواب السؤال"}]', '["كتاب الورع للإمام أحمد بن حنبل، رواية المروذي، ص 10-18، وأخرجه البخاري (52)."]', '{"en":"Imam Ahmad ibn Hanbal''s definitive manual on Scrupulous Piety (Al-Wara''): Guarding against ambiguous matters in food and earning. When asked what softens hardened hearts, he replied: ''Eating pure Halal!'' He declined eating from his son''s food because of government allowances.","ar":"أثر أكل الحلال في رقة القلوب والتحرز من الشبهات المالية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wara_ahmad_ch2_lisan', 'kharji_wara_ahmad', 1, 'بَابُ وَرَعِ اللِّسَانِ وَكَفِّهِ عَنْ أَعْرَاضِ المُسْلِمِينَ وَالفُضُولِ', 'باب 2: زبان کا تقویٰ — مسلمانوں کی عزتوں، عیب جوئی اور فضول باتوں سے زبان کی حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wara_ahmad_seg_2_1', 'wara_ahmad_ch2_lisan', 'kharji_wara_ahmad', 0, '«قَالَ المَرُّوذِيُّ: قُلْتُ لِأَبِي عَبْدِ اللَّهِ أَحْمَدَ بْنِ حَنْبَلٍ: مَا كَثْرَةُ الصَّوْمِ وَالصَّلَاةِ؟ قَالَ: «الصَّوْمُ وَالصَّلَاةُ حَسَنٌ، وَلَكِنَّ الوَرَعَ عَنْ أَعْرَاضِ المُسْلِمِينَ وَكَفَّ اللِّسَانِ أَفْضَلُ؛ كَمْ مِنْ صَائِمٍ قَائِمٍ لَا يَرَى لَهُ عَمَلٌ لِأَنَّهُ خَاضَ فِي أَعْرَاضِ النَّاسِ!». وَكَانَ إِذَا ذُكِرَ عِنْدَهُ رَجُلٌ بِسُوءٍ أَعْرَضَ وَقَالَ: «مَا لَنَا وَلِلنَّاسِ، دَعُونَا نُصْلِحْ عُيُوبَ أَنْفُسِنَا».', 'ابو بکر مروذی فرماتے ہیں: میں نے امام احمد بن حنبل سے عرض کیا: کثرت سے نفل روزے رکھنا اور نفل نمازیں پڑھنا کیسا ہے؟ آپ نے فرمایا: ''نفل نماز اور روزہ بہت اچھی چیز ہے، لیکن مسلمانوں کی عزتوں پر حملہ کرنے سے بچنا اور اپنی زبان کو فضول گوئی سے روک رکھنا اس سے کہیں زیادہ افضل ہے؛ کتنے ہی راتوں کو جاگنے والے اور دنوں کو روزے رکھنے والے ایسے ہیں جن کا کوئی عمل اللہ کے ہاں وزنی نہیں مانا جاتا کیونکہ وہ لوگوں کی غیبت اور عیب جوئی میں لگے رہتے تھے!'' اور امام احمد کے سامنے جب کسی کا برا تذکرہ ہوتا تو آپ رخ پھیر لیتے اور فرماتے: ''ہمیں لوگوں سے کیا لینا دینا، آؤ پہلے ہم اپنے ذاتی عیبوں کی اصلاح کر لیں!''', 'زبان کا ورع سب سے مشکل ورع ہے۔ امام احمد نے سمجھایا کہ نفل عبادات کے ڈھیر بھی غیبت اور بدگوئی کے سامنے برباد ہو جاتے ہیں۔', '[{"word":"حَسَنٌ","role":"خبر المبتدأ مرفوع","sign":"ضمة","detail":"الصوم مبتدأ وحسن خبره"},{"word":"أَفْضَلُ","role":"خبر المبتدأ الورع مرفوع","sign":"ضمة","detail":"اسم تفضيل"}]', '["كتاب الورع للإمام أحمد، ص 85-92."]', '{"en":"Guarding the tongue: Al-Marrudhi asked Imam Ahmad regarding abundant voluntary prayers and fasting. Ahmad replied: ''Good indeed, but restraining the tongue from dishonoring Muslims is far superior. How many a fasting worshiper has his deeds rendered void due to backbiting!''","ar":"صيانة اللسان عن الغيبة والاشتغال بعيوب النفس عن عيوب الخلق."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_adab_nufus_muhasibi', 'آدَابُ النُّفُوسِ', 'الإِمَامُ الحَارِثُ بْنُ أَسَدٍ المُحَاسِبِيُّ (ت: 243ھ)', 'kharji_kitab', 'tazkiyah', 'محاسبۂ نفس اور باطنی عیوب کی شناخت', 'کتبِ مطالعہ و تحلیلِ نفس', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'نفس کے فریب، باطنی ریاکاری، کبر، اور حسد کا باریک بینی سے آپریشن کرنے والی اسلامی تاریخ کی ابتدائی ترین کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adab_nufus_ch1_kibr', 'kharji_adab_nufus_muhasibi', 0, 'بَابُ مَعْرِفَةِ آفَاتِ الكِبْرِ وَالعُجْبِ وَدَفِينِ الرِّيَاءِ فِي النَّفْسِ', 'باب 1: باطنی امراض — تکبر، خود پسندی اور پوشیدہ ریاکاری کا نفسیاتی علاج');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adab_nufus_seg_1_1', 'adab_nufus_ch1_kibr', 'kharji_adab_nufus_muhasibi', 0, 'قَالَ الإِمَامُ الحَارِثُ بْنُ أَسَدٍ المُحَاسِبِيُّ: «أَصْلُ الكِبْرِ فِي النَّفْسِ: رُؤْيَةُ الفَضْلِ عَلَى الغَيْرِ، وَاسْتِعْظَامُ العَمَلِ. وَعَلَامَتُهُ أَنْ يَأْنَفَ مِنَ الرُّجُوعِ إِلَى الحَقِّ إِذَا خَفِيَ عَلَيْهِ، وَأَنْ يَحْتَقِرَ الفُقَرَاءَ وَالضُّعَفَاءَ. وَدَوَاؤُهُ: أَنْ يَعْلَمَ أَنَّ كُلَّ نِعْمَةٍ عِنْدَهُ هِيَ مِنْ فَضْلِ اللَّهِ لَا بِاسْتِحْقَاقِهِ، وَأَنَّهُ لَا يَدْرِي بِمَا يُخْتَمُ لَهُ؛ فَرُبَّ مُبْتَذَلٍ عِنْدَ النَّاسِ أَشْعَثَ أَغْبَرَ هُوَ عِنْدَ اللَّهِ خَيْرٌ مِنْ مِلْءِ الأَرْضِ مِنْ مِثْلِهِ!».', 'امام حارث بن اسد محاسبی رحمہ اللہ فرماتے ہیں: ''نفس کے اندر تکبر کی جڑ یہ ہے کہ انسان اپنے آپ کو دوسروں سے بہتر سمجھے، اور اپنی نیکیوں کو بہت بڑا کارنامہ خیال کرے۔ اور تکبر کی علامت یہ ہے کہ جب اس پر اپنی غلطی واضح ہو جائے تو وہ حق کی طرف رجوع کرنے میں انا اور عار محسوس کرے، اور غریبوں اور کمزوروں کو حقیر سمجھے۔ اور اس بیماری کا شافی علاج یہ ہے کہ وہ یہ یقین رکھے کہ اس کے پاس جو بھی علم، عزت اور نیکی کی توفیق ہے وہ محض اللہ کا فضل ہے اس کی اپنی قابلیت نہیں، اور اسے یہ معلوم نہیں کہ اس کا خاتمہ کس حال پر ہوگا؛ کیونکہ بسا اوقات لوگوں کی نظر میں ایک پراگندہ حال فقیر اللہ کے ہاں ایسے متکبر جیسے زمین بھر لوگوں سے زیادہ معزز اور محبوب ہوتا ہے!''', 'آداب النفوس امام حارث محاسبی کی وہ تصنیف ہے جس نے اسلامی علمِ نفسیات (سائیکالوجی) کی داغ بیل ڈالی۔ انہوں نے نفس کی باریک ترین فریب کاریوں کا پردہ چاک کیا۔', '[{"word":"رُؤْيَةُ","role":"خبر المبتدأ أصل مرفوع","sign":"ضمة","detail":"وهو مضاف والفضل مضاف إليه"},{"word":"خَيْرٌ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"اسم تفضيل"}]', '["آداب النفوس للحارث المحاسبي، ص 24-32، دار الجيل."]', '{"en":"Imam Al-Harith al-Muhasibi analyzes the anatomy of Arrogance (Kibr): Perceiving oneself superior to others and exalting one''s own deeds. Its symptoms include refusing to yield to truth when corrected and disdaining the vulnerable. Its cure is realizing every virtue is unearned divine favor.","ar":"التشخيص النفسي الدقيق لمرض الكبر وعلاجه بالافتقار إلى الله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adab_nufus_ch2_sidq', 'kharji_adab_nufus_muhasibi', 1, 'بَابُ الصِّدْقِ مَعَ اللَّهِ فِي السِّرِّ وَالعَلَنِ', 'باب 2: صدق — تنہائی اور جلوت میں اللہ کے ساتھ کھرا اور سچا رہنے کا طریقہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adab_nufus_seg_2_1', 'adab_nufus_ch2_sidq', 'kharji_adab_nufus_muhasibi', 0, '«الصِّدْقُ هُوَ: اسْتِوَاءُ السَّرِيرَةِ وَالعَلَانِيَةِ، بَلْ أَنْ تَكُونَ سَرِيرَةُ العَبْدِ أَحْسَنَ مِنْ عَلَانِيَتِهِ؛ فَمَنْ تَزَيَّنَ لِلنَّاسِ بِمَا لَيْسَ فِي قَلْبِهِ سَقَطَ مِنْ عَيْنِ اللَّهِ. قَالَ بَعْضُ الصَّالِحِينَ: مَثَلُ مَنْ يَعْمَلُ لِلنَّاسِ كَمَثَلِ مَنْ يَمْلَأُ جِرَابَهُ حَصًى ثُمَّ يَدْخُلُ السُّوقَ لِيَشْتَرِيَ بِهِ، فَيَقُولُ النَّاسُ: مَا أَمْلَأَ جِرَابَهُ! وَلَا يَنْفَعُهُ فِي الشِّرَاءِ شَيْئاً؛ كَذَلِكَ المُرَائِي لَا يَنَالُ مِنْ عَمَلِهِ إِلَّا مَدْحَ النَّاسِ بِلَا ثَوَابٍ».', 'امام حارث محاسبی فرماتے ہیں: ''سچائی اور صدق کی حقیقت یہ ہے کہ انسان کا باطن اور ظاہر بالکل ایک جیسا ہو، بلکہ انسان کا باطن اور اس کی خلوت اس کے ظاہری چہرے سے بھی زیادہ پاکیزہ اور خوبصورت ہو؛ پس جو شخص لوگوں کے سامنے اپنے آپ کو متقی ظاہر کرے جبکہ اس کے دل میں وہ تقویٰ نہ ہو تو وہ اللہ کی نظر سے گر جاتا ہے۔ کسی بزرگ نے فرمایا: لوگوں کو دکھانے کے لیے عمل کرنے والے کی مثال اس نادان شخص جیسی ہے جو اپنی تھیلی میں کنکریاں بھر لے اور بازار میں سودا خریدنے چلا جائے، لوگ دیکھ کر کہیں: واہ! اس کی تھیلی کتنی بھری ہوئی ہے! لیکن وہ کنکریاں سودا خریدنے میں ایک دمڑی کا بھی کام نہیں دیتیں؛ بالکل اسی طرح ریاکار کو اپنے عمل سے محض دنیا داروں کی عارضی تعریف ملتی ہے لیکن اللہ کے ہاں اس کے لیے رائی کے دانے کے برابر بھی ثواب نہیں ہوتا''۔', 'یہ مثال ریاکاری کی بے وقعتی کو انتہا درجے کی خوبصورتی کے ساتھ عیاں کرتی ہے کہ انسان فانی تعریف کے لیے دائمی اجر کو ضائع کر بیٹھتا ہے۔', '[{"word":"اسْتِوَاءُ","role":"خبر المبتدأ الصدق مرفوع","sign":"ضمة","detail":"وهو مضاف والسريرة مضاف إليه"},{"word":"شَيْئاً","role":"مفعول به أو نائب مفعول مطلق","sign":"فتحة","detail":"يفيد نفي النفع بالكلية"}]', '["آداب النفوس للمحاسبي، ص 60-68."]', '{"en":"The Essence of Truthfulness (Sidq): Congruence between privacy and publicity—indeed, one''s inner state should outshine outer appearances. A person acting for human praise is like one filling his bag with worthless pebbles; spectators admire its weight, but it buys nothing at the market.","ar":"حقيقة الصدق ومطابقة السر للعلن وضرب المثل لبطلان عمل المرائي."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ikhlas_ibn_abi_dunya', 'الإِخْلَاصُ وَالنِّيَّةُ', 'الحَافِظُ أَبُو بَكْرٍ ابْنُ أَبِي الدُّنْيَا القُرَشِيُّ (ت: 281ھ)', 'kharji_kitab', 'tazkiyah', 'اخلاص، صدقِ نیت اور عمل کی قبولیت کی روایات', 'کتبِ مطالعہ و اصلاحِ نیت', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'نیت کی طہارت اور اخلاص کے موضوع پر احادیثِ نبویہ اور سلف صالحین کے ارشادات کا قدیم ترین اور معتبر ترین مسند مجموعہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ikhlas_dunya_ch1_asl', 'kharji_ikhlas_ibn_abi_dunya', 0, 'بَابُ الإِخْلَاصِ وَالنِّيَّةِ الصَّادِقَةِ وَأَنَّهَا مِيزَانُ قَبُولِ الأَعْمَالِ', 'باب 1: اخلاص اور سچی نیت — اعمال کی مقبولیت کا الٰہی ترازو');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ikhlas_dunya_seg_1_1', 'ikhlas_dunya_ch1_asl', 'kharji_ikhlas_ibn_abi_dunya', 0, 'حَدَّثَنَا الحَافِظُ أَبُو بَكْرٍ عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ابْنُ أَبِي الدُّنْيَا قَالَ: حَدَّثَنَا أَبُو خَيْثَمَةَ، عَنْ سُفْيَانَ الثَّوْرِيِّ قَالَ: «مَا عَالَجْتُ شَيْئاً أَشَدَّ عَلَيَّ مِنْ نِيَّتِي؛ لِأَنَّهَا تَتَقَلَّبُ عَلَيَّ!». وَعَنْ مُطَرِّفِ بْنِ عَبْدِ اللَّهِ قَالَ: «صَلَاحُ القَلْبِ بِصَلَاحِ العَمَلِ، وَصَلَاحُ العَمَلِ بِصَلَاحِ النِّيَّةِ». وَقَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ».', 'حافظ ابو بکر عبد اللہ بن محمد ابن ابی الدنیا قرشی رحمہ اللہ بسندِ متصل روایت کرتے ہیں کہ امام سفیان ثوری رحمہ اللہ نے فرمایا: ''میں نے اپنی نیت سے زیادہ سرکش کسی چیز کا علاج نہیں کیا؛ کیونکہ نیت پل پل بدلتی رہتی ہے!'' اور مطرف بن عبد اللہ رحمہ اللہ فرماتے ہیں: ''دل کی درستی عمل کی درستی سے ہوتی ہے، اور عمل کی درستی نیت کی سچائی سے حاصل ہوتی ہے''۔ اور رسول اللہ ﷺ کا ارشادِ گرامی ہے: ''اللہ تعالیٰ تمہاری ظاہری صورتوں اور تمہارے مال و دولت کو نہیں دیکھتا، بلکہ وہ تمہارے دلوں کے اخلاص اور تمہارے اعمال کو دیکھتا ہے''۔', 'کتاب الإخلاص والنية امام ابن ابی الدنیا کی تیسری صدی ہجری کی وہ مستند کتاب ہے جس میں انہوں نے صحابہ اور تابعین کے ارشادات جمع کیے۔ سفیان ثوری کا مقولہ بتاتا ہے کہ نیت کی حفاظت ہر لمحے کی ریاضت ہے۔', '[{"word":"شَيْئاً","role":"مفعول به لعالجت منصوب","sign":"فتحة","detail":"أشد نعت لشيئاً"},{"word":"قُلُوبِكُمْ","role":"مجرور بإلى","sign":"كسرة","detail":"معطوف على المنظور إليه"}]', '["كتاب الإخلاص والنية لابن أبي الدنيا، رقم (1-5)، وأخرجه مسلم (2564)."]', '{"en":"Hafiz Ibn Abi ad-Dunya''s classic treatise on Sincerity: Sufyan ath-Thawri confessed: ''I never treated anything more stubborn than my intention, for it fluctuates incessantly!'' The Prophet ﷺ declared: ''Allah looks not at your forms or wealth, but at your hearts and deeds.''","ar":"مركزية القلب والنية في ميزان الحساب الإلهي وتقلبات النيات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ikhlas_dunya_ch2_fawaid', 'kharji_ikhlas_ibn_abi_dunya', 1, 'بَابُ نِيَّةِ المُؤْمِنِ خَيْرٌ مِنْ عَمَلِهِ وَبَرَكَةِ الصِّدْقِ فِي الخَفَاءِ', 'باب 2: ''مؤمن کی نیت اس کے عمل سے بہتر ہے'' اور مخفی نیکیوں کی برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ikhlas_dunya_seg_2_1', 'ikhlas_dunya_ch2_fawaid', 'kharji_ikhlas_ibn_abi_dunya', 0, '«عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنْ سَأَلَ اللَّهَ الشَّهَادَةَ بِصِدْقٍ بَلَّغَهُ اللَّهُ مَنَازِلَ الشُّهَدَاءِ، وَإِنْ مَاتَ عَلَى فِرَاشِهِ». وَقَالَ يَحْيَى بْنُ أَبِي كَثِيرٍ: «تَعَلَّمُوا النِّيَّةَ؛ فَإِنَّهَا أَبْلَغُ مِنَ العَمَلِ». فَإِنَّ العَبْدَ يَبْلُغُ بِنِيَّتِهِ الصَّالِحَةِ مَا لَا يَبْلُغُهُ بِبَدَنِهِ إِذَا عَجَزَ؛ فَمَنْ نَوَى قِيَامَ اللَّيْلِ فَغَلَبَتْهُ عَيْنَاهُ كُتِبَ لَهُ أَجْرُ قِيَامِهِ كَامِلاً، وَكَانَ نَوْمُهُ صَدَقَةً عَلَيْهِ مِنْ رَبِّهِ».', 'ابن ابی الدنیا روایت کرتے ہیں: حضرت سہل بن حنیف رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''جس شخص نے سچے دل سے اللہ تعالیٰ سے شہادت کی موت مانگی، تو اللہ تعالیٰ اسے شہداء کے بلند ترین درجات پر پہنچا دے گا اگرچہ وہ اپنے بستر پر ہی طبعی موت کیوں نہ مرے!'' اور یحییٰ بن ابی کثیر فرماتے ہیں: ''نیت کرنا اور اس کی روح کو سیکھو؛ کیونکہ نیت کا تیر عمل سے بھی زیادہ دور تک پہنچتا ہے''۔ پس بلاشبہ مومن بندہ اپنی سچی نیت کے ذریعے ان درجات تک پہنچ جاتا ہے جہاں وہ اپنے جسم کی کمزوری یا مجبوری کے سبب نہیں پہنچ سکتا تھا؛ چنانچہ جس شخص نے رات کو تہجد پڑھنے کی نیت کی اور نیند کا غلبہ ہو گیا تو اللہ کی بارگاہ سے اس کے لیے پوری رات کے قیام کا ثواب لکھ دیا جاتا ہے، اور اس کا سونا اس کے رب کی طرف سے اس کے لیے انعام اور صدقہ بن جاتا ہے''۔', 'نیت اللہ کی وہ رحمت ہے جس کے ذریعے ایک غریب، بیمار یا کمزور انسان بھی بڑے بڑے مجاہدین اور سخیوں کے اجر کو پا لیتا ہے اگر اس کا دل سچا ہو۔', '[{"word":"الشَّهَادَةَ","role":"مفعول به لسأل منصوب","sign":"فتحة","detail":"بصدق جار ومجرور حال"},{"word":"أَجْرُ","role":"نائب فاعل لكُتب مرفوع","sign":"ضمة","detail":"وهو مضاف وقيامه مضاف إليه"}]', '["كتاب الإخلاص والنية، رقم (22-28)، وأخرجه مسلم (1909)."]', '{"en":"The supremacy of Intention: ''Whoever sincerely asks Allah for martyrdom, Allah elevates him to the ranks of martyrs even if he dies in his bed.'' An incapacitated believer attains via pure intention what his physical body cannot achieve.","ar":"فضل النية الصادقة وبلوغ منازل الأبرار بعقد القلب السليم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tadhkirat_sami_kinani', 'تَذْكِرَةُ السَّامِعِ وَالمُتَكَلِّمِ فِي أَدَبِ العَالِمِ وَالمُتَعَلِّمِ', 'قَاضِي القُضَاةِ بَدْرُ الدِّينِ ابْنُ جَمَاعَةَ الكِنَانِيُّ (ت: 733ھ)', 'kharji_kitab', 'adab', 'استاد اور شاگرد کے آداب، کتب بینی کے اصول', 'کتبِ مطالعہ و آدابِ تعلیم (لازمی نصاب)', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'استاد کا احترام، درسگاہ کے آداب، سبق کی تیاری، اور کتابوں کے رکھنے اور مطالعہ کرنے کے زریں اصول۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kinani_ch1_adab_alim', 'kharji_tadhkirat_sami_kinani', 0, 'البَابُ الأَوَّلُ: فِي آدَابِ العَالِمِ فِي نَفْسِهِ وَمَعَ طَلَبَتِهِ', 'باب 1: استاد اور عالم کے ذاتی آداب اور شاگردوں کے ساتھ شفقت و ہمدردی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kinani_seg_1_1', 'kinani_ch1_adab_alim', 'kharji_tadhkirat_sami_kinani', 0, 'قَالَ قَاضِي القُضَاةِ بَدْرُ الدِّينِ ابْنُ جَمَاعَةَ الكِنَانِيُّ: «يَنْبَغِي لِلْعَالِمِ أَنْ يَقْصِدَ بِتَعْلِيمِهِ وَجْهَ اللَّهِ تَعَالَى، لَا لِيَنَالَ بِهِ عَرَضاً دُنْيَوِيّاً مِنْ مَالٍ أَوْ جَاهٍ أَوْ شُهْرَةٍ. وَأَنْ يُعَامِلَ طَلَبَتَهُ بِمَا يُعَامِلُ بِهِ أَعَزَّ أَوْلَادِهِ: مِنَ العَطْفِ، وَالشَّفَقَةِ، وَالصَّبْرِ عَلَى جَفَائِهِمْ، وَحِرْصِهِ عَلَى تَفْهِيمِهِمْ بِحَسَبِ عُقُولِهِمْ؛ فَلَا يَطْرَحُ لِلْمُبْتَدِئِ مَا لَا يَحْتَمِلُهُ، وَلَا يُقَصِّرُ مَعَ المُنْتَهِي فِيمَا يَطْلُبُهُ. وَأَنْ يَكُونَ مِثَالاً لَهُمْ فِي الزُّهْدِ، وَالتَّوَاضُعِ، وَطَهَارَةِ البَاطِنِ».', 'قاضی القضاۃ بدر الدین محمد بن ابراہیم ابن جماعہ کنانی رحمہ اللہ فرماتے ہیں: ''استاد اور عالم پر لازم ہے کہ وہ اپنے درس و تدریس سے خالص اللہ کی خوشنودی کا ارادہ کرے، نہ کہ دنیاوی مال، عہدہ یا شہرت کا لالچ رکھے۔ اور اپنے شاگردوں کے ساتھ ایسا مشفقانہ سلوک کرے جیسا وہ اپنے سب سے چہیتے بچوں کے ساتھ کرتا ہے: یعنی ان پر شفقت و مہربانی کرنا، ان کی بداخلاقی و نادانی پر صبر کرنا، اور ان کی ذہنی استعداد کے مطابق انہیں سمجھانے کی پوری کوشش کرنا؛ پس مبتدی طالب علم کے سامنے ایسے باریک مسائل نہ ڈالے جن کا اس کا ذہن متحمل نہ ہو سکے، اور نہ ہی منتہی طالب علم کو اس کے مطلوبہ علمی مقام سے محروم رکھے۔ اور ان کے لیے زہد، عاجزی اور پاکیزگی کا عملی نمونہ بنے''۔', 'تذكرة السامع والمتكلم في أدب العالم والمتعلم اسلامی تعلیم و تربیت اور تدریسی آداب پر لکھی جانے والی سب سے جامع نصابی کتاب ہے۔', '[{"word":"وَجْهَ","role":"مفعول به ليقصد منصوب","sign":"فتحة","detail":"وهو مضاف ولفظ الجلالة مضاف إليه"},{"word":"مِثَالاً","role":"خبر كان منصوب","sign":"فتحة","detail":"واسم كان ضمير مستتر"}]', '["تذكرة السامع والمتكلم لابن جماعة الكناني، ص 25-36، دار البشائر."]', '{"en":"Ibn Jama''ah''s classic pedagogue guide: The teacher must dedicate instruction solely to Allah, treating students with the tenderness bestowed upon one''s dearest children—bearing their roughness, adapting lessons to their cognitive capacities, and exemplifying humility.","ar":"آداب المعلم الرباني ومراعاته الفروق الفردية بين المتعلمين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kinani_ch2_adab_mutaallim', 'kharji_tadhkirat_sami_kinani', 1, 'البَابُ الثَّانِي: فِي آدَابِ المُتَعَلِّمِ مَعَ شَيْخِهِ وَكُتُبِهِ وَدَرْسِهِ', 'باب 2: طالب علم کے اپنے استاد کے ساتھ آداب اور درس گاہ کی حرمت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kinani_seg_2_1', 'kinani_ch2_adab_mutaallim', 'kharji_tadhkirat_sami_kinani', 0, '«يَنْبَغِي لِلطَّالِبِ أَنْ يَنْظُرَ إِلَى شَيْخِهِ بِعَيْنِ الإِجْلَالِ وَالتَّعْظِيمِ؛ فَإِنَّ ذَلِكَ أَقْرَبُ إِلَى نَفْعِهِ بِهِ. وَلَا يُخَاطِبَهُ بِاسْمِهِ مُجَرَّداً، بَلْ يَقُولُ: يَا سَيِّدِي أَوْ يَا أُسْتَاذِي. وَلَا يَمْشِي أَمَامَهُ إِلَّا لِضَرُورَةٍ، وَلَا يَجْلِسَ مَكَانَهُ، وَلَا يَقْطَعَ عَلَيْهِ كَلَامَهُ، وَإِذَا رَأَى مِنْهُ هَفْوَةً لَمْ يُسْقِطْهُ ذَلِكَ مِنْ عَيْنِهِ؛ فَإِنَّ العَالِمَ غَيْرُ مَعْصُومٍ. وَعَلَيْهِ بِتَعْظِيمِ الكُتُبِ؛ فَلَا يَضَعْهَا عَلَى الأَرْضِ، وَلَا يَجْعَلْ فَوْقَ المُصْحَفِ شَيْئاً أَبَداً».', 'ابن جماعہ فرماتے ہیں: ''طالب علم پر لازم ہے کہ وہ اپنے استاد کو ہمیشہ ادب اور احترام کی نظر سے دیکھے؛ کیونکہ استاد کی جتنی تعظیم دل میں ہوگی اتنا ہی اس کے علم سے نفع حاصل ہوگا۔ اور استاد کو کبھی اس کے نام سے پکار کر خطاب نہ کرے، بلکہ ادب سے ''یا سیدی'' یا ''یا استادی'' کہے۔ اور ضرورت کے بغیر استاد کے آگے آگے نہ چلے، اس کی خاص نشست پر نہ بیٹھے، اس کی گفتگو کے درمیان میں اپنی بات نہ کاٹے، اور اگر استاد سے بشری تقاضے کے تحت کوئی لغزش نظر آ جائے تو اس کی وجہ سے استاد کو دل سے نہ گرائے؛ کیونکہ سوائے انبیاء کے کوئی عالم معصوم نہیں ہوتا۔ اور طالب علم پر کتابوں کا ادب بھی لازم ہے؛ کتابوں کو زمین پر نہ پھینکے، اور قرآنِ مجید کے اوپر کسی بھی دوسری کتاب یا چیز کو ہرگز نہ رکھے''۔', 'باادب با نصیب، بے ادب بے نصیب! ابن جماعہ نے واضح کیا کہ علم صرف دماغی یادداشت سے نہیں بلکہ استاد کے ادب اور کتابوں کی حرمت کے نتیجے میں دل میں اترتا ہے۔', '[{"word":"أَقْرَبُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"ذلك اسمها وأقرب خبرها"},{"word":"مَعْصُومٍ","role":"مضاف إليه مجرور","sign":"كسرة","detail":"غير مضاف ومعصوم مضاف إليه"}]', '["تذكرة السامع والمتكلم، ص 85-98."]', '{"en":"Etiquette of the student toward the mentor: Gazing upon the teacher with veneration, addressing him honorifically, refraining from interrupting, excusing occasional human lapses, and upholding the physical sanctity of books—never placing anything atop the Mushaf.","ar":"حرمة الشيخ وتوقير أدوات العلم والكتب الشرعية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_jami_bayan_ilm_qurtubi', 'جَامِعُ بَيَانِ العِلْمِ وَفَضْلِهِ وَمَا يَنْبَغِي فِي رِوَايَتِهِ وَحَمْلِهِ', 'الإِمَامُ أَبُو عُمَرَ يُوسُفُ ابْنُ عَبْدِ البَرِّ القُرْطُبِيُّ (ت: 463ھ)', 'kharji_kitab', 'adab', 'فضیلتِ علم، آدابِ روایت و فقاہت', 'کتبِ مطالعہ و اصولِ علم', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'اندلس کے عظیم محدث امام ابن عبد البر کی فضیلتِ علم اور طلبۂ علم کی ذمہ داریوں پر بے نظیر کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jami_bayan_ch1_fadl_ilm', 'kharji_jami_bayan_ilm_qurtubi', 0, 'بَابُ فَضْلِ العِلْمِ وَالعُلَمَاءِ وَحَمَلَةِ الشَّرِيعَةِ فِي الإِسْلَامِ', 'باب 1: علم کی برتری اور حاملینِ شریعت علماء کا بلند ترین مقام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jami_bayan_seg_1_1', 'jami_bayan_ch1_fadl_ilm', 'kharji_jami_bayan_ilm_qurtubi', 0, 'قَالَ الإِمَامُ الحَافِظُ ابْنُ عَبْدِ البَرِّ القُرْطُبِيُّ: «رَوَى أَبُو الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ سَلَكَ طَرِيقاً يَبْتَغِي فِيهِ عِلْماً سَلَكَ اللَّهُ بِهِ طَرِيقاً إِلَى الجَنَّةِ، وَإِنَّ المَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا رِضاً لِطَالِبِ العِلْمِ، وَإِنَّ العَالِمَ لَيَسْتَغْفِرُ لَهُ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الأَرْضِ حَتَّى الحِيتَانُ فِي المَاءِ، وَفَضْلُ العَالِمِ عَلَى العَابِدِ كَفَضْلِ القَمَرِ عَلَى سَائِرِ الكَوَاكِبِ، وَإِنَّ العُلَمَاءَ وَرَثَةُ الأَنْبِيَاءِ».', 'امام حافظ ابو عمر یوسف بن عبد البر قرطبی رحمہ اللہ فرماتے ہیں: حضرت ابو درداء رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ ﷺ کو فرماتے ہوئے سنا: ''جو شخص علم حاصل کرنے کے راستے پر چلا اللہ اس کے لیے جنت کا راستہ آسان فرما دیتا ہے، اور فرشتے طالب علم کی خوشنودی کے لیے اپنے پر بچھا دیتے ہیں، اور عالم کے لیے آسمانوں اور زمین کی تمام مخلوقات دعائے مغفرت کرتی ہیں یہاں تک کہ پانی کے اندر مچھلیاں بھی اس کے لیے دعا کرتی ہیں، اور عالم کی فضیلت عابد پر ایسی ہے جیسے چودھویں کے چاند کی فضیلت تمام ستاروں پر ہوتی ہے، اور بلاشبہ علماء ہی انبیاء کے وارث ہیں''۔', 'جامع بيان العلم وفضله علم کی فضیلت، آداب اور مناہج پر لکھی جانے والی امہات الکتب میں سے ہے۔ ابن عبد البر نے اس حدیث کی روشنی میں ثابت کیا کہ علمِ دین حاصل کرنا دنیا کی سب سے بڑی نیکی ہے۔', '[{"word":"طَرِيقاً","role":"مفعول به لسلك منصوب","sign":"فتحة","detail":"طريقاً الثانية مفعول به ثانٍ"},{"word":"وَرَثَةُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"العلماء اسمها وورثة خبرها"}]', '["جامع بيان العلم وفضله لابن عبد البر، 1/ 32-45، وأخرجه أبو داود (3641)."]', '{"en":"Hafiz Ibn ''Abd al-Barr records the supreme status of sacred knowledge: ''Whoever treads a path seeking knowledge, Allah directs him to a path toward Paradise... The scholar''s superiority over the mere devout worshiper is like the moon over all stars, and the scholars are the heirs of the Prophets.''","ar":"تأصيل فضل طلب العلم الشرعي واستغفار الكائنات لمعلم الناس الخير."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jami_bayan_ch2_ijma_ikhtilaf', 'kharji_jami_bayan_ilm_qurtubi', 1, 'بَابُ الإِجْمَاعِ وَالِاخْتِلَافِ: مَنْ عَرَفَ الِاخْتِلَافَ اتَّسَعَ صَدْرُهُ', 'باب 2: اجماع اور اختلاف — جو ائمہ کے فقہی اختلاف کو پہچان لے اس کا سینہ کشادہ ہو جاتا ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jami_bayan_seg_2_1', 'jami_bayan_ch2_ijma_ikhtilaf', 'kharji_jami_bayan_ilm_qurtubi', 0, '«قَالَ ابْنُ عَبْدِ البَرِّ: قَالَ عُمَرُ بْنُ عَبْدِ العَزِيزِ: «مَا يَسُرُّنِي أَنَّ أَصْحَابَ مُحَمَّدٍ ﷺ لَمْ يَخْتَلِفُوا؛ لِأَنَّهُمْ لَوْ لَمْ يَخْتَلِفُوا لَمْ تَكُنْ رُخْصَةٌ!». وَقَالَ قَتَادَةُ: «مَنْ لَمْ يَعْرِفِ الِاخْتِلَافَ لَمْ يَشَمَّ أَنْفُهُ الفِقْهَ!». فَإِنَّ مَعْرِفَةَ أَقْوَالِ الفُقَهَاءِ وَمَآخِذِهِمْ تُورِثُ الفَقِيهَ سَعَةَ الصَّدْرِ، وَتَمْنَعُهُ مِنَ التَّعَصُّبِ المَذْهَبِيِّ المَقِيتِ، وَتَجْعَلُهُ يَلْتَمِسُ الأَعْذَارَ لِلأَئِمَّةِ الأَعْلَامِ إِذَا اخْتَلَفُوا فِي الفُرُوعِ الِاجْتِهَادِيَّةِ».', 'حافظ ابن عبد البر فرماتے ہیں: خلیفہ راشد عمر بن عبد العزیز رحمہ اللہ نے فرمایا تھا: ''مجھے اس بات سے کوئی خوشی نہ ہوتی اگر صحابۂ کرام آپس میں فروعی مسائل میں اختلاف نہ فرماتے؛ کیونکہ اگر وہ اختلاف نہ کرتے تو امت کے لیے کسی مسئلے میں کوئی وسعت اور رخصت نہ رہتی!'' اور امام قتادہ فرماتے ہیں: ''جس نے ائمہ کے باہمی اختلاف اور اس کے دلائل کو نہیں جانا اس کی ناک نے فقہ کی خوشبو تک نہیں سونگھی!'' کیونکہ فقہاء کے اقوال اور ان کے دلائل کو جاننا انسان کے اندر وسعتِ ظرف پیدا کرتا ہے، اسے تنگ نظر تعصب سے بچاتا ہے، اور وہ اجتہادی مسائل میں ائمہ کے لیے عذر تلاش کرتا ہے اور ہر ایک کی قدر کرتا ہے''۔', 'یہ بصیرت تنگ نظری کا سب سے بڑا علاج ہے۔ جو شخص ائمہ کے دلائل کو سمجھتا ہے وہ کبھی دوسرے مسلمانوں پر کفر یا گمراہی کے فتوے نہیں لگاتا۔', '[{"word":"رُخْصَةٌ","role":"اسم تكن مؤخر مرفوع","sign":"ضمة","detail":"لم تكن تامة أو ناقصة ورخصة اسمها"},{"word":"الفِقْهَ","role":"مفعول به ليشم منصوب","sign":"فتحة","detail":"أنفه فاعل مرفوع"}]', '["جامع بيان العلم وفضله، 2/ 885-895."]', '{"en":"Understanding scholarly divergence: ''Umar bin ''Abd al-''Aziz rejoiced that the Sahabah differed in secondary branches because their variations created legitimate dispensations for the Ummah. Qatadah remarked: ''Whoever knows not differences has not inhaled the fragrance of Fiqh.''","ar":"فقه الخلاف وسعة الأفق ونبذ التعصب الأعمى للآراء الفردية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_akhlaq_ulama_ajurri', 'أَخْلَاقُ العُلَمَاءِ', 'الإِمَامُ أَبُو بَكْرٍ مُحَمَّدُ بْنُ الحُسَيْنِ الآجُرِّيُّ (ت: 360ھ)', 'kharji_kitab', 'adab', 'اخلاق و اوصافِ حاملینِ علمِ دین', 'کتبِ مطالعہ و تربیتِ طلبہ', NULL, NULL, 'from-stone-900 via-emerald-950 to-teal-950', NULL, 'چوتھی صدی ہجری کے عظیم محدث امام آجری کا طلبۂ علم اور علماء کے لیے نصیحت آموز آئینہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ajurri_ch1_akhlaq', 'kharji_akhlaq_ulama_ajurri', 0, 'بَابُ أَخْلَاقِ العُلَمَاءِ الرَّبَّانِيِّينَ فِي أَنْفُسِهِمْ وَمُعَامَلَاتِهِمْ', 'باب 1: علمائے ربانیین کے اعلیٰ اخلاق — حلم، وقار، تواضع اور للہیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ajurri_seg_1_1', 'ajurri_ch1_akhlaq', 'kharji_akhlaq_ulama_ajurri', 0, 'قَالَ الإِمَامُ أَبُو بَكْرٍ مُحَمَّدُ بْنُ الحُسَيْنِ الآجُرِّيُّ: «يَنْبَغِي لِمَنْ عَلَّمَهُ اللَّهُ كِتَابَهُ وَفَقَّهَهُ فِي دِينِهِ أَنْ يَكُونَ مَوْصُوفاً بِأَخْلَاقِ الأَنْبِيَاءِ: حَلِيماً رَحِيماً، عَفِيفاً نَزِيهاً، قَلِيلَ الكَلَامِ إِلَّا فِيمَا يَعْنِيهِ، مُتَوَاضِعاً لِلْفُقَرَاءِ، غَيْرَ خَاضِعٍ لِلْأَغْنِيَاءِ وَالكُبَرَاءِ. إِذَا جَلَسَ فِي مَجْلِسِهِ جَلَسَ بِالوَقَارِ وَالسَّكِينَةِ، لَا يَفْخَرُ بِعِلْمِهِ، وَلَا يَسْتَطِيلُ عَلَى أَحَدٍ، بَلْ يَرَى الفَضْلَ كُلَّهُ لِلَّهِ عَلَيْهِ إِذْ وَفَّقَهُ وَلَمْ يَكِلْهُ إِلَى نَفْسِهِ طَرْفَةَ عَيْنٍ».', 'امام ابو بکر محمد بن حسین الآجری بغدادی رحمہ اللہ فرماتے ہیں: ''جس خوش نصیب کو اللہ نے اپنی کتاب کا علم بخشا اور اپنے دین کی فقہ عطا فرمائی اس پر واجب ہے کہ وہ انبیاء کے اعلیٰ اخلاق کا پیکر ہو: بردبار، نرم دل، انتہائی پاک دامن، غیر ضروری باتوں سے خاموش رہنے والا، غریبوں کے ساتھ خاکسار اور متواضع، اور دنیا دار مالداروں کے سامنے کبھی نہ جھکنے والا۔ جب وہ اپنی درس گاہ میں بیٹھے تو وقار اور سنجیدگی کے ساتھ بیٹھے، اپنے علم پر اترائے نہیں، کسی پر برتری نہ جتائے، بلکہ ہر لمحہ یہ سمجھے کہ سارا فضل صرف اللہ کا ہے جس نے اسے نیکی کی توفیق بخشی اور اسے ایک پل کے لیے بھی اس کے نفس کے حوالے نہیں کیا''۔', 'أخلاق العلماء امام آجری کی چوتھی صدی ہجری کی وہ تصنیف ہے جس نے اہلِ علم کے لیے ایسا آئینہ رکھا جس میں ہر طالب علم اور مفتی اپنا باطن جھانک سکتا ہے۔', '[{"word":"حَلِيماً","role":"خبر كان منصوب","sign":"فتحة","detail":"واسم كان ضمير مستتر يعود على من"},{"word":"الفَضْلَ","role":"مفعول به ليرى منصوب","sign":"فتحة","detail":"كله توكيد معنوي"}]', '["أخلاق العلماء للآجري، ص 30-42، دار الغرب الإسلامي."]', '{"en":"Imam Al-Ajurri outlines the ethos of godly scholars: Embodying prophetic forbearance, chastity, measured speech, tender humility before the impoverished, uncompromising dignity before the opulent, and attributing all success to Allah alone.","ar":"شمائل العالم الرباني وترفعه عن مطامع الدنيا وممالأة أصحاب الثروات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ajurri_ch2_talab_dunya', 'kharji_akhlaq_ulama_ajurri', 1, 'التَّحْذِيرُ مِنْ طَلَبِ الدُّنْيَا بِالعِلْمِ وَمُمَالَأَةِ السَّلَاطِينِ', 'باب 2: علم کو دنیا کمانے کا ذریعہ بنانے اور سلاطین کی خوشامد کرنے کی سخت ممانعت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ajurri_seg_2_1', 'ajurri_ch2_talab_dunya', 'kharji_akhlaq_ulama_ajurri', 0, '«قَالَ الآجُرِّيُّ: احْذَرْ رَحِمَكَ اللَّهُ أَنْ تَكُونَ مِمَّنْ يَطْلُبُ العِلْمَ لِيُقَالَ: فُلَانٌ عَالِمٌ، أَوْ لِيُجَالِسَ الأُمَرَاءَ فَيَنَالَ دُنْيَاهُمْ؛ فَقَدْ رُوِيَ عَنِ النَّبِيِّ ﷺ أَنَّهُ قَالَ: «مَنْ طَلَبَ العِلْمَ لِيُجَارِيَ بِهِ العُلَمَاءَ، أَوْ لِيُمَارِيَ بِهِ السُّفَهَاءَ، أَوْ يَصْرِفَ بِهِ وُجُوهَ النَّاسِ إِلَيْهِ، أَدْخَلَهُ اللَّهُ النَّارَ!». فَمَنْ كَانَ هَذَا قَصْدَهُ فَقَدْ خَسِرَ خُسْرَاناً مُبِيناً، وَصَارَ عِلْمُهُ حُجَّةً عَلَيْهِ يَوْمَ القِيَامَةِ».', 'امام آجری فرماتے ہیں: ''اللہ تم پر رحم فرمائے! اس بات سے سخت بچو کہ تم ان لوگوں میں شامل ہو جاؤ جو علم اس لیے سیکھتے ہیں تاکہ دنیا کہے: فلاں بڑا عالم ہے! یا حکمرانوں کے درباروں میں بیٹھ کر ان کی دولت کے ٹکڑے سمیٹیں؛ کیونکہ نبی کریم ﷺ سے مروی ہے کہ آپ نے فرمایا: ''جس شخص نے علم اس لیے سیکھا تاکہ وہ علماء پر اپنی برتری جتائے، یا جاہلوں اور بے وقوفوں سے مناظرے بازی کرے، یا لوگوں کے چہرے اپنی طرف متوجہ کرے، تو اللہ اسے جہنم میں داخل فرمائے گا!'' پس جس کی نیت یہ غلیظ ہوئی وہ کھلے خسارے میں پڑ گیا اور اس کا یہی علم قیامت کے دن اس کے خلاف سب سے بڑی سزا کا ثبوت بن جائے گا''۔', 'علم نبوت کی امانت ہے۔ اگر اسے پیسے یا سستی شہرت کی بھینٹ چڑھا دیا جائے تو انسان ان پہلے تین بدبختوں میں شامل ہوگا جن سے جہنم کو بھڑکایا جائے گا۔', '[{"word":"خُسْرَاناً","role":"مفعول مطلق منصوب","sign":"فتحة","detail":"مبيناً نعت له"},{"word":"حُجَّةً","role":"خبر صار منصوب","sign":"فتحة","detail":"واسمها علمه"}]', '["أخلاق العلماء، ص 78-85، وأخرجه الترمذي (2654)."]', '{"en":"Stern warning against utilizing knowledge for worldly acclaim: ''Whoever acquires knowledge to compete with scholars, dispute with fools, or captivate people''s attention, Allah will cast him into the Fire.''","ar":"الوعيد الشديد فيمن جعل العلم الديني سلعة للمناصب والجاه الدنيوي."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_hilyat_talib_ilm', 'حِلْيَةُ طَالِبِ العِلْمِ', 'العَلَّامَةُ الشَّيْخُ بَكْرُ بْنُ عَبْدِ اللَّهِ أَبُو زَيْدٍ (ت: 1429ھ)', 'kharji_kitab', 'adab', 'طلبۂ علومِ دینیہ کے لیے دورِ حاضر کا ضابطۂ حیات', 'کتبِ مطالعہ و دستورِ زندگی', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'عصرِ حاضر کے طلبۂ علم کے لیے آداب، مطالعے کے طریقوں، اساتذہ کے احترام اور وقت کی حفاظت کا سب سے مقبول رسالہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hilyat_talib_ch1_adab', 'kharji_hilyat_talib_ilm', 0, 'حِلْيَةُ طَالِبِ العِلْمِ: تَطْهِيرُ البَاطِنِ وَسَمْتُ أَهْلِ الحَدِيثِ', 'باب 1: طالب علم کا زیور — باطن کی پاکیزگی اور محدثین جیسا باوقار کردار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hilyat_talib_seg_1_1', 'hilyat_talib_ch1_adab', 'kharji_hilyat_talib_ilm', 0, 'قَالَ العَلَّامَةُ الشَّيْخُ بَكْرُ بْنُ عَبْدِ اللَّهِ أَبُو زَيْدٍ: «تَحَلَّ بِحِلْيَةِ طَالِبِ العِلْمِ فِي نَفْسِكَ: بِالإِخْلَاصِ الصَّادِقِ، وَمُرَاقَبَةِ اللَّهِ فِي السِّرِّ وَالعَلَنِ، وَخَفْضِ الجَنَاحِ، وَالقَنَاعَةِ وَالزُّهْدِ. وَاعْلَمْ أَنَّ العِلْمَ عِبَادَةٌ مِنَ العِبَادَاتِ، بَلْ مِنْ أَجَلِّ القُرُبَاتِ؛ فَإِذَا فَقَدَ الإِخْلَاصَ انْتَقَلَ مِنْ أَعْظَمِ الطَّاعَاتِ إِلَى أَحَطِّ الدَّرَكَاتِ. وَكُنْ عَلَى جَادَّةِ السَّلَفِ الصَّالِحِ فِي السَّمْتِ الصَّالِحِ، وَالهَدْيِ الرَّشِيدِ، وَتَرْكِ الخَوْضِ فِيمَا لَا يَعْنِي».', 'علامہ شیخ بکر بن عبد اللہ ابو زید رحمہ اللہ فرماتے ہیں: ''اپنے آپ کو طالب علم کے حقیقی زیور سے آراستہ کرو: سچے اخلاص کے ساتھ، خلوت و جلوت میں اللہ کے دھیان اور مراقبے کے ساتھ، عاجزی اور انکساری کے ساتھ، اور قناعت و زہد کے ساتھ۔ اور خوب جان لو کہ علم کی طلب بذاتِ خود ایک عظیم عبادت ہے، بلکہ اعلیٰ ترین نیکیوں میں سے ہے؛ پس جب اس میں اخلاص نہ رہے تو یہ سب سے بڑی طاعت سے گر کر ہلاکت کے سب سے نچلے گڑھے میں تبدیل ہو جاتی ہے۔ اور اپنی روش، طور طریقوں اور وقار میں سلف صالحین کے راستے پر چلو، اور فضول لایعنی مباحث میں پڑنے سے بچو''۔', 'حلية طالب العلم معاصر دور میں طلبۂ علم کے آداب اور تربیت کی سب سے معتمد اور مقبول کتاب ہے جس کی شرح شیخ ابن عثیمین نے فرمائی ہے۔', '[{"word":"حِلْيَةِ","role":"مجرور بالباء","sign":"کسرة","detail":"وهو مضاف وطالب مضاف إليه"},{"word":"عِبَادَةٌ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"العلم اسمها وعبادة خبرها"}]', '["حلية طالب العلم لبكر بن عبد الله أبو زيد، ص 10-18."]', '{"en":"Shaykh Bakr Abu Zayd''s contemporary classic ''Hilyat Talib al-''Ilm'': Knowledge is an act of worship. Adorn yourself with sincerity, vigilant God-consciousness in privacy, gentle humility, contentment, and the serene demeanour of the pious predecessors.","ar":"المعالم السلوكية والأخلاقية لطالب العلم الشرعي في عصر الفتن."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('hilyat_talib_ch2_talaqqi', 'kharji_hilyat_talib_ilm', 1, 'أَخْذُ العِلْمِ عَنِ الأَشْيَاخِ وَالحَذَرُ مِنْ «صَحَفِيِّ الكُتُبِ»', 'باب 2: علم شیوخ اور اساتذہ کے زانوئے تلمذ طے کر کے حاصل کرنا، نہ کہ محض کتابی مطالعے سے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('hilyat_talib_seg_2_1', 'hilyat_talib_ch2_talaqqi', 'kharji_hilyat_talib_ilm', 0, '«مِنْ أَعْظَمِ قَوَاعِدِ التَّحْصِيلِ: أَنْ تَأْخُذَ العِلْمَ عَنِ الأَشْيَاخِ المُتْقِنِينَ لَا مِنْ بُطُونِ الصُّحُفِ وَالكُتُبِ وَحْدَهَا؛ فَإِنَّ مَنْ كَانَ شَيْخُهُ كِتَابَهُ كَانَ خَطَؤُهُ أَكْثَرَ مِنْ صَوَابِهِ! وَكَمَا قِيلَ: «لَا تَأْخُذِ القُرْآنَ مِنْ مُصْحَفِيٍّ، وَلَا الحَدِيثَ مِنْ صَحَفِيٍّ»؛ لِأَنَّ الكُتُبَ تَحْتَمِلُ التَّصْحِيفَ وَالتَّحْرِيفَ، وَالأُسْتَاذُ يُعْطِيكَ المَلَكَةَ وَالسَّمْتَ وَالفَهْمَ الدَّقِيقَ الَّذِي لَا تَجِدُهُ فِي السُّطُورِ».', 'علامہ بکر ابو زید فرماتے ہیں: ''علم حاصل کرنے کا سب سے عظیم اور اساسی اصول یہ ہے کہ علم ماہر اور پختہ کار اساتذہ کے روبرو بیٹھ کر حاصل کیا جائے، نہ کہ محض کتابوں کے اوراق پلٹ کر؛ کیونکہ جس کا استاد صرف اس کی کتاب ہو اس کی غلطیاں اس کی درست باتوں سے کہیں زیادہ ہوتی ہیں! جیسا کہ سلف کا زریں مقولہ ہے: ''نہ تو قرآن کسی ایسے شخص سے پڑھو جس نے صرف مصحف دیکھ کر پڑھا ہو (استاد سے نہ سیکھا ہو)، اور نہ حدیث کسی ایسے سے سیکھو جو صرف کتابیں پڑھ کر محدث بنا ہو!'' کیونکہ کتابوں میں کتابت کی غلطی ہو سکتی ہے، جبکہ باعمل استاد تمہیں وہ فکری ملکہ، اخلاقی وقار اور دقیق فہم عطا کرتا ہے جو کتابوں کی سطروں میں کہیں نہیں ملتا''۔', 'صرف انٹرنیٹ یا کتابوں سے علامہ بننے والے لوگ اکثر گمراہی پھیلاتے ہیں۔ حقیقی علم استاد کی صحبت اور ادب سے ہی حاصل ہوتا ہے۔', '[{"word":"خَطَؤُهُ","role":"اسم كان مؤخر مرفوع","sign":"ضمة","detail":"أكثر خبرها مقدم"},{"word":"المَلَكَةَ","role":"مفعول به ثان ليعطيك منصوب","sign":"فتحة","detail":"والكاف مفعول أول"}]', '["حلية طالب العلم، ص 35-42."]', '{"en":"Acquiring knowledge directly from verified masters rather than solely from books: ''He whose teacher is only his book will have more errors than correct understandings.'' A living teacher transmits the subtle analytical methodology and character.","ar":"أهمية التلقي المباشر والمشافهة في حفظ الصنعة العلمية من التصحيف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_sabr_ulama_abu_ghuddah', 'صَفَحَاتٌ مِنْ صَبْرِ العُلَمَاءِ عَلَى شَدَائِدِ العِلْمِ وَالتَّحْصِيلِ', 'العَلَّامَةُ المُحَدِّثُ الشَّيْخُ عَبْدُ الفَتَّاحِ أَبُو غُدَّةَ الحَلَبِيُّ (ت: 1417ھ)', 'kharji_kitab', 'adab', 'حصولِ علم میں اسلاف کی قربانیاں، فاقہ کشی و محنتیں', 'کتبِ مطالعہ و ہمت افزائی (شاہکار)', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'اسلافِ امت نے علم کی طلب میں کیسی کیسی بھوک، پیاس، غربت، سفر کی صعوبتیں اور راتوں کی بیداری برداشت کی، اس کا روح پرور تذکرہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sabr_ulama_ch1_jaw', 'kharji_sabr_ulama_abu_ghuddah', 0, 'صَبْرُ العُلَمَاءِ عَلَى الجُوعِ وَالفَقْرِ وَشَظَفِ العَيْشِ فِي طَلَبِ العِلْمِ', 'باب 1: علم کی خاطر علماء کا بھوک، فاقہ کشی اور غربت پر لازوال صبر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sabr_ulama_seg_1_1', 'sabr_ulama_ch1_jaw', 'kharji_sabr_ulama_abu_ghuddah', 0, 'قَالَ العَلَّامَةُ الشَّيْخُ عَبْدُ الفَتَّاحِ أَبُو غُدَّةَ: «لَمْ يَنَلْ أَئِمَّتُنَا هَذَا العِلْمَ عَلَى فُرُشِ الحَرِيرِ وَلَا فِي ظِلَالِ الرَّفَاهِيَةِ، بَلْ نَالُوهُ بِالصَّبْرِ عَلَى الجُوعِ الحَارِقِ وَالفَقْرِ المُدْقِعِ. رُوِيَ عَنِ الإِمَامِ مَالِكٍ أَنَّهُ قَالَ: «لَا يَبْلُغُ أَحَدٌ هَذَا الشَّأْنَ حَتَّى يَذُوقَ فِيهِ طَعْمَ الفَقْرِ، وَحَتَّى يَنْقُضَ سَقْفَ بَيْتِهِ فَيَبِيعَ خَشَبَهُ لِيَشْتَرِيَ بِهِ الكُتُبَ!». وَكَانَ ابْنُ مَعِينٍ وَأَحْمَدُ يَسِيرَانِ أَيَّاماً بِلَا زَادٍ إِلَّا كِسَرَ خُبْزٍ يَابِسَةٍ، حُبّاً فِي حَدِيثِ رَسُولِ اللَّهِ ﷺ».', 'علامہ شیخ عبد الفتاح ابو غدہ رحمہ اللہ فرماتے ہیں: ''ہمارے ائمہ کرام نے یہ علم ریشم کے بستروں پر اور آسائش کے محلات میں بیٹھ کر حاصل نہیں کیا، بلکہ انہوں نے اسے تڑپا دینے والی بھوک اور کسمپرسی پر صبر کر کے حاصل کیا۔ امام مالک رحمہ اللہ سے مروی ہے کہ انہوں نے فرمایا: ''کوئی شخص اس علم میں امامت کے مقام تک نہیں پہنچ سکتا جب تک کہ وہ اس کی خاطر فقر اور فاقے کا مزہ نہ چکھ لے، یہاں تک کہ اپنے گھر کی چھت گرا کر اس کی لکڑیاں بیچ کر کتابیں خریدنے پر مجبور نہ ہو جائے!'' اور امام یحییٰ بن معین اور امام احمد بن حنبل حدیثِ نبوی کی تلاش میں کئی کئی دن بغیر توشے کے سفر کرتے اور صرف سوکھی روٹی کے ٹکڑے چبا کر گزارا کرتے تھے''۔', 'صفحات من صبر العلماء علم کے طلبہ کے لیے ہمت، قربانی اور عزم کا سمندر ہے۔ یہ واقعات بتاتے ہیں کہ علم کی قدر وہی جان سکتا ہے جس نے اس کی خاطر مشقتیں کاٹی ہوں۔', '[{"word":"أَحَدٌ","role":"فاعل يبلغ مرفوع","sign":"ضمة","detail":"هذا الشأن مفعول به مقدم"},{"word":"حُبّاً","role":"مفعول لأجله منصوب","sign":"فتحة","detail":"يبين سبب تحملهما المشاق"}]', '["صفحات من صبر العلماء على شدائد العلم والتحصيل لعبد الفتاح أبو غدة، ص 35-50."]', '{"en":"Shaykh Abu Ghuddah documents the immense endurance of classical scholars: Sacrificing bodily comfort, enduring pangs of famine, and selling roof timbers to purchase parchment, embodying Imam Malik''s dictum that mastery requires tasting poverty.","ar":"تضحيات أئمة الحديث الكبرى وصبرهم على شظف العيش حباً في السنة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sabr_ulama_ch2_rihlah', 'kharji_sabr_ulama_abu_ghuddah', 1, 'صَبْرُهُمْ عَلَى السَّفَرِ الشَّاقِّ وَمَخَاطِرِ البِحَارِ وَالصَّحَارَى', 'باب 2: ایک حدیث کی تلاش میں ہزاروں میل پیدل سفر اور صحراؤں کے خطرات جھیلنا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sabr_ulama_seg_2_1', 'sabr_ulama_ch2_rihlah', 'kharji_sabr_ulama_abu_ghuddah', 0, '«سَافَرَ جَابِرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ مَسِيرَةَ شَهْرٍ كَامِلٍ إِلَى الشَّامِ فِي طَلَبِ حَدِيثٍ وَاحِدٍ لَمْ يَسْمَعْهُ مِنْ غَيْرِ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ! وَكَانَ بَقِيُّ بْنُ مَخْلَدٍ الأَنْدَلُسِيُّ يَسِيرُ مِنْ قُرْطُبَةَ فِي أَقْصَى المَغْرِبِ إِلَى بَغْدَادَ مَاشِياً عَلَى قَدَمَيْهِ لِيَلْقَى الإِمَامَ أَحْمَدَ، فَلَمَّا وَصَلَ وَجَدَهُ مَمْنُوعاً مِنَ التَّحْدِيثِ، فَكَانَ يَتَنَكَّرُ فِي ثِيَابِ شَحَّاذٍ وَيَقِفُ عَلَى بَابِ أَحْمَدَ فَيَقُولُ: الأَجْرَ رَحِمَكُمُ اللَّهُ! فَيَخْرُجُ إِلَيْهِ أَحْمَدُ فَيُحَدِّثُهُ بِالحَدِيثَيْنِ وَالثَّلَاثَةِ، حَتَّى كَتَبَ عَنْهُ مِئَاتِ الأَحَادِيثِ!».', 'شیخ ابو غدہ فرماتے ہیں: ''حضرت جابر بن عبد اللہ رضی اللہ عنہ نے صرف ایک حدیث کی تحقیق کے لیے مدینہ سے شام تک ایک مہینے کا طویل سفر اونٹ پر طے فرمایا کیونکہ وہ حدیث انہوں نے حضرت عبداللہ بن انیس کے سوا کسی اور سے نہیں سنی تھی! اور اندلس کے عظیم محدث امام بقی بن مخلد اندلسی قرطبہ (اسپین) سے لے کر بغداد تک ہزاروں میل کا راستہ پیدل چل کر طے کر کے امام احمد بن حنبل سے ملنے پہنچے، جب پہنچے تو دیکھا کہ حکومت نے امام احمد پر درس دینے کی پابندی لگا رکھی ہے، تو بقی بن مخلد نے فقیروں کا بھیس بدلا اور روزانہ امام احمد کے دروازے پر جا کر فقیر کی صدا لگاتے: ''اللہ کے واسطے کچھ خیرات دے دو!'' تو امام احمد اندر سے نکلتے اور خیرات کے بہانے انہیں دو تین حدیثیں املا کروا دیتے، یہاں تک کہ انہوں نے اس طرح سینکڑوں احادیث لکھ لیں!''', 'یہ واقعہ عزم و ہمت کا وہ کوہِ گراں ہے جو انسان کو دنگ کر دیتا ہے کہ اسپین سے بغداد تک پیدل چل کر آنا اور پھر فقیر بن کر حدیثیں حاصل کرنا کیسا جنون تھا۔', '[{"word":"مَسِيرَةَ","role":"ظرف زمان منصوب","sign":"فتحة","detail":"وهو مضاف وشهر مضاف إليه"},{"word":"مَاشِياً","role":"حال منصوب","sign":"فتحة","detail":"يبين هيئة مجيئه من الأندلس"}]', '["صفحات من صبر العلماء، ص 70-85."]', '{"en":"Unbelievable scholastic tenacity: Jabir travelled an entire month on camel for a solitary hadith. Baqi ibn Makhlad walked on foot from Cordoba (Spain) to Baghdad to meet Imam Ahmad; when Ahmad was under house arrest, Baqi disguised himself as a beggar daily to receive private hadith dictation at the doorway.","ar":"قصة بقي بن مخلد الأندلسي في التحيل لطلب العلم مشياً من الأندلس إلى بغداد."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ulama_uzzab_abu_ghuddah', 'العُلَمَاءُ العُزَّابُ الَّذِينَ آثَرُوا العِلْمَ عَلَى الزَّوَاجِ', 'العَلَّامَةُ المُحَدِّثُ الشَّيْخُ عَبْدُ الفَتَّاحِ أَبُو غُدَّةَ (ت: 1417ھ)', 'kharji_kitab', 'adab', 'جن ائمہ نے علم کی خاطر تجرد کی زندگی گزاری', 'کتبِ مطالعہ و تاریخِ اہلِ علم', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'امام طبری، زمخشری، نووی، اور ابن تیمیہ جیسے ان نابغۂ روزگار ائمہ کے احوال جنہوں نے علم اور تصنیف میں اس قدر انہماک پایا کہ شادی کا وقت نہ نکال سکے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ulama_uzzab_ch1_asbab', 'kharji_ulama_uzzab_abu_ghuddah', 0, 'العُلَمَاءُ العُزَّابُ: إِيثَارُ العِلْمِ عَلَى الزَّوَاجِ لِعُذْرٍ لَا رَغْبَةً عَنِ السُّنَّةِ', 'باب 1: کنوارے علماء — سنت سے بے رغبتی نہیں بلکہ علم میں مکمل غرق ہونے کا اضطراری عذر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ulama_uzzab_seg_1_1', 'ulama_uzzab_ch1_asbab', 'kharji_ulama_uzzab_abu_ghuddah', 0, 'قَالَ العَلَّامَةُ المُحَدِّثُ عَبْدُ الفَتَّاحِ أَبُو غُدَّةَ: «لَيْسَ المُرَادُ بِهَذَا الكِتَابِ الدَّعْوَةَ إِلَى العُزُوبَةِ أَوْ تَفْضِيلَهَا عَلَى الزَّوَاجِ؛ فَإِنَّ الزَّوَاجَ سُنَّةُ المُرْسَلِينَ، وَقَدْ قَالَ ﷺ: «النِّكَاحُ مِنْ سُنَّتِي فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي». وَإِنَّمَا أَرَدْنَا بَيَانَ سِيَرِ أَعْلَامٍ اسْتَغْرَقَهُمُ العِلْمُ كُلِّيَّةً، وَمَلَكَ عَلَيْهِمْ مَشَاعِرَهُمْ وَأَوْقَاتَهُمْ، أَوْ مَنَعَهُمُ الفَقْرُ الشَّدِيدُ وَالرِّحْلَةُ الدَّائِمَةُ فِي الآفَاقِ مِنْ تَحَمُّلِ أَعْبَاءِ الأُسْرَةِ وَحُقُوقِ الزَّوْجَةِ؛ فَآثَرُوا العُزُوبَةَ خَوْفاً مِنَ التَّقْصِيرِ فِي حُقُوقِ الخَلْقِ، مَعَ انْقِطَاعِهِمْ لِخِدْمَةِ الدِّينِ».', 'علامہ عبد الفتاح ابو غدہ رحمہ اللہ فرماتے ہیں: ''اس کتاب کا ہرگز یہ مقصد نہیں ہے کہ لوگوں کو کنوارا رہنے کی ترغیب دی جائے یا نکاح پر تجرد کو فضیلت دی جائے؛ کیونکہ نکاح تمام انبیاء کی مقدس سنت ہے، اور نبی ﷺ کا فرمان ہے: ''نکاح میری سنت ہے پس جس نے میری سنت سے منہ موڑا وہ مجھ میں سے نہیں''۔ بلکہ ہمارا مقصد ان عظیم المرتبت ائمہ کے حالات سامنے لانا ہے جنہیں علم کی طلب اور تصنیف و تالیف نے اس قدر اپنے اندر غرق کر لیا تھا کہ ان کے پاس کوئی وقت نہ بچا، یا شدید غربت اور ملکوں ملکوں کے مسلسل سفر نے انہیں بیوی بچوں کے حقوق اور مالی اخراجات کی ذمہ داری اٹھانے سے روک دیا؛ پس انہوں نے کسی مسلمان عورت کے حقوق پامال ہونے کے ڈر سے خود کو تنہا رکھا تاکہ وہ یکسو ہو کر دینِ متین کی خدمت کے لیے اپنی زندگیاں وقف کر دیں''۔', 'العلماء العزاب علامہ ابو غدہ کی وہ تصنیف ہے جس نے امت کے ان مجرد ائمہ کے حالات جمع کیے جنہوں نے دین کی خاطر اپنی ذاتی زندگیاں قربان کر دیں۔', '[{"word":"الدَّعْوَةَ","role":"خبر ليس منصوب","sign":"فتحة","detail":"المراد اسمها والدعوة خبرها"},{"word":"خَوْفاً","role":"مفعول لأجله منصوب","sign":"فتحة","detail":"يبين علة إيثارهم العزوبة"}]', '["العلماء العزاب الذين آثروا العلم على الزواج، ص 15-28."]', '{"en":"Shaykh Abu Ghuddah''s unique historical study: Clarifying that celibacy is not preferred over marriage (which is the Prophetic Sunnah), but recounting the extraordinary lives of titans (like An-Nawawi and Ibn Taymiyyah) whose absolute absorption in sacred sciences and poverty precluded them from marital obligations.","ar":"تحرير الموقف الفقهي والتربوي من مسألة العلماء الذين آثروا العلم على النكاح."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ulama_uzzab_ch2_nawawi_taymiyyah', 'kharji_ulama_uzzab_abu_ghuddah', 1, 'سِيرَةُ الإِمَامِ النَّوَوِيِّ وَشَيْخِ الإِسْلَامِ ابْنِ تَيْمِيَّةَ فِي التَّجَرُّدِ لِلْعِلْمِ', 'باب 2: امام نووی اور شیخ الاسلام ابن تیمیہ — علم کے سمندر میں غوطہ زنی اور امت کے لیے لازوال تصانیف');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ulama_uzzab_seg_2_1', 'ulama_uzzab_ch2_nawawi_taymiyyah', 'kharji_ulama_uzzab_abu_ghuddah', 0, '«كَانَ الإِمَامُ يَحْيَى بْنُ شَرَفٍ النَّوَوِيُّ مَضْرِبَ المَثَلِ فِي التَّجَرُّدِ؛ عَاشَ خَمْساً وَأَرْبَعِينَ سَنَةً لَمْ يَتَزَوَّجْ، وَكَانَ يَقْرَأُ كُلَّ يَوْمٍ اثْنَيْ عَشَرَ دَرْساً عَلَى المَشَايِخِ شَرْحاً وَتَصْحِيحاً، وَأَلَّفَ «المَجْمُوعَ» وَ«شَرْحَ صَحِيحِ مُسْلِمٍ» وَ«رِيَاضَ الصَّالِحِينَ» الَّتِي مَلَأَتِ الخَافِقَيْنِ. وَكَذَلِكَ شَيْخُ الإِسْلَامِ ابْنُ تَيْمِيَّةَ عَاشَ مُجَاهِداً بَيْنَ السِّجْنِ وَمَيَادِينِ الجِهَادِ وَالتَّصْنِيفِ، فَكَانَتْ كُتُبُهُمْ هِيَ أَوْلَادَهُمُ الخَالِدِينَ الَّذِينَ لَا يَمُوتُونَ إِلَى يَوْمِ القِيَامَةِ!».', 'علامہ ابو غدہ فرماتے ہیں: ''امام محیی الدین نووی رحمہ اللہ علم میں فنا ہو جانے کی لازوال مثال تھے؛ انہوں نے صرف پینتالیس سال کی مختصر عمر پائی، کبھی نکاح نہیں کیا، وہ طالب علمی کے دور میں روزانہ اساتذہ سے بارہ تفصیلی اسباق پڑھتے تھے، اور انہوں نے ''المجموع شرح المہذب''، ''شرح صحیح مسلم'' اور ''ریاض الصالحین'' جیسی وہ لازوال کتب تصنیف فرمائیں جن کے فیض سے مشرق و مغرب بھر گئے۔ اور اسی طرح شیخ الاسلام امام ابن تیمیہ رحمہ اللہ نے اپنی پوری زندگی جہاد کے میدانوں، قید خانوں کی سلاخوں اور حق کی مدافعت میں تالیفات کرتے ہوئے گزاری، پس یہ شاہکار کتب ہی دراصل ان کی وہ روحانی اور ابدی اولادیں بن گئیں جو قیامت تک زندہ رہیں گی!''', 'امام نووی اور ابن تیمیہ نے دنیاوی گھریلو زندگی کو چھوڑ کر امت کے لیے جو علمی ورثہ چھوڑا وہ قیامت تک کروڑوں انسانوں کے لیے رہنمائی کا ذریعہ بنا ہوا ہے۔', '[{"word":"مَضْرِبَ","role":"خبر كان منصوب","sign":"فتحة","detail":"الإمام اسمها ومضرب خبرها وهو مضاف"},{"word":"أَوْلَادَهُمُ","role":"خبر كانت منصوب","sign":"فتحة","detail":"وهو مضاف وهم مضاف إليه"}]', '["العلماء العزاب، تراجم: الإمام النووي وابن تيمية، ص 75-110."]', '{"en":"Imam An-Nawawi lived only 45 years unwed, attending 12 rigorous daily tutorials and producing masterpieces like Riyadh as-Salihin and Sharh Sahih Muslim. Likewise, Ibn Taymiyyah lived a tempestuous life of battlefields, prison, and writing—their enduring books becoming their immortal offspring.","ar":"آثار الإمامين النواوي وابن تيمية وبركة أعمارهم في خدمة الملة المحمدية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_mushawwiq_qiraah_omran', 'المُشَوِّقُ إِلَى القِرَاءَةِ وَطَلَبِ العِلْمِ', 'الشَّيْخُ عَلِيُّ بْنُ مُحَمَّدٍ العِمْرَانُ', 'kharji_kitab', 'adab', 'شوقِ مطالعہ، کتب بینی کی لذت اور سلف کے احوال', 'کتبِ مطالعہ و ایجادِ ذوقِ کتب بینی', NULL, NULL, 'from-blue-950 via-stone-900 to-emerald-950', NULL, 'کتابوں سے عشق، مطالعے کی لت، اور لائبریریوں میں اسلاف کے شب و روز گزارنے کی دلچسپ اور انوکھی سچی کہانیاں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('mushawwiq_ch1_lahaf', 'kharji_mushawwiq_qiraah_omran', 0, 'لَهَفُ العُلَمَاءِ عَلَى اقْتِنَاءِ الكُتُبِ وَشَغَفُهُمْ بِمُطَالَعَتِهَا', 'باب 1: کتابوں کے حصول کی دیوانگی اور مطالعے کا جنون');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('mushawwiq_seg_1_1', 'mushawwiq_ch1_lahaf', 'kharji_mushawwiq_qiraah_omran', 0, 'قَالَ الشَّيْخُ عَلِيُّ بْنُ مُحَمَّدٍ العِمْرَانُ: «القِرَاءَةُ هِيَ غِذَاءُ العَقْلِ، وَرَوْحُ النَّفْسِ، وَسُلَّمُ الرُّقِيِّ الإِنْسَانِيِّ. كَانَ عُلَمَاؤُنَا يُضَحُّونَ بِالقُوتِ وَاللِّبَاسِ فِي سَبِيلِ شِرَاءِ كِتَابٍ نَادِرٍ؛ قَالَ الإِمَامُ الشَّعْبِيُّ: «لَوْ سَافَرَ رَجُلٌ مِنَ الشَّامِ إِلَى أَقْصَى اليَمَنِ لِيَسْمَعَ كَلِمَةَ حِكْمَةٍ مَا رَأَيْتُ أَنَّ سَفَرَهُ ضَاعَ!». وَكَانَ ابْنُ رُشْدٍ الفَقِيهُ الفَيْلَسُوفُ لَا يَدَعُ القِرَاءَةَ لَيْلَةً وَاحِدَةً فِي حَيَاتِهِ إِلَّا لَيْلَتَيْنِ: لَيْلَةَ بِنَائِهِ بِأَهْلِهِ (زَوَاجِهِ)، وَلَيْلَةَ وَفَاةِ أَبِيهِ!».', 'شیخ علی بن محمد العمران فرماتے ہیں: ''مطالعہ عقل کی غذا، روح کی تازگی، اور انسانی بلندی کی معراج ہے۔ ہمارے اسلاف نادر کتاب خریدنے کے لیے اپنے کھانے پینے اور کپڑوں تک کی قربانی دے دیتے تھے؛ امام شعبی فرماتے ہیں: ''اگر کوئی شخص ملکِ شام سے یمن کے آخری کونے تک صرف ایک دانائی کی بات سننے کے لیے سفر کرے تو میں اس کے اس طویل سفر کو ہرگز ضائع نہیں سمجھتا!'' اور قاضی ابن رشد الحفید نے اپنی پوری زندگی میں سوائے دو راتوں کے کبھی مطالعہ نہیں چھوڑا: ایک اپنی شادی کی رات، اور دوسری اپنے والد کی وفات کی رات!''', 'المشوق إلى القراءة وطلب العلم مطالعے کے شائقین کے لیے ایک پرکشش اور روح پرور کتاب ہے جس میں کتب بینی کے فضائل اور اسلاف کی کتب نوازی کے واقعات جمع کیے گئے ہیں۔', '[{"word":"غِذَاءُ","role":"خبر المبتدأ القراءة مرفوع","sign":"ضمة","detail":"وهو مضاف والعقل مضاف إليه"},{"word":"ضَاعَ","role":"فعل ماض والجملة خبر أنّ","sign":"مبني","detail":"سفره اسم أنّ"}]', '["المشوق إلى القراءة وطلب العلم لعلي العمران، ص 20-35، دار عالم الفوائد."]', '{"en":"Shaykh Ali Al-Omran''s ''Inspiring Love for Reading'': Knowledge is the intellect''s nourishment. Ibn Rushd never skipped reading a single night across his entire lifetime except on two occasions: his wedding night and the night his father passed away.","ar":"قصص ملهمة في إدمان القراءة والارتباط الوجداني بالكتاب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('mushawwiq_ch2_adab_kitab', 'kharji_mushawwiq_qiraah_omran', 1, 'كَيْفَ تُحَصِّلُ المَلَكَةَ العِلْمِيَّةَ مِنَ القِرَاءَةِ المَنْهَجِيَّةِ؟', 'باب 2: اصولی اور منہجی مطالعہ — محض ورق گردانی سے نکل کر علمی ملکہ پیدا کرنے کے طریقے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('mushawwiq_seg_2_1', 'mushawwiq_ch2_adab_kitab', 'kharji_mushawwiq_qiraah_omran', 0, '«لَيْسَتِ العِبْرَةُ بِكَثْرَةِ تَقْلِيبِ الأَوْرَاقِ، بَلْ بِالفَهْمِ وَالتَّأَمُّلِ وَالتَّقْيِيدِ؛ فَالقِرَاءَةُ المَنْهَجِيَّةُ تَقُومُ عَلَى ثَلَاثٍ: التَّدَرُّجِ مِنْ صِغَارِ العِلْمِ قَبْلَ كِبَارِهِ، وَتَقْيِيدِ الفَوَائِدِ وَالفَرَائِدِ عَلَى طُرَرِ الكُتُبِ، وَمُذَاكَرَةِ المَقْرُوءِ مَعَ الأَقْرَانِ. قَالَ عَبْدُ اللَّهِ بْنُ المُبَارَكِ: «قَيِّدُوا العِلْمَ بِالكِتَابِ». فَمَنْ لَمْ يُقَيِّدْ فَوَائِدَهُ طَارَتْ مَعَ النِّسْيَانِ، وَمَنْ قَرَأَ بِغَيْرِ تَرْتِيبٍ تَشَتَّتَ ذِهْنُهُ وَلَمْ يَظْفَرْ بِطَائِلٍ».', 'شیخ علی العمران فرماتے ہیں: ''کامیابی کا دارومدار محض ڈھیروں ورق پلٹنے میں نہیں ہے، بلکہ فہم، تدبر اور اہم نکات کو قلمبند کرنے میں ہے؛ چنانچہ بامقصد اور اصولی مطالعہ تین ستونوں پر قائم ہوتا ہے: پہلے بنیادی اور مختصر کتابوں کا مطالعہ کرنا اس سے قبل کہ بڑی کتابوں کی طرف جایا جائے، کتاب کے حاشیوں پر نایاب علمی فوائد کو فوراً نوٹ کرنا، اور جو پڑھا ہو اسے ہم درس ساتھیوں کے ساتھ تکرار و مذاکرہ کرنا۔ عبد اللہ بن مبارک فرماتے ہیں: ''علم کو لکھ کر قید کر لو''۔ پس جس نے نایاب نکات کو قلمبند نہ کیا وہ نسیان کی آندھی میں اڑ جائیں گے، اور جس نے بغیر استاد اور ترتیب کے بے ہنگم مطالعہ کیا اس کا ذہن منتشر ہو جائے گا اور وہ کبھی کسی نتیجے پر نہیں پہنچ سکے گا''۔', 'یہ باب طلبۂ علم کے لیے مطالعے کی گائیڈ لائن ہے تاکہ وہ وقت کے ضیاع سے بچ کر کتابوں سے حقیقی معنوں میں مستفید ہو سکیں۔', '[{"word":"العِبْرَةُ","role":"اسم ليس مرفوع","sign":"ضمة","detail":"بكثرة شبه جملة خبر مقدم"},{"word":"فَوَائِدَهُ","role":"مفعول به ليقيد منصوب","sign":"فتحة","detail":"والهاء مضاف إليه"}]', '["المشوق إلى القراءة، ص 80-95."]', '{"en":"Methodological reading: 1. Gradual progression from primers to encyclopedias, 2. Recording marginalia and pearls (Taiseer al-Fawa''id), 3. Peer discussion (Mudhakarah). ''Bind knowledge by writing it down.''","ar":"قواعد القراءة المثمرة وتدوين الفوائد وضبط أصول التحصيل."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_rihlah_talab_hadith', 'الرِّحْلَةُ فِي طَلَبِ الحَدِيثِ', 'الحَافِظُ أَبُو بَكْرٍ أَحْمَدُ بْنُ عَلِيٍّ الخَطِيبُ البَغْدَادِيُّ (ت: 463ھ)', 'kharji_kitab', 'adab', 'ایک ایک حدیث کی خاطر مہینوں کے صحرائی اسفار', 'کتبِ مطالعہ و تاریخِ اسفارِ علم', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'صحابہ کرام اور ائمۂ محدثین کا صرف ایک حدیث کی تصدیق کے لیے مصر سے شام اور مدینہ تک اونٹوں پر مہینوں سفر کرنے کی داستانیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('rihlah_hadith_ch1_sahabah', 'kharji_rihlah_talab_hadith', 0, 'رِحْلَةُ الصَّحَابَةِ فِي طَلَبِ الحَدِيثِ: النَّمُوذَجُ النَّبَوِيُّ الفَرِيدُ', 'باب 1: ایک حدیث کے لیے صحابہ کرام کا ہزاروں میل کا پرمشقت سفر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('rihlah_hadith_seg_1_1', 'rihlah_hadith_ch1_sahabah', 'kharji_rihlah_talab_hadith', 0, 'قَالَ الحَافِظُ أَبُو بَكْرٍ الخَطِيبُ البَغْدَادِيُّ: «رَحَلَ أَبُو أَيُّوبَ الأَنْصَارِيُّ رَضِيَ اللَّهُ عَنْهُ مِنْ المَدِينَةِ إِلَى مِصْرَ إِلَى عُقْبَةَ بْنِ عَامِرٍ لِيَسْأَلَهُ عَنْ حَدِيثٍ سَمِعَهُ مِنْ رَسُولِ اللَّهِ ﷺ فِي سَتْرِ المُسْلِمِ؛ فَلَمَّا قَدِمَ عَلَيْهِ قَالَ لَهُ: حَدِّثْنِي بِالحَدِيثِ؛ فَقَالَ عُقْبَةُ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ سَتَرَ مُسْلِماً سَتَرَهُ اللَّهُ يَوْمَ القِيَامَةِ». فَرَكِبَ أَبُو أَيُّوبَ رَاحِلَتَهُ فَوْراً وَانْصَرَفَ رَاجِعاً إِلَى المَدِينَةِ، وَمَا حَلَّ رَحْلَهُ وَلَا نَزَلَ لِضِيَافَةٍ؛ إِعْظَاماً لِسُنَّةِ النَّبِيِّ ﷺ!».', 'حافظ ابو بکر خطیب بغدادی رحمہ اللہ فرماتے ہیں: ''حضرت ابو ایوب انصاری رضی اللہ عنہ نے مدینہ منورہ سے مصر تک کا طویل اور کٹھن سفر محض ایک حدیث سننے کے لیے طے فرمایا جو انہوں نے اور حضرت عقبہ بن عامر نے رسول اللہ ﷺ سے سنی تھی مسلمان کی پردہ پوشی کے بارے میں؛ پس جب وہ مصر میں حضرت عقبہ کے گھر پہنچے تو فرمایا: مجھے وہ حدیث سنا دیجیے؛ حضرت عقبہ نے فرمایا: میں نے رسول اللہ ﷺ کو فرماتے سنا: ''جس شخص نے دنیا میں کسی مسلمان کے عیب کی پردہ پوشی کی، اللہ تعالیٰ قیامت کے دن اس کے عیبوں پر پردہ ڈالے گا''۔ حضرت ابو ایوب نے فوراً اپنی اونٹنی کی لگام موڑی اور اسی وقت مدینہ کی طرف واپس روانہ ہو گئے، نہ اپنی سواری کھولی اور نہ کسی مہمانی کے لیے رکے؛ رسول اللہ ﷺ کی سنت کی ایسی والہانہ تعظیم تھی!''', 'الرحلة في طلب الحديث خطیب بغدادی کی وہ نایاب کتاب ہے جس میں انہوں نے حدیث کی خاطر صحابہ اور تابعین کے اسفار کے سچے اور ایمان افروز واقعات قلمبند کیے ہیں۔', '[{"word":"سَتَرَ","role":"فعل ماض مبني في محل جزم فعل الشرط","sign":"مبني","detail":"من اسم شرط مبتدأ"},{"word":"فَوْراً","role":"مفعول مطلق أو نائب عن الظرف","sign":"فتحة","detail":"يدل على السرعة"}]', '["الرحلة في طلب الحديث للخطيب البغدادي، ص 30-38، وأخرجه الحاكم في المستدرك."]', '{"en":"Khatib al-Baghdadi documents the classic journeys: Abu Ayyub al-Ansari rode all the way from Madinah to Egypt purely to re-verify a single hadith on concealing a Muslim''s fault from ''Uqbah ibn ''Amir, departing immediately without even dismounting for hospitality.","ar":"تعظيم الصحابة للحديث النبوي وقطع المسافات الشاسعة للتثبت من الرواية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('rihlah_hadith_ch2_aimmah', 'kharji_rihlah_talab_hadith', 1, 'رِحْلَةُ أَئِمَّةِ الحَدِيثِ: شُعْبَةُ وَيَحْيَى بْنُ مَعِينٍ وَطَوَافُ الأَرْضِ', 'باب 2: ائمہ حدیث کا بحر و بر کا طواف — امام شعبہ اور ابن معین کے حیرت انگیز اسفار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('rihlah_hadith_seg_2_1', 'rihlah_hadith_ch2_aimmah', 'kharji_rihlah_talab_hadith', 0, '«كَانَ الإِمَامُ شُعْبَةُ بْنُ الحَجَّاجِ يَقُولُ: «إِنِّي لَأَسْمَعُ الحَدِيثَ عَنِ الرَّجُلِ فَلَا يَسَعُنِي حَتَّى أَرْحَلَ إِلَيْهِ فَأَسْمَعَهُ مِنْ فِيهِ!». وَقَالَ يَحْيَى بْنُ مَعِينٍ: «أَرْبَعَةٌ لَا تُؤْنَسُ مِنْهُمْ رُشْداً: فَاسِقٌ، وَكَذَّابٌ، وَرَجُلٌ يُحَدِّثُ مِنْ كُتُبِ النَّاسِ، وَرَجُلٌ لَا يَرْحَلُ فِي طَلَبِ العِلْمِ!». وَرَحَلَ ابْنُ مَعِينٍ أَرْبَعِينَ سَنَةً فِي طَلَبِ الأَسَانِيدِ، وَأَنْفَقَ أَلْفَ أَلْفِ دِرْهَمٍ (مِلْيُونَ دِرْهَمٍ) وَرِثَهَا عَنْ أَبِيهِ فِي الرِّحْلَةِ حَتَّى لَمْ يَبْقَ لَهُ نَعْلٌ يَلْبَسُهُ!».', 'خطیب بغدادی فرماتے ہیں: ''امیر المؤمنین فی الحدیث امام شعبہ بن الحجاج فرمایا کرتے تھے: ''جب میں کسی شخص سے کوئی حدیث سنتا ہوں تو مجھے اس وقت تک چین نہیں آتا جب تک کہ میں سفر کر کے خود اس راوی کے سامنے بیٹھ کر اس کے مبارک منہ سے وہ حدیث نہ سن لوں!'' اور امام یحییٰ بن معین فرمایا کرتے تھے: ''چار قسم کے آدمیوں سے کبھی بھلائی اور ہدایت کی امید مت رکھو: کھلا فاسق، جھوٹا، وہ شخص جو لوگوں کی کتابوں سے چوری کر کے حدیثیں بیان کرے، اور وہ طالب علم جو علم کی تلاش میں ملکوں ملکوں کا سفر نہ کرے!'' اور امام یحییٰ بن معین نے چالیس سال تک احادیث کی تلاش میں سفر کیا اور اپنے والد کی وراثت سے ملنے والے دس لاکھ درہم اس سفر پر نچھاور کر دیے یہاں تک کہ ان کے پاس پاؤں میں پہننے کے لیے جوتا تک باقی نہ رہا!''', 'یہ وہ عظیم قربانیاں ہیں جن کی بدولت آج ہمارے ہاتھوں میں بخاری اور مسلم کی صحیح احادیث محفوظ ہیں جن میں ملاوٹ کا ایک شائبہ تک نہیں۔', '[{"word":"أَرْبَعَةٌ","role":"مبتدأ مرفوع","sign":"ضمة","detail":"لا تؤنس جملة فعلية خبر"},{"word":"أَلْفَ","role":"مفعول به لأنفق منصوب","sign":"فتحة","detail":"وهو مضاف وألف درهم مضاف إليه"}]', '["الرحلة في طلب الحديث، ص 60-75."]', '{"en":"Imam Yahya ibn Ma''in spent 1,000,000 dirhams inherited from his father travelling for 40 years across the Islamic world to verify narrators, walking barefoot when his funds depleted. Shu''bah traversed lands to hear narrations directly from the narrator''s lips.","ar":"الإنفاق السخي والجهد الأسطوري لأئمة الجرح والتعديل في حفظ السنة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_iqtida_ilm_amal', 'اقْتِضَاءُ العِلْمِ العَمَلَ', 'الحَافِظُ أَبُو بَكْرٍ الخَطِيبُ البَغْدَادِيُّ (ت: 463ھ)', 'kharji_kitab', 'adab', 'علم کا تقاضا: عمل اور کردار کی درستگی', 'کتبِ مطالعہ و عمل بالسنۃ', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'بے عمل عالم کی وعیدیں، اور یہ کہ علم کا اصل مقصد اللہ کا خوف اور تقویٰ ہے نہ کہ محض معلومات کا ذخیرہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('iqtida_ilm_ch1_tahdhir', 'kharji_iqtida_ilm_amal', 0, 'بَابُ التَّغْلِيظِ عَلَى مَنْ تَرَكَ العَمَلَ بِعِلْمِهِ وَأَنَّهُ حُجَّةٌ عَلَيْهِ', 'باب 1: بے عمل عالم پر سخت وعید — علم پر عمل نہ کرنا بدترین عذاب کا سبب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('iqtida_ilm_seg_1_1', 'iqtida_ilm_ch1_tahdhir', 'kharji_iqtida_ilm_amal', 0, 'قَالَ الحَافِظُ أَبُو بَكْرٍ الخَطِيبُ البَغْدَادِيُّ: «أَمَّا بَعْدُ، فَإِنِّي مُوصِيكَ يَا طَالِبَ العِلْمِ بِإِخْلَاصِ النِّيَّةِ، وَإِتْبَاعِ العِلْمِ بِالعَمَلِ؛ فَإِنَّ العِلْمَ شَجَرَةٌ وَالعَمَلَ ثَمَرَةٌ، وَلَيْسَ يُعَدُّ عَالِماً مَنْ لَمْ يَكُنْ بِعِلْمِهِ عَامِلاً. عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَثَلُ الَّذِي يُعَلِّمُ النَّاسَ الخَيْرَ وَيَنْسَى نَفْسَهُ مَثَلُ السِّرَاجِ: يُضِيءُ لِلنَّاسِ وَيَحْرِقُ نَفْسَهُ!». وَقَالَ أَبُو الدَّرْدَاءِ: «إِنَّ أَخْوَفَ مَا أَخَافُ عَلَى نَفْسِي إِذَا وَقَفْتُ بَيْنَ يَدَيْ رَبِّي أَنْ يَقُولَ لِي: قَدْ عَلِمْتَ، فَمَاذَا عَمِلْتَ فِيمَا عَلِمْتَ؟!».', 'حافظ ابو بکر خطیب بغدادی رحمہ اللہ فرماتے ہیں: ''اے علم کے طالب! میں تجھے نیت کو خالص رکھنے اور علم کے پیچھے عمل کی پیروی کرنے کی پرزور وصیت کرتا ہوں؛ کیونکہ علم درخت کی مانند ہے اور عمل اس کا پھل ہے، اور وہ شخص عالم کہلانے کا مستحق ہی نہیں جو اپنے علم پر عمل نہ کرتا ہو۔ حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''اس شخص کی مثال جو لوگوں کو تو بھلائی کی تعلیم دیتا ہے لیکن اپنے آپ کو بھول جاتا ہے چراغ جیسی ہے: جو دوسروں کو تو روشنی دیتا ہے مگر خود اپنے آپ کو جلا کر راکھ کر دیتا ہے!'' اور حضرت ابو درداء رضی اللہ عنہ فرماتے ہیں: ''مجھے اپنے رب کے سامنے کھڑے ہوتے وقت جس بات کا سب سے زیادہ خوف لاحق ہے وہ یہ ہے کہ اللہ مجھ سے فرمائے: تو نے علم تو سیکھ لیا تھا، اب بتا کہ جتنا علم تیرے پاس تھا اس پر تو نے کتنا عمل کیا تھا؟!''', 'کتاب ''اقتضاء العلم العمل'' طلبۂ علم کے لیے ضمیر کا تازیانہ ہے۔ خطیب بغدادی نے اس کتاب میں ثابت کیا کہ بے عمل عالم کا علم اس کے گلے کا طوق اور قیامت کے دن اس کے خلاف سب سے بڑی دلیل بن جائے گا۔', '[{"word":"شَجَرَةٌ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"العلم اسمها وشجرة خبرها"},{"word":"السِّرَاجِ","role":"مضاف إليه مجرور","sign":"كسرة","detail":"مثل مضاف والسراج مضاف إليه"}]', '["اقتضاء العلم العمل للخطيب البغدادي، ص 10-22، بتحقيق الألباني."]', '{"en":"Khatib al-Baghdadi''s masterpiece ''Knowledge Demands Action'' (Iqtida'' al-''Ilm al-''Amal): Knowledge is the tree, action is the fruit. The Prophet ﷺ warned: ''The one who teaches people virtue while neglecting himself is like a lantern: illuminating others while burning itself to ashes.''","ar":"الأصل الرباني بأن العلم وسيلة للعمل وذم من خالف قوله فعله."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('iqtida_ilm_ch2_fadhilah', 'kharji_iqtida_ilm_amal', 1, 'بَابُ أَنَّ زَكَاةَ العِلْمِ العَمَلُ بِهِ وَنَشْرُهُ بَيْنَ النَّاسِ', 'باب 2: علم کی زکوٰۃ — ہر حدیث اور مسئلے پر ایک بار ضرور عمل کرنا اور اسے پھیلانا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('iqtida_ilm_seg_2_1', 'iqtida_ilm_ch2_fadhilah', 'kharji_iqtida_ilm_amal', 0, '«قَالَ سُفْيَانُ الثَّوْرِيُّ: «إِذَا بَلَغَكَ عَنْ رَسُولِ اللَّهِ ﷺ حَدِيثٌ فَاعْمَلْ بِهِ وَلَوْ مَرَّةً وَاحِدَةً تَكُنْ مِنْ أَهْلِهِ». وَكَانَ بِشْرٌ الحَافِي يَقُولُ: «يَا أَصْحَابَ الحَدِيثِ، أَدُّوا زَكَاةَ هَذَا الحَدِيثِ! قَالُوا: وَمَا زَكَاتُهُ؟ قَالَ: اعْمَلُوا مِنْ كُلِّ مِائَتَيْ حَدِيثٍ بِخَمْسَةِ أَحَادِيثَ!». وَقَالَ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ: «هَتَفَ العِلْمُ بِالعَمَلِ، فَإِنْ أَجَابَهُ وَإِلَّا ارْتَحَلَ!». فَمَنْ أَرَادَ بَقَاءَ حِفْظِهِ وَبَرَكَةَ فَهْمِهِ فَعَلَيْهِ بِطَاعَةِ اللَّهِ وَتَرْكِ الذُّنُوبِ».', 'خطیب بغدادی فرماتے ہیں: امام سفیان ثوری فرماتے ہیں: ''جب تمہارے پاس رسول اللہ ﷺ کی کوئی بھی سنت یا حدیث پہنچے تو اس پر کم از کم ایک مرتبہ ضرور عمل کر لو تاکہ تم اس حدیث کے اہل اور عاملین میں شامل ہو جاؤ''۔ اور بشر حافی فرمایا کرتے تھے: ''اے حدیث کے طالبو! اس حدیث کی زکوٰۃ ادا کرو! لوگوں نے پوچھا: حدیث کی زکوٰۃ کیا ہے؟ فرمایا: ہر دو سو احادیث میں سے کم از کم پانچ حدیثوں پر ضرور عمل کیا کرو!'' اور حضرت علی بن ابی طالب رضی اللہ عنہ نے وہ تاریخی جملہ فرمایا: ''علم عمل کو پکارتا ہے، پس اگر عمل اس کی پکار کا جواب دے تو علم دل میں ٹھہر جاتا ہے، ورنہ وہ دل سے کوچ کر جاتا ہے اور اڑ جاتا ہے!'' پس جو شخص اپنے حافظے کی پختگی اور فہم کی برکت چاہتا ہے اس پر لازم ہے کہ وہ گناہوں کو چھوڑ کر عمل کی راہ اپنائے''۔', 'علم کو یاد رکھنے کا سب سے بڑا نسخہ اس پر عمل کرنا ہے۔ حضرت علی کا یہ جملہ کہ ''علم عمل کو پکارتا ہے ورنہ رخصت ہو جاتا ہے'' تدریسی و تربیتی حکمت کی معراج ہے۔', '[{"word":"زَكَاةَ","role":"مفعول به لأدوا منصوب","sign":"فتحة","detail":"أدوا فعل أمر مبني على حذف النون"},{"word":"ارْتَحَلَ","role":"فعل ماض والفاعل مستتر","sign":"مبني","detail":"جواب الشرط وإلا ارتحل"}]', '["اقتضاء العلم العمل، ص 45-58."]', '{"en":"Sufyan ath-Thawri advised: ''When a Hadith reaches you, act upon it even once, so you become of its practitioners.'' ''Ali ibn Abi Talib proclaimed: ''Knowledge calls out for action: if answered, it abides; otherwise, it departs.''","ar":"تثبيت العلم بالعمل وبيان زكاة الحديث الشريف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_maalam_tariq_talab', 'مَعَالِمُ فِي طَرِيقِ طَلَبِ العِلْمِ', 'الشَّيْخُ عَبْدُ العَزِيزِ بْنُ مُحَمَّدٍ السَّدْحَانُ', 'kharji_kitab', 'adab', 'طلبِ علم کے راہنما اصول و منہجی غلطیاں', 'کتبِ مطالعہ و منہجی رہنمائی', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'طلبۂ علم کو درپیش رکاوٹیں، اساتذہ سے استفادے کے آداب، اور مطالعے میں توازن برقرار رکھنے کا جدید نصاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('maalam_ch1_asl', 'kharji_maalam_tariq_talab', 0, 'المَعْلَمُ الأَوَّلُ: إِخْلَاصُ النِّيَّةِ وَالصَّبْرُ عَلَى مُرَادِ العِلْمِ', 'نشانِ راہ 1: اخلاصِ نیت اور طلبِ علم کی طویل مسافت پر صبر و استقامت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('maalam_seg_1_1', 'maalam_ch1_asl', 'kharji_maalam_tariq_talab', 0, 'قَالَ الشَّيْخُ عَبْدُ العَزِيزِ بْنُ مُحَمَّدٍ السَّدْحَانُ: «مِنْ أَهَمِّ المَعَالِمِ فِي طَرِيقِ طَلَبِ العِلْمِ: أَنْ يَعْلَمَ الطَّالِبُ أَنَّ هَذَا الطَّرِيقَ لَيْسَ مَفْرُوشاً بِالوَرْدِ، بَلْ هُوَ طَرِيقُ جِهَادٍ وَصَبْرٍ وَمُصَابَرَةٍ. يَحْتَاجُ إِلَى نِيَّةٍ خَالِصَةٍ تَنْتَشِلُهُ مِنْ رِيَاءِ المَحَافِلِ، وَإِلَى عَزِيمَةٍ لَا تَفْتُرُ عِنْدَ فَقْدِ الرَّفِيقِ أَوْ ضِيقِ ذَاتِ اليَدِ. وَكَمَا قَالَ الإِمَامُ الشَّافِعِيُّ: «أَخِي لَنْ تَنَالَ العِلْمَ إِلَّا بِسِتَّةٍ: ذَكَاءٍ وَحِرْصٍ وَاجْتِهَادٍ وَبُلْغَةٍ ... وَصُحْبَةِ أُسْتَاذٍ وَطُولِ زَمَانِ».', 'شیخ عبد العزیز بن محمد السدحان فرماتے ہیں: ''علم کی راہ کے سب سے اہم رہنما اصولوں میں سے یہ ہے کہ طالب علم اچھی طرح جان لے کہ یہ راستہ پھولوں کی سیج نہیں ہے، بلکہ یہ مسلسل جہاد، عزم اور صبر و استقامت کا راستہ ہے۔ اس راستے کے مسافر کو ایسی مخلص نیت درکار ہے جو اسے محفلوں کی ریاکاری سے بچا لے، اور ایسا پختہ ارادہ درکار ہے جو کسی ہم سفر کے چھوٹ جانے یا مفلسی و تنگی کے آ جانے پر سست نہ پڑے۔ جیسا کہ امام شافعی نے فرمایا تھا: ''اے میرے بھائی! تم چھ چیزوں کے بغیر ہرگز علم حاصل نہیں کر سکتے: تیز فہم، سچی لگن، شب و روز کی محنت، گزر بسر کے لائق توشہ، کامل استاد کی صحبت، اور ایک طویل زمانہ''۔', 'معالم في طريق طلب العلم طلبۂ علم کے لیے راہنما مشعل ہے جو جلد بازی، بے صبری اور بے ترتیبی سے بچا کر ایک مضبوط عالم بنانے کا خاکہ دیتی ہے۔', '[{"word":"طَرِيقُ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"وهو مضاف وجهاد مضاف إليه"},{"word":"سِتَّةٍ","role":"مجرور بإلا","sign":"کسرة","detail":"استثناء مفرغ بعد نفي"}]', '["معالم في طريق طلب العلم للسدحان، ص 15-24."]', '{"en":"Shaykh Abd al-Aziz As-Sadhan''s ''Milestones on the Path of Knowledge'': A path paved with endurance and sacrifice. Citing Imam Ash-Shafi''i''s immortal six requisites: Keen intellect, fervent yearning, relentless toil, modest subsistence, companionship of an erudite mentor, and vast spans of time.","ar":"المعالم الأساسية لمنهجية الطلب وتوطين النفس على طول الزمان."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('maalam_ch2_tadarruj', 'kharji_maalam_tariq_talab', 1, 'المَعْلَمُ الثَّانِي: التَّدَرُّجُ المَنْهَجِيُّ فِي المَذَاهِبِ وَالمُتُونِ', 'نشانِ راہ 2: علمی متون اور درسی کتب میں بتدریج ترقی کا سنہری اصول');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('maalam_seg_2_1', 'maalam_ch2_tadarruj', 'kharji_maalam_tariq_talab', 0, '«مِنْ أَفْظَعِ الأَخْطَاءِ الَّتِي تُهْلِكُ الطَّالِبَ: العَجَلَةُ وَالقَفْزُ إِلَى المُطَوَّلَاتِ وَالخِلَافِ العَالِي قَبْلَ إِحْكَامِ الأُصُولِ؛ فَقَدْ قِيلَ: «مَنْ رَامَ العِلْمَ جُمْلَةً ذَهَبَ عَنْهُ جُمْلَةً!». وَسُنَّةُ اللَّهِ فِي التَّعْلِيمِ هِيَ التَّدَرُّجُ؛ كَمَا قَالَ تَعَالَى: {وَلَكِنْ كُونُوا رَبَّانِيِّينَ بِمَا كُنْتُمْ تُعَلِّمُونَ الْكِتَابَ وَبِمَا كُنْتُمْ تَدْرُسُونَ}. قَالَ ابْنُ عَبَّاسٍ: الرَّبَّانِيُّ هُوَ الَّذِي يُرَبِّي النَّاسَ بِصِغَارِ العِلْمِ قَبْلَ كِبَارِهِ».', 'شیخ السدحان فرماتے ہیں: ''طالب علم کو ہلاک کرنے والی سب سے بھیانک غلطیوں میں سے جلد بازی اور بنیادی قواعد کی پختگی سے پہلے بڑی ضخیم کتب اور اختلافی مباحث میں چھلانگ لگانا ہے؛ جیسا کہ اسلاف نے فرمایا: ''جس نے علم کو ایک ہی گھونٹ میں یکمشت پینا چاہا علم اس کے پاس سے یکمشت رخصت ہو گیا!'' اور تعلیم و تربیت میں اللہ کا قانون بتدریج آگے بڑھنا ہے، جیسا کہ اللہ کا فرمان ہے: {بلکہ تم ربانی بنو اس وجہ سے کہ تم کتاب کی تعلیم دیتے ہو اور اسے پڑھتے ہو}۔ حضرت ابن عباس رضی اللہ عنہما نے فرمایا: ''ربانی وہ کامل استاد ہوتا ہے جو لوگوں کو بڑے اور مشکل علوم سکھانے سے پہلے بنیادی اور آسان علوم سکھا کر ان کی فکری تربیت کرتا ہے''۔', 'چھوٹے متون کو یاد کیے بغیر بڑی کتابوں کا مطالعہ انسان کو نیم حکیم اور متکبر بنا دیتا ہے۔ بنیاد جتنی گہری ہوگی عمارت اتنی ہی پائیدار ہوگی۔', '[{"word":"جُمْلَةً","role":"حال منصوب","sign":"فتحة","detail":"يفيد الإحاطة دفعة واحدة"},{"word":"رَبَّانِيِّينَ","role":"خبر كونوا منصوب","sign":"ياء","detail":"جمع مذكر سالم"}]', '["معالم في طريق طلب العلم، ص 40-52."]', '{"en":"Methodological Gradualism: ''Whoever seeks knowledge in a single leap will lose it entirely.'' Ibn Abbas defines a divine scholar (Rabbani) as one who nurtures people with foundational elementary sciences prior to complex scholastic treatises.","ar":"قاعدة التدرج التربوي وحفظ الطالب من آفة التشتت والقفز على الأصول."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_sharaf_ashab_hadith', 'شَرَفُ أَصْحَابِ الحَدِيثِ', 'الحَافِظُ أَبُو بَكْرٍ الخَطِيبُ البَغْدَادِيُّ (ت: 463ھ)', 'kharji_kitab', 'adab', 'اہلِ حدیث، رواۃ اور محدثین کی فضیلت و شرف', 'کتبِ مطالعہ و علومِ حدیث', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'رسول اللہ ﷺ کی احادیث نقل کرنے اور ان کی حفاظت کرنے والوں کے دنیا و آخرت میں عظیم ترین درجات۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sharaf_hadith_ch1_fadl', 'kharji_sharaf_ashab_hadith', 0, 'بَابُ شَرَفِ أَهْلِ الحَدِيثِ وَأَنَّهُمُ الطَّائِفَةُ المَنْصُورَةُ', 'باب 1: اصحابِ حدیث کا شرف — سنت کے پاسبان اور قیامت تک قائم رہنے والی طائفۂ منصورہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sharaf_hadith_seg_1_1', 'sharaf_hadith_ch1_fadl', 'kharji_sharaf_ashab_hadith', 0, 'قَالَ الحَافِظُ أَبُو بَكْرٍ الخَطِيبُ البَغْدَادِيُّ: «جَعَلَ اللَّهُ تَعَالَى أَهْلَ الحَدِيثِ أَرْكَانَ الشَّرِيعَةِ، وَهَدَمَ بِهِمْ كُلَّ بِدْعَةٍ شَنِيعَةٍ؛ فَهُمْ حُمَاةُ الدِّينِ، وَأُمَنَاءُ النَّبِيِّ ﷺ فِي أُمَّتِهِ. عَنْ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الحَقِّ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ وَهُمْ كَذَلِكَ». قَالَ الإِمَامُ أَحْمَدُ بْنُ حَنْبَلٍ: «إِنْ لَمْ يَكُونُوا أَهْلَ الحَدِيثِ فَلَا أَدْرِي مَنْ هُمْ!».', 'حافظ ابو بکر خطیب بغدادی رحمہ اللہ فرماتے ہیں: ''اللہ تعالیٰ نے محدثین اور اصحابِ حدیث کو شریعت کے مضبوط ستون بنایا ہے، اور ان کے قلم اور تحقیق کے ذریعے ہر بری بدعت کی عمارت کو منہدم فرمایا ہے؛ پس وہی دین کے حقیقی محافظ اور اپنی امت میں رسول اللہ ﷺ کے معتمد امانت دار ہیں۔ حضرت معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''میری امت میں سے ایک جماعت ہمیشہ حق پر غالب رہے گی، ان کی مدد چھوڑنے والے ان کا کچھ نہیں بگاڑ سکیں گے یہاں تک کہ اللہ کا حکم (قیامت) آ جائے اور وہ اسی طرح ڈٹے ہوئے ہوں گے''۔ امام احمد بن حنبل فرماتے ہیں: ''اگر یہ طائفۂ منصورہ اصحابِ حدیث نہیں ہیں تو میری سمجھ میں نہیں آتا کہ روئے زمین پر وہ اور کون ہو سکتے ہیں!''', 'شرف أصحاب الحديث خطیب بغدادی کی وہ کتاب ہے جس نے محدثین کے اس بے مثال مقام کو احادیث اور آثار کی روشنی میں ثابت کیا جنہوں نے حدیث کی حفاظت کے لیے اپنی زندگیاں نچھاور کیں۔', '[{"word":"أَرْكَانَ","role":"مفعول به ثان لجعل منصوب","sign":"فتحة","detail":"أهل مفعول أول وأركان ثانٍ"},{"word":"ظَاهِرِينَ","role":"خبر لا تزال منصوب","sign":"ياء","detail":"جمع مذكر سالم"}]', '["شرف أصحاب الحديث للخطيب البغدادي، ص 15-28، وأخرجه البخاري (7311)."]', '{"en":"Khatib al-Baghdadi celebrates the Nobility of Hadith Scholars (Sharaf Ashab al-Hadith): Pillars of Shariah destroying innovation. Citing the Prophet''s prophecy of the Victorious Group (At-Ta''ifah al-Mansurah), regarding which Imam Ahmad declared: ''If they are not the scholars of Hadith, I know not who they could be!''","ar":"المكانة الرفيعة لحملة الآثار النبوية ودفاعهم عن حياض الشريعة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sharaf_hadith_ch2_salat', 'kharji_sharaf_ashab_hadith', 1, 'بَابُ اخْتِصَاصِ أَهْلِ الحَدِيثِ بِكَثْرَةِ الصَّلَاةِ عَلَى النَّبِيِّ ﷺ', 'باب 2: کثرتِ درود — اصحابِ حدیث کو رسول اللہ ﷺ پر سب سے زیادہ درود و سلام بھیجنے کی خصوصی سعادت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sharaf_hadith_seg_2_1', 'sharaf_hadith_ch2_salat', 'kharji_sharaf_ashab_hadith', 0, '«مِنْ أَعْظَمِ فَضَائِلِ طَلَبَةِ الحَدِيثِ وَكَتَبَتِهِ: أَنَّهُمْ أَكْثَرُ النَّاسِ صَلَاةً عَلَى رَسُولِ اللَّهِ ﷺ؛ فَلَا يَمُرُّ عَلَيْهِمْ سَطْرٌ إِلَّا وَفِيهِ ذِكْرُ النَّبِيِّ ﷺ فَيُصَلُّونَ وَيُسَلِّمُونَ عَلَيْهِ خَطّاً وَلَفْظاً. عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «أَوْلَى النَّاسِ بِي يَوْمَ القِيَامَةِ أَكْثَرُهُمْ عَلَيَّ صَلَاةً». قَالَ سُفْيَانُ الثَّوْرِيُّ: «لَوْ لَمْ يَكُنْ لِصَاحِبِ الحَدِيثِ فَائِدَةٌ إِلَّا الصَّلَاةُ عَلَى رَسُولِ اللَّهِ ﷺ لَكَفَاهُ ذَلِكَ شَرَفاً فِي الدُّنْيَا وَالآخِرَةِ».', 'خطیب بغدادی فرماتے ہیں: ''حدیث کے طلبہ اور اس کے لکھنے والوں کی سب سے عظیم ترین فضیلت یہ ہے کہ وہ روئے زمین کے تمام انسانوں میں رسول اللہ ﷺ پر سب سے زیادہ درود و سلام بھیجنے والے ہیں؛ ان کے قلم کے نیچے سے کوئی سطر ایسی نہیں گزرتی جس میں رسول اللہ ﷺ کا مبارک نام نہ آئے اور وہ تحریراً اور زباناً آپ ﷺ پر درود و سلام نہ پڑھتے ہوں۔ حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ ﷺ نے فرمایا: ''قیامت کے دن مجھ سے سب سے زیادہ قریب وہ شخص ہوگا جو مجھ پر سب سے زیادہ درود بھیجتا ہو''۔ امام سفیان ثوری رحمہ اللہ فرماتے ہیں: ''اگر طالبِ حدیث کے لیے حدیث لکھنے کے سوا کوئی اور فائدہ نہ ہوتا سوائے اس کے کہ وہ ہر لمحہ رسول اللہ ﷺ پر درود پڑھتا رہتا ہے، تو دنیا اور آخرت کے شرف کے لیے اکیلی یہی بات اس کے لیے کافی تھی!''', 'محدثین کے قلم اور انگلیاں ہر لمحہ ''صلی اللہ علیہ وسلم'' لکھتی رہتی ہیں، یہ وہ روحانی انعام ہے جو کسی اور پیشے یا فن کے طالب علم کو نصیب نہیں ہوتا۔', '[{"word":"أَكْثَرُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"هم اسمها وأكثر خبرها"},{"word":"أَوْلَى","role":"مبتدأ مرفوع بضمة مقدرة","sign":"ضمة مقدرة","detail":"أكثرهم خبر المبتدأ"}]', '["شرف أصحاب الحديث، ص 68-75، وأخرجه الترمذي (484)."]', '{"en":"The unrivaled blessing of Hadith students: Being the foremost in sending blessings upon the Prophet ﷺ in both manuscript ink and spoken voice. ''The closest people to me on the Day of Resurrection are those who sent the most blessings upon me.''","ar":"بركة الصلاة الدائمة على الحبيب المصطفى ﷺ لأهل السنن والآثار."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_tawqir_ulama_alawi', 'تَوْقِيرُ العُلَمَاءِ وَتَعْظِيمُ شَعَائِرِ الدِّينِ', 'خَاتِمَةُ المُحَقِّقِينَ العَلَّامَةُ مُحَمَّدٌ أَمِينٌ ابْنُ عَابِدِينَ الحَنَفِيُّ (ت: 1252ھ)', 'kharji_kitab', 'adab', 'علماء و فقہاء کی تعظیم اور ان کی بے ادبی کی وعیدیں', 'کتبِ مطالعہ و ادبِ فقہ', NULL, NULL, 'from-stone-900 via-emerald-950 to-teal-950', NULL, 'علماء اور حاملینِ قرآن کا احترام شریعت کی تعظیم ہے؛ ان کی غیبت اور توہین کے سنگین دینی و دنیاوی خطرات۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tawqir_ulama_ch1_hurmah', 'kharji_tawqir_ulama_alawi', 0, 'بَابُ تَوْقِيرِ العُلَمَاءِ وَتَعْظِيمِ حُرُمَاتِهِمْ فِي المِلَّةِ الإِسْلَامِيَّةِ', 'باب 1: علماء کی تعظیم اور اسلامی معاشرے میں ان کا مقدس مقام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tawqir_ulama_seg_1_1', 'tawqir_ulama_ch1_hurmah', 'kharji_tawqir_ulama_alawi', 0, 'قَالَ خَاتِمَةُ المُحَقِّقِينَ العَلَّامَةُ مُحَمَّدٌ أَمِينٌ ابْنُ عَابِدِينَ الحَنَفِيُّ: «اعْلَمْ أَنَّ حُرْمَةَ العَالِمِ فِي الإِسْلَامِ عَظِيمَةٌ؛ لِأَنَّهُ حَامِلٌ لِشَرِيعَةِ اللَّهِ وَوَارِثٌ لِنَبِيِّهِ ﷺ، فَتَوْقِيرُهُ تَوْقِيرٌ لِلشَّرْعِ الشَّرِيفِ، وَاسْتِخْفَافُهُ اسْتِخْفَافٌ بِالدِّينِ. عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَيْسَ مِنْ أُمَّتِي مَنْ لَمْ يُجِلَّ كَبِيرَنَا، وَيَرْحَمْ صَغِيرَنَا، وَيَعْرِفْ لِعَالِمِنَا حَقَّهُ!». وَكَانَ السَّلَفُ يُعَظِّمُونَ أَئِمَّتَهُمْ حَتَّى كَانَ الشَّافِعِيُّ يَقُولُ: كُنْتُ أَصْفَحُ الوَرَقَةَ بَيْنَ يَدَيْ مَالِكٍ صَفْحاً رَفِيقاً لِئَلَّا يَسْمَعَ وَقْعَهَا!».', 'خاتمۃ المحققین علامہ محمد امین ابن عابدین شامی حنفی رحمہ اللہ فرماتے ہیں: ''خوب جان لو کہ اسلام میں عالمِ دین کی حرمت اور احترام انتہا درجے کا فریضہ ہے؛ کیونکہ وہ اللہ کی شریعت کا حامل اور اس کے نبی ﷺ کا وارث ہے، پس عالم کی تعظیم درحقیقت شریعت کی تعظیم ہے، اور عالم کی تحقیر و توہین دین کی توہین ہے۔ حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''وہ شخص میری امت میں سے نہیں جو ہمارے بڑوں کی عزت نہ کرے، ہمارے چھوٹوں پر رحم نہ کرے، اور ہمارے عالم کے واجب حق کو نہ پہچانے!'' اور سلف صالحین اپنے اساتذہ کا اس قدر ادب کرتے تھے کہ امام شافعی فرماتے ہیں: ''میں امام مالک کی مجلس میں کتاب کا ورق بھی اتنی آہستہ سے پلٹتا تھا تاکہ کہیں امام مالک کے کانوں میں ورق پلٹنے کی آواز نہ چلی جائے اور ان کے درس میں خلل نہ پڑے!''', 'کتاب ''توقير العلماء وتعظيم شعائر الدين'' علامہ ابن عابدین حنفی کا وہ رسالہ ہے جس میں انہوں نے علماء کے احترام کے فقہی اور اخلاقی احکام مدون کیے۔', '[{"word":"حُرْمَةَ","role":"اسم أنّ منصوب","sign":"فتحة","detail":"عظيمة خبر أنّ مرفوع"},{"word":"صَفْحاً","role":"مفعول مطلق منصوب","sign":"فتحة","detail":"رفيقاً نعت له"}]', '["رسائل ابن عابدين، رسالة توقير العلماء، 2/ 240-255، وأخرجه أحمد (22755)."]', '{"en":"Ibn ''Abidin articulates the sacred sanctity of Islamic scholars: Honoring them is honoring the Shariah they embody. The Prophet ﷺ declared: ''He is not of my nation who does not revere our elders, show mercy to our youngsters, and acknowledge the right of our scholar!''","ar":"مكانة أهل العلم وحرمة النيل من كرامتهم في المجتمع المسلم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tawqir_ulama_ch2_tahdhir_tanqis', 'kharji_tawqir_ulama_alawi', 1, 'خُطُورَةُ الطَّعْنِ فِي العُلَمَاءِ وَأَنَّ «لُحُومَ العُلَمَاءِ مَسْمُومَةٌ»', 'باب 2: علماء پر زبان درازی کا ہولناک وبال — ''علماء کا گوشت زہریلا ہے''');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tawqir_ulama_seg_2_1', 'tawqir_ulama_ch2_tahdhir_tanqis', 'kharji_tawqir_ulama_alawi', 0, '«قَالَ الحَافِظُ ابْنُ عَسَاكِرَ الدِّمَشْقِيُّ فِي كَلِمَتِهِ الشَّهِيرَةِ الَّتِي رَوَاهَا ابْنُ عَابِدِينَ: «اعْلَمْ يَا أَخِي أَنَّ لُحُومَ العُلَمَاءِ مَسْمُومَةٌ، وَعَادَةَ اللَّهِ فِي هَتْكِ أَسْتَارِ مُنْتَقِصِيهِمْ مَعْلُومَةٌ؛ فَإِنَّ مَنْ أَطْلَقَ لِسَانَهُ فِي العُلَمَاءِ بِالثَّلْبِ، بَلَاهُ اللَّهُ تَعَالَى قَبْلَ مَوْتِهِ بِمَوْتِ القَلْبِ! فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ». فَالطَّعْنُ فِي حَمَلَةِ الشَّرِيعَةِ طَعْنٌ فِي الشَّرِيعَةِ نَفْسِهَا؛ لِأَنَّهُمُ الوَاسِطَةُ فِي نَقْلِهَا إِلَيْنَا».', 'علامہ ابن عابدین نے حافظ ابن عساکر دمشقی کا وہ تاریخی مقولہ نقل فرمایا: ''اے میرے بھائی! خوب جان لے کہ علماء کی غیبت اور ان کا گوشت زہریلا ہے، اور ان کی تنقیص اور عیب جوئی کرنے والوں کے پردے چاک کرنا اللہ کی پرانی اور معلوم سنت ہے؛ پس جس شخص نے علماء کی بدگوئی اور بے ادبی میں اپنی زبان دراز کی، اللہ تعالیٰ اسے مرنے سے پہلے ہی دل کی موت (بے حسی و گمراہی) میں مبتلا فرما دیتا ہے! پس ڈرنا چاہیے ان لوگوں کو جو اللہ کے حکم کی مخالفت کرتے ہیں کہ کہیں ان پر کوئی بڑا فتنہ یا دردناک عذاب نہ آ پڑے''۔ کیونکہ شریعت کے حاملین پر طعن و تشنیع کرنا دراصل خود شریعتِ اسلامیہ کو مشکوک بنانے کے مترادف ہے؛ کیونکہ وہی وہ واسطہ ہیں جن کے ذریعے دین ہم تک پہنچا ہے''۔', 'جو معاشرہ اپنے علماء کی عزت کھو دیتا ہے وہ باطل فتنوں اور گمراہی کا تر نوالہ بن جاتا ہے۔ علماء کی کردار کشی دراصل دین کے دفاعی حصار کو توڑنے کی شیطانی سازش ہے۔', '[{"word":"مَسْمُومَةٌ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"لحوم اسمها ومسمومة خبرها"},{"word":"بِمَوْتِ","role":"جار ومجرور متعلق ببلاه","sign":"کسرة","detail":"وهو مضاف والقلب مضاف إليه"}]', '["تبيين كذب المفتري لابن عساكر، ص 29-32، ورسائل ابن عابدين."]', '{"en":"Ibn ''Asakir''s immortal axiom cited by Ibn ''Abidin: ''The flesh of scholars is poisoned, and Allah''s habit of uncovering the secrets of their denigrators is well known! Whoever looses his tongue against scholars with slander, Allah afflicts him before death with the death of the heart!''","ar":"عقوبة الخوض في أعراض العلماء وهتك أستار المتطاولين على ورثة الأنبياء."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_nafhat_arab_iazaz', 'نَفْحَةُ العَرَبِ فِي مُحَاسِنِ الأَدَبِ', 'شَيْخُ الأَدَبِ وَالفِقْهِ العَلَّامَةُ مُحَمَّدٌ إِعْزَازُ عَلِيٍّ اللَّكْنَوِيُّ (ت: 1374ھ)', 'kharji_kitab', 'adab', 'عربی ادب، امثال، حکایات و انشاء', 'کتبِ مطالعہ و درجہ رابعہ / خامسہ نصاب', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'دار العلوم دیوبند کے شیخ الادب کی وہ بے نظیر ادبی کتاب جس نے برصغیر کے لاکھوں طلبہ میں عربی ادب، بلاغت اور انشاء کا ذوق پیدا کیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nafhat_arab_ch1_adab', 'kharji_nafhat_arab_iazaz', 0, 'البَابُ الأَوَّلُ: فِي مَحَاسِنِ الأَدَبِ وَنَوَادِرِ الفُصَحَاءِ وَالأَعْرَابِ', 'باب 1: عربی ادب کے محاسن — فصحاء اور بدوی قبائل کے بلیغ اور حاضر جواب قصے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nafhat_arab_seg_1_1', 'nafhat_arab_ch1_adab', 'kharji_nafhat_arab_iazaz', 0, 'قَالَ شَيْخُ الأَدَبِ العَلَّامَةُ مُحَمَّدٌ إِعْزَازُ عَلِيٍّ اللَّكْنَوِيُّ: «الأَدَبُ زِينَةُ العَقْلِ، وَحِلْيَةُ اللِّسَانِ؛ قِيلَ لِأَعْرَابِيٍّ: مَا المُرُوءَةُ فِيكُمْ؟ قَالَ: «العِفَّةُ عَمَّا حَرَّمَ اللَّهُ، وَالحِلْمُ عِنْدَ الغَضَبِ، وَإِقْرَاءُ الضَّيْفِ، وَإِعَانَةُ المَلْهُوفِ». وَوَقَفَ أَعْرَابِيٌّ عَلَى قَوْمٍ فَقَالَ: «أَصْلَحَكُمُ اللَّهُ، إِنَّ اللَّهَ أَعْطَاكُمْ مَا تَمُنُّونَ بِهِ عَلَى غَيْرِكُمْ، فَلَا تَمْنَعُونَا مَا نَسْأَلُكُمْ فَتَكُونُوا كَمَنْ يُبَدِّلُ نِعْمَةَ اللَّهِ كُفْراً! فَرَقَّتْ لَهُ قُلُوبُهُمْ وَأَعْطَوْهُ مَا سَأَلَ».', 'شیخ الادب والفقه علامہ محمد اعزاز علی امروہوی لکھنوی رحمہ اللہ فرماتے ہیں: ''ادب عقل کی زینت اور زبان کا حسن و جمال ہے؛ ایک دیہاتی بدو سے پوچھا گیا: تمہارے نزدیک مروءت اور شرافت کیا ہے؟ اس نے جواب دیا: ''اللہ کی حرام کردہ چیزوں سے پاک دامن رہنا، غصے کے وقت بردباری اختیار کرنا، مہمان کی دل کھول کر ضیافت کرنا، اور مصیبت زدہ مظلوم کی مدد کرنا''۔ اور ایک اعرابی ایک محفل میں کھڑا ہوا اور بڑے بلیغ انداز میں گویا ہوا: ''اللہ تمہاری اصلاح فرمائے، اللہ نے تمہیں وہ مال و دولت عطا کی ہے جس سے تم دوسروں پر احسان کر سکتے ہو، لہٰذا جو سوال ہم تم سے کرتے ہیں وہ ہمیں دینے سے انکار نہ کرو ورنہ تم ان لوگوں جیسے ہو جاؤ گے جو اللہ کی نعمت کا شکر ناشکری اور بخل سے بدل دیتے ہیں!'' پس اس کے فصیح کلام سے ان کے دل پگھل گئے اور انہوں نے اس کی ضرورت سے بڑھ کر اسے عطا کیا''۔', 'نفحة العرب درسِ نظامی کے نصاب میں عربی ادب اور انشا کی معتبر ترین کتاب ہے جسے شیخ الادب اعزاز علی نے طلبہ میں عربی ذوق اور فصاحت پیدا کرنے کے لیے مرتب فرمایا۔', '[{"word":"زِينَةُ","role":"خبر المبتدأ الأدب مرفوع","sign":"ضمة","detail":"وهو مضاف والعقل مضاف إليه"},{"word":"كُفْراً","role":"مفعول به ثان ليبدل منصوب","sign":"فتحة","detail":"نعمة مفعول أول وكفراً ثانٍ"}]', '["نفحة العرب في محاسن الأدب لمحمد إعزاز علي، ص 10-22."]', '{"en":"Shaykh al-Adab I''zaz ''Ali''s masterpiece ''Nafhat al-''Arab'': The aesthetic eloquence of Bedouin Arabic. When a nomad was asked defining virtue (Muru''ah), he replied: ''Chastity from divine prohibitions, forbearance in wrath, lavish hospitality to guests, and rushing to aid the distressed.''","ar":"روائع الأدب العربي ونوادر البلاغة البدوية وحسن الجواب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nafhat_arab_ch2_hikam', 'kharji_nafhat_arab_iazaz', 1, 'البَابُ الثَّانِي: فِي حِكَمِ البُلَغَاءِ وَوَصَايَا الحُكَمَاءِ لِلأَبْنَاءِ', 'باب 2: دانائے عرب کے حکیمانہ اقوال اور اولاد کے لیے سنہری وصیتیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nafhat_arab_seg_2_1', 'nafhat_arab_ch2_hikam', 'kharji_nafhat_arab_iazaz', 0, '«أَوْصَى حَكِيمٌ ابْنَهُ فَقَالَ: «يَا بُنَيَّ، إِيَّاكَ وَالنَّمِيمَةَ؛ فَإِنَّهَا تَزْرَعُ الضَّغِينَةَ، وَتُفَرِّقُ بَيْنَ الإِخْوَةِ. وَإِيَّاكَ وَكَثْرَةَ المِزَاحِ؛ فَإِنَّهُ يُذْهِبُ البَهَاءَ، وَيُجَرِّئُ عَلَيْكَ السُّفَهَاءَ. وَعَلَيْكَ بِحُسْنِ الخُلُقِ؛ فَإِنَّ الخُلُقَ الحَسَنَ كَالشَّجَرَةِ الطَّيِّبَةِ: أَصْلُهَا ثَابِتٌ فِي القُلُوبِ، وَفَرْعُهَا ثَنَاءٌ جَمِيلٌ فِي الآفَاقِ. وَكُنْ كَالنَّحْلَةِ: لَا تَأْكُلُ إِلَّا طَيِّباً، وَلَا تَضَعُ إِلَّا طَيِّباً، وَإِذَا وَقَعَتْ عَلَى عُودٍ هَشٍّ لَمْ تَكْسِرْهُ».', 'علامہ اعزاز علی نقل فرماتے ہیں: ''ایک عرب دانا نے اپنے بیٹے کو وصیت کرتے ہوئے فرمایا: ''اے میرے پیارے بیٹے! چغل خوری سے سخت پرہیز کرنا؛ کیونکہ یہ دلوں میں کینہ اور دشمنی کا بیج بوتی ہے، اور سگے بھائیوں کے درمیان جدائی ڈال دیتی ہے۔ اور زیادہ ہنسی مذاق اور مسخرا پن کرنے سے بچنا؛ کیونکہ یہ چہرے کے رعب اور وقار کو بہا لے جاتا ہے، اور کم ظرف بیوقوفوں کو تم پر زبان درازی کی جرأت دیتا ہے۔ اور ہمیشہ حسنِ اخلاق کو اپنا شیوہ بنانا؛ کیونکہ اچھا اخلاق ایک پاکیزہ درخت کی طرح ہے: جس کی جڑیں لوگوں کے دلوں میں پیوست ہوتی ہیں، اور اس کی شاخیں دنیا بھر میں انسان کی نیک نامی کی صورت میں پھیلتی ہیں۔ اور شہد کی مکھی کی مانند بننا: جو صرف پاکیزہ پھولوں کا رس چوستی ہے، اور صرف پاکیزہ و میٹھا شہد بناتی ہے، اور اگر کسی کمزور نازک شاخ پر بھی بیٹھ جائے تو اسے توڑتی نہیں ہے''۔', 'شہد کی مکھی کی یہ تمثیل ایک مومن کے عمدہ کردار کا سب سے خوبصورت نقشہ ہے کہ اس کا بولنا، کھانا اور اٹھنا بیٹھنا سراپا امن اور برکت ہونا چاہیے۔', '[{"word":"إِيَّاكَ","role":"ضمير نصب منفصل في محل نصب مفعول به لفعل محذوف وجوباً","sign":"مبني","detail":"أسلوب تحذير"},{"word":"طَيِّباً","role":"مفعول به لتأكل منصوب","sign":"فتحة","detail":"استثناء مفرغ"}]', '["نفحة العرب، باب الوصايا والحكم، ص 65-78."]', '{"en":"A sage''s counsel to his son: Beware of talebearing (Namimah) for it sows malice; shun excessive frivolity for it strips away dignity; embody noble character like a sweet tree rooted in hearts, and be like the honeybee—consuming only purity and producing only sweetness without snapping the fragile twig.","ar":"جوامع الوصايا التربوية في حفظ المروءة وطيب المعشر."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_nahw_wadih', 'النَّحْوُ الوَاضِحُ فِي قَوَاعِدِ اللُّغَةِ العَرَبِيَّةِ', 'الأُسْتَاذُ عَلِيُّ الجَارِمُ وَمُصْطَفَى أَمِينٌ', 'kharji_kitab', 'nahw', 'قواعدِ نحو کا جدید اسلوب، امثلہ و تمرینات', 'کتبِ مطالعہ و تسہیلِ نحو', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'عربی نحو کی سب سے آسان، منظم اور جدید ترین کتاب جس میں مثالوں اور استنباط کے ذریعے قواعد سکھائے گئے ہیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nahw_wadih_ch1_jumla', 'kharji_nahw_wadih', 0, 'الجُمْلَةُ المُفِيدَةُ وَأَجْزَاءُ الكَلَامِ: الِاسْمُ وَالفِعْلُ وَالحَرْفُ', 'باب 1: جملۂ مفیدہ کی تعریف اور کلام کے تین اجزاء (اسم، فعل، حرف) کی شناخت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nahw_wadih_seg_1_1', 'nahw_wadih_ch1_jumla', 'kharji_nahw_wadih', 0, 'قَالَ الأُسْتَاذُ عَلِيُّ الجَارِمُ وَمُصْطَفَى أَمِينٌ: «الجُمْلَةُ المُفِيدَةُ: هِيَ كُلُّ تَرْكِيبٍ يُفِيدُ فَائِدَةً تَامَّةً يَحْسُنُ سُكُوتُ المُتَكَلِّمِ عَلَيْهَا، مِثْلُ: «البُسْتَانُ جَمِيلٌ» وَ«طَلَعَتِ الشَّمْسُ». وَأَجْزَاءُ الكَلَامِ ثَلَاثَةٌ لَا مَزِيدَ عَلَيْهَا: 1. الِاسْمُ: وَهُوَ كُلُّ لَفْظٍ يُسَمَّى بِهِ إِنْسَانٌ أَوْ حَيَوَانٌ أَوْ نَبَاتٌ أَوْ جَمَادٌ أَوْ أَيُّ شَيْءٍ آخَرَ دُونَ دَلَالَةٍ عَلَى الزَّمَنِ. 2. الفِعْلُ: وَهُوَ كُلُّ لَفْظٍ يَدُلُّ عَلَى حُصُولِ عَمَلٍ فِي زَمَنٍ خَاصٍّ (مَاضٍ أَوْ مُضَارِعٌ أَوْ أَمْرٌ). 3. الحَرْفُ: وَهُوَ كُلُّ لَفْظٍ لَا يَظْهَرُ مَعْنَاهُ كَامِلاً إِلَّا مَعَ غَيْرِهِ مِثْلُ: فِي، وَعَلَى، وَمِنْ».', 'استاذ علی الجارم اور مصطفیٰ امین رحمہما اللہ فرماتے ہیں: ''جملۂ مفیدہ ہر اس بامعنی کلامی مرکب کو کہتے ہیں جس سے پوری اور مکمل بات سمجھ میں آ جائے اس طرح کہ بولنے والے کے خاموش ہو جانے پر سننے والے کو کسی اور بات کا انتظار نہ رہے، جیسے: ''باغ خوبصورت ہے'' اور ''سورج طلوع ہو گیا''۔ اور عربی زبان میں کلام کے صرف تین ہی اجزاء ہوتے ہیں: 1. اسم: وہ لفظ جو کسی انسان، جانور، پودے، بے جان چیز یا کسی صفت کا نام ہو بغیر اس کے کہ اس میں کوئی زمانہ پایا جائے۔ 2. فعل: وہ لفظ جو کسی خاص زمانے (ماضی، حال یا مستقبل) میں کسی کام کے واقع ہونے پر دلالت کرے۔ 3. حرف: وہ لفظ جس کا اپنا مکمل معنی دوسرے الفاظ کے ساتھ ملے بغیر اکیلے ظاہر نہ ہو سکے، جیسے: في، على، اور من''۔', 'النحو الواضح عربی گرائمر سکھانے کی جدید تاریخ کی سب سے شاندار اور آسان ترین کتاب ہے جس نے روایتی پیچیدگیوں کو ختم کر کے مثالوں اور تمارین کے ذریعے نحو کو عام فہم بنایا۔', '[{"word":"جَمِيلٌ","role":"خبر المبتدأ البستان مرفوع","sign":"ضمة","detail":"يكمل الفائدة التامة"},{"word":"ثَلَاثَةٌ","role":"خبر المبتدأ أجزاء مرفوع","sign":"ضمة","detail":"أجزاء مبتدأ وثلاثة خبره"}]', '["النحو الواضح في قواعد اللغة العربية، المرحلة الابتدائية، 1/ 5-15."]', '{"en":"Al-Jarim and Amin''s pedagogical classic ''An-Nahw al-Wadih'': Defining the Complete Sentence (Al-Jumlat al-Mufidah) and classifying speech into its three fundamental components: Noun (Ism), Verb (Fi''l), and Particle (Harf).","ar":"التأصيل المنهجي التعليمي المبسط لأركان الجملة العربية وأقسام الكلم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('nahw_wadih_ch2_fayil_maful', 'kharji_nahw_wadih', 1, 'الفَاعِلُ وَالمَفْعُولُ بِهِ وَالمُبْتَدَأُ وَالخَبَرُ: مَبَادِئُ الإِعْرَابِ', 'باب 2: فاعل، مفعول بہ، اور مبتدا و خبر — اعراب کے بنیادی قواعد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('nahw_wadih_seg_2_1', 'nahw_wadih_ch2_fayil_maful', 'kharji_nahw_wadih', 0, '«الفَاعِلُ: اسْمٌ مَرْفُوعٌ تَقَدَّمَهُ فِعْلٌ وَدَلَّ عَلَى مَنْ قَامَ بِالفِعْلِ، مِثْلُ: «فَازَ المُجْتَهِدُ». وَالمَفْعُولُ بِهِ: اسْمٌ مَنْصُوبٌ وَقَعَ عَلَيْهِ فِعْلُ الفَاعِلِ، مِثْلُ: «قَرَأَ التِّلْمِيذُ كِتَاباً». وَالمُبْتَدَأُ: اسْمٌ مَرْفُوعٌ يَقَعُ فِي أَوَّلِ الجُمْلَةِ، وَالخَبَرُ: اسْمٌ مَرْفُوعٌ يُكَوِّنُ مَعَ المُبْتَدَأِ جُمْلَةً مُفِيدَةً، مِثْلُ: «الصِّدْقُ فَضِيلَةٌ». وَالأَصْلُ فِي الإِعْرَابِ: الرَّفْعُ بِالضَّمَّةِ، وَالنَّصْبُ بِالفَتْحَةِ، وَالجَرُّ بِالكَسْرَةِ، وَالجَزْمُ بِالسُّكُونِ».', 'مصنفین فرماتے ہیں: ''فاعل وہ مرفوع اسم ہے جس سے پہلے فعل واقع ہو اور وہ اس بات پر دلالت کرے کہ کام کس نے کیا ہے، جیسے: ''محنتی طالب علم کامیاب ہو گیا''۔ اور مفعول بہ وہ منصوب اسم ہے جس پر فاعل کا فعل واقع ہوا ہو، جیسے: ''شاگرد نے کتاب پڑھی''۔ اور مبتدا وہ مرفوع اسم ہے جو جملے کے آغاز میں آئے، اور خبر وہ مرفوع اسم ہے جو مبتدا کے ساتھ مل کر بات کو مکمل کر دے، جیسے: ''سچائی بڑی فضیلت ہے''۔ اور عربی زبان میں اعراب کی اصل علامات چار ہیں: رفع کی علامت ضمہ (پیش)، نصب کی علامت فتحہ (زبر)، جر کی علامت کسرہ (زیر)، اور جزم کی علامت سکون (جزم) ہے''۔', 'یہ چار بنیادی ستون عربی زبان کے ڈھانچے کو سمجھنے کی بنیاد ہیں۔ جب تک طالب علم کو فاعل اور مفعول کا اعرابی فرق معلوم نہ ہو وہ قرآن کی آیات کا صحیح معنی نہیں سمجھ سکتا۔', '[{"word":"المُجْتَهِدُ","role":"فاعل فاز مرفوع","sign":"ضمة ظاهرة","detail":"قام بالفعل"},{"word":"كِتَاباً","role":"مفعول به منصوب","sign":"فتحة","detail":"وقع عليه فعل القراءة"}]', '["النحو الواضح، 1/ 25-40."]', '{"en":"Core Syntactic Roles: Fa''il (Subject performing the act, Nominative with Dammah), Maf''ul bihi (Direct Object receiving the act, Accusative with Fathah), Mubtada'' and Khabar (Subject and Predicate), and the four primordial grammatical inflections.","ar":"قواعد المرفوعات والمنصوبات وعلامات الإعراب الأصلية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_balaghah_wadihah', 'البَلَاغَةُ الوَاضِحَةُ: البَيَانُ وَالمَعَانِي وَالبَدِيعُ', 'الأُسْتَاذُ عَلِيُّ الجَارِمُ وَمُصْطَفَى أَمِينٌ', 'kharji_kitab', 'balaghah', 'علمِ بیان، علمِ معانی اور علمِ بدیع کا جدید طریقہ', 'کتبِ مطالعہ و فنِ بلاغت', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'تشبیہ، استعارہ، کنایہ، اور صنایع و بدائع کو قرآنی آیات اور فصیح اشعار کی مثالوں سے سکھانے والی شاہکار نصابی کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('balaghah_wadihah_ch1_tashbih', 'kharji_balaghah_wadihah', 0, 'عِلْمُ البَيَانِ: أَرْكَانُ التَّشْبِيهِ وَأَقْسَامُهُ (المُؤَكَّدُ وَالبَلِيغُ)', 'باب 1: علمِ بیان — تشبیہ کے چار ارکان اور تشبیہ بلیغ کا اعجاز');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('balaghah_wadihah_seg_1_1', 'balaghah_wadihah_ch1_tashbih', 'kharji_balaghah_wadihah', 0, 'قَالَ عَلِيُّ الجَارِمُ وَمُصْطَفَى أَمِينٌ: «التَّشْبِيهُ: بَيَانُ أَنَّ شَيْئاً أَوْ أَشْيَاءَ شَارَكَتْ غَيْرَهَا فِي صِفَةٍ أَوْ أَكْثَرَ، بِأَدَاةٍ هِيَ الكَافُ أَوْ نَحْوُهَا. وَأَرْكَانُ التَّشْبِيهِ أَرْبَعَةٌ: المُشَبَّهُ، وَالمُشَبَّهُ بِهِ (وَيُسَمَّيَانِ طَرَفَيِ التَّشْبِيهِ)، وَأَدَاةُ التَّشْبِيهِ، وَوَجْهُ الشَّبَهِ. مِثْلُ: «العِلْمُ كَالنُّورِ فِي الهِدَايَةِ». فَإِذَا حُذِفَتِ الأَدَاةُ وَوَجْهُ الشَّبَهِ سُمِّيَ: «تَشْبِيهاً بَلِيغاً»، مِثْلُ: «العِلْمُ نُورٌ»، وَهُوَ أَعْلَى مَرَاتِبِ التَّشْبِيهِ فِي البَلَاغَةِ؛ لِأَنَّهُ يَدَّعِي أَنَّ المُشَبَّهَ عَيْنُ المُشَبَّهِ بِهِ».', 'علی الجارم اور مصطفیٰ امین رحمہما اللہ فرماتے ہیں: ''تشبیہ سے مراد یہ واضح کرنا ہے کہ کوئی چیز کسی دوسری چیز کے ساتھ کسی ایک یا زیادہ خوبیوں میں شریک ہے، تشبیہ کے کسی حرف (جیسے کاف یا مثل) کے ذریعے سے۔ اور تشبیہ کے چار بنیادی ارکان ہیں: مشبہ (جس کو تشبیہ دی جائے)، مشبہ بہ (جس کے ساتھ تشبیہ دی جائے، اور ان دونوں کو طرفینِ تشبیہ کہا جاتا ہے)، اداتِ تشبیہ (تشبیہ کا حرف)، اور وجہِ شبہ (مشترک صفت)؛ جیسے: ''علم نور کی طرح ہے رہنمائی کرنے میں''۔ پس اگر جملے سے تشبیہ کا حرف اور وجہِ شبہ دونوں کو حذف کر دیا جائے تو اسے ''تشبیہِ بلیغ'' کہا جاتا ہے، جیسے: ''العلم نور'' (علم ہی نور ہے)، اور یہ بلاغت میں تشبیہ کا سب سے بلند ترین درجہ ہے؛ کیونکہ اس میں گویا یہ دعویٰ کیا جاتا ہے کہ مشبہ اور مشبہ بہ دو الگ چیزیں نہیں بلکہ ایک ہی حقیقت بن چکے ہیں!''', 'البلاغة الواضحة علمِ بلاغت (معانی، بیان، بدیع) کی دنیا کی سب سے مقبول ترین نصابی کتاب ہے جس نے بلاغت کو عربی ادب کے حسین ترین اشعار اور قرآنی مثالوں سے مزین کیا ہے۔', '[{"word":"نُورٌ","role":"خبر المبتدأ العلم مرفوع","sign":"ضمة","detail":"تشبيه بليغ مبني على المبتدأ والخبر"},{"word":"تَشْبِيهاً","role":"مفعول به ثان لسمي منصوب","sign":"فتحة","detail":"نائب الفاعل ضمير مستتر"}]', '["البلاغة الواضحة، علم البيان: التشبيه وأقسامه، ص 15-28."]', '{"en":"Al-Balaghah al-Wadihah (Science of Bayan): The four pillars of Simile (Tashbih)—Subject, Analogy, Particle, and Aspect of Resemblance. When both the particle and aspect are omitted, it ascends to Tashbih Baligh (e.g. ''Knowledge is light''), the most potent rhetorical metaphor.","ar":"أسرار التشبيه البليغ في البلاغة العربية وتطبيقاته في القرآن والشعر."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('balaghah_wadihah_ch2_istiarah', 'kharji_balaghah_wadihah', 1, 'الِاسْتِعَارَةُ المَكْنِيَّةُ وَالتَّصْرِيحِيَّةُ: سِرُّ الجَمَالِ البَلَاغِيِّ', 'باب 2: استعارہ مصرحہ اور استعارہ مکنیہ — عربی فصاحت کا سحر انگیز حسن');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('balaghah_wadihah_seg_2_1', 'balaghah_wadihah_ch2_istiarah', 'kharji_balaghah_wadihah', 0, '«الِاسْتِعَارَةُ: هِيَ تَشْبِيهٌ حُذِفَ أَحَدُ طَرَفَيْهِ. وَهِيَ قِسْمَانِ رَئِيسَانِ: 1. الِاسْتِعَارَةُ التَّصْرِيحِيَّةُ: وَهِيَ مَا صُرِّحَ فِيهَا بِلَفْظِ المُشَبَّهِ بِهِ وَحُذِفَ المُشَبَّهُ، كَقَوْلِهِ تَعَالَى: {كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ إِلَى النُّورِ}؛ أَيْ: مِنَ الكُفْرِ إِلَى الإِيمَانِ، فَشَبَّهَ الكُفْرَ بِالظُّلُمَاتِ وَحَذَفَ الكُفْرَ وَصَرَّحَ بِالظُّلُمَاتِ. 2. الِاسْتِعَارَةُ المَكْنِيَّةُ: وَهِيَ مَا حُذِفَ فِيهَا المُشَبَّهُ بِهِ وَرُمِزَ لَهُ بِشَيْءٍ مِنْ لَوَازِمِهِ، كَقَوْلِ الحَجَّاجِ: «إِنِّي لَأَرَى رُءُوساً قَدْ أَيْنَعَتْ وَحَانَ قِطَافُهَا»؛ شَبَّهَ الرُّؤُوسَ بِالثِّمَارِ، وَحَذَفَ الثِّمَارَ وَرَمَزَ لَهَا بِـ (أَيْنَعَتْ وَقِطَافُهَا)».', 'مصنفین فرماتے ہیں: ''استعارہ دراصل ایسی تشبیہ کو کہتے ہیں جس کے طرفین (مشبہ یا مشبہ بہ) میں سے کسی ایک کو بالکل حذف کر دیا گیا ہو۔ اور اس کی دو بنیادی قسمیں ہیں: 1. استعارہ مصرحہ: وہ استعارہ جس میں مشبہ کو چھپا کر صرف مشبہ بہ کو صراحتاً بول دیا جائے، جیسے قرآن کی یہ آیت: {یہ وہ کتاب ہے جو ہم نے آپ کی طرف نازل کی تاکہ آپ لوگوں کو تاریکیوں سے نکال کر نور کی طرف لائیں}؛ یعنی کفر کی گمراہی سے نکال کر ایمان کی طرف لائیں، پس کفر کو تاریکی اور ایمان کو نور سے تشبیہ دی گئی اور کفر و ایمان کو حذف کر کے صراحتاً تاریکی اور نور بولا گیا۔ 2. استعارہ مکنیہ: وہ استعارہ جس میں مشبہ بہ کو حذف کر دیا جائے اور اس کی کسی لازمی صفت یا علامت کو اس کی جگہ ذکر کر دیا جائے، جیسے حجاج بن یوسف کا مشہور جملہ: ''میں ایسے سر دیکھ رہا ہوں جو پک چکے ہیں اور ان کے توڑے جانے کا وقت آ گیا ہے''؛ اس نے سروں کو درخت کے پھلوں سے تشبیہ دی اور پھلوں کو چھپا کر ان کی صفت ''پکنا اور توڑا جانا'' ذکر کر دیا''۔', 'استعارہ زبان کو نئی زندگی بخشتا ہے۔ تشبیہ کے مقابلے میں استعارہ زیادہ طاقتور ہوتا ہے کیونکہ یہ دو الگ چیزوں کو ایک بنا کر سامع کے تخیل کو بیدار کرتا ہے۔', '[{"word":"الظُّلُمَاتِ","role":"مجرور بمن","sign":"كسرة","detail":"استعارة تصريحية عن الضلال"},{"word":"رُءُوساً","role":"مفعول به لأرى منصوب","sign":"فتحة","detail":"استعارة مكنية"}]', '["البلاغة الواضحة، مبحث الاستعارة، ص 58-72."]', '{"en":"Metaphor (Isti''arah) in Arabic Rhetoric: A simile with one of its two primary poles deleted. Isti''arah Tasrihiyyah explicitly states the borrowed attribute ({from darkness into light}, meaning disbelief to faith), while Makniyyah conceals it while retaining its telltale hallmark.","ar":"الفرق الدقيق بين الاستعارة التصريحية والمكنية وبلاغة الإيجاز في التعبير."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_maqamat_hariri', 'مَقَامَاتُ الحَرِيرِيِّ', 'أَبُو مُحَمَّدٍ القَاسِمُ بْنُ عَلِيٍّ الحَرِيرِيُّ (ت: 516ھ)', 'kharji_kitab', 'adab', 'فصاحت و بلاغت، مسجع عبارتیں و لغتِ عرب', 'کتبِ مطالعہ و ادبی کمال (درسِ نظامی درجہ خامسہ)', NULL, NULL, 'from-amber-950 via-stone-900 to-teal-950', NULL, 'عربی ادب کا وہ معجزانہ کلام جس میں سجع، جناس، نادر الفاظ اور عقل کو حیران کر دینے والے ادبی لطائف جمع کیے گئے ہیں۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('maqamat_hariri_ch1_sananiyyah', 'kharji_maqamat_hariri', 0, 'المَقَامَةُ الصَّنْعَانِيَّةُ: أُولَى المَقَامَاتِ وَبَرَاعَةُ أَبِي زَيْدٍ السَّرُوجِيِّ', 'باب 1: المقامۃ الصنعانیۃ — ابو زید سروجی کی شعلہ بیانی، صنائعِ لفظی اور ادبی چاشنی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('maqamat_hariri_seg_1_1', 'maqamat_hariri_ch1_sananiyyah', 'kharji_maqamat_hariri', 0, 'قَالَ أَبُو مُحَمَّدٍ القَاسِمُ بْنُ عَلِيٍّ الحَرِيرِيُّ: «رَوَى الحَارِثُ بْنُ هَمَّامٍ قَالَ: وَفَدْتُ صَنْعَاءَ اليَمَنِ وَأَنَا خَاوِي الوِفَاضِ، فَدَخَلْتُ جَامِعَهَا فَإِذَا بِشَيْخٍ ذِي طِمْرَيْنِ رَثَّيْنِ يَقِفُ خَطِيباً يَنْثُرُ الدُّرَرَ، فَقَالَ: «يَا أَهْلَ صَنْعَاءَ، يَا مَأْوَى الغُرَبَاءِ، اعْلَمُوا أَنَّ الدُّنْيَا دَارُ مَمَرٍّ لَا دَارُ مَقَرٍّ، شَهْدُهَا مَمْزُوجٌ بِالسَّمِّ، وَصَفْوُهَا مَشُوبٌ بِالهَمِّ! كَمْ غَرَّتْ مِنْ مَغْرُورٍ، وَكَمْ كَدَّرَتْ مِنْ سُرُورٍ! أَيْنَ المُلُوكُ الأَقْدَمُونَ، وَأَيْنَ الجَبَابِرَةُ الأَوَّلُونَ؟! صَارُوا رَمِيماً فِي التُّرَابِ، وَخَلَوْا بِمَا قَدَّمُوا لِلْحِسَابِ!». فَانْهَالَتْ عَلَيْهِ الدَّرَاهِمُ كَالمَطَرِ، ثُمَّ انْكَشَفَ لِي أَنَّهُ الشَّيْخُ أَبُو زَيْدٍ السَّرُوجِيُّ سَيِّدُ الحِيلَةِ وَالأَدَبِ!».', 'ابو محمد قاسم بن علی الحریری بصری رحمہ اللہ فرماتے ہیں: ''راوی حارث بن ہمام بیان کرتا ہے کہ میں یمن کے شہر صنعاء میں اس حال میں پہنچا کہ میری جیب خالی تھی، میں جامع مسجد میں داخل ہوا تو کیا دیکھتا ہوں کہ دو پرانے کپڑوں میں ملبوس ایک بزرگ خطیب کی طرح کھڑا موتی برسا رہا ہے، وہ پکار رہا تھا: ''اے صنعاء کے لوگو! اے مسافروں کی پناہ گاہو! خوب جان لو کہ یہ دنیا گزر گاہ ہے، مستقل رہنے کا ٹھکانہ نہیں؛ اس کا شہد زہر میں ملا ہوا ہے، اور اس کا سکون فکر و غم سے آلودہ ہے! اس نے کتنے ہی دھوکے بازوں کو فریب دیا، اور کتنی ہی خوشیوں کو خاک میں ملا دیا! کہاں گئے وہ پرانے بادشاہ اور کہاں گئے وہ پہلے جابر حکمران؟! سب مٹی میں ہڈیاں بن کر گل سڑ گئے اور اپنے اعمال کے حساب کے لیے تنہا رہ گئے!'' پس سامعین کے دل پگھل گئے اور اس پر درہموں کی بارش ہونے لگی، پھر بعد میں مجھ پر کھلا کہ یہ تو وہی چالاک بزرگ ابو زید سروجی ہے جو ادب اور حیلہ سازی کا بے تاج بادشاہ تھا!''', 'مقامات الحریری عربی زبان میں سجع، امثال، محاورات اور لغوی شاہکاروں کا سب سے بڑا ذخیرہ ہے۔ پچھلی آٹھ صدیوں سے عربی ادب کے طلبہ اپنی زبان میں روانی پیدا کرنے کے لیے مقاماتِ حریری کا مطالعہ کرتے ہیں۔', '[{"word":"خَاوِي","role":"خبر المبتدأ أنا مرفوع بضمة مقدرة","sign":"ضمة مقدرة","detail":"والجملة حالية"},{"word":"الدُّرَرَ","role":"مفعول به لينثر منصوب","sign":"فتحة","detail":"استعارة تصريحية عن فصيح الكلام"}]', '["مقامات الحريري، المقامة الأولى (الصنعانية)، ص 15-26، دار صادر."]', '{"en":"Al-Hariri''s legendary ''Maqamat'' (The San''a Assembly): The narrator Al-Harith ibn Hammam witnesses the beggar-intellectual Abu Zayd al-Saruji delivering an astonishing, rhymed sermon on the transience of worldly vanity, eliciting floods of coins.","ar":"قمة النثر الفني المسجع والبلاغة السردية في المقامة الصنعانية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('maqamat_hariri_ch2_fasahah', 'kharji_maqamat_hariri', 1, 'المَقَامَةُ المَرَاقِيَّةُ: الفَصَاحَةُ العَرَبِيَّةُ وَاللُّغَاتُ النَّادِرَةُ', 'باب 2: لغوی چمتکار — بغیر نقطوں والے کلمات اور الٹ پلٹ پڑھے جانے والے جملے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('maqamat_hariri_seg_2_1', 'maqamat_hariri_ch2_fasahah', 'kharji_maqamat_hariri', 0, '«أَبْدَعَ الحَرِيرِيُّ فِي مَقَامَاتِهِ فُنُوناً لُغَوِيَّةً لَا يَقْدِرُ عَلَيْهَا إِلَّا مَلِكُ البَلَاغَةِ؛ مِنْهَا خُطَبٌ كَامِلَةٌ خَالِيَةٌ مِنَ النِّقَاطِ (العَاطِلَةُ)، كَقَوْلِهِ: «الحَمْدُ لِلَّهِ المَلِكِ المَحْمُودِ، المَالِكِ الوَدُودِ، مُصَوِّرِ كُلِّ مَوْلُودٍ، وَمَآلِ كُلِّ مَطْرُودٍ!». وَمِنْهَا الكَلَامُ المَقْلُوبُ الَّذِي يُقْرَأُ طَرْداً وَعَكْساً بِلَا تَفَاوُتٍ، كَقَوْلِهِ: «سِرْ فَلَا كَبَا بِكَ الفَرَسُ»، وَقَوْلِهِ: «عَقْرَبٌ يَرْقَى بِقُرْبِ قَعْرٍ». فَكَانَتْ مَقَامَاتُهُ مِعْيَارَ الذَّوْقِ الأَدَبِيِّ فِي كُلِّ عَصْرٍ».', 'حریری رحمہ اللہ فرماتے ہیں: ''انہوں نے اپنے مقامات میں ایسے محیر العقول لغوی فنون دکھائے جن پر بلاغت کے سلطان کے سوا کسی کو دسترس نہیں ہوتی؛ جن میں ایسے مکمل خطبے ہیں جن میں ایک بھی نقطے والا حرف نہیں ہے (خطبۂ عاطلہ)، جیسے ان کا یہ کلام: ''سب تعریف اللہ کے لیے ہے جو لائقِ حمد بادشاہ ہے، محبت کرنے والا مالک ہے، ہر پیدا ہونے والے کا صورت گر ہے، اور ہر دھتکارے ہوئے کی پناہ گاہ ہے!'' (اس پورے جملے میں ایک نقطہ بھی نہیں ہے)۔ اور جن میں ایسا الٹ پلٹ کلام (مقلوب مستوی) ہے جسے شروع سے آخر تک پڑھیں یا آخر سے شروع کی طرف الٹا پڑھیں تو بالکل وہی الفاظ اور وہی معنی برقرار رہتا ہے، جیسے: ''سِرْ فَلَا كَبَا بِكَ الفَرَسُ'' (سفر کرو تاکہ گھوڑا تمہیں لے کر نہ گرے)۔ چنانچہ مقاماتِ حریری ہر دور میں عربی زبان کے ادبی ذوق کا سب سے بلند پیمانہ بنی رہی''۔', 'عربی زبان کے عجائبات اور وسعت کو حریری نے جس طرح اپنے قابو میں کیا وہ دنیا کی کسی اور زبان میں ممکن ہی نہیں ہے۔', '[{"word":"المَلِكِ","role":"نعت للفظ الجلالة مجرور","sign":"كسرة","detail":"المحمود نعت ثانٍ"},{"word":"مِعْيَارَ","role":"خبر كانت منصوب","sign":"فتحة","detail":"مقاماته اسمها ومعيار خبرها"}]', '["مقامات الحريري، ص 180-195."]', '{"en":"Al-Hariri''s linguistic acrobatics: Crafting entire sermons without a single dotted letter (Huroof Muhmalah) and palindromic masterpieces that read identically forward and backward (e.g. ''Sir fala kaba bik al-faras'').","ar":"براعة الحريري في المحسنات البديعية المعجزة وتطويع مفردات الضاد."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_diwan_hamasah', 'دِيوَانُ الحَمَاسَةِ', 'أَمِيرُ الشُّعَرَاءِ أَبُو تَمَّامٍ حَبِيبُ بْنُ أَوْسٍ الطَّائِيُّ (ت: 231ھ)', 'kharji_kitab', 'adab', 'جاہلی و اسلامی دور کے شجاعت، مروءت و حکمت کے اشعار', 'کتبِ مطالعہ و عربی شاعری (درسِ نظامی درجہ سادسہ)', NULL, NULL, 'from-stone-900 via-rose-950 to-emerald-950', NULL, 'عربوں کی بہادری، سخاوت، غیرت اور حکمت پر مشتمل منتخب ترین اشعار کا وہ شاہکار جس کے بارے میں کہا گیا کہ ابو تمام کا انتخاب اس کی اپنی شاعری سے بڑا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('diwan_hamasah_ch1_shajaah', 'kharji_diwan_hamasah', 0, 'بَابُ الحَمَاسَةِ: شَجَاعَةُ الفُرْسَانِ وَالصَّبْرُ عِنْدَ اللِّقَاءِ وَعِزَّةُ النَّفْسِ', 'باب 1: باب الحماسہ — میدانِ جنگ کی شجاعت، موت کی آنکھوں میں آنکھیں ڈالنا اور عزتِ نفس');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('diwan_hamasah_seg_1_1', 'diwan_hamasah_ch1_shajaah', 'kharji_diwan_hamasah', 0, 'قَالَ أَمِيرُ الشُّعَرَاءِ أَبُو تَمَّامٍ حَبِيبُ بْنُ أَوْسٍ الطَّائِيُّ فِي مُخْتَارَاتِهِ: «قَالَ قَطَرِيُّ بْنُ الفُجَاءَةِ يُشَجِّعُ نَفْسَهُ فِي مَعْمَعَةِ القِتَالِ: / أَقُولُ لَهَا وَقَدْ جَشَأَتْ وَجَاشَتْ ... رُوَيْدَكِ تَحْمَدِي أَوْ تَسْتَرِيحِي / فَمَا نَيْلُ الخُلُودِ بِمُسْتَطَاعٍ ... وَلَا ثَوْبُ البَقَاءِ بِمُسْتَعَارِ / فَصَبْراً فِي مَجَالِ المَوْتِ صَبْراً ... فَمَا نَيْلُ الخُلُودِ بِمُسْتَطَاعِ / سَبِيلُ المَوْتِ غَايَةُ كُلِّ حَيٍّ ... وَدَاعِيهِ لِأَهْلِ الأَرْضِ دَاعِي / وَمَنْ لَا يُغْتَبَطْ يَسْأَمْ وَيَهْرَمْ ... وَتُسْلِمْهُ المَنُونُ إِلَى انْقِطَاعِ».', 'امیر الشعراء ابو تمام حبیب بن اوس الطائی رحمہ اللہ اپنے دیوانِ حماسہ کے آغاز میں قطری بن الفجاءۃ کے وہ لازوال اشعار نقل فرماتے ہیں جن میں وہ میدانِ جنگ میں تلواروں کے سائے تلے اپنے نفس کو غیرت دلاتے ہوئے کہتا ہے: ''میں اپنے نفس سے کہتا ہوں جبکہ وہ جنگ کے ہولناک منظر سے کانپنے اور اضطراب میں مبتلا ہونے لگتا ہے: ذرا ٹھہر جا! ہمت کر! یا تو بہادری سے لڑ کر فتح یاب ہو کر تعریف پائے گا یا پھر جامِ شہادت پی کر اس دنیاوی قید سے ہمیشہ کے لیے آرام پا جائے گا! دنیا میں ہمیشہ زندہ رہنا کسی کے بس کی بات نہیں ہے، اور بقا اور ہمیشگی کا لباس کسی سے عاریتاً مانگا نہیں جا سکتا! پس موت کے گھاٹ اور میدانِ جنگ میں جمے رہو اور صبر کا دامن تھامے رکھو! کیونکہ موت کی راہ ہر زندہ جاوید کا آخری انجام ہے، اور موت کا پکارنے والا ہر لمحہ زمین والوں کو پکار رہا ہے! اور جو شخص میدانِ کارزار میں شہادت کا قابلِ رشک اعزاز حاصل نہ کر سکا وہ بالآخر بڑھاپے کی ذلت اور بیماریوں سے اکتا جائے گا اور موت اسے تنہائی اور مایوسی کے عالم میں بے بس کر دے گی!''', 'دیوان الحماسة عربی شاعری کا سب سے عظیم انتخاب مانا جاتا ہے جسے ابو تمام نے ہمدان کی ایک برفانی سردی میں ایک کتب خانے میں بیٹھ کر مرتب کیا۔ اس کا پہلا باب ''باب الحماسہ'' جوانمردی کا شاہکار ہے۔', '[{"word":"رُوَيْدَكِ","role":"اسم فعل أمر مبني على الفتح","sign":"مبني","detail":"والكاف للخطاب بمعنى تمهلي"},{"word":"صَبْراً","role":"مفعول مطلق لفعل محذوف تقديره اصبري","sign":"فتحة","detail":"يفيد الأمر والحث"}]', '["شرح ديوان الحماسة للتبريزي، 1/ 10-25، دار القلم."]', '{"en":"Abu Tammam''s supreme poetic anthology ''Diwan al-Hamasah'': Qatari ibn al-Fuja''ah stiffening his resolve amid the clashing swords: ''I tell my soul as it quivers in dread: steady yourself! Either you win praised glory or attain eternal rest; immortality is unattainable and eternity is not a borrowed robe, so stand resolute in the arena of death!''","ar":"قمة شعر البطولة والفروسية العربية وشرف الموت في سبيل المبدأ."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('diwan_hamasah_ch2_marthiyyah', 'kharji_diwan_hamasah', 1, 'بَابُ المَرَاثِي: لَوْعَةُ الفَقْدِ وَأَصْدَقُ شِعْرِ الرِّثَاءِ عِنْدَ العَرَبِ', 'باب 2: باب المراثی — رثائیہ شاعری اور بچھڑنے والے پیاروں کے فراق کا دلدوز بیان');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('diwan_hamasah_seg_2_1', 'diwan_hamasah_ch2_marthiyyah', 'kharji_diwan_hamasah', 0, '«مِنْ أَبْلَغِ مَا اخْتَارَهُ أَبُو تَمَّامٍ فِي بَابِ المَرَاثِي قَوْلُ مُتَمِّمِ بْنِ نُوَيْرَةَ يَرْثِي أَخَاهُ مَالِكاً: / لَعَمْرِي وَمَا دَهْرِي بِتَأْبِينِ مَالِكٍ ... وَلَا جَزَعٍ مِمَّا أَصَابَ فَأَوْجَعَا / وَلَكِنَّنِي أَمْضِي وَأَعْلَمُ أَنَّنِي ... سَأَلْقَى الَّذِي لَاقَى أَخِي حَيْثُ جَمَّعَا / وَكُنَّا كَنَدْمَانَيْ جَذِيمَةَ حِقْبَةً ... مِنَ الدَّهْرِ حَتَّى قِيلَ لَنْ يَتَصَدَّعَا / فَلَمَّا تَفَرَّقْنَا كَأَنِّي وَمَالِكاً ... لِطُولِ اجْتِمَاعٍ لَمْ نَبِتْ لَيْلَةً مَعَا!».', 'ابو تمام فرماتے ہیں: ''مرثیے کے باب میں انہوں نے متمم بن نویرہ کے وہ اشعار چنے جو اس نے اپنے مقتول بھائی مالک بن نویرہ کی یاد میں کہے تھے: ''مجھے اپنی جان کی قسم! میرا کام صرف مالک پر نوحہ کرنا نہیں ہے اور نہ ہی میں اس دردناک صدمے پر بے صبری کا مظاہرہ کر رہا ہوں؛ بلکہ میں تو اپنی منزل کی طرف بڑھ رہا ہوں اور جانتا ہوں کہ جس موت سے میرا بھائی گزرا ہے ایک دن مجھے بھی اسی سے گزرنا ہے! اور میں اور میرا بھائی مدتوں تک شاہِ جذیمہ کے ان دو ساتھیوں کی طرح اکٹھے رہے جن کے بارے میں لوگ کہتے تھے کہ یہ کبھی جدا نہیں ہو سکتے؛ لیکن جب موت نے ہمیں ایک دوسرے سے جدا کیا تو یوں محسوس ہوا گویا میں اور مالک اتنے طویل ساتھ کے باوجود کبھی زندگی میں ایک رات بھی اکٹھے نہیں رہے تھے!''', 'حضرت عمر فاروق رضی اللہ عنہ متمم بن نویرہ سے فرمایا کرتے تھے کہ مجھے اپنے بھائی مالک کا مرثیہ سناؤ اور سن کر رو پڑتے تھے اور فرماتے تھے کہ اگر میں اچھا شاعر ہوتا تو اپنے بھائی زید بن خطاب کا ایسا ہی مرثیہ کہتا۔', '[{"word":"لَعَمْرِي","role":"اللام للابتداء وعمري مبتدأ مرفوع بضمة مقدرة","sign":"ضمة مقدرة","detail":"والخبر محذوف وجوباً تقديره قسمي"},{"word":"لَيْلَةً","role":"ظرف زمان منصوب","sign":"فتحة","detail":"متعلق بنبت"}]', '["ديوان الحماسة، باب المراثي، 2/ 120-135."]', '{"en":"Mutammim ibn Nuwayrah elegizing his slain brother Malik: ''We were inseparable companions for an age until folk said we would never part; yet when we were severed, it felt as though, despite that immense union, Malik and I had never spent a single night together.''","ar":"أصدق رثاء أخوي في ديوان العرب وتصوير وحشة الفراق."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_jawahir_balaghah_hashimi', 'جَوَاهِرُ البَلَاغَةِ فِي المَعَانِي وَالبَيَانِ وَالبَدِيعِ', 'السَّيِّدُ أَحْمَدُ الهَاشِمِيُّ (ت: 1362ھ)', 'kharji_kitab', 'balaghah', 'علمِ بلاغت کا مستند و تفصیلی مرجع', 'کتبِ مطالعہ و تخصص فی اللغۃ', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'معانی، بیان اور بدیع کے تمام اصول و ضوابط، شواہدِ شعریہ اور قرآنی نکات کو انتہائی شستہ اور منظم انداز میں بیان کرنے والا جامع مرجع۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jawahir_hashimi_ch1_fasahah', 'kharji_jawahir_balaghah_hashimi', 0, 'البَابُ الأَوَّلُ: الفَرْقُ بَيْنَ الفَصَاحَةِ وَالبَلَاغَةِ وَعُيُوبِ الكَلَامِ', 'باب 1: فصاحت اور بلاغت کے درمیان فرق اور کلام کے عیوب (تنافرِ حروف، تعقیدِ لفظی و معنوی)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jawahir_hashimi_seg_1_1', 'jawahir_hashimi_ch1_fasahah', 'kharji_jawahir_balaghah_hashimi', 0, 'قَالَ السَّيِّدُ أَحْمَدُ الهَاشِمِيُّ: «الفَصَاحَةُ فِي اللُّغَةِ: البَيَانُ وَالظُّهُورُ، وَفِي الِاصْطِلَاحِ: عِبَارَةٌ عَنِ الأَلْفَاظِ البَيِّنَةِ الخَفِيفَةِ عَلَى اللِّسَانِ، الخَالِيَةِ مِنْ عُيُوبٍ ثَلَاثَةٍ: تَنَافُرِ الحُرُوفِ (كَقَوْلِهِمْ: هُعْخُعٌ لِلنَّبْتِ)، وَغَرَابَةِ الِاسْتِعْمَالِ، وَمُخَالَفَةِ القِيَاسِ الصَّرْفِيِّ. أَمَّا البَلَاغَةُ: فَهِيَ مُطَابَقَةُ الكَلَامِ الفَصِيحِ لِمُقْتَضَى حَالِ السَّامِعِينَ مَعَ فَصَاحَتِهِ؛ فَكُلُّ كَلَامٍ بَلِيغٍ فَصِيحٌ، وَلَيْسَ كُلُّ فَصِيحٍ بَلِيغاً؛ إِذْ قَدْ يَكُونُ الكَلَامُ فِي غَايَةِ الفَصَاحَةِ لَكِنَّهُ لَا يُنَاسِبُ المَقَامَ كَأَنْ يُلْقَى خِطَابُ التَّهْنِئَةِ فِي مَجْلِسِ العَزَاءِ!».', 'سید احمد الہاشمی رحمہ اللہ فرماتے ہیں: ''فصاحت لغت میں واضح اور ظاہر ہونے کو کہتے ہیں، اور بلاغت کی اصطلاح میں اس سے مراد وہ صاف ستھرے اور زبان پر ہلکے پھلکے الفاظ ہیں جو تین بڑے عیوب سے بالکل پاک ہوں: حروف کا باہمی ٹکراؤ اور ثقالت (جیسے بدوؤں کا گھاس کے لیے ''ہعخع'' کا بھاری لفظ بولنا)، غریب اور اجنبی الفاظ کا لانا، اور صرفی قواعد کی خلاف ورزی کرنا۔ جبکہ بلاغت یہ ہے کہ وہ فصیح کلام سننے والوں کے فہم اور موقع و محل کے عین مطابق ہو؛ لہٰذا ہر بلیغ کلام لازماً فصیح ہوتا ہے، لیکن ہر فصیح کلام کا بلیغ ہونا ضروری نہیں؛ کیونکہ بسا اوقات ایک کلام فصاحت کے اعتبار سے تو کمال درجے کا ہوتا ہے لیکن وہ موقع کے مطابق نہیں ہوتا جیسے کوئی شخص تعزیت اور ماتم کی مجلس میں مبارکباد کی تقریر شروع کر دے!''', 'جواهر البلاغة في المعاني والبيان والبديع عربی ادب کے طلبہ کے لیے بلاغت کی سب سے منظم اور جامع کتاب مانی جاتی ہے جس میں سینکڑوں مثالوں سے تفہیم کرائی گئی ہے۔', '[{"word":"عِبَارَةٌ","role":"خبر المبتدأ الفصاحة مرفوع","sign":"ضمة","detail":"في الاصطلاح شبه جملة اعتراضية"},{"word":"فَصِيحٌ","role":"خبر المبتدأ كل كلام مرفوع","sign":"ضمة","detail":"بليغ نعت لكلام"}]', '["جواهر البلاغة في المعاني والبيان والبديع لأحمد الهاشمي، ص 10-22، المكتبة العصرية."]', '{"en":"Ahmad al-Hashimi''s definitive manual ''Jawahir al-Balaghah'': Differentiating Fasahah (phonetic elegance devoid of cacophony and archaic obscurity) from Balaghah (congruence of eloquent speech to the situational context). Every Baligh speech is Fasih, but not vice versa.","ar":"تحرير أركان الفصاحة وشروط مطابقة الكلام لمقتضى الحال."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('jawahir_hashimi_ch2_badi', 'kharji_jawahir_balaghah_hashimi', 1, 'البَابُ الثَّالِثُ: عِلْمُ البَدِيعِ — الجِنَاسُ وَالطِّبَاقُ وَالمُقَابَلَةُ وَالسَّجْعُ', 'باب 2: علمِ بدیع — لفظی اور معنوی خوبصورتیاں (جناس، طباق، مقابلہ اور سجع)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('jawahir_hashimi_seg_2_1', 'jawahir_hashimi_ch2_badi', 'kharji_jawahir_balaghah_hashimi', 0, '«عِلْمُ البَدِيعِ: هُوَ عِلْمٌ يُعْرَفُ بِهِ وُجُوهُ تَحْسِينِ الكَلَامِ بَعْدَ رِعَايَةِ مُطَابَقَتِهِ لِمُقْتَضَى الحَالِ. وَالمُحَسِّنَاتُ نَوْعَانِ: 1. مُحَسِّنَاتٌ مَعْنَوِيَّةٌ: وَأَهَمُّهَا «الطِّبَاقُ» وَهُوَ الجَمْعُ بَيْنَ الشَّيْءِ وَضِدِّهِ، كَقَوْلِهِ: {وَتَحْسَبُهُمْ أَيْقَاظاً وَهُمْ رُقُودٌ}، وَ«المُقَابَلَةُ» وَهِيَ أَنْ يُؤْتَى بِمَعْنَيَيْنِ أَوْ أَكْثَرَ ثُمَّ يُؤْتَى بِمَا يُقَابِلُ ذَلِكَ عَلَى التَّرْتِيبِ، كَقَوْلِهِ: {فَلْيَضْحَكُوا قَلِيلاً وَلْيَبْكُوا كَثِيراً}. 2. مُحَسِّنَاتٌ لَفْظِيَّةٌ: كَـ «الجِنَاسِ التَّامِّ» الَّذِي يَتَّفِقُ فِيهِ اللَّفْظَانِ فِي أَرْبَعَةِ أُمُورٍ: الحُرُوفِ، وَعَدَدِهَا، وَهَيْئَتِهَا، وَتَرْتِيبِهَا مَعَ اخْتِلَافِ المَعْنَى، كَقَوْلِهِ: {وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ}؛ فَالسَّاعَةُ الأُولَى: يَوْمُ القِيَامَةِ، وَالثَّانِيَةُ: الوَقْتُ مِنَ الزَّمَانِ».', 'سید احمد الہاشمی فرماتے ہیں: ''علمِ بدیع وہ علم ہے جس کے ذریعے کلام کی معنوی اور لفظی سجاوٹ اور خوبصورتی کے طریقے پہچانے جاتے ہیں۔ اور اس کے محاسن دو قسموں میں بٹے ہیں: 1. معنوی خوبصورتیاں: جن میں سب سے اہم ''طباق'' ہے یعنی کلام میں دو متضاد چیزوں کو اکٹھا کرنا، جیسے فرمانِ الٰہی: {اور تم ان اصحاب کہف کو جاگتا ہوا سمجھتے تھے حالانکہ وہ سو رہے تھے}؛ اور ''مقابلہ'' یعنی پہلے دو یا دو سے زائد باتیں لانا پھر ان کے بالمقابل اسی ترتیب سے متضاد باتیں لانا، جیسے: {پس انہیں چاہیے کہ وہ دنیا میں تھوڑا سا ہنس لیں اور آخرت میں بہت زیادہ روئیں}۔ 2. لفظی خوبصورتیاں: جیسے ''جناسِ تام'' جس میں دو لفظ تلفظ، حروف کی تعداد، حرکات اور ترتیب میں بالکل ایک جیسے ہوں مگر دونوں کا معنی الگ ہو، جیسے قرآنی آیت: {اور جس دن قیامت (الساعۃ) قائم ہوگی تو مجرم قسمیں کھائیں گے کہ وہ دنیا میں گھڑی بھر (ساعۃ) سے زیادہ نہیں ٹھہرے تھے}؛ پس پہلی الساعۃ سے مراد قیامت کا دن ہے اور دوسری ساعۃ سے مراد وقت کی مختصر گھڑی ہے''۔', 'قرآن کریم نے ان تمام صنائعِ بدائع کو بغیر کسی تکلف اور بناوٹ کے کلام کے اندر اتنی قدرتی شان سے سمویا ہے جو انسانی خطباء کے بس کی بات نہیں۔', '[{"word":"أَيْقَاظاً","role":"مفعول به ثان لتحسبهم منصوب","sign":"فتحة","detail":"والهاء مفعول أول"},{"word":"غَيْرَ","role":"نائب ظرف زمان منصوب","sign":"فتحة","detail":"ساعة مضاف إليه"}]', '["جواهر البلاغة، علم البديع، ص 280-305."]', '{"en":"The Science of Badi'' (Embellishment): Conceptual devices like Antithesis (Tibaqa) and Parallel Contrast (Muqabalah: {Let them laugh a little and weep much}), alongside verbal ornaments like Perfect Paronomasia (Jinas Tamm: {The Hour arrives... they lingered not but an hour}).","ar":"المحسنات اللفظية والمعنوية ودورها في تجميل الأسلوب دون تكلف."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_shudhur_dhahab', 'شُذُورُ الذَّهَبِ فِي مَعْرِفَةِ كَلَامِ العَرَبِ', 'الإِمَامُ جَمَالُ الدِّينِ ابْنُ هِشَامٍ الأَنْصَارِيُّ (ت: 761ھ)', 'kharji_kitab', 'nahw', 'قواعدِ اعراب اور کلامِ عرب کی نادر نحوی تراکیب', 'کتبِ مطالعہ و درجہ خامسہ / سادسہ', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'ابن ہشام انصاری کا وہ شاہکار نحوی متن اور شرح جس میں عربی جملے کی ہر باریکی اور اعراب کے شواہد کو سمیٹ لیا گیا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shudhur_ch1_kalimah', 'kharji_shudhur_dhahab', 0, 'بَابُ الكَلِمَةِ وَالكَلاَمِ وَالإِعْرَابِ وَالبِنَاءِ فِي لِسَانِ العَرَبِ', 'باب 1: کلمہ، کلام، معرب اور مبنی — عربی زبان کے نحوی قوانین');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shudhur_seg_1_1', 'shudhur_ch1_kalimah', 'kharji_shudhur_dhahab', 0, 'قَالَ الإِمَامُ جَمَالُ الدِّينِ ابْنُ هِشَامٍ الأَنْصَارِيُّ: «الكَلِمَةُ قَوْلٌ مُفْرَدٌ، وَهِيَ: اسْمٌ، وَفِعْلٌ، وَحَرْفٌ. فَالِاسْمُ يُعْرَفُ بِـ (أَلْ) وَالتَّنْوِينِ وَالجَرِّ، مِثْلُ: «رَجُلٌ، وَبِالرَّجُلِ». وَالفِعْلُ يُعْرَفُ بِـ (قَدْ) وَالسِّينِ وَتَاءِ التَّأْنِيثِ السَّاكِنَةِ، مِثْلُ: «قَامَتْ وَسَيَقُومُ». وَالحَرْفُ مَا لَا يَقْبَلُ شَيْئاً مِنْ عَلَامَاتِ الاسْمِ وَلَا الفِعْلِ، كَـ «هَلْ» وَ«بَلْ». ثُمَّ الكَلِمَاتُ مِنْهَا مُعْرَبٌ: وَهُوَ مَا يَتَغَيَّرُ آخِرُهُ بِتَغَيُّرِ العَوَامِلِ، وَمِنْهَا مَبْنِيٌّ: وَهُوَ مَا يَلْزَمُ حَالَةً وَاحِدَةً لِغَيْرِ عَامِلٍ، كَـ «هَؤُلَاءِ» وَ«أَيْنَ» وَ«كَمْ».', 'امام جمال الدین عبد اللہ بن ہشام انصاری نحوی رحمہ اللہ فرماتے ہیں: ''کلمہ وہ اکیلا مفرد لفظ ہے جو کسی معنی کے لیے بولا جائے، اور وہ تین اقسام پر مشتمل ہے: اسم، فعل، اور حرف۔ پس اسم کو ''ال'' (الف لام)، تنوین، اور کسرہ (زیر) کے ذریعے پہچانا جاتا ہے، جیسے: ''رجلٌ'' اور ''بالرجلِ''۔ اور فعل کو ''قد''، حرفِ استقبال ''سین'' اور تائے تانیث ساکنہ کے ذریعے پہچانا جاتا ہے، جیسے: ''قامتْ'' اور ''سیقومُ''۔ اور حرف وہ ہے جو اسم اور فعل کی کسی بھی علامت کو قبول نہ کرے، جیسے: ''ھل'' اور ''بل''۔ پھر کلمات کی دو قسمیں ہیں: معرب: وہ کلمہ جس کا آخری حرف مختلف عوامل کے بدلنے سے بدلتا رہے (رفع، نصب، جر)، اور مبنی: وہ کلمہ جو کسی بھی عامل کے آنے پر اپنی ایک ہی حالت پر جما رہے کبھی تبدیل نہ ہو، جیسے: ''ہؤلاءِ''، ''أینَ'' اور ''کمْ''۔', 'شذور الذهب في معرفة كلام العرب ابن ہشام کی وہ گہری اور مستند کتاب ہے جس نے نحو کے دقائق کو سلجھایا۔ ابن خلدون فرماتے تھے کہ مصر کے ابن ہشام سیبویہ سے بھی بڑے نحوی ہیں۔', '[{"word":"قَوْلٌ","role":"خبر المبتدأ الكلمة مرفوع","sign":"ضمة","detail":"مفرد نعت له"},{"word":"مُعْرَبٌ","role":"مبتدأ مؤخر مرفوع","sign":"ضمة","detail":"منها خبر مقدم"}]', '["شذور الذهب في معرفة كلام العرب لابن هشام، ص 15-28."]', '{"en":"Ibn Hisham al-Ansari''s ''Shudhur adh-Dhahab'' (Splinters of Gold): Defining the Word (Kalimah) and speech components, distinguishing Mu''rab (inflected according to governing agents) from Mabni (indeclinable rigid words).","ar":"التحرير النحوي الدقيق لأقسام الكلم وعلامات الإعراب والبناء."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('shudhur_ch2_marfuat', 'kharji_shudhur_dhahab', 1, 'بَابُ المَرْفُوعَاتِ: الفَاعِلُ وَنَائِبُهُ وَالمُبْتَدَأُ وَالخَبَرُ', 'باب 2: مرفوعات — فاعل، نائب الفاعل اور مبتدا و خبر کے تفصیلی قوانین');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('shudhur_seg_2_1', 'shudhur_ch2_marfuat', 'kharji_shudhur_dhahab', 0, '«المَرْفُوعَاتُ سَبْعَةٌ: الفَاعِلُ، وَنَائِبُ الفَاعِلِ (وَهُوَ المَفْعُولُ الَّذِي لَمْ يُسَمَّ فَاعِلُهُ إِذْ حُذِفَ فَاعِلُهُ لِعِلَّةٍ كَالخَوْفِ أَوْ التَّعْظِيمِ، مِثْلُ: «خُلِقَ الإِنْسَانُ ضَعِيفاً»)، وَالمُبْتَدَأُ، وَالخَبَرُ، وَاسْمُ (كَانَ) وَأَخَوَاتِهَا، وَخَبَرُ (إِنَّ) وَأَخَوَاتِهَا، وَالتَّابِعُ لِلْمَرْفُوعِ (وَهُوَ النَّعْتُ وَالعَطْفُ وَالتَّوْكِيدُ وَالبَدَلُ). وَلَا يَرْتَفِعُ المَفْعُولُ إِلَّا إِذَا أُنِيبَ عَنِ الفَاعِلِ بَعْدَ حَذْفِهِ وَتَغْيِيرِ صِيغَةِ الفِعْلِ بِضَمِّ أَوَّلِهِ وَكَسْرِ مَا قَبْلَ آخِرِهِ فِي المَاضِي».', 'ابن ہشام فرماتے ہیں: ''عربی زبان میں مرفوعات (پیش پڑھے جانے والے اسماء) کل سات ہیں: فاعل، نائب الفاعل (یعنی وہ مفعول جس کے فاعل کو خوف، تعظیم یا اختصار کی وجہ سے حذف کر دیا گیا ہو اور مفعول کو فاعل کا مقام دے دیا گیا ہو، جیسے: {انسان کمزور پیدا کیا گیا ہے})، مبتدا، خبر، کان اور اس کی بہنوں کا اسم، اِنَّ اور اس کی بہنوں کی خبر، اور مرفوع کا تابع (جو نعت، عطف، تاکید اور بدل پر مشتمل ہے)۔ اور مفعول اس وقت تک کبھی مرفوع نہیں ہوتا جب تک کہ فاعل کو حذف کر کے فعل کی بنا کو ماضی میں پہلے حرف کو پیش اور آخری سے پہلے کو زیر دے کر مجہول نہ بنا دیا جائے''۔', 'مرفوعات نحو کی ریڑھ کی ہڈی ہیں۔ ابن ہشام نے ان ساتوں کو ایک ہی جامع پیرائے میں سمیٹ کر نحوی الجھنوں کو دور کیا۔', '[{"word":"سَبْعَةٌ","role":"خبر المبتدأ المرفوعات مرفوع","sign":"ضمة","detail":"المرفوعات مبتدأ وسبعة خبر"},{"word":"الإِنْسَانُ","role":"نائب فاعل مرفوع","sign":"ضمة","detail":"ضعيفاً حال منصوبة"}]', '["شذور الذهب، ص 95-110."]', '{"en":"The Seven Nominatives (Marfu''at): Subject (Fa''il), Deputy Subject (Na''ib al-Fa''il e.g. {Man was created weak}), Inchoative (Mubtada''), Enuntiative (Khabar), Noun of Kana, Predicate of Inna, and Appositives (Tabi'').","ar":"حصر المرفوعات السبعة في النحو العربي وتأصيل أحكام نائب الفاعل."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_qatr_nada_ansari', 'قَطْرُ النَّدَى وَبَلُّ الصَّدَى', 'الإِمَامُ ابْنُ هِشَامٍ الأَنْصَارِيُّ النَّحْوِيُّ (ت: 761ھ)', 'kharji_kitab', 'nahw', 'نحو کی درمیانی اور مضبوط ترین کتاب مع شواہد', 'کتبِ مطالعہ و نصابِ نحو', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'قرآنی مثالوں، عربی امثال اور نحوی علل سے بھرپور وہ کتاب جس نے صدیوں تک طلبہ کو اعراب حل کرنے کا ماہر بنایا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qatr_nada_ch1_iytilaf', 'kharji_qatr_nada_ansari', 0, 'بَابُ الإِعْرَابِ التَّقْدِيرِيِّ وَالمَحَلِّيِّ فِي الأَسْمَاءِ وَالأَفْعَالِ', 'باب 1: اعرابِ تقدیری اور اعرابِ محلی — مقصور، منقوص اور متکلم کی یائے اضافت کا اعراب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qatr_nada_seg_1_1', 'qatr_nada_ch1_iytilaf', 'kharji_qatr_nada_ansari', 0, 'قَالَ الإِمَامُ ابْنُ هِشَامٍ الأَنْصَارِيُّ: «الإِعْرَابُ إِمَّا لَفْظِيٌّ يَظْهَرُ فِي النُّطْقِ كَـ «جَاءَ زَيْدٌ»، وَإِمَّا تَقْدِيرِيٌّ لَا يَظْهَرُ لِمَانِعٍ. وَالمَانِعُ ثَلَاثَةٌ: 1. التَّعَذُّرُ: فِي كُلِّ اسْمٍ آخِرُهُ أَلِفٌ لَازِمَةٌ (المَقْصُورُ)، مِثْلُ: «الفَتَى وَمُوسَى»؛ تُقَدَّرُ فِيهِ الحَرَكَاتُ الثَّلَاثُ؛ لِأَنَّ الأَلِفَ لَا تَقْبَلُ الحَرَكَةَ لِذَاتِهَا. 2. الثِّقَلُ: فِي كُلِّ اسْمٍ آخِرُهُ يَاءٌ لَازِمَةٌ مَكْسُورٌ مَا قَبْلَهَا (المَنْقُوصُ)، مِثْلُ: «القَاضِي وَالدَّاعِي»؛ تُقَدَّرُ فِيهِ الضَّمَّةُ وَالكَسْرَةُ لِلثِّقَلِ، وَتَظْهَرُ الفَتْحَةُ لِخِفَّتِهَا: «رَأَيْتُ القَاضِيَ». 3. اشْتِغَالُ المَحَلِّ بِحَرَكَةِ المُنَاسَبَةِ: مِثْلُ: «غُلَامِي وَكِتَابِي»؛ تُقَدَّرُ فِيهِ الحَرَكَاتُ لِأَنَّ يَاءَ المُتَكَلِّمِ تُوجِبُ كَسْرَ مَا قَبْلَهَا».', 'امام ابن ہشام انصاری رحمہ اللہ فرماتے ہیں: ''اعراب یا تو لفظی ہوتا ہے جو زبان سے ادا ہو سکے جیسے ''جاء زیدٌ''، اور یا اعراب تقدیری (پوشیدہ) ہوتا ہے جو کسی رکاوٹ کی وجہ سے ظاہر نہیں ہو سکتا۔ اور اعراب ظاہر نہ ہونے کی تین رکاوٹیں ہیں: 1. تعذر (ناممکن ہونا): ہر اس اسم میں جس کے آخر میں الفِ لازمہ ہو (اسے اسمِ مقصور کہتے ہیں)، جیسے: ''الفتیٰ'' اور ''موسیٰ''؛ اس پر تینوں اعراب (ضمہ، فتحہ، کسرہ) تقدیری ہوں گے کیونکہ الف اپنی ذات میں حرکت کو قبول کرنے کی صلاحیت ہی نہیں رکھتا۔ 2. ثقل (زبان پر بھاری ہونا): ہر اس اسم میں جس کے آخر میں یائے لازمہ ہو اور اس سے پہلے زیر ہو (اسے اسمِ منقوص کہتے ہیں)، جیسے: ''القاضی'' اور ''الداعی''؛ اس پر ضمہ اور کسرہ ثقالت کی وجہ سے تقدیری ہوں گے، جبکہ فتحہ ہلکا ہونے کی وجہ سے ظاہر ہو جائے گا جیسے ''رأيتُ القاضيَ''۔ 3. محل کا حرکتِ مناسبت کے ساتھ مشغول ہونا: جیسے ''غلامی'' اور ''کتابی''؛ اس پر تینوں اعراب تقدیری ہوں گے کیونکہ متکلم کی ''یاء'' اپنے سے پہلے حرف پر لازماً زیر (کسرہ) کا تقاضا کرتی ہے''۔', 'قطر الندى وبل الصدى ابن ہشام کا وہ شہرۂ آفاق متن ہے جس پر انہوں نے خود نہایت شاندار شرح لکھی۔ تعذر اور ثقل کا یہ فرق قرآنی آیات کے اعراب کو کھولنے کی کنجی ہے۔', '[{"word":"الفَتَى","role":"فاعل مرفوع بضمة مقدرة منع من ظهورها التعذر","sign":"ضمة مقدرة","detail":"اسم مقصور"},{"word":"القَاضِيَ","role":"مفعول به منصوب بفتحة ظاهرة لخفتها","sign":"فتحة ظاهرة","detail":"اسم منقوص"}]', '["قطر الندى وبل الصدى لابن هشام، ص 30-42."]', '{"en":"Ibn Hisham''s foundational primer ''Qatr an-Nada'' (Dew Drops): Distinguishing apparent inflection from implicit/virtual inflection (I''rab Taqidiri) caused by: 1. Impossibility (Ta''adhur in Ism Maqsur like Musa), 2. Heaviness (Thiql in Ism Manqus like Al-Qadi), 3. Vocalic harmony (Ishtighal al-Mahall before the first-person pronoun ''Ya'').","ar":"تحقيق أسباب الإعراب التقديري الثلاثة في الأسماء المعتلة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qatr_nada_ch2_nawasib', 'kharji_qatr_nada_ansari', 1, 'نَوَاصِبُ الفِعْلِ المُضَارِعِ وَجَوَازِمُهُ وَشُرُوطُ عَمَلِهَا', 'باب 2: فعل مضارع کو زبر اور جزم دینے والے حروف (أن، لن، إذن، كي / لم، لما، لام الأمر، لا الناهية)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qatr_nada_seg_2_1', 'qatr_nada_ch2_nawasib', 'kharji_qatr_nada_ansari', 0, '«يُرْفَعُ الفِعْلُ المُضَارِعُ إِذَا تَجَرَّدَ عَنِ النَّاصِبِ وَالجَازِمِ، مِثْلُ: «يَكْتُبُ زَيْدٌ». وَيُنْصَبُ بِأَرْبَعَةِ أَحْرُفٍ: «أَنْ» المَصْدَرِيَّةِ نَحْوُ: {وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ}، وَ«لَنْ» لِنَفْيِ المُسْتَقْبَلِ نَحْوُ: {لَنْ نَبْرَحَ عَلَيْهِ عَاكِفِينَ}، وَ«إِذَنْ» بِشُرُوطِهَا، وَ«كَيْ» المَصْدَرِيَّةِ. وَيُجْزَمُ بِإِحْدَى ثَمَانِيَ عَشْرَةَ جَازِماً: مِنْهَا مَا يَجْزِمُ فِعْلاً وَاحِداً؛ وَهِيَ «لَمْ» وَ«لَمَّا» وَلَامُ الأَمْرِ وَ«لَا» النَّاهِيَةُ، وَمِنْهَا مَا يَجْزِمُ فِعْلَيْنِ (أَدَوَاتُ الشَّرْطِ)؛ نَحْوُ «إِنْ» وَ«مَنْ» وَ«مَا»، مِثْلُ: {مَنْ يَعْمَلْ سُوءاً يُجْزَ بِهِ}».', 'ابن ہشام فرماتے ہیں: ''فعل مضارع اصل حالت میں مرفوع (پیش والا) ہوتا ہے جب تک کہ اس پر کوئی نصب یا جزم دینے والا عامل داخل نہ ہو، جیسے: ''یکتبُ زیدٌ''۔ اور فعل مضارع کو زبر (نصب) دینے والے چار حروف ہیں: ''أن'' مصدریہ، جیسے: {اور تمہارا روزہ رکھنا تمہارے لیے زیادہ بہتر ہے}، ''لن'' جو مستقبل میں نفی کی تاکید کرتا ہے، جیسے: {ہم ہرگز اس بچھڑے کی پوجا سے پیچھے نہیں ہٹیں گے}، ''إذن'' اپنی شرائط کے ساتھ، اور ''کی'' مصدریہ۔ اور فعل مضارع کو جزم دینے والے اٹھارہ حروف ہیں: جن میں سے چار ایک فعل کو جزم دیتے ہیں: ''لم''، ''لما''، لامِ امر، اور نہی کی ''لا''؛ اور بقیہ حروف و اسماء وہ ہیں جو دو فعلوں کو بیک وقت جزم دیتے ہیں جنہیں ادواتِ شرط کہا جاتا ہے، جیسے: ''إن''، ''من''، اور ''ما''؛ جیسا کہ فرمانِ الٰہی: {جو شخص بھی کوئی برائی کرے گا اسے اس کا بدلہ دیا جائے گا}''۔', 'فعل مضارع کے اعراب کی یہ تقسیم نحوی کلام کی تفہیم کے لیے بنیادی ہے جس سے شرط و جزا اور احکام کے مطالبات سمجھے جاتے ہیں۔', '[{"word":"تَصُومُوا","role":"فعل مضارع منصوب بأن وعلامة نصبه حذف النون","sign":"حذف النون","detail":"من الأفعال الخمسة"},{"word":"يُجْزَ","role":"فعل مضارع مبني للمجهول مجزوم بحذف حرف العلة","sign":"حذف حرف العلة","detail":"جواب الشرط لمن"}]', '["قطر الندى وبل الصدى، باب إعراب الفعل، ص 70-85."]', '{"en":"Subjunctive and Jussive Moods of the Imperfect Verb (Mudari''): Raised by default; subjunctive via four particles (An, Lan, Idhan, Kay); jussive via single-verb particles (Lam, Lamma, Lam of command, prohibitive La) or conditional pairs ({Whoever does evil will be recompensed for it}).","ar":"تحرير أدوات النصب والجزم وعمل أسماء الشرط في الفعل المضارع."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_mughni_labib_ansari', 'مُغْنِي اللَّبِيبِ عَنْ كُتُبِ الأَعَارِيبِ', 'الإِمَامُ ابْنُ هِشَامٍ الأَنْصَارِيُّ (ت: 761ھ)', 'kharji_kitab', 'nahw', 'اعراب القرآن کا سب سے بڑا نحوی انسائیکلوپیڈیا', 'کتبِ مطالعہ و تخصص فی اللغۃ والتفسیر', NULL, NULL, 'from-stone-900 via-amber-950 to-emerald-950', NULL, 'عربی کے تمام حروف اور ادوات کے معانی، جملوں کی ترکیب اور مفسرین کے نحوی اختلافات کو حل کرنے والا تاریخی شاہکار۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('mughni_ch1_huruf', 'kharji_mughni_labib_ansari', 0, 'البَابُ الأَوَّلُ: فِي تَفْسِيرِ المُفْرَدَاتِ وَذِكْرِ أَحْكَامِ الحُرُوفِ وَمَعَانِيهَا', 'باب 1: حروف کے معانی اور تفسیری احکام — حرفِ ''لو''، ''حتی''، اور ''إذ'' کی باریکیاں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('mughni_seg_1_1', 'mughni_ch1_huruf', 'kharji_mughni_labib_ansari', 0, 'قَالَ الإِمَامُ جَمَالُ الدِّينِ ابْنُ هِشَامٍ الأَنْصَارِيُّ: «هَذَا كِتَابٌ عَظِيمُ النَّفْعِ لَمْ يُنْسَجْ عَلَى مِنْوَالِهِ؛ أَوْرَدْتُ فِيهِ الحُرُوفَ عَلَى حُرُوفِ المُعْجَمِ. فَمِنْ ذَلِكَ حَرْفُ «لَوْ»: وَلَهُ خَمْسَةُ أَوْجُهٍ؛ أَشْهَرُهَا: أَنَّهُ حَرْفُ امْتِنَاعٍ لِامْتِنَاعٍ؛ أَيْ: يَدُلُّ عَلَى امْتِنَاعِ الجَوَابِ لِامْتِنَاعِ الشَّرْطِ، مِثْلُ: «لَوْ جِئْتَنِي لَأَكْرَمْتُكَ»، فَالإِكْرَامُ امْتَنَعَ لِامْتِنَاعِ المَجِيءِ. وَمِنْهَا: حَرْفُ «حَتَّى»: وَلَهَا ثَلَاثَةُ أَوْجُهٍ: تَكُونُ جَارَّةً بِمَعْنَى إِلَى كَقَوْلِهِ: {حَتَّى مَطْلَعِ الْفَجْرِ}، وَتَكُونُ عَاطِفَةً، وَتَكُونُ ابْتِدَائِيَّةً يَلِيهَا الجُمَلُ».', 'امام جمال الدین ابن ہشام انصاری رحمہ اللہ فرماتے ہیں: ''یہ کتاب ایسی بے مثال اور عظیم الشان نفع کی حامل ہے جس کے طرز پر پہلے کوئی کتاب نہیں لکھی گئی؛ میں نے اس میں حروف کے معانی کو لغت کی ابجدی ترتیب پر جمع کیا ہے۔ ان میں سے ایک حرف ''لو'' ہے: اس کے پانچ معانی آتے ہیں جن میں سب سے مشہور یہ ہے کہ یہ ''حرفِ امتناع لامتناع'' ہے؛ یعنی شرط کے نہ پائے جانے کی وجہ سے جزا کے رک جانے پر دلالت کرتا ہے، جیسے: ''اگر تم میرے پاس آتے تو میں تمہاری عزت کرتا''، پس یہاں عزت کرنا اس لیے نہیں ہوا کیونکہ آنا ہی نہیں پایا گیا۔ اور ان میں سے ایک حرف ''حتیٰ'' ہے: جس کے تین استعمالات ہیں: کبھی حرفِ جر بنتا ہے بمعنی ''إلی'' (تک)، جیسے: {فجر کے طلوع ہونے تک}، کبھی حرفِ عطف بنتا ہے، اور کبھی حرفِ ابتدائیہ ہوتا ہے جس کے بعد نیا جملہ شروع ہوتا ہے''۔', 'مغني اللبيب عن كتب الأعاريب نحو اور اعرابِ قرآن کی تاریخ کی سب سے بلند پایہ اور فلسفیانہ کتاب ہے۔ ابن ہشام نے حروف کے معانی کا ایسا تفصیلی احاطہ کیا ہے جس کے بغیر قرآن کی باریک تفسیر ممکن نہیں۔', '[{"word":"امْتِنَاعٍ","role":"مضاف إليه مجرور","sign":"كسرة","detail":"حرف مضاف وامتناع مضاف إليه"},{"word":"مَطْلَعِ","role":"اسم مجرور بحتى","sign":"كسرة","detail":"وهو مضاف والفجر مضاف إليه"}]', '["مغني اللبيب عن كتب الأعاريب لابن هشام، الباب الأول: في تفسير المفردات، 1/ 15-32."]', '{"en":"Ibn Hisham''s crowning masterpiece ''Mughni al-Labib'': Analyzing particles. The particle ''Law'' as an indicator of non-occurrence due to non-occurrence (Imtina'' li-mtina''). ''Hatta'' functioning across three dimensions: Preposition, Conjunction, and Resumptive Particle.","ar":"الموسوعة النحوية الكبرى في معاني الأدوات والحروف وتطبيقاتها القرآنية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('mughni_ch2_qawaid_irab', 'kharji_mughni_labib_ansari', 1, 'البَابُ الرَّابِعُ: فِي ذِكْرِ أَحْكَامٍ كُلِّيَّةٍ يَتَخَرَّجُ عَلَيْهَا الإِعْرَابُ وَدَفْعُ الأَغَالِيطِ', 'باب 2: اعراب کے کلی اصول اور معربین کی غلطیوں سے بچاؤ کے قواعد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('mughni_seg_2_1', 'mughni_ch2_qawaid_irab', 'kharji_mughni_labib_ansari', 0, '«قَالَ ابْنُ هِشَامٍ: مِنْ أَهَمِّ قَوَاعِدِ الإِعْرَابِ: أَنَّ الجُمَلَ بَعْدَ النَّكِرَاتِ صِفَاتٌ، وَبَعْدَ المَعَارِفِ أَحْوَالٌ، مِثْلُ: «رَأَيْتُ رَجُلاً يَضْحَكُ» فـ (يَضْحَكُ) نَعْتٌ لِرَجُلٍ، أَمَّا «رَأَيْتُ زَيْداً يَضْحَكُ» فـ (يَضْحَكُ) حَالٌ مِنْ زَيْدٍ. وَقَاعِدَةٌ أُخْرَى: الإِعْرَابُ فَرْعُ المَعْنَى؛ فَلَا يَجُوزُ لِلْمُعْرِبِ أَنْ يَتَكَلَّفَ إِعْرَاباً يُخَالِفُ المَعْنَى المَقْصُودَ، وَإِنْ صَحَّ فِي صِنَاعَةِ النَّحْوِ؛ فَإِنَّ صِيَانَةَ المَعْنَى الشَّرْعِيِّ مُقَدَّمَةٌ عَلَى مُجَرَّدِ القَوَاعِدِ اللَّفْظِيَّةِ».', 'ابن ہشام فرماتے ہیں: ''اعراب کے سب سے اہم اور بنیادی قواعد میں سے ایک سنہری قاعدہ یہ ہے: نکرہ اسماء کے بعد آنے والے جملے ہمیشہ صفت (نعت) بنتے ہیں، اور معرفہ اسماء کے بعد آنے والے جملے ہمیشہ حال بنتے ہیں؛ جیسے: ''رأيتُ رجلاً يضحك'' (میں نے ایک نکرہ آدمی کو دیکھا جو ہنس رہا تھا)، یہاں ''یضحک'' کا جملہ رجل کی صفت ہے، لیکن جب کہا جائے ''رأيتُ زيداً يضحك'' (میں نے زید کو اس حال میں دیکھا کہ وہ ہنس رہا تھا)، تو یہاں ''یضحک'' کا جملہ زید کا حال بنے گا کیونکہ زید معرفہ ہے۔ اور دوسرا عظیم اصول یہ ہے: اعراب معنی کا تابع اور اس کی شاخ ہوتا ہے؛ لہٰذا کسی اعراب کرنے والے کے لیے جائز نہیں کہ وہ ایسا بناوٹی اعراب تراشے جو مقصود معنی کے خلاف ہو اگرچہ نحو کے ظاہری قواعد کے مطابق وہ ممکن ہی کیوں نہ ہو؛ کیونکہ شرعی معنی کی حفاظت محض لفظی قواعد کی پابندی پر ہمیشہ مقدم ہوتی ہے''۔', 'ابن ہشام کا یہ اصول ''الإعراب فرع المعنى'' علمِ تفسیر اور اصولِ فقہ کا سب سے بڑا قانون مانا جاتا ہے جس نے نحو کو بے روح موشگافیوں سے بچا کر کلام کی مراد کے تابع کیا۔', '[{"word":"صِفَاتٌ","role":"خبر المبتدأ الجمل مرفوع","sign":"ضمة","detail":"بعد النكرات شبه جملة ظرفية"},{"word":"فَرْعُ","role":"خبر المبتدأ الإعراب مرفوع","sign":"ضمة","detail":"المعنى مضاف إليه"}]', '["مغني اللبيب، الباب الرابع: في ذكر أحكام يكثر دورها، 2/ 420-435."]', '{"en":"Golden Axioms of Syntax: 1. Sentences following indefinite nouns are Adjectives (Sifat), whereas sentences following definite nouns are Circumstantial States (Ahwal). 2. ''Inflection is a branch of meaning'' (Al-I''rab far'' al-Ma''na)—the intended meaning governs the grammatical parsing, never vice versa.","ar":"القواعد النحوية الكبرى وضابط تبعية الإعراب للمعنى التفسيري."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_qiraah_rashidah_nadwi', 'القِرَاءَةُ الرَّاشِدَةُ لِتَعْلِيمِ اللُّغَةِ العَرَبِيَّةِ', 'المُفَكِّرُ الإِسْلَامِيُّ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ (ت: 1420ھ)', 'kharji_kitab', 'adab', 'عربی ادب، تربیتی قصص اور بچوں و طلبہ کی زبان دانی', 'کتبِ مطالعہ و ابتدائی عربی انشاء', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'عربی زبان کو بچوں اور طلبہ کے دلوں میں پیوست کرنے والی اخلاقی، دینی اور فطری کہانیوں پر مشتمل تاریخی ادبی سلسلہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qiraah_rashidah_ch1_sidq', 'kharji_qiraah_rashidah_nadwi', 0, 'بَابُ الصِّدْقِ وَالأَمَانَةِ فِي مُعَامَلَةِ النَّاسِ', 'باب 1: سچائی، امانت داری اور حسنِ اخلاق کی دلنشین کہانیاں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qiraah_rashidah_seg_1_1', 'qiraah_rashidah_ch1_sidq', 'kharji_qiraah_rashidah_nadwi', 0, 'قَالَ مُفَكِّرُ الإِسْلَامِ السَّيِّدُ أَبُو الحَسَنِ عَلِيُّ الحَسَنِيُّ النَّدْوِيُّ: «كَانَ فِي بَغْدَادَ تَاجِرٌ صَالِحٌ يَخَافُ اللَّهَ، بَعَثَ غُلَامَهُ إِلَى السُّوقِ لِيَبِيعَ ثَوْباً فِيهِ عَيْبٌ خَفِيٌّ، فَقَالَ لَهُ: يَا غُلَامُ، بَيِّنْ لِلْمُشْتَرِي هَذَا العَيْبَ وَلَا تَكْتُمْهُ! فَذَهَبَ الغُلَامُ وَبَاعَ الثَّوْبَ بِثَمَنٍ كَبِيرٍ وَنَسِيَ أَنْ يُبَيِّنَ العَيْبَ؛ فَلَمَّا رَجَعَ إِلَى سَيِّدِهِ وَأَخْبَرَهُ، فَزِعَ التَّاجِرُ وَقَالَ: «وَيْحَكَ! كَيْفَ آكُلُ مَالاً حَرَاماً بِالغِشِّ وَالخِيَانَةِ؟!». فَتَرَكَ مَتْجَرَهُ وَخَرَجَ فِي أَثَرِ المُشْتَرِي يَجُوبُ شَوَارِعَ بَغْدَادَ أَيَّاماً، حَتَّى وَجَدَهُ فَرَدَّ عَلَيْهِ مَالَهُ وَأَخَذَ ثَوْبَهُ! فَعَجِبَ المُشْتَرِي مِنْ أَمَانَتِهِ وَأَسْلَمَ عَلَى يَدَيْهِ».', 'علامہ ابو الحسن علی حسنی ندوی رحمہ اللہ فرماتے ہیں: ''بغداد میں ایک نیک پرہیزگار تاجر رہتا تھا جو اللہ سے بہت ڈرتا تھا، اس نے اپنے ملازم کو بازار میں ایک ایسا کپڑا بیچنے کے لیے بھیجا جس میں ایک چھپا ہوا عیب تھا، اور تاکید کرتے ہوئے کہا: اے لڑکے! گاہک کو یہ عیب اچھی طرح کھول کر دکھا دینا اور ہرگز نہ چھپانا! ملازم بازار گیا اور اس نے وہ کپڑا اچھے خاصے داموں بیچ دیا لیکن عیب بتانا بھول گیا؛ پس جب وہ واپس آیا اور اپنے مالک کو بتایا تو وہ نیک تاجر کانپ اٹھا اور بولا: ''افسوس تجھ پر! میں دھوکے بازی اور خیانت کے ذریعے حرام مال کیسے کھا سکتا ہوں؟!'' چنانچہ وہ اپنی دکان چھوڑ کر اس خریدار کی تلاش میں نکل کھڑا ہوا اور کئی دن تک بغداد کی گلیوں کی خاک چھانتا رہا، یہاں تک کہ اس خریدار کو تلاش کر لیا، اس کی رقم اسے واپس لوٹا دی اور اپنا عیب دار کپڑا واپس لے لیا! وہ خریدار اس کی ایسی حیرت انگیز امانت داری دیکھ کر دنگ رہ گیا اور اسی وقت اس کے ہاتھ پر اسلام قبول کر لیا''۔', 'القراءة الراشدة علامہ ندوی کی وہ کتاب ہے جو عربی ادب کی چاشنی کے ساتھ ساتھ اخلاقی اور ایمانی تربیت کا شاہکار ہے۔ اسلام باتوں سے نہیں کردار سے پھیلا ہے۔', '[{"word":"تَاجِرٌ","role":"اسم كان مؤخر مرفوع","sign":"ضمة","detail":"في بغداد شبه جملة خبر مقدم"},{"word":"خِيَانَةِ","role":"معطوف على الغش مجرور","sign":"كسرة","detail":"بيان الحرمة"}]', '["القراءة الراشدة لأبي الحسن الندوي، الجزء الأول، ص 15-25."]', '{"en":"Allama Nadwi''s ''Al-Qira''ah ar-Rashidah'': The merchant of Baghdad who traversed the city for days to locate a customer who unwittingly bought defective cloth, refunding him in full, inspiring the amazed buyer to embrace Islam through practical integrity.","ar":"التربية على الأمانة والصدق في التجارة والتنفير من الغش."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('qiraah_rashidah_ch2_watan', 'kharji_qiraah_rashidah_nadwi', 1, 'حُبُّ العَمَلِ وَالكَدِّ وَنَبْذُ الكَسَلِ وَالبَطَالَةِ', 'باب 2: محنت کی عظمت — اپنے ہاتھ سے روزی کمانا اور بے روزگاری و سستی سے نفرت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('qiraah_rashidah_seg_2_1', 'qiraah_rashidah_ch2_watan', 'kharji_qiraah_rashidah_nadwi', 0, '«خَرَجَ أَمِيرُ المُؤْمِنِينَ عُمَرُ بْنُ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ إِلَى المَسْجِدِ، فَرَأَى قَوْماً جَالِسِينَ لَا عَمَلَ لَهُمْ يَسْأَلُونَ النَّاسَ، فَقَالَ: «مَنْ أَنْتُمْ؟» قَالُوا: «نَحْنُ المُتَوَكِّلُونَ عَلَى اللَّهِ!». فَعَلَاهُمْ عُمَرُ بِدِرَّتِهِ وَقَالَ غَاضِباً: «بَلْ أَنْتُمُ المُتَآكِلُونَ! لَا يَقْعُدَنَّ أَحَدُكُمْ عَنْ طَلَبِ الرِّزْقِ وَيَقُولُ: اللَّهُمَّ ارْزُقْنِي، وَقَدْ عَلِمَ أَنَّ السَّمَاءَ لَا تُمْطِرُ ذَهَباً وَلَا فِضَّةً، وَإِنَّ اللَّهَ يَرْزُقُ النَّاسَ بَعْضَهُمْ مِنْ بَعْضٍ!». وَقَالَ رَسُولُ اللَّهِ ﷺ: «مَا أَكَلَ أَحَدٌ طَعَاماً قَطُّ خَيْراً مِنْ أَنْ يَأْكُلَ مِنْ عَمَلِ يَدِهِ، وَإِنَّ نَبِيَّ اللَّهِ دَاوُدَ كَانَ يَأْكُلُ مِنْ عَمَلِ يَدِهِ».', 'علامہ ندوی فرماتے ہیں: ''امیر المؤمنین حضرت عمر فاروق رضی اللہ عنہ مسجد میں تشریف لائے تو دیکھا کہ کچھ ہٹے کٹے لوگ ہاتھ پر ہاتھ دھرے بیٹھے ہیں، کوئی کام کاج نہیں کرتے اور لوگوں کے آگے ہاتھ پھیلاتے ہیں، حضرت عمر نے پوچھا: ''تم کون لوگ ہو؟'' انہوں نے کہا: ''ہم اللہ پر توکل کرنے والے درویش ہیں!'' تو فاروقِ اعظم نے اپنا کوڑا اٹھایا اور غضبناک ہو کر فرمایا: ''جھوٹ بکتے ہو! تم متوکل نہیں بلکہ دوسروں کے ٹکڑوں پر پلنے والے مفت خورے ہو! خبردار! تم میں سے کوئی شخص حلال روزی کی تلاش چھوڑ کر مسجد کے کونے میں نہ بیٹھے اور یہ دعا نہ کرے کہ اے اللہ مجھے رزق دے، حالانکہ وہ خوب جانتا ہے کہ آسمان سے کبھی سونے چاندی کی بارش نہیں برستی، اور اللہ لوگوں کو ایک دوسرے کے ذریعے محنت کے بدلے رزق عطا فرماتا ہے!'' اور رسول اللہ ﷺ کا ارشاد ہے: ''کسی انسان نے اس کھانے سے بہتر کھانا کبھی نہیں کھایا جو اس نے اپنے ہاتھوں کی محنت سے کمایا ہو، اور اللہ کے برگزیدہ پیغمبر حضرت داؤد علیہ السلام بھی اپنے ہاتھوں کی محنت (زرہ سازی) سے کما کر کھاتے تھے''۔', 'اسلام محنت، پیشہ وری اور دستکاری کو عبادت کا درجہ دیتا ہے۔ مفت خوری کو توکل کا نام دینا شریعت پر بہتان ہے۔', '[{"word":"المُتَآكِلُونَ","role":"خبر المبتدأ أنتم مرفوع","sign":"واو","detail":"جمع مذكر سالم"},{"word":"ذَهَباً","role":"مفعول به لتمطر منصوب","sign":"فتحة","detail":"السماء اسمها المنفي"}]', '["القراءة الراشدة، الجزء الثاني، ص 45-56، وأخرجه البخاري (2072)."]', '{"en":"Umar bin Al-Khattab chastising idle beggars in the mosque who claimed to be ''relying on God'' (Mutawakkilun): ''Nay, you are parasitic idlers (Muta''akilun)! None of you should sit idle begging for sustenance, well aware that the sky rains neither gold nor silver.''","ar":"الحث على كسب اليد ونبذ التواكل والبطالة في المنظور الإسلامي."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_muallaqat_sab', 'شَرْحُ المُعَلَّقَاتِ السَّبْعِ', 'الإِمَامُ الحُسَيْنُ بْنُ أَحْمَدَ الزَّوْزَنِيُّ (ت: 486ھ)', 'kharji_kitab', 'adab', 'جاہلی عربی شاعری کے سات لازوال قصائد مع شرح', 'کتبِ مطالعہ و درسِ نظامی درجہ سادسہ / عالمیہ', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'امرؤ القیس، زہیر بن ابی سلمی، عنترہ اور لبید کے وہ قصائد جو خانۂ کعبہ کی دیواروں پر لٹکائے گئے تھے۔ عربی لغت کا اصل سرچشمہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('muallaqat_ch1_imru_qays', 'kharji_muallaqat_sab', 0, 'مُعَلَّقَةُ امْرِئِ القَيْسِ: قِفَا نَبْكِ مِنْ ذِكْرَى حَبِيبٍ وَمَنْزِلِ', 'باب 1: معلقۂ امرؤ القیس — عرب جاہلی شاعری کا شاہکار اور تشبیہات کی باریکیاں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('muallaqat_seg_1_1', 'muallaqat_ch1_imru_qays', 'kharji_muallaqat_sab', 0, 'قَالَ الإِمَامُ أَبُو عَبْدِ اللَّهِ الحُسَيْنُ بْنُ أَحْمَدَ الزَّوْزَنِيُّ فِي شَرْحِهِ: «هَذِهِ قَصِيدَةُ امْرِئِ القَيْسِ بْنِ حُجْرٍ الكِنْدِيِّ، أَمِيرِ شُعَرَاءِ الجَاهِلِيَّةِ، وَهِيَ أَوَّلُ المُعَلَّقَاتِ السَّبْعِ الَّتِي عُلِّقَتْ عَلَى أَسْتَارِ الكَعْبَةِ تَعْظِيماً لَهَا. مَطْلَعُهَا: / قِفَا نَبْكِ مِنْ ذِكْرَى حَبِيبٍ وَمَنْزِلِ ... بِسِقْطِ اللِّوَى بَيْنَ الدَّخُولِ فَحَوْمَلِ / فَتُوْضِحَ فَالِمقْرَاةِ لَمْ يَعْفُ رَسْمُهَا ... لِمَا نَسَجَتْهَا مِنْ جَنُوبٍ وَشَمْأَلِ / وَمِنْ بَلِيغِ تَشْبِيهَاتِهِ فِي وَصْفِ اللَّيْلِ قَوْلُهُ: / وَلَيْلٍ كَمَوْجِ البَحْرِ أَرْخَى سُدُولَهُ ... عَلَيَّ بِأَنْوَاعِ الهُمُومِ لِيَبْتَلِي / فَقُلْتُ لَهُ لَمَّا تَمَطَّى بِصُلْبِهِ ... وَأَرْدَفَ أَعْجَازاً وَنَاءَ بِكَلْكَلِ / أَلَا أَيُّهَا اللَّيْلُ الطَّوِيلُ أَلَا انْجَلِي ... بِصُبْحٍ وَمَا الإِصْبَاحُ مِنْكَ بِأَمْثَلِ».', 'امام ابو عبد اللہ حسین بن احمد الزوزنی رحمہ اللہ فرماتے ہیں: ''یہ قصیدہ جاہلیت کے سب سے بڑے شاعر امرؤ القیس بن حجر کندی کا ہے، اور یہ ان سات معلقات میں سے پہلا معلقہ ہے جنہیں ان کی بے مثال فصاحت کی بنا پر خانۂ کعبہ کی دیواروں پر لٹکایا گیا تھا۔ اس کا مطلع ہے: ''اے میرے دونوں ساتھیو! ذرا ٹھہرو، ہم اپنے بچھڑے ہوئے محبوب کی یاد اور اس کے ان اجڑے ہوئے گھروں پر آنسو بہا لیں جو وادیِ سقط اللوی میں واقع ہیں''۔ اور رات کی ہولناکی اور غم کی شدت کی تصویر کشی میں اس کا یہ شعر عربی ادب کا سب سے بڑا استعارہ مانا جاتا ہے: ''اور کتنی ہی ایسی تاریک راتیں ہیں جو سمندر کی موجوں کی طرح مجھ پر اپنے سیاہ پردے گرا دیتی ہیں، اور غم و اندوہ کی نت نئی قسمیں لے کر آتی ہیں تاکہ میرا امتحان لیں! تو میں نے اس رات سے کہا جب اس نے اپنے بوجھل سینے کو تان لیا اور اپنی بھاری کمر کو مجھ پر لاد دیا: اے لمبی سیاہ رات! ذرا ہٹ جا اور صبح کی روشنی میں بدل جا، اگرچہ تیری صبح کا اجالا بھی میرے غموں کو کم کرنے میں تجھ سے کچھ بہتر نہیں ہے!''', 'المعلقات السبع جاہلی عربی شاعری کی معراج ہیں جنہیں سمجھے بغیر عربی لغت، نحو اور قرآن کے نزول کے وقت کی زبان کی بلندی کو نہیں سمجھا جا سکتا۔ الزوزنی کی شرح سب سے معتمد شرح ہے۔', '[{"word":"قِفَا","role":"فعل أمر مبني على حذف النون لاتصاله بألف الاثنين","sign":"مبني","detail":"والألف فاعل"},{"word":"نَبْكِ","role":"فعل مضارع مجزوم في جواب الطلب","sign":"حذف حرف العلة","detail":"وعلامة جزمه حذف الياء"}]', '["شرح المعلقات السبع للزوزني، ص 10-25، دار المعرفة."]', '{"en":"Az-Zawzani''s commentary on the Mu''allaqat: The immortal Ode of Imru'' al-Qays hung upon the Ka''bah. His dramatic personification of the nocturnal tempest: ''A night like the sea surge let down its drapes over me laden with divers sorrows to test me... O long night, dispel by dawn, yet dawn brings no better reprieve!''","ar":"تحليل معلقة امرئ القيس وبراعة التشبيه في وصف الليل والخيل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('muallaqat_ch2_zuhair', 'kharji_muallaqat_sab', 1, 'مُعَلَّقَةُ زُهَيْرِ بْنِ أَبِي سُلْمَى: حِكْمَةُ الجَاهِلِيَّةِ وَذَمُّ الحَرْبِ', 'باب 2: معلقۂ زہیر بن ابی سلمیٰ — جاہلیت کی دانائی، جنگ کی مذمت اور امن و صلح کی دعوت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('muallaqat_seg_2_1', 'muallaqat_ch2_zuhair', 'kharji_muallaqat_sab', 0, '«كَانَ زُهَيْرُ بْنُ أَبِي سُلْمَى شَاعِرَ الحِكْمَةِ وَالسَّلَامِ؛ مَدَحَ هَرِمَ بْنَ سِنَانٍ وَالحَارِثَ بْنَ عَوْفٍ لِتَحَمُّلِهِمَا دِيَاتِ القَتْلَى لِإِطْفَاءِ حَرْبِ دَاحِسٍ وَالغَبْرَاءِ، وَقَالَ يُحَذِّرُ مِنَ الحَرْبِ: / وَمَا الحَرْبُ إِلَّا مَا عَلِمْتُمْ وَذُقْتُمُ ... وَمَا هُوَ عَنْهَا بِالحَدِيثِ المُرَجَّمِ / مَتَى تَبْعَثُوهَا تَبْعَثُوهَا ذَمِيمَةً ... وَتَضْرَ إِذَا ضَرَّيْتُمُوهَا فَتَضْرَمِ / وَمِنْ حِكَمِهِ الخَالِدَةِ فِي آخِرِهَا: / وَمَنْ يَكُ ذَا فَضْلٍ فَيَبْخَلْ بِفَضْلِهِ ... عَلَى قَوْمِهِ يُسْتَغْنَ عَنْهُ وَيُذْمَمِ / وَمَنْ يَجْعَلِ المَعْرُوفَ مِنْ دُونِ عِرْضِهِ ... يَفِرْهُ وَمَنْ لَا يَتَّقِ الشَّتْمَ يُشْتَمِ / سَئِمْتُ تَكَالِيفَ الحَيَاةِ وَمَنْ يَعِشْ ... ثَمَانِينَ حَوْلاً لَا أَبَا لَكَ يَسْأَمِ».', 'امام زوزنی فرماتے ہیں: ''زہیر بن ابی سلمیٰ حکمت، دانائی اور امن کے علمبردار شاعر تھے؛ انہوں نے ہرم بن سنان اور حارث بن عوف کی تعریف میں یہ معلقہ کہا جنہوں نے داحس و غبراء کی چالیس سالہ خونی جنگ کو ختم کرنے کے لیے مقتولین کی دیتیں اپنے پلے سے ادا کیں، زہیر نے جنگ کے بھیانک نتائج سے ڈراتے ہوئے کہا: ''اور جنگ کوئی نامعلوم چیز نہیں ہے بلکہ تم نے اس کی تباہ کاریوں کو خود چکھا ہے؛ جب بھی تم اسے چھیڑو گے تو وہ ایک بدصورت ڈائن کی طرح بھڑکے گی اور تمہیں آگ کی طرح جلا کر راکھ کر دے گی!'' اور اس کے آخر میں دانائی کے وہ لازوال اشعار کہے: ''اور جو شخص مال و دولت کا مالک ہو پھر اپنی قوم کے ضرورت مندوں پر بخل کرے تو لوگ اس سے بے نیاز ہو جاتے ہیں اور ہر طرف اس کی مذمت کی جاتی ہے! اور جو شخص اپنے مال کو اپنی عزت کی حفاظت کی ڈھال بناتا ہے اس کی عزت محفوظ رہتی ہے، اور جو گالیوں اور بدگوئی سے بچنے کی تدبیر نہیں کرتا اسے گالیاں دی جاتی ہیں! میں زندگی کی مشقتوں سے تنگ آ چکا ہوں، اور جو شخص اسی سال کی طویل عمر گزار لے وہ یقیناً زندگی سے اکتا جاتا ہے!''', 'زہیر بن ابی سلمیٰ کے اشعار حکمت کے موتی ہیں۔ رسول اللہ ﷺ زہیر کے بیٹے کعب بن زہیر کا قصیدہ (بانت سعاد) سن کر اپنی مبارک چادر ان پر ڈال دی تھی۔', '[{"word":"ذَمِيمَةً","role":"حال منصوب","sign":"فتحة","detail":"تبين حال الحرب"},{"word":"حَوْلاً","role":"تمييز منصوب","sign":"فتحة","detail":"لثمانين"}]', '["شرح المعلقات للزوزني، ص 80-102."]', '{"en":"Zuhayr ibn Abi Sulma: The sage poet of peace. Warning against warfare: ''War is nothing but what you have tasted... Whenever you unleash it, it rages like a ravenous inferno.'' And his timeless wisdom: ''He who possesses wealth yet withholds it from his kin will be discarded and reviled.''","ar":"الحكمة الجاهلية في نبذ الحروب العبثية والترغيب في الجود وصيانة العرض."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_adab_dunya_din_mawardi', 'أَدَبُ الدُّنْيَا وَالدِّينِ', 'الإِمَامُ أَبُو الحَسَنِ عَلِيُّ بْنُ مُحَمَّدٍ المَاوَرْدِيُّ الشَّافِعِيُّ (ت: 450ھ)', 'kharji_kitab', 'adab', 'نظامِ زندگی، اخلاقِ حسنہ اور تدبیرِ معاش', 'کتبِ مطالعہ و فلسفۂ اخلاق', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'دین اور دنیا کے تعلق، عقل کی فضیلت، علم کی برکت، اور معاشرتی زندگی کے سنہری آداب پر مشتمل صدیوں کی معتمد کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adab_dunya_ch1_ilm', 'kharji_adab_dunya_din_mawardi', 0, 'البَابُ الأَوَّلُ: فِي فَضِيلَةِ العِلْمِ وَأَدَبِ العَقْلِ وَالهَوَى', 'باب 1: عقل اور خواہشِ نفس کی کشمکش — علم عقل کا نگران اور نفس کا محافظ ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adab_dunya_seg_1_1', 'adab_dunya_ch1_ilm', 'kharji_adab_dunya_din_mawardi', 0, 'قَالَ الإِمَامُ أَبُو الحَسَنِ عَلِيُّ بْنُ مُحَمَّدٍ المَاوَرْدِيُّ الشَّافِعِيُّ: «العَقْلُ هُوَ قُطْبُ الرَّحَى الَّذِي تَدُورُ عَلَيْهِ مَصَالِحُ الدُّنْيَا وَالدِّينِ؛ وَالهَوَى ضِدُّهُ وَعَدُوُّهُ المُبِينُ. فَإِذَا غَلَبَ العَقْلُ الهَوَى اسْتَقَامَتِ الأَحْوَالُ، وَإِذَا غَلَبَ الهَوَى العَقْلَ فَسَدَ الزَّمَانُ. وَالعِلْمُ هُوَ نُورُ العَقْلِ الَّذِي يُبْصِرُ بِهِ طُرُقَ الخَيْرِ مِنْ مَهَالِكِ الشَّرِّ. قَالَ بَعْضُ الحُكَمَاءِ: «العِلْمُ حَيَاةُ النَّفْسِ، وَالعَقْلُ مُدَبِّرُ الجَسَدِ؛ فَلَا حَيَاةَ لِجَسَدٍ لَا رُوحَ فِيهِ، وَلَا قِيَامَ لِرُوحٍ لَا عَقْلَ يَهْدِيهَا».', 'امام ابو الحسن علی بن محمد الماوردی شافعی رحمہ اللہ فرماتے ہیں: ''عقل وہ مرکزی دھرہ ہے جس کے گرد دنیا اور دین دونوں کی ساری مصلحتیں گھومتی ہیں؛ اور نفسانی خواہش (ہویٰ) اس عقل کی کھلی دشمن اور اس کے متضاد ہے۔ پس جب عقل خواہشِ نفس پر غالب آ جائے تو انسان کے تمام احوال سنور جاتے ہیں، اور جب خواہشِ نفس عقل پر غالب آ جائے تو معاشرہ اور زمانہ فساد کی نذر ہو جاتا ہے۔ اور علم دراصل عقل کی وہ آنکھ اور روشنی ہے جس کے ذریعے وہ خیر کے راستوں کو شر کی ہلاکتوں سے جدا کر کے دیکھتی ہے۔ کسی دانا نے فرمایا: ''علم نفس کی روح اور زندگی ہے، اور عقل جسم کی تدبیر کرنے والی ہے؛ پس اس جسم کی کوئی زندگی نہیں جس میں روح نہ ہو، اور اس روح کی کوئی بقا نہیں جسے راہنمائی دینے والی عقل میسر نہ ہو''۔', 'أدب الدنيا والدين امام ماوردی کی وہ بے مثل کتاب ہے جس میں انہوں نے اخلاقیات، معاشیات، سیاست اور مذہب کو ایک لڑی میں پرو کر انسان کے لیے کامل ضابطۂ حیات پیش کیا۔', '[{"word":"قُطْبُ","role":"خبر المبتدأ العقل مرفوع","sign":"ضمة","detail":"وهو مضاف والرحى مضاف إليه"},{"word":"ضِدُّهُ","role":"خبر المبتدأ الهوى مرفوع","sign":"ضمة","detail":"والهاء مضاف إليه"}]', '["أدب الدنيا والدين للماوردي، ص 10-24، دار الكتب العلمية."]', '{"en":"Imam Al-Mawardi''s masterpiece ''Adab ad-Dunya wad-Din'': Reason (Aql) is the axis of human welfare, while caprice (Hawa) is its sworn adversary. When reason subdues desire, affairs flourish; when desire overpowers intellect, catastrophe ensues. Knowledge is the radiant sight of the intellect.","ar":"الموازنة بين سلطان العقل وسلطان الهوى ودور العلم في ترشيد المسار البشري."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('adab_dunya_ch2_adab_dunya', 'kharji_adab_dunya_din_mawardi', 1, 'البَابُ الثَّالِثُ: فِي صَلَاحِ الدُّنْيَا: الأَمْنُ وَالعَدْلُ وَالخِصْبُ وَالأَمَلُ', 'باب 2: دنیا کی فلاح و بہبود کے چار بنیادی ستون — امن، عدل و انصاف، معاشی فراوانی اور امید');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('adab_dunya_seg_2_1', 'adab_dunya_ch2_adab_dunya', 'kharji_adab_dunya_din_mawardi', 0, '«قَالَ المَاوَرْدِيُّ: قَوَاعِدُ صَلَاحِ الدُّنْيَا سِتَّةُ أَشْيَاءَ هِيَ أُصُولُ عِمَارَتِهَا: دِينٌ مُتَّبَعٌ يَزْجُرُ الضَّمَائِرَ، وَسُلْطَانٌ قَاهِرٌ يَكُفُّ الجُفَاةَ، وَعَدْلٌ شَامِلٌ يَدْعُو إِلَى الأُلْفَةِ، وَأَمْنٌ عَامٌّ تَهْدَأُ فِيهِ النُّفُوسُ، وَخِصْبٌ دَائِمٌ يَتَّسِعُ فِيهِ الرِّزْقُ، وَأَمَلٌ فَسِيحٌ يَبْعَثُ عَلَى عِمَارَةِ الأَرْضِ. فَإِذَا اخْتَلَّ العَدْلُ خَرِبَتِ البِلَادُ؛ لِأَنَّ الظُّلْمَ مُؤْذِنٌ بِانْقِطَاعِ العُمْرَانِ كَمَا شَهِدَتْ بِهِ تَجَارِبُ الأُمَمِ».', 'امام ماوردی فرماتے ہیں: ''دنیا کی خوشحالی اور اس کی فلاح کے چھ ایسے بنیادی ستون ہیں جن پر پوری انسانی بستیوں کی آبادی کا انحصار ہے: 1. ایسا دین جس کی پیروی کی جائے جو دلوں کے ضمیر کو بیدار رکھے، 2. ایسا باوقار حکمران جو ظالموں کے ہاتھ روک سکے، 3. ایسا ہمہ گیر عدل و انصاف جو معاشرے میں باہمی محبت پیدا کرے، 4. ایسا عام امن و امان جس کے سائے میں لوگ سکون سے زندگی گزاریں، 5. ایسی زرخیزی اور خوشحالی جس سے رزق میں کشادگی ہو، اور 6. ایسی وسیع امید جو انسان کو زمین آباد کرنے اور محنت پر ابھارے۔ پس جب معاشرے میں انصاف کا توازن بگڑ جاتا ہے تو بستیاں اجڑ جاتی ہیں؛ کیونکہ ظلم و ناانصافی تاریخ کے اٹل تجربے کے مطابق تہذیبوں کی تباہی کا کھلا اعلان ہے''۔', 'یہ عمرانی نظریہ ابن خلدون کے مقدمے سے صدیوں پہلے ماوردی نے پیش کیا تھا کہ کسی ملک کی معیشت اور بقا عدل اور امن کے بغیر قائم نہیں رہ سکتی۔', '[{"word":"سِتَّةُ","role":"خبر المبتدأ قواعد مرفوع","sign":"ضمة","detail":"وهو مضاف وأشياء مضاف إليه"},{"word":"مُؤْذِنٌ","role":"خبر المبتدأ الظلم مرفوع","sign":"ضمة","detail":"اسم فاعل يعمل عمل فعله"}]', '["أدب الدنيا والدين، ص 125-140."]', '{"en":"Al-Mawardi''s Six Pillars of Civilizational Prosperity: Practiced religion governing consciences, strong governance restraining tyrants, comprehensive justice fostering social fraternity, public security, sustainable agricultural prosperity, and enduring hope driving enterprise.","ar":"أسس العمران البشري ومقومات ازدهار الدول وسقوطها بالظلم."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_aqeedah_tahawiyyah_sharah', 'شَرْحُ العَقِيدَةِ الطَّحَاوِيَّةِ', 'العَلَّامَةُ عَلِيُّ بْنُ عَلِيِّ ابْنِ أَبِي العِزِّ الحَنَفِيُّ (ت: 792ھ)', 'kharji_kitab', 'aqaid', 'عقائدِ اہلِ سنت و جماعت کا عظیم الشان اور مدلل ذخیرہ', 'کتبِ مطالعہ و درجہ سابعہ / موقوف علیہ', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'امام ابو جعفر طحاوی کے عقیدے کی سب سے معتمد، مدلل اور مشہور ترین شرح جس میں سلفِ صالحین کے عقائد کا دفاع کیا گیا ہے۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tahawiyyah_ch1_tawheed', 'kharji_aqeedah_tahawiyyah_sharah', 0, 'أَصْلُ التَّوْحِيدِ: تَوْحِيدُ الرُّبُوبِيَّةِ وَالأُلُوهِيَّةِ وَالأَسْمَاءِ وَالصِّفَاتِ', 'باب 1: توحید کی حقیقت — توحیدِ ربوبیت، توحیدِ الوہیت اور اسماء و صفات کا اثبات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tahawiyyah_seg_1_1', 'tahawiyyah_ch1_tawheed', 'kharji_aqeedah_tahawiyyah_sharah', 0, 'قَالَ العَلَّامَةُ ابْنُ أَبِي العِزِّ الحَنَفِيُّ فِي شَرْحِهِ عَلَى الإِمَامِ الطَّحَاوِيِّ: «نَقُولُ فِي تَوْحِيدِ اللَّهِ مُعْتَقِدِينَ بِتَوْفِيقِ اللَّهِ: إِنَّ اللَّهَ وَاحِدٌ لَا شَرِيكَ لَهُ، وَلَا شَيْءَ مِثْلُهُ، وَلَا شَيْءَ يُعْجِزُهُ، وَلَا إِلَهَ غَيْرُهُ. وَالتَّوْحِيدُ الَّذِي دَعَتْ إِلَيْهِ الرُّسُلُ لَيْسَ هُوَ مُجَرَّدَ الإِقْرَارِ بِأَنَّ اللَّهَ خَالِقُ الكَوْنِ (تَوْحِيدُ الرُّبُوبِيَّةِ)؛ فَإِنَّ مُشْرِكِي قُرَيْشٍ كَانُوا يُقِرُّونَ بِذَلِكَ كَمَا قَالَ تَعَالَى: {وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ}، وَإِنَّمَا التَّوْحِيدُ المَطْلُوبُ هُوَ إِفْرَادُ اللَّهِ بِالعِبَادَةِ كُلِّهَا: دُعَاءً وَنَذْراً وَذَبْحاً وَرَجَاءً وَخَوْفاً (تَوْحِيدُ الأُلُوهِيَّةِ)».', 'علامہ صدر الدین علی بن علی ابن ابی العز حنفی رحمہ اللہ امام ابو جعفر طحاوی کے متن کی شرح میں فرماتے ہیں: ''ہم اللہ کی توفیق پر بھروسہ کرتے ہوئے توحید کے بارے میں یہ عقیدہ رکھتے ہیں: یقیناً اللہ ایک ہے اس کا کوئی شریک نہیں، کوئی چیز اس کے مانند نہیں، کوئی چیز اسے عاجز نہیں کر سکتی، اور اس کے سوا کوئی سچا معبود نہیں۔ اور وہ توحید جس کی طرف تمام انبیاء نے دعوت دی وہ محض اس بات کا اقرار نہیں تھی کہ اللہ کائنات کا پیدا کرنے والا ہے (توحیدِ ربوبیت)؛ کیونکہ قریش کے مکہ کے مشرکین بھی اس کا مکمل اقرار کرتے تھے جیسا کہ قرآن نے فرمایا: {اور اگر آپ ان سے پوچھیں کہ آسمانوں اور زمین کو کس نے پیدا کیا تو وہ لازماً کہیں گے کہ اللہ نے!}، بلکہ وہ اصل توحید جس پر نجات موقوف ہے وہ یہ ہے کہ تمام کی تمام عبادتیں صرف اللہ کے لیے خاص کی جائیں: دعا مانگنا، نذر نیاز، قربانی، امید اور خوف سب صرف اللہ سے ہو (توحیدِ الوہیت)''۔', 'شرح العقيدة الطحاوية اہل سنت والجماعت کے سلفی و حنفی عقائد کی متفقہ اور سب سے مستند کتاب ہے جس نے گمراہ کن فلسفیانہ تاویلات سے دین کو پاک کر کے صحابہ کے عقیدے کو نکھارا۔', '[{"word":"وَاحِدٌ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"لفظ الجلالة اسمها"},{"word":"دُعَاءً","role":"بدل أو تفصيل لمنصوب","sign":"فتحة","detail":"تفصيل للعبادة"}]', '["شرح العقيدة الطحاوية لابن أبي العز الحنفي، ص 25-40، بتحقيق التركي والأرناؤوط."]', '{"en":"Ibn Abi al-''Izz al-Hanafi''s authoritative commentary on the Creed of Imam At-Tahawi: True Monotheism is not merely Tawhid ar-Rububiyyah (affirming God as Creator, which pagan Quraysh acknowledged), but Tawhid al-Uluhiyyah—directing all worship, prayer, slaughter, and reliance exclusively to Him.","ar":"تحرير أركان التوحيد والفرق بين توحيد الربوبية وتوحيد الألوهية."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('tahawiyyah_ch2_quran_kalam', 'kharji_aqeedah_tahawiyyah_sharah', 1, 'عَقِيدَةُ أَهْلِ السُّنَّةِ فِي أَنَّ القُرْآنَ كَلَامُ اللَّهِ غَيْرُ مَخْلُوقٍ', 'باب 2: قرآنِ مجید اللہ کا کلام ہے، مخلوق نہیں — اہل سنت والجماعت کا قطعی عقیدہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('tahawiyyah_seg_2_1', 'tahawiyyah_ch2_quran_kalam', 'kharji_aqeedah_tahawiyyah_sharah', 0, '«قَالَ الإِمَامُ الطَّحَاوِيُّ وَشَارِحُهُ: «وَإِنَّ القُرْآنَ كَلَامُ اللَّهِ، مِنْهُ بَدَأَ بِلَا كَيْفِيَّةٍ قَوْلاً، وَأَنْزَلَهُ عَلَى رَسُولِهِ وَحْياً، وَصَدَّقَهُ المُؤْمِنُونَ عَلَى ذَلِكَ حَقّاً، وَأَيْقَنُوا أَنَّهُ كَلَامُ اللَّهِ تَعَالَى بِالحَقِيقَةِ، لَيْسَ بِمَخْلُوقٍ كَكَلَامِ البَرِيَّةِ؛ فَمَنْ سَمِعَهُ فَزَعَمَ أَنَّهُ كَلَامُ البَشَرِ فَقَدْ كَفَرَ، وَقَدْ ذَمَّهُ اللَّهُ وَأَوْعَدَهُ بِسَقَرَ حَيْثُ قَالَ تَعَالَى: {سَأُصْلِيهِ سَقَرَ} لَمَّا قَالَ: {إِنْ هَذَا إِلَّا قَوْلُ الْبَشَرِ}». وَالكَلَامُ صِفَةٌ قَائِمَةٌ بِذَاتِهِ تَعَالَى تَكَلَّمَ بِهِ حَقِيقَةً بِحَرْفٍ وَصَوْتٍ يَلِيقُ بِجَلَالِهِ».', 'امام طحاوی اور ان کے شارح ابن ابی العز فرماتے ہیں: ''اور بلاشبہ قرآن کریم اللہ کا سچا کلام ہے، اسی کی ذات سے بغیر کسی کیفیت کے کلام کے طور پر صادر ہوا، اور اس نے اپنے رسول پر وحی کے ذریعے نازل فرمایا، اور تمام اہل ایمان نے اس کو برحق تسلیم کیا اور یہ پختہ یقین رکھا کہ یہ حقیقت میں اللہ تعالیٰ کا کلام ہے، مخلوق کی طرح پیدا کیا ہوا نہیں ہے؛ پس جس نے قرآن کو سنا اور یہ دعویٰ کیا کہ یہ انسان کا کلام ہے تو اس نے صریح کفر کیا، اور اللہ نے ایسے معترض کی مذمت فرمائی اور اسے دوزخ کے سقر عذاب کی وعید سنائی جہاں فرمایا: {عنقریب میں اسے سقر کی آگ میں جھونک دوں گا} کیونکہ اس نے کہا تھا کہ {یہ تو محض انسان کا کلام ہے}۔ اور کلام اللہ کی ذات کی صفت ہے جس سے وہ حقیقت میں متکلم ہے جیسا کہ اس کی شانِ جلال کے لائق ہے''۔', 'یہ مسئلہ اہل سنت کا امتیازی نشان ہے جس پر امام احمد بن حنبل نے کوڑے کھائے مگر قرآن کو مخلوق ماننے سے انکار کر دیا تاکہ شریعت کی بنیاد محفوظ رہے۔', '[{"word":"كَلَامُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"القرآن اسمها وكلام خبرها"},{"word":"سَقَرَ","role":"مفعول به ثان لأصليه منصوب","sign":"فتحة","detail":"ممنوع من الصرف للعلمية والتأنيث"}]', '["شرح العقيدة الطحاوية، ص 168-185."]', '{"en":"The Uncreated Speech of Allah: ''The Quran is the Speech of Allah, originating from Him without modality as spoken word, revealed to His Messenger as revelation... It is not created like the speech of mortals. Whoever claims it is human speech has disbelieved.''","ar":"تقرير عقيدة السلف في إثبات صفة الكلام لله تعالى والرد على الجهمية والمعتزلة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lumah_itiqad_maqdisi', 'لُمْعَةُ الِاعْتِقَادِ الهَادِي إِلَى سَبِيلِ الرَّشَادِ', 'الإِمَامُ مُوَفَّقُ الدِّينِ ابْنُ قُدَامَةَ المَقْدِسِيُّ (ت: 620ھ)', 'kharji_kitab', 'aqaid', 'صفاتِ باری تعالیٰ اور نصوصِ شریعت پر ایمان کا سلفی منہج', 'کتبِ مطالعہ و عقائدِ سلف', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'اللہ کی صفات پر بغیر تاویل، بغیر تعطیل، بغیر تمثیل اور بغیر تکییف کے ایمان لانے کا سلفِ صالحین کا تابناک عقیدہ۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('lumah_ch1_sifat', 'kharji_lumah_itiqad_maqdisi', 0, 'بَابُ الإِيمَانِ بِآيَاتِ الصِّفَاتِ وَأَحَادِيثِهَا عَلَى ظَاهِرِهَا بِلَا تَأْوِيلٍ وَلَا تَعْطِيلٍ', 'باب 1: صفاتِ الٰہی پر ایمان — بلا تحریف، بلا تعطیل، بلا تکییف اور بلا تمثیل');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('lumah_seg_1_1', 'lumah_ch1_sifat', 'kharji_lumah_itiqad_maqdisi', 0, 'قَالَ الإِمَامُ مُوَفَّقُ الدِّينِ ابْنُ قُدَامَةَ المَقْدِسِيُّ: «كُلُّ مَا جَاءَ فِي القُرْآنِ أَوْ صَحَّ عَنِ المُصْطَفَى ﷺ مِنْ صِفَاتِ الرَّحْمَنِ، وَجَبَ الإِيمَانُ بِهِ، وَتَلَقِّيهِ بِالتَّسْلِيمِ وَالقَبُولِ، وَتَرْكُ التَّعَرُّضِ لَهُ بِالرَّدِّ وَالتَّأْوِيلِ، وَالتَّشْبِيهِ وَالتَّمْثِيلِ. فَمَا أَشْكَلَ مِنْ ذَلِكَ وَجَبَ إِثْبَاتُهُ لَفْظاً، وَتَرْكُ التَّعَمُّقِ فِي مَعْنَاهُ، وَنَرُدُّ عِلْمَهُ إِلَى قَائِلِهِ. كَقَوْلِهِ تَعَالَى: {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى}، وَقَوْلِهِ: {بَلْ يَدَاهُ مَبْسُوطَتَانِ}، وَقَوْلِهِ: {يَبْقَى وَجْهُ رَبِّكَ}؛ نُؤْمِنُ بِهَا وَنَعْلَمُ أَنَّهُ: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ}».', 'امام موفق الدین عبد اللہ بن احمد ابن قدامہ مقدسی حنبلی رحمہ اللہ فرماتے ہیں: ''اللہ کی صفات کے بارے میں جو کچھ بھی قرآنِ مجید میں آیا ہے یا رسول اللہ ﷺ سے صحیح سند کے ساتھ ثابت ہے، اس پر ایمان لانا، اس کو تسلیم و رضا کے ساتھ قبول کرنا، اور اس پر تاویل کرنے، رد کرنے، تشبیہ دینے اور مثالیں گھڑنے سے بالکلیہ باز رہنا فرض ہے۔ پس ان صفات کے جو الفاظ بھی آئے ہیں ان کے الفاظ کو ثابت مانا جائے گا، ان کی کیفیت میں غیر شرعی کھوج سے پرہیز کیا جائے گا، اور اس کی اصل حقیقت کا علم اللہ کے سپرد کیا جائے گا۔ جیسے اللہ کا فرمان: {رحمان عرش پر مستوی ہوا}، اور اس کا فرمان: {بلکہ اللہ کے دونوں ہاتھ کشادہ ہیں}، اور فرمایا: {اور تیرے رب کا باجلال چہرہ باقی رہے گا}؛ ہم ان تمام صفات پر ایمان لاتے ہیں اور یہ یقین رکھتے ہیں کہ: {اس جیسی کوئی چیز نہیں اور وہ سب کچھ سننے والا اور دیکھنے والا ہے}''۔', 'لمعة الاعتقاد الهادي إلى سبيل الرشاد حنبلی عقائد کا سب سے متفقہ اور آسان متن ہے جس میں ابن قدامہ نے اہل سنت کا معتدل راستہ واضح کیا ہے۔', '[{"word":"الإِيمَانُ","role":"فاعل وجب مرفوع","sign":"ضمة","detail":"وجب فعل لازم"},{"word":"شَيْءٌ","role":"اسم ليس مؤخر مرفوع","sign":"ضمة","detail":"كمثله الكاف زائدة ومثله خبر مقدم مجرور لفظاً"}]', '["لمعة الاعتقاد لابن قدامة المقدسي، ص 10-18."]', '{"en":"Imam Ibn Qudamah al-Maqdisi''s ''Lum''at al-I''tiqad'' (Radiance of Faith): Affirming Allah''s divine attributes as revealed in the Quran and authentic Sunnah—accepting them with submission without distortion (Tahrif), negation (Ta''til), inquiring ''how'' (Takyif), or anthropomorphism (Tamthil), anchoring upon: {There is nothing like unto Him, and He is the All-Hearing, All-Seeing}.","ar":"تقرير منهج السلف الصالح في إثبات الصفات الإلهية وتنزيه الباري عن التشبيه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('lumah_ch2_qadar', 'kharji_lumah_itiqad_maqdisi', 1, 'بَابُ القَضَاءِ وَالقَدَرِ وَمَرَاتِبِهِ الأَرْبَعَةِ عِنْدَ أَهْلِ السُّنَّةِ', 'باب 2: تقدیر پر ایمان اور اس کے چار درجات (علم، کتابت، مشیت، اور خلق)');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('lumah_seg_2_1', 'lumah_ch2_qadar', 'kharji_lumah_itiqad_maqdisi', 0, '«وَمِنْ صِفَاتِ اللَّهِ تَعَالَى أَنَّهُ الفَعَّالُ لِمَا يُرِيدُ، لَا يَكُونُ شَيْءٌ فِي المُلْكِ إِلَّا بِإِرَادَتِهِ، وَلَا يَخْرُجُ عَنْ مَشِيئَتِهِ شَيْءٌ. وَالإِيمَانُ بِالقَدَرِ يَقُومُ عَلَى أَرْبَعِ مَرَاتِبَ: 1. العِلْمُ القَدِيمُ بِكُلِّ مَا سَيَكُونُ. 2. الكِتَابَةُ فِي اللَّوْحِ المَحْفُوظِ قَبْلَ خَلْقِ السَّمَاوَاتِ وَالأَرْضِ. 3. المَشِيئَةُ الشَّامِلَةُ النَّافِذَةُ الَّتِي مَا شَاءَ اللَّهُ كَانَ وَمَا لَمْ يَشَأْ لَمْ يَكُنْ. 4. الخَلْقُ؛ فَإِنَّ اللَّهَ خَالِقُ كُلِّ شَيْءٍ وَخَالِقُ أَفْعَالِ العِبَادِ، وَلِلْعَبْدِ قُدْرَةٌ وَاخْتِيَارٌ هُوَ بِهِمَا فَاعِلٌ حَقِيقَةً وَمُثَابٌ وَمُعَاقَبٌ».', 'ابن قدامہ رحمہ اللہ فرماتے ہیں: ''اور اللہ تعالیٰ کی صفات میں سے یہ ہے کہ وہ جو چاہتا ہے کر گزرتا ہے، اس کی کائنات میں کوئی ایک پتہ بھی اس کے ارادے کے بغیر نہیں ہل سکتا، اور کوئی چیز اس کی مشیت سے باہر نہیں۔ اور تقدیر پر ایمان چار درجات کے ماننے پر مکمل ہوتا ہے: 1. علمِ الٰہی: کہ اللہ ازل سے ہر اس چیز کو جانتا ہے جو قیامت تک ہونے والی ہے۔ 2. کتابت: کہ اللہ نے کائنات کی پیدائش سے پچاس ہزار سال پہلے لوحِ محفوظ میں ہر چیز لکھ دی۔ 3. مشیت: کہ اللہ کی مشیت سب پر حاوی ہے، جو اللہ چاہے وہ ہو کر رہتا ہے اور جو وہ نہ چاہے کبھی نہیں ہو سکتا۔ 4. خلق: کہ اللہ ہر چیز کا خالق ہے اور بندوں کے تمام افعال کو پیدا کرنے والا ہے، اور بندے کو اللہ نے قدرت اور ارادہ بخشا ہے جس کے تحت وہ اپنے افعال کا خود حقیقی فاعل ہے اور اسی ارادے کی بنیاد پر وہ ثواب یا سزا کا حقدار بنتا ہے''۔', 'یہ عقیدہ جبر اور قدر کے دونوں انتہاؤں کے درمیان عین اعتدال ہے۔ انسان نہ تو پتھر کی طرح مجبورِ محض ہے اور نہ ہی خود مختار خدا۔', '[{"word":"الفَعَّالُ","role":"خبر أنَّ مرفوع","sign":"ضمة","detail":"صيغة مبالغة"},{"word":"خَالِقُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"لفظ الجلالة اسمها"}]', '["لمعة الاعتقاد، باب الإيمان بالقدر، ص 35-45."]', '{"en":"The Four Tiers of Predestination (Qadar): 1. Eternal Divine Knowledge (''Ilm), 2. Inscription in the Preserved Tablet (Kitabah), 3. Sovereign Divine Will (Mashi''ah), 4. Divine Creation of all entities and human deeds (Khalq), while granting man moral agency and accountability.","ar":"مراتب القضاء والقدر الأربعة والرد على الجبرية والقدرية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_aqeedah_wasitiyyah_taymiyyah', 'العَقِيدَةُ الوَاسِطِيَّةُ', 'شَيْخُ الإِسْلَامِ أَحْمَدُ بْنُ عَبْدِ الحَلِيمِ ابْنُ تَيْمِيَّةَ (ت: 728ھ)', 'kharji_kitab', 'aqaid', 'اہلِ سنت و جماعت کا عقیدہ، صفاتِ الٰہی و صحابہ کے حقوق', 'کتبِ مطالعہ و اصولِ دین', NULL, NULL, 'from-stone-900 via-emerald-950 to-amber-950', NULL, 'ایک ہی نشست میں عصر تا مغرب لکھی جانے والی وہ تاریخی دستاویز جس نے دمشق کی علمی مجالس میں تمام مخالفین کو قائل کر لیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wasitiyyah_ch1_asl', 'kharji_aqeedah_wasitiyyah_taymiyyah', 0, 'مَنْهَجُ أَهْلِ السُّنَّةِ فِي صِفَاتِ اللَّهِ تَعَالَى: إِثْبَاتٌ بِلَا تَمْثِيلٍ وَتَنْزِيهٌ بِلَا تَعْطِيلٍ', 'باب 1: اسماء و صفات میں اہل سنت کا منہاج — بغیر تمثیل کے اثبات اور بغیر انکار کے پاکیزگی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wasitiyyah_seg_1_1', 'wasitiyyah_ch1_asl', 'kharji_aqeedah_wasitiyyah_taymiyyah', 0, 'قَالَ شَيْخُ الإِسْلَامِ ابْنُ تَيْمِيَّةَ: «هَذَا اعْتِقَادُ الفِرْقَةِ النَّاجِيَةِ المَنْصُورَةِ إِلَى قِيَامِ السَّاعَةِ أَهْلِ السُّنَّةِ وَالجَمَاعَةِ: وَهُوَ الإِيمَانُ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالبَعْثِ بَعْدَ المَوْتِ، وَالإِيمَانِ بِالقَدَرِ خَيْرِهِ وَشَرِّهِ. وَمِنَ الإِيمَانِ بِاللَّهِ: الإِيمَانُ بِمَا وَصَفَ بِهِ نَفْسَهُ فِي كِتَابِهِ، وَبِمَا وَصَفَهُ بِهِ رَسُولُهُ مُحَمَّدٌ ﷺ مِنْ غَيْرِ تَحْرِيفٍ وَلَا تَعْطِيلٍ، وَمِنْ غَيْرِ تَكْيِيفٍ وَلَا تَمْثِيلٍ؛ بَلْ يُؤْمِنُونَ بِأَنَّ اللَّهَ تَعَالَى: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ}؛ فَلَا يَنْفُونَ عَنْهُ مَا وَصَفَ بِهِ نَفْسَهُ، وَلَا يُمَثِّلُونَ صِفَاتِهِ بِصِفَاتِ خَلْقِهِ».', 'شیخ الاسلام احمد بن عبد الحلیم ابن تیمیہ رحمہ اللہ فرماتے ہیں: ''قیامت تک نجات پانے والی اور نصرت یافتہ جماعت اہل سنت والجماعت کا عقیدہ یہ ہے: یعنی اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر، اس کے رسولوں پر، مرنے کے بعد جی اٹھنے پر، اور تقدیر کی بھلائی اور برائی کے اللہ کی طرف سے ہونے پر ایمان لانا۔ اور اللہ پر ایمان لانے کا لازمی تقاضا یہ ہے کہ اللہ نے اپنی کتاب میں اپنی جو صفات بیان فرمائی ہیں، اور اس کے سچے رسول محمد ﷺ نے جو صفات بیان فرمائی ہیں، ان پر بغیر کسی تحریف (معنی بدلنے) کے، بغیر تعطیل (صفات کا انکار کرنے) کے، بغیر تکییف (کیفیت گھڑنے) کے، اور بغیر تمثیل (مخلوق سے تشبیہ دینے) کے ایمان لایا جائے؛ بلکہ اہل سنت اس پر ایمان رکھتے ہیں کہ: {اس جیسی کوئی چیز نہیں اور وہ سب کچھ سننے والا اور دیکھنے والا ہے}؛ پس وہ نہ تو ان صفات کا انکار کرتے ہیں جو اللہ نے خود اپنے لیے ثابت فرمائیں اور نہ ہی اس کی صفات کو مخلوق کی صفات کے مشابہ قرار دیتے ہیں''۔', 'العقيدة الواسطية شیخ الاسلام ابن تیمیہ کا وہ شہرۂ آفاق رسالہ ہے جو انہوں نے واسط کے قاضی کی درخواست پر عصر سے مغرب کے درمیان قلمبند فرمایا۔ یہ کتاب سلفی عقائد کا سب سے متوازن منشور ہے۔', '[{"word":"اعْتِقَادُ","role":"خبر المبتدأ هذا مرفوع","sign":"ضمة","detail":"وهو مضاف والفرقة مضاف إليه"},{"word":"تَحْرِيفٍ","role":"مضاف إليه مجرور بغير","sign":"كسرة","detail":"نفي التحريف والتعطيل"}]', '["العقيدة الواسطية لابن تيمية، ص 7-16، بتحقيق صالح الفوزان."]', '{"en":"Shaykh al-Islam Ibn Taymiyyah''s ''Al-Aqidah al-Wasitiyyah'': The Creed of the Saved Sect. Affirming divine attributes without alteration (Tahrif), negation (Ta''til), conjecturing modality (Takyif), or anthropomorphic comparison (Tamthil)—upholding {There is nothing like unto Him, and He is the All-Hearing, All-Seeing}.","ar":"الميثاق العقدي الجامع لأهل السنة والجماعة في أسماء الله وصفاته."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('wasitiyyah_ch2_uluww', 'kharji_aqeedah_wasitiyyah_taymiyyah', 1, 'إِثْبَاتُ عُلُوِّ اللَّهِ تَعَالَى عَلَى خَلْقِهِ وَمَعِيَّتِهِ لَهُمْ', 'باب 2: اللہ تعالیٰ کا اپنی ذات کے ساتھ عرش پر بلند ہونا اور اپنے علم کے ساتھ ہر جگہ بندوں کے ساتھ ہونا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('wasitiyyah_seg_2_1', 'wasitiyyah_ch2_uluww', 'kharji_aqeedah_wasitiyyah_taymiyyah', 0, '«وَقَدْ دَخَلَ فِي هَذِهِ الجُمْلَةِ مَا وَصَفَ اللَّهُ بِهِ نَفْسَهُ مِنْ أَنَّهُ قَرِيبٌ مُجِيبٌ، كَمَا جَمَعَ بَيْنَ ذَلِكَ فِي قَوْلِهِ: {هُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يَعْلَمُ مَا يَلِجُ فِي الْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنْزِلُ مِنَ السَّمَاءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ}. فَبَيَّنَ أَنَّهُ عَلَى العَرْشِ مُسْتَوٍ بَائِنٌ مِنْ خَلْقِهِ، وَهُوَ مَعَهُمْ بِعِلْمِهِ وَإِحَاطَتِهِ وَقُدْرَتِهِ حَيْثُمَا كَانُوا؛ لَا يَخْفَى عَلَيْهِ مِنْهُمْ خَافِيَةٌ».', 'ابن تیمیہ رحمہ اللہ فرماتے ہیں: ''اور اہل سنت کے عقیدے میں یہ بات بھی داخل ہے کہ اللہ تعالیٰ اپنی مخلوق سے بلند ہونے کے ساتھ ساتھ اپنے بندوں کے قریب اور دعاؤں کا قبول کرنے والا ہے، جیسا کہ اللہ نے ان دونوں باتوں کو اپنی اس آیت میں بیک وقت جمع فرمایا: {وہی ہے جس نے آسمانوں اور زمین کو چھ دن میں پیدا کیا پھر وہ عرش پر مستوی ہوا، وہ جانتا ہے جو کچھ زمین میں داخل ہوتا ہے اور جو اس سے نکلتا ہے، اور جو آسمان سے اترتا ہے اور جو اس میں چڑھتا ہے، اور وہ تمہارے ساتھ ہے جہاں کہیں بھی تم ہو، اور اللہ تمہارے تمام اعمال کو خوب دیکھنے والا ہے}۔ پس اللہ نے واضح فرما دیا کہ وہ اپنی ذات کے ساتھ عرشِ عظیم پر مستوی ہے اور اپنی مخلوق سے بالکل جدا ہے، اور وہ اپنے کامل علم، نگرانی، احاطے اور قدرت کے ساتھ اپنے بندوں کے ساتھ ہے وہ جہاں کہیں بھی ہوں؛ ان کی کوئی ایک چھوٹی سی بات بھی اللہ سے پوشیدہ نہیں رہ سکتی''۔', 'اہل سنت کا یہ عقیدہ حلول اور اتحاد کی گمراہی کا خاتمہ کرتا ہے کہ اللہ کائنات کے اندر حلول نہیں کیے ہوئے بلکہ عرش پر مستوی ہے اور اپنے علم سے کائنات کے ہر ذرے پر محیط ہے۔', '[{"word":"مُسْتَوٍ","role":"خبر ثانٍ مرفوع بضمة مقدرة","sign":"ضمة مقدرة","detail":"على الياء المحذوفة"},{"word":"بَصِيرٌ","role":"خبر المبتدأ لفظ الجلالة مرفوع","sign":"ضمة","detail":"بما تعملون متعلق به"}]', '["العقيدة الواسطية، ص 48-60."]', '{"en":"Harmonizing Transcendence (Uluww) and Immanence (Ma''iyyah): Allah is established upon His Throne distinct from creation, while simultaneously ''with'' His servants through His all-encompassing knowledge, sight, and dominion ({He is with you wherever you are}).","ar":"الجمع بين مباينة الله لخلقه وعلوه الذاتي ومعيته العلمية العامة والخاصة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_kitab_tawheed_ibn_khuzaymah', 'كِتَابُ التَّوْحِيدِ وَإِثْبَاتِ صِفَاتِ الرَّبِّ عَزَّ وَجَلَّ', 'إِمَامُ الأَئِمَّةِ أَبُو بَكْرٍ مُحَمَّدُ بْنُ إِسْحَاقَ ابْنُ خُزَيْمَةَ (ت: 311ھ)', 'kharji_kitab', 'aqaid', 'توحید اور اثباتِ صفاتِ رب العالمین باسانیدِ صحیحہ', 'کتبِ مطالعہ و مسنداتِ عقیدہ', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'امام الائمہ ابن خزیمہ کی چوتھی صدی ہجری کی عظیم الشان مسند کتاب جس میں صحیح اسانید سے توحید اور صفاتِ باری تعالیٰ کا ثبوت پیش کیا گیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('khuzaymah_ch1_ruyah', 'kharji_kitab_tawheed_ibn_khuzaymah', 0, 'بَابُ إِثْبَاتِ رُؤْيَةِ المُؤْمِنِينَ لِرَبِّهِمْ فِي الآخِرَةِ عِيَاناً', 'باب 1: آخرت میں اہل جنت کا اپنے رب کو اپنی آنکھوں سے بے نقاب دیکھنا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('khuzaymah_seg_1_1', 'khuzaymah_ch1_ruyah', 'kharji_kitab_tawheed_ibn_khuzaymah', 0, 'قَالَ إِمَامُ الأَئِمَّةِ أَبُو بَكْرٍ مُحَمَّدُ بْنُ إِسْحَاقَ ابْنُ خُزَيْمَةَ: «بَابُ ذِكْرِ إِثْبَاتِ رُؤْيَةِ المُؤْمِنِينَ خَالِقَهُمْ يَوْمَ القِيَامَةِ كَمَا يَرَوْنَ الشَّمْسَ صَحْواً لَيْسَ دُونَهَا سَحَابٌ، وَالقَمَرَ لَيْلَةَ البَدْرِ. عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ البَجَلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا جُلُوساً عِنْدَ النَّبِيِّ ﷺ إِذْ نَظَرَ إِلَى القَمَرِ لَيْلَةَ البَدْرِ فَقَالَ: «إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا القَمَرَ، لَا تُضَامُونَ فِي رُؤْيَتِهِ؛ فَإِنِ اسْتَطَعْتُمْ أَلَّا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَصَلَاةٍ قَبْلَ غُرُوبِهَا فَافْعَلُوا! (يَعْنِي الفَجْرَ وَالعَصْرَ)».', 'امام الائمہ ابو بکر محمد بن اسحاق ابن خزیمہ نیشاپوری رحمہ اللہ فرماتے ہیں: ''اس باب میں قیامت اور جنت کے اندر مومنوں کا اپنے پیدا کرنے والے رب کو اپنی آنکھوں سے روبرو دیکھنے کا قطعی ثبوت ہے جیسے انسان دوپہر کے وقت بغیر بادل کے سورج کو دیکھتا ہے یا چودھویں کی رات چاند کو دیکھتا ہے۔ حضرت جریر بن عبد اللہ بجلی رضی اللہ عنہ سے روایت ہے کہ ہم رسول اللہ ﷺ کی خدمت میں بیٹھے ہوئے تھے کہ آپ نے چودھویں کی رات کے چاند کی طرف دیکھا اور فرمایا: ''تم عنقریب اپنے پروردگار کو اپنی آنکھوں سے دیکھو گے جیسے تم اس چاند کو بلا رکاوٹ دیکھ رہے ہو، تمہیں اس کے دیکھنے میں نہ کوئی تنگی ہوگی نہ دھکم پیل؛ پس اگر تم سے ہو سکے تو سورج نکلنے سے پہلے کی نماز (فجر) اور سورج ڈوبنے سے پہلے کی نماز (عصر) کی پابندی میں کبھی مغلوب نہ ہونا تو ضرور اس پر عمل کرو!''', 'كتاب التوحيد وإثبات صفات الرب عز وجل تیسری صدی ہجری کی وہ عظیم الشان کتاب ہے جسے امام ابن خزیمہ نے دلائلِ قاطعہ کے ساتھ تحریر فرمایا۔ رؤیتِ باری تعالیٰ جنتیوں کا سب سے بڑا انعام ہے۔', '[{"word":"رَبَّكُمْ","role":"مفعول به لترون منصوب","sign":"فتحة","detail":"وهو مضاف وكم مضاف إليه"},{"word":"عِيَاناً","role":"حال منصوب","sign":"فتحة","detail":"يفيد الرؤية بالبصر حقيقة"}]', '["كتاب التوحيد لابن خزيمة، 1/ 420-435، وأخرجه البخاري (554)."]', '{"en":"Imam of the Imams Ibn Khuzaymah''s ''Kitab at-Tawhid'': Verifying the Beatific Vision of Allah in the Hereafter: ''Indeed you shall see your Lord just as you see this full moon, without difficulty in beholding Him.'' Linking the vision to the guarding of Fajr and ''Asr prayers.","ar":"إثبات عقيدة الرؤية العينية للمؤمنين في جنات النعيم والرد على المعطلة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('khuzaymah_ch2_yadain', 'kharji_kitab_tawheed_ibn_khuzaymah', 1, 'بَابُ إِثْبَاتِ صِفَةِ اليَدَيْنِ لِلَّهِ تَعَالَى بِلَا كَيْفٍ', 'باب 2: صفاتِ الٰہی میں اللہ تعالیٰ کے دونوں دستِ مبارک کا اثبات جیسا کہ اس کی شان کے لائق ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('khuzaymah_seg_2_1', 'khuzaymah_ch2_yadain', 'kharji_kitab_tawheed_ibn_khuzaymah', 0, '«قَالَ ابْنُ خُزَيْمَةَ: نَحْنُ نُقِرُّ بِلِسَانِنَا، وَنَعْتَقِدُ بِقُلُوبِنَا، أَنَّ لِرَبِّنَا عَزَّ وَجَلَّ يَدَيْنِ مَوْصُوفَتَيْنِ بِالجَلَالِ وَالإِكْرَامِ، كَمَا نَطَقَ كِتَابُهُ فِي قَوْلِهِ لِإِبْلِيسَ: {مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ}، وَقَالَ ﷺ: «يَمِينُ اللَّهِ مَلْأَى لَا يَغِيضُهَا نَفَقَةٌ، سَحَّاءُ اللَّيْلَ وَالنَّهَارَ». وَلَا نُشَبِّهُ يَدَيْ خَالِقِنَا بِأَيْدِي المَخْلُوقِينَ؛ فَمَنْ شَبَّهَ اللَّهَ بِخَلْقِهِ فَهُوَ مُشَبِّهٌ ضَالٌّ، وَمَنْ أَنْكَرَ مَا وَصَفَ اللَّهُ بِهِ نَفْسَهُ فَهُوَ جَهْمِيٌّ مُعَطِّلٌ، وَأَهْلُ السُّنَّةِ وَسَطٌ بَيْنَ التَّشْبِيهِ وَالتَّعْطِيلِ».', 'امام ابن خزیمہ فرماتے ہیں: ''ہم اپنی زبان سے اقرار کرتے ہیں اور اپنے دلوں سے یہ پختہ عقیدہ رکھتے ہیں کہ ہمارے رب عزوجل کے دو دستِ مبارک ہیں جو جلال اور اکرام سے متصف ہیں جیسا کہ اس کی کتاب نے ابلیس سے خطاب کرتے ہوئے فرمایا: {تجھے اس ہستی (آدم) کو سجدہ کرنے سے کس چیز نے روکا جسے میں نے اپنے دونوں ہاتھوں سے بنایا}، اور رسول اللہ ﷺ نے فرمایا: ''اللہ کا دایاں ہاتھ بھرا ہوا ہے جسے شب و روز کی بارش کی طرح سخاوت بھی کم نہیں کر سکتی''۔ اور ہم اپنے خالق کے دستِ مبارک کو مخلوق کے ہاتھوں کے مشابہ نہیں ٹھہراتے؛ پس جس نے اللہ کو اس کی مخلوق سے تشبیہ دی وہ گمراہ مشبہ ہے، اور جس نے ان صفات کا انکار کیا وہ گمراہ جہمی معطل ہے، اور اہل سنت والجماعت تشبیہ اور انکار کے درمیان عین اعتدال کی شاہراہ پر ہیں''۔', 'ابن خزیمہ نے واضح کیا کہ اگر يدين سے مراد قدرت ہوتی تو آدم علیہ السلام کی کوئی خصوصیت نہ رہتی کیونکہ ابلیس بھی اللہ ہی کی قدرت سے پیدا ہوا تھا۔', '[{"word":"بِيَدَيَّ","role":"الباء حرف جر ويدي مجرور بالياء","sign":"ياء","detail":"مثنى وحذفت النون للإضافة"},{"word":"سَحَّاءُ","role":"خبر ثانٍ مرفوع","sign":"ضمة","detail":"صيغة مبالغة تفيد دوام العطاء"}]', '["كتاب التوحيد لابن خزيمة، 1/ 180-205، وأخرجه البخاري (4684)."]', '{"en":"Affirming the Attribute of Hands for Allah: As affirmed in the divine address to Iblis: {What prevented you from prostrating to that which I created with My Hands?}. Standing midway between the anthropomorphism of the Mushabbihah and the negation of the Jahmiyyah.","ar":"منهج أهل الحديث في إثبات الصفات الخبرية على مراد الله ورسوله."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_ibana_ashari', 'الإِبَانَةُ عَنْ أُصُولِ الدِّيَانَةِ', 'الإِمَامُ أَبُو الحَسَنِ عَلِيُّ بْنُ إِسْمَاعِيلَ الأَشْعَرِيُّ (ت: 324ھ)', 'kharji_kitab', 'aqaid', 'اعتزال سے رجوع اور منہجِ اہل سنت و احمد بن حنبل کی پیروی', 'کتبِ مطالعہ و تاریخِ عقائد', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'امام ابو الحسن اشعری کی وہ تاریخی آخری کتاب جس میں انہوں نے معتزلہ کے عقائد کو توڑ کر امام احمد بن حنبل اور اہل حدیث کے عقیدے کو اختیار کرنے کا اعلان کیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ibana_ch1_rujoo', 'kharji_ibana_ashari', 0, 'رُجُوعُ الإِمَامِ الأَشْعَرِيِّ إِلَى مَذْهَبِ أَهْلِ السُّنَّةِ وَالإِمَامِ أَحْمَدَ', 'باب 1: امام ابو الحسن اشعری کا اعتزال سے توبہ اور مسلکِ سلف و امام احمد کی پیروی کا اعلان');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ibana_seg_1_1', 'ibana_ch1_rujoo', 'kharji_ibana_ashari', 0, 'قَالَ الإِمَامُ أَبُو الحَسَنِ عَلِيُّ بْنُ إِسْمَاعِيلَ الأَشْعَرِيُّ: «قَوْلُنَا الَّذِي نَقُولُ بِهِ، وَدِيَانَتُنَا الَّتِي نَدِينُ بِهَا: التَّمَسُّكُ بِكِتَابِ رَبِّنَا عَزَّ وَجَلَّ، وَبِسُنَّةِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَمَا رُوِيَ عَنِ الصَّحَابَةِ وَالتَّابِعِينَ وَأَئِمَّةِ الحَدِيثِ؛ وَبِذَلِكَ نَعْتَصِمُ، وَبِمَا كَانَ يَقُولُ بِهِ أَبُو عَبْدِ اللَّهِ أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ نَضَّرَ اللَّهُ وَجْهَهُ قَائِلُونَ، وَلِمَنْ خَالَفَ قَوْلَهُ مُجَانِبُونَ؛ لِأَنَّهُ الإِمَامُ الفَاضِلُ الَّذِي أَبَانَ اللَّهُ بِهِ الحَقَّ، وَدَفَعَ بِهِ الضَّلَالَ، وَأَوْضَحَ بِهِ المِنْهَاجَ، وَقَمَعَ بِهِ مُبْتَدِعَةَ الزَّيْغِ».', 'امام ابو الحسن علی بن اسماعیل الاشعری رحمہ اللہ فرماتے ہیں: ''ہمارا وہ قطعی عقیدہ جس پر ہم قائم ہیں، اور ہمارا وہ دین جس پر ہم اللہ کی بندگی کرتے ہیں وہ یہ ہے: اپنے رب عزوجل کی کتاب، اپنے نبی محمد ﷺ کی سنت، اور جو کچھ صحابہ، تابعین اور ائمۂ حدیث سے منقول ہوا ہے اس کو مضبوطی سے تھامے رکھنا؛ اسی پر ہم جماؤ رکھتے ہیں، اور جو مسلک ابو عبد اللہ امام احمد بن حنبل کا تھا (اللہ ان کے چہرے کو روشن فرمائے) ہم وہی عقیدہ رکھتے ہیں، اور جو ان کے مسلک کے خلاف جائے ہم اس سے بیزار ہیں؛ کیونکہ امام احمد بن حنبل وہ باکمال امام ہیں جن کے ذریعے اللہ نے حق کو کھول کر واضح فرمایا، جن کے ذریعے گمراہی کو دفع فرمایا، جن کے ذریعے سیدھے راستے کو روشن کیا، اور جن کے ذریعے کج رو بدعتیوں کی سرکوبی فرمائی''۔', 'الإبانة عن أصول الديانة امام ابو الحسن اشعری کی آخری اور فیصلہ کن کتاب ہے جس میں انہوں نے معتزلہ کے عقائد سے بیزاری کا اعلان کر کے امام احمد بن حنبل اور محدثین کے مسلک کو اپنا عقیدہ قرار دیا۔', '[{"word":"التَّمَسُّكُ","role":"خبر المبتدأ قولنا مرفوع","sign":"ضمة","detail":"قولنا مبتدأ والتمسك خبره"},{"word":"قَائِلُونَ","role":"خبر لمبتدأ محذوف نحن مرفوع بالواو","sign":"واو","detail":"جمع مذكر سالم"}]', '["الإبانة عن أصول الديانة لأبي الحسن الأشعري، ص 20-30، دار البصيرة."]', '{"en":"Imam Abu al-Hasan al-Ash''ari''s final theological manifesto ''Al-Ibanah'': Renouncing Mu''tazilism and aligning completely with the traditional Sunnism of Imam Ahmad ibn Hanbal—clinging to the Quran, authentic Sunnah, and the consensus of Hadith masters.","ar":"إعلان الإمام الأشعري لمنهجه السلفي الأخير واقتدائه بالإمام أحمد."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('ibana_ch2_shafaa', 'kharji_ibana_ashari', 1, 'بَابُ إِثْبَاتِ حَوْضِ النَّبِيِّ ﷺ وَشَفَاعَتِهِ لأَهْلِ الكَبَائِرِ', 'باب 2: حوضِ کوثر اور گناہ گار مومنین کے لیے رسول اللہ ﷺ کی شفاعتِ کبریٰ کا اثبات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('ibana_seg_2_1', 'ibana_ch2_shafaa', 'kharji_ibana_ashari', 0, '«قَالَ الإِمَامُ الأَشْعَرِيُّ: وَنَدِينُ بِأَنَّ لِرَسُولِ اللَّهِ ﷺ حَوْضاً مَاؤُهُ أَشَدُّ بَيَاضاً مِنَ اللَّبَنِ، وَأَحْلَى مِنَ العَسَلِ، آنِيَتُهُ كَعَدَدِ نُجُومِ السَّمَاءِ، مَنْ شَرِبَ مِنْهُ شَرْبَةً لَمْ يَظْمَأْ بَعْدَهَا أَبَداً. وَنَدِينُ بِأَنَّ شَفَاعَةَ رَسُولِ اللَّهِ ﷺ حَقٌّ لِأَهْلِ الكَبَائِرِ مِنْ أُمَّتِهِ، خِلَافاً لِلْمُعْتَزِلَةِ وَالخَوَارِجِ الَّذِينَ زَعَمُوا أَنَّ الفَاسِقَ مُخَلَّدٌ فِي النَّارِ؛ لِقَوْلِهِ ﷺ: «شَفَاعَتِي لِأَهْلِ الكَبَائِرِ مِنْ أُمَّتِي». فَلَا يَبْقَى فِي النَّارِ مُوَحِّدٌ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ إِيمَانٍ».', 'امام اشعری فرماتے ہیں: ''اور ہمارا پختہ عقیدہ ہے کہ قیامت کے دن رسول اللہ ﷺ کے لیے حوضِ کوثر ہوگا جس کا پانی دودھ سے زیادہ سفید اور شہد سے زیادہ میٹھا ہے، اس کے پیالے آسمان کے تاروں کی مانند لاتعداد ہیں، جس نے اس میں سے ایک گھونٹ بھی پی لیا وہ اس کے بعد کبھی پیاسا نہیں ہوگا۔ اور ہمارا یہ عقیدہ ہے کہ رسول اللہ ﷺ کی شفاعت اپنی امت کے کبیرہ گناہ گاروں کے لیے برحق اور ثابت ہے، ان معتزلہ اور خوارج کے خلاف جنہوں نے یہ گمراہ کن دعویٰ کیا تھا کہ گناہ گار مسلمان ہمیشہ جہنم میں جلے گا؛ کیونکہ رسول اللہ ﷺ کا فرمان ہے: ''میری شفاعت میری امت کے کبیرہ گناہ کرنے والوں کے لیے ہے''۔ پس جہنم میں کوئی ایسا موحد اور کلمہ گو باقی نہیں رہے گا جس کے دل میں رائی کے دانے کے برابر بھی ایمان موجود ہو''۔', 'شفاعت کا عقیدہ امت کے لیے امید کی کرن ہے۔ اشعری نے خوارج کے اس تکفیری فتنہ کا قلع قمع کیا جو مسلمانوں کو گناہوں کی وجہ سے کافر قرار دیتے تھے۔', '[{"word":"حَقٌّ","role":"خبر أنّ مرفوع","sign":"ضمة","detail":"شفاعة اسمها وحق خبرها"},{"word":"مُوَحِّدٌ","role":"فاعل يبقى مرفوع","sign":"ضمة","detail":"في النار جار ومجرور متعلق به"}]', '["الإبانة، باب الشفاعة والحوض، ص 80-92، وأخرجه الترمذي (2435)."]', '{"en":"Affirming the Prophet''s Basin (Hawd) and Intercession (Shafa''ah) for major sinners of the Ummah, in direct refutation of Kharijites and Mu''tazilites who falsely condemned sinful Muslims to eternal Hellfire.","ar":"إثبات خروج أهل التوحيد من النار بشفاعة سيد الأخيار ﷺ."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_sawaiq_mursalah_jawziyyah', 'الصَّوَاعِقُ المُرْسَلَةُ عَلَى الجَهْمِيَّةِ وَالمُعَطِّلَةِ', 'الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ (ت: 751ھ)', 'kharji_kitab', 'aqaid', 'باطل تاویلات، تحریفات اور جہمیہ کا تفصیلی رد', 'کتبِ مطالعہ و مناظراتِ عقیدہ', NULL, NULL, 'from-red-950 via-stone-900 to-amber-950', NULL, 'قرآنی نصوص کو تاویل کے نام پر باطل معانی پہنانے والے فلاسفہ اور معطلہ کے چار بنیادی ستونوں کو پاش پاش کرنے والی کتاب۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sawaiq_ch1_taweel', 'kharji_sawaiq_mursalah_jawziyyah', 0, 'كَسْرُ طَاغُوتِ التَّأْوِيلِ الفَاسِدِ الَّذِي عَطَّلَ نُصُوصَ الوَحْيِ', 'باب 1: باطل تاویل کے بت کو پاش پاش کرنا — نصوصِ شریعت کو صریح معنی سے پھیرنے کی سازش کا رد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sawaiq_seg_1_1', 'sawaiq_ch1_taweel', 'kharji_sawaiq_mursalah_jawziyyah', 0, 'قَالَ الإِمَامُ ابْنُ قَيِّمِ الجَوْزِيَّةِ: «إِنَّ طَاغُوتَ التَّأْوِيلِ هُوَ المِفْتَاحُ الَّذِي فَتَحَ بِهِ أَهْلُ البِدَعِ بَابَ الزَّنْدَقَةِ وَالتَّعْطِيلِ؛ فَمَا رَدَّ مُعَطِّلٌ نَصّاً مِنَ الكِتَابِ أَوِ السُّنَّةِ إِلَّا بِحُجَّةِ التَّأْوِيلِ. وَالتَّأْوِيلُ فِي اصْطِلَاحِ السَّلَفِ هُوَ: عَيْنُ التَّفْسِيرِ، أَوْ نَفْسُ المَآلِ وَالحَقِيقَةِ الَّتِي يَئُولُ إِلَيْهَا الشَّيْءُ. أَمَّا فِي اصْطِلَاحِ المُتَأَخِّرِينَ فَهُوَ: صَرْفُ اللَّفْظِ عَنِ احْتِمَالِهِ الرَّاجِحِ إِلَى احْتِمَالٍ مَرْجُوحٍ لِدَلِيلٍ؛ فَإِذَا خَلَا عَنِ الدَّلِيلِ الصَّحِيحِ كَانَ تَحْرِيفاً بَاطِلاً لَا تَأْوِيلاً مَقْبُولاً».', 'امام ابن قیم الجوزیہ رحمہ اللہ فرماتے ہیں: ''بے شک باطل تاویل کا طاغوت اور بت وہ منحوس چابی ہے جس کے ذریعے گمراہ فرقوں نے الحاد اور انکارِ صفات کا دروازہ کھولا؛ کسی بھی گمراہ نے کتاب و سنت کی کسی نص کا انکار نہیں کیا مگر اسی جھوٹی تاویل کا سہارا لے کر۔ اور تاویل سلف صالحین کی اصطلاح میں دو معانی رکھتی ہے: یا تو وہ خود تفسیر کا نام ہے، یا وہ اس خارجی حقیقت کا نام ہے جس پر بات جا کر ختم ہوتی ہے۔ لیکن پچھلے کلامی لوگوں کی اصطلاح میں تاویل سے مراد یہ ہے کہ لفظ کے راجح اور ظاہر معنی کو چھوڑ کر کسی کمزور معنی کی طرف کسی دلیل کے تحت پھیر دیا جائے؛ پس اگر اس کے پیچھے کوئی صحیح شرعی دلیل نہ ہو تو وہ مقبول تاویل نہیں بلکہ کتاب اللہ کی کھلی تحریف اور کھلواڑ ہے''۔', 'الصواعق المرسلة على الجهمية والمعطلة امام ابن قیم کی وہ معرکۃ الآراء کتاب ہے جس نے فلسفے اور اعتزال کے ان چاروں بتوں (طاغوتِ تاویل، طاغوتِ مجاز، معارضۂ عقل و نقل وغیرہ) کو دلائل کے بجلی کے کوڑوں سے جلا کر راکھ کر دیا۔', '[{"word":"المِفْتَاحُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"طاغوت اسمها وهو مضاف"},{"word":"تَحْرِيفاً","role":"خبر كان منصوب","sign":"فتحة","detail":"باطلاً نعت له"}]', '["الصواعق المرسلة لابن القيم، 1/ 180-210، دار العاصمة."]', '{"en":"Ibn al-Qayyim''s ''Thunderbolts Unleashed'' (As-Sawa''iq al-Mursalah): Demolishing the idol of Corrupt Interpretation (Ta''wil Fasid). True early Ta''wil was synonym of Tafsir, whereas late theological Ta''wil diverting words from their manifest truth without proof constitutes illegitimate distortion (Tahrif).","ar":"بيان جناية التأويل الكلامي على نصوص الأسماء والصفات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('sawaiq_ch2_majaz', 'kharji_sawaiq_mursalah_jawziyyah', 1, 'كَسْرُ طَاغُوتِ المَجَازِ فِي نُصُوصِ العَقِيدَةِ وَالصِّفَاتِ', 'باب 2: صفاتِ باری تعالیٰ میں مجازی معنی گھڑنے کے باطل طاغوت کا رد');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('sawaiq_seg_2_1', 'sawaiq_ch2_majaz', 'kharji_sawaiq_mursalah_jawziyyah', 0, '«فَصْلٌ فِي كَسْرِ الطَّاغُوتِ الثَّانِي: وَهُوَ دَعْوَى أَنَّ فِي القُرْآنِ مَجَازاً يُجَوِّزُ نَفْيَ الحَقَائِقِ؛ فَإِنَّ أَهْلَ البَاطِلِ قَالُوا: نُصُوصُ الصِّفَاتِ مَجَازٌ لَا حَقِيقَةَ لَهَا، فَاليَدُ مَجَازٌ عَنِ القُوَّةِ، وَالغَضَبُ مَجَازٌ عَنِ انْتِقَامِ الإِرَادَةِ! فَرَدَّ عَلَيْهِمُ ابْنُ القَيِّمِ بِأَنَّ صِفَاتِ اللَّهِ تَعَالَى حَقَائِقُ لَا مَجَازَاتٍ؛ لِأَنَّ المَجَازَ يَصِحُّ نَفْيُهُ، وَلَا يَجُوزُ نَفْيُ صِفَاتِ الرَّبِّ سُبْحَانَهُ، وَلِأَنَّ اللَّهَ خَاطَبَنَا بِلِسَانٍ عَرَبِيٍّ مُبِينٍ حَقِيقِيٍّ يَقْتَضِي إِثْبَاتَ الكَمَالِ اللَّائِقِ بِجَلَالِهِ».', 'ابن قیم رحمہ اللہ فرماتے ہیں: ''دوسرے طاغوت کو توڑنے کا بیان: اور وہ یہ دعویٰ ہے کہ قرآن کی صفات میں ایسا مجاز ہے جو حقیقی معانی کی نفی کو جائز کر دیتا ہے؛ کیونکہ گمراہ فرقوں نے کہا: صفات کی نصوص مجاز ہیں ان کی کوئی حقیقی بنیاد نہیں، لہٰذا دستِ مبارک سے مراد طاقت ہے، اور غضب سے مراد انتقام کا ارادہ ہے! تو امام ابن قیم نے ان کا مدلل رد کرتے ہوئے فرمایا کہ اللہ تعالیٰ کی تمام صفات برحق حقائق ہیں، کوئی فرضی مجاز نہیں ہیں؛ کیونکہ مجاز کی یہ نشانی ہوتی ہے کہ اس کی نفی کرنا صحیح ہوتا ہے، جبکہ رب سبحانہ کی صفات کی نفی کرنا کسی مسلمان کے لیے جائز نہیں ہے، اور اس لیے کہ اللہ نے ہمیں واضح اور حقیقی عربی زبان میں خطاب فرمایا ہے جو اللہ کی ذات کے شایانِ شان صفاتِ کمال کے حقیقی اثبات کا تقاضا کرتی ہے''۔', 'اگر صفات کو استعارے اور مجاز پر محمول کر دیا جائے تو دین کے تمام بنیادی حقائق بے وزن ہو جائیں گے۔ ابن قیم نے ثابت کیا کہ رب کی صفات حقیقی ہیں۔', '[{"word":"حَقَائِقُ","role":"خبر إنّ مرفوع","sign":"ضمة","detail":"صفات اسمها"},{"word":"نَفْيُهُ","role":"فاعل يصح مرفوع","sign":"ضمة","detail":"والهاء مضاف إليه"}]', '["الصواعق المرسلة لابن القيم، 2/ 540-575."]', '{"en":"Demolishing the Second Idol: The abuse of Metaphor (Majaz) to strip divine attributes of reality—alleging Hands mean mere power and Wrath means intent of vengeance. Divine attributes are ontological realities matching divine grandeur.","ar":"نقض دعوى المجاز في صفات الباري وتأصيل كمال دلالة النصوص الشرعية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_minhaj_sunnah_taymiyyah', 'مِنْهَاجُ السُّنَّةِ النَّبَوِيَّةِ فِي نَقْضِ كَلَامِ الشِّيعَةِ وَالقَدَرِيَّةِ', 'شَيْخُ الإِسْلَامِ أَحْمَدُ بْنُ عَبْدِ الحَلِيمِ ابْنُ تَيْمِيَّةَ (ت: 728ھ)', 'kharji_kitab', 'aqaid', 'دفاعِ صحابہ، امامت اور اہل تشیع و قدریہ کا اصولی رد', 'کتبِ مطالعہ و دورۂ حدیث / تخصص', NULL, NULL, 'from-amber-950 via-stone-900 to-emerald-950', NULL, 'ابن مطہر حلی کی کتاب ''منہاج الکرامہ'' کے جواب میں لکھی گئی وہ تاریخی تصنیف جس نے تاریخ اور حدیث کے تمام مسودات کا عرق نکال دیا۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('minhaj_sunnah_ch1_khilafah', 'kharji_minhaj_sunnah_taymiyyah', 0, 'فَصْلٌ فِي تَرْتِيبِ الخِلَافَةِ الرَّاشِدَةِ وَأَفْضَلِيَّةِ الصِّدِّيقِ وَالفَارُوقِ', 'باب 1: خلافتِ راشدہ کی شرعی ترتیب اور حضرت ابوبکر و عمر رضی اللہ عنہما کی قطعی افضلیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('minhaj_sunnah_seg_1_1', 'minhaj_sunnah_ch1_khilafah', 'kharji_minhaj_sunnah_taymiyyah', 0, 'قَالَ شَيْخُ الإِسْلَامِ ابْنُ تَيْمِيَّةَ: «مِنْ أُصُولِ أَهْلِ السُّنَّةِ وَالجَمَاعَةِ: الإِقْرَارُ بِخِلَافَةِ الخُلَفَاءِ الرَّاشِدِينَ عَلَى التَّرْتِيبِ الَّذِي وَقَعَ فِي الوُجُودِ: أَبِي بَكْرٍ، ثُمَّ عُمَرَ، ثُمَّ عُثْمَانَ، ثُمَّ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُمْ. وَمَنْ طَعَنَ فِي خِلَافَةِ أَحَدٍ مِنْ هَؤُلَاءِ فَهُوَ أَضَلُّ مِنْ حِمَارِ أَهْلِهِ! وَأَفْضَلُ هَذِهِ الأُمَّةِ بَعْدَ نَبِيِّهَا: أَبُو بَكْرٍ ثُمَّ عُمَرُ بِإِجْمَاعِ الصَّحَابَةِ؛ فَقَدْ تَوَاتَرَ عَنْ أَمِيرِ المُؤْمِنِينَ عَلِيِّ بْنِ أَبِي طَالِبٍ أَنَّهُ قَالَ عَلَى مِنْبَرِ الكُوفَةِ: «خَيْرُ هَذِهِ الأُمَّةِ بَعْدَ نَبِيِّهَا أَبُو بَكْرٍ ثُمَّ عُمَرُ» رَوَاهُ عَنْهُ أَكْثَرُ مِنْ ثَمَانِينَ نَفْساً».', 'شیخ الاسلام ابن تیمیہ رحمہ اللہ فرماتے ہیں: ''اہل سنت والجماعت کے بنیادی اصولوں میں سے یہ ہے کہ خلفائے راشدین کی خلافت کا اسی ترتیب پر اقرار کیا جائے جس ترتیب پر وہ عملاً واقع ہوئی: یعنی پہلے حضرت ابوبکر، پھر حضرت عمر، پھر حضرت عثمان، اور پھر حضرت علی رضی اللہ عنہم اجمعین۔ اور جس شخص نے ان میں سے کسی کی خلافت پر بھی انگلی اٹھائی وہ اپنے گھر کے گدھے سے بھی زیادہ گمراہ ہے! اور اس امت کے سب سے افضل ترین انسان رسول اللہ ﷺ کے بعد حضرت ابوبکر ہیں اور پھر حضرت عمر ہیں صحابہ کے اجماع کے ساتھ؛ کیونکہ خود امیر المؤمنین حضرت علی بن ابی طالب رضی اللہ عنہ سے تواتر کے ساتھ یہ ثابت ہے کہ انہوں نے کوفہ کے منبر پر کھڑے ہو کر باآوازِ بلند فرمایا: ''اس امت میں اس کے نبی کے بعد سب سے بہترین انسان ابوبکر ہیں اور پھر عمر ہیں''، یہ روایت حضرت علی سے اسی سے زائد راویوں نے بسندِ صحیح نقل کی ہے''۔', 'منهاج السنة النبوية علامہ ابن مطہر حلی کی کتاب کے رد میں لکھی گئی وہ عظیم تصنیف ہے جس نے صحابہ کے مقام، خلافت کے شرعی احکام اور رافضیت کے شکوک کا قطعی علمی ابطال کیا۔', '[{"word":"الإِقْرَارُ","role":"مبتدأ مؤخر مرفوع","sign":"ضمة","detail":"من أصول شبه جملة خبر مقدم"},{"word":"أَضَلُّ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"اسم تفضيل"}]', '["منهاج السنة النبوية لابن تيمية، 1/ 130-150، بتحقيق محمد رشاد سالم."]', '{"en":"Ibn Taymiyyah''s encyclopedia ''Minhaj as-Sunnah an-Nabawiyyah'': Affirming the legitimate chronological succession of the Rightly Guided Caliphs: Abu Bakr, ''Umar, ''Uthman, and ''Ali. Citing the mass-transmitted declaration of ''Ali on the pulpit of Kufa that Abu Bakr and ''Umar are the best of this nation.","ar":"تقرير عدالة الصحابة وترتيب الخلفاء الراشدين في الفضل والخلافة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('minhaj_sunnah_ch2_sahabah', 'kharji_minhaj_sunnah_taymiyyah', 1, 'فَضْلُ الصَّحَابَةِ جَمِيعاً وَعَدَالَتُهُمْ وَالكَتْمُ عَمَّا شَجَرَ بَيْنَهُمْ', 'باب 2: تمام صحابہ کرام کی عدالت اور ان کے باہمی مشاجرات میں زبان بند رکھنے کا شرعی فریضہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('minhaj_sunnah_seg_2_1', 'minhaj_sunnah_ch2_sahabah', 'kharji_minhaj_sunnah_taymiyyah', 0, '«وَيُمْسِكُ أَهْلُ السُّنَّةِ عَمَّا شَجَرَ بَيْنَ الصَّحَابَةِ؛ وَيَعْلَمُونَ أَنَّ مَا نُقِلَ فِيهِمْ مِنْ مَسَاوِئَ كَثِيرٌ مِنْهُ كَذِبٌ مُخْتَلَقٌ، وَمَا كَانَ مِنْهُ صَحِيحاً فَهُمْ فِيهِ مَعْذُورُونَ: إِمَّا مُجْتَهِدُونَ أَصَابُوا فَلَهُمْ أَجْرَانِ، وَإِمَّا مُجْتَهِدُونَ أَخْطَئُوا فَلَهُمْ أَجْرٌ وَاحِدٌ وَخَطَؤُهُمْ مَغْفُورٌ؛ وَلَهُمْ مِنَ السَّوَابِقِ وَالفَضَائِلِ مَا يُكَفِّرُ مَا عَسَى أَنْ يَكُونَ صَدَرَ مِنْهُمْ. وَقَدْ قَالَ ﷺ: «لَا تَسُبُّوا أَصْحَابِي؛ فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ أَحَدَكُمْ أَنْفَقَ مِثْلَ أُحُدٍ ذَهَباً مَا أَدْرَكَ مُدَّ أَحَدِهِمْ وَلَا نَصِيفَهُ!».', 'شیخ الاسلام فرماتے ہیں: ''اور اہل سنت والجماعت صحابہ کرام کے باہمی مشاجرات اور اختلافات پر اپنی زبانیں بند رکھتے ہیں؛ اور وہ جانتے ہیں کہ صحابہ کے بارے میں جو برائیاں اور روایات نقل کی گئی ہیں ان میں سے کثیر جھوٹی اور گھڑی ہوئی ہیں، اور جو روایات صحیح سند سے ہیں ان میں وہ معذور اور صاحبِ اجتہاد تھے: یا تو وہ مجتہد تھے جنہوں نے درست فیصلہ کیا تو ان کے لیے دہرا اجر ہے، اور یا وہ مجتہد تھے جن سے خطا ہوئی تو ان کے لیے اجتہاد کا ایک اجر ہے اور ان کی خطا معاف ہے؛ اور ان کے پاس اسلام کی اولین قربانیاں، جہاد اور ایسی فضیلتیں ہیں جو ان کی تمام لغزشوں کو مٹا دینے کے لیے کافی ہیں۔ اور رسول اللہ ﷺ نے فرمایا: ''میرے صحابہ کو گالی مت دو! قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! اگر تم میں سے کوئی احد پہاڑ کے برابر بھی سونا خیرات کر دے تو وہ ان کے ایک سیر یا آدھے سیر جو کے صدقے کے برابر بھی نہیں پہنچ سکتا!''', 'صحابہ پر انگلی اٹھانا دراصل رسول اللہ ﷺ کی تربیت پر حملہ ہے۔ اہل سنت کا راستہ دل کی سلامتی اور زبان کا ادب ہے۔', '[{"word":"مُجْتَهِدُونَ","role":"خبر لمبتدأ محذوف هم مرفوع بالواو","sign":"واو","detail":"تفصيل لمعذورون"},{"word":"مُدَّ","role":"مفعول به لأدرك منصوب","sign":"فتحة","detail":"وهو مضاف وأحدهم مضاف إليه"}]', '["منهاج السنة النبوية، 6/ 200-225، وأخرجه البخاري (3673)."]', '{"en":"Withholding from Companions'' disputes: Most disparaging accounts are fabricated; verified incidents stem from bona fide Ijtihad where they earn either two rewards or one, their vast virtues obliterating shortcomings. ''Do not curse my Companions...''","ar":"كف اللسان عما جرى بين الصحابة وحفظ سابقتهم العظيمة في نصرة الدين."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_darr_taarud_taymiyyah', 'دَرْءُ تَعَارُضِ العَقْلِ وَالنَّقْلِ', 'شَيْخُ الإِسْلَامِ أَحْمَدُ بْنُ عَبْدِ الحَلِيمِ ابْنُ تَيْمِيَّةَ (ت: 728ھ)', 'kharji_kitab', 'aqaid', 'عقلِ صریح اور نقلِ صحیح میں کامل موافقت', 'کتبِ مطالعہ و فلسفۂ اسلامی و کلام', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'فخر الدین رازی کے ''قانونِ کلی'' کا ابطال اور یہ ثابت کرنا کہ عقلِ سلیم کبھی بھی صحیح ثابت شدہ وحی سے متصادم نہیں ہو سکتی۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('darr_taarud_ch1_aql_naql', 'kharji_darr_taarud_taymiyyah', 0, 'القَاعِدَةُ الكُلِّيَّةُ فِي تَقْدِيمِ النَّقْلِ الصَّحِيحِ عَلَى العَقْلِ الصَّرِيحِ وَاسْتِحَالَةِ تَعَارُضِهِمَا', 'باب 1: عقلِ صریح اور نقلِ صحیح کا باہمی ربط — عقل اور وحی میں کبھی حقیقی تضاد نہیں ہو سکتا');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('darr_taarud_seg_1_1', 'darr_taarud_ch1_aql_naql', 'kharji_darr_taarud_taymiyyah', 0, 'قَالَ شَيْخُ الإِسْلَامِ ابْنُ تَيْمِيَّةَ: «إِنَّ العَقْلَ الصَّرِيحَ لَا يُعَارِضُ النَّقْلَ الصَّحِيحَ أَبَداً؛ فَمَا عُلِمَ بِالعَقْلِ الصَّرِيحِ لَا يُمْكِنُ أَنْ يُنَاقِضَهُ نَقْلٌ صَحِيحٌ ثَابِتٌ عَنِ الرَّسُولِ ﷺ. وَإِذَا وَقَعَ فِي الظَّاهِرِ تَعَارُضٌ فَلَا يَخْلُو مِنْ أَمْرَيْنِ: إِمَّا أَنْ يَكُونَ النَّقْلُ غَيْرَ صَحِيحٍ (ضَعِيفاً أَوْ مَوْضُوعاً)، وَإِمَّا أَنْ يَكُونَ العَقْلُ غَيْرَ صَرِيحٍ (شُبْهَةً وَوَهْماً سُمِّيَتْ عَقْلاً وَلَيْسَتْ بِعَقْلٍ). وَأَمَّا إِذَا تَحَقَّقَ صَرِيحُ العَقْلِ وَصَحِيحُ النَّقْلِ فَإِنَّهُمَا يَتَصَادَقَانِ وَيَتَطَابَقَانِ؛ لِأَنَّ خَالِقَ العَقْلِ هُوَ مُنَزِّلُ الشَّرْعِ سُبْحَانَهُ».', 'شیخ الاسلام ابن تیمیہ رحمہ اللہ فرماتے ہیں: ''بے شک خالص اور سچی عقل (عقلِ صریح) رسول اللہ ﷺ سے ثابت شدہ صحیح روایت (نقلِ صحیح) کے کبھی بھی متصادم نہیں ہو سکتی؛ کیونکہ جو بات عقلِ سلیم سے قطعی طور پر معلوم ہو ناممکن ہے کہ رسول اللہ ﷺ کی کوئی سچی حدیث اس کے متضاد ہو۔ اور اگر بظاہر کبھی کوئی تضاد نظر آئے تو وہ دو باتوں سے خالی نہیں ہو سکتا: یا تو وہ حدیث ہی من گھڑت یا ضعیف ہوگی، اور یا پھر وہ عقل عقل نہیں ہوگی بلکہ کوئی وہم، فکری شبہ اور مغالطہ ہوگا جسے جہالت سے عقل کا نام دے دیا گیا ہوگا! لیکن جب سچی عقل اور صحیح حدیث دونوں سامنے ہوں تو وہ ہمیشہ ایک دوسرے کی تصدیق اور تائید کرتی ہیں؛ کیونکہ جس پروردگار نے انسان کے اندر عقل بنائی ہے اسی پروردگار نے آسمان سے شریعت نازل فرمائی ہے''۔', 'درء تعارض العقل والنقل (11 جلدیں) انسانی فکر کی تاریخ کی سب سے عظیم فلسفیانہ کتاب ہے جس کے بارے میں علامہ ابن قیم نے فرمایا کہ دنیا میں ایسی کتاب نہ پہلے لکھی گئی نہ بعد میں لکھی جا سکی۔', '[{"word":"أَبَداً","role":"ظرف زمان منصوب","sign":"فتحة","detail":"يفيد استمرار النفي"},{"word":"مُنَزِّلُ","role":"خبر المبتدأ هو مرفوع","sign":"ضمة","detail":"وهو مضاف والشرع مضاف إليه"}]', '["درء تعارض العقل والنقل لابن تيمية، 1/ 78-95، بتحقيق د. محمد رشاد سالم."]', '{"en":"Ibn Taymiyyah''s philosophical magnum opus ''Dar'' Ta''arud al-''Aql wan-Naql'' (Averting the Conflict of Reason and Revelation): Sound unambiguous reason never clashes with verified authentic revelation. Any apparent contradiction stems from spurious narrations or corrupted syllogisms mistaken for reason.","ar":"إثبات التوافق التام والانسجام المطلق بين العقل الفطري والوحي الإلهي."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('darr_taarud_ch2_qanun_kulli', 'kharji_darr_taarud_taymiyyah', 1, 'إِبْطَالُ القَانُونِ الكُلِّيِّ لِلْمُتَكَلِّمِينَ فِي تَقْدِيمِ العَقْلِ عَلَى النَّصِّ', 'باب 2: متکلمین کے خود ساختہ قانونِ کلی (عقل کو نص پر مقدم کرنا) کا زبردست منطقی ابطال');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('darr_taarud_seg_2_1', 'darr_taarud_ch2_qanun_kulli', 'kharji_darr_taarud_taymiyyah', 0, '«أَبْطَلَ شَيْخُ الإِسْلَامِ قَانُونَ أَهْلِ الكَلَامِ الَّذِينَ قَالُوا: «إِذَا تَعَارَضَ العَقْلُ وَالنَّقْلُ قَدَّمْنَا العَقْلَ؛ لِأَنَّ العَقْلَ هُوَ أَصْلُ النَّقْلِ!». فَقَالَ ابْنُ تَيْمِيَّةَ: هَذَا بَاطِلٌ مِنْ أَرْبَعِينَ وَجْهاً؛ أَبْرَزُهَا: أَنَّ تَقْدِيمَ العَقْلِ عَلَى النَّقْلِ يَقْدَحُ فِي العَقْلِ نَفْسِهِ؛ لِأَنَّ العَقْلَ هُوَ الَّذِي شَهِدَ بِصِدْقِ الرَّسُولِ ﷺ وَوُجُوبِ طَاعَتِهِ، فَإِذَا كَذَّبْنَا الرَّسُولَ بِحُجَّةِ العَقْلِ كُنَّا قَدْ كَذَّبْنَا شَاهِدَ العَقْلِ، فَإِذَا بَطَلَتْ شَهَادَتُهُ بَطَلَ العَقْلُ وَالنَّقْلُ جَمِيعاً! فَكَانَ الوَاجِبُ تَقْدِيمَ كَلَامِ المَعْصُومِ».', 'ابن تیمیہ رحمہ اللہ نے متکلمین اور فلاسفہ کے اس قاعدے کو پاش پاش کیا جنہوں نے یہ قانون بنایا تھا کہ: ''جب عقل اور نقل میں ٹکراؤ ہو تو ہم عقل کو آگے رکھیں گے کیونکہ عقل ہی نقل کی بنیاد ہے!''۔ شیخ الاسلام نے فرمایا: یہ قاعدہ چالیس مختلف طریقوں سے باطل ہے جن میں سب سے روشن دلیل یہ ہے: کہ عقل کو وحی پر مقدم کرنا خود عقل کو جھوٹا ثابت کر دیتا ہے؛ کیونکہ یہ عقل ہی تو تھی جس نے معجزات دیکھ کر گواہی دی تھی کہ رسول اللہ ﷺ سچے ہیں اور ان کی بات ماننا فرض ہے، پس اگر ہم عقل کے نام پر رسول کی بات کو جھٹلا دیں تو ہم نے خود عقل کی گواہی کو جھوٹا قرار دے دیا، اور جب عقل کی اپنی گواہی باطل ہو گئی تو عقل اور نقل دونوں بیک وقت برباد ہو گئے! لہٰذا عقل کا تقاضا یہ ہے کہ معصوم نبی کے کلام کو اپنی ناقص عقل پر مقدم رکھا جائے''۔', 'یہ وہ زبردست منطقی اور فلسفیانہ استدلال ہے جس نے رازی اور فلاسفہ کے کلامی نظام کو جڑ سے ہلا دیا اور وحی کی برتری کا پرچم لہرایا۔', '[{"word":"بَاطِلٌ","role":"خبر المبتدأ هذا مرفوع","sign":"ضمة","detail":"هذا مبتدأ وباطل خبره"},{"word":"شَاهِدَ","role":"مفعول به لكذبنا منصوب","sign":"فتحة","detail":"وهو مضاف والعقل مضاف إليه"}]', '["درء تعارض العقل والنقل، 1/ 135-160."]', '{"en":"Refuting the theologians'' ''Universal Law'' of prioritizing reason over scripture: Prioritizing reason actually invalidates reason itself, because reason is the very witness that verified the Prophet''s truthfulness. If you reject the Prophet via reason, you impeach your own witness.","ar":"النقض المنطقي الباهر لدعوى تقديم العقل على النقل عند المتكلمين."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_haqiqat_iman_salafi', 'حَقِيقَةُ الإِيمَانِ بَيْنَ الغُلُوِّ وَالتَّقْصِيرِ', 'نُخْبَةٌ مِنْ عُلَمَاءِ العَقِيدَةِ وَالتَّحْقِيقِ', 'kharji_kitab', 'aqaid', 'حقیقتِ ایمان، ارکانِ ایمان اور تکفیر کے خطرات', 'کتبِ مطالعہ و عصرِ حاضر کے فکری مسائل', NULL, NULL, 'from-emerald-950 via-stone-900 to-amber-950', NULL, 'خوارج کی بے جا تکفیر اور مرجئہ کی عمل سے بے پرواہی کے درمیان اسلام کا معتدل عقیدۂ ایمان۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('haqiqat_iman_ch1_arkaan', 'kharji_haqiqat_iman_salafi', 0, 'حَقِيقَةُ الإِيمَانِ عِنْدَ أَهْلِ السُّنَّةِ: قَوْلٌ وَعَمَلٌ وَاعْتِقَادٌ يَزِيدُ وَيَنْقُصُ', 'باب 1: ایمان کی حقیقت — دل کا یقین، زبان کا اقرار اور اعضاء کا عمل، جو نیکی سے بڑھتا اور گناہ سے گھٹتا ہے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('haqiqat_iman_seg_1_1', 'haqiqat_iman_ch1_arkaan', 'kharji_haqiqat_iman_salafi', 0, 'أَجْمَعَ أَئِمَّةُ السَّلَفِ وَأَهْلُ الحَدِيثِ عَلَى أَنَّ الإِيمَانَ: «قَوْلٌ بِاللِّسَانِ، وَاعْتِقَادٌ بِالجَنَانِ، وَعَمَلٌ بِالأَرْكَانِ؛ يَزِيدُ بِطَاعَةِ الرَّحْمَنِ، وَيَنْقُصُ بِطَاعَةِ الشَّيْطَانِ». قَالَ اللَّهُ تَعَالَى: {لِيَزْدَادُوا إِيمَاناً مَعَ إِيمَانِهِمْ}، وَقَالَ تَعَالَى: {وَإِذَا مَا أُنْزِلَتْ سُورَةٌ فَمِنْهُمْ مَنْ يَقُولُ أَيُّكُمْ زَادَتْهُ هَذِهِ إِيمَاناً}. وَرَدَّ أَهْلُ السُّنَّةِ عَلَى المُرْجِئَةِ الَّذِينَ أَخْرَجُوا العَمَلَ عَنْ مُسَمَّى الإِيمَانِ وَزَعَمُوا أَنَّ الإِيمَانَ مُجَرَّدُ المَعْرِفَةِ، وَعَلَى الخَوَارِجِ الَّذِينَ كَفَّرُوا بِالمَعَاصِي دُونَ الشِّرْكِ».', 'ائمۂ سلف اور اہل سنت والجماعت کا اس پر اجماع ہے کہ ایمان کی تعریف یہ ہے: ''زبان سے اقرار کرنا، دل سے سچا یقین رکھنا، اور جسمانی اعضاء سے نیک اعمال کرنا؛ یہ ایمان رحمان کی اطاعت سے بڑھتا ہے اور شیطان کی نافرمانی اور گناہوں سے گھٹتا ہے''۔ اللہ تعالیٰ کا فرمان ہے: {تاکہ وہ اپنے ایمان کے ساتھ ایمان میں اور زیادہ بڑھ جائیں}، اور فرمایا: {اور جب کوئی سورت نازل ہوتی ہے تو منافقین کہتے ہیں کہ تم میں سے کس کے ایمان کو اس سورت نے بڑھایا؟}۔ اور اہل سنت نے ان مرجئہ کا بطلان کیا جنہوں نے اعمال کو ایمان سے نکال باہر کیا اور دعویٰ کیا کہ ایمان محض دل کی تصدیق کا نام ہے اور عمل کی کوئی ضرورت نہیں، اور ان خوارج کا بھی رد کیا جنہوں نے شرک کے علاوہ عام گناہوں کی وجہ سے مسلمانوں کو کافر قرار دے دیا''۔', 'حقيقة الإيمان علمائے عقیدہ کی وہ مستند تحقیق ہے جس نے اسلام میں ایمان کی حقیقت کو واضح کیا تاکہ لوگ نہ تو مرجئہ کی طرح بے عمل ہو جائیں اور نہ خوارج کی طرح مسلمانوں کی تکفیر کریں۔', '[{"word":"قَوْلٌ","role":"خبر المبتدأ الإيمان مرفوع","sign":"ضمة","detail":"اعتقاد وعمل معطوفان عليه"},{"word":"إِيمَاناً","role":"مفعول به ليزدادوا منصوب","sign":"فتحة","detail":"أو تمييز"}]', '["حقيقة الإيمان بين الغلو والتقصير، ص 15-28، وكتاب الإيمان لابن تيمية."]', '{"en":"The Core of Faith (Iman) in Orthodox Sunnism: Comprising belief in the heart, verbal confession on the tongue, and physical righteous deeds with bodily limbs—increasing with obedience and decreasing with sin, rejecting both Murji''ite laxity and Kharijite extremism.","ar":"تعريف الإيمان الشرعي والرد على طرفي الغلو والإرجاء."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('haqiqat_iman_ch2_shuab', 'kharji_haqiqat_iman_salafi', 1, 'شُعَبُ الإِيمَانِ البِضْعُ وَالسَّبْعُونَ وَأَصْلُ النَّجَاةِ', 'باب 2: ایمان کے ستر سے زائد شعبے — لا الہ الا اللہ سے لے کر راستے سے تکلیف دہ چیز ہٹانے تک');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('haqiqat_iman_seg_2_1', 'haqiqat_iman_ch2_shuab', 'kharji_haqiqat_iman_salafi', 0, '«عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «الإِيمَانُ بِضْعٌ وَسَبْعُونَ شُعْبَةً، فَأَفْضَلُهَا قَوْلُ: لَا إِلَهَ إِلَّا اللَّهُ، وَأَدْنَاهَا إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ، وَالحَيَاءُ شُعْبَةٌ مِنَ الإِيمَانِ». فَدَلَّ هَذَا الحَدِيثُ الجَلِيلُ عَلَى أَنَّ الإِيمَانَ ذُو أَصْلٍ وَفُرُوعٍ؛ فَأَصْلُهُ قَوْلُ التَّوْحِيدِ الَّذِي إِذَا زَالَ زَالَ الإِيمَانُ كُلُّهُ، وَفُرُوعُهُ كَإِمَاطَةِ الأَذَى وَالحَيَاءِ الَّتِي يَنْقُصُ الإِيمَانُ بِنَقْصِهَا وَلَا يَزُولُ أَصْلُهُ، وَفِي هَذَا أَعْظَمُ حُجَّةٍ عَلَى أَنَّ الإِيمَانَ يَتَبَعَّضُ وَيَتَفَاوَتُ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''ایمان کے ستر سے کچھ اوپر شعبے اور شاخیں ہیں، پس ان میں سب سے افضل اور اعلیٰ شعبہ ''لا الہ الا اللہ'' کا اقرار ہے، اور اس کا سب سے ادنیٰ شعبہ راستے سے کسی تکلیف دہ چیز (پتھر یا کانٹے) کو ہٹا دینا ہے، اور حیا بھی ایمان کا ایک عظیم الشان شعبہ ہے''۔ پس اس جلیل القدر حدیث نے یہ ثابت کر دیا کہ ایمان ایک تناور درخت کی طرح ہے جس کی ایک جڑ ہے اور بہت سی شاخیں ہیں؛ پس اس کی جڑ کلمۂ توحید ہے کہ اگر وہ جڑ کٹ جائے تو پورا ایمان ختم ہو جاتا ہے، اور اس کی شاخیں حیا اور راستے سے تکلیف ہٹانے جیسے اخلاق ہیں جن کے چھوٹنے سے ایمان کامل نہیں رہتا مگر اس کی جڑ ختم نہیں ہوتی، اور اس میں اس بات کی سب سے بڑی دلیل ہے کہ ایمان کے درجات مختلف اور کم و بیش ہوتے ہیں''۔', 'ایمان کو درخت کی تمثیل سے سمجھنا سب سے آسان ہے۔ ہر پتے کے جھڑنے سے درخت نہیں مرتا لیکن جڑ کے کٹنے سے درخت گر جاتا ہے۔', '[{"word":"بِضْعٌ","role":"خبر المبتدأ الإيمان مرفوع","sign":"ضمة","detail":"وسبعون معطوف عليه"},{"word":"إِمَاطَةُ","role":"خبر المبتدأ أدناها مرفوع","sign":"ضمة","detail":"الأذى مضاف إليه"}]', '["أخرجه مسلم (35)، وشعب الإيمان للبيهقي."]', '{"en":"The Branches of Faith: ''Iman has over seventy branches: the highest is the declaration ''There is no god but Allah'', the lowest is removing harm from the pathway, and modesty (Haya'') is a branch of faith.'' Proving that faith possesses a core root alongside varied branches.","ar":"بيان مراتب شعب الإيمان وتفاضل الأعمال الإيمانية."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_fiqh_akbar_abu_hanifah', 'الفِقْهُ الأَكْبَرُ', 'الإِمَامُ الأَعْظَمُ أَبُو حَنِيفَةَ النُّعْمَانُ بْنُ ثَابِتٍ الكُوفِيُّ (ت: 150ھ)', 'kharji_kitab', 'aqaid', 'امامِ اعظم ابو حنیفہ کا رسالۂ عقائد و توحید', 'کتبِ مطالعہ و اولین متنِ عقیدہ', NULL, NULL, 'from-teal-950 via-stone-900 to-emerald-950', NULL, 'فقہِ اصغر (احکام) سے پہلے فقہِ اکبر (عقائد و توحید)۔ امام ابو حنیفہ کا مبارک رسالہ جس کی بنیاد پر امت کی دینی عمارت استوار ہوئی۔', 2, 2);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('fiqh_akbar_ch1_asl', 'kharji_fiqh_akbar_abu_hanifah', 0, 'أَصْلُ التَّوْحِيدِ عِنْدَ الإِمَامِ الأَعْظَمِ أَبِي حَنِيفَةَ النُّعْمَانِ', 'باب 1: امام اعظم ابو حنیفہ کا بنیادی عقیدہ — الفقه الاکبر اور صفاتِ باری تعالیٰ کا اثبات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('fiqh_akbar_seg_1_1', 'fiqh_akbar_ch1_asl', 'kharji_fiqh_akbar_abu_hanifah', 0, 'قَالَ الإِمَامُ الأَعْظَمُ أَبُو حَنِيفَةَ النُّعْمَانُ بْنُ ثَابِتٍ الكُوفِيُّ رَحِمَهُ اللَّهُ: «أَصْلُ التَّوْحِيدِ وَمَا يَصِحُّ الِاعْتِقَادُ عَلَيْهِ: نَقُولُ آمَنَّا بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالبَعْثِ بَعْدَ المَوْتِ، وَالقَدَرِ خَيْرِهِ وَشَرِّهِ مِنَ اللَّهِ تَعَالَى. وَاللَّهُ تَعَالَى وَاحِدٌ لَا مِنْ طَرِيقِ العَدَدِ، وَلَكِنْ مِنْ طَرِيقِ أَنَّهُ لَا شَرِيكَ لَهُ، {قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ}. لَا يُشْبِهُ شَيْئاً مِنْ خَلْقِهِ، وَلَا يُشْبِهُهُ شَيْءٌ مِنْ خَلْقِهِ، لَمْ يَزَلْ وَلَا يَزَالُ بِأَسْمَائِهِ وَصِفَاتِهِ الذَّاتِيَّةِ وَالفِعْلِيَّةِ».', 'امام اعظم ابو حنیفہ نعمان بن ثابت کوفی رحمہ اللہ فرماتے ہیں: ''توحید کی اصل بنیاد اور وہ عقیدہ جس پر ایمان صحیح ہوتا ہے یہ ہے: ہم دل کی گہرائیوں سے اقرار کرتے ہیں کہ ہم اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر، اس کے تمام رسولوں پر، مرنے کے بعد دوبارہ جی اٹھنے پر، اور تقدیر کی اچھائی اور برائی کے منجانب اللہ ہونے پر ایمان لائے۔ اور اللہ تعالیٰ ایک ہے عددی گنتی کے اعتبار سے نہیں، بلکہ اس اعتبار سے کہ اس کا کوئی شریک اور ساجھی نہیں، {آپ فرما دیجیے کہ وہ اللہ ایک ہے، اللہ بے نیاز ہے، نہ اس کی کوئی اولاد ہے نہ وہ کسی سے پیدا ہوا، اور نہ کوئی اس کا ہمسر ہے}۔ وہ اپنی مخلوق میں سے کسی چیز کے مشابہ نہیں، اور نہ اس کی مخلوق میں سے کوئی چیز اس کے مشابہ ہے، وہ ہمیشہ سے اپنے تمام اسماء اور صفاتِ ذاتیہ و فعلیہ کے ساتھ متصف تھا اور ہمیشہ رہے گا''۔', 'الفقه الأكبر امام اعظم ابو حنیفہ (متوفی 150ھ) کی وہ تاریخی کتاب ہے جو اہل سنت کے عقائد کا اولین مدون متن ہے۔ امام صاحب نے علمِ عقائد کو ''فقہ اکبر'' (سب سے بڑی فقہ) قرار دیا۔', '[{"word":"وَاحِدٌ","role":"خبر المبتدأ لفظ الجلالة مرفوع","sign":"ضمة","detail":"لا من طريق العدد نفي للتركيب"},{"word":"كُفُواً","role":"خبر يكن مقدم منصوب","sign":"فتحة","detail":"أحد اسم يكن مؤخر"}]', '["الفقه الأكبر للإمام أبي حنيفة بشرح علي القاري، ص 15-30."]', '{"en":"Imam al-A''zam Abu Hanifah''s foundational creed ''Al-Fiqh al-Akbar'': ''The root of Monotheism is that we believe in Allah, His angels, His books, His messengers, resurrection, and predestination. Allah is One—not numerically, but in that He has no partner. He resembles nothing of His creation, and nothing of creation resembles Him.''","ar":"العقيدة المعتمدة للإمام أبي حنيفة وإثبات صفات الذات والفعل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('fiqh_akbar_ch2_dhanb', 'kharji_fiqh_akbar_abu_hanifah', 1, 'عَدَمُ تَكْفِيرِ أَهْلِ القِبْلَةِ بِالذُّنُوبِ مَا لَمْ يَسْتَحِلُّوهَا', 'باب 2: اہل قبلہ کی تکفیر کی ممانعت — گناہ گار مومن دائرۂ اسلام سے خارج نہیں ہوتا جب تک کہ گناہ کو حلال نہ سمجھے');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('fiqh_akbar_seg_2_1', 'fiqh_akbar_ch2_dhanb', 'kharji_fiqh_akbar_abu_hanifah', 0, '«قَالَ الإِمَامُ أَبُو حَنِيفَةَ: «وَلَا نُكَفِّرُ أَحَداً مِنْ أَهْلِ القِبْلَةِ بِذَنْبٍ مِنْ ذُنُوبِ الكَبَائِرِ مَا لَمْ يَسْتَحِلَّهُ، وَلَا نُزِيلُ عَنْهُ اسْمَ الإِيمَانِ، وَنُسَمِّيهِ مُؤْمِناً عَاصِياً غَيْرَ كَافِرٍ. وَأَمْرُهُ إِلَى اللَّهِ تَعَالَى: إِنْ شَاءَ عَذَّبَهُ بِعَدْلِهِ، وَإِنْ شَاءَ غَفَرَ لَهُ بِفَضْلِهِ؛ كَمَا قَالَ تَعَالَى: {إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ}. وَلَا نَقُولُ: لَا تَضُرُّ مَعَ الإِيمَانِ سَيِّئَةٌ كَمَا تَقُولُ المُرْجِئَةُ، بَلْ نَرْجُو لِلْمُحْسِنِ وَنَخَافُ عَلَى المُسِيءِ».', 'امام اعظم ابو حنیفہ رحمہ اللہ فرماتے ہیں: ''اور ہم کسی بھی کلمہ گو اہل قبلہ کو کسی بھی کبیرہ گناہ کی وجہ سے کافر قرار نہیں دیتے جب تک کہ وہ اس گناہ کو حلال نہ سمجھے، اور نہ ہی ہم اس سے ایمان کا نام چھینتے ہیں، بلکہ ہم اسے گناہ گار مومن کہتے ہیں کافر نہیں کہتے۔ اور اس کا معاملہ اللہ کے سپرد ہے: اگر اللہ چاہے تو اپنے عدل سے اسے گناہوں کی سزا دے، اور اگر چاہے تو اپنے فضل و رحمت سے اسے معاف فرما دے؛ جیسا کہ اللہ کا فرمان ہے: {بے شک اللہ اس بات کو معاف نہیں کرتا کہ اس کے ساتھ شرک کیا جائے اور شرک کے علاوہ باقی تمام گناہ جس کے لیے چاہے معاف فرما دیتا ہے}۔ اور ہم مرجئہ کی طرح یہ بے ہودہ بات بھی نہیں کہتے کہ ایمان کے ہوتے ہوئے گناہ کوئی نقصان نہیں پہنچاتا، بلکہ ہم نیکوکاروں کے لیے رحمت کی امید رکھتے ہیں اور گناہ گاروں پر اللہ کے عذاب سے ڈرتے ہیں''۔', 'یہ فقہ حنفی اور اہل سنت کا وہ سنہری اصول ہے جس نے امت کے خون کی حفاظت کی اور خوارج کے تکفیری فتنوں سے مسلمانوں کو بچایا۔ گناہ سے انسان فاسق ہوتا ہے، کافر نہیں۔', '[{"word":"أَحَداً","role":"مفعول به لنكفر منصوب","sign":"فتحة","detail":"نكفر فعل مضارع والفاعل مستتر تقديره نحن"},{"word":"مُؤْمِناً","role":"مفعول به ثان لنسَمِّيه منصوب","sign":"فتحة","detail":"عاصياً نعت له"}]', '["الفقه الأكبر للإمام أبي حنيفة، ص 45-60."]', '{"en":"The Hanafi Gold Standard on Takfir: ''We do not declare any Muslim an infidel due to a major sin so long as he does not deem it lawful; we call him a disobedient believer, not a disbeliever. His fate rests with Allah—He may punish via justice or pardon via grace ({Allah forgives not that partners be set up with Him, but forgives anything else to whom He wills}).''","ar":"قاعدة أهل السنة الكبرى في عصمة دماء المسلمين والنهي عن تكفير أهل القبلة."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0108', 'جامع البيان عن تأويل آي القرآن', 'الإمام محمد بن جرير الطبري (ت: 310ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'أعظم تفاسير أهل السنة بالأثر واللغة والتوجيه الفقهي.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0108_ch1', 'kharji_lib_0108', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0108_seg_1', 'kharji_lib_0108_ch1', 'kharji_lib_0108', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''جامع البيان عن تأويل آي القرآن'' by الإمام محمد بن جرير الطبري (ت: 310ھ).","ar":"نص مختار من كتاب جامع البيان عن تأويل آي القرآن للإمام الإمام محمد بن جرير الطبري (ت: 310ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0109', 'تأويلات أهل السنة (تفسير الماتريدي)', 'الإمام أبو منصور الماتريدي الحنفي (ت: 333ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'من عيون تفاسير أهل السنة والجماعة على مذهب الإمام أبي حنيفة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0109_ch1', 'kharji_lib_0109', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0109_seg_1', 'kharji_lib_0109_ch1', 'kharji_lib_0109', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''تأويلات أهل السنة (تفسير الماتريدي)'' by الإمام أبو منصور الماتريدي الحنفي (ت: 333ھ).","ar":"نص مختار من كتاب تأويلات أهل السنة (تفسير الماتريدي) للإمام الإمام أبو منصور الماتريدي الحنفي (ت: 333ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0110', 'بحر العلوم (تفسير السمرقندي)', 'الإمام أبو الليث نصر بن محمد السمرقندي الحنفي (ت: 373ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'تفسير حنفي أصيل يجمع بين الأثر والفقه ولطائف الموعظة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0110_ch1', 'kharji_lib_0110', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0110_seg_1', 'kharji_lib_0110_ch1', 'kharji_lib_0110', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''بحر العلوم (تفسير السمرقندي)'' by الإمام أبو الليث نصر بن محمد السمرقندي الحنفي (ت: 373ھ).","ar":"نص مختار من كتاب بحر العلوم (تفسير السمرقندي) للإمام الإمام أبو الليث نصر بن محمد السمرقندي الحنفي (ت: 373ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0111', 'الكشف والبيان عن تفسير القرآن (تفسير الثعلبي)', 'الإمام أبو إسحاق أحمد بن محمد الثعلبي (ت: 427ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'مرجع كبير في روايات التفسير وقصص الأنبياء والتراجم.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0111_ch1', 'kharji_lib_0111', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0111_seg_1', 'kharji_lib_0111_ch1', 'kharji_lib_0111', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الكشف والبيان عن تفسير القرآن (تفسير الثعلبي)'' by الإمام أبو إسحاق أحمد بن محمد الثعلبي (ت: 427ھ).","ar":"نص مختار من كتاب الكشف والبيان عن تفسير القرآن (تفسير الثعلبي) للإمام الإمام أبو إسحاق أحمد بن محمد الثعلبي (ت: 427ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0112', 'النكت والعيون (تفسير الماوردي)', 'الإمام أبو الحسن علي بن محمد الماوردي (ت: 450ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'تفسير بديع يورد الأقوال مرقمة مع الدقة البالغة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0112_ch1', 'kharji_lib_0112', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0112_seg_1', 'kharji_lib_0112_ch1', 'kharji_lib_0112', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''النكت والعيون (تفسير الماوردي)'' by الإمام أبو الحسن علي بن محمد الماوردي (ت: 450ھ).","ar":"نص مختار من كتاب النكت والعيون (تفسير الماوردي) للإمام الإمام أبو الحسن علي بن محمد الماوردي (ت: 450ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0113', 'معالم التنزيل في التفسير والتأويل (تفسير البغوي)', 'الإمام محيي السنة الحسين بن مسعود البغوي (ت: 516ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'تفسير سلفي محقق يجمع صحاح الروايات والآثار.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0113_ch1', 'kharji_lib_0113', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0113_seg_1', 'kharji_lib_0113_ch1', 'kharji_lib_0113', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''معالم التنزيل في التفسير والتأويل (تفسير البغوي)'' by الإمام محيي السنة الحسين بن مسعود البغوي (ت: 516ھ).","ar":"نص مختار من كتاب معالم التنزيل في التفسير والتأويل (تفسير البغوي) للإمام الإمام محيي السنة الحسين بن مسعود البغوي (ت: 516ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0114', 'الكشاف عن حقائق غوامض التنزيل', 'الإمام جار الله محمود بن عمر الزمخشري (ت: 538ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'المرجع الأعظم في بلاغة القرآن ودقائق الإعجاز البياني.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0114_ch1', 'kharji_lib_0114', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0114_seg_1', 'kharji_lib_0114_ch1', 'kharji_lib_0114', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الكشاف عن حقائق غوامض التنزيل'' by الإمام جار الله محمود بن عمر الزمخشري (ت: 538ھ).","ar":"نص مختار من كتاب الكشاف عن حقائق غوامض التنزيل للإمام الإمام جار الله محمود بن عمر الزمخشري (ت: 538ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0115', 'المحرر الوجيز في تفسير الكتاب العزيز', 'القاضي أبو محمد عبد الحق بن عطية الأندلسي (ت: 546ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'من أجلّ التفاسير المجمعة للغة والقراءات والأحكام.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0115_ch1', 'kharji_lib_0115', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
