INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0123', 'غرائب القرآن ورغائب الفرقان', 'العلامة نظام الدين الحسن بن محمد النيسابوري (ت: 728ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'جمع فيه بين الكشاف والرازي مع إشارات عرفانية لطيفة.', 1, 1);
