INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0145', 'حرز الأماني ووجه التهاني (الشاطبية)', 'الإمام القاسم بن فيرة الشاطبي الرعيني (ت: 590ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'القصيدة اللامية الخالدة الجامعة لأصول وفرش القراءات السبع.', 1, 1);
