INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0146_ch1', 'kharji_lib_0146', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0146_seg_1', 'kharji_lib_0146_ch1', 'kharji_lib_0146', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''إعجاز القرآن'' by القاضي أبو بكر محمد بن الطيب الباقلاني (ت: 403ھ).","ar":"نص مختار من كتاب إعجاز القرآن للإمام القاضي أبو بكر محمد بن الطيب الباقلاني (ت: 403ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0147', 'الناسخ والمنسوخ في القرآن العزيز', 'الإمام أبو عبيد القاسم بن سلام الهروي (ت: 224ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'أول مدونات علم النسخ وأصول التشريع القرآني.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0147_ch1', 'kharji_lib_0147', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0147_seg_1', 'kharji_lib_0147_ch1', 'kharji_lib_0147', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الناسخ والمنسوخ في القرآن العزيز'' by الإمام أبو عبيد القاسم بن سلام الهروي (ت: 224ھ).","ar":"نص مختار من كتاب الناسخ والمنسوخ في القرآن العزيز للإمام الإمام أبو عبيد القاسم بن سلام الهروي (ت: 224ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0148', 'لباب النقول في أسباب النزول', 'الحافظ جلال الدين السيوطي (ت: 911ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'مجموع أسباب النزول الصحيحة بأسانيدها المعتمدة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0148_ch1', 'kharji_lib_0148', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0148_seg_1', 'kharji_lib_0148_ch1', 'kharji_lib_0148', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''لباب النقول في أسباب النزول'' by الحافظ جلال الدين السيوطي (ت: 911ھ).","ar":"نص مختار من كتاب لباب النقول في أسباب النزول للإمام الحافظ جلال الدين السيوطي (ت: 911ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0149', 'الفوز الكبير في أصول التفسير', 'الإمام الشاه ولي الله أحمد بن عبد الرحيم الدهلوي (ت: 1176ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'قواعد الإمام المجدد في أسرار النظم وأساليب القرآن.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0149_ch1', 'kharji_lib_0149', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0149_seg_1', 'kharji_lib_0149_ch1', 'kharji_lib_0149', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الفوز الكبير في أصول التفسير'' by الإمام الشاه ولي الله أحمد بن عبد الرحيم الدهلوي (ت: 1176ھ).","ar":"نص مختار من كتاب الفوز الكبير في أصول التفسير للإمام الإمام الشاه ولي الله أحمد بن عبد الرحيم الدهلوي (ت: 1176ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0150', 'التفسير المظهري', 'القاضي ثناء الله العثماني الباني بتي الحنفي (ت: 1225ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'تفسير جامع بين الفقه والحديث واللطائف السلوكية.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0150_ch1', 'kharji_lib_0150', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0150_seg_1', 'kharji_lib_0150_ch1', 'kharji_lib_0150', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب علوم القرآن و التفسیر کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''التفسير المظهري'' by القاضي ثناء الله العثماني الباني بتي الحنفي (ت: 1225ھ).","ar":"نص مختار من كتاب التفسير المظهري للإمام القاضي ثناء الله العثماني الباني بتي الحنفي (ت: 1225ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0151', 'بيان القرآن', 'حكيم الأمة مولانا أشرف علي التهانوي (ت: 1362ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'تفسير دقيق يحل المشكلات الإعرابية والمسائل الكلامية والعملية.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0151_ch1', 'kharji_lib_0151', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
