INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0152', 'معارف القرآن', 'مفتي أعظم باكستان مولانا محمد شفيع العثماني (ت: 1396ھ)', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'أشهر التفسيرات المعاصرة المخدومة فقهياً واجتماعياً وإصلاحياً.', 1, 1);
