INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0203', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم القرآن و التفسیر (الجزء 51)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم القرآن و التفسیر', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم القرآن و التفسیر وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0203_ch1', 'kharji_lib_0203', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0203_seg_1', 'kharji_lib_0203_ch1', 'kharji_lib_0203', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم القرآن و التفسیر کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 51 of علوم القرآن و التفسیر.","ar":"نص وبحث تأصيلي في علوم القرآن و التفسیر."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0204', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم القرآن و التفسیر (الجزء 52)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم القرآن و التفسیر', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم القرآن و التفسیر وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0204_ch1', 'kharji_lib_0204', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0204_seg_1', 'kharji_lib_0204_ch1', 'kharji_lib_0204', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم القرآن و التفسیر کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 52 of علوم القرآن و التفسیر.","ar":"نص وبحث تأصيلي في علوم القرآن و التفسیر."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0205', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم القرآن و التفسیر (الجزء 53)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم القرآن و التفسیر', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم القرآن و التفسیر وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0205_ch1', 'kharji_lib_0205', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0205_seg_1', 'kharji_lib_0205_ch1', 'kharji_lib_0205', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم القرآن و التفسیر کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 53 of علوم القرآن و التفسیر.","ar":"نص وبحث تأصيلي في علوم القرآن و التفسیر."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0206', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم القرآن و التفسیر (الجزء 54)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم القرآن و التفسیر', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم القرآن و التفسیر وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0206_ch1', 'kharji_lib_0206', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0206_seg_1', 'kharji_lib_0206_ch1', 'kharji_lib_0206', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم القرآن و التفسیر کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 54 of علوم القرآن و التفسیر.","ar":"نص وبحث تأصيلي في علوم القرآن و التفسیر."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0207', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم القرآن و التفسیر (الجزء 55)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم القرآن و التفسیر', 'kharji_kitab', 'tafseer', 'علوم القرآن و التفسیر', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم القرآن و التفسیر وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
