INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0236', 'معارف السنن شرح سنن الترمذي', 'العلامة السيد محمد يوسف البنوري (ت: 1397ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'الشرح الفقهي المقارن الراقي الذي أبهر علماء العالم الإسلامي.', 1, 1);
