INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0238', 'فيض الباري على صحيح البخاري', 'العلامة محمد أنور شاه الكشميري (ت: 1352ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'درر وتحقيقات كبار علماء الهند على أصح الكتب بعد كتاب الله.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0238_ch1', 'kharji_lib_0238', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0238_seg_1', 'kharji_lib_0238_ch1', 'kharji_lib_0238', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''فيض الباري على صحيح البخاري'' by العلامة محمد أنور شاه الكشميري (ت: 1352ھ).","ar":"نص مختار من كتاب فيض الباري على صحيح البخاري للإمام العلامة محمد أنور شاه الكشميري (ت: 1352ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0239', 'التمهيد لما في الموطأ من المعاني والأسانيد', 'الإمام أبو عمر يوسف بن عبد البر النمري القرطبي (ت: 463ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'موسوعة السنة والفقه المقارن المرتبة على شيوخ مالك.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0239_ch1', 'kharji_lib_0239', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0239_seg_1', 'kharji_lib_0239_ch1', 'kharji_lib_0239', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''التمهيد لما في الموطأ من المعاني والأسانيد'' by الإمام أبو عمر يوسف بن عبد البر النمري القرطبي (ت: 463ھ).","ar":"نص مختار من كتاب التمهيد لما في الموطأ من المعاني والأسانيد للإمام الإمام أبو عمر يوسف بن عبد البر النمري القرطبي (ت: 463ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0240', 'الاستذكار لمذاهب فقهاء الأمصار', 'الإمام ابن عبد البر الأندلسي (ت: 463ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'بيان مذاهب أئمة الفتوى في نصوص موطأ الإمام مالك.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0240_ch1', 'kharji_lib_0240', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0240_seg_1', 'kharji_lib_0240_ch1', 'kharji_lib_0240', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الاستذكار لمذاهب فقهاء الأمصار'' by الإمام ابن عبد البر الأندلسي (ت: 463ھ).","ar":"نص مختار من كتاب الاستذكار لمذاهب فقهاء الأمصار للإمام الإمام ابن عبد البر الأندلسي (ت: 463ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0241', 'أوجز المسالك إلى موطأ مالك', 'العلامة الشيخ محمد زكريا الكاندهلوي (ت: 1402ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'الموسوعة الحديثية الفقهية المتقنة في تخريج روايات الموطأ.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0241_ch1', 'kharji_lib_0241', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0241_seg_1', 'kharji_lib_0241_ch1', 'kharji_lib_0241', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''أوجز المسالك إلى موطأ مالك'' by العلامة الشيخ محمد زكريا الكاندهلوي (ت: 1402ھ).","ar":"نص مختار من كتاب أوجز المسالك إلى موطأ مالك للإمام العلامة الشيخ محمد زكريا الكاندهلوي (ت: 1402ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0242', 'شرح معاني الآثار', 'الإمام أبو جعفر أحمد بن محمد الطحاوي الحنفي (ت: 321ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'عمدة مذهب الحنفية في توجيه نصوص السنة ودفع التعارض.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0242_ch1', 'kharji_lib_0242', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0242_seg_1', 'kharji_lib_0242_ch1', 'kharji_lib_0242', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''شرح معاني الآثار'' by الإمام أبو جعفر أحمد بن محمد الطحاوي الحنفي (ت: 321ھ).","ar":"نص مختار من كتاب شرح معاني الآثار للإمام الإمام أبو جعفر أحمد بن محمد الطحاوي الحنفي (ت: 321ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0243', 'نخب الأفكار في تنقيح مباني الأخبار', 'الإمام بدر الدين العيني الحنفي (ت: 855ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'شرح الطحاوي الحافل ببيان صحاح الروايات ولطائف الإسناد.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0243_ch1', 'kharji_lib_0243', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
