INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0244', 'إعلاء السنن', 'العلامة ظفر أحمد العثماني التهانوي (ت: 1394ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'الموسوعة الحديثية الكبرى لإثبات أدلة المذهب الحنفي.', 1, 1);
