INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0245', 'نصب الراية لأحاديث الهداية', 'الحافظ جمال الدين عبد الله بن يوسف الزيلعي (ت: 762ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'أكمل كتب التخريج في إنصاف المذاهب وجمع الأسانيد.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0245_ch1', 'kharji_lib_0245', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0245_seg_1', 'kharji_lib_0245_ch1', 'kharji_lib_0245', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''نصب الراية لأحاديث الهداية'' by الحافظ جمال الدين عبد الله بن يوسف الزيلعي (ت: 762ھ).","ar":"نص مختار من كتاب نصب الراية لأحاديث الهداية للإمام الحافظ جمال الدين عبد الله بن يوسف الزيلعي (ت: 762ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0246', 'الدراية في تخريج أحاديث الهداية', 'الحافظ ابن حجر العسقلاني (ت: 852ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'تلخيص محرر لكتاب نصب الراية مع إضافات نفيسة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0246_ch1', 'kharji_lib_0246', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0246_seg_1', 'kharji_lib_0246_ch1', 'kharji_lib_0246', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الدراية في تخريج أحاديث الهداية'' by الحافظ ابن حجر العسقلاني (ت: 852ھ).","ar":"نص مختار من كتاب الدراية في تخريج أحاديث الهداية للإمام الحافظ ابن حجر العسقلاني (ت: 852ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0247', 'تلخيص الحبير في تخريج أحاديث الرافعي الكبير', 'الحافظ ابن حجر العسقلاني (ت: 852ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'المرجع الأعلى في معرفة مراتب أحاديث الأحكام الفقهية.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0247_ch1', 'kharji_lib_0247', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0247_seg_1', 'kharji_lib_0247_ch1', 'kharji_lib_0247', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''تلخيص الحبير في تخريج أحاديث الرافعي الكبير'' by الحافظ ابن حجر العسقلاني (ت: 852ھ).","ar":"نص مختار من كتاب تلخيص الحبير في تخريج أحاديث الرافعي الكبير للإمام الحافظ ابن حجر العسقلاني (ت: 852ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0248', 'مجمع الزوائد ومنبع الفوائد', 'الحافظ نور الدين علي بن أبي بكر الهيثمي (ت: 807ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'تجريد زوائد المسانيد والمعاجم مع الحكم على الرواة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0248_ch1', 'kharji_lib_0248', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0248_seg_1', 'kharji_lib_0248_ch1', 'kharji_lib_0248', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''مجمع الزوائد ومنبع الفوائد'' by الحافظ نور الدين علي بن أبي بكر الهيثمي (ت: 807ھ).","ar":"نص مختار من كتاب مجمع الزوائد ومنبع الفوائد للإمام الحافظ نور الدين علي بن أبي بكر الهيثمي (ت: 807ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0249', 'مقدمة ابن الصلاح (علوم الحديث)', 'الإمام أبو عمرو عثمان بن عبد الرحمن الشهرزوري (ت: 643ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'الأساس الذي دارت عليه جميع مصنفات المصطلح بعده.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0249_ch1', 'kharji_lib_0249', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0249_seg_1', 'kharji_lib_0249_ch1', 'kharji_lib_0249', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''مقدمة ابن الصلاح (علوم الحديث)'' by الإمام أبو عمرو عثمان بن عبد الرحمن الشهرزوري (ت: 643ھ).","ar":"نص مختار من كتاب مقدمة ابن الصلاح (علوم الحديث) للإمام الإمام أبو عمرو عثمان بن عبد الرحمن الشهرزوري (ت: 643ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0250', 'تدريب الراوي في شرح تقريب النواوي', 'الحافظ جلال الدين عبد الرحمن السيوطي (ت: 911ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'الموسوعة المنهجية الشاملة لقواعد وأصول المصطلح الحديثي.', 1, 1);
