INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0251', 'فتح المغيث بشرح ألفية الحديث', 'الحافظ شمس الدين محمد بن عبد الرحمن السخاوي (ت: 902ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'الشرح الأوفى لألفية العراقي في مصطلح الحديث.', 1, 1);
