INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0258', 'ميزان الاعتدال في نقد الرجال', 'الإمام الحافظ شمس الدين محمد بن أحمد الذهبي (ت: 748ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'ميزان النقد الأعدل في تمييز الضعفاء والمتروكين والمفترى عليهم.', 1, 1);
