INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0260', 'جامع العلوم والحكم في شرح خمسين حديثاً', 'الحافظ زين الدين عبد الرحمن بن رجب الحنبلي (ت: 795ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'شرح الأربعين النووية مع الزيادة الجامعة لجوامع الكلم.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0260_ch1', 'kharji_lib_0260', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0260_seg_1', 'kharji_lib_0260_ch1', 'kharji_lib_0260', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''جامع العلوم والحكم في شرح خمسين حديثاً'' by الحافظ زين الدين عبد الرحمن بن رجب الحنبلي (ت: 795ھ).","ar":"نص مختار من كتاب جامع العلوم والحكم في شرح خمسين حديثاً للإمام الحافظ زين الدين عبد الرحمن بن رجب الحنبلي (ت: 795ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0261', 'رياض الصالحين من كلام سيد المرسلين', 'الإمام محيي الدين يحيى بن شرف النووي (ت: 676ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'شہرۂ آفاق مجموعۂ احادیث: تہذیبِ اخلاق، اصلاحِ باطن، فضائلِ اعمال اور آدابِ زندگی کا معتمد ترین классикی شاہکار۔ مکمل 25 اساسی ابواب اور 50 مفصل صفحات پر مشتمل جس میں ہر صفحے پر اگلے صفحے اور باب کی مسلسل رہنمائی موجود ہے۔', 25, 50);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch1_ikhlas', 'kharji_lib_0261', 0, 'بَابُ الإِخْلَاصِ وَإِحْضَارِ النِّيَّةِ فِي جَمِيعِ الأَعْمَالِ', 'باب 1: تمام اعمال و اقوال میں اخلاص اور نیت کا استحضار');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_1_1', 'riyad_ch1_ikhlas', 'kharji_lib_0261', 0, 'عَنْ أَمِيرِ المُؤْمِنِينَ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ».', 'امیر المؤمنین حضرت عمر بن الخطاب رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے ہوئے سنا: ''تمام اعمال کا دارومدار نیتوں پر ہے، اور ہر انسان کے لیے وہی ہے جس کی اس نے نیت کی۔ پس جس کی ہجرت اللہ اور اس کے رسول کی رضا کے لیے ہو، اس کی ہجرت اللہ اور اس کے رسول کے لیے ہی قبول ہوگی؛ اور جس کی ہجرت دنیا حاصل کرنے کے لیے یا کسی عورت سے نکاح کرنے کے لیے ہو، تو اس کی ہجرت اسی کے لیے شمار ہوگی جس کے لیے اس نے ہجرت کی۔''', 'نیت کی طہارت اور اخلاصِ قلب ہر دینی عمل کی روح ہے۔ امام شافعی اور امام احمد بن حنبل فرماتے ہیں کہ یہ حدیثِ پاک ایک تہائی دین پر محیط ہے، کیونکہ انسان کے اعمال کا تعلق دل، زبان اور اعضاء سے ہے اور دل کا عمل نیت ہے۔', '[{"word":"إِنَّمَا","role":"أداة حصر","sign":"مبنی","detail":"مركبة من إن المكفوفة وما الكافة"},{"word":"الأَعْمَالُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالابتداء وعلامة رفعه الضمة"},{"word":"بِالنِّيَّاتِ","role":"جار ومجرور","sign":"كسرة لفظاً","detail":"شبه جملة متعلق بمحذوف خبر المبتدأ"}]', '["متفق عليه: أخرجه البخاري (1)، ومسلم (1907)."]', '{"en":"Narrated ''Umar bin Al-Khattab: I heard Allah''s Messenger ﷺ saying: ''Actions are judged by intentions, and every person will get what they intended. So whoever emigrated for Allah and His Messenger, his emigration is for Allah and His Messenger...''","ar":"هذا الحديث قاعدة كبرى من قواعد الإسلام، وافتتح به الإمام البخاري صحيحه والإمام النووي رياض الصالحين تذكيراً بالإخلاص."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_1_2', 'riyad_ch1_ikhlas', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى أَجْسَادِكُمْ، وَلَا إِلَى صُوَرِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''بے شک اللہ تعالیٰ تمہارے جسموں اور تمہاری ظاہری صورتوں کو نہیں دیکھتا، بلکہ وہ تمہارے دلوں (کے اخلاص) اور تمہارے اعمال کو دیکھتا ہے۔''', 'اللہ تعالیٰ کے ہاں انسانی صورت، حسب و نسب یا دنیاوی ٹھاٹھ باٹھ کی کوئی حیثیت نہیں؛ اصل کسوٹی دل کا تقویٰ اور عمل کا اخلاص ہے۔', '[{"word":"إِنَّ","role":"حرف توكيد ونصب","sign":"مبنی علی الفتح","detail":"تنصب الاسم وترفع الخبر"},{"word":"قُلُوبِكُمْ","role":"اسم مجرور بإلى","sign":"كسرة لفظاً","detail":"وهو مضاف والكاف ضمير متصل مضاف إليه"}]', '["أخرجه مسلم في صحيحه (2564)."]', '{"en":"Abu Hurairah narrated that the Messenger of Allah ﷺ said: ''Verily, Allah does not look at your bodies or your appearances, but He looks at your hearts and your deeds.''","ar":"المقصود طهارة السريرة وصدق الإخلاص، فالقلب محل نظر الرب سبحانه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch2_tawbah', 'kharji_lib_0261', 1, 'بَابُ التَّوْبَةِ وَشُرُوطِهَا وَفَضْلِ الاسْتِغْفَارِ', 'باب 2: توبہ، اس کی شرائط اور استغفار کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_2_1', 'riyad_ch2_tawbah', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «وَاللَّهِ إِنِّي لَأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي اليَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''اللہ کی قسم! میں دن بھر میں ستر مرتبہ سے بھی زیادہ اللہ تعالیٰ سے استغفار کرتا ہوں اور اس کی بارگاہ میں توبہ کرتا ہوں۔''', 'جب سید الانبیاء ﷺ تمام گناہوں سے پاک اور معصوم ہونے کے باوجود روزانہ کثرت سے استغفار فرماتے تھے، تو امت کے لیے ہر وقت توبہ و انابت کا دامن تھامے رکھنا کتنا ضروری ہے۔', '[{"word":"وَاللَّهِ","role":"واو القسم وجار ومجرور","sign":"كسرة لفظاً","detail":"متعلق بفعل أقسم المحذوف"},{"word":"لَأَسْتَغْفِرُ","role":"اللام واقعة في جواب القسم","sign":"ضمة لفظاً","detail":"فعل مضارع مرفوع والفاعل ضمير مستتر تقديره أنا"}]', '["أخرجه البخاري في صحيحه (6307)."]', '{"en":"Abu Hurairah reported: I heard Allah''s Messenger ﷺ saying: ''By Allah, I seek forgiveness of Allah and turn to Him in repentance more than seventy times a day.''","ar":"بيان عظم شأن التوبة والاستغفار واقتداء الأمة بالنبي المعصوم ﷺ."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_2_2', 'riyad_ch2_tawbah', 'kharji_lib_0261', 1, 'وَعَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَلَّهُ أَشَدُّ فَرَحاً بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا... فَبَيْنَمَا هُوَ كَذَلِكَ إِذَا هُوَ بِهَا قَائِمَةً عِنْدَهُ... ثُمَّ قَالَ مِنْ شِدَّةِ الفَرَحِ: اللَّهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ، أَخْطَأَ مِنْ شِدَّةِ الفَرَحِ».', 'حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے فرمایا: ''اللہ تعالیٰ اپنے بندے کی توبہ سے اس شخص سے بھی زیادہ خوش ہوتا ہے جس کی سواری کسی بیابان صحرا میں گم ہو جائے اور اسی پر اس کا سارا کھانا پینا ہو، اور وہ زندگی سے مایوس ہو کر کسی درخت کے سائے میں موت کا انتظار کرنے لگے، پھر اچانک وہ اپنی سواری کو بالکل اپنے پاس کھڑا پائے... تو وہ بے پناہ خوشی کی شدت میں زبان کی لغزش سے بول اٹھے: اے اللہ! تو میرا بندہ اور میں تیرا رب ہوں!''', 'اللہ تعالیٰ کی رحمت اپنے گناہ گار بندوں کے لیے بے پایاں ہے۔ یہ مثال سمجھاتی ہے کہ اللہ کے دربار میں مایوسی کفر ہے، جب بھی بندہ سچے دل سے رجوع کرتا ہے، اللہ تعالیٰ اسے گلے لگا لیتا ہے۔', '[{"word":"لَلَّهُ","role":"لام الابتداء ولفظ الجلالة مبتدأ","sign":"ضمة لفظاً","detail":"تفيد التوكيد ولفظ الجلالة مرفوع بالابتداء"},{"word":"أَشَدُّ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"اسم تفضيل ممنوع من الصرف"}]', '["متفق عليه: أخرجه البخاري (6309)، ومسلم (2747)."]', '{"en":"Anas reported that Allah''s Messenger ﷺ said: ''Allah is more pleased with the repentance of His servant than one of you who lost his camel loaded with food and water in a barren desert, surrendered to death, then suddenly found it standing before him...''","ar":"ضرب الأمثال لتقريب سعة رحمة الله وفرحه بعودة العبد المذنب إليه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch3_sabr', 'kharji_lib_0261', 2, 'بَابُ الصَّبْرِ وَالمُصَابَرَةِ عَلَى البَلَاءِ وَالمَصَائِبِ', 'باب 3: صبر، مصائب پر استقامت اور اس کا عظیم اجر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_3_1', 'riyad_ch3_sabr', 'kharji_lib_0261', 0, 'عَنْ أَبِي يَحْيَى صُهَيْبِ بْنِ سِنَانٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «عَجَباً لِأَمْرِ المُؤْمِنِ، إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ: إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْراً لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْراً لَهُ».', 'حضرت صہیب رومی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''مومن کا معاملہ بھی خوب عجیب ہے! اس کے ہر معاملے میں سراسر خیر ہی خیر ہے، اور یہ فضیلت مومن کے سوا کسی کو حاصل نہیں: اگر اسے خوشی اور نعمت ملے تو وہ شکر ادا کرتا ہے تو یہ اس کے لیے خیر بن جاتی ہے، اور اگر اسے کوئی تکلیف یا دکھ پہنچے تو وہ صبر کرتا ہے تو یہ بھی اس کے لیے خیر بن جاتی ہے۔''', 'مومن کی پوری زندگی شکر اور صبر کے دو پروں کے درمیان پرواز کرتی ہے۔ نعمت پر شکر اور مصیبت پر صبر انسان کو ہر حالت میں اللہ کا مقرب بنا دیتے ہیں۔', '[{"word":"عَجَباً","role":"مفعول مطلق لفعل محذوف","sign":"فتحة لفظاً","detail":"تقديره: أعجب عجباً"},{"word":"كُلَّهُ","role":"توكيد معنوي","sign":"ضمة لفظاً","detail":"توكيد لاسم إن (أمره) مرفوع"}]', '["أخرجه مسلم في صحيحه (2999)."]', '{"en":"Suhaib narrated that the Messenger of Allah ﷺ said: ''How wonderful is the affair of the believer! For all his affairs are good for him, and this is for none except the believer: if prosperity comes to him, he expresses gratitude and it is good for him; and if adversity befalls him, he is patient and it is good for him.''","ar":"المؤمن يتقلب بين مقامي الشكر والصبر، فكلتا الحالتين ربح له في ميزان الحسنات."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_3_2', 'riyad_ch3_sabr', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ ﷺ قَالَ: «مَا يُصِيبُ المُسْلِمَ مِنْ نَصَبٍ، وَلَا وَصَبٍ، وَلَا هَمٍّ، وَلَا حُزْنٍ، وَلَا أَذًى، وَلَا غَمٍّ، حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلَّا كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ».', 'حضرت ابوسعید خدری اور حضرت ابوہریرہ رضی اللہ عنہما سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ''مسلمان کو جو بھی تھکن، بیماری، فکر، غم، تکلیف یا دکھ پہنچتا ہے، یہاں تک کہ وہ کانٹا بھی جو اس کے پاؤں میں چبھ جائے، تو اللہ تعالیٰ اس کے بدلے اس کے گناہوں کا کفارہ فرما دیتا ہے۔''', 'دنیا کی کوئی تکلیف بھی ضائع نہیں جاتی؛ بیماری اور پریشانی اگر بندہ صبر کے ساتھ برداشت کرے تو وہ گناہوں کو ایسے جھاڑ دیتی ہے جیسے خزاں میں درخت کے پتے گرتے ہیں۔', '[{"word":"مَا","role":"حرف نفي","sign":"مبني على السكون","detail":"نافية لا عمل لها"},{"word":"نَصَبٍ","role":"مجرور لفظاً بمن الزائدة","sign":"كسرة لفظاً","detail":"في محل رفع فاعل يُصِيب"}]', '["متفق عليه: البخاري (5641)، ومسلم (2573)."]', '{"en":"Abu Sa''id and Abu Hurairah reported that the Prophet ﷺ said: ''No fatigue, illness, sorrow, grief, hurt, or distress befalls a Muslim, even to the prick of a thorn, except that Allah expiates some of his sins by it.''","ar":"البلايا والمصائب كفارات للذنوب ورافعات للدرجات عند الصبر والاحتساب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch4_sidq', 'kharji_lib_0261', 3, 'بَابُ الصِّدْقِ وَفَضْلِهِ وَثَمَرَاتِهِ فِي الدُّنْيَا وَالآخِرَةِ', 'باب 4: سچائی، دیانت اور اس کے عظیم ثمرات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_4_1', 'riyad_ch4_sidq', 'kharji_lib_0261', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ الصِّدْقَ يَهْدِي إِلَى البِرِّ، وَإِنَّ البِرَّ يَهْدِي إِلَى الجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقاً، وَإِنَّ الكَذِبَ يَهْدِي إِلَى الفُجُورِ، وَإِنَّ الفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الرَّجُلَ لَيَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّاباً».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''بے شک سچائی نیکی کی راہ دکھاتی ہے، اور نیکی جنت کا راستہ بتاتی ہے؛ اور آدمی سچ بولتا رہتا ہے یہاں تک کہ اللہ کے ہاں اس کا نام صدیق (انتہائی سچا) لکھ دیا جاتا ہے۔ اور بے شک جھوٹ گناہ اور نافرمانی کی طرف لے جاتا ہے، اور نافرمانی جہنم کا راستہ دکھاتی ہے؛ اور آدمی جھوٹ بولتا رہتا ہے یہاں تک کہ اللہ کے ہاں اس کا نام کذاب (بڑا جھوٹا) لکھ دیا جاتا ہے۔''', 'سچائی تمام نیکیوں کی جڑ ہے اور جھوٹ تمام برائیوں اور نفاق کی ماں ہے۔ صدقِ لسان انسان کو مقامِ صدیقیت تک پہنچاتا ہے۔', '[{"word":"الصِّدْقَ","role":"اسم إن منصوب","sign":"فتحة لفظاً","detail":"منصوب وعلامة نصبه الفتحة"},{"word":"يَهْدِي","role":"فعل مضارع والفاعل مستتر","sign":"ضمة مقدرة","detail":"والجملة الفعلية في محل رفع خبر إن"}]', '["متفق عليه: البخاري (6094)، ومسلم (2607)."]', '{"en":"Abdullah bin Mas''ud narrated that the Prophet ﷺ said: ''Truthfulness leads to righteousness, and righteousness leads to Paradise. A man continues to speak the truth until he is recorded with Allah as a truthful person (Siddiq)...''","ar":"الحث على الصدق في الأقوال والأفعال والتحذير من الكذب وعواقبه الوخيمة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_4_2', 'riyad_ch4_sidq', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي مُحَمَّدٍ الحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: حَفِظْتُ مِنْ رَسُولِ اللَّهِ ﷺ: «دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ، فَإِنَّ الصِّدْقَ طُمَأْنِينَةٌ، وَإِنَّ الكَذِبَ رِيبَةٌ».', 'حضرت حسن بن علی رضی اللہ عنہما نے فرمایا: میں نے رسول اللہ ﷺ سے یہ بات یاد رکھی ہے کہ آپ ﷺ نے فرمایا: ''جس چیز میں تمہیں شک اور شبہ ہو اسے چھوڑ کر اس چیز کو اختیار کرو جس میں کوئی شک نہ ہو، کیونکہ سچائی دل کا سکون و اطمینان ہے اور جھوٹ شک اور بے چینی ہے۔''', 'یہ حدیثِ مبارک شبہات سے بچنے اور تقویٰ و ورع اختیار کرنے کا عظیم ترین ضابطہ ہے۔ دل کا حقیقی سکون صرف سچائی اور حلال میں ہے۔', '[{"word":"دَعْ","role":"فعل أمر مبني على السكون","sign":"سكون","detail":"والفاعل ضمير مستتر وجوباً تقديره أنت"},{"word":"مَا","role":"اسم موصول مفعول به","sign":"مبني على السكون","detail":"في محل نصب مفعول به"}]', '["أخرجه الترمذي (2518) وقال: حديث حسن صحيح."]', '{"en":"Al-Hasan bin ''Ali reported: I memorized from Allah''s Messenger ﷺ: ''Leave that which makes you doubt for that which does not make you doubt. For indeed, truthfulness brings tranquility, while falsehood brings doubt and unease.''","ar":"قاعدة شرعية جليلة في الورع واجتناب الشبهات والتحلي بالصدق."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch5_muraqabah', 'kharji_lib_0261', 4, 'بَابُ المُرَاقَبَةِ وَخَشْيَةِ اللَّهِ فِي السِّرِّ وَالعَلَنِ', 'باب 5: مراقبہ، تنہائی و جلوت میں اللہ کا خوف اور استحضارِ ربوبیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_5_1', 'riyad_ch5_muraqabah', 'kharji_lib_0261', 0, 'عَنْ أَبِي ذَرٍّ جُنْدَبِ بْنِ جُنَادَةَ، وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ ﷺ قَالَ: «اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ».', 'حضرت ابوذر اور حضرت معاذ بن جبل رضی اللہ عنہما سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تم جہاں کہیں بھی ہو اللہ سے ڈرتے رہو، اور کسی برائی کے بعد فوراً نیکی کر لیا کرو وہ نیکی اس برائی کو مٹا دے گی، اور لوگوں کے ساتھ حسنِ اخلاق سے پیش آؤ۔''', 'اس مختصر حدیث میں دین و دنیا کی تمام تر بھلائیاں سمو دی گئی ہیں: خالق کے ساتھ تقویٰ، اپنی خطاؤں کا نیکیوں سے علاج، اور مخلوق کے ساتھ بہترین اخلاق۔', '[{"word":"اتَّقِ","role":"فعل أمر","sign":"حذف حرف العلة","detail":"مبني على حذف الياء والفاعل مستتر تقديره أنت"},{"word":"حَيْثُمَا","role":"اسم شرط جازم للمكان","sign":"مبني على الضم","detail":"في محل نصب ظرف مكان"}]', '["أخرجه الترمذي (1987) وقال: حديث حسن."]', '{"en":"Abu Dharr and Mu''adh bin Jabal reported that the Messenger of Allah ﷺ said: ''Fear Allah wherever you may be; follow up an evil deed with a good one and it will wipe it out; and behave towards people with good manners.''","ar":"وصية نبوية جامعة جمعت حق الله تعالى في التقوى وحق النفس في التوبة وحق العباد في حسن الخلق."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_5_2', 'riyad_ch5_muraqabah', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ: إِمَامٌ عَادِلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي المَسَاجِدِ، وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ: إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِياً فَفَاضَتْ عَيْنَاهُ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ نبی کریم ﷺ نے ارشاد فرمایا: ''سات خوش نصیب ایسے ہیں جنہیں اللہ تعالیٰ اس دن اپنے عرش کے سائے میں جگہ دے گا جس دن اس کے سائے کے سوا کوئی سایہ نہ ہوگا: عادل حکمران، وہ نوجوان جس کی جوانی اللہ کی عبادت میں پروان چڑھی، وہ شخص جس کا دل مسجد سے اٹکا رہتا ہو، وہ دو شخص جو اللہ کے لیے محبت کریں اسی پر جمع ہوں اور اسی پر جدا ہوں، وہ شخص جسے کسی حسب و نسب اور حسن والی عورت نے گناہ کی دعوت دی تو اس نے کہا: میں اللہ سے ڈرتا ہوں، وہ شخص جس نے اتنا پوشیدہ صدقہ کیا کہ اس کے بائیں ہاتھ کو بھی خبر نہ ہوئی کہ دائیں ہاتھ نے کیا خرچ کیا، اور وہ شخص جس نے تنہائی میں اللہ کو یاد کیا اور اس کی آنکھوں سے آنسو جاری ہو گئے۔''', 'قیامت کی ہولناک گرمی میں عرش کا سایہ ان اہل اخلاص کو ملے گا جنہوں نے جوانی کی خواہشات کو دبایا، مساجد کو آباد کیا، تنہائیوں میں آنسو بہائے اور گناہ کی دعوت کو خوفِ خدا کی خاطر ٹھکرا دیا۔', '[{"word":"سَبْعَةٌ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"سوغ الابتداء بالنكرة كونها موصوفة بجملة يظلهم"},{"word":"إِمَامٌ","role":"بدل من سبعة","sign":"ضمة لفظاً","detail":"بدل تفصيل مرفوع"}]', '["متفق عليه: البخاري (660)، ومسلم (1031)."]', '{"en":"Abu Hurairah reported that the Prophet ﷺ said: ''Seven will be shaded by Allah under His Shade on the Day when there is no shade except His: a just ruler, a youth who grew up in the worship of Allah... and a person who remembers Allah in solitude and his eyes overflow with tears.''","ar":"أهل الإخلاص والمراقبة في أعلى درجات الكرامة يوم القيامة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch6_taqwa', 'kharji_lib_0261', 5, 'بَابُ التَّقْوَى وَفَضْلِهَا فِي الدُّنْيَا وَالآخِرَةِ', 'باب 6: تقویٰ، پرہیزگاری اور اس کی عظیم برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_6_1', 'riyad_ch6_taqwa', 'kharji_lib_0261', 0, 'عَنْ أَبِي أُمَامَةَ صُدَيِّ بْنِ عَجْلَانَ البَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَخْطُبُ فِي حَجَّةِ الوَدَاعِ فَقَالَ: «اتَّقُوا اللَّهَ رَبَّكُمْ، وَصَلُّوا خَمْسَكُمْ، وَصُومُوا شَهْرَكُمْ، وَأَدُّوا زَكَاةَ أَمْوَالِكُمْ، وَأَطِيعُوا ذَا أَمْرِكُمْ، تَدْخُلُوا جَنَّةَ رَبِّكُمْ».', 'حضرت ابو امامہ باہلی رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو حجتہ الوداع کے خطبے میں فرماتے سنا: ''اپنے رب اللہ سے ڈرو، اپنی پانچوں نمازیں ادا کرو، اپنے ماہِ رمضان کے روزے رکھو، اپنے مالوں کی زکوٰۃ ادا کرو، اور اپنے حکمرانوں اور امیروں کی جائز باتوں میں اطاعت کرو، تم اپنے رب کی جنت میں داخل ہو جاؤ گے۔''', 'رسول اکرم ﷺ نے آخری خطبے میں تمام بنیادی ارکان کو جمع فرما کر واضح کر دیا کہ تقویٰ اور شریعت پر عمل پیرا ہونا ہی دائمی فلاح اور دخولِ جنت کا واحد راستہ ہے۔', '[{"word":"اتَّقُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"},{"word":"تَدْخُلُوا","role":"جواب الطلب مجزوم","sign":"حذف النون","detail":"مجزوم في جواب الأمر وعلامة جزمه حذف النون"}]', '["أخرجه الترمذي في آخر كتاب الصلاة (616) وقال: حديث حسن صحيح."]', '{"en":"Abu Umamah reported: I heard Allah''s Messenger ﷺ deliver a sermon in the Farewell Pilgrimage saying: ''Fear your Lord, pray your five daily prayers, fast your month of Ramadan, pay the Zakah on your wealth, and obey your leaders, and you will enter the Paradise of your Lord.''","ar":"وصية جامعة من خطبة حجة الوداع جمعت أركان الإسلام وثمرتها دخول الجنة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_6_2', 'riyad_ch6_taqwa', 'kharji_lib_0261', 1, 'وَعَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «البِرُّ حُسْنُ الخُلُقِ، وَالإِثْمُ مَا حَاكَ فِي نَفْسِكَ، وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ».', 'حضرت نواس بن سمعان رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ''نیکی اچھے اخلاق کا نام ہے، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور بے چین کرے اور تم ناپسند کرو کہ لوگوں کو اس کی خبر ہو۔''', 'انسان کی فطرتِ سلیمہ گناہ پر بے چین ہو جاتی ہے۔ متقی انسان اپنے ضمیر کی اس پکار کو پہچانتا ہے اور ہر ایسے عمل سے دور رہتا ہے جسے وہ ظاہر کرنے سے شرمائے۔', '[{"word":"البِرُّ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالابتداء"},{"word":"حُسْنُ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والخلق مضاف إليه"}]', '["أخرجه مسلم في صحيحه (2553)."]', '{"en":"An-Nawwas bin Sam''an reported that the Prophet ﷺ said: ''Righteousness is good character, and sin is that which wavers in your heart and you dislike people finding out about it.''","ar":"الفطرة السليمة والضمير الحي ميزان لمعرفة الإثم واجتناب الشبهات."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch7_tawakkul', 'kharji_lib_0261', 6, 'بَابُ اليَقِينِ وَالتَّوَكُّلِ عَلَى اللَّهِ تَعَالَى', 'باب 7: یقین، حسنِ ظن اور اللہ تعالیٰ پر توکل');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_7_1', 'riyad_ch7_tawakkul', 'kharji_lib_0261', 0, 'عَنْ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «لَوْ أَنَّكُمْ تَتَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُمْ كَمَا يَرْزُقُ الطَّيْرَ، تَغْدُو خِمَاصاً وَتَرُوحُ بِطَاناً».', 'حضرت عمر فاروق رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''اگر تم اللہ تعالیٰ پر ویسا توکل کرو جیسا کہ توکل کرنے کا حق ہے، تو وہ تمہیں اس طرح رزق عطا فرمائے گا جیسے وہ پرندوں کو رزق دیتا ہے؛ کہ وہ صبح خالی پیٹ نکلتے ہیں اور شام کو پیٹ بھر کر لوٹتے ہیں۔''', 'توکل کا مطلب ہاتھ پر ہاتھ رکھ کر بیٹھنا نہیں ہے، بلکہ پرندوں کی طرح محنت و جستجو کے لیے نکلنا اور دل کا بھروسہ صرف اور صرف رزاقِ حقیقی پر رکھنا ہے۔', '[{"word":"لَوْ","role":"حرف شرط غير جازم","sign":"مبني على السكون","detail":"حرف امتناع لامتناع"},{"word":"خِمَاصاً","role":"حال منصوب","sign":"فتحة لفظاً","detail":"حال من فاعل تغدو"}]', '["أخرجه الترمذي (2344) وقال: حديث حسن صحيح."]', '{"en":"''Umar bin Al-Khattab reported: I heard Allah''s Messenger ﷺ saying: ''If you were to rely upon Allah with true reliance, He would provide for you just as He provides for birds: they depart in the morning with empty stomachs and return in the evening full.''","ar":"التوكل الشرعي يجمع بين اعتماد القلب على الله والأخذ بالأسباب المشروعة كخروج الطير وسعيه."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_7_2', 'riyad_ch7_tawakkul', 'kharji_lib_0261', 1, 'وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: «حَسْبُنَا اللَّهُ وَنِعْمَ الوَكِيلُ» قَالَهَا إِبْرَاهِيمُ ﷺ حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ ﷺ حِينَ قَالُوا لَهُ: ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَاناً وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الوَكِيلُ﴾.', 'حضرت عبداللہ بن عباس رضی اللہ عنہما نے فرمایا: ''حسبنا اللہ ونعم الوکیل'' (ہمیں اللہ کافی ہے اور وہ کیا ہی بہترین کارساز ہے!) یہ وہ کلمہ مبارکہ ہے جو حضرت ابراہیم علیہ السلام نے اس وقت پکارا جب انہیں آگ میں ڈالا جا رہا تھا، اور یہی کلمہ سیدنا محمد ﷺ نے اس وقت فرمایا جب لوگوں نے کہا کہ کافروں نے تمہارے خلاف لشکر جمع کر لیا ہے تو ڈرو، مگر اس بات نے مسلمانوں کے ایمان کو اور بڑھا دیا اور انہوں نے کہا: ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے۔', 'جب تمام ظاہری اسباب ٹوٹ جائیں تو ''حسبنا اللہ ونعم الوکیل'' کا ورد بندۂ مومن کے لیے نصرتِ الٰہی کا دروازہ کھول دیتا ہے، جیسا کہ حضرت ابراہیم کے لیے آگ گلزار بن گئی تھی۔', '[{"word":"حَسْبُنَا","role":"مبتدأ مرفوع","sign":"ضمة مقدرة","detail":"وهو مضاف ونا ضمير متصل مضاف إليه"},{"word":"اللَّهُ","role":"خبر المبتدأ","sign":"ضمة لفظاً","detail":"لفظ الجلالة مرفوع بالخبرية"}]', '["أخرجه البخاري في صحيحه (4563)."]', '{"en":"Ibn ''Abbas reported: ''Allah alone is sufficient for us, and He is the best disposer of affairs'' was said by Ibrahim when he was thrown into the fire, and was said by Muhammad ﷺ when people said to them: ''Verily, people have gathered against you, so fear them.''","ar":"كلمة التوحيد واللجوء المطلق إلى الله عند الشدائد والأزمات العظام."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch8_istiqamah', 'kharji_lib_0261', 7, 'بَابُ الاسْتِقَامَةِ وَلُزُومِ الصِّرَاطِ المُسْتَقِيمِ', 'باب 8: استقامت اور صراطِ مستقیم پر ہمیشگی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_8_1', 'riyad_ch8_istiqamah', 'kharji_lib_0261', 0, 'عَنْ أَبِي عَمْرٍو، وَقِيلَ: أَبِي عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللَّهِ الثَّقَفِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، قُلْ لِي فِي الإِسْلَامِ قَوْلاً لَا أَسْأَلُ عَنْهُ أَحَداً غَيْرَكَ، قَالَ: «قُلْ: آمَنْتُ بِاللَّهِ، ثُمَّ اسْتَقِمْ».', 'حضرت سفیان بن عبداللہ ثقفی رضی اللہ عنہ نے عرض کیا: یا رسول اللہ! مجھے اسلام کے بارے میں ایسی جامع بات ارشاد فرما دیجیے کہ آپ کے بعد مجھے کسی اور سے پوچھنے کی ضرورت نہ رہے۔ آپ ﷺ نے فرمایا: ''کہو: میں اللہ پر ایمان لایا، پھر اس پر ڈٹ جاؤ (استقامت اختیار کرو)''۔', 'استقامت کرامت سے بڑھ کر ہے۔ ایمان لانے کے بعد شریعت کے احکام پر زندگی کی آخری سانس تک استقلال کے ساتھ قائم رہنا ہی انسان کی اصل کامیابی ہے۔', '[{"word":"آمَنْتُ","role":"فعل ماض وفاعل","sign":"مبني على السكون","detail":"والتاء ضمير متصل فاعل في محل نصب مقول القول"},{"word":"اسْتَقِمْ","role":"فعل أمر مبني على السكون","sign":"سكون","detail":"والفاعل ضمير مستتر تقديره أنت"}]', '["أخرجه مسلم في صحيحه (38)."]', '{"en":"Sufyan bin ''Abdullah reported: I said: ''O Messenger of Allah! Tell me something about Islam so comprehensive that I will not need to ask anyone after you.'' He replied: ''Say: I believe in Allah, and then be steadfast.''","ar":"هذا الحديث من جوامع كلمه ﷺ، جمع فيه الإيمان والعمل والاستمرار عليه."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_8_2', 'riyad_ch8_istiqamah', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «سَدِّدُوا وَقَارِبُوا، وَاعْلَمُوا أَنَّهُ لَنْ يَنْجُوَ أَحَدٌ مِنْكُمْ بِعَمَلِهِ»، قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: «وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِي اللَّهُ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''درستی اور میانہ روی اختیار کرو، اور جان لو کہ تم میں سے کوئی بھی محض اپنے عمل کے بل بوتے پر نجات نہیں پا سکے گا۔'' صحابہ کرام نے عرض کیا: یا رسول اللہ! کیا آپ بھی نہیں؟ فرمایا: ''نہ میں، بجز اس کے کہ اللہ تعالیٰ مجھے اپنی خاص رحمت اور فضل کی چادر میں ڈھانپ لے!''', 'بندے کو کبھی اپنے اعمال پر ناز اور گھمنڈ نہیں کرنا چاہیے؛ اعمال تو بندگی کی علامت ہیں، اصل نجات اور جنت اللہ کے بے پایاں فضل و کرم سے ہی نصیب ہوگی۔', '[{"word":"سَدِّدُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو فاعل"},{"word":"لَنْ","role":"حرف نفي ونصب واستقبال","sign":"مبني على السكون","detail":"ينجو فعل مضارع منصوب بالفتحة"}]', '["أخرجه مسلم في صحيحه (2816)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Aim for accuracy and moderation, and know that none of you will be saved merely by his actions.'' They said: ''Not even you, O Messenger of Allah?'' He said: ''Not even me, unless Allah envelops me in His mercy and grace.''","ar":"النجاة ودخول الجنة برحمة الله وفضله، والأعمال أسباب وأمارات للقبول."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch9_tafakkur', 'kharji_lib_0261', 8, 'بَابُ التَّفَكُّرِ فِي فَنَاءِ الدُّنْيَا وَعَظِيمِ خَلْقِ اللَّهِ', 'باب 9: دنیا کی ناپائیداری اور اللہ کی مخلوقات میں تفکر');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_9_1', 'riyad_ch9_tafakkur', 'kharji_lib_0261', 0, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللَّهِ ﷺ بِمَنْكِبَيَّ فَقَالَ: «كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ، أَوْ عَابِرُ سَبِيلٍ». وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: «إِذَا أَمْسَيْتَ فَلَا تَنْتَظِرِ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلَا تَنْتَظِرِ المَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ، وَمِنْ حَيَاتِكَ لِمَوْتِكَ».', 'حضرت عبداللہ بن عمر رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ ﷺ نے میرے دونوں کندھوں کو پکڑ کر ارشاد فرمایا: ''دنیا میں اس طرح رہو گویا تم کوئی اجنبی پردیسی ہو، یا راستہ طے کرنے والے مسافر ہو۔'' اور حضرت ابن عمر فرمایا کرتے تھے: جب شام ہو جائے تو صبح کا انتظار نہ کرو، اور جب صبح ہو جائے تو شام کا انتظار نہ کرو؛ اور اپنی صحت کے زمانے میں بیماری کے وقت کے لیے، اور اپنی زندگی میں موت کے لیے تیاری کر لو۔', 'مسافر منزل پر پہنچنے کے لیے سامان ہلکا رکھتا ہے۔ اسی طرح مومن کو دنیا میں مستقل گھر نہیں بسانا چاہیے بلکہ آخرت کی ابدی منزل کے لیے توشہ تیار کرنا چاہیے۔', '[{"word":"كُنْ","role":"فعل أمر ناقص","sign":"سكون","detail":"واسمها ضمير مستتر تقديره أنت"},{"word":"كَأَنَّكَ","role":"كأن حرف تشبيه ونصب","sign":"مبني على الفتح","detail":"والكاف اسمها وغريب خبرها"}]', '["أخرجه البخاري في صحيحه (6416)."]', '{"en":"Ibn ''Umar narrated: Allah''s Messenger ﷺ took me by my shoulders and said: ''Be in this world as if you were a stranger or a wayfarer.'' And Ibn ''Umar used to say: ''When evening comes, do not anticipate the morning...''","ar":"الزهد في الدنيا وقصر الأمل والاستعداد للمصير الأخروي."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_9_2', 'riyad_ch9_tafakkur', 'kharji_lib_0261', 1, 'وَعَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَامَ رَسُولُ اللَّهِ ﷺ عَلَى حَصِيرٍ فَقَامَ وَقَدْ أَثَّرَ فِي جَنْبِهِ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، لَوِ اتَّخَذْنَا لَكَ وِطَاءً؟ فَقَالَ: «مَا لِي وَلِلدُّنْيَا؟ مَا أَنَا فِي الدُّنْيَا إِلَّا كَرَاكِبٍ اسْتَظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ ایک چٹائی پر سوئے، جب آپ بیدار ہوئے تو آپ کے مبارک جسم پر چٹائی کے نشانات پڑ گئے تھے۔ ہم نے عرض کیا: یا رسول اللہ! کاش ہم آپ کے لیے کوئی نرم بستر بچھا دیا کرتے؟ آپ ﷺ نے ارشاد فرمایا: ''مجھے دنیا سے کیا سروکار؟ میری اور دنیا کی مثال تو بس اس سوار کی سی ہے جس نے چلتے ہوئے کسی درخت کے سائے میں کچھ دیر آرام کیا، پھر روانہ ہوا اور درخت کو وہیں چھوڑ گیا۔''', 'یہ شان ہے شہنشاہِ کونین ﷺ کی کہ قیصر و کسریٰ کے محلات سونے چاندی سے آراستہ تھے اور رحمتِ عالم کے پہلوئے اقدس پر بوریا کے نشان پڑتے تھے۔ یہ زہد امت کو سادگی کا درس دیتا ہے۔', '[{"word":"مَا","role":"اسم استفهام مبني","sign":"سكون","detail":"في محل رفع مبتدأ وللدنيا جار ومجرور خبره"},{"word":"إِلَّا","role":"أداة استثناء ملغاة","sign":"مبني","detail":"أداة حصر والقصر"}]', '["أخرجه الترمذي (2377) وقال: حديث حسن صحيح."]', '{"en":"Abdullah bin Mas''ud reported: The Messenger of Allah ﷺ slept on a straw mat and stood up with marks on his side. We said: ''O Messenger of Allah, if only we prepared a soft bedding for you?'' He replied: ''What do I have to do with this world? My example in this world is like a rider who shades under a tree, then leaves it behind.''","ar":"ضرب المثل النبوي في زهد النبي الأكرم وعلو همته عن حطام الدنيا."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch10_mubadarah', 'kharji_lib_0261', 9, 'بَابُ المُبَادَرَةِ إِلَى الخَيْرَاتِ وَالمُسَارَعَةِ فِيهَا', 'باب 10: نیکیوں میں سبقت اور وقت کی قدر و قیمت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_10_1', 'riyad_ch10_mubadarah', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «بَادِرُوا بِالأَعْمَالِ فِتَناً كَقِطَعِ اللَّيْلِ المُظْلِمِ، يُصْبِحُ الرَّجُلُ مُؤْمِناً وَيُمْسِي كَافِراً، أَوْ يُمْسِي مُؤْمِناً وَيُصْبِحُ كَافِراً، يَبِيعُ دِينَهُ بِعَرَضٍ مِنَ الدُّنْيَا».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تاریک رات کے ٹکڑوں کی مانند فتنوں کے امڈ آنے سے پہلے پہلے نیک اعمال کرنے میں جلدی کر لو! فتنوں کا یہ حال ہوگا کہ آدمی صبح مومن ہوگا اور شام کو کافر ہو جائے گا، یا شام کو مومن ہوگا اور صبح کافر ہو جائے گا؛ لوگ دنیا کے حقیر ساز و سامان کے بدلے اپنا دین بیچ ڈالیں گے۔''', 'فتنوں کے دور میں ایمان کی حفاظت کا واحد ڈھال نیک اعمال اور سنت کی پیروی ہے۔ وقت ضائع کرنا اور توبہ میں تاخیر انسان کو گمراہی کی دلدل میں دھکیل سکتی ہے۔', '[{"word":"بَادِرُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"},{"word":"فِتَناً","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"وعلامة نصبه الفتحة الظاهرة"}]', '["أخرجه مسلم في صحيحه (118)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Hasten to do good deeds before trials emerge like patches of dark night, wherein a man wakes up as a believer and becomes an unbeliever by evening... selling his religion for a paltry worldly gain.''","ar":"التحذير من فتن آخر الزمان والحث على التمسك بالأعمال الصالحة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_10_2', 'riyad_ch10_mubadarah', 'kharji_lib_0261', 1, 'وَعَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ: الصِّحَّةُ وَالفَرَاغُ».', 'حضرت عبداللہ بن عباس رضی اللہ عنہما نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''دو نعمتیں ایسی ہیں جن کے معاملے میں بہت سے لوگ بڑے خسارے اور دھوکے میں مبتلا ہیں: ایک صحت اور دوسری فراغت (فارغ وقت)۔''', 'انسان جب تندرست اور فارغ ہوتا ہے تو غفلت برتتا ہے، اور جب بیماری یا مصروفیات گھیر لیتی ہیں تو حسرت کرتا ہے۔ طالب علم کے لیے صحت اور فرصت سب سے بڑی دولت ہے۔', '[{"word":"نِعْمَتَانِ","role":"مبتدأ مرفوع","sign":"ألف المثنى","detail":"وعلامة رفعه الألف لأنه مثنى"},{"word":"مَغْبُونٌ","role":"نعت أو خبر ثان","sign":"ضمة لفظاً","detail":"اسم مفعول ونائب فاعله كثير"}]', '["أخرجه البخاري في صحيحه (6412)."]', '{"en":"Ibn ''Abbas reported that the Messenger of Allah ﷺ said: ''There are two blessings in which many people are in great loss: health and free time.''","ar":"بيان قيمة الوقت والصحة واغتنامهما في طاعة الله قبل فوات الأوان."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch11_mujahadah', 'kharji_lib_0261', 10, 'بَابُ المُجَاهَدَةِ وَمُحَاسَبَةِ النَّفْسِ', 'باب 11: نفس کے خلاف جہاد اور روزمرہ محاسبہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_11_1', 'riyad_ch11_mujahadah', 'kharji_lib_0261', 0, 'عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «الكَيِّسُ مَنْ دَانَ نَفْسَهُ وَعَمِلَ لِمَا بَعْدَ المَوْتِ، وَالعَاجِزُ مَنْ أَتْبَعَ نَفْسَهُ هَوَاهَا وَتَمَنَّى عَلَى اللَّهِ».', 'حضرت شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''عقلمند اور زیرک وہ شخص ہے جس نے اپنے نفس کا محاسبہ کیا اور موت کے بعد کی زندگی کے لیے تیاری کی؛ اور بے بس اور کمزور وہ شخص ہے جس نے اپنے نفس کو خواہشات کے پیچھے لگا دیا اور اللہ سے جھوٹی امیدیں باندھتا رہا۔''', 'محاسبہ نفس کا مطلب ہے کہ انسان ہر شام سونے سے پہلے اپنے اعمال کا جائزہ لے کہ آج کے دن اللہ کا کتنا حق ادا کیا اور کتنی نافرمانی کی۔ بغیر عمل کے صرف امیدیں باندھنا خود فریبی ہے۔', '[{"word":"الكَيِّسُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"مرفوع بالابتداء"},{"word":"مَنْ","role":"اسم موصول خبر المبتدأ","sign":"مبني على السكون","detail":"في محل رفع خبر"}]', '["أخرجه الترمذي (2459) وقال: حديث حسن."]', '{"en":"Shaddad bin Aws reported that the Prophet ﷺ said: ''The wise person is one who holds himself accountable and works for what comes after death; and the helpless person is one who follows his desires and still hopes from Allah.''","ar":"المحاسبة الدائمة للنفس وحذر الركون إلى التمني الباطل دون عمل."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_11_2', 'riyad_ch11_mujahadah', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الجَنَّةُ بِالمَكَارِهِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جہنم کو دل لبھانے والی خواہشات سے ڈھانپ دیا گیا ہے، اور جنت کو مشقت اور ناپسندیدہ چیزوں سے گھیر دیا گیا ہے۔''', 'جنت کا راستہ آسان نہیں، اس میں فجر کی ٹھنڈک میں بیداری، حلال و حرام کی تمیز، اور نفس کی خواہشات کی قربانی درکار ہے۔ جبکہ جہنم کا راستہ وقتی لذتوں اور گناہوں سے مزین ہے۔', '[{"word":"حُجِبَتِ","role":"فعل ماض مبني للمجهول","sign":"مبني على الفتح","detail":"والتاء للتأنيث والنار نائب فاعل مرفوع"}]', '["متفق عليه: البخاري (6487)، ومسلم (2822)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''The Hellfire is veiled behind desires, and Paradise is veiled behind hardships.''","ar":"طريق الجنة محفوف بالصبر على الطاعات واجتناب المغريات المحرمة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch12_ilm', 'kharji_lib_0261', 11, 'بَابُ فَضْلِ العِلْمِ وَطَلَبِهِ وَبَثِّهِ فِي النَّاسِ', 'باب 12: طلبِ علم، فقاہت اور اشاعتِ علم کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_12_1', 'riyad_ch12_ilm', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ سَلَكَ طَرِيقاً يَلْتَمِسُ فِيهِ عِلْماً، سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقاً إِلَى الجَنَّةِ».', 'حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو شخص علم دین حاصل کرنے کے لیے کسی راستے پر نکلتا ہے، تو اللہ تعالیٰ اس کے بدلے اس کے لیے جنت کا راستہ آسان فرما دیتا ہے۔''', 'طالب علم کے اٹھنے والے تمام قدم جنت کی طرف اٹھتے ہیں۔ فرشتے طالب علم کے اکرام میں اپنے پر بچھاتے ہیں اور سمندر کی مچھلیاں تک اس کے لیے استغفار کرتی ہیں۔', '[{"word":"مَنْ","role":"اسم شرط جازم","sign":"مبني على السكون","detail":"في محل رفع مبتدأ"},{"word":"سَلَكَ","role":"فعل ماض في محل جزم","sign":"فعل الشرط","detail":"والفاعل مستتر تقديره هو"}]', '["أخرجه مسلم في صحيحه (2699)."]', '{"en":"Abu Hurairah reported that the Messenger of Allah ﷺ said: ''Whoever treads a path seeking knowledge, Allah will make easy for him thereby a path to Paradise.''","ar":"بيان عظمة فضل طلب العلم الشرعي وتيسيره لطريق الجنة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_12_2', 'riyad_ch12_ilm', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «فَضْلُ العَالِمِ عَلَى العَابِدِ كَفَضْلِي عَلَى أَدْنَاكُمْ»، ثُمَّ قَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ وَمَلَائِكَتَهُ وَأَهْلَ السَّمَاوَاتِ وَالأَرْضِ حَتَّى النَّمْلَةَ فِي جُحْرِهَا وَحَتَّى الحُوتَ لَيُصَلُّونَ عَلَى مُعَلِّمِ النَّاسِ الخَيْرَ».', 'حضرت ابو امامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''عالم کی فضیلت عابد پر ایسی ہے جیسے میری فضیلت تم میں سے ادنیٰ ترین شخص پر!'' پھر آپ ﷺ نے فرمایا: ''بے شک اللہ تعالیٰ، اس کے فرشتے، تمام آسمان اور زمین کی مخلوقات، یہاں تک کہ چیونٹی اپنے سوراخ میں اور مچھلیاں سمندر میں اس شخص کے لیے خیر اور رحمت کی دعا کرتی ہیں جو لوگوں کو بھلائی کی تعلیم دیتا ہے۔''', 'عابد کی عبادت کا فائدہ صرف اس کی اپنی ذات تک محدود ہوتا ہے، جبکہ عالم کا نفع پوری انسانیت اور کائنات کے نظام کو مستحکم کرتا ہے، اس لیے ساری کائنات اس کے حق میں دعا گو رہتی ہے۔', '[{"word":"فَضْلُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والعالم مضاف إليه"},{"word":"كَفَضْلِي","role":"شبه جملة خبر المبتدأ","sign":"كسرة مقدرة","detail":"الكاف حرف جر وفضلي مجرور بالكسرة المقدرة"}]', '["أخرجه الترمذي (2685) وقال: حديث حسن صحيح."]', '{"en":"Abu Umamah reported that the Prophet ﷺ said: ''The superiority of the scholar over the devout worshipper is like my superiority over the lowest of you... Verily, Allah, His angels, the inhabitants of the heavens and earth, even the ant in its hole and the fish send blessings upon the teacher of good to mankind.''","ar":"عظم شأن المعلم والداعية إلى الله في ميزان الشريعة المطهرة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch13_quran', 'kharji_lib_0261', 12, 'بَابُ فَضْلِ قِرَاءَةِ القُرْآنِ الكَرِيمِ وَتَدَبُّرِهِ', 'باب 13: تلاوتِ قرآن، تدبر اور اس کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_13_1', 'riyad_ch13_quran', 'kharji_lib_0261', 0, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «خَيْرُكُمْ مَنْ تَعَلَّمَ القُرْآنَ وَعَلَّمَهُ».', 'حضرت عثمان بن عفان رضی اللہ عنہ نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تم میں سے سب سے بہترین اور افضل وہ شخص ہے جس نے خود قرآن سیکھا اور دوسروں کو سکھایا۔''', 'قرآن مجید کلامِ الٰہی ہے۔ کلام کا شرف متکلم کے شرف کے تابع ہوتا ہے۔ لہٰذا جو شخص قرآن کو پڑھنے اور پڑھانے میں اپنی زندگی صرف کرتا ہے وہ امت کا سب سے معزز فرد ہے۔', '[{"word":"خَيْرُكُمْ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"اسم تفضيل حذفت همزته لكثرة الاستعمال"},{"word":"مَنْ","role":"اسم موصول خبر المبتدأ","sign":"مبني على السكون","detail":"في محل رفع خبر"}]', '["أخرجه البخاري في صحيحه (5027)."]', '{"en":"''Uthman bin ''Affan narrated that the Messenger of Allah ﷺ said: ''The best amongst you are those who learn the Quran and teach it to others.''","ar":"أفضل الناس من جمع بين تعلم كتاب الله وتعليمه للناس ابتغاء وجه الله."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_13_2', 'riyad_ch13_quran', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «اقْرَؤُوا القُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ القِيَامَةِ شَفِيعاً لِأَصْحَابِهِ».', 'حضرت ابو امامہ رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''قرآن مجید کی تلاوت کیا کرو، کیونکہ وہ قیامت کے دن اپنے پڑھنے والوں کے لیے شفاعت کرنے والا بن کر آئے گا۔''', 'قیامت کے اس دن جب ہر کوئی نفسی نفسی پکار رہا ہوگا، قرآنِ مجید اپنے پڑھنے اور اس پر عمل کرنے والے کے حق میں بارگاہِ الٰہی میں جھگڑا کرے گا اور اسے بخشوا کر جنت میں لے جائے گا۔', '[{"word":"اقْرَؤُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"},{"word":"شَفِيعاً","role":"حال منصوب","sign":"فتحة لفظاً","detail":"حال من الضمير في يأتي"}]', '["أخرجه مسلم في صحيحه (804)."]', '{"en":"Abu Umamah reported: I heard the Messenger of Allah ﷺ saying: ''Recite the Quran, for indeed it will come on the Day of Resurrection as an intercessor for its companions.''","ar":"شفاعة القرآن الكريم لأهله الذين كانوا يتلونه ويعملون بأحكامه في الدنيا."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch14_dhikr', 'kharji_lib_0261', 13, 'بَابُ فَضْلِ الذِّكْرِ وَالحَثِّ عَلَيْهِ وَمَجَالِسِ الذَّاكِرِينَ', 'باب 14: ذکرِ الٰہی، تسبیح و تہلیل اور ذاکرین کی مجالس');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_14_1', 'riyad_ch14_dhikr', 'kharji_lib_0261', 0, 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ، مَثَلُ الحَيِّ وَالمَيِّتِ».', 'حضرت ابوموسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''اپنے رب کو یاد کرنے والے اور یاد نہ کرنے والے کی مثال ایسی ہے جیسے زندہ اور مردہ کی مثال!''', 'جسم کی زندگی سانس اور خون کی روانی سے ہے اور روح کی زندگی اللہ کے ذکر سے ہے۔ جس دل میں ذکرِ الٰہی نہ ہو وہ بظاہر چلتا پھرتا جسم ہے مگر حقیقت میں ایک متحرک قبر ہے۔', '[{"word":"مَثَلُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والذي اسم موصول مضاف إليه"},{"word":"الحَيِّ","role":"مضاف إليه مجرور","sign":"كسرة لفظاً","detail":"مثل الثاني خبر المبتدأ"}]', '["متفق عليه: البخاري (6407)، ومسلم (777)."]', '{"en":"Abu Musa Al-Ash''ari reported that the Prophet ﷺ said: ''The example of the one who remembers his Lord and the one who does not remember his Lord is like that of the living and the dead.''","ar":"حياة القلوب الحقيقية بذكر الله، والغفلة موت روحي وإن كان الجسد حياً."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_14_2', 'riyad_ch14_dhikr', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي المِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ العَظِيمِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''دو کلمے ایسے ہیں جو زبان پر بالکل ہلکے پھلکے ہیں، مگر میزانِ عمل میں بے حد وزنی ہیں، اور رحمان کو نہایت محبوب ہیں: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ العَظِيمِ (اللہ پاک ہے اپنی تعریفوں کے ساتھ، اللہ پاک ہے جو بڑی عظمت والا ہے)''۔', 'امام بخاری نے اپنی صحیح کا اختتام اسی مبارک حدیث پر فرمایا ہے۔ یہ تسبیح اللہ تعالیٰ کی عظمت، تنزیہ اور حمد کا ایسا تحفہ ہے جو بندے کو رحمان کا محبوب بنا دیتا ہے۔', '[{"word":"كَلِمَتَانِ","role":"مبتدأ مرفوع","sign":"ألف المثنى","detail":"وعلامة رفعه الألف لأنه مثنى"},{"word":"خَفِيفَتَانِ","role":"نعت أول مرفوع","sign":"ألف المثنى","detail":"والخبر جملة: سبحان الله"}]', '["متفق عليه: البخاري (6682)، ومسلم (2694)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Two words are light on the tongue, heavy on the Balance, and beloved to the Most Merciful: Subhan Allahi wa bihamdihi, Subhan Allahil-''Azim.''","ar":"ختم به الإمام البخاري صحيحه الشريف، وهو من أجمع الأذكار فضلاً وأجراً."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch15_salawat', 'kharji_lib_0261', 14, 'بَابُ فَضْلِ الصَّلَاةِ عَلَى النَّبِيِّ ﷺ وَآدَابِهَا', 'باب 15: نبی کریم ﷺ پر درود و سلام کے فضائل و برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_15_1', 'riyad_ch15_salawat', 'kharji_lib_0261', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ صَلَّى عَلَيَّ صَلَاةً، صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً».', 'حضرت عبداللہ بن عمرو بن العاص رضی اللہ عنہما نے فرمایا کہ انہوں نے رسول اللہ ﷺ کو فرماتے سنا: ''جو شخص مجھ پر ایک مرتبہ درود شریف بھیجتا ہے، اللہ تعالیٰ اس کے بدلے اس پر دس رحمتیں نازل فرماتا ہے۔''', 'خالقِ کائنات کی ایک رحمت دونوں جہانوں کی تمام پریشانیوں کو ختم کرنے کے لیے کافی ہے، اور درود پڑھنے والے کو ہر ایک درود کے بدلے دس رحمتیں، دس درجات کی بلندی اور دس گناہوں کی معافی نصیب ہوتی ہے۔', '[{"word":"مَنْ","role":"اسم شرط جازم","sign":"مبني على السكون","detail":"في محل رفع مبتدأ"},{"word":"عَشْراً","role":"مفعول مطلق نائب عن المصدر","sign":"فتحة لفظاً","detail":"تقديره: صلوات عشراً"}]', '["أخرجه مسلم في صحيحه (384)."]', '{"en":"''Abdullah bin ''Amr bin Al-''As reported that he heard the Messenger of Allah ﷺ saying: ''Whoever sends blessings upon me once, Allah sends blessings upon him ten times thereby.''","ar":"عظيم فضل الصلاة على النبي المصطفى ﷺ وثمراتها العاجلة والآجلة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_15_2', 'riyad_ch15_salawat', 'kharji_lib_0261', 1, 'وَعَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أَوْلَى النَّاسِ بِي يَوْمَ القِيَامَةِ أَكْثَرُهُمْ عَلَيَّ صَلَاةً».', 'حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''قیامت کے دن لوگوں میں مجھ سے سب سے زیادہ قریب اور شفاعت کا حق دار وہ شخص ہوگا جو مجھ پر سب سے زیادہ کثرت سے درود شریف پڑھا کرتا تھا۔''', 'قیامت کے محشر میں آقائے نامدار ﷺ کی شفاعت اور حوضِ کوثر پر ان کا قرب سب سے بڑی کامیابی ہے۔ کثرتِ درود انسان کے دل کو عشقِ رسول کے نور سے منور کرتی ہے۔', '[{"word":"أَوْلَى","role":"مبتدأ مرفوع","sign":"ضمة مقدرة","detail":"اسم تفضيل والناس مضاف إليه"},{"word":"أَكْثَرُهُمْ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف وهم ضمير متصل مضاف إليه"}]', '["أخرجه الترمذي (484) وقال: حديث حسن."]', '{"en":"Ibn Mas''ud reported that the Messenger of Allah ﷺ said: ''The closest of people to me on the Day of Resurrection will be those who sent the most blessings upon me.''","ar":"القرب والوجاهة عند النبي الأعظم ﷺ رهن بكثرة الصلاة والسلام عليه."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch16_zuhd', 'kharji_lib_0261', 15, 'بَابُ الزُّهْدِ فِي الدُّنْيَا وَفَضْلِ القَنَاعَةِ', 'باب 16: زہد فی الدنیا، قناعت اور فقرِ اختیاری کی فضیلت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_16_1', 'riyad_ch16_zuhd', 'kharji_lib_0261', 0, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ العَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «قَدْ أَفْلَحَ مَنْ أَسْلَمَ، وَرُزِقَ كَفَافاً، وَقَنَّعَهُ اللَّهُ بِمَا آتَاهُ».', 'حضرت عبداللہ بن عمرو بن العاص رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''کامیاب ہو گیا وہ شخص جس نے اسلام قبول کیا، اور اسے بقدرِ ضرورت (کفاف) روزی نصیب ہوئی، اور اللہ نے اسے جو کچھ دیا اس پر اسے قناعت عطا فرما دی''۔', 'اصل غنا اور دولت دل کی قناعت کا نام ہے۔ جس انسان کے پاس اسلام، بنیادی ضروریات اور راضی بہ رضا رہنے والا دل ہو، وہ دنیا کا سب سے بڑا بادشاہ ہے۔', '[{"word":"قَدْ","role":"حرف تحقيق","sign":"مبني على السكون","detail":"تدخل على الماضي فتفيده التحقيق"},{"word":"كَفَافاً","role":"مفعول به ثان","sign":"فتحة لفظاً","detail":"لفعل رُزق المبني للمجهول"}]', '["أخرجه مسلم في صحيحه (1054)."]', '{"en":"''Abdullah bin ''Amr reported that the Messenger of Allah ﷺ said: ''Successful indeed is he who embraces Islam, is provided with sufficient sustenance, and Allah makes him content with what He gave him.''","ar":"الفلاح الحقيقي في الإسلام والكفاف والقناعة برزق الله."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_16_2', 'riyad_ch16_zuhd', 'kharji_lib_0261', 1, 'وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «لَيْسَ الغِنَى عَنْ كَثْرَةِ العَرَضِ، وَلَكِنَّ الغِنَى غِنَى النَّفْسِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''امیری اور تونگری دنیاوی ساز و سامان اور مال و دولت کی کثرت کا نام نہیں ہے، بلکہ حقیقی امیری دل کا غنی ہونا ہے۔''', 'بہت سے ارب پتی دل کے غریب اور لالچی ہوتے ہیں، جبکہ جھونپڑی میں بیٹھنے والا درویش اپنے دل کے استغنا کی وجہ سے دنیا سے بے پرواہ ہوتا ہے۔ اصل دولت باطنی قناعت ہے۔', '[{"word":"لَيْسَ","role":"فعل ماض ناقص","sign":"مبني على الفتح","detail":"يرفع الاسم وينصب الخبر"},{"word":"الغِنَى","role":"اسم ليس مرفوع","sign":"ضمة مقدرة","detail":"مرفوع بضمة مقدرة على الألف للتعذر"}]', '["متفق عليه: البخاري (6446)، ومسلم (1051)."]', '{"en":"Abu Hurairah reported that the Prophet ﷺ said: ''Richness is not in having many possessions, but true richness is the richness of the soul (contentment).''","ar":"الغنى الحقيقي غنى القلب والقناعة وعدم التطلع إلى ما في أيدي الناس."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch17_khuluq', 'kharji_lib_0261', 16, 'بَابُ حُسْنِ الخُلُقِ وَالحِلْمِ وَالرِّفْقِ', 'باب 17: حسنِ اخلاق، حلم اور نرم مزاجی کی برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_17_1', 'riyad_ch17_khuluq', 'kharji_lib_0261', 0, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «مَا مِنْ شَيْءٍ أَثْقَلُ فِي مِيزَانِ المُؤْمِنِ يَوْمَ القِيَامَةِ مِنْ حُسْنِ الخُلُقِ، وَإِنَّ اللَّهَ يُبْغِضُ الفَاحِشَ البَذِيءَ».', 'حضرت ابو درداء رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''قیامت کے دن مومن کے پلڑے میں حسنِ اخلاق سے زیادہ وزنی کوئی چیز نہیں ہوگی، اور بے شک اللہ تعالیٰ بے حیا اور بدزبان شخص سے سخت نفرت فرماتا ہے۔''', 'نرمی، خندہ پیشانی، درگزر اور دوسروں کے ساتھ ہمدردی کا سلوک انسان کو نفل نماز اور نفل روزے رکھنے والوں کے درجے تک پہنچا دیتا ہے۔', '[{"word":"مَا","role":"نافية تعمل عمل ليس أو مهملة","sign":"مبني","detail":"من شيء مجرور لفظاً مرفوع محلاً مبتدأ"},{"word":"أَثْقَلُ","role":"خبر مرفوع","sign":"ضمة لفظاً","detail":"اسم تفضيل ممنوع من الصرف"}]', '["أخرجه الترمذي (2002) وقال: حديث حسن صحيح."]', '{"en":"Abu Ad-Darda'' reported that the Prophet ﷺ said: ''Nothing is heavier upon the Scale of a believer on the Day of Resurrection than good character. Indeed, Allah hates the shameless and obscene person.''","ar":"حسن الخلق أثقل شيء في ميزان الأعمال الصالحة يوم القيامة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_17_2', 'riyad_ch17_khuluq', 'kharji_lib_0261', 1, 'وَعَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ، وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ».', 'ام المؤمنین حضرت عائشہ صدیقہ رضی اللہ عنہا نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''نرمی جس چیز میں بھی شامل ہوتی ہے اسے خوبصورت اور پروقار بنا دیتی ہے، اور جس چیز سے نرمی نکال لی جائے وہ اسے عیب دار اور بدنما بنا دیتی ہے۔''', 'دعوتِ دین، تدریس اور گھریلو زندگی میں سختی دلوں کو توڑ دیتی ہے جبکہ حلم اور شفقت پتھر دلوں کو بھی موم کر دیتے ہیں۔ نرمی مومن کا خاصہ ہے۔', '[{"word":"إِنَّ","role":"حرف توكيد ونصب","sign":"مبني","detail":"الرفق اسمها منصوب بالفتحة"},{"word":"زَانَهُ","role":"فعل ماض ومفعول به","sign":"مبني على الفتح","detail":"والفاعل مستتر والجملة في محل نصب خبر كان"}]', '["أخرجه مسلم في صحيحه (2594)."]', '{"en":"''Aishah reported: I heard the Messenger of Allah ﷺ saying: ''Kindness is not found in anything except that it beautifies it, and it is not removed from anything except that it mars it.''","ar":"الرفق بالناس واللين في المعاملة زينة لكل قول وفعل وعمل."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch18_birr', 'kharji_lib_0261', 17, 'بَابُ بِرِّ الوَالِدَيْنِ وَصِلَةِ الأَرْحَامِ', 'باب 18: والدین کے حقوق، حسنِ سلوک اور صلہ رحمی');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_18_1', 'riyad_ch18_birr', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ».', 'حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا کہ ایک شخص نے رسول اللہ ﷺ کی خدمت میں حاضر ہو کر عرض کیا: یا رسول اللہ! لوگوں میں میرے اچھے سلوک کا سب سے زیادہ حق دار کون ہے؟ آپ ﷺ نے فرمایا: ''تمہاری ماں۔'' اس نے پوچھا: پھر کون؟ فرمایا: ''تمہاری ماں۔'' پوچھا: پھر کون؟ فرمایا: ''تمہاری ماں۔'' پوچھا: پھر کون؟ فرمایا: ''پھر تمہارا باپ۔''', 'ماں کی مشقت اور قربانی بے مثال ہے۔ اسی لیے شریعت نے حسنِ صحبت اور خدمت میں ماں کے حق کو باپ پر تین گنا ترجیح عطا فرمائی ہے۔', '[{"word":"مَنْ","role":"اسم استفهام مبني","sign":"سكون","detail":"في محل رفع مبتدأ أو خبر مقدم"},{"word":"أُمُّكَ","role":"خبر لمبتدأ محذوف","sign":"ضمة لفظاً","detail":"تقديره: أحق الناس أمك"}]', '["متفق عليه: البخاري (5971)، ومسلم (2548)."]', '{"en":"Abu Hurairah reported: A man came to Allah''s Messenger ﷺ and said: ''O Messenger of Allah! Who is most deserving of my fine companionship?'' He replied: ''Your mother.'' The man asked: ''Then who?'' He said: ''Your mother.'' The man asked: ''Then who?'' He said: ''Your mother.'' The man asked: ''Then who?'' He said: ''Then your father.''","ar":"تقديم حق الوالدة على الوالد لعظيم تضحيتها في الحمل والولادة والرضاع."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_18_2', 'riyad_ch18_birr', 'kharji_lib_0261', 1, 'وَعَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ».', 'حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو شخص یہ پسند کرتا ہو کہ اس کے رزق میں وسعت و برکت کی جائے اور اس کی عمر دراز کر دی جائے (اس کا نام باقی رہے)، تو اسے چاہیے کہ اپنے رشتہ داروں کے ساتھ صلہ رحمی اور حسن سلوک کرے۔''', 'صلہ رحمی سے انسان کے رزق میں خیر و برکت پیدا ہوتی ہے اور اس کی عمر میں نیک اعمال کی توفیق کے ذریعے درازی عطا فرمائی جاتی ہے۔ قطع رحمی نحوست کا سبب ہے۔', '[{"word":"فَلْيَصِلْ","role":"اللام لام الأمر والفعل مجزوم","sign":"سكون","detail":"مجزوم بلام الأمر والفاعل ضمير مستتر تقديره هو"},{"word":"رَحِمَهُ","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"وهو مضاف والهاء مضاف إليه"}]', '["متفق عليه: البخاري (5986)، ومسلم (2557)."]', '{"en":"Anas bin Malik reported that the Messenger of Allah ﷺ said: ''Whoever loves that his sustenance be expanded and his lifespan prolonged, let him maintain the ties of kinship.''","ar":"صلة الرحم سبب للبركة في العمر والرزق والتوفيق في الحياة."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch19_lisan', 'kharji_lib_0261', 18, 'بَابُ حِفْظِ اللِّسَانِ عَنِ الغِيبَةِ وَالنَّمِيمَةِ', 'باب 19: حفظِ لسان، غیبت اور بدگوئی سے حفاظت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_19_1', 'riyad_ch19_lisan', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَاليَوْمِ الآخِرِ فَلْيَقُلْ خَيْراً أَوْ لِيَصْمُتْ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہو، اسے چاہیے کہ یا تو بھلی اور اچھی بات کہے، ورنہ خاموش رہے!''', 'خاموشی میں سلامتی ہے۔ انسان کی اکثر خطائیں اور گناہ زبان کی بے احتیاطی سے سرزد ہوتے ہیں۔ اس لیے بلا ضرورت گفتگو سے بچنا اور صرف خیر کا کلمہ بولنا مومن کی علامت ہے۔', '[{"word":"فَلْيَقُلْ","role":"اللام لام الأمر والفعل مجزوم","sign":"سكون","detail":"جواب الشرط مقترن بالفاء"},{"word":"خَيْراً","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"وعلامة نصبه الفتحة الظاهرة"}]', '["متفق عليه: البخاري (6018)، ومسلم (47)."]', '{"en":"Abu Hurairah reported that the Prophet ﷺ said: ''Whoever believes in Allah and the Last Day, let him speak good or remain silent.''","ar":"قاعدة شرعية جامعة في ضبط المنطق وتطهير اللسان عن اللغو والآثام."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_19_2', 'riyad_ch19_lisan', 'kharji_lib_0261', 1, 'وَعَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنْ يَضْمَنْ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنْ لَهُ الجَنَّةَ».', 'حضرت سہل بن سعد رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جو شخص مجھے اپنے دو جبڑوں کے درمیان کی چیز (زبان) اور اپنی دو ٹانگوں کے درمیان کی چیز (شرمگاہ) کی حفاظت کی ضمانت دے، میں اس کے لیے جنت کی ضمانت دیتا ہوں۔''', 'انسان کو ہلاکت میں ڈالنے والے دو بڑے دروازے زبان کی برائیاں (جھوٹ، غیبت، تہمت) اور شہوت کی بدکاریاں ہیں۔ جو ان دونوں کو شریعت کے تابع کر لے، نبی کریم ﷺ اس کے جنتی ہونے کے ضامن ہیں۔', '[{"word":"مَنْ","role":"اسم شرط جازم","sign":"مبني","detail":"يضمن فعل الشرط مجزوم بالسكون"},{"word":"أَضْمَنْ","role":"جواب الشرط مجزوم","sign":"سكون","detail":"والفاعل ضمير مستتر تقديره أنا"}]', '["أخرجه البخاري في صحيحه (6474)."]', '{"en":"Sahl bin Sa''d reported that Allah''s Messenger ﷺ said: ''Whoever guarantees for me what is between his jaws (his tongue) and what is between his legs (his private parts), I guarantee for him Paradise.''","ar":"حفظ اللسان والفرج هما أعظم أسباب النجاة ودخول الجنان."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch20_amr_bil_maruf', 'kharji_lib_0261', 19, 'بَابُ الأَمْرِ بِالمَعْرُوفِ وَالنَّهْيِ عَنِ المُنْكَرِ', 'باب 20: امر بالمعروف، نہی عن المنکر اور اصلاحِ معاشرہ');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_20_1', 'riyad_ch20_amr_bil_maruf', 'kharji_lib_0261', 0, 'عَنْ أَبِي سَعِيدٍ الخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ رَأَى مِنْكُمْ مُنْكَراً فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الإِيمَانِ».', 'حضرت ابوسعید خدری رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: ''تم میں سے جو شخص کوئی برائی دیکھے تو اسے چاہیے کہ اپنے ہاتھ کی طاقت سے بدل دے؛ اگر اس کی طاقت نہ ہو تو اپنی زبان سے روکے؛ اور اگر اس کی بھی طاقت نہ ہو تو کم از کم اپنے دل سے اسے برا جانے، اور یہ ایمان کا کمزور ترین درجہ ہے۔''', 'معاشرے کو بگاڑ سے بچانے کے لیے برائی کے خلاف کھڑا ہونا ضروری ہے۔ حکمران ہاتھ سے، علماء زبان و قلم سے اور عوام دل سے برائی کو ناپسند کر کے اپنا دینی فریضہ نبھائیں۔', '[{"word":"مُنْكَراً","role":"مفعول به منصوب","sign":"فتحة لفظاً","detail":"لفعل رأى"},{"word":"فَلْيُغَيِّرْهُ","role":"اللام لام الأمر والفعل مجزوم","sign":"سكون","detail":"والهاء ضمير متصل مفعول به"}]', '["أخرجه مسلم في صحيحه (49)."]', '{"en":"Abu Sa''id Al-Khudri reported: I heard Allah''s Messenger ﷺ saying: ''Whoever among you sees an evil, let him change it with his hand; if he cannot, then with his tongue; if he cannot, then with his heart, and that is the weakest of faith.''","ar":"درجات إنكار المنكر بحسب القدرة والمصلحة الشرعية."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_20_2', 'riyad_ch20_amr_bil_maruf', 'kharji_lib_0261', 1, 'وَعَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ ﷺ قَالَ: «مَثَلُ القَائِمِ عَلَى حُدُودِ اللَّهِ وَالوَاقِعِ فِيهَا كَمَثَلِ قَوْمٍ اسْتَهَمُوا عَلَى سَفِينَةٍ، فَأَصَابَ بَعْضُهُمْ أَعْلَاهَا وَبَعْضُهُمْ أَسْفَلَهَا... فَقَالَ الَّذِينَ فِي أَسْفَلِهَا: لَوْ أَنَّا خَرَقْنَا فِي نَصِيبِنَا خَرْقاً وَلَمْ نُؤْذِ مَنْ فَوْقَنَا! فَإِنْ يَتْرُكُوهُمْ وَمَا أَرَادُوا هَلَكُوا جَمِيعاً، وَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ نَجَوْا وَنَجَوْا جَمِيعاً».', 'حضرت نعمان بن بشیر رضی اللہ عنہما سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: ''اللہ کے حدود و احکام کی پابندی کرنے والے اور ان کو توڑنے والے کی مثال ان مسافروں جیسی ہے جنہوں نے کشتی میں سوار ہونے کے لیے قرعہ ڈالا، تو بعض کو اوپری منزل ملی اور بعض کو نچلی منزل... نچلی منزل والوں نے سوچا: ہم نیچے کے حصے میں سوراخ کر لیں تاکہ اوپر والوں کو پانی لینے کے لیے تکلیف نہ دیں! اب اگر اوپر والے انہیں اس ارادے پر چھوڑ دیں گے تو پوری کشتی والے ڈوب کر ہلاک ہو جائیں گے؛ اور اگر وہ ان کا ہاتھ پکڑ لیں گے تو وہ بھی بچ جائیں گے اور سارے کے سارے محفوظ رہیں گے!''', 'یہ نبی کریم ﷺ کی دی ہوئی شاندار تمثیل ہے جو بتاتی ہے کہ معاشرہ ایک کشتی ہے؛ اگر گناہ گاروں کو کھلی چھوٹ دے دی جائے تو عذابِ الٰہی پورے معاشرے کو اپنی لپیٹ میں لے لیتا ہے۔', '[{"word":"القَائِمِ","role":"مضاف إليه مجرور","sign":"كسرة لفظاً","detail":"مثل مبتدأ والقائم مضاف إليه"},{"word":"جَمِيعاً","role":"حال منصوب","sign":"فتحة لفظاً","detail":"حال من واو الجماعة في هلكوا"}]', '["أخرجه البخاري في صحيحه (2493)."]', '{"en":"An-Nu''man bin Bashir reported that the Prophet ﷺ said: ''The example of the person abiding by Allah''s bounds and the one falling into them is like people who drew lots for places on a ship... If they prevent them from boring a hole, all will be saved.''","ar":"مثل بليغ في التضامن الاجتماعي وأهمية الأمر بالمعروف لحماية المجتمع من الغرق."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch21_qiyam_layl', 'kharji_lib_0261', 20, 'بَابُ فَضْلِ قِيَامِ اللَّيْلِ وَالتَّهَجُّدِ', 'باب 21: قیام اللیل، تہجد اور مناجاتِ سحر کی برکات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_21_1', 'riyad_ch21_qiyam_layl', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ المُحَرَّمُ، وَأَفْضَلُ الصَّلَاةِ بَعْدَ الفَرِيضَةِ صَلَاةُ اللَّيْلِ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''رمضان المبارک کے بعد سب سے افضل روزے اللہ کے مہینے محرم کے ہیں، اور فرض نمازوں کے بعد سب سے افضل نماز رات کی نماز (تہجد) ہے''۔', 'رات کی تاریکی اور تنہائی میں جب سب سو رہے ہوں، سجدہ ریز ہو کر مناجات کرنا بندۂ مومن کے قلب کو انوار سے بھر دیتا ہے۔ صلحاء و اولیاء کا سب سے بڑا ہتھیار نمازِ تہجد ہے۔', '[{"word":"أَفْضَلُ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والصيام مضاف إليه"},{"word":"صَلَاةُ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"في الجملة الثانية"}]', '["أخرجه مسلم في صحيحه (1163)."]', '{"en":"Abu Hurairah reported that the Messenger of Allah ﷺ said: ''The best fasting after Ramadan is the month of Allah, Al-Muharram; and the best prayer after the obligatory prayer is the night prayer (Tahajjud).''","ar":"فضل قيام الليل وقربه من الله تعالى لما فيه من الإخلاص والبعد عن الرياء."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_21_2', 'riyad_ch21_qiyam_layl', 'kharji_lib_0261', 1, 'وَعَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «أَيُّهَا النَّاسُ، أَفْشُوا السَّلَامَ، وَأَطْعِمُوا الطَّعَامَ، وَصَلُّوا بِاللَّيْلِ وَالنَّاسُ نِيَامٌ، تَدْخُلُوا الجَنَّةَ بِسَلَامٍ».', 'حضرت عبداللہ بن سلام رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے مدینہ منورہ تشریف لاتے ہی پہلا خطبہ دیتے ہوئے ارشاد فرمایا: ''اے لوگو! سلام کو عام کرو، (محتاجوں کو) کھانا کھلاؤ، اور رات کو جب لوگ سو رہے ہوں نماز پڑھو، تم سلامتی کے ساتھ جنت میں داخل ہو جاؤ گے!''', 'مدینہ طیبہ کی نئی اسلامی ریاست کی بنیاد ان چار ستونوں پر رکھی گئی: محبت کی اشاعت (سلام)، غریب پروری (اطعام)، رات کا تعلق باللہ (تہجد)، جس کا حتمی نتیجہ دائمی امن و جنت ہے۔', '[{"word":"أَيُّهَا","role":"منادى مبني على الضم","sign":"ضم","detail":"والهاء للتنبيه والناس بدل أو نعت"},{"word":"تَدْخُلُوا","role":"جواب الطلب مجزوم","sign":"حذف النون","detail":"علامة جزمه حذف النون"}]', '["أخرجه الترمذي (2485) وقال: حديث حسن صحيح."]', '{"en":"''Abdullah bin Salam reported that the Prophet ﷺ said: ''O people! Spread peace, feed the hungry, and pray at night while people are sleeping, and you will enter Paradise in peace.''","ar":"أول وصية نبوية في المدينة المنورة جمعت بين الإحسان إلى الخلق والتقرب إلى الخالق."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch22_adab_taam', 'kharji_lib_0261', 21, 'بَابُ آدَابِ الطَّعَامِ وَالشَّرَابِ وَالضِّيَافَةِ', 'باب 22: کھانے پینے اور مہمان نوازی کے مسنون آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_22_1', 'riyad_ch22_adab_taam', 'kharji_lib_0261', 0, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْتُ غُلَاماً فِي حِجْرِ رَسُولِ اللَّهِ ﷺ، وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي رَسُولُ اللَّهِ ﷺ: «يَا غُلَامُ، سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ».', 'حضرت عمر بن ابی سلمہ رضی اللہ عنہما نے فرمایا: میں رسول اللہ ﷺ کی زیرِ پرورش بچہ تھا اور کھانا کھاتے وقت میرا ہاتھ برتن میں چاروں طرف گھوما کرتا تھا، تو رسول اللہ ﷺ نے شفقت سے مجھ سے فرمایا: ''اے بچے! اللہ کا نام لو (بسم اللہ پڑھو)، اپنے دائیں ہاتھ سے کھاؤ، اور اپنے سامنے سے کھاؤ!''', 'کھانے پینے کے اس نبوی دستور میں برکت، طہارت اور شائستگی ہے۔ بسم اللہ سے برکت آتی ہے، دائیں ہاتھ سے سنت ادا ہوتی ہے اور سامنے سے کھانا ادبِ طعام ہے۔', '[{"word":"سَمِّ","role":"فعل أمر مبني على حذف حرف العلة","sign":"حذف الياء","detail":"والفاعل مستتر تقديره أنت"},{"word":"بِيَمِينِكَ","role":"جار ومجرور","sign":"كسرة لفظاً","detail":"متعلق بفعل كُل"}]', '["متفق عليه: البخاري (5376)، ومسلم (2022)."]', '{"en":"''Umar bin Abi Salamah reported: I was a boy under the care of Allah''s Messenger ﷺ and my hand used to wander around the dish. He said to me: ''O boy! Mention Allah''s Name, eat with your right hand, and eat from what is directly in front of you.''","ar":"تعليم النبي ﷺ للأطفال آداب الأكل بكل رفق ومحبة وتوجيه سديد."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_22_2', 'riyad_ch22_adab_taam', 'kharji_lib_0261', 1, 'وَعَنْ مِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَا مَلَأَ آدَمِيٌّ وِعَاءً شَرّاً مِنْ بَطْنٍ، بِحَسْبِ ابْنِ آدَمَ أُكُلَاتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا مَحَالَةَ، فَثُلُثٌ لِطَعَامِهِ، وَثُلُثٌ لِشَرَابِهِ، وَثُلُثٌ لِنَفَسِهِ».', 'حضرت مقدام بن معدیکرب رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ کو فرماتے سنا: ''انسان نے پیٹ سے برا کوئی برتن نہیں بھرا! ابنِ آدم کے لیے تو چند لقمے ہی کافی ہیں جو اس کی پیٹھ سیدھی رکھ سکیں؛ اگر زیادہ ہی کھانا ضروری ہو تو ایک تہائی پیٹ کھانے کے لیے، ایک تہائی پانی کے لیے، اور ایک تہائی سانس لینے کے لیے خالی رکھے!''', 'تمام بیماریوں کی جڑ پیٹ کا ضرورت سے زیادہ بھرنا ہے۔ نبی کریم ﷺ نے طبِ نبوی کا یہ سنہرا قانون عطا فرمایا کہ اعتدال اور بھوک رکھ کر کھانا انسان کو صحت مند اور عبادات کے لیے چست رکھتا ہے۔', '[{"word":"شَرّاً","role":"نعت منصوب لوعاء","sign":"فتحة لفظاً","detail":"أو تمييز منصوب"},{"word":"ثُلُثٌ","role":"مبتدأ مؤخر أو خبر لمبتدأ محذوف","sign":"ضمة لفظاً","detail":"تقديره: فالواجب ثلث لطعامه"}]', '["أخرجه الترمذي (2380) وقال: حديث حسن صحيح."]', '{"en":"Al-Miqdam bin Ma''dikarib reported: I heard the Messenger of Allah ﷺ saying: ''A human being fills no vessel worse than his stomach. A few morsels to keep his back straight are sufficient for him. But if he must, then one third for his food, one third for his drink, and one third for his breath.''","ar":"قاعدة نبوية عظيمة في حفظ الصحة والاعتدال في المأكل والمشرب."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch23_salam', 'kharji_lib_0261', 22, 'بَابُ آدَابِ السَّلَامِ وَالاسْتِئْذَانِ وَالمُصَافَحَةِ', 'باب 23: سلام کی اشاعت، مصافحہ اور اجازت طلب کرنے کے آداب');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_23_1', 'riyad_ch23_salam', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا تَدْخُلُونَ الجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''تم جنت میں داخل نہیں ہو سکتے جب تک کہ کامل مومن نہ بن جاؤ، اور تم کامل مومن نہیں بن سکتے جب تک کہ آپس میں ایک دوسرے سے محبت نہ کرنے لگو؛ کیا میں تمہیں ایسا عمل نہ بتاؤں جس کو کرنے سے تمہارے درمیان باہمی محبت پیدا ہو جائے؟ آپس میں کثرت سے سلام کو عام کرو!''', 'سلام صرف ایک رسمی کلمہ نہیں بلکہ سلامتی اور رحمت کی دعا ہے۔ ہر مسلمان کو خواہ جان پہچان ہو یا نہ ہو سلام کرنے سے دلوں سے کینہ، بغض اور تکبر کا خاتمہ ہوتا ہے اور ایمانی اخوت پروان چڑھتی ہے۔', '[{"word":"تَدْخُلُونَ","role":"فعل مضارع مرفوع بثبوت النون","sign":"ثبوت النون","detail":"والواو فاعل ولا نافية"},{"word":"أَفْشُوا","role":"فعل أمر مبني على حذف النون","sign":"حذف النون","detail":"والواو ضمير متصل فاعل"}]', '["أخرجه مسلم في صحيحه (54)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''You will not enter Paradise until you believe, and you will not believe until you love one another. Shall I not guide you to something which, if you do it, will make you love one another? Spread peace among yourselves.''","ar":"إفشاء السلام مفتاح المحبة والمودة وكمال الإيمان المفضي إلى الجنة."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_23_2', 'riyad_ch23_salam', 'kharji_lib_0261', 1, 'وَعَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَا مِنْ مُسْلِمَيْنِ يَلْتَقِيَانِ فَيَتَصَافَحَانِ إِلَّا غُفِرَ لَهُمَا قَبْلَ أَنْ يَفْتَرِقَا».', 'حضرت براء بن عازب رضی اللہ عنہما نے فرمایا کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جب بھی دو مسلمان آپس میں ملتے ہیں اور گرم جوشی سے مصافحہ کرتے ہیں، تو ان کے جدا ہونے سے پہلے پہلے اللہ تعالیٰ ان دونوں کے گناہوں کی مغفرت فرما دیتا ہے!''', 'مصافحہ کرنے سے باہمی دوری اور کھچاؤ ختم ہو جاتا ہے۔ جب دونوں ہاتھ ملتے ہیں تو گناہ ایسے جھڑتے ہیں جیسے درخت سے خشک پتے جھڑتے ہیں، یہ اسلام کے خوبصورت معاشرتی آداب کا عکس ہے۔', '[{"word":"مَا","role":"حرف نفي","sign":"مبني","detail":"من حرف جر زائد ومسلمين مجرور لفظاً مرفوع محلاً مبتدأ"},{"word":"إِلَّا","role":"أداة حصر","sign":"مبني","detail":"وغفر لهما جملة فعلية خبر المبتدأ"}]', '["أخرجه أبو داود (5212)، والترمذي (2727) وقال: حديث حسن."]', '{"en":"Al-Bara'' bin ''Azib reported that Allah''s Messenger ﷺ said: ''No two Muslims meet and shake hands except that their sins are forgiven before they part.''","ar":"فضل المصافحة باليد وتطهيرها للذنوب وإزالة الأحقاد بين المسلمين."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch24_iyadah', 'kharji_lib_0261', 23, 'بَابُ عِيَادَةِ المَرِيضِ وَحُقُوقِ المُسْلِمِ', 'باب 24: عیادتِ مریض، حقوقِ مسلم اور جنازے کے احکام');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_24_1', 'riyad_ch24_iyadah', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «حَقُّ المُسْلِمِ عَلَى المُسْلِمِ سِتٌّ»، قِيلَ: مَا هُنَّ يَا رَسُولَ اللَّهِ؟ قَالَ: «إِذَا لَقِيتَهُ فَسَلِّمْ عَلَيْهِ، وَإِذَا دَعَاكَ فَأَجِبْهُ، وَإِذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ، وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ فَشَمِّتْهُ، وَإِذَا مَرِضَ فَعُدْهُ، وَإِذَا مَاتَ فَاتَّبِعْهُ».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: ''ایک مسلمان کے دوسرے مسلمان پر چھ حقوق ہیں''۔ پوچھا گیا: یا رسول اللہ! وہ کون سے ہیں؟ آپ ﷺ نے فرمایا: ''جب تم اس سے ملو تو اسے سلام کرو؛ جب وہ تمہاری دعوت کرے تو اسے قبول کرو؛ جب وہ تم سے مخلصانہ مشورہ مانگے تو اسے نیک مشورہ دو؛ جب وہ چھینکے اور الحمد للہ کہے تو اس کے جواب میں یرحمک اللہ کہو؛ جب وہ بیمار ہو جائے تو اس کی عیادت کرو؛ اور جب وہ وفات پا جائے تو اس کے جنازے کے ساتھ جاؤ''۔', 'یہ چھ حقوق اسلامی معاشرے کے تانے بانے کو مضبوط کرتے ہیں۔ خوشی میں شرکت، دکھ میں ہمدردی، بیماری میں تسلی اور موت کے بعد دعائے مغفرت باہمی وحدت کو جنم دیتی ہے۔', '[{"word":"حَقُّ","role":"مبتدأ مرفوع","sign":"ضمة لفظاً","detail":"وهو مضاف والمسلم مضاف إليه"},{"word":"سِتٌّ","role":"خبر المبتدأ مرفوع","sign":"ضمة لفظاً","detail":"والجمل بعده تفصيل للمجمل"}]', '["أخرجه مسلم في صحيحه (2162)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''The rights of a Muslim upon a Muslim are six: When you meet him, greet him; when he invites you, accept; when he seeks your advice, counsel him; when he sneezes and praises Allah, invoke mercy on him; when he is sick, visit him; and when he dies, follow his funeral.''","ar":"الحقوق الستة المشتركة التي تبني المجتمع الإسلامي المترابط."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_24_2', 'riyad_ch24_iyadah', 'kharji_lib_0261', 1, 'وَعَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ المُسْلِمَ إِذَا عَادَ أَخَاهُ المُسْلِمَ لَمْ يَزَلْ فِي خُرْفَةِ الجَنَّةِ حَتَّى يَرْجِعَ»، قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا خُرْفَةُ الجَنَّةِ؟ قَالَ: «جَنَاهَا».', 'حضرت ثوبان رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: ''بے شک مسلمان جب اپنے کسی مسلمان بھائی کی عیادت کے لیے جاتا ہے، تو وہ واپس لوٹنے تک مسلسل جنت کے پھلوں کے باغ میں رہتا ہے!'' عرض کیا گیا: یا رسول اللہ! خرفۃ الجنۃ سے کیا مراد ہے؟ آپ ﷺ نے فرمایا: ''جنت کے چنے ہوئے تازہ اور لذیذ پھل!''', 'بیمار پرسی کے لمحات رحمت کے سائے میں گزرتے ہیں۔ جب تک بندہ بیمار کی دلجوئی کرتا ہے، اللہ کی رحمتیں اور جنت کی برکات اس کا احاطہ کیے رکھتی ہیں۔', '[{"word":"لَمْ يَزَلْ","role":"فعل مضارع ناقص مجزوم","sign":"سكون","detail":"واسمها ضمير مستتر تقديره هو"},{"word":"فِي خُرْفَةِ","role":"شبه جملة خبر لم يزل","sign":"كسرة لفظاً","detail":"في محل نصب خبر لم يزل"}]', '["أخرجه مسلم في صحيحه (2568)."]', '{"en":"Thawban reported that the Prophet ﷺ said: ''Verily, when a Muslim visits his sick Muslim brother, he remains in the fruit gardens of Paradise until he returns.'' It was asked: ''What is Khurfat al-Jannah?'' He said: ''Its harvested fruits.''","ar":"ثواب عيادة المريض وتفقد أحوال الضعفاء وإدخال السرور على قلوبهم."}');
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('riyad_ch25_raja_khatm', 'kharji_lib_0261', 24, 'بَابُ الرَّجَاءِ وَحُسْنِ الظَّنِّ بِاللَّهِ وَسَعَةِ الرَّحْمَةِ (خَتْمُ الكِتَابِ)', 'باب 25: رجاء، اللہ سے امید، حسنِ ظن اور ختمِ کتاب کی دعائیں');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_25_1', 'riyad_ch25_raja_khatm', 'kharji_lib_0261', 0, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «قَالَ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ، وَإِنْ تَقَرَّبَ إِلَيَّ بِشِبْرٍ تَقَرَّبْتُ إِلَيْهِ ذِرَاعاً، وَإِنْ تَقَرَّبَ إِلَيَّ ذِرَاعاً تَقَرَّبْتُ إِلَيْهِ بَاعاً، وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً».', 'حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''اللہ تعالیٰ کا ارشاد ہے: میں اپنے بندے کے ساتھ اس کے گمان کے مطابق معاملہ فرماتا ہوں، اور جب وہ مجھے یاد کرتا ہے تو میں اس کے ساتھ ہوتا ہوں۔ پس اگر وہ مجھے اپنے دل میں یاد کرے تو میں اسے اپنی بارگاہ میں یاد فرماتا ہوں، اور اگر وہ کسی مجلس اور مجمع میں میرا ذکر کرے تو میں اس سے کہیں زیادہ معزز اور برگزیدہ مجمع (فرشتوں کی جماعت) میں اس کا تذکرہ کرتا ہوں۔ اور اگر وہ میری طرف ایک بالشت قریب آتا ہے تو میں اس کی طرف ایک ہاتھ قریب ہوتا ہوں، اور اگر وہ میری طرف ایک ہاتھ قریب آئے تو میں اس کی طرف دو کھلے ہاتھوں کے فاصلے کے برابر قریب ہوتا ہوں، اور اگر وہ میری طرف چل کر آئے تو میں اس کی طرف دوڑ کر آتا ہوں!''', 'امام نووی رحمہ اللہ نے اپنی مبارک کتاب کا اختتام اللہ تعالیٰ کی بے پایاں رحمت، وسعتِ مغفرت اور حسنِ ظن کے ابواب پر کیا ہے۔ اللہ اپنے بندے کے ذرا سے رجوع کو بھی شرفِ قبولیت بخشتا ہے۔', '[{"word":"أَنَا","role":"ضمير منفصل مبتدأ","sign":"مبني","detail":"في محل رفع مبتدأ"},{"word":"عِنْدَ","role":"ظرف مكان خبر المبتدأ","sign":"فتحة لفظاً","detail":"متعلق بمحذوف خبر وهو مضاف وظن مضاف إليه"}]', '["متفق عليه: البخاري (7405)، ومسلم (2675)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''Allah Almighty says: I am as My servant thinks of Me, and I am with him when he mentions Me. If he remembers Me in his heart, I remember him in Myself... and if he comes to Me walking, I come to him running.''","ar":"حديث قدسي جليل يفيض بالرجاء والمحبة الإلهية لمن أقبل على ربه مخلصاً."}');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('riyad_seg_25_2', 'riyad_ch25_raja_khatm', 'kharji_lib_0261', 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَمَّا قَضَى اللَّهُ الخَلْقَ كَتَبَ فِي كِتَابِهِ فَهُوَ عِنْدَهُ فَوْقَ العَرْشِ: إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي»؛ وَفِي رِوَايَةٍ: «سَبَقَتْ غَضَبِي». وَالحَمْدُ لِلَّهِ رَبِّ العَالَمِينَ عَلَى التَّمَامِ، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَصَحْبِهِ أَجْمَعِينَ.', 'حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: ''جب اللہ تعالیٰ نے کائنات کو پیدا فرمایا تو اپنے پاس عرشِ معلیٰ پر رکھی ہوئی کتاب میں تحریر فرما دیا: بے شک میری رحمت میرے غضب پر غالب آ گئی ہے؛ (اور دوسری روایت میں ہے: میری رحمت میرے غضب سے سبقت لے گئی ہے)''۔ اور تمام تعریفیں اللہ رب العالمین ہی کے لیے ہیں جس نے اس کتاب کے مطالعے کی تکمیل کی توفیق بخشی، اور درود و سلام ہو ہمارے آقا و مولیٰ محمد ﷺ اور ان کی تمام آل اور اصحاب پر۔', 'یہ مبارک کتاب کا آخری صفحہ ہے! امام محیی الدین نووی رحمہ اللہ نے پوری کتاب میں پہلے انسان کے باطن کی اصلاح (اخلاص، توبہ، تقویٰ)، پھر ظاہری معاملات (آداب، حقوق، حسنِ خلق) اور آخر میں وسعتِ رحمتِ الٰہی پر خاتمہ فرمایا، تاکہ قاری خوف اور امید کے حسین توازن کے ساتھ دنیا سے رخصت ہو۔', '[{"word":"إِنَّ","role":"حرف توكيد ونصب","sign":"مبني","detail":"رحمتي اسمها منصوب بفتحة مقدرة"},{"word":"غَلَبَتْ","role":"فعل ماض والتاء للتأنيث","sign":"مبني على الفتح","detail":"والجملة الفعلية في محل رفع خبر إن"}]', '["متفق عليه: البخاري (3194)، ومسلم (2751)."]', '{"en":"Abu Hurairah reported that Allah''s Messenger ﷺ said: ''When Allah decreed the creation, He wrote in His Book which is with Him above the Throne: Verily, My mercy prevails over My wrath.'' All praise is due to Allah for the completion of this blessed book.","ar":"ختام كتاب رياض الصالحين بتقرير غلبة رحمة أرحم الراحمين ليكون العبد في خاتمته مقبلاً على الله راجياً لفضله."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0262', 'مشكاة المصابيح', 'الإمام ولي الدين محمد بن عبد الله الخطيب التبريزي (ت: 741ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'ديوان السنة المختار لطلبة العلم وحلقات التدريس.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0262_ch1', 'kharji_lib_0262', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0262_seg_1', 'kharji_lib_0262_ch1', 'kharji_lib_0262', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''مشكاة المصابيح'' by الإمام ولي الدين محمد بن عبد الله الخطيب التبريزي (ت: 741ھ).","ar":"نص مختار من كتاب مشكاة المصابيح للإمام الإمام ولي الدين محمد بن عبد الله الخطيب التبريزي (ت: 741ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0263', 'بلوغ المرام من أدلة الأحكام', 'الحافظ ابن حجر العسقلاني (ت: 852ھ)', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'أدق مختصرات أحاديث الأحكام مرتباً على الأبواب الفقهية.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0263_ch1', 'kharji_lib_0263', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0263_seg_1', 'kharji_lib_0263_ch1', 'kharji_lib_0263', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم الحديث و الشروح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''بلوغ المرام من أدلة الأحكام'' by الحافظ ابن حجر العسقلاني (ت: 852ھ).","ar":"نص مختار من كتاب بلوغ المرام من أدلة الأحكام للإمام الحافظ ابن حجر العسقلاني (ت: 852ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0264', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم الحديث و الشروح (الجزء 1)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم الحديث و الشروح', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم الحديث و الشروح وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0264_ch1', 'kharji_lib_0264', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0264_seg_1', 'kharji_lib_0264_ch1', 'kharji_lib_0264', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم الحديث و الشروح کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 1 of علوم الحديث و الشروح.","ar":"نص وبحث تأصيلي في علوم الحديث و الشروح."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0265', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم الحديث و الشروح (الجزء 2)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم الحديث و الشروح', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم الحديث و الشروح وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0265_ch1', 'kharji_lib_0265', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0265_seg_1', 'kharji_lib_0265_ch1', 'kharji_lib_0265', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم الحديث و الشروح کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 2 of علوم الحديث و الشروح.","ar":"نص وبحث تأصيلي في علوم الحديث و الشروح."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0266', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم الحديث و الشروح (الجزء 3)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم الحديث و الشروح', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم الحديث و الشروح وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0266_ch1', 'kharji_lib_0266', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0266_seg_1', 'kharji_lib_0266_ch1', 'kharji_lib_0266', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم الحديث و الشروح کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 3 of علوم الحديث و الشروح.","ar":"نص وبحث تأصيلي في علوم الحديث و الشروح."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0267', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم الحديث و الشروح (الجزء 4)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم الحديث و الشروح', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم الحديث و الشروح وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0267_ch1', 'kharji_lib_0267', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0267_seg_1', 'kharji_lib_0267_ch1', 'kharji_lib_0267', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم الحديث و الشروح کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 4 of علوم الحديث و الشروح.","ar":"نص وبحث تأصيلي في علوم الحديث و الشروح."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0268', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم الحديث و الشروح (الجزء 5)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم الحديث و الشروح', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم الحديث و الشروح وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0268_ch1', 'kharji_lib_0268', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0268_seg_1', 'kharji_lib_0268_ch1', 'kharji_lib_0268', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے علوم الحديث و الشروح کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 5 of علوم الحديث و الشروح.","ar":"نص وبحث تأصيلي في علوم الحديث و الشروح."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0269', 'المُعْجَمُ التَّأْصِيلِيُّ فِي علوم الحديث و الشروح (الجزء 6)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي علوم الحديث و الشروح', 'kharji_kitab', 'hadith', 'علوم الحديث و الشروح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث علوم الحديث و الشروح وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
