INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0350', 'تبيين الحقائق شرح كنز الدقائق', 'فخر الدين عثمان بن علي الزيلعي الحنفي (ت: 743ھ)', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'شرح جليل في الاستدلال لأحكام الكنز ودفع الاعتراضات.', 1, 1);
