INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0351', 'فتح القدير للعاجز الفقير', 'كمال الدين محمد بن عبد الواحد السيواسي ابن الهمام (ت: 861ھ)', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'المرجع الأعلى للترجيح والاجتهاد وتخريج الفروع على الأصول.', 1, 1);
