INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0358', 'اللباب في شرح الكتاب', 'عبد الغني الغنيمي الميداني الدمشقي الحنفي (ت: 1298ھ)', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'الرفيق المعتمد لكل طالب علم في قراءة متن القدوري.', 1, 1);
