INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0365', 'أصول البزدوي (كنز الوصول)', 'فخر الإسلام علي بن محمد البزدوي الحنفي (ت: 482ھ)', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'دستور أصول الفقه الحنفي المتوارث بين كبار المحققين.', 1, 1);
