INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0372', 'التوضيح في حل غوامض التنقيح', 'صدر الشريعة عبيد الله بن مسعود المحبوبي (ت: 747ھ)', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'متن وشرح فائق العناية في ضبط قواعد استنباط الأحكام.', 1, 1);
