INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0380', 'بداية المجتهد ونهاية المقتصد', 'القاضي أبو الوليد محمد بن أحمد بن رشد الحفيد (ت: 595ھ)', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'فلسفة الخلاف العالي وأسباب اختلاف الفقهاء في كل باب.', 1, 1);
