INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0411_ch1', 'kharji_lib_0411', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0411_seg_1', 'kharji_lib_0411_ch1', 'kharji_lib_0411', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے الفقہ و اصول الفقہ کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 28 of الفقہ و اصول الفقہ.","ar":"نص وبحث تأصيلي في الفقہ و اصول الفقہ."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0412', 'المُعْجَمُ التَّأْصِيلِيُّ فِي الفقہ و اصول الفقہ (الجزء 29)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي الفقہ و اصول الفقہ', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث الفقہ و اصول الفقہ وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0412_ch1', 'kharji_lib_0412', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0412_seg_1', 'kharji_lib_0412_ch1', 'kharji_lib_0412', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے الفقہ و اصول الفقہ کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 29 of الفقہ و اصول الفقہ.","ar":"نص وبحث تأصيلي في الفقہ و اصول الفقہ."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0413', 'المُعْجَمُ التَّأْصِيلِيُّ فِي الفقہ و اصول الفقہ (الجزء 30)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي الفقہ و اصول الفقہ', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث الفقہ و اصول الفقہ وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0413_ch1', 'kharji_lib_0413', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0413_seg_1', 'kharji_lib_0413_ch1', 'kharji_lib_0413', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے الفقہ و اصول الفقہ کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 30 of الفقہ و اصول الفقہ.","ar":"نص وبحث تأصيلي في الفقہ و اصول الفقہ."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0414', 'المُعْجَمُ التَّأْصِيلِيُّ فِي الفقہ و اصول الفقہ (الجزء 31)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي الفقہ و اصول الفقہ', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث الفقہ و اصول الفقہ وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0414_ch1', 'kharji_lib_0414', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0414_seg_1', 'kharji_lib_0414_ch1', 'kharji_lib_0414', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے الفقہ و اصول الفقہ کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 31 of الفقہ و اصول الفقہ.","ar":"نص وبحث تأصيلي في الفقہ و اصول الفقہ."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0415', 'المُعْجَمُ التَّأْصِيلِيُّ فِي الفقہ و اصول الفقہ (الجزء 32)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي الفقہ و اصول الفقہ', 'kharji_kitab', 'fiqh', 'الفقہ و اصول الفقہ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث الفقہ و اصول الفقہ وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
