INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0497', 'كفايت المفتي', 'مفتي أعظم هند المفتي كفاية الله الدهلوي (ت: 1372ھ)', 'kharji_kitab', 'fatawa', 'کتبِ فتاویٰ و فقہی نوازل', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'الفتاوى المتقنة المحررة بالاختصار الفقهي المحكم ودقة العبارة.', 1, 1);
