INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0504', 'قرارات وتوصيات مجمع الفقه الإسلامي الدولي', 'مجمع الفقه الإسلامي الدولي المنبثق عن منظمة التعاون الإسلامي', 'kharji_kitab', 'fatawa', 'کتبِ فتاویٰ و فقہی نوازل', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'الاجتهاد الجماعي لكبار علماء العالم الإسلامي في النوازل المعاصرة.', 1, 1);
