INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0581', 'فقه السيرة النبوية مع موجز لتاريخ الخلافة', 'الشهيد الدكتور محمد سعيد رمضان البوطي (ت: 1434ھ)', 'kharji_kitab', 'seerah', 'السیرۃ النبویۃ و الشمائل', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'استخراج العبر والدروس الفقهية والدعوية من وقائع السيرة.', 1, 1);
