INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0665', 'وفيات الأعيان وأنباء أبناء الزمان', 'القاضي أحمد بن محمد بن إبراهيم ابن خلكان (ت: 681ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'الأدب التاريخي الأرقى في إبراز فضائل العباقرة والشعراء والقادة.', 1, 1);
