INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0666', 'شذرات الذهب في أخبار من ذهب', 'شهاب الدين عبد الحي بن أحمد ابن العماد الحنبلي (ت: 1089ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'حوليات تاريخية مختصرة جامعة لوفيات العلماء على رأس كل سنة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0666_ch1', 'kharji_lib_0666', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0666_seg_1', 'kharji_lib_0666_ch1', 'kharji_lib_0666', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ کتاب تاریخِ اسلام و سوانح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''شذرات الذهب في أخبار من ذهب'' by شهاب الدين عبد الحي بن أحمد ابن العماد الحنبلي (ت: 1089ھ).","ar":"نص مختار من كتاب شذرات الذهب في أخبار من ذهب للإمام شهاب الدين عبد الحي بن أحمد ابن العماد الحنبلي (ت: 1089ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0667', 'مقدمة ابن خلدون (العبر وديوان المبتدأ والخبر)', 'العلامة عبد الرحمن بن محمد بن خلدون الحضرمي (ت: 808ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'تأسيس علم الاجتماع البشري وفلسفة قيام وسقوط الدول والحضارات.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0667_ch1', 'kharji_lib_0667', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0667_seg_1', 'kharji_lib_0667_ch1', 'kharji_lib_0667', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب تاریخِ اسلام و سوانح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''مقدمة ابن خلدون (العبر وديوان المبتدأ والخبر)'' by العلامة عبد الرحمن بن محمد بن خلدون الحضرمي (ت: 808ھ).","ar":"نص مختار من كتاب مقدمة ابن خلدون (العبر وديوان المبتدأ والخبر) للإمام العلامة عبد الرحمن بن محمد بن خلدون الحضرمي (ت: 808ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0668', 'الاستيعاب في معرفة الأصحاب', 'الإمام أبو عمر يوسف بن عبد البر القرطبي (ت: 463ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'أول الكتب المحررة المستوعبة لتراجم الصحابة الكرام رضي الله عنهم.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0668_ch1', 'kharji_lib_0668', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0668_seg_1', 'kharji_lib_0668_ch1', 'kharji_lib_0668', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب تاریخِ اسلام و سوانح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الاستيعاب في معرفة الأصحاب'' by الإمام أبو عمر يوسف بن عبد البر القرطبي (ت: 463ھ).","ar":"نص مختار من كتاب الاستيعاب في معرفة الأصحاب للإمام الإمام أبو عمر يوسف بن عبد البر القرطبي (ت: 463ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0669', 'أسد الغابة في معرفة الصحابة', 'عز الدين علي بن محمد بن الأثير الجزري (ت: 630ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'الموسوعة الجامعة لأكثر من سبعة آلاف ترجمة من أصحاب النبي ﷺ.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0669_ch1', 'kharji_lib_0669', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0669_seg_1', 'kharji_lib_0669_ch1', 'kharji_lib_0669', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب تاریخِ اسلام و سوانح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''أسد الغابة في معرفة الصحابة'' by عز الدين علي بن محمد بن الأثير الجزري (ت: 630ھ).","ar":"نص مختار من كتاب أسد الغابة في معرفة الصحابة للإمام عز الدين علي بن محمد بن الأثير الجزري (ت: 630ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0670', 'الإصابة في تمييز الصحابة', 'الحافظ أحمد بن علي بن حجر العسقلاني (ت: 852ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'التحرير الأخير الأتقن في ضبط من ثبتت صحبته ومن اخْتُلِفَ فيه.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0670_ch1', 'kharji_lib_0670', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0670_seg_1', 'kharji_lib_0670_ch1', 'kharji_lib_0670', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب تاریخِ اسلام و سوانح کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''الإصابة في تمييز الصحابة'' by الحافظ أحمد بن علي بن حجر العسقلاني (ت: 852ھ).","ar":"نص مختار من كتاب الإصابة في تمييز الصحابة للإمام الحافظ أحمد بن علي بن حجر العسقلاني (ت: 852ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0671', 'طبقات الشافعية الكبرى', 'الإمام تاج الدين عبد الوهاب بن علي السبكي (ت: 771ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'مرجع تراجم كبار الفقهاء والنظار وأصحاب الوجوه في المذهب.', 1, 1);
