INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0672', 'الجواهر المضية في طبقات الحنفية', 'محيي الدين عبد القادر بن محمد بن نصر القرشي (ت: 775ھ)', 'kharji_kitab', 'tarikh', 'تاریخِ اسلام و سوانح', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'ديوان أئمة المذهب الحنفي وأصحاب الكتب والفتاوى عبر العصور.', 1, 1);
