INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0759', 'الزهد والورع', 'الإمام أحمد بن حنبل الشيباني (ت: 241ھ)', 'kharji_kitab', 'tazkiyah', 'التزکیۃ، الاخلاق و الادب', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'روايات إمام أهل السنة في مواعظ الأنبياء وتواضع الصالحين.', 1, 1);
