INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0844', 'المسايرة في العقائد المنجية في الآخرة', 'الإمام كمال الدين محمد بن الهمام الحنفي (ت: 861ھ)', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'تحرير عقدي حنفي متين يجمع بين الماتريدية والأشعرية.', 1, 1);
