INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0853', 'العقيدة الواسطية', 'شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني (ت: 728ھ)', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'رسالة محكمة في تقرير الأسماء والصفات والإيمان والصحابة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0853_ch1', 'kharji_lib_0853', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0853_seg_1', 'kharji_lib_0853_ch1', 'kharji_lib_0853', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب العقیدۃ و علم الکلام کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''العقيدة الواسطية'' by شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني (ت: 728ھ).","ar":"نص مختار من كتاب العقيدة الواسطية للإمام شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني (ت: 728ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0854', 'درء تعارض العقل والنقل', 'شيخ الإسلام ابن تيمية (ت: 728ھ)', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'موسوعة الدفاع عن الوحي وإثبات موافقته لصريح المعقول.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0854_ch1', 'kharji_lib_0854', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0854_seg_1', 'kharji_lib_0854_ch1', 'kharji_lib_0854', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب العقیدۃ و علم الکلام کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''درء تعارض العقل والنقل'' by شيخ الإسلام ابن تيمية (ت: 728ھ).","ar":"نص مختار من كتاب درء تعارض العقل والنقل للإمام شيخ الإسلام ابن تيمية (ت: 728ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0855', 'منهاج السنة النبوية في نقض كلام الشيعة القدرية', 'شيخ الإسلام ابن تيمية (ت: 728ھ)', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'الرد التاريخي والعقائدي الأعظم على كتاب منهاج الكرامة.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0855_ch1', 'kharji_lib_0855', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0855_seg_1', 'kharji_lib_0855_ch1', 'kharji_lib_0855', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب العقیدۃ و علم الکلام کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''منهاج السنة النبوية في نقض كلام الشيعة القدرية'' by شيخ الإسلام ابن تيمية (ت: 728ھ).","ar":"نص مختار من كتاب منهاج السنة النبوية في نقض كلام الشيعة القدرية للإمام شيخ الإسلام ابن تيمية (ت: 728ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0856', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 1)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0856_ch1', 'kharji_lib_0856', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0856_seg_1', 'kharji_lib_0856_ch1', 'kharji_lib_0856', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے العقیدۃ و علم الکلام کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 1 of العقیدۃ و علم الکلام.","ar":"نص وبحث تأصيلي في العقیدۃ و علم الکلام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0857', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 2)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0857_ch1', 'kharji_lib_0857', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0857_seg_1', 'kharji_lib_0857_ch1', 'kharji_lib_0857', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے العقیدۃ و علم الکلام کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 2 of العقیدۃ و علم الکلام.","ar":"نص وبحث تأصيلي في العقیدۃ و علم الکلام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0858', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 3)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-stone-800 via-emerald-950 to-amber-950', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
