INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0883', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 28)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0883_ch1', 'kharji_lib_0883', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0883_seg_1', 'kharji_lib_0883_ch1', 'kharji_lib_0883', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے العقیدۃ و علم الکلام کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 28 of العقیدۃ و علم الکلام.","ar":"نص وبحث تأصيلي في العقیدۃ و علم الکلام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0884', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 29)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0884_ch1', 'kharji_lib_0884', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0884_seg_1', 'kharji_lib_0884_ch1', 'kharji_lib_0884', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے العقیدۃ و علم الکلام کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 29 of العقیدۃ و علم الکلام.","ar":"نص وبحث تأصيلي في العقیدۃ و علم الکلام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0885', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 30)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-900 via-yellow-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0885_ch1', 'kharji_lib_0885', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0885_seg_1', 'kharji_lib_0885_ch1', 'kharji_lib_0885', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے العقیدۃ و علم الکلام کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 30 of العقیدۃ و علم الکلام.","ar":"نص وبحث تأصيلي في العقیدۃ و علم الکلام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0886', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 31)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-900 via-green-950 to-stone-900', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0886_ch1', 'kharji_lib_0886', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0886_seg_1', 'kharji_lib_0886_ch1', 'kharji_lib_0886', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ تحقیقی جلد طلبہ اور اساتذہ کے لیے العقیدۃ و علم الکلام کے مختلف ابواب اور فتاویٰ کے مراجع کو یکجا پیش کرتی ہے۔', NULL, NULL, '{"en":"Scholarly reference excerpt from Volume 31 of العقیدۃ و علم الکلام.","ar":"نص وبحث تأصيلي في العقیدۃ و علم الکلام."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0887', 'المُعْجَمُ التَّأْصِيلِيُّ فِي العقیدۃ و علم الکلام (الجزء 32)', 'نُخْبَةٌ مِنْ كِبَارِ عُلَمَاءِ وَمُحَقِّقِي العقیدۃ و علم الکلام', 'kharji_kitab', 'aqaid', 'العقیدۃ و علم الکلام', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-rose-900 via-stone-900 to-emerald-950', NULL, 'موسوعة مرجعية شاملة تضم أمهات أبحاث العقیدۃ و علم الکلام وتحقيقات كبار الأئمة في المسائل والدلائل.', 1, 1);
