INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0919', 'المفصل في صنعة الإعراب', 'جار الله محمود بن عمر الزمخشري (ت: 538ھ)', 'kharji_kitab', 'nahw', 'علوم اللغۃ، النحو و البلاغۃ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-teal-900 via-stone-900 to-amber-900', NULL, 'المتن البديع المقسم إلى الأسماء والأفعال والحروف والمشترك.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0919_ch1', 'kharji_lib_0919', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0919_seg_1', 'kharji_lib_0919_ch1', 'kharji_lib_0919', 0, 'وَمِنْ لَطَائِفِ هَذَا الكِتَابِ أَنَّهُ يَفْتَحُ لِلطَّالِبِ أَبْوَابَ الفَهْمِ وَيُعِينُهُ عَلَى حَلِّ غَوَامِضِ العِبَارَاتِ.', 'اس کتاب کی خاص خوبی یہ ہے کہ یہ طالب علم کے لیے فہم و تدبر کے در وا کرتی ہے اور کتب قدیمہ کی پیچیدہ عبارات کو آسان بناتی ہے۔', 'یہ کتاب علوم اللغۃ، النحو و البلاغۃ کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''المفصل في صنعة الإعراب'' by جار الله محمود بن عمر الزمخشري (ت: 538ھ).","ar":"نص مختار من كتاب المفصل في صنعة الإعراب للإمام جار الله محمود بن عمر الزمخشري (ت: 538ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0920', 'شرح ابن عقيل على ألفية ابن مالك', 'قاضي القضاة بهاء الدين عبد الله بن عقيل (ت: 769ھ)', 'kharji_kitab', 'nahw', 'علوم اللغۃ، النحو و البلاغۃ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-emerald-800 via-teal-900 to-stone-900', NULL, 'أشهر الشروح التدريسية لألفية ابن مالك وأوضحها تقريباً.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0920_ch1', 'kharji_lib_0920', 0, 'المقدمة في تأصيل هذا العلم ومنزلته', 'فصل اول: اس علم کی فضیلت، تعریف اور شرعی و عملی حیثیت');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0920_seg_1', 'kharji_lib_0920_ch1', 'kharji_lib_0920', 0, 'اعْلَمْ أَنَّ شَرَفَ العِلْمِ بِشَرَفِ مَعْلُومِهِ، وَإِنَّ أَعْظَمَ مَا صَرَفَ الأَئِمَّةُ فِيهِ أَعْمَارَهُمْ تَحْصِيلُ هَذَا الفَنِّ الشَّرِيفِ.', 'جان لو کہ علم کی فضیلت اس کے معلوم کے شرف سے وابستہ ہے، اور ائمہ دین نے اپنی قیمتی عمریں اسی مبارک فن کی خدمت میں وقف فرمائیں۔', 'یہ کتاب علوم اللغۃ، النحو و البلاغۃ کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''شرح ابن عقيل على ألفية ابن مالك'' by قاضي القضاة بهاء الدين عبد الله بن عقيل (ت: 769ھ).","ar":"نص مختار من كتاب شرح ابن عقيل على ألفية ابن مالك للإمام قاضي القضاة بهاء الدين عبد الله بن عقيل (ت: 769ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0921', 'قطر الندى وبل الصدى', 'جمال الدين عبد الله بن يوسف بن هشام الأنصاري (ت: 761ھ)', 'kharji_kitab', 'nahw', 'علوم اللغۃ، النحو و البلاغۃ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-amber-800 via-stone-900 to-emerald-950', NULL, 'المتن المتين الذي تدرجت به أجيال طلبة العربية إلى الإتقان.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0921_ch1', 'kharji_lib_0921', 0, 'الباب الأول: الأصول الكلية والقواعد الجامعة', 'باب اول: اساسی و کلی قواعد اور ائمہ کی اصطلاحات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0921_seg_1', 'kharji_lib_0921_ch1', 'kharji_lib_0921', 0, 'قَالَ الإِمَامُ المُحَقِّقُ: مَدَارُ هَذَا البَابِ عَلَى صِحَّةِ النِّيَّةِ وَاتِّبَاعِ النُّصُوصِ الصَّحِيحَةِ عَلَى فَهْمِ أَئِمَّةِ الهُدَى.', 'امام محقق فرماتے ہیں: اس باب کا اصل دارومدار اخلاص نیت اور ائمہ ہدایت کی فہم کے مطابق نصوص صحیحہ کی اتباع پر ہے۔', 'یہ کتاب علوم اللغۃ، النحو و البلاغۃ کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''قطر الندى وبل الصدى'' by جمال الدين عبد الله بن يوسف بن هشام الأنصاري (ت: 761ھ).","ar":"نص مختار من كتاب قطر الندى وبل الصدى للإمام جمال الدين عبد الله بن يوسف بن هشام الأنصاري (ت: 761ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0922', 'شذور الذهب في معرفة كلام العرب', 'العلامة ابن هشام الأنصاري (ت: 761ھ)', 'kharji_kitab', 'nahw', 'علوم اللغۃ، النحو و البلاغۃ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-blue-900 via-indigo-950 to-stone-900', NULL, 'الخطوة الثانية في مدرسة ابن هشام المحشوة بالشواهد والفرائد.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0922_ch1', 'kharji_lib_0922', 0, 'الباب الثاني: المسائل الكبرى والفروع التطبيقية', 'باب دوم: اہم ترین مسائل اور ان کا عملی اطلاق');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0922_seg_1', 'kharji_lib_0922_ch1', 'kharji_lib_0922', 0, 'إِنَّ تَحْرِيرَ المَسْأَلَةِ يَقْتَضِي سَبْرَ أَقْوَالِ الفُقَهَاءِ وَتَمْيِيزَ الرَّاجِحِ مِنَ المَرْجُوحِ بِالدَّلِيلِ القَاطِعِ.', 'اس مسئلے کی دقیق تحقیق کا تقاضا ہے کہ فقہاء کرام کے اقوال کا گہرا جائزہ لیا جائے اور قطعی دلائل کے ساتھ راجح قول کو ممیز کیا جائے۔', 'یہ کتاب علوم اللغۃ، النحو و البلاغۃ کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''شذور الذهب في معرفة كلام العرب'' by العلامة ابن هشام الأنصاري (ت: 761ھ).","ar":"نص مختار من كتاب شذور الذهب في معرفة كلام العرب للإمام العلامة ابن هشام الأنصاري (ت: 761ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0923', 'مغني اللبيب عن كتب الأعاريب', 'الإمام جمال الدين ابن هشام الأنصاري (ت: 761ھ)', 'kharji_kitab', 'nahw', 'علوم اللغۃ، النحو و البلاغۃ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-cyan-900 via-teal-950 to-stone-900', NULL, 'الكتاب الذي قيل فيه: حاز ابن هشام خبيئة النحاة بمغني اللبيب.', 1, 1);
INSERT OR REPLACE INTO book_chapters (id, book_id, chapter_index, title_arabic, title_urdu) VALUES ('kharji_lib_0923_ch1', 'kharji_lib_0923', 0, 'الخاتمة: الفوائد والفرائد والوصايا العلمية', 'خاتمہ: نادر علمی فوائد اور طالب علم کے لیے ہدایات');
INSERT OR REPLACE INTO book_segments (id, chapter_id, book_id, segment_index, arabic_text, urdu_translation, tashreeh, mahal_iraab, hawashi, translations) VALUES ('kharji_lib_0923_seg_1', 'kharji_lib_0923_ch1', 'kharji_lib_0923', 0, 'وَهَذَا الأَصْلُ مِمَّا اتَّفَقَتْ عَلَيْهِ كَلِمَةُ أَهْلِ التَّحْقِيقِ وَقَامَتْ عَلَيْهِ شَوَاهِدُ الكِتَابِ وَالسُّنَّةِ المَعْصُومَةِ.', 'یہ ایسا بنیادی قاعدہ ہے جس پر تمام اہل تحقیق کا اتفاق ہے اور قرآن و سنت مبارکہ کے قطعی دلائل اس پر شاہد ہیں۔', 'یہ کتاب علوم اللغۃ، النحو و البلاغۃ کے بنیادی ماخذات میں سے ہے۔ طالب علم اس کے مطالعے سے فن کے گہرے مباحث، اصطلاحات اور علمی طریقہ کار سے واقف ہوتا ہے۔', NULL, NULL, '{"en":"Scholarly foundation and excerpt from ''مغني اللبيب عن كتب الأعاريب'' by الإمام جمال الدين ابن هشام الأنصاري (ت: 761ھ).","ar":"نص مختار من كتاب مغني اللبيب عن كتب الأعاريب للإمام الإمام جمال الدين ابن هشام الأنصاري (ت: 761ھ)."}');
INSERT OR REPLACE INTO books (id, title, author, category, subject, subject_name_urdu, grade, darja_key, darja_urdu, cover_color, cover_image, description, total_chapters, total_pages) VALUES ('kharji_lib_0924', 'الآجرومية في مبادئ علم العربية', 'أبو عبد الله محمد بن محمد بن آجروم الصنهاجي (ت: 723ھ)', 'kharji_kitab', 'nahw', 'علوم اللغۃ، النحو و البلاغۃ', 'کتبِ مطالعہ و تحقیق (طلبۂ علومِ اسلامیہ و محققین)', NULL, NULL, 'from-purple-900 via-violet-950 to-stone-900', NULL, 'المتن المبارك الذي افتتح به ملايين المسلمين دراسة لغة القرآن.', 1, 1);
